COMMENT ON FUNCTION vortex_access.current_organization_access_version(p_tenant_id uuid, p_organization_id uuid) IS 'Returns only the current version for one exact active tenant and organisation.';


--
-- Name: deactivate_organization_role_activation_for_administration(uuid, bigint, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.deactivate_organization_role_activation_for_administration(
  p_role_activation_id uuid, p_expected_activation_revision bigint, p_activity_id uuid
)
returns table (outcome text, organization_id uuid, activation_summary jsonb, access_version bigint)
language plpgsql volatile security definer set search_path = '' as $function$
declare
  context_value jsonb; context_organization_id uuid; context_account_id uuid;
  context_access_version bigint; context_correlation_id uuid;
  locked_access_version bigint; activation_fact vortex_access.organization_role_activations%rowtype;
  affected_permissions jsonb; decision record; changed record; summary jsonb;
  activity_result text;
begin
  if p_role_activation_id is null or p_role_activation_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_activation_revision is null or p_expected_activation_revision not between 1 and 9007199254740991
    or p_activity_id is null or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023', message = 'Role activation deactivation input is invalid';
  end if;
  context_value := vortex_access.validated_human_request_context();
  context_organization_id := (context_value ->> 'organizationId')::uuid;
  context_account_id := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version := (context_value ->> 'accessVersion')::bigint;
  context_correlation_id := (context_value ->> 'correlationId')::uuid;
  select version.current_version into locked_access_version
  from vortex_access.organization_access_versions as version
  join vortex_identity.organizations as organization on organization.organization_id = version.organization_id
  join vortex_identity.tenants as tenant on tenant.tenant_id = organization.tenant_id
  where version.organization_id = context_organization_id
    and organization.state = 'active' and tenant.state = 'active' for update of version;
  if not found or locked_access_version is distinct from context_access_version then
    raise exception using errcode = '42501', message = 'Role activation deactivation is unavailable';
  end if;
  select activation.* into activation_fact
  from vortex_access.organization_role_activations as activation
  where activation.organization_id = context_organization_id
    and activation.role_activation_id = p_role_activation_id for update;
  if not found or activation_fact.revision <> p_expected_activation_revision
    or activation_fact.state <> 'live' then
    raise exception using errcode = '40001', message = 'Role activation deactivation is stale or unavailable';
  end if;
  if activation_fact.organization_account_id <> context_account_id then
    select pg_catalog.jsonb_agg(reference.permission order by reference.application_root_id nulls first,
      reference.owner_kind, reference.owner_id, reference.permission_id) into affected_permissions
    from (select permission.application_root_id, permission.owner_kind, permission.owner_id,
      permission.permission_id, pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'applicationRootId', permission.application_root_id, 'ownerKind', permission.owner_kind,
        'ownerId', permission.owner_id, 'permissionId', permission.permission_id)) as permission
      from vortex_access.organization_role_permission_entries as permission
      where permission.organization_id = context_organization_id
        and permission.role_id = activation_fact.role_id
        and permission.role_revision = activation_fact.historical_role_revision) as reference;
    if affected_permissions is null then
      raise exception using errcode = '40001', message = 'Role activation historical scope is unavailable';
    end if;
    select evaluated.* into strict decision from vortex_access.evaluate_organization_permission_eligibility(
      pg_catalog.jsonb_build_object('operationKey', 'platform.organization.role_activations.revoke',
        'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
        'target', pg_catalog.jsonb_build_object('kind', 'organization'),
        'requiredPermission', pg_catalog.jsonb_build_object('ownerKind', 'platform',
          'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
          'permissionId', '156d01f3-8f80-45fb-8fc8-b31c47dbb1df'),
        'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
        'authority', pg_catalog.jsonb_build_object('kind', 'delegated_management',
          'before', pg_catalog.jsonb_build_object('kind', 'bounded', 'permissions', affected_permissions),
          'after', pg_catalog.jsonb_build_object('kind', 'none')))) as evaluated;
    if decision.outcome = 'refused'
    and decision.operation_key = 'platform.organization.role_activations.revoke'
    and decision.target_kind = 'organization'
    and decision.target_application_root_id is null
    and decision.organization_id = context_organization_id
    and decision.organization_account_id = context_account_id
    and decision.access_version = context_access_version
    and decision.correlation_id = context_correlation_id
    and decision.reason_code in (
      'permission_unavailable', 'permission_not_effective',
      'authentication_unsatisfied', 'delegation_insufficient'
    ) then
    activity_result := vortex_activity.append_organization_activity_entry(
      context_organization_id, p_activity_id, decision.checked_at,
      'organization_account', context_account_id, 'revoke_role_activation',
      array[context_organization_id]::uuid[], array[]::uuid[], vortex_context.channel(),
      context_correlation_id, 'refused'
    );
    if activity_result is distinct from 'inserted' then
      raise exception using errcode = '40001',
        message = 'Role activation deactivation refusal Activity is stale';
    end if;
    return query select 'refused'::text, context_organization_id,
      null::jsonb, context_access_version;
    return;
  end if;

  if decision.outcome is distinct from 'eligible'
    or decision.operation_key is distinct from 'platform.organization.role_activations.revoke'
    or decision.target_kind is distinct from 'organization'
    or decision.target_application_root_id is not null
    or decision.organization_id is distinct from context_organization_id
    or decision.organization_account_id is distinct from context_account_id
    or decision.access_version is distinct from context_access_version
    or decision.correlation_id is distinct from context_correlation_id then
    raise exception using errcode = '42501',
      message = 'Role activation deactivation is unavailable';
  end if;
  end if;
  select result.* into strict changed from vortex_access.coordinate_organization_role_activation_change(
    'revoke_role_activation', context_organization_id, p_role_activation_id,
    p_expected_activation_revision, null, null, null, null, null, null, null,
    null, null, context_account_id, context_correlation_id) as result;
  summary := vortex_access.project_organization_role_activation_summary(context_organization_id, p_role_activation_id);
  if summary is null then raise exception using errcode = '40001', message = 'Changed activation projection is unavailable'; end if;
  activity_result := vortex_activity.append_organization_activity_entry(context_organization_id,
    p_activity_id, (changed.activation ->> 'changedAt')::timestamptz, 'organization_account',
    context_account_id, 'revoke_role_activation', array[p_role_activation_id]::uuid[],
    array[]::uuid[], vortex_context.channel(), context_correlation_id, 'completed');
  if activity_result is distinct from 'inserted' then raise exception using errcode = '40001', message = 'Role activation Activity is stale'; end if;
  return query select 'completed'::text, context_organization_id, summary, changed.access_version;
end $function$;


ALTER FUNCTION vortex_access.deactivate_organization_role_activation_for_administration(p_role_activation_id uuid, p_expected_activation_revision bigint, p_activity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION deactivate_organization_role_activation_for_administration(p_role_activation_id uuid, p_expected_activation_revision bigint, p_activity_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.deactivate_organization_role_activation_for_administration(p_role_activation_id uuid, p_expected_activation_revision bigint, p_activity_id uuid) IS 'Standalone request entry: performs revoke_role_activation after fixed protected checks, records one atomic completed Activity or returns one content-free refused Activity row; no SQL function composes this result.';


--
-- Name: derive_usage_projection(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.derive_usage_projection(p_tenant_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS TABLE(rollup_scope text, scope_id uuid, organization_id uuid, bucket_start timestamp with time zone, capability_key text, unit text, quantity numeric, accepted_event_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with accepted as (
    select original.organization_id,
      (pg_catalog.date_trunc('day', original.occurred_at at time zone 'UTC') at time zone 'UTC') as bucket_start,
      original.capability_key, original.unit,
      original.quantity + coalesce(pg_catalog.sum(case correction.correction_direction
        when 'increase' then correction.quantity else -correction.quantity end), 0) as net_quantity,
      1 + pg_catalog.count(correction.metering_event_id) as accepted_event_count
    from vortex_access.metering_events as original
    left join vortex_access.metering_events as correction
      on correction.tenant_id = original.tenant_id
      and correction.corrects_metering_event_id = original.metering_event_id
    where original.tenant_id = p_tenant_id and original.corrects_metering_event_id is null
      and original.occurred_at >= p_period_start and original.occurred_at < p_period_end
    group by original.metering_event_id
  ), scoped as (
    select 'tenant'::text as rollup_scope,
      '00000000-0000-0000-0000-000000000000'::uuid as scope_id, null::uuid as organization_id,
      bucket_start, capability_key, unit, net_quantity, accepted_event_count
    from accepted
    union all
    select 'organization'::text, organization_id, organization_id,
      bucket_start, capability_key, unit, net_quantity, accepted_event_count
    from accepted where organization_id is not null
  )
  select rollup_scope, scope_id, organization_id, bucket_start, capability_key, unit,
    pg_catalog.sum(net_quantity), pg_catalog.sum(accepted_event_count)::bigint
  from scoped
  group by rollup_scope, scope_id, organization_id, bucket_start, capability_key, unit;
$$;


ALTER FUNCTION vortex_access.derive_usage_projection(p_tenant_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: evaluate_current_record_ownership_visibility(jsonb, text, uuid, uuid, uuid, uuid, uuid, text, jsonb, uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.evaluate_current_record_ownership_visibility(p_permission_record_scope jsonb, p_ownership_mode text, p_binding_organization_id uuid, p_binding_application_root_id uuid, p_binding_module_root_id uuid, p_binding_record_type_id uuid, p_binding_storage_contract_id uuid, p_binding_storage_scope text, p_record_scope jsonb, p_owner_organization_account_id uuid, p_owner_group_id uuid, p_current_organization_id uuid, p_current_application_root_id uuid, p_current_organization_account_id uuid, p_checked_at timestamp with time zone) RETURNS TABLE(admitted boolean, valid_until timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  nil_id constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  scope_key_count integer;
  has_all_records boolean;
  has_ownership boolean;
  record_storage_scope text;
  record_organization_id uuid;
  record_application_root_id uuid;
  record_module_root_id uuid;
  record_type_id uuid;
  record_storage_contract_id uuid;
  record_id uuid;
  membership_deadline timestamptz;
begin
  has_all_records := exists (
    select 1
    from pg_catalog.jsonb_array_elements(
      p_permission_record_scope -> 'routes'
    ) as route(value)
    where route.value ->> 'kind' = 'all_records'
  );
  has_ownership := exists (
    select 1
    from pg_catalog.jsonb_array_elements(
      p_permission_record_scope -> 'routes'
    ) as route(value)
    where route.value ->> 'kind' = 'ownership'
  );

  if p_binding_organization_id is null or p_binding_organization_id = nil_id
    or p_binding_application_root_id is null
    or p_binding_application_root_id = nil_id
    or p_binding_module_root_id is null or p_binding_module_root_id = nil_id
    or p_binding_record_type_id is null or p_binding_record_type_id = nil_id
    or p_binding_storage_contract_id is null
    or p_binding_storage_contract_id = nil_id
    or p_current_organization_id is null or p_current_organization_id = nil_id
    or p_current_application_root_id is null
    or p_current_application_root_id = nil_id
    or p_current_organization_account_id is null
    or p_current_organization_account_id = nil_id
    or p_checked_at is null
    or p_checked_at in ('-infinity'::timestamptz, 'infinity'::timestamptz)
    or p_binding_storage_scope is null
    or p_binding_storage_scope not in ('organization_shared', 'application_contained')
    or p_ownership_mode is null
    or p_ownership_mode not in ('none', 'organization_account', 'group', 'inherited') then
    raise exception using errcode = '22023',
      message = 'Record visibility context is invalid';
  end if;

  if (p_ownership_mode in ('none', 'inherited')
      and (p_owner_organization_account_id is not null or p_owner_group_id is not null))
    or (p_ownership_mode = 'organization_account'
      and (p_owner_organization_account_id is null
        or p_owner_organization_account_id = nil_id
        or p_owner_group_id is not null))
    or (p_ownership_mode = 'group'
      and (p_owner_group_id is null or p_owner_group_id = nil_id
        or p_owner_organization_account_id is not null)) then
    raise exception using errcode = '22023',
      message = 'Record ownership evidence is invalid';
  end if;

  if p_record_scope is null
    or pg_catalog.jsonb_typeof(p_record_scope) is distinct from 'object' then
    raise exception using errcode = '22023',
      message = 'Record identity is invalid';
  end if;
  record_storage_scope := p_record_scope ->> 'storageScope';
  select pg_catalog.count(*) into scope_key_count
  from pg_catalog.jsonb_object_keys(p_record_scope) as record_key;
  if record_storage_scope = 'organization_shared' then
    if scope_key_count <> 6 or p_record_scope ? 'applicationRootId' then
      raise exception using errcode = '22023', message = 'Record identity is invalid';
    end if;
  elsif record_storage_scope = 'application_contained' then
    if scope_key_count <> 7 or not (p_record_scope ? 'applicationRootId') then
      raise exception using errcode = '22023', message = 'Record identity is invalid';
    end if;
  else
    raise exception using errcode = '22023', message = 'Record identity is invalid';
  end if;

  if not (p_record_scope ?& array[
    'organizationId', 'moduleRootId', 'recordTypeId',
    'storageContractId', 'recordId'
  ]) then
    raise exception using errcode = '22023', message = 'Record identity is invalid';
  end if;
  if not vortex_context.is_non_nil_uuid(p_record_scope ->> 'organizationId')
    or not vortex_context.is_non_nil_uuid(p_record_scope ->> 'moduleRootId')
    or not vortex_context.is_non_nil_uuid(p_record_scope ->> 'recordTypeId')
    or not vortex_context.is_non_nil_uuid(p_record_scope ->> 'storageContractId')
    or not vortex_context.is_non_nil_uuid(p_record_scope ->> 'recordId')
    or (record_storage_scope = 'application_contained'
      and not vortex_context.is_non_nil_uuid(
        p_record_scope ->> 'applicationRootId'
      )) then
    raise exception using errcode = '22023', message = 'Record identity is invalid';
  end if;
  begin
    record_organization_id := (p_record_scope ->> 'organizationId')::uuid;
    record_module_root_id := (p_record_scope ->> 'moduleRootId')::uuid;
    record_type_id := (p_record_scope ->> 'recordTypeId')::uuid;
    record_storage_contract_id := (p_record_scope ->> 'storageContractId')::uuid;
    record_id := (p_record_scope ->> 'recordId')::uuid;
    if record_storage_scope = 'application_contained' then
      record_application_root_id := (p_record_scope ->> 'applicationRootId')::uuid;
    end if;
  exception
    when invalid_text_representation then
      raise exception using errcode = '22023', message = 'Record identity is invalid';
  end;
  if record_organization_id is null or record_organization_id = nil_id
    or record_module_root_id is null or record_module_root_id = nil_id
    or record_type_id is null or record_type_id = nil_id
    or record_storage_contract_id is null or record_storage_contract_id = nil_id
    or record_id is null or record_id = nil_id
    or (record_storage_scope = 'application_contained'
      and (record_application_root_id is null or record_application_root_id = nil_id)) then
    raise exception using errcode = '22023', message = 'Record identity is invalid';
  end if;

  if p_binding_organization_id <> p_current_organization_id
    or p_binding_application_root_id <> p_current_application_root_id
    or record_organization_id <> p_current_organization_id
    or record_module_root_id <> p_binding_module_root_id
    or record_type_id <> p_binding_record_type_id
    or record_storage_contract_id <> p_binding_storage_contract_id
    or record_storage_scope <> p_binding_storage_scope
    or (record_storage_scope = 'application_contained'
      and record_application_root_id <> p_current_application_root_id) then
    return query select false, null::timestamptz;
    return;
  end if;

  if has_all_records then
    return query select true, null::timestamptz;
    return;
  end if;

  if has_ownership and p_ownership_mode = 'organization_account'
    and p_owner_organization_account_id = p_current_organization_account_id then
    return query select true, null::timestamptz;
    return;
  end if;

  if has_ownership and p_ownership_mode = 'group' then
    select membership.expires_at into membership_deadline
    from vortex_access.organization_group_memberships as membership
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = membership.organization_id
      and organization_group.group_id = membership.group_id
      and organization_group.state = 'active'
    where membership.organization_id = p_current_organization_id
      and membership.group_id = p_owner_group_id
      and membership.organization_account_id = p_current_organization_account_id
      and membership.state = 'live'
      and membership.starts_at <= p_checked_at
      and (membership.expires_at is null or membership.expires_at > p_checked_at);
    if found then
      return query select true, membership_deadline;
      return;
    end if;
  end if;

  return query select false, null::timestamptz;
end
$$;


ALTER FUNCTION vortex_access.evaluate_current_record_ownership_visibility(p_permission_record_scope jsonb, p_ownership_mode text, p_binding_organization_id uuid, p_binding_application_root_id uuid, p_binding_module_root_id uuid, p_binding_record_type_id uuid, p_binding_storage_contract_id uuid, p_binding_storage_scope text, p_record_scope jsonb, p_owner_organization_account_id uuid, p_owner_group_id uuid, p_current_organization_id uuid, p_current_application_root_id uuid, p_current_organization_account_id uuid, p_checked_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_current_record_ownership_visibility(p_permission_record_scope jsonb, p_ownership_mode text, p_binding_organization_id uuid, p_binding_application_root_id uuid, p_binding_module_root_id uuid, p_binding_record_type_id uuid, p_binding_storage_contract_id uuid, p_binding_storage_scope text, p_record_scope jsonb, p_owner_organization_account_id uuid, p_owner_group_id uuid, p_current_organization_id uuid, p_current_application_root_id uuid, p_current_organization_account_id uuid, p_checked_at timestamp with time zone); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_current_record_ownership_visibility(p_permission_record_scope jsonb, p_ownership_mode text, p_binding_organization_id uuid, p_binding_application_root_id uuid, p_binding_module_root_id uuid, p_binding_record_type_id uuid, p_binding_storage_contract_id uuid, p_binding_storage_scope text, p_record_scope jsonb, p_owner_organization_account_id uuid, p_owner_group_id uuid, p_current_organization_id uuid, p_current_application_root_id uuid, p_current_organization_account_id uuid, p_checked_at timestamp with time zone) IS 'Evaluates all-record and direct account/current-Group ownership routes over one trusted current record projection; unsupported valid routes add no authority.';


--
-- Name: evaluate_organization_permission_eligibility(jsonb); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.evaluate_organization_permission_eligibility(
  p_declaration jsonb
)
returns table (
  outcome text,
  operation_key text,
  target_kind text,
  target_application_root_id uuid,
  organization_id uuid,
  organization_account_id uuid,
  access_version bigint,
  checked_at timestamptz,
  valid_until timestamptz,
  correlation_id uuid,
  reason_code text
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  declaration_action jsonb;
  declaration_target jsonb;
  declaration_permission jsonb;
  declaration_authentication jsonb;
  declaration_authority jsonb;
  scope_candidate jsonb;
  permission_candidate jsonb;
  scope_name text;
  operation_value text;
  target_kind_value text;
  target_application_value uuid;
  permission_application_value uuid;
  permission_owner_kind_value text;
  authority_kind_value text;
  context_value jsonb;
  context_organization_value uuid;
  context_account_value uuid;
  context_access_version_value bigint;
  context_application_value uuid;
  context_expires_value timestamptz;
  context_correlation_value uuid;
  authentication_deadline timestamptz;
  authentication_satisfied boolean := true;
  context_current boolean := true;
  target_context_satisfied boolean := true;
  unsupported_context boolean := false;
  decision_checked_at timestamptz;
begin
  if p_declaration is null
    or pg_catalog.jsonb_typeof(p_declaration) <> 'object'
    or not p_declaration ?& array[
      'operationKey', 'action', 'target', 'requiredPermission',
      'recentAuthentication', 'authority'
    ]
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(p_declaration) as supplied(key)
      where supplied.key <> all (array[
        'operationKey', 'action', 'target', 'requiredPermission',
        'recentAuthentication', 'authority'
      ])
    )
    or pg_catalog.jsonb_typeof(p_declaration -> 'operationKey') <> 'string'
    or pg_catalog.char_length(p_declaration ->> 'operationKey') not between 3 and 120
    or (p_declaration ->> 'operationKey') !~
      '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)+$'
    or (p_declaration ->> 'operationKey') ~ '(^|\.)[^.]{41,}(\.|$)' then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  declaration_action := p_declaration -> 'action';
  declaration_target := p_declaration -> 'target';
  declaration_permission := p_declaration -> 'requiredPermission';
  declaration_authentication := p_declaration -> 'recentAuthentication';
  declaration_authority := p_declaration -> 'authority';

  if pg_catalog.jsonb_typeof(declaration_action) <> 'object'
    or not declaration_action ? 'actionKind'
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(declaration_action) as supplied(key)
      where supplied.key <> all (array['actionKind', 'namedAction'])
    )
    or pg_catalog.jsonb_typeof(declaration_action -> 'actionKind') <> 'string'
    or declaration_action ->> 'actionKind' not in (
      'create', 'read', 'update', 'delete', 'restore', 'export', 'share', 'manage', 'named'
    )
    or (
      (declaration_action ->> 'actionKind') = 'named'
      and (
        not declaration_action ? 'namedAction'
        or pg_catalog.jsonb_typeof(declaration_action -> 'namedAction') <> 'string'
        or pg_catalog.char_length(declaration_action ->> 'namedAction') not between 1 and 40
        or (declaration_action ->> 'namedAction') !~
          '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
      )
    )
    or (
      (declaration_action ->> 'actionKind') <> 'named'
      and declaration_action ? 'namedAction'
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_target) <> 'object'
    or not declaration_target ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_target -> 'kind') <> 'string'
    or declaration_target ->> 'kind' not in ('organization', 'application')
    or (
      declaration_target ->> 'kind' = 'organization'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_target) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_target ->> 'kind' = 'application'
      and (
        not declaration_target ? 'applicationRootId'
        or not vortex_context.is_non_nil_uuid(
          declaration_target ->> 'applicationRootId'
        )
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_target) as supplied(key)
          where supplied.key <> all (array['kind', 'applicationRootId'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_authentication) <> 'object'
    or not declaration_authentication ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_authentication -> 'kind') <> 'string'
    or declaration_authentication ->> 'kind' not in ('none', 'primary', 'multi_factor')
    or (
      declaration_authentication ->> 'kind' = 'none'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_authentication) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_authentication ->> 'kind' in ('primary', 'multi_factor')
      and (
        not declaration_authentication ? 'maximumAgeSeconds'
        or pg_catalog.jsonb_typeof(
          declaration_authentication -> 'maximumAgeSeconds'
        ) <> 'number'
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_authentication) as supplied(key)
          where supplied.key <> all (array['kind', 'maximumAgeSeconds'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if declaration_authentication ->> 'kind' in ('primary', 'multi_factor')
    and (
      (declaration_authentication ->> 'maximumAgeSeconds')::numeric < 1
      or (declaration_authentication ->> 'maximumAgeSeconds')::numeric >
        9007199254740991
      or (declaration_authentication ->> 'maximumAgeSeconds')::numeric <>
        pg_catalog.trunc(
          (declaration_authentication ->> 'maximumAgeSeconds')::numeric
        )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_authority) <> 'object'
    or not declaration_authority ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_authority -> 'kind') <> 'string'
    or declaration_authority ->> 'kind' not in ('permission', 'delegated_management')
    or (
      declaration_authority ->> 'kind' = 'permission'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_authority) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_authority ->> 'kind' = 'delegated_management'
      and (
        not declaration_authority ?& array['before', 'after']
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_authority) as supplied(key)
          where supplied.key <> all (array['kind', 'before', 'after'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if declaration_authority ->> 'kind' = 'delegated_management' then
    foreach scope_name in array array['before', 'after'] loop
      scope_candidate := declaration_authority -> scope_name;
      if pg_catalog.jsonb_typeof(scope_candidate) <> 'object'
        or not scope_candidate ? 'kind'
        or pg_catalog.jsonb_typeof(scope_candidate -> 'kind') <> 'string'
        or scope_candidate ->> 'kind' not in (
          'none', 'organization_catalogue', 'bounded'
        )
        or (
          scope_candidate ->> 'kind' in ('none', 'organization_catalogue')
          and exists (
            select 1
            from pg_catalog.jsonb_object_keys(scope_candidate) as supplied(key)
            where supplied.key <> 'kind'
          )
        )
        or (
          scope_candidate ->> 'kind' = 'bounded'
          and (
            not scope_candidate ? 'permissions'
            or pg_catalog.jsonb_typeof(scope_candidate -> 'permissions') <> 'array'
            or pg_catalog.jsonb_array_length(scope_candidate -> 'permissions') = 0
            or exists (
              select 1
              from pg_catalog.jsonb_object_keys(scope_candidate) as supplied(key)
              where supplied.key <> all (array['kind', 'permissions'])
            )
          )
        ) then
        raise exception using errcode = '22023',
          message = 'Organization permission declaration is invalid';
      end if;
    end loop;

    if declaration_authority -> 'before' ->> 'kind' = 'none'
      and declaration_authority -> 'after' ->> 'kind' = 'none' then
      raise exception using errcode = '22023',
        message = 'Organization permission declaration is invalid';
    end if;
  end if;

  for permission_candidate in
    select candidate.value
    from (
      select declaration_permission as value
      union all
      select scoped.value
      from pg_catalog.jsonb_array_elements(
        case
          when declaration_authority ->> 'kind' = 'delegated_management'
            and declaration_authority -> 'before' ->> 'kind' = 'bounded'
          then declaration_authority -> 'before' -> 'permissions'
          else '[]'::jsonb
        end
      ) as scoped(value)
      union all
      select scoped.value
      from pg_catalog.jsonb_array_elements(
        case
          when declaration_authority ->> 'kind' = 'delegated_management'
            and declaration_authority -> 'after' ->> 'kind' = 'bounded'
          then declaration_authority -> 'after' -> 'permissions'
          else '[]'::jsonb
        end
      ) as scoped(value)
    ) as candidate
  loop
    if pg_catalog.jsonb_typeof(permission_candidate) <> 'object'
      or not permission_candidate ?& array['ownerKind', 'ownerId', 'permissionId']
      or pg_catalog.jsonb_typeof(permission_candidate -> 'ownerKind') <> 'string'
      or permission_candidate ->> 'ownerKind' not in ('platform', 'application', 'module')
      or not vortex_context.is_non_nil_uuid(permission_candidate ->> 'ownerId')
      or not vortex_context.is_non_nil_uuid(permission_candidate ->> 'permissionId')
      or exists (
        select 1
        from pg_catalog.jsonb_object_keys(permission_candidate) as supplied(key)
        where supplied.key <> all (array[
          'applicationRootId', 'ownerKind', 'ownerId', 'permissionId'
        ])
      )
      or (
        permission_candidate ->> 'ownerKind' = 'platform'
        and permission_candidate ? 'applicationRootId'
      )
      or (
        permission_candidate ->> 'ownerKind' in ('application', 'module')
        and (
          not permission_candidate ? 'applicationRootId'
          or not vortex_context.is_non_nil_uuid(
            permission_candidate ->> 'applicationRootId'
          )
        )
      )
      or (
        permission_candidate ->> 'ownerKind' = 'application'
        and pg_catalog.lower(permission_candidate ->> 'ownerId') <>
          pg_catalog.lower(permission_candidate ->> 'applicationRootId')
      ) then
      raise exception using errcode = '22023',
        message = 'Organization permission declaration is invalid';
    end if;
  end loop;

  if declaration_authority ->> 'kind' = 'delegated_management' then
    foreach scope_name in array array['before', 'after'] loop
      scope_candidate := declaration_authority -> scope_name;
      if scope_candidate ->> 'kind' = 'bounded'
        and (
          select pg_catalog.count(*)
          from pg_catalog.jsonb_array_elements(scope_candidate -> 'permissions')
        ) <> (
          select pg_catalog.count(distinct pg_catalog.concat_ws(
            ':',
            pg_catalog.lower(permission.value ->> 'applicationRootId'),
            permission.value ->> 'ownerKind',
            pg_catalog.lower(permission.value ->> 'ownerId'),
            pg_catalog.lower(permission.value ->> 'permissionId')
          ))
          from pg_catalog.jsonb_array_elements(
            scope_candidate -> 'permissions'
          ) as permission(value)
        ) then
        raise exception using errcode = '22023',
          message = 'Organization permission declaration is invalid';
      end if;
    end loop;
  end if;

  operation_value := p_declaration ->> 'operationKey';
  target_kind_value := declaration_target ->> 'kind';
  target_application_value := case
    when target_kind_value = 'application'
      then (declaration_target ->> 'applicationRootId')::uuid
    else null
  end;
  permission_application_value := case
    when declaration_permission ? 'applicationRootId'
      then (declaration_permission ->> 'applicationRootId')::uuid
    else null
  end;
  permission_owner_kind_value := declaration_permission ->> 'ownerKind';
  authority_kind_value := declaration_authority ->> 'kind';

  if (target_kind_value = 'organization' and permission_owner_kind_value <> 'platform')
    or (
      target_kind_value = 'application'
      and (
        permission_owner_kind_value = 'platform'
        or permission_application_value is distinct from target_application_value
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  context_organization_value := (context_value ->> 'organizationId')::uuid;
  context_account_value := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version_value := (context_value ->> 'accessVersion')::bigint;
  context_application_value := case
    when context_value ? 'applicationRootId'
      then (context_value ->> 'applicationRootId')::uuid
    else null
  end;
  context_expires_value := (context_value ->> 'expiresAt')::timestamptz;
  context_correlation_value := (context_value ->> 'correlationId')::uuid;
  decision_checked_at := pg_catalog.clock_timestamp();
  context_current := context_expires_value > decision_checked_at;

  unsupported_context := context_value ? 'delegatedContext'
    or context_value ? 'supportContext';
  target_context_satisfied := target_kind_value = 'organization'
    or coalesce(context_application_value = target_application_value, false);

  authentication_deadline := vortex_access.recent_authentication_deadline_internal(
    context_value, decision_checked_at, declaration_authentication
  );
  authentication_satisfied := authentication_deadline is not null;

  return query
  with permission_eligibility as materialized (
    select evaluated.path_valid_until
    from vortex_access.evaluate_permission_role_path_internal(
      context_value, decision_checked_at, declaration_permission,
      declaration_action, null::uuid
    ) as evaluated
  ), management_scopes as materialized (
    select declaration_authority -> 'before' as scope
    where authority_kind_value = 'delegated_management'
    union all
    select declaration_authority -> 'after'
    where authority_kind_value = 'delegated_management'
  ), delegation_requirements as materialized (
    select 'organization_catalogue'::text as requirement_kind,
      null::uuid as application_root_id, null::text as owner_kind,
      null::uuid as owner_id, null::uuid as permission_id
    where exists (
      select 1 from management_scopes as managed
      where managed.scope ->> 'kind' = 'organization_catalogue'
    )
    union all
    select distinct 'bounded',
      case when permission.value ? 'applicationRootId'
        then (permission.value ->> 'applicationRootId')::uuid
        else null::uuid
      end,
      permission.value ->> 'ownerKind',
      (permission.value ->> 'ownerId')::uuid,
      (permission.value ->> 'permissionId')::uuid
    from management_scopes as managed
    cross join lateral pg_catalog.jsonb_array_elements(
      case when managed.scope ->> 'kind' = 'bounded'
        then managed.scope -> 'permissions'
        else '[]'::jsonb
      end
    ) as permission(value)
  ), current_delegation_paths as materialized (
    select 1 as route_rank, delegation.delegation_authority_id,
      null::uuid as membership_id, delegation.scope_kind,
      delegation.bounded_permissions,
      least(
        context_expires_value,
        coalesce(delegation.expires_at, context_expires_value)
      ) as path_valid_until
    from vortex_access.organization_delegation_authorities as delegation
    where delegation.organization_id = context_organization_value
      and delegation.holder_kind = 'organization_account'
      and delegation.organization_account_id = context_account_value
      and delegation.state = 'live'
      and delegation.starts_at <= decision_checked_at
      and (
        delegation.expires_at is null
        or delegation.expires_at > decision_checked_at
      )

    union all

    select 2, delegation.delegation_authority_id,
      membership.membership_id, delegation.scope_kind,
      delegation.bounded_permissions,
      least(
        context_expires_value,
        coalesce(delegation.expires_at, context_expires_value),
        coalesce(membership.expires_at, context_expires_value)
      )
    from vortex_access.organization_delegation_authorities as delegation
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = delegation.organization_id
      and organization_group.group_id = delegation.group_id
      and organization_group.state = 'active'
    join vortex_access.organization_group_memberships as membership
      on membership.organization_id = delegation.organization_id
      and membership.group_id = delegation.group_id
      and membership.organization_account_id = context_account_value
      and membership.state = 'live'
      and membership.starts_at <= decision_checked_at
      and (
        membership.expires_at is null
        or membership.expires_at > decision_checked_at
      )
    where delegation.organization_id = context_organization_value
      and delegation.holder_kind = 'group'
      and delegation.state = 'live'
      and delegation.starts_at <= decision_checked_at
      and (
        delegation.expires_at is null
        or delegation.expires_at > decision_checked_at
      )
  ), current_bounded_path_permissions as materialized (
    select path.delegation_authority_id, path.membership_id,
      case when stored.value ? 'applicationRootId'
        then (stored.value ->> 'applicationRootId')::uuid
        else null::uuid
      end as application_root_id,
      stored.value ->> 'ownerKind' as owner_kind,
      (stored.value ->> 'ownerId')::uuid as owner_id,
      (stored.value ->> 'permissionId')::uuid as permission_id
    from current_delegation_paths as path
    cross join lateral pg_catalog.jsonb_array_elements(
      path.bounded_permissions
    ) as stored(value)
    join vortex_access.permission_registrations as registration
      on registration.organization_id = context_organization_value
      and registration.state = 'active'
    join vortex_access.permission_catalogue_entries as catalogue
      on catalogue.organization_id = registration.organization_id
      and catalogue.registration_kind = registration.registration_kind
      and catalogue.registration_owner_id is not distinct from
        registration.registration_owner_id
      and catalogue.registration_revision = registration.revision
      and catalogue.application_root_id is not distinct from case
        when stored.value ? 'applicationRootId'
          then (stored.value ->> 'applicationRootId')::uuid
        else null::uuid
      end
      and catalogue.owner_kind = stored.value ->> 'ownerKind'
      and catalogue.owner_id = (stored.value ->> 'ownerId')::uuid
      and catalogue.permission_id = (stored.value ->> 'permissionId')::uuid
      and catalogue.meaning_fingerprint =
        stored.value ->> 'meaningFingerprint'
    join vortex_access.permission_continuities as continuity
      on continuity.organization_id = catalogue.organization_id
      and continuity.application_root_id is not distinct from
        catalogue.application_root_id
      and continuity.owner_kind = catalogue.owner_kind
      and continuity.owner_id = catalogue.owner_id
      and continuity.permission_id = catalogue.permission_id
      and continuity.registration_kind = catalogue.registration_kind
      and continuity.registration_owner_id is not distinct from
        catalogue.registration_owner_id
      and continuity.last_processed_registration_revision = registration.revision
      and continuity.state = 'available'
      and continuity.continuity_revision =
        (stored.value ->> 'continuityRevision')::numeric::bigint
      and continuity.meaning_fingerprint =
        stored.value ->> 'meaningFingerprint'
    where path.scope_kind = 'bounded'
  ), delegation_path_candidates as (
    select requirement.requirement_kind, requirement.application_root_id,
      requirement.owner_kind, requirement.owner_id,
      requirement.permission_id, path.route_rank,
      path.delegation_authority_id, path.membership_id,
      path.path_valid_until,
      pg_catalog.row_number() over (
        partition by requirement.requirement_kind,
          requirement.application_root_id, requirement.owner_kind,
          requirement.owner_id, requirement.permission_id
        order by path.route_rank, path.delegation_authority_id,
          path.membership_id nulls first
      ) as path_ordinal
    from delegation_requirements as requirement
    join current_delegation_paths as path
      on path.scope_kind = 'organization_catalogue'
      or (
        requirement.requirement_kind = 'bounded'
        and exists (
          select 1
          from current_bounded_path_permissions as covered
          where covered.delegation_authority_id =
              path.delegation_authority_id
            and covered.membership_id is not distinct from path.membership_id
            and covered.application_root_id is not distinct from
              requirement.application_root_id
            and covered.owner_kind = requirement.owner_kind
            and covered.owner_id = requirement.owner_id
            and covered.permission_id = requirement.permission_id
        )
      )
    where requirement.requirement_kind <> 'organization_catalogue'
      or path.scope_kind = 'organization_catalogue'
  ), selected_delegation_paths as materialized (
    select candidate.requirement_kind, candidate.application_root_id,
      candidate.owner_kind, candidate.owner_id, candidate.permission_id,
      candidate.path_valid_until
    from delegation_path_candidates as candidate
    where candidate.path_ordinal = 1
  ), delegation_summary as (
    select pg_catalog.count(*) as requirement_count,
      pg_catalog.count(selected.requirement_kind) as selected_count,
      pg_catalog.min(selected.path_valid_until) as path_valid_until
    from delegation_requirements as requirement
    left join selected_delegation_paths as selected
      on selected.requirement_kind = requirement.requirement_kind
      and selected.application_root_id is not distinct from
        requirement.application_root_id
      and selected.owner_kind is not distinct from requirement.owner_kind
      and selected.owner_id is not distinct from requirement.owner_id
      and selected.permission_id is not distinct from requirement.permission_id
  ), decision as (
    select exists(select 1 from permission_eligibility) as permission_available,
      (
        select pg_catalog.min(selected.path_valid_until)
        from permission_eligibility as selected
      ) as path_valid_until,
      authority_kind_value = 'permission'
        or (
          delegation.requirement_count > 0
          and delegation.requirement_count = delegation.selected_count
        ) as delegation_satisfied,
      delegation.path_valid_until as delegation_valid_until
    from (select 1) as singleton
    cross join delegation_summary as delegation
  )
  select
    case
      when not context_current
        or unsupported_context or not target_context_satisfied then 'refused'
      when not decision.permission_available then 'refused'
      when decision.path_valid_until is null then 'refused'
      when not authentication_satisfied then 'refused'
      when not decision.delegation_satisfied then 'refused'
      else 'eligible'
    end,
    operation_value,
    target_kind_value,
    target_application_value,
    context_organization_value,
    context_account_value,
    context_access_version_value,
    decision_checked_at,
    case
      when context_current
        and not unsupported_context
        and target_context_satisfied
        and decision.permission_available
        and decision.path_valid_until is not null
        and authentication_satisfied
        and decision.delegation_satisfied
      then least(
        decision.path_valid_until,
        authentication_deadline,
        coalesce(decision.delegation_valid_until, context_expires_value)
      )
      else null
    end,
    context_correlation_value,
    case
      when not context_current
        or unsupported_context or not target_context_satisfied
        then 'target_policy_unavailable'
      when not decision.permission_available then 'permission_unavailable'
      when decision.path_valid_until is null then 'permission_not_effective'
      when not authentication_satisfied then 'authentication_unsatisfied'
      when not decision.delegation_satisfied then 'delegation_insufficient'
      else null
    end
  from decision;
end
$function$;


ALTER FUNCTION vortex_access.evaluate_organization_permission_eligibility(p_declaration jsonb) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION evaluate_organization_permission_eligibility(p_declaration jsonb); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.evaluate_organization_permission_eligibility(p_declaration jsonb) IS 'Returns transaction-bound permission and current delegation eligibility from one trusted operation declaration; it is not a final protected-operation decision.';


--
-- Name: evaluate_organization_record_access_internal(jsonb, uuid, jsonb); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.evaluate_organization_record_access_internal(
  p_declaration jsonb,
  p_target_record_id uuid,
  p_facts jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  declaration_binding jsonb := p_declaration -> 'recordBinding';
  facts_binding jsonb;
  record_type_item jsonb;
  field_item jsonb;
  relationship_item jsonb;
  condition_item jsonb;
  record_item jsonb;
  record_scope_item jsonb;
  edge_item jsonb;
  scope_key_count integer;
  seen_type_ids text[] := array[]::text[];
  seen_field_ids text[];
  seen_relationship_ids text[] := array[]::text[];
  seen_condition_ids text[] := array[]::text[];
  seen_record_ids text[] := array[]::text[];
  ctx jsonb;
  checked_at timestamptz;
  auth_deadline timestamptz;
  eligibility jsonb;
  decision_evidence jsonb;
  target_application_root_id uuid;
  target_record_row jsonb;
  target_ok boolean;
  matched jsonb;
  decision_valid_until text;
begin
  -- Facts shape: a closed object with exactly the declared top-level keys.
  if p_facts is null or pg_catalog.jsonb_typeof(p_facts) <> 'object'
    or not (p_facts ?& array['binding', 'recordTypes', 'relationships', 'sharingConditions', 'records', 'edges'])
    or exists (
      select 1 from pg_catalog.jsonb_object_keys(p_facts) as supplied(key)
      where supplied.key <> all (array['binding', 'recordTypes', 'relationships', 'sharingConditions', 'records', 'edges'])
    )
    or pg_catalog.jsonb_typeof(p_facts -> 'binding') <> 'object'
    or pg_catalog.jsonb_typeof(p_facts -> 'recordTypes') <> 'array'
    or pg_catalog.jsonb_typeof(p_facts -> 'relationships') <> 'array'
    or pg_catalog.jsonb_typeof(p_facts -> 'sharingConditions') <> 'array'
    or pg_catalog.jsonb_typeof(p_facts -> 'records') <> 'array'
    or pg_catalog.jsonb_typeof(p_facts -> 'edges') <> 'array' then
    raise exception using errcode = '22023', message = 'Record access facts are invalid';
  end if;

  facts_binding := p_facts -> 'binding';
  if not (facts_binding ?& array['moduleRootId', 'recordTypeId', 'storageContractId', 'storageScope'])
    or exists (
      select 1 from pg_catalog.jsonb_object_keys(facts_binding) as supplied(key)
      where supplied.key <> all (array['moduleRootId', 'recordTypeId', 'storageContractId', 'storageScope'])
    )
    or not vortex_context.is_non_nil_uuid(facts_binding ->> 'moduleRootId')
    or not vortex_context.is_non_nil_uuid(facts_binding ->> 'recordTypeId')
    or not vortex_context.is_non_nil_uuid(facts_binding ->> 'storageContractId')
    or facts_binding ->> 'storageScope' not in ('organization_shared', 'application_contained') then
    raise exception using errcode = '22023', message = 'Record access facts are invalid';
  end if;

  if pg_catalog.lower(facts_binding ->> 'moduleRootId') <> pg_catalog.lower(declaration_binding ->> 'moduleRootId')
    or pg_catalog.lower(facts_binding ->> 'recordTypeId') <> pg_catalog.lower(declaration_binding ->> 'recordTypeId')
    or pg_catalog.lower(facts_binding ->> 'storageContractId') <> pg_catalog.lower(declaration_binding ->> 'storageContractId')
    or (facts_binding ->> 'storageScope') <> (declaration_binding ->> 'storageScope') then
    raise exception using errcode = '22023', message = 'Record access facts are invalid';
  end if;

  -- Record types: unique identity, well-formed ownership/field shape.
  for record_type_item in
    select value from pg_catalog.jsonb_array_elements(p_facts -> 'recordTypes') as item(value)
  loop
    if pg_catalog.jsonb_typeof(record_type_item) <> 'object'
      or not (record_type_item ?& array[
        'moduleRootId', 'recordTypeId', 'storageContractId', 'storageScope', 'ownershipMode', 'fields'
      ])
      or exists (
        select 1 from pg_catalog.jsonb_object_keys(record_type_item) as supplied(key)
        where supplied.key <> all (array[
          'moduleRootId', 'recordTypeId', 'storageContractId', 'storageScope',
          'ownershipMode', 'ownershipRelationshipId', 'validationContractVersion', 'fields'
        ])
      )
      or not vortex_context.is_non_nil_uuid(record_type_item ->> 'moduleRootId')
      or not vortex_context.is_non_nil_uuid(record_type_item ->> 'recordTypeId')
      or not vortex_context.is_non_nil_uuid(record_type_item ->> 'storageContractId')
      or record_type_item ->> 'storageScope' not in ('organization_shared', 'application_contained')
      or record_type_item ->> 'ownershipMode' not in ('none', 'organization_account', 'group', 'inherited')
      or ((record_type_item ? 'ownershipRelationshipId') <> (record_type_item ->> 'ownershipMode' = 'inherited'))
      or (record_type_item ? 'ownershipRelationshipId'
        and not vortex_context.is_non_nil_uuid(record_type_item ->> 'ownershipRelationshipId'))
      or (record_type_item ? 'validationContractVersion' and (
        pg_catalog.jsonb_typeof(record_type_item -> 'validationContractVersion') <> 'string'
        or record_type_item ->> 'validationContractVersion' <> all (vortex_definition.accepted_contract_version('record_type'))
      ))
      or pg_catalog.jsonb_typeof(record_type_item -> 'fields') <> 'array' then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if pg_catalog.lower(record_type_item ->> 'recordTypeId') = any (seen_type_ids) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;
    seen_type_ids := pg_catalog.array_append(seen_type_ids, pg_catalog.lower(record_type_item ->> 'recordTypeId'));

    seen_field_ids := array[]::text[];
    for field_item in
      select value from pg_catalog.jsonb_array_elements(record_type_item -> 'fields') as item(value)
    loop
      if pg_catalog.jsonb_typeof(field_item) <> 'object'
        or not (field_item ?& array['fieldId', 'type'])
        or exists (
          select 1 from pg_catalog.jsonb_object_keys(field_item) as supplied(key)
          where supplied.key <> all (array['fieldId', 'type', 'settings'])
        )
        or not vortex_context.is_non_nil_uuid(field_item ->> 'fieldId')
        or pg_catalog.jsonb_typeof(field_item -> 'type') <> 'string'
        or (field_item ? 'settings' and pg_catalog.jsonb_typeof(field_item -> 'settings') <> 'object') then
        raise exception using errcode = '22023', message = 'Record access facts are invalid';
      end if;
      if pg_catalog.lower(field_item ->> 'fieldId') = any (seen_field_ids) then
        raise exception using errcode = '22023', message = 'Record access facts are invalid';
      end if;
      seen_field_ids := pg_catalog.array_append(seen_field_ids, pg_catalog.lower(field_item ->> 'fieldId'));
    end loop;
  end loop;

  if not (pg_catalog.lower(facts_binding ->> 'recordTypeId') = any (seen_type_ids)) then
    raise exception using errcode = '22023', message = 'Record access facts are invalid';
  end if;

  -- Relationships: unique identity, well-formed endpoints. `toRecordTypes`
  -- is every declared target: one for a link, several for a link to one of
  -- several record types.
  for relationship_item in
    select value from pg_catalog.jsonb_array_elements(p_facts -> 'relationships') as item(value)
  loop
    if pg_catalog.jsonb_typeof(relationship_item) <> 'object'
      or not (relationship_item ?& array[
        'relationshipId', 'fromModuleRootId', 'fromRecordTypeId', 'toRecordTypes'
      ])
      or exists (
        select 1 from pg_catalog.jsonb_object_keys(relationship_item) as supplied(key)
        where supplied.key <> all (array[
          'relationshipId', 'fromModuleRootId', 'fromRecordTypeId', 'toRecordTypes'
        ])
      )
      or not vortex_context.is_non_nil_uuid(relationship_item ->> 'relationshipId')
      or not vortex_context.is_non_nil_uuid(relationship_item ->> 'fromModuleRootId')
      or not vortex_context.is_non_nil_uuid(relationship_item ->> 'fromRecordTypeId')
      or pg_catalog.jsonb_typeof(relationship_item -> 'toRecordTypes') is distinct from 'array'
      or pg_catalog.jsonb_array_length(relationship_item -> 'toRecordTypes') = 0
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(relationship_item -> 'toRecordTypes') as target(value)
        where pg_catalog.jsonb_typeof(target.value) <> 'object'
          or not (target.value ?& array['moduleRootId', 'recordTypeId'])
          or exists (
            select 1 from pg_catalog.jsonb_object_keys(target.value) as supplied(key)
            where supplied.key <> all (array['moduleRootId', 'recordTypeId'])
          )
          or not vortex_context.is_non_nil_uuid(target.value ->> 'moduleRootId')
          or not vortex_context.is_non_nil_uuid(target.value ->> 'recordTypeId')
      ) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if pg_catalog.lower(relationship_item ->> 'relationshipId') = any (seen_relationship_ids) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;
    seen_relationship_ids := pg_catalog.array_append(
      seen_relationship_ids, pg_catalog.lower(relationship_item ->> 'relationshipId')
    );
  end loop;

  -- Sharing conditions: unique identity, the fields the row-scope composition
  -- and the saved-condition predicate actually consume. Extra compiled-release
  -- fields (key, publicationTests, ...) are passed through untouched.
  for condition_item in
    select value from pg_catalog.jsonb_array_elements(p_facts -> 'sharingConditions') as item(value)
  loop
    if pg_catalog.jsonb_typeof(condition_item) <> 'object'
      or not (condition_item ?& array[
        'conditionId', 'sourceRecordTypeId', 'publishedRevision', 'contractFingerprint',
        'parameters', 'condition', 'declaredFieldIds'
      ])
      or not vortex_context.is_non_nil_uuid(condition_item ->> 'conditionId')
      or not vortex_context.is_non_nil_uuid(condition_item ->> 'sourceRecordTypeId')
      or pg_catalog.jsonb_typeof(condition_item -> 'publishedRevision') <> 'number'
      or pg_catalog.jsonb_typeof(condition_item -> 'contractFingerprint') <> 'string'
      or pg_catalog.jsonb_typeof(condition_item -> 'parameters') <> 'array'
      or pg_catalog.jsonb_typeof(condition_item -> 'condition') <> 'object'
      or pg_catalog.jsonb_typeof(condition_item -> 'declaredFieldIds') <> 'array' then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if pg_catalog.lower(condition_item ->> 'conditionId') = any (seen_condition_ids) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;
    seen_condition_ids := pg_catalog.array_append(
      seen_condition_ids, pg_catalog.lower(condition_item ->> 'conditionId')
    );
  end loop;

  -- Records: unique identity, well-formed record-identity scope, known type.
  for record_item in
    select value from pg_catalog.jsonb_array_elements(p_facts -> 'records') as item(value)
  loop
    if pg_catalog.jsonb_typeof(record_item) <> 'object'
      or not (record_item ?& array['recordScope', 'lifecycleState', 'fieldValues'])
      or exists (
        select 1 from pg_catalog.jsonb_object_keys(record_item) as supplied(key)
        where supplied.key <> all (array[
          'recordScope', 'ownerOrganizationAccountId', 'ownerGroupId', 'lifecycleState', 'fieldValues'
        ])
      )
      or pg_catalog.jsonb_typeof(record_item -> 'recordScope') <> 'object'
      or record_item ->> 'lifecycleState' not in ('active', 'soft_deleted', 'removal_pending')
      or pg_catalog.jsonb_typeof(record_item -> 'fieldValues') <> 'object'
      or (record_item ? 'ownerOrganizationAccountId'
        and not vortex_context.is_non_nil_uuid(record_item ->> 'ownerOrganizationAccountId'))
      or (record_item ? 'ownerGroupId'
        and not vortex_context.is_non_nil_uuid(record_item ->> 'ownerGroupId'))
      or (record_item ? 'ownerOrganizationAccountId' and record_item ? 'ownerGroupId') then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    record_scope_item := record_item -> 'recordScope';
    select pg_catalog.count(*) into scope_key_count
    from pg_catalog.jsonb_object_keys(record_scope_item) as supplied(key);

    if not (record_scope_item ?& array[
        'storageScope', 'organizationId', 'moduleRootId', 'recordTypeId', 'storageContractId', 'recordId'
      ])
      or not vortex_context.is_non_nil_uuid(record_scope_item ->> 'organizationId')
      or not vortex_context.is_non_nil_uuid(record_scope_item ->> 'moduleRootId')
      or not vortex_context.is_non_nil_uuid(record_scope_item ->> 'recordTypeId')
      or not vortex_context.is_non_nil_uuid(record_scope_item ->> 'storageContractId')
      or not vortex_context.is_non_nil_uuid(record_scope_item ->> 'recordId')
      or (record_scope_item ->> 'storageScope') not in ('organization_shared', 'application_contained')
      or (
        (record_scope_item ->> 'storageScope') = 'organization_shared'
        and (scope_key_count <> 6 or record_scope_item ? 'applicationRootId')
      )
      or (
        (record_scope_item ->> 'storageScope') = 'application_contained'
        and (scope_key_count <> 7 or not vortex_context.is_non_nil_uuid(record_scope_item ->> 'applicationRootId'))
      ) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if not (pg_catalog.lower(record_scope_item ->> 'recordTypeId') = any (seen_type_ids)) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if pg_catalog.lower(record_scope_item ->> 'recordId') = any (seen_record_ids) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;
    seen_record_ids := pg_catalog.array_append(seen_record_ids, pg_catalog.lower(record_scope_item ->> 'recordId'));
  end loop;

  -- Edges: well-formed, no dangling relationship or missing endpoint record.
  -- Duplicate/ambiguous edges are a functional refusal inside the row-scope
  -- composition, not a facts-shape violation, so they are not rejected here.
  for edge_item in
    select value from pg_catalog.jsonb_array_elements(p_facts -> 'edges') as item(value)
  loop
    if pg_catalog.jsonb_typeof(edge_item) <> 'object'
      or not (edge_item ?& array['relationshipId', 'fromRecordId', 'toRecordId'])
      or exists (
        select 1 from pg_catalog.jsonb_object_keys(edge_item) as supplied(key)
        where supplied.key <> all (array['relationshipId', 'fromRecordId', 'toRecordId'])
      )
      or not vortex_context.is_non_nil_uuid(edge_item ->> 'relationshipId')
      or not vortex_context.is_non_nil_uuid(edge_item ->> 'fromRecordId')
      or not vortex_context.is_non_nil_uuid(edge_item ->> 'toRecordId') then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if not (pg_catalog.lower(edge_item ->> 'relationshipId') = any (seen_relationship_ids)) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;
    if not (pg_catalog.lower(edge_item ->> 'fromRecordId') = any (seen_record_ids))
      or not (pg_catalog.lower(edge_item ->> 'toRecordId') = any (seen_record_ids)) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;
  end loop;

  -- One Access-version observation, one time sample, shared by the eligibility
  -- call and every row-scope composition below.
  ctx := vortex_access.validated_human_request_context();
  checked_at := pg_catalog.clock_timestamp();

  eligibility := vortex_access.evaluate_organization_record_permission_eligibility_internal(
    p_declaration, ctx, checked_at
  );

  decision_evidence := (eligibility - 'outcome' - 'validUntil' - 'eligiblePermissions' - 'reasonCode')
    || pg_catalog.jsonb_build_object('recordId', p_target_record_id, 'action', p_declaration -> 'action');

  if eligibility ->> 'outcome' = 'refused' then
    return decision_evidence || pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', eligibility ->> 'reasonCode'
    );
  end if;

  target_application_root_id := (p_declaration -> 'target' ->> 'applicationRootId')::uuid;

  -- Target row check: fail closed, never raise. This is the cross-organisation
  -- and cross-application isolation path.
  select value into target_record_row
  from pg_catalog.jsonb_array_elements(p_facts -> 'records') as item(value)
  where (value -> 'recordScope' ->> 'recordId')::uuid = p_target_record_id
  limit 1;

  target_ok := target_record_row is not null
    and (target_record_row -> 'recordScope' ->> 'organizationId')::uuid = (ctx ->> 'organizationId')::uuid
    and pg_catalog.lower(target_record_row -> 'recordScope' ->> 'moduleRootId') = pg_catalog.lower(facts_binding ->> 'moduleRootId')
    and pg_catalog.lower(target_record_row -> 'recordScope' ->> 'recordTypeId') = pg_catalog.lower(facts_binding ->> 'recordTypeId')
    and pg_catalog.lower(target_record_row -> 'recordScope' ->> 'storageContractId') = pg_catalog.lower(facts_binding ->> 'storageContractId')
    and (target_record_row -> 'recordScope' ->> 'storageScope') = (facts_binding ->> 'storageScope')
    and (
      (facts_binding ->> 'storageScope') = 'organization_shared'
      or (target_record_row -> 'recordScope' ->> 'applicationRootId')::uuid = target_application_root_id
    )
    and target_record_row ->> 'lifecycleState' = 'active';

  if not target_ok then
    return decision_evidence || pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'record_scope_refused'
    );
  end if;

  auth_deadline := vortex_access.recent_authentication_deadline_internal(
    ctx, checked_at, p_declaration -> 'recentAuthentication'
  );

  select coalesce(
    pg_catalog.jsonb_agg(
      contribution.value
      order by
        alt.ordinality,
        case contribution.value -> 'route' ->> 'kind'
          when 'all_records' then 0
          when 'ownership' then 1
          when 'direct_share' then 2
          when 'relationship' then 3
        end,
        coalesce(
          contribution.value -> 'route' ->> 'directShareId',
          contribution.value -> 'route' ->> 'sourceRecordId',
          ''
        )
    ),
    '[]'::jsonb
  )
  into matched
  from pg_catalog.jsonb_array_elements(eligibility -> 'eligiblePermissions')
    with ordinality as alt(value, ordinality)
  cross join lateral pg_catalog.jsonb_array_elements(
    vortex_access.evaluate_record_permission_row_scope_internal(
      ctx,
      checked_at,
      auth_deadline,
      target_application_root_id,
      p_declaration -> 'action',
      alt.value,
      p_target_record_id,
      p_facts,
      array[(alt.value -> 'permission' ->> 'permissionId')::uuid]
    )
  ) as contribution(value);

  if pg_catalog.jsonb_array_length(matched) = 0 then
    return decision_evidence || pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'record_scope_refused'
    );
  end if;

  select vortex_context.format_timestamp_utc(
    pg_catalog.min((elem.value ->> 'validUntil')::timestamptz)
  )
  into decision_valid_until
  from pg_catalog.jsonb_array_elements(matched) as elem(value);

  return decision_evidence || pg_catalog.jsonb_build_object(
    'outcome', 'allowed',
    'validUntil', decision_valid_until,
    'matchedContributions', matched
  );
end
$function$;


ALTER FUNCTION vortex_access.evaluate_organization_record_access_internal(p_declaration jsonb, p_target_record_id uuid, p_facts jsonb) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_organization_record_access_internal(p_declaration jsonb, p_target_record_id uuid, p_facts jsonb); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_organization_record_access_internal(p_declaration jsonb, p_target_record_id uuid, p_facts jsonb) IS 'The complete exact-record access decision: unions every eligible alternative''s own complete row scope and always carries the exact recordId. Owner-only except for the fixed record adapter.';


--
-- Name: evaluate_organization_record_permission_availability(jsonb); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.evaluate_organization_record_permission_availability(
  p_declaration jsonb
)
returns table (
  eligibility jsonb,
  organization_id uuid,
  organization_account_id uuid,
  application_root_id uuid,
  access_version bigint,
  correlation_id uuid,
  expires_at timestamptz,
  observed_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  checked_at_value timestamptz;
  eligibility_value jsonb;
begin
  -- The placement entry point accepts exactly one permission; the private core validates all
  -- remaining declaration fields, including the action, target and exact record binding.
  if p_declaration is null
    or pg_catalog.jsonb_typeof(p_declaration) <> 'object'
    or pg_catalog.jsonb_typeof(p_declaration -> 'requiredPermissions') is distinct from 'array'
  then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_declaration -> 'requiredPermissions') <> 1 then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  checked_at_value := pg_catalog.clock_timestamp();
  eligibility_value := vortex_access.evaluate_organization_record_permission_eligibility_internal(
    p_declaration, context_value, checked_at_value
  );

  -- These bindings come from the same validated context and time used by the eligibility core.
  return query select
    eligibility_value,
    (context_value ->> 'organizationId')::uuid,
    (context_value ->> 'organizationAccountId')::uuid,
    (context_value ->> 'applicationRootId')::uuid,
    (context_value ->> 'accessVersion')::bigint,
    (context_value ->> 'correlationId')::uuid,
    (context_value ->> 'expiresAt')::timestamptz,
    checked_at_value;
end;
$function$;


ALTER FUNCTION vortex_access.evaluate_organization_record_permission_availability(p_declaration jsonb) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION evaluate_organization_record_permission_availability(p_declaration jsonb); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.evaluate_organization_record_permission_availability(p_declaration jsonb) IS 'Human-context-bound singleton record permission availability only; does not decide row access or invoke an operation.';


--
-- Name: evaluate_organization_record_permission_eligibility_internal(jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.evaluate_organization_record_permission_eligibility_internal(p_declaration jsonb, p_context jsonb, p_checked_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  declaration_action jsonb;
  declaration_target jsonb;
  declaration_permissions jsonb;
  declaration_binding jsonb;
  declaration_authentication jsonb;
  declaration_authority jsonb;
  permission_candidate jsonb;
  previous_identity text;
  candidate_identity text;
  operation_value text;
  action_kind_value text;
  target_application_value uuid;
  binding_record_type_value uuid;
  context_value jsonb;
  context_organization_value uuid;
  context_account_value uuid;
  context_access_version_value bigint;
  context_application_value uuid;
  context_expires_value timestamptz;
  context_correlation_value uuid;
  authentication_deadline timestamptz;
  authentication_satisfied boolean := true;
  context_current boolean := true;
  target_context_satisfied boolean := true;
  unsupported_context boolean := false;
  decision_checked_at timestamptz;
  catalogue_available boolean := false;
  scoped_available boolean := false;
  path_effective boolean := false;
  eligible_permissions jsonb;
  eligible_valid_until timestamptz;
  refusal_reason text;
  evidence jsonb;
begin
  if p_declaration is null
    or pg_catalog.jsonb_typeof(p_declaration) <> 'object'
    or not p_declaration ?& array[
      'operationKey', 'action', 'target', 'requiredPermissions',
      'recordBinding', 'recentAuthentication', 'authority'
    ]
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(p_declaration) as supplied(key)
      where supplied.key <> all (array[
        'operationKey', 'action', 'target', 'requiredPermissions',
        'recordBinding', 'recentAuthentication', 'authority'
      ])
    )
    or pg_catalog.jsonb_typeof(p_declaration -> 'operationKey') <> 'string'
    or pg_catalog.char_length(p_declaration ->> 'operationKey') not between 3 and 120
    or (p_declaration ->> 'operationKey') !~
      '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)+$'
    or (p_declaration ->> 'operationKey') ~ '(^|\.)[^.]{41,}(\.|$)' then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  declaration_action := p_declaration -> 'action';
  declaration_target := p_declaration -> 'target';
  declaration_permissions := p_declaration -> 'requiredPermissions';
  declaration_binding := p_declaration -> 'recordBinding';
  declaration_authentication := p_declaration -> 'recentAuthentication';
  declaration_authority := p_declaration -> 'authority';

  if pg_catalog.jsonb_typeof(declaration_action) <> 'object'
    or not declaration_action ? 'actionKind'
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(declaration_action) as supplied(key)
      where supplied.key <> all (array['actionKind', 'namedAction'])
    )
    or pg_catalog.jsonb_typeof(declaration_action -> 'actionKind') <> 'string'
    or declaration_action ->> 'actionKind' not in (
      'create', 'read', 'update', 'delete', 'restore', 'export', 'share', 'manage', 'transfer', 'named'
    )
    or (
      (declaration_action ->> 'actionKind') = 'named'
      and (
        not declaration_action ? 'namedAction'
        or pg_catalog.jsonb_typeof(declaration_action -> 'namedAction') <> 'string'
        or pg_catalog.char_length(declaration_action ->> 'namedAction') not between 1 and 40
        or (declaration_action ->> 'namedAction') !~
          '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
      )
    )
    or (
      (declaration_action ->> 'actionKind') <> 'named'
      and declaration_action ? 'namedAction'
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_target) <> 'object'
    or not declaration_target ?& array['kind', 'applicationRootId']
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(declaration_target) as supplied(key)
      where supplied.key <> all (array['kind', 'applicationRootId'])
    )
    or pg_catalog.jsonb_typeof(declaration_target -> 'kind') <> 'string'
    or declaration_target ->> 'kind' <> 'application'
    or not vortex_context.is_non_nil_uuid(
      declaration_target ->> 'applicationRootId'
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_binding) <> 'object'
    or not declaration_binding ?& array[
      'moduleRootId', 'recordTypeId', 'storageContractId', 'storageScope'
    ]
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(declaration_binding) as supplied(key)
      where supplied.key <> all (array[
        'moduleRootId', 'recordTypeId', 'storageContractId', 'storageScope'
      ])
    )
    or not vortex_context.is_non_nil_uuid(declaration_binding ->> 'moduleRootId')
    or not vortex_context.is_non_nil_uuid(declaration_binding ->> 'recordTypeId')
    or not vortex_context.is_non_nil_uuid(
      declaration_binding ->> 'storageContractId'
    )
    or pg_catalog.jsonb_typeof(declaration_binding -> 'storageScope') <> 'string'
    or declaration_binding ->> 'storageScope' not in (
      'organization_shared', 'application_contained'
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_authentication) <> 'object'
    or not declaration_authentication ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_authentication -> 'kind') <> 'string'
    or declaration_authentication ->> 'kind' not in ('none', 'primary', 'multi_factor')
    or (
      declaration_authentication ->> 'kind' = 'none'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_authentication) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_authentication ->> 'kind' in ('primary', 'multi_factor')
      and (
        not declaration_authentication ? 'maximumAgeSeconds'
        or pg_catalog.jsonb_typeof(
          declaration_authentication -> 'maximumAgeSeconds'
        ) <> 'number'
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_authentication) as supplied(key)
          where supplied.key <> all (array['kind', 'maximumAgeSeconds'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  if declaration_authentication ->> 'kind' in ('primary', 'multi_factor')
    and (
      (declaration_authentication ->> 'maximumAgeSeconds')::numeric < 1
      or (declaration_authentication ->> 'maximumAgeSeconds')::numeric >
        9007199254740991
      or (declaration_authentication ->> 'maximumAgeSeconds')::numeric <>
        pg_catalog.trunc(
          (declaration_authentication ->> 'maximumAgeSeconds')::numeric
        )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  -- A record operation carries ordinary permission authority only; delegated
  -- management scopes stay on the existing non-record path.
  if pg_catalog.jsonb_typeof(declaration_authority) <> 'object'
    or not declaration_authority ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_authority -> 'kind') <> 'string'
    or declaration_authority ->> 'kind' <> 'permission'
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(declaration_authority) as supplied(key)
      where supplied.key <> 'kind'
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_permissions) <> 'array'
    or pg_catalog.jsonb_array_length(declaration_permissions) = 0 then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  previous_identity := null;
  for permission_candidate in
    select item.value
    from pg_catalog.jsonb_array_elements(declaration_permissions) as item(value)
  loop
    if pg_catalog.jsonb_typeof(permission_candidate) <> 'object'
      or not permission_candidate ?& array[
        'applicationRootId', 'ownerKind', 'ownerId', 'permissionId'
      ]
      or exists (
        select 1
        from pg_catalog.jsonb_object_keys(permission_candidate) as supplied(key)
        where supplied.key <> all (array[
          'applicationRootId', 'ownerKind', 'ownerId', 'permissionId'
        ])
      )
      or pg_catalog.jsonb_typeof(permission_candidate -> 'ownerKind') <> 'string'
      or permission_candidate ->> 'ownerKind' not in ('application', 'module')
      or not vortex_context.is_non_nil_uuid(
        permission_candidate ->> 'applicationRootId'
      )
      or not vortex_context.is_non_nil_uuid(permission_candidate ->> 'ownerId')
      or not vortex_context.is_non_nil_uuid(permission_candidate ->> 'permissionId')
      or pg_catalog.lower(permission_candidate ->> 'applicationRootId') <>
        pg_catalog.lower(declaration_target ->> 'applicationRootId')
      or (
        permission_candidate ->> 'ownerKind' = 'application'
        and pg_catalog.lower(permission_candidate ->> 'ownerId') <>
          pg_catalog.lower(permission_candidate ->> 'applicationRootId')
      )
      or (
        permission_candidate ->> 'ownerKind' = 'module'
        and pg_catalog.lower(permission_candidate ->> 'ownerId') <>
          pg_catalog.lower(declaration_binding ->> 'moduleRootId')
      ) then
      raise exception using errcode = '22023',
        message = 'Organization record permission declaration is invalid';
    end if;

    candidate_identity := pg_catalog.concat_ws(
      ':',
      pg_catalog.lower(permission_candidate ->> 'applicationRootId'),
      permission_candidate ->> 'ownerKind',
      pg_catalog.lower(permission_candidate ->> 'ownerId'),
      pg_catalog.lower(permission_candidate ->> 'permissionId')
    );
    if previous_identity is not null
      and previous_identity collate "C" >= candidate_identity then
      raise exception using errcode = '22023',
        message = 'Organization record permission declaration is invalid';
    end if;
    previous_identity := candidate_identity;
  end loop;

  operation_value := p_declaration ->> 'operationKey';
  action_kind_value := declaration_action ->> 'actionKind';
  target_application_value := (declaration_target ->> 'applicationRootId')::uuid;
  binding_record_type_value := (declaration_binding ->> 'recordTypeId')::uuid;

  if action_kind_value = 'named'
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(declaration_permissions) as item(value)
      where item.value ->> 'ownerKind' <>
          declaration_permissions -> 0 ->> 'ownerKind'
        or pg_catalog.lower(item.value ->> 'ownerId') <>
          pg_catalog.lower(declaration_permissions -> 0 ->> 'ownerId')
    ) then
    raise exception using errcode = '22023',
      message = 'Organization record permission declaration is invalid';
  end if;

  context_value := p_context;
  context_organization_value := (context_value ->> 'organizationId')::uuid;
  context_account_value := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version_value := (context_value ->> 'accessVersion')::bigint;
  context_application_value := case
    when context_value ? 'applicationRootId'
      then (context_value ->> 'applicationRootId')::uuid
    else null
  end;
  context_expires_value := (context_value ->> 'expiresAt')::timestamptz;
  context_correlation_value := (context_value ->> 'correlationId')::uuid;
  decision_checked_at := p_checked_at;
  context_current := context_expires_value > decision_checked_at;

  unsupported_context := context_value ? 'delegatedContext'
    or context_value ? 'supportContext';
  target_context_satisfied := coalesce(
    context_application_value = target_application_value, false
  );

  authentication_deadline := vortex_access.recent_authentication_deadline_internal(
    context_value, decision_checked_at, declaration_authentication
  );
  authentication_satisfied := authentication_deadline is not null;

  -- Every declared alternative is evaluated against its exact record type by the
  -- shared role-path helper under this one context and checked time. A candidate
  -- keeps its own catalogue record scope, immutable source release and path
  -- deadline; an alternative never lends authority to another. Keeping
  -- path_valid_until separate from authentication_deadline here (instead of
  -- combining them per row) is what lets the three existence flags below tell
  -- "no catalogue entry", "entry without record scope" and "scoped entry
  -- without a live path" apart as distinct refusal reasons.
  with candidate as (
    select declared.ordinality as alternative_ordinal,
      declared.value as permission_value,
      (evaluated.permission_entry).record_scope as record_scope,
      pg_catalog.jsonb_build_object(
        'kind', (evaluated.permission_entry).source_kind,
        'definitionKey', (evaluated.permission_entry).source_definition_key,
        'rootId', (evaluated.permission_entry).source_root_id,
        'releaseRevision', (evaluated.permission_entry).source_revision,
        'releaseVersion', (evaluated.permission_entry).source_version,
        'validationContractVersion',
          (evaluated.permission_entry).source_validation_contract_version,
        'contentFingerprint', (evaluated.permission_entry).source_content_fingerprint,
        'resolutionFingerprint',
          (evaluated.permission_entry).source_resolution_fingerprint
      ) as source_release,
      evaluated.path_valid_until as path_valid_until
    from pg_catalog.jsonb_array_elements(declaration_permissions)
      with ordinality as declared(value, ordinality)
    cross join lateral vortex_access.evaluate_permission_role_path_internal(
      context_value, decision_checked_at, declared.value, declaration_action,
      binding_record_type_value
    ) as evaluated
  )
  select pg_catalog.count(*) > 0,
    pg_catalog.count(*) filter (where candidate.record_scope is not null) > 0,
    pg_catalog.count(*) filter (
      where candidate.record_scope is not null
        and candidate.path_valid_until is not null
    ) > 0,
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'permission', candidate.permission_value,
        'recordScope', candidate.record_scope,
        'source', candidate.source_release,
        'validUntil', pg_catalog.to_char(
          pg_catalog.timezone(
            'UTC', least(candidate.path_valid_until, authentication_deadline)
          ),
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        )
      ) order by candidate.alternative_ordinal
    ) filter (
      where candidate.record_scope is not null
        and candidate.path_valid_until is not null
        and authentication_deadline is not null
    ),
    pg_catalog.min(least(candidate.path_valid_until, authentication_deadline))
      filter (
        where candidate.record_scope is not null
          and candidate.path_valid_until is not null
          and authentication_deadline is not null
      )
  into catalogue_available, scoped_available, path_effective, eligible_permissions,
    eligible_valid_until
  from candidate;

  evidence := pg_catalog.jsonb_build_object(
    'operationKey', operation_value,
    'target', declaration_target,
    'organizationId', context_organization_value,
    'organizationAccountId', context_account_value,
    'accessVersion', context_access_version_value,
    'checkedAt', pg_catalog.to_char(
      pg_catalog.timezone('UTC', decision_checked_at),
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    ),
    'correlationId', context_correlation_value,
    'recordBinding', declaration_binding
  );

  -- Refusal precedence keeps each cause distinguishable: an unsupported
  -- context always wins; then "no candidate has any catalogue entry"; then
  -- "entries exist but none carries record_scope"; then "scoped entries exist
  -- but none has a live role path"; only then does recent-authentication
  -- refuse an otherwise-complete set of alternatives.
  refusal_reason := case
    when not context_current
      or unsupported_context or not target_context_satisfied
      then 'target_policy_unavailable'
    when not catalogue_available then 'permission_unavailable'
    when not scoped_available then 'target_policy_unavailable'
    when not path_effective then 'permission_not_effective'
    when not authentication_satisfied then 'authentication_unsatisfied'
    else null
  end;

  if refusal_reason is not null then
    return evidence || pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', refusal_reason
    );
  end if;

  return evidence || pg_catalog.jsonb_build_object(
    'outcome', 'eligible',
    'validUntil', pg_catalog.to_char(
      pg_catalog.timezone('UTC', eligible_valid_until),
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    ),
    'eligiblePermissions', eligible_permissions
  );
end
$_$;


ALTER FUNCTION vortex_access.evaluate_organization_record_permission_eligibility_internal(p_declaration jsonb, p_context jsonb, p_checked_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_organization_record_permission_eligibility_internal(p_declaration jsonb, p_context jsonb, p_checked_at timestamp with time zone); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_organization_record_permission_eligibility_internal(p_declaration jsonb, p_context jsonb, p_checked_at timestamp with time zone) IS 'Private record-permission eligibility evidence per declared alternative; carries the declared record binding as context and is never a record allow result. The caller supplies one Access-bound context and checked time.';


--
-- Name: permission_field_policy_is_valid(jsonb); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.permission_field_policy_is_valid(p_policy jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  field_value jsonb;
  field_id text;
  previous_field_id text;
begin
  if p_policy is null
    or pg_catalog.jsonb_typeof(p_policy) <> 'object'
    or p_policy - array['readableFieldIds', 'changeableFieldIds']::text[] <> '{}'::jsonb
    or not (p_policy ?& array['readableFieldIds', 'changeableFieldIds'])
    or pg_catalog.jsonb_typeof(p_policy -> 'readableFieldIds') <> 'array'
    or pg_catalog.jsonb_typeof(p_policy -> 'changeableFieldIds') <> 'array' then
    return false;
  end if;

  previous_field_id := null;
  for field_value in
    select item.value from pg_catalog.jsonb_array_elements(
      p_policy -> 'readableFieldIds'
    ) as item(value)
  loop
    if pg_catalog.jsonb_typeof(field_value) <> 'string' then return false; end if;
    field_id := field_value #>> '{}';
    if not vortex_context.is_non_nil_uuid(field_id)
      or (
        previous_field_id is not null
        and previous_field_id >= pg_catalog.lower(field_id)
      ) then
      return false;
    end if;
    previous_field_id := pg_catalog.lower(field_id);
  end loop;

  previous_field_id := null;
  for field_value in
    select item.value from pg_catalog.jsonb_array_elements(
      p_policy -> 'changeableFieldIds'
    ) as item(value)
  loop
    if pg_catalog.jsonb_typeof(field_value) <> 'string' then return false; end if;
    field_id := field_value #>> '{}';
    if not vortex_context.is_non_nil_uuid(field_id)
      or (
        previous_field_id is not null
        and previous_field_id >= pg_catalog.lower(field_id)
      )
      or not exists (
        select 1
        from pg_catalog.jsonb_array_elements_text(
          p_policy -> 'readableFieldIds'
        ) as readable(value)
        where pg_catalog.lower(readable.value) = pg_catalog.lower(field_id)
      ) then
      return false;
    end if;
    previous_field_id := pg_catalog.lower(field_id);
  end loop;
  return true;
end
$$;


ALTER FUNCTION vortex_access.permission_field_policy_is_valid(p_policy jsonb) OWNER TO postgres;

--
-- Name: FUNCTION permission_field_policy_is_valid(p_policy jsonb); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.permission_field_policy_is_valid(p_policy jsonb) IS 'Private strict validator for canonical unique field-policy UUID arrays and their subset rule.';


--
-- Name: permission_record_scope_is_valid(jsonb); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.permission_record_scope_is_valid(p_record_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  route_value jsonb;
  route_kind text;
  route_identity text;
  previous_route_identity text;
  has_all_records boolean := false;
  route_count integer := 0;
  saved_condition jsonb;
  binding_value jsonb;
  binding_key text;
  binding_key_count integer;
  previous_binding_key text;
begin
  if p_record_scope is null
    or pg_catalog.jsonb_typeof(p_record_scope) <> 'object'
    or p_record_scope - array['routes', 'savedCondition']::text[] <> '{}'::jsonb
    or not (p_record_scope ? 'routes')
    or pg_catalog.jsonb_typeof(p_record_scope -> 'routes') <> 'array'
    or pg_catalog.jsonb_array_length(p_record_scope -> 'routes') < 1 then
    return false;
  end if;

  previous_route_identity := null;
  for route_value in
    select item.value
    from pg_catalog.jsonb_array_elements(p_record_scope -> 'routes') as item(value)
  loop
    if pg_catalog.jsonb_typeof(route_value) <> 'object'
      or not (route_value ? 'kind')
      or pg_catalog.jsonb_typeof(route_value -> 'kind') <> 'string' then
      return false;
    end if;
    route_kind := route_value ->> 'kind';
    route_count := route_count + 1;

    if route_kind = 'all_records' then
      if route_value - array['kind']::text[] <> '{}'::jsonb then
        return false;
      end if;
      has_all_records := true;
      route_identity := '0:';
    elsif route_kind = 'ownership' then
      if route_value - array['kind']::text[] <> '{}'::jsonb then
        return false;
      end if;
      route_identity := '1:';
    elsif route_kind = 'direct_share' then
      if route_value - array['kind']::text[] <> '{}'::jsonb then
        return false;
      end if;
      route_identity := '2:';
    elsif route_kind = 'relationship' then
      if route_value - array['kind', 'relationshipId', 'sourcePermissionId']::text[]
          <> '{}'::jsonb
        or not (route_value ?& array['relationshipId', 'sourcePermissionId'])
        or pg_catalog.jsonb_typeof(route_value -> 'relationshipId') <> 'string'
        or pg_catalog.jsonb_typeof(route_value -> 'sourcePermissionId') <> 'string'
        or not vortex_context.is_non_nil_uuid(route_value ->> 'relationshipId')
        or not vortex_context.is_non_nil_uuid(route_value ->> 'sourcePermissionId') then
        return false;
      end if;
      route_identity := '3:' || pg_catalog.lower(route_value ->> 'relationshipId')
        || ':' || pg_catalog.lower(route_value ->> 'sourcePermissionId');
    else
      return false;
    end if;

    -- One strictly-ascending adjacent-pair check encodes both Zod rules at
    -- once: a route array that is unique by identity AND in canonical order
    -- is exactly a route array whose identities strictly increase pairwise,
    -- and vice versa (strict monotonicity implies injectivity). This is the
    -- same combined check the ownership-visibility function used to run
    -- itself (20260906144015_evaluate_current_record_ownership_visibility.sql).
    if previous_route_identity is not null
      and (route_identity collate "C") <= (previous_route_identity collate "C") then
      return false;
    end if;
    previous_route_identity := route_identity;
  end loop;

  if has_all_records and route_count <> 1 then
    return false;
  end if;

  if p_record_scope ? 'savedCondition' then
    saved_condition := p_record_scope -> 'savedCondition';
    if pg_catalog.jsonb_typeof(saved_condition) <> 'object'
      or saved_condition - array[
        'conditionId', 'publishedRevision', 'contractFingerprint', 'parameterBindings'
      ]::text[] <> '{}'::jsonb
      or not (saved_condition ?& array[
        'conditionId', 'publishedRevision', 'contractFingerprint', 'parameterBindings'
      ])
      or pg_catalog.jsonb_typeof(saved_condition -> 'conditionId') <> 'string'
      or not vortex_context.is_non_nil_uuid(saved_condition ->> 'conditionId')
      or pg_catalog.jsonb_typeof(saved_condition -> 'publishedRevision') <> 'number'
      or (saved_condition ->> 'publishedRevision') !~ '^[1-9][0-9]*$'
      or (saved_condition ->> 'publishedRevision')::numeric > 9007199254740991
      or pg_catalog.jsonb_typeof(saved_condition -> 'contractFingerprint') <> 'string'
      or (saved_condition ->> 'contractFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pg_catalog.jsonb_typeof(saved_condition -> 'parameterBindings') <> 'array' then
      return false;
    end if;

    previous_binding_key := null;
    for binding_value in
      select item.value
      from pg_catalog.jsonb_array_elements(
        saved_condition -> 'parameterBindings'
      ) as item(value)
    loop
      if pg_catalog.jsonb_typeof(binding_value) <> 'object'
        or not (binding_value ? 'key')
        or pg_catalog.jsonb_typeof(binding_value -> 'key') <> 'string' then
        return false;
      end if;
      binding_key := binding_value ->> 'key';
      if binding_key !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
        or pg_catalog.length(binding_key) > 40 then
        return false;
      end if;
      select pg_catalog.count(*) into binding_key_count
      from pg_catalog.jsonb_object_keys(binding_value) as key;

      if not (binding_value ? 'source')
        or pg_catalog.jsonb_typeof(binding_value -> 'source') <> 'string' then
        return false;
      end if;

      if binding_value ->> 'source' = 'current_organization_account_id' then
        if binding_key_count <> 2 then
          return false;
        end if;
      elsif binding_value ->> 'source' = 'literal' then
        if binding_key_count <> 3 or not (binding_value ? 'value') then
          return false;
        end if;
      else
        return false;
      end if;

      if previous_binding_key is not null
        and (binding_key collate "C") <= (previous_binding_key collate "C") then
        return false;
      end if;
      previous_binding_key := binding_key;
    end loop;
  end if;

  return true;
end
$_$;


ALTER FUNCTION vortex_access.permission_record_scope_is_valid(p_record_scope jsonb) OWNER TO postgres;

--
-- Name: FUNCTION permission_record_scope_is_valid(p_record_scope jsonb); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.permission_record_scope_is_valid(p_record_scope jsonb) IS 'Private strict validator for canonical unique record-scope routes, the sole all-record route rule and the saved-condition envelope shape.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: permission_catalogue_entries; Type: TABLE; Schema: vortex_access; Owner: postgres
--

CREATE TABLE vortex_access.permission_catalogue_entries (
    organization_id uuid NOT NULL,
    registration_kind text NOT NULL,
    registration_owner_id uuid NOT NULL,
    registration_revision bigint NOT NULL,
    application_root_id uuid,
    owner_kind text NOT NULL,
    owner_id uuid NOT NULL,
    permission_id uuid NOT NULL,
    permission_key text NOT NULL,
    label text NOT NULL,
    description text NOT NULL,
    record_type_id uuid,
    action_kind text NOT NULL,
    named_action text,
    administrative boolean NOT NULL,
    source_kind text NOT NULL,
    source_definition_key text,
    source_root_id uuid,
    source_version text NOT NULL,
    source_revision bigint,
    source_validation_contract_version text,
    source_content_fingerprint text,
    source_resolution_fingerprint text,
    source_catalogue_fingerprint text,
    meaning_fingerprint text NOT NULL,
    record_scope jsonb,
    field_policy jsonb,
    CONSTRAINT permission_catalogue_entries_action_kind_valid CHECK ((action_kind = ANY (ARRAY['create'::text, 'read'::text, 'update'::text, 'delete'::text, 'restore'::text, 'export'::text, 'share'::text, 'manage'::text, 'transfer'::text, 'named'::text]))),
    CONSTRAINT permission_catalogue_entries_description_valid CHECK (((description = btrim(description)) AND ((char_length(description) >= 1) AND (char_length(description) <= 1000)))),
    CONSTRAINT permission_catalogue_entries_field_policy_shape CHECK (((field_policy IS NULL) OR ((registration_kind = 'application'::text) AND (record_type_id IS NOT NULL) AND (jsonb_typeof(field_policy) = 'object'::text) AND ((field_policy - ARRAY['readableFieldIds'::text, 'changeableFieldIds'::text]) = '{}'::jsonb) AND (field_policy ?& ARRAY['readableFieldIds'::text, 'changeableFieldIds'::text]) AND (jsonb_typeof((field_policy -> 'readableFieldIds'::text)) = 'array'::text) AND (jsonb_typeof((field_policy -> 'changeableFieldIds'::text)) = 'array'::text)))),
    CONSTRAINT permission_catalogue_entries_field_policy_value CHECK (((field_policy IS NULL) OR vortex_access.permission_field_policy_is_valid(field_policy))),
    CONSTRAINT permission_catalogue_entries_fingerprints_valid CHECK ((((source_content_fingerprint IS NULL) OR (source_content_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)) AND ((source_resolution_fingerprint IS NULL) OR (source_resolution_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)) AND ((source_catalogue_fingerprint IS NULL) OR (source_catalogue_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)) AND (meaning_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text))),
    CONSTRAINT permission_catalogue_entries_ids_non_nil CHECK (((registration_owner_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (owner_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (permission_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((application_root_id IS NULL) OR (application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid)) AND ((record_type_id IS NULL) OR (record_type_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT permission_catalogue_entries_label_valid CHECK (((label = btrim(label)) AND ((char_length(label) >= 1) AND (char_length(label) <= 60)))),
    CONSTRAINT permission_catalogue_entries_named_action_shape CHECK ((((action_kind = 'named'::text) = (named_action IS NOT NULL)) AND ((named_action IS NULL) OR (((char_length(named_action) >= 1) AND (char_length(named_action) <= 40)) AND (named_action ~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'::text))))),
    CONSTRAINT permission_catalogue_entries_owner_kind_valid CHECK ((owner_kind = ANY (ARRAY['platform'::text, 'application'::text, 'module'::text]))),
    CONSTRAINT permission_catalogue_entries_permission_key_format CHECK ((((char_length(permission_key) >= 3) AND (char_length(permission_key) <= 120)) AND (permission_key ~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)+$'::text) AND (permission_key !~ '(^|\.)[^.]{41,}(\.|$)'::text))),
    CONSTRAINT permission_catalogue_entries_record_scope_shape CHECK (((record_scope IS NULL) OR ((registration_kind = 'application'::text) AND (record_type_id IS NOT NULL) AND (jsonb_typeof(record_scope) = 'object'::text)))),
    CONSTRAINT permission_catalogue_entries_record_scope_value CHECK (((record_scope IS NULL) OR vortex_access.permission_record_scope_is_valid(record_scope))),
    CONSTRAINT permission_catalogue_entries_registration_kind_valid CHECK ((registration_kind = ANY (ARRAY['platform'::text, 'application'::text]))),
    CONSTRAINT permission_catalogue_entries_revision_range CHECK ((((registration_revision >= 1) AND (registration_revision <= '9007199254740991'::bigint)) AND ((source_revision IS NULL) OR ((source_revision >= 1) AND (source_revision <= '9007199254740991'::bigint))))),
    CONSTRAINT permission_catalogue_entries_scope_shape CHECK ((((registration_kind = 'platform'::text) AND (registration_owner_id = 'cabe121e-0baf-4084-9471-cce915d460a8'::uuid) AND (application_root_id IS NULL) AND (owner_kind = 'platform'::text) AND (owner_id = registration_owner_id) AND (source_kind = 'platform_catalogue'::text) AND (source_definition_key IS NULL) AND (source_root_id IS NULL) AND (source_revision IS NULL) AND (source_validation_contract_version IS NULL) AND (source_content_fingerprint IS NULL) AND (source_resolution_fingerprint IS NULL) AND (source_catalogue_fingerprint IS NOT NULL)) OR ((registration_kind = 'application'::text) AND (application_root_id = registration_owner_id) AND (owner_kind = ANY (ARRAY['application'::text, 'module'::text])) AND (source_kind = owner_kind) AND (source_definition_key IS NOT NULL) AND (source_root_id = owner_id) AND (source_revision IS NOT NULL) AND (source_validation_contract_version IS NOT NULL) AND (source_content_fingerprint IS NOT NULL) AND (source_resolution_fingerprint IS NOT NULL) AND (source_catalogue_fingerprint IS NULL) AND ((owner_kind <> 'application'::text) OR (owner_id = application_root_id))))),
    CONSTRAINT permission_catalogue_entries_source_definition_key_format CHECK (((source_definition_key IS NULL) OR (((char_length(source_definition_key) >= 3) AND (char_length(source_definition_key) <= 120)) AND (source_definition_key ~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)+$'::text) AND (source_definition_key !~ '(^|\.)[^.]{41,}(\.|$)'::text)))),
    CONSTRAINT permission_catalogue_entries_source_kind_valid CHECK ((source_kind = ANY (ARRAY['platform_catalogue'::text, 'application'::text, 'module'::text]))),
    CONSTRAINT permission_catalogue_entries_source_version_format CHECK ((source_version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'::text)),
    CONSTRAINT permission_catalogue_entries_validation_version_format CHECK (((source_validation_contract_version IS NULL) OR (source_validation_contract_version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-((0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)(\.(0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?(\+([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?$'::text)))
);

ALTER TABLE ONLY vortex_access.permission_catalogue_entries FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_access.permission_catalogue_entries OWNER TO postgres;

--
-- Name: TABLE permission_catalogue_entries; Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON TABLE vortex_access.permission_catalogue_entries IS 'Immutable owner-qualified permissions supplied by one exact registration revision.';


--
-- Name: COLUMN permission_catalogue_entries.record_scope; Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON COLUMN vortex_access.permission_catalogue_entries.record_scope IS 'Optional canonical Definition-owned record scope; historical omission remains SQL null.';


--
-- Name: COLUMN permission_catalogue_entries.field_policy; Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON COLUMN vortex_access.permission_catalogue_entries.field_policy IS 'Optional canonical Definition-owned field policy; historical omission remains SQL null.';


--
-- Name: evaluate_permission_role_path_internal(jsonb, timestamp with time zone, jsonb, jsonb, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.evaluate_permission_role_path_internal(
  p_context jsonb,
  p_checked_at timestamptz,
  p_permission jsonb,
  p_action jsonb,
  p_record_type_id uuid
)
returns table (
  permission_entry vortex_access.permission_catalogue_entries,
  path_valid_until timestamptz
)
language plpgsql
stable
security invoker
set search_path = ''
as $function$
declare
  context_organization_value uuid := (p_context ->> 'organizationId')::uuid;
  context_account_value uuid := (p_context ->> 'organizationAccountId')::uuid;
  context_expires_value timestamptz := (p_context ->> 'expiresAt')::timestamptz;
  decision_checked_at timestamptz := p_checked_at;
  permission_application_value uuid := (p_permission ->> 'applicationRootId')::uuid;
  permission_owner_kind_value text := p_permission ->> 'ownerKind';
  permission_owner_value uuid := (p_permission ->> 'ownerId')::uuid;
  permission_value uuid := (p_permission ->> 'permissionId')::uuid;
  action_kind_value text := p_action ->> 'actionKind';
  named_action_value text := p_action ->> 'namedAction';
begin
  return query
  with current_permission as materialized (
    select catalogue.application_root_id, catalogue.owner_kind,
      catalogue.owner_id, catalogue.permission_id,
      catalogue.meaning_fingerprint, catalogue as permission_entry
    from vortex_access.permission_registrations as registration
    join vortex_access.permission_catalogue_entries as catalogue
      on catalogue.organization_id = registration.organization_id
      and catalogue.registration_kind = registration.registration_kind
      and catalogue.registration_owner_id = registration.registration_owner_id
      and catalogue.registration_revision = registration.revision
    join vortex_access.permission_continuities as continuity
      on continuity.organization_id = catalogue.organization_id
      and continuity.application_root_id is not distinct from
        catalogue.application_root_id
      and continuity.owner_kind = catalogue.owner_kind
      and continuity.owner_id = catalogue.owner_id
      and continuity.permission_id = catalogue.permission_id
      and continuity.registration_kind = catalogue.registration_kind
      and continuity.registration_owner_id = catalogue.registration_owner_id
      and continuity.last_processed_registration_revision = registration.revision
      and continuity.state = 'available'
      and continuity.meaning_fingerprint = catalogue.meaning_fingerprint
    where registration.organization_id = context_organization_value
      and registration.state = 'active'
      and catalogue.application_root_id is not distinct from
        permission_application_value
      and catalogue.owner_kind = permission_owner_kind_value
      and catalogue.owner_id = permission_owner_value
      and catalogue.permission_id = permission_value
      and catalogue.record_type_id is not distinct from p_record_type_id
      and catalogue.action_kind = action_kind_value
      and catalogue.named_action is not distinct from named_action_value
  ), current_role_permission as materialized (
    select role.role_id, role.live_revision,
      revision.assignment_policy, revision.authority_continuity_revision,
      revision.policy_continuity_revision, revision.activation_policy_id,
      revision.activation_policy_revision,
      revision.activation_policy_fingerprint
    from vortex_access.organization_roles as role
    join vortex_access.organization_role_revisions as revision
      on revision.organization_id = role.organization_id
      and revision.role_id = role.role_id
      and revision.revision = role.live_revision
    join vortex_access.organization_role_permission_entries as permission
      on permission.organization_id = revision.organization_id
      and permission.role_id = revision.role_id
      and permission.role_revision = revision.revision
    join current_permission as available
      on available.application_root_id is not distinct from
        permission.application_root_id
      and available.owner_kind = permission.owner_kind
      and available.owner_id = permission.owner_id
      and available.permission_id = permission.permission_id
      and available.meaning_fingerprint = permission.meaning_fingerprint
    join vortex_access.permission_continuities as continuity
      on continuity.organization_id = permission.organization_id
      and continuity.application_root_id is not distinct from
        permission.application_root_id
      and continuity.owner_kind = permission.owner_kind
      and continuity.owner_id = permission.owner_id
      and continuity.permission_id = permission.permission_id
      and continuity.state = 'available'
      and continuity.continuity_revision = permission.continuity_revision
      and continuity.meaning_fingerprint = permission.meaning_fingerprint
    where role.organization_id = context_organization_value
      and revision.lifecycle in ('active', 'acceptance_required')
  ), route_candidates as (
    select 1 as route_rank, permission.role_id,
      assignment.role_assignment_id, null::uuid as membership_id,
      null::uuid as role_activation_id,
      least(
        context_expires_value,
        coalesce(assignment.expires_at, context_expires_value)
      ) as path_valid_until
    from current_role_permission as permission
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = context_organization_value
      and assignment.role_id = permission.role_id
      and assignment.assignee_kind = 'organization_account'
      and assignment.organization_account_id = context_account_value
      and assignment.assignment_kind = 'standing'
      and assignment.state = 'live'
      and assignment.starts_at <= decision_checked_at
      and (
        assignment.expires_at is null
        or assignment.expires_at > decision_checked_at
      )
    where permission.assignment_policy = 'standing'

    union all

    select 2, permission.role_id, assignment.role_assignment_id,
      membership.membership_id, null::uuid,
      least(
        context_expires_value,
        coalesce(assignment.expires_at, context_expires_value),
        coalesce(membership.expires_at, context_expires_value)
      )
    from current_role_permission as permission
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = context_organization_value
      and assignment.role_id = permission.role_id
      and assignment.assignee_kind = 'group'
      and assignment.assignment_kind = 'standing'
      and assignment.state = 'live'
      and assignment.starts_at <= decision_checked_at
      and (
        assignment.expires_at is null
        or assignment.expires_at > decision_checked_at
      )
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = assignment.organization_id
      and organization_group.group_id = assignment.group_id
      and organization_group.state = 'active'
    join vortex_access.organization_group_memberships as membership
      on membership.organization_id = assignment.organization_id
      and membership.group_id = assignment.group_id
      and membership.organization_account_id = context_account_value
      and membership.state = 'live'
      and membership.starts_at <= decision_checked_at
      and (
        membership.expires_at is null
        or membership.expires_at > decision_checked_at
      )
    where permission.assignment_policy = 'standing'

    union all

    select 3, permission.role_id, assignment.role_assignment_id,
      null::uuid, activation.role_activation_id,
      least(
        context_expires_value,
        coalesce(assignment.expires_at, context_expires_value),
        activation.expires_at
      )
    from current_role_permission as permission
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = context_organization_value
      and assignment.role_id = permission.role_id
      and assignment.assignee_kind = 'organization_account'
      and assignment.organization_account_id = context_account_value
      and assignment.assignment_kind = 'eligible'
      and assignment.state = 'live'
      and assignment.starts_at <= decision_checked_at
      and (
        assignment.expires_at is null
        or assignment.expires_at > decision_checked_at
      )
    join vortex_access.organization_role_activations as activation
      on activation.organization_id = assignment.organization_id
      and activation.organization_account_id = context_account_value
      and activation.role_id = assignment.role_id
      and activation.eligibility_source_kind = 'direct'
      and activation.role_assignment_id = assignment.role_assignment_id
      and activation.role_assignment_revision = assignment.revision
      and activation.state = 'live'
      and activation.activated_at <= decision_checked_at
      and activation.expires_at > decision_checked_at
      and activation.authority_continuity_revision =
        permission.authority_continuity_revision
      and activation.policy_continuity_revision =
        permission.policy_continuity_revision
      and activation.activation_policy_id = permission.activation_policy_id
      and activation.activation_policy_revision =
        permission.activation_policy_revision
      and activation.activation_policy_fingerprint =
        permission.activation_policy_fingerprint
    where permission.assignment_policy = 'activation_required'

    union all

    select 4, permission.role_id, assignment.role_assignment_id,
      membership.membership_id, activation.role_activation_id,
      least(
        context_expires_value,
        coalesce(assignment.expires_at, context_expires_value),
        coalesce(membership.expires_at, context_expires_value),
        activation.expires_at
      )
    from current_role_permission as permission
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = context_organization_value
      and assignment.role_id = permission.role_id
      and assignment.assignee_kind = 'group'
      and assignment.assignment_kind = 'eligible'
      and assignment.state = 'live'
      and assignment.starts_at <= decision_checked_at
      and (
        assignment.expires_at is null
        or assignment.expires_at > decision_checked_at
      )
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = assignment.organization_id
      and organization_group.group_id = assignment.group_id
      and organization_group.state = 'active'
    join vortex_access.organization_role_activations as activation
      on activation.organization_id = assignment.organization_id
      and activation.organization_account_id = context_account_value
      and activation.role_id = assignment.role_id
      and activation.eligibility_source_kind = 'group'
      and activation.role_assignment_id = assignment.role_assignment_id
      and activation.role_assignment_revision = assignment.revision
      and activation.state = 'live'
      and activation.activated_at <= decision_checked_at
      and activation.expires_at > decision_checked_at
      and activation.authority_continuity_revision =
        permission.authority_continuity_revision
      and activation.policy_continuity_revision =
        permission.policy_continuity_revision
      and activation.activation_policy_id = permission.activation_policy_id
      and activation.activation_policy_revision =
        permission.activation_policy_revision
      and activation.activation_policy_fingerprint =
        permission.activation_policy_fingerprint
    join vortex_access.organization_group_memberships as membership
      on membership.organization_id = assignment.organization_id
      and membership.group_id = assignment.group_id
      and membership.organization_account_id = context_account_value
      and membership.membership_id = activation.membership_id
      and membership.revision = activation.membership_revision
      and membership.state = 'live'
      and membership.starts_at <= decision_checked_at
      and (
        membership.expires_at is null
        or membership.expires_at > decision_checked_at
      )
    where permission.assignment_policy = 'activation_required'
  ), selected_route as materialized (
    select route.path_valid_until
    from route_candidates as route

    union all

    select context_expires_value
    from current_permission as available
    where vortex_identity.resolve_active_vortex_super_administrator_assignment_internal(
      (p_context ->> 'identityId')::uuid, decision_checked_at
    ) is not null

    order by path_valid_until
    limit 1
  )
  select available.permission_entry, selected.path_valid_until
  from current_permission as available
  left join selected_route as selected on true;
end
$function$;


ALTER FUNCTION vortex_access.evaluate_permission_role_path_internal(p_context jsonb, p_checked_at timestamp with time zone, p_permission jsonb, p_action jsonb, p_record_type_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_permission_role_path_internal(p_context jsonb, p_checked_at timestamp with time zone, p_permission jsonb, p_action jsonb, p_record_type_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_permission_role_path_internal(p_context jsonb, p_checked_at timestamp with time zone, p_permission jsonb, p_action jsonb, p_record_type_id uuid) IS 'Private current-permission and role-path evidence; null record type selects only non-record permissions. No row authority.';


--
-- Name: evaluate_permission_saved_condition(jsonb, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.evaluate_permission_saved_condition(p_record_scope jsonb, p_saved_condition jsonb, p_source_record_type jsonb, p_field_values jsonb, p_current_organization_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  scope_condition jsonb;
  field_entry jsonb;
  field_id text;
  field_kind text;
  result_kind text;
  semantic_type text;
  field_types jsonb := '{}'::jsonb;
  declared_fields jsonb;
  declaration jsonb;
  binding jsonb;
  parameter_key text;
  parameter_type text;
  parameter_types jsonb := '{}'::jsonb;
  parameter_values jsonb := '{}'::jsonb;
  declaration_keys text[] := array[]::text[];
  binding_keys text[] := array[]::text[];
  key_count integer;
  tree_depth integer;
  tree_operands integer;
  supplied_key text;
  supplied_value jsonb;
  contract_version text;
  exact_values boolean;
  canonical_decimal constant text :=
    '^(?:(?:0|[1-9][0-9]*)(?:\.[0-9]*[1-9])?|-(?:0\.[0-9]*[1-9]|[1-9][0-9]*(?:\.[0-9]*[1-9])?))$';
begin
  if p_record_scope is null or pg_catalog.jsonb_typeof(p_record_scope) is distinct from 'object'
    or p_saved_condition is null or pg_catalog.jsonb_typeof(p_saved_condition) is distinct from 'object'
    or p_source_record_type is null or pg_catalog.jsonb_typeof(p_source_record_type) is distinct from 'object'
    or p_field_values is null or pg_catalog.jsonb_typeof(p_field_values) is distinct from 'object'
    or p_current_organization_account_id is null
    or p_current_organization_account_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  -- The evaluator selects semantics only from explicit trusted version
  -- evidence. Actual adapter facts below always carry the pinned version.
  contract_version := p_source_record_type ->> 'validationContractVersion';
  if not (p_source_record_type ? 'validationContractVersion')
    or pg_catalog.jsonb_typeof(p_source_record_type -> 'validationContractVersion') is distinct from 'string'
    or contract_version not in ('1.0.0', '2.0.0', '3.0.0') then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;
  exact_values := contract_version in ('2.0.0', '3.0.0');

  scope_condition := p_record_scope -> 'savedCondition';
  if pg_catalog.jsonb_typeof(scope_condition) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;
  select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(scope_condition);
  if key_count <> 4
    or pg_catalog.jsonb_typeof(scope_condition -> 'conditionId') is distinct from 'string'
    or not vortex_context.is_non_nil_uuid(scope_condition ->> 'conditionId')
    or pg_catalog.jsonb_typeof(scope_condition -> 'publishedRevision') is distinct from 'number'
    or (scope_condition ->> 'publishedRevision') !~ '^[1-9][0-9]*$'
    or (scope_condition ->> 'publishedRevision')::numeric > 9007199254740991
    or pg_catalog.jsonb_typeof(scope_condition -> 'contractFingerprint') is distinct from 'string'
    or (scope_condition ->> 'contractFingerprint') !~ '^sha256:[a-f0-9]{64}$'
    or pg_catalog.jsonb_typeof(scope_condition -> 'parameterBindings') is distinct from 'array' then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  if pg_catalog.jsonb_typeof(p_saved_condition -> 'conditionId') is distinct from 'string'
    or not vortex_context.is_non_nil_uuid(p_saved_condition ->> 'conditionId')
    or pg_catalog.jsonb_typeof(p_saved_condition -> 'sourceRecordTypeId') is distinct from 'string'
    or not vortex_context.is_non_nil_uuid(p_saved_condition ->> 'sourceRecordTypeId')
    or pg_catalog.jsonb_typeof(p_saved_condition -> 'publishedRevision') is distinct from 'number'
    or (p_saved_condition ->> 'publishedRevision') !~ '^[1-9][0-9]*$'
    or (p_saved_condition ->> 'publishedRevision')::numeric > 9007199254740991
    or pg_catalog.jsonb_typeof(p_saved_condition -> 'contractFingerprint') is distinct from 'string'
    or (p_saved_condition ->> 'contractFingerprint') !~ '^sha256:[a-f0-9]{64}$'
    or pg_catalog.jsonb_typeof(p_saved_condition -> 'parameters') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_saved_condition -> 'condition') is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_saved_condition -> 'declaredFieldIds') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_source_record_type -> 'recordTypeId') is distinct from 'string'
    or not vortex_context.is_non_nil_uuid(p_source_record_type ->> 'recordTypeId')
    or pg_catalog.jsonb_typeof(p_source_record_type -> 'fields') is distinct from 'array'
    or scope_condition ->> 'conditionId' <> p_saved_condition ->> 'conditionId'
    or (scope_condition ->> 'publishedRevision')::numeric <> (p_saved_condition ->> 'publishedRevision')::numeric
    or scope_condition ->> 'contractFingerprint' <> p_saved_condition ->> 'contractFingerprint'
    or p_saved_condition ->> 'sourceRecordTypeId' <> p_source_record_type ->> 'recordTypeId' then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  for field_entry in select value from pg_catalog.jsonb_array_elements(p_source_record_type -> 'fields') loop
    if pg_catalog.jsonb_typeof(field_entry) is distinct from 'object'
      or pg_catalog.jsonb_typeof(field_entry -> 'fieldId') is distinct from 'string'
      or not vortex_context.is_non_nil_uuid(field_entry ->> 'fieldId')
      or pg_catalog.jsonb_typeof(field_entry -> 'type') is distinct from 'string' then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    field_id := field_entry ->> 'fieldId';
    field_kind := field_entry ->> 'type';
    if field_types ? field_id then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    semantic_type := case
      when exact_values and field_kind = 'decimal_number' then 'decimal_number'
      when exact_values and field_kind = 'money' then 'money'
      when field_kind in ('whole_number', 'decimal_number', 'money') then 'number'
      when field_kind = 'yes_no' then 'boolean'
      when field_kind = 'date' then 'date'
      when field_kind = 'date_time' then 'date_time'
      when field_kind = 'several_choices' then 'text_collection'
      when field_kind in ('table', 'attachment') then 'opaque_json'
      when field_kind in ('link', 'link_to_one_of_several') then 'record_reference'
      when field_kind = 'link_to_person' then 'organization_account_reference'
      when field_kind in ('calculation', 'total') then null
      when field_kind in (
        'text', 'long_text', 'formatted_text', 'choice', 'reference_number',
        'email_address', 'phone_number', 'web_address'
      ) then 'text'
      else null end;
    if field_kind in ('calculation', 'total') then
      result_kind := field_entry #>> '{settings,resultType}';
      semantic_type := case
        when exact_values and result_kind = 'decimal_number' then 'decimal_number'
        when exact_values and result_kind = 'money' then 'money'
        when result_kind in ('whole_number', 'decimal_number', 'money') then 'number'
        when result_kind = 'yes_no' then 'boolean'
        when result_kind = 'date' then 'date'
        when result_kind = 'date_time' then 'date_time'
        when result_kind in ('text', 'choice') then 'text'
        else null end;
    end if;
    if semantic_type is null then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    field_types := field_types || pg_catalog.jsonb_build_object(field_id, semantic_type);
  end loop;

  declared_fields := '{}'::jsonb;
  for field_entry in select value from pg_catalog.jsonb_array_elements(p_saved_condition -> 'declaredFieldIds') loop
    if pg_catalog.jsonb_typeof(field_entry) is distinct from 'string'
      or not (field_types ? (field_entry #>> '{}'))
      or declared_fields ? (field_entry #>> '{}') then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    declared_fields := declared_fields || pg_catalog.jsonb_build_object(field_entry #>> '{}', true);
  end loop;

  select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(p_field_values);
  if key_count <> pg_catalog.jsonb_array_length(p_saved_condition -> 'declaredFieldIds') then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;
  for supplied_key, supplied_value in select key, value from pg_catalog.jsonb_each(p_field_values) loop
    semantic_type := field_types ->> supplied_key;
    if not (declared_fields ? supplied_key)
      or not vortex_access.typed_condition_value_matches_internal(supplied_value, semantic_type, true)
      or (
        supplied_value <> 'null'::jsonb and semantic_type = 'decimal_number'
        and (
          pg_catalog.jsonb_typeof(supplied_value) <> 'string'
          or (supplied_value #>> '{}') !~ canonical_decimal
        )
      ) then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
  end loop;

  for declaration in select value from pg_catalog.jsonb_array_elements(p_saved_condition -> 'parameters') loop
    if pg_catalog.jsonb_typeof(declaration) is distinct from 'object' then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(declaration);
    parameter_key := declaration ->> 'key';
    parameter_type := declaration ->> 'type';
    if key_count <> 2
      or parameter_key !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
      or pg_catalog.length(parameter_key) > 40
      or parameter_type is null
      or not (
        parameter_type in (
          'text', 'number', 'boolean', 'date', 'date_time', 'organization_account_reference'
        )
        or (exact_values and parameter_type in ('decimal_number', 'money'))
      )
      or parameter_types ? parameter_key then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    parameter_types := parameter_types || pg_catalog.jsonb_build_object(parameter_key, parameter_type);
    declaration_keys := pg_catalog.array_append(declaration_keys, parameter_key);
  end loop;

  for binding in select value from pg_catalog.jsonb_array_elements(scope_condition -> 'parameterBindings') loop
    if pg_catalog.jsonb_typeof(binding) is distinct from 'object' then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(binding);
    parameter_key := binding ->> 'key';
    parameter_type := parameter_types ->> parameter_key;
    if parameter_key is null or not (parameter_types ? parameter_key) or parameter_key = any(binding_keys) then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    if binding ->> 'source' = 'current_organization_account_id' then
      if key_count <> 2 or parameter_type not in ('text', 'organization_account_reference') then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
      parameter_values := parameter_values || pg_catalog.jsonb_build_object(
        parameter_key, p_current_organization_account_id::text
      );
    elsif binding ->> 'source' = 'literal' then
      if key_count <> 3 or not (binding ? 'value')
        or not vortex_access.typed_condition_value_matches_internal(binding -> 'value', parameter_type, false)
        or (parameter_type = 'decimal_number' and (
          pg_catalog.jsonb_typeof(binding -> 'value') <> 'string'
          or (binding ->> 'value') !~ canonical_decimal
        )) then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
      parameter_values := parameter_values || pg_catalog.jsonb_build_object(parameter_key, binding -> 'value');
    else
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    binding_keys := pg_catalog.array_append(binding_keys, parameter_key);
  end loop;
  if pg_catalog.cardinality(declaration_keys) <> pg_catalog.cardinality(binding_keys)
    or exists (
      select 1 from pg_catalog.unnest(declaration_keys) as declared(key)
      where not (declared.key = any(binding_keys))
    ) then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  with recursive nodes(node, depth) as (
    select p_saved_condition -> 'condition', 1
    union all
    select children.child, nodes.depth + 1
    from nodes
    cross join lateral (
      select child.value as child
      from pg_catalog.jsonb_array_elements(case
        when nodes.node ->> 'kind' in ('all', 'any')
          and pg_catalog.jsonb_typeof(nodes.node -> 'conditions') = 'array'
          then nodes.node -> 'conditions' else '[]'::jsonb end) as child(value)
      union all
      select nodes.node -> 'condition'
      where nodes.node ->> 'kind' = 'not'
        and pg_catalog.jsonb_typeof(nodes.node -> 'condition') = 'object'
    ) as children
  )
  select pg_catalog.max(depth), pg_catalog.sum(case when node ->> 'kind' = 'comparison'
    then case when node ->> 'operator' in ('is_empty', 'is_not_empty') then 1 else 2 end else 0 end)::integer
  into tree_depth, tree_operands from nodes;
  if tree_depth > 10 or tree_operands > 100 then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  perform vortex_access.evaluate_typed_condition_node_internal(
    p_saved_condition -> 'condition', field_types, p_field_values,
    parameter_types, parameter_values, true
  );
  return vortex_access.evaluate_typed_condition_node_internal(
    p_saved_condition -> 'condition', field_types, p_field_values,
    parameter_types, parameter_values, false
  );
exception
  when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
end
$_$;


ALTER FUNCTION vortex_access.evaluate_permission_saved_condition(p_record_scope jsonb, p_saved_condition jsonb, p_source_record_type jsonb, p_field_values jsonb, p_current_organization_account_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_permission_saved_condition(p_record_scope jsonb, p_saved_condition jsonb, p_source_record_type jsonb, p_field_values jsonb, p_current_organization_account_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_permission_saved_condition(p_record_scope jsonb, p_saved_condition jsonb, p_source_record_type jsonb, p_field_values jsonb, p_current_organization_account_id uuid) IS 'Owner-only pure predicate for one sealed permission saved condition over trusted versioned record values and a protected current organization account.';


--
-- Name: evaluate_query_condition_internal(jsonb, jsonb, jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.evaluate_query_condition_internal(p_condition jsonb, p_field_types jsonb, p_field_values jsonb, p_parameter_types jsonb, p_parameter_values jsonb, p_validate_only boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  entry record;
begin
  if pg_catalog.jsonb_typeof(p_condition) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_field_types) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_field_values) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_parameter_types) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_parameter_values) is distinct from 'object'
    or p_validate_only is null then
    raise exception using errcode = '22023', message = 'Query condition is invalid';
  end if;

  for entry in select item.key, item.value from pg_catalog.jsonb_each(p_field_values) as item loop
    if not (p_field_types ? entry.key)
      or not vortex_access.typed_condition_value_matches_internal(
        entry.value, p_field_types ->> entry.key, true
      ) then
      raise exception using errcode = '22023', message = 'Query condition is invalid';
    end if;
  end loop;

  -- Every declared parameter is bound, as JSON null when it is optional and
  -- absent; a supplied value must match its declared type exactly.
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(p_parameter_types) as declared(key)
    where not (p_parameter_values ? declared.key)
  ) then
    raise exception using errcode = '22023', message = 'Query condition is invalid';
  end if;
  for entry in select item.key, item.value from pg_catalog.jsonb_each(p_parameter_values) as item loop
    if not (p_parameter_types ? entry.key)
      or not vortex_access.typed_condition_value_matches_internal(
        entry.value, p_parameter_types ->> entry.key, true
      )
      or (
        p_parameter_types ->> entry.key = 'decimal_number'
        and entry.value <> 'null'::jsonb
        and pg_catalog.jsonb_typeof(entry.value) <> 'string'
      ) then
      raise exception using errcode = '22023', message = 'Query condition is invalid';
    end if;
  end loop;

  return vortex_access.evaluate_typed_condition_node_internal(
    p_condition, p_field_types, p_field_values, p_parameter_types, p_parameter_values,
    p_validate_only
  );
exception
  when invalid_text_representation or numeric_value_out_of_range
    or invalid_datetime_format or datetime_field_overflow then
    raise exception using errcode = '22023', message = 'Query condition is invalid';
end
$$;


ALTER FUNCTION vortex_access.evaluate_query_condition_internal(p_condition jsonb, p_field_types jsonb, p_field_values jsonb, p_parameter_types jsonb, p_parameter_values jsonb, p_validate_only boolean) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_query_condition_internal(p_condition jsonb, p_field_types jsonb, p_field_values jsonb, p_parameter_types jsonb, p_parameter_values jsonb, p_validate_only boolean); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_query_condition_internal(p_condition jsonb, p_field_types jsonb, p_field_values jsonb, p_parameter_types jsonb, p_parameter_values jsonb, p_validate_only boolean) IS 'Private bridge from the Query reader to the typed condition engine; checks bound values against their declared semantic types and never widens a condition.';


--
-- Name: evaluate_record_permission_row_scope_internal(jsonb, timestamp with time zone, timestamp with time zone, uuid, jsonb, jsonb, uuid, jsonb, uuid[]); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.evaluate_record_permission_row_scope_internal(
  p_context jsonb,
  p_checked_at timestamptz,
  p_auth_deadline timestamptz,
  p_application_root_id uuid,
  p_action jsonb,
  p_candidate jsonb,
  p_record_id uuid,
  p_facts jsonb,
  p_path uuid[]
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  context_organization_id uuid := (p_context ->> 'organizationId')::uuid;
  context_account_id uuid := (p_context ->> 'organizationAccountId')::uuid;
  action_kind text := p_action ->> 'actionKind';
  candidate_permission jsonb := p_candidate -> 'permission';
  candidate_record_scope jsonb := p_candidate -> 'recordScope';
  candidate_valid_until timestamptz := (p_candidate ->> 'validUntil')::timestamptz;
  target_record jsonb;
  target_record_scope jsonb;
  target_type jsonb;
  has_all_records boolean;
  has_ownership boolean;
  has_direct_share boolean;
  route_list jsonb[] := array[]::jsonb[];
  deadline_list timestamptz[] := array[]::timestamptz[];
  ownership_admitted boolean;
  ownership_deadline timestamptz;
  chase_record jsonb;
  chase_scope jsonb;
  chase_type jsonb;
  chase_relationship jsonb;
  chase_edge jsonb;
  chase_edge_count integer;
  chase_target jsonb;
  parent_record jsonb;
  parent_scope jsonb;
  parent_type jsonb;
  visited_ids uuid[];
  chase_admitted boolean;
  chase_deadline timestamptz;
  share_row record;
  route jsonb;
  relationship_decl jsonb;
  source_owner_kind text;
  source_owner_id uuid;
  source_eval record;
  source_permission_entry vortex_access.permission_catalogue_entries;
  source_path_valid_until timestamptz;
  source_valid_until timestamptz;
  source_candidate jsonb;
  source_record jsonb;
  source_record_scope jsonb;
  edge_item jsonb;
  sub_result jsonb;
  sub_min_valid_until timestamptz;
  contribution_deadline timestamptz;
  condition_id uuid;
  saved_condition jsonb;
  projected_values jsonb;
  declared_field jsonb;
  reduced_type jsonb;
  condition_ok boolean;
  result jsonb;
begin
  select value into target_record
  from pg_catalog.jsonb_array_elements(p_facts -> 'records') as item(value)
  where (value -> 'recordScope' ->> 'recordId')::uuid = p_record_id
  limit 1;

  if target_record is null or target_record ->> 'lifecycleState' <> 'active' then
    return '[]'::jsonb;
  end if;

  target_record_scope := target_record -> 'recordScope';

  select value into target_type
  from pg_catalog.jsonb_array_elements(p_facts -> 'recordTypes') as item(value)
  where (value ->> 'recordTypeId')::uuid = (target_record_scope ->> 'recordTypeId')::uuid
  limit 1;

  if target_type is null then
    return '[]'::jsonb;
  end if;

  has_all_records := exists (
    select 1 from pg_catalog.jsonb_array_elements(candidate_record_scope -> 'routes') as item(value)
    where item.value ->> 'kind' = 'all_records'
  );
  has_ownership := exists (
    select 1 from pg_catalog.jsonb_array_elements(candidate_record_scope -> 'routes') as item(value)
    where item.value ->> 'kind' = 'ownership'
  );
  has_direct_share := exists (
    select 1 from pg_catalog.jsonb_array_elements(candidate_record_scope -> 'routes') as item(value)
    where item.value ->> 'kind' = 'direct_share'
  );

  -- Step 2: base ownership/all-record routes, then inherited-ownership chase.
  if has_all_records or has_ownership then
    select outcome.admitted, outcome.valid_until into ownership_admitted, ownership_deadline
    from vortex_access.evaluate_current_record_ownership_visibility(
      candidate_record_scope,
      target_type ->> 'ownershipMode',
      context_organization_id,
      p_application_root_id,
      (target_type ->> 'moduleRootId')::uuid,
      (target_type ->> 'recordTypeId')::uuid,
      (target_type ->> 'storageContractId')::uuid,
      target_type ->> 'storageScope',
      target_record_scope,
      (target_record ->> 'ownerOrganizationAccountId')::uuid,
      (target_record ->> 'ownerGroupId')::uuid,
      context_organization_id,
      p_application_root_id,
      context_account_id,
      p_checked_at
    ) as outcome;

    if ownership_admitted then
      route_list := pg_catalog.array_append(route_list, pg_catalog.jsonb_build_object(
        'kind', case when has_all_records then 'all_records' else 'ownership' end
      ));
      deadline_list := pg_catalog.array_append(deadline_list, ownership_deadline);
    elsif has_ownership and target_type ->> 'ownershipMode' = 'inherited' then
      chase_record := target_record;
      chase_scope := target_record_scope;
      chase_type := target_type;
      visited_ids := array[(target_record_scope ->> 'recordId')::uuid];

      while chase_type ->> 'ownershipMode' = 'inherited' loop
        select value into chase_relationship
        from pg_catalog.jsonb_array_elements(p_facts -> 'relationships') as item(value)
        where (value ->> 'relationshipId')::uuid = (chase_type ->> 'ownershipRelationshipId')::uuid
        limit 1;

        exit when chase_relationship is null;

        select pg_catalog.count(*) into chase_edge_count
        from pg_catalog.jsonb_array_elements(p_facts -> 'edges') as item(value)
        where (value ->> 'relationshipId')::uuid = (chase_relationship ->> 'relationshipId')::uuid
          and (value ->> 'fromRecordId')::uuid = (chase_scope ->> 'recordId')::uuid;

        exit when chase_edge_count <> 1;

        select value into chase_edge
        from pg_catalog.jsonb_array_elements(p_facts -> 'edges') as item(value)
        where (value ->> 'relationshipId')::uuid = (chase_relationship ->> 'relationshipId')::uuid
          and (value ->> 'fromRecordId')::uuid = (chase_scope ->> 'recordId')::uuid
        limit 1;

        select value into parent_record
        from pg_catalog.jsonb_array_elements(p_facts -> 'records') as item(value)
        where (value -> 'recordScope' ->> 'recordId')::uuid = (chase_edge ->> 'toRecordId')::uuid
        limit 1;

        exit when parent_record is null or parent_record ->> 'lifecycleState' <> 'active';

        parent_scope := parent_record -> 'recordScope';

        select value into parent_type
        from pg_catalog.jsonb_array_elements(p_facts -> 'recordTypes') as item(value)
        where (value ->> 'recordTypeId')::uuid = (parent_scope ->> 'recordTypeId')::uuid
        limit 1;

        exit when parent_type is null;

        select item.value into chase_target
        from pg_catalog.jsonb_array_elements(chase_relationship -> 'toRecordTypes') as item(value)
        where pg_catalog.lower(item.value ->> 'moduleRootId') =
            pg_catalog.lower(parent_scope ->> 'moduleRootId')
          and pg_catalog.lower(item.value ->> 'recordTypeId') =
            pg_catalog.lower(parent_scope ->> 'recordTypeId')
        limit 1;

        exit when chase_target is null;

        exit when not vortex_access.record_relationship_witness_matches(
          (chase_relationship ->> 'relationshipId')::uuid,
          (chase_relationship ->> 'fromModuleRootId')::uuid,
          (chase_relationship ->> 'fromRecordTypeId')::uuid,
          (chase_target ->> 'moduleRootId')::uuid,
          (chase_target ->> 'recordTypeId')::uuid,
          (chase_edge ->> 'relationshipId')::uuid,
          (chase_edge ->> 'fromRecordId')::uuid,
          (chase_edge ->> 'toRecordId')::uuid,
          chase_scope,
          parent_scope,
          context_organization_id,
          p_application_root_id
        );

        exit when (parent_scope ->> 'recordId')::uuid = any(visited_ids);

        visited_ids := pg_catalog.array_append(visited_ids, (parent_scope ->> 'recordId')::uuid);
        chase_record := parent_record;
        chase_scope := parent_scope;
        chase_type := parent_type;
      end loop;

      if chase_type ->> 'ownershipMode' in ('organization_account', 'group') then
        select outcome.admitted, outcome.valid_until into chase_admitted, chase_deadline
        from vortex_access.evaluate_current_record_ownership_visibility(
          '{"routes":[{"kind":"ownership"}]}'::jsonb,
          chase_type ->> 'ownershipMode',
          context_organization_id,
          p_application_root_id,
          (chase_type ->> 'moduleRootId')::uuid,
          (chase_type ->> 'recordTypeId')::uuid,
          (chase_type ->> 'storageContractId')::uuid,
          chase_type ->> 'storageScope',
          chase_scope,
          (chase_record ->> 'ownerOrganizationAccountId')::uuid,
          (chase_record ->> 'ownerGroupId')::uuid,
          context_organization_id,
          p_application_root_id,
          context_account_id,
          p_checked_at
        ) as outcome;

        if chase_admitted then
          route_list := pg_catalog.array_append(route_list, pg_catalog.jsonb_build_object('kind', 'ownership'));
          deadline_list := pg_catalog.array_append(deadline_list, chase_deadline);
        end if;
      end if;
    end if;
  end if;

  -- Step 3: direct share, read/update only, each recipient contributing
  -- independently with its own field bounds.
  if has_direct_share and action_kind in ('read', 'update') then
    for share_row in
      select *
      from vortex_access.read_current_direct_record_share_contributions(
        context_organization_id,
        p_application_root_id,
        (target_type ->> 'moduleRootId')::uuid,
        (target_type ->> 'recordTypeId')::uuid,
        (target_type ->> 'storageContractId')::uuid,
        target_type ->> 'storageScope',
        p_record_id,
        context_organization_id,
        p_application_root_id,
        context_account_id,
        p_checked_at
      )
    loop
      if action_kind = 'update' and pg_catalog.cardinality(share_row.changeable_field_ids) = 0 then
        continue;
      end if;
      route_list := pg_catalog.array_append(route_list, pg_catalog.jsonb_build_object(
        'kind', 'direct_share',
        'directShareId', share_row.direct_share_id,
        'directShareRevision', share_row.direct_share_revision,
        'readableFieldIds', pg_catalog.to_jsonb(share_row.readable_field_ids),
        'changeableFieldIds', pg_catalog.to_jsonb(share_row.changeable_field_ids)
      ));
      deadline_list := pg_catalog.array_append(deadline_list, share_row.valid_until);
    end loop;
  end if;

  -- Step 4: relationship routes. The target record is always the relationship's
  -- `to` endpoint and the source record its `from` endpoint (see
  -- runtime/definition/src/validation.ts). Every recursive step re-evaluates
  -- the source permission's own eligibility and own complete scope; authority
  -- never crosses alternatives.
  for route in
    select value from pg_catalog.jsonb_array_elements(candidate_record_scope -> 'routes') as item(value)
    where value ->> 'kind' = 'relationship'
  loop
    select value into relationship_decl
    from pg_catalog.jsonb_array_elements(p_facts -> 'relationships') as item(value)
    where (value ->> 'relationshipId')::uuid = (route ->> 'relationshipId')::uuid
    limit 1;

    if relationship_decl is null
      or not exists (
        select 1
        from pg_catalog.jsonb_array_elements(relationship_decl -> 'toRecordTypes') as declared(value)
        where pg_catalog.lower(declared.value ->> 'moduleRootId') = pg_catalog.lower(target_type ->> 'moduleRootId')
          and pg_catalog.lower(declared.value ->> 'recordTypeId') = pg_catalog.lower(target_type ->> 'recordTypeId')
      ) then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    if (route ->> 'sourcePermissionId')::uuid = any(p_path) then
      continue;
    end if;

    begin
      select entry.owner_kind, entry.owner_id
      into strict source_owner_kind, source_owner_id
      from vortex_access.permission_catalogue_entries as entry
      join vortex_access.permission_registrations as registration
        on registration.organization_id = entry.organization_id
        and registration.registration_kind = entry.registration_kind
        and registration.registration_owner_id = entry.registration_owner_id
        and registration.revision = entry.registration_revision
        and registration.state = 'active'
      where entry.organization_id = context_organization_id
        and entry.application_root_id = p_application_root_id
        and entry.permission_id = (route ->> 'sourcePermissionId')::uuid
        and entry.record_type_id = (relationship_decl ->> 'fromRecordTypeId')::uuid
        and entry.action_kind = 'read'
        and entry.named_action is null;
    exception
      when no_data_found or too_many_rows then
        continue;
    end;

    source_eval := null;
    select evaluated.permission_entry, evaluated.path_valid_until
    into source_eval
    from vortex_access.evaluate_permission_role_path_internal(
      p_context,
      p_checked_at,
      pg_catalog.jsonb_build_object(
        'applicationRootId', p_application_root_id,
        'ownerKind', source_owner_kind,
        'ownerId', source_owner_id,
        'permissionId', (route ->> 'sourcePermissionId')::uuid
      ),
      pg_catalog.jsonb_build_object('actionKind', 'read'),
      (relationship_decl ->> 'fromRecordTypeId')::uuid
    ) as evaluated
    limit 1;

    if source_eval is null or (source_eval.permission_entry).record_scope is null
      or source_eval.path_valid_until is null or p_auth_deadline is null then
      continue;
    end if;
    source_permission_entry := source_eval.permission_entry;
    source_path_valid_until := source_eval.path_valid_until;
    source_valid_until := least(source_path_valid_until, p_auth_deadline);

    source_candidate := pg_catalog.jsonb_build_object(
      'permission', pg_catalog.jsonb_build_object(
        'applicationRootId', p_application_root_id,
        'ownerKind', source_owner_kind,
        'ownerId', source_owner_id,
        'permissionId', (route ->> 'sourcePermissionId')::uuid
      ),
      'recordScope', (source_permission_entry).record_scope,
      'source', pg_catalog.jsonb_build_object(
        'kind', (source_permission_entry).source_kind,
        'definitionKey', (source_permission_entry).source_definition_key,
        'rootId', (source_permission_entry).source_root_id,
        'releaseRevision', (source_permission_entry).source_revision,
        'releaseVersion', (source_permission_entry).source_version,
        'validationContractVersion', (source_permission_entry).source_validation_contract_version,
        'contentFingerprint', (source_permission_entry).source_content_fingerprint,
        'resolutionFingerprint', (source_permission_entry).source_resolution_fingerprint
      ),
      'validUntil', pg_catalog.to_char(
        pg_catalog.timezone('UTC', source_valid_until), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    );

    for edge_item in
      select value from pg_catalog.jsonb_array_elements(p_facts -> 'edges') as item(value)
      where (value ->> 'relationshipId')::uuid = (relationship_decl ->> 'relationshipId')::uuid
        and (value ->> 'toRecordId')::uuid = p_record_id
    loop
      select value into source_record
      from pg_catalog.jsonb_array_elements(p_facts -> 'records') as item(value)
      where (value -> 'recordScope' ->> 'recordId')::uuid = (edge_item ->> 'fromRecordId')::uuid
      limit 1;

      if source_record is null or source_record ->> 'lifecycleState' <> 'active' then
        continue;
      end if;
      source_record_scope := source_record -> 'recordScope';

      if pg_catalog.lower(source_record_scope ->> 'recordTypeId')
        <> pg_catalog.lower(relationship_decl ->> 'fromRecordTypeId') then
        continue;
      end if;

      if not vortex_access.record_relationship_witness_matches(
        (relationship_decl ->> 'relationshipId')::uuid,
        (relationship_decl ->> 'fromModuleRootId')::uuid,
        (relationship_decl ->> 'fromRecordTypeId')::uuid,
        (target_type ->> 'moduleRootId')::uuid,
        (target_type ->> 'recordTypeId')::uuid,
        (edge_item ->> 'relationshipId')::uuid,
        (edge_item ->> 'fromRecordId')::uuid,
        (edge_item ->> 'toRecordId')::uuid,
        source_record_scope,
        target_record_scope,
        context_organization_id,
        p_application_root_id
      ) then
        continue;
      end if;

      sub_result := vortex_access.evaluate_record_permission_row_scope_internal(
        p_context,
        p_checked_at,
        p_auth_deadline,
        p_application_root_id,
        pg_catalog.jsonb_build_object('actionKind', 'read'),
        source_candidate,
        (edge_item ->> 'fromRecordId')::uuid,
        p_facts,
        pg_catalog.array_append(p_path, (route ->> 'sourcePermissionId')::uuid)
      );

      if pg_catalog.jsonb_array_length(sub_result) > 0 then
        select pg_catalog.min((elem.value ->> 'validUntil')::timestamptz) into sub_min_valid_until
        from pg_catalog.jsonb_array_elements(sub_result) as elem(value);

        contribution_deadline := least(source_valid_until, sub_min_valid_until);

        route_list := pg_catalog.array_append(route_list, pg_catalog.jsonb_build_object(
          'kind', 'relationship',
          'relationshipId', (route ->> 'relationshipId')::uuid,
          'sourcePermissionId', (route ->> 'sourcePermissionId')::uuid,
          'sourceRecordId', (edge_item ->> 'fromRecordId')::uuid
        ));
        deadline_list := pg_catalog.array_append(deadline_list, contribution_deadline);
      end if;
    end loop;
  end loop;

  -- Step 5: a saved condition narrows every route, including all_records.
  if coalesce(pg_catalog.array_length(route_list, 1), 0) > 0
    and candidate_record_scope ? 'savedCondition' then
    condition_id := (candidate_record_scope -> 'savedCondition' ->> 'conditionId')::uuid;

    select value into saved_condition
    from pg_catalog.jsonb_array_elements(p_facts -> 'sharingConditions') as item(value)
    where (value ->> 'conditionId')::uuid = condition_id
    limit 1;

    if saved_condition is null then
      raise exception using errcode = '22023', message = 'Record access facts are invalid';
    end if;

    projected_values := '{}'::jsonb;
    for declared_field in
      select value from pg_catalog.jsonb_array_elements(saved_condition -> 'declaredFieldIds') as item(value)
    loop
      if not ((target_record -> 'fieldValues') ? (declared_field #>> '{}')) then
        raise exception using errcode = '22023', message = 'Record access facts are invalid';
      end if;
      projected_values := projected_values || pg_catalog.jsonb_build_object(
        declared_field #>> '{}', (target_record -> 'fieldValues') -> (declared_field #>> '{}')
      );
    end loop;

    reduced_type := pg_catalog.jsonb_build_object(
      'recordTypeId', target_type -> 'recordTypeId',
      'fields', target_type -> 'fields'
    ) || case
      when target_type ? 'validationContractVersion' then
        pg_catalog.jsonb_build_object(
          'validationContractVersion', target_type -> 'validationContractVersion'
        )
      else '{}'::jsonb
    end;

    condition_ok := vortex_access.evaluate_permission_saved_condition(
      candidate_record_scope, saved_condition, reduced_type, projected_values, context_account_id
    );

    if condition_ok is not true then
      route_list := array[]::jsonb[];
      deadline_list := array[]::timestamptz[];
    end if;
  end if;

  -- Step 6: map to full matched contributions for this candidate.
  result := '[]'::jsonb;
  for route_index in 1 .. coalesce(pg_catalog.array_length(route_list, 1), 0) loop
    result := result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'permission', candidate_permission,
      'recordScope', candidate_record_scope,
      'source', p_candidate -> 'source',
      'route', route_list[route_index],
      'validUntil', pg_catalog.to_char(
        pg_catalog.timezone('UTC', least(candidate_valid_until, deadline_list[route_index])),
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    ));
  end loop;

  return result;
end
$function$;


ALTER FUNCTION vortex_access.evaluate_record_permission_row_scope_internal(p_context jsonb, p_checked_at timestamp with time zone, p_auth_deadline timestamp with time zone, p_application_root_id uuid, p_action jsonb, p_candidate jsonb, p_record_id uuid, p_facts jsonb, p_path uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION evaluate_record_permission_row_scope_internal(p_context jsonb, p_checked_at timestamp with time zone, p_auth_deadline timestamp with time zone, p_application_root_id uuid, p_action jsonb, p_candidate jsonb, p_record_id uuid, p_facts jsonb, p_path uuid[]); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.evaluate_record_permission_row_scope_internal(p_context jsonb, p_checked_at timestamp with time zone, p_auth_deadline timestamp with time zone, p_application_root_id uuid, p_action jsonb, p_candidate jsonb, p_record_id uuid, p_facts jsonb, p_path uuid[]) IS 'Private row-scope composition for one already-eligible permission against one exact record; returns matched contributions only, never a final allow/refuse result.';


--
-- Name: evaluate_typed_condition_node_internal(jsonb, jsonb, jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.evaluate_typed_condition_node_internal(p_condition jsonb, p_field_types jsonb, p_field_values jsonb, p_parameter_types jsonb, p_parameter_values jsonb, p_validate_only boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  node_kind text;
  operator_value text;
  child jsonb;
  child_result boolean;
  combined_result boolean;
  operand_count integer;
  operand_entry jsonb;
  operand_source text;
  operand_key text;
  operand_types text[] := array[null::text, null::text];
  operand_values jsonb[] := array[null::jsonb, null::jsonb];
  operand_typed boolean[] := array[false, false];
  operand_literal boolean[] := array[false, false];
  shared_type text;
  expected_type text;
  collection_element_type text;
  candidate_type text;
  member jsonb;
  member_type text;
  collection_valid boolean;
  contains_value boolean;
  equal_value boolean;
  comparison_value integer;
  left_number double precision;
  right_number double precision;
  key_count integer;
  exact_compatible boolean;
begin
  if p_condition is null or pg_catalog.jsonb_typeof(p_condition) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;
  node_kind := p_condition ->> 'kind';

  if node_kind in ('all', 'any') then
    select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(p_condition);
    if key_count <> 2
      or pg_catalog.jsonb_typeof(p_condition -> 'conditions') is distinct from 'array'
      or pg_catalog.jsonb_array_length(p_condition -> 'conditions') not between 1 and 50 then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    combined_result := node_kind = 'all';
    for child in select value from pg_catalog.jsonb_array_elements(p_condition -> 'conditions') loop
      child_result := vortex_access.evaluate_typed_condition_node_internal(
        child, p_field_types, p_field_values, p_parameter_types, p_parameter_values, p_validate_only
      );
      combined_result := case when node_kind = 'all'
        then combined_result and child_result else combined_result or child_result end;
    end loop;
    return case when p_validate_only then true else combined_result end;
  elsif node_kind = 'not' then
    select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(p_condition);
    if key_count <> 2
      or pg_catalog.jsonb_typeof(p_condition -> 'condition') is distinct from 'object' then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
    child_result := vortex_access.evaluate_typed_condition_node_internal(
      p_condition -> 'condition', p_field_types, p_field_values,
      p_parameter_types, p_parameter_values, p_validate_only
    );
    return case when p_validate_only then true else not child_result end;
  elsif node_kind is distinct from 'comparison' then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  operator_value := p_condition ->> 'operator';
  if operator_value is null or operator_value not in (
    'equals', 'not_equals', 'contains', 'not_contains', 'in', 'not_in',
    'greater_than', 'greater_than_or_equal', 'less_than', 'less_than_or_equal',
    'is_empty', 'is_not_empty'
  ) then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;
  operand_count := case when operator_value in ('is_empty', 'is_not_empty') then 1 else 2 end;
  select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(p_condition);
  if key_count <> (case when operand_count = 1 then 3 else 4 end)
    or pg_catalog.jsonb_typeof(p_condition -> 'left') is distinct from 'object'
    or (operand_count = 1 and p_condition ? 'right')
    or (operand_count = 2 and pg_catalog.jsonb_typeof(p_condition -> 'right') is distinct from 'object') then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  for operand_index in 1..operand_count loop
    operand_entry := case when operand_index = 1 then p_condition -> 'left' else p_condition -> 'right' end;
    operand_source := operand_entry ->> 'source';
    select pg_catalog.count(*) into key_count from pg_catalog.jsonb_object_keys(operand_entry);
    if operand_source = 'field' then
      operand_key := operand_entry ->> 'fieldId';
      if key_count <> 2 or operand_key is null or not (p_field_types ? operand_key)
        or not (p_field_values ? operand_key) then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
      operand_types[operand_index] := p_field_types ->> operand_key;
      operand_values[operand_index] := p_field_values -> operand_key;
      operand_typed[operand_index] := true;
    elsif operand_source = 'parameter' then
      operand_key := operand_entry ->> 'key';
      if key_count <> 2 or operand_key is null or not (p_parameter_types ? operand_key)
        or not (p_parameter_values ? operand_key) then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
      operand_types[operand_index] := p_parameter_types ->> operand_key;
      operand_values[operand_index] := p_parameter_values -> operand_key;
      operand_typed[operand_index] := true;
    elsif operand_source = 'value' then
      if key_count <> 2 or not (operand_entry ? 'value') then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
      operand_values[operand_index] := operand_entry -> 'value';
      operand_literal[operand_index] := true;
      if operand_values[operand_index] <> 'null'::jsonb then
        case pg_catalog.jsonb_typeof(operand_values[operand_index])
          when 'number' then candidate_type := 'number';
          when 'boolean' then candidate_type := 'boolean';
          when 'string' then
            if vortex_access.typed_condition_temporal_value_internal(
              operand_values[operand_index] #>> '{}', 'date'
            ) is not null then candidate_type := 'date';
            elsif vortex_access.typed_condition_temporal_value_internal(
              operand_values[operand_index] #>> '{}', 'date_time'
            ) is not null then candidate_type := 'date_time';
            else candidate_type := 'text'; end if;
          when 'array' then
            if not exists (
              select 1 from pg_catalog.jsonb_array_elements(operand_values[operand_index]) as element(value)
              where pg_catalog.jsonb_typeof(element.value) is distinct from 'string'
            ) then candidate_type := 'text_collection'; else candidate_type := 'opaque_json'; end if;
          else candidate_type := 'opaque_json';
        end case;
        if not vortex_access.typed_condition_value_matches_internal(
          operand_values[operand_index], candidate_type, true
        ) then
          raise exception using errcode = '22023', message = 'Typed record condition is invalid';
        end if;
        operand_types[operand_index] := candidate_type;
      end if;
    else
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
  end loop;

  if operand_count = 1 then
    return case when p_validate_only then true
      when operator_value = 'is_empty' then operand_values[1] = 'null'::jsonb or operand_values[1] = '""'::jsonb
      else operand_values[1] <> 'null'::jsonb and operand_values[1] <> '""'::jsonb end;
  end if;

  if operand_typed[1] and operand_typed[2] then
    if operand_types[1] = operand_types[2] then shared_type := operand_types[1]; end if;
  elsif operand_typed[1] then
    if operand_literal[2] and vortex_access.typed_condition_value_matches_internal(
      operand_values[2], operand_types[1], true
    ) then shared_type := operand_types[1]; end if;
  elsif operand_typed[2] then
    if operand_literal[1] and vortex_access.typed_condition_value_matches_internal(
      operand_values[1], operand_types[2], true
    ) then shared_type := operand_types[2]; end if;
  elsif operand_values[1] = 'null'::jsonb and operand_values[2] = 'null'::jsonb then
    shared_type := 'opaque_json';
  elsif operand_values[1] = 'null'::jsonb then shared_type := operand_types[2];
  elsif operand_values[2] = 'null'::jsonb then shared_type := operand_types[1];
  elsif operand_types[1] = operand_types[2] then shared_type := operand_types[1];
  end if;

  -- V2 decimal operands may pair with whole JSON-number literals or legacy
  -- number parameters only when those values are integers, exactly as the
  -- TypeScript V2 evaluator lifts them into exact base ten.
  if shared_type is null
    and operand_types[1] in ('number', 'decimal_number')
    and operand_types[2] in ('number', 'decimal_number') then
    exact_compatible := true;
    for operand_index in 1..2 loop
      if operand_values[operand_index] <> 'null'::jsonb
        and not vortex_access.typed_condition_value_matches_internal(
          operand_values[operand_index], 'decimal_number', true
        ) then
        exact_compatible := false;
      end if;
    end loop;
    if exact_compatible then shared_type := 'decimal_number'; end if;
  end if;

  if operator_value in ('contains', 'not_contains', 'in', 'not_in') then
    if operator_value in ('contains', 'not_contains') then
      if vortex_access.typed_condition_value_matches_internal(operand_values[1], 'text', true)
        and vortex_access.typed_condition_value_matches_internal(operand_values[2], 'text', true)
        and (operand_types[1] is null or operand_types[1] = 'text')
        and (operand_types[2] is null or operand_types[2] = 'text') then
        collection_element_type := null;
      elsif operand_typed[1] and operand_types[1] = 'text_collection' then
        collection_element_type := 'text';
      elsif operand_literal[1] and pg_catalog.jsonb_typeof(operand_values[1]) = 'array' then
        expected_type := case when operand_typed[2] then operand_types[2] else null end;
        collection_valid := true;
        member_type := null;
        for member in select value from pg_catalog.jsonb_array_elements(operand_values[1]) loop
          if expected_type is not null then
            if expected_type in ('text_collection', 'opaque_json')
              or not vortex_access.typed_condition_value_matches_internal(member, expected_type, true) then
              collection_valid := false;
            else member_type := expected_type; end if;
          else
            candidate_type := case pg_catalog.jsonb_typeof(member)
              when 'number' then 'number' when 'boolean' then 'boolean'
              when 'string' then case
                when vortex_access.typed_condition_temporal_value_internal(member #>> '{}', 'date') is not null then 'date'
                when vortex_access.typed_condition_temporal_value_internal(member #>> '{}', 'date_time') is not null then 'date_time'
                else 'text' end else null end;
            if candidate_type is null or candidate_type in ('text_collection', 'opaque_json')
              or (member_type is not null and member_type <> candidate_type) then collection_valid := false;
            else member_type := candidate_type; end if;
          end if;
        end loop;
        if pg_catalog.jsonb_array_length(operand_values[1]) = 0 then
          member_type := case when expected_type not in ('text_collection', 'opaque_json') then expected_type else null end;
        end if;
        if collection_valid then collection_element_type := member_type; end if;
      end if;
      if ((collection_element_type is null and shared_type = 'text') or (
        collection_element_type is not null
        and vortex_access.typed_condition_value_matches_internal(operand_values[2], collection_element_type, true)
        and (not operand_typed[2] or operand_types[2] = collection_element_type)
      )) is not true then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
    else
      if operand_typed[2] and operand_types[2] = 'text_collection' then
        collection_element_type := 'text';
      elsif operand_literal[2] and pg_catalog.jsonb_typeof(operand_values[2]) = 'array' then
        expected_type := case when operand_typed[1] then operand_types[1] else null end;
        collection_valid := true;
        member_type := null;
        for member in select value from pg_catalog.jsonb_array_elements(operand_values[2]) loop
          if expected_type is not null then
            if expected_type in ('text_collection', 'opaque_json')
              or not vortex_access.typed_condition_value_matches_internal(member, expected_type, true) then
              collection_valid := false;
            else member_type := expected_type; end if;
          else
            candidate_type := case pg_catalog.jsonb_typeof(member)
              when 'number' then 'number' when 'boolean' then 'boolean'
              when 'string' then case
                when vortex_access.typed_condition_temporal_value_internal(member #>> '{}', 'date') is not null then 'date'
                when vortex_access.typed_condition_temporal_value_internal(member #>> '{}', 'date_time') is not null then 'date_time'
                else 'text' end else null end;
            if candidate_type is null or candidate_type in ('text_collection', 'opaque_json')
              or (member_type is not null and member_type <> candidate_type) then collection_valid := false;
            else member_type := candidate_type; end if;
          end if;
        end loop;
        if pg_catalog.jsonb_array_length(operand_values[2]) = 0 then
          member_type := case when expected_type not in ('text_collection', 'opaque_json') then expected_type else null end;
        end if;
        if collection_valid then collection_element_type := member_type; end if;
      end if;
      if collection_element_type is null
        or not vortex_access.typed_condition_value_matches_internal(operand_values[1], collection_element_type, true)
        or (operand_typed[1] and operand_types[1] <> collection_element_type) then
        raise exception using errcode = '22023', message = 'Typed record condition is invalid';
      end if;
    end if;
  elsif operator_value in ('equals', 'not_equals') then
    if shared_type is null then
      raise exception using errcode = '22023', message = 'Typed record condition is invalid';
    end if;
  elsif shared_type is null
    or shared_type not in ('text', 'number', 'decimal_number', 'money', 'date', 'date_time') then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  if shared_type = 'money'
    and operator_value in ('greater_than', 'greater_than_or_equal', 'less_than', 'less_than_or_equal')
    and operand_values[1] <> 'null'::jsonb and operand_values[2] <> 'null'::jsonb
    and operand_values[1] ->> 'currency' <> operand_values[2] ->> 'currency' then
    raise exception using errcode = '22023', message = 'Typed record condition is invalid';
  end if;

  if p_validate_only then return true; end if;

  if operator_value in ('equals', 'not_equals') then
    if operand_values[1] = 'null'::jsonb or operand_values[2] = 'null'::jsonb then
      equal_value := operand_values[1] = operand_values[2];
    elsif shared_type = 'number' then
      equal_value := (operand_values[1] #>> '{}')::double precision
        = (operand_values[2] #>> '{}')::double precision;
    elsif shared_type = 'decimal_number' then
      equal_value := (operand_values[1] #>> '{}')::numeric = (operand_values[2] #>> '{}')::numeric;
    elsif shared_type = 'money' then
      equal_value := operand_values[1] ->> 'currency' = operand_values[2] ->> 'currency'
        and (operand_values[1] ->> 'amount')::numeric = (operand_values[2] ->> 'amount')::numeric;
    elsif shared_type = 'date_time' then
      equal_value := vortex_access.typed_condition_temporal_value_internal(
        operand_values[1] #>> '{}', 'date_time'
      ) = vortex_access.typed_condition_temporal_value_internal(
        operand_values[2] #>> '{}', 'date_time'
      );
    elsif shared_type in ('record_reference', 'organization_account_reference') then
      equal_value := pg_catalog.lower(operand_values[1] #>> '{}')
        = pg_catalog.lower(operand_values[2] #>> '{}');
    else equal_value := operand_values[1] = operand_values[2]; end if;
    return case when operator_value = 'equals' then equal_value else not equal_value end;
  end if;

  if operator_value in ('contains', 'not_contains', 'in', 'not_in') then
    contains_value := false;
    if operator_value in ('contains', 'not_contains') then
      if operand_values[1] <> 'null'::jsonb and operand_values[2] <> 'null'::jsonb then
        if shared_type = 'text' and pg_catalog.jsonb_typeof(operand_values[1]) = 'string' then
          contains_value := pg_catalog.strpos(operand_values[1] #>> '{}', operand_values[2] #>> '{}') > 0;
        elsif pg_catalog.jsonb_typeof(operand_values[1]) = 'array' then
          for member in select value from pg_catalog.jsonb_array_elements(operand_values[1]) loop
            if collection_element_type = 'number' then
              equal_value := (member #>> '{}')::double precision = (operand_values[2] #>> '{}')::double precision;
            elsif collection_element_type = 'decimal_number' then
              equal_value := (member #>> '{}')::numeric = (operand_values[2] #>> '{}')::numeric;
            elsif collection_element_type = 'money' then
              equal_value := member ->> 'currency' = operand_values[2] ->> 'currency'
                and (member ->> 'amount')::numeric = (operand_values[2] ->> 'amount')::numeric;
            elsif collection_element_type = 'date_time' then
              equal_value := vortex_access.typed_condition_temporal_value_internal(member #>> '{}', 'date_time')
                = vortex_access.typed_condition_temporal_value_internal(operand_values[2] #>> '{}', 'date_time');
            elsif collection_element_type in ('record_reference', 'organization_account_reference') then
              equal_value := pg_catalog.lower(member #>> '{}') = pg_catalog.lower(operand_values[2] #>> '{}');
            else equal_value := member = operand_values[2]; end if;
            contains_value := contains_value or (equal_value is true);
          end loop;
        end if;
      end if;
      return case when operator_value = 'contains' then contains_value else not contains_value end;
    end if;

    if operand_values[1] <> 'null'::jsonb and operand_values[2] <> 'null'::jsonb then
      for member in select value from pg_catalog.jsonb_array_elements(operand_values[2]) loop
        if collection_element_type = 'number' then
          equal_value := (operand_values[1] #>> '{}')::double precision = (member #>> '{}')::double precision;
        elsif collection_element_type = 'decimal_number' then
          equal_value := (operand_values[1] #>> '{}')::numeric = (member #>> '{}')::numeric;
        elsif collection_element_type = 'money' then
          equal_value := operand_values[1] ->> 'currency' = member ->> 'currency'
            and (operand_values[1] ->> 'amount')::numeric = (member ->> 'amount')::numeric;
        elsif collection_element_type = 'date_time' then
          equal_value := vortex_access.typed_condition_temporal_value_internal(operand_values[1] #>> '{}', 'date_time')
            = vortex_access.typed_condition_temporal_value_internal(member #>> '{}', 'date_time');
        elsif collection_element_type in ('record_reference', 'organization_account_reference') then
          equal_value := pg_catalog.lower(operand_values[1] #>> '{}') = pg_catalog.lower(member #>> '{}');
        else equal_value := operand_values[1] = member; end if;
        contains_value := contains_value or (equal_value is true);
      end loop;
    end if;
    return case when operator_value = 'in' then contains_value else not contains_value end;
  end if;

  if operand_values[1] = 'null'::jsonb or operand_values[2] = 'null'::jsonb then return false; end if;
  if shared_type = 'number' then
    left_number := (operand_values[1] #>> '{}')::double precision;
    right_number := (operand_values[2] #>> '{}')::double precision;
    comparison_value := case when left_number < right_number then -1 when left_number > right_number then 1 else 0 end;
  elsif shared_type = 'decimal_number' then
    comparison_value := case
      when (operand_values[1] #>> '{}')::numeric < (operand_values[2] #>> '{}')::numeric then -1
      when (operand_values[1] #>> '{}')::numeric > (operand_values[2] #>> '{}')::numeric then 1 else 0 end;
  elsif shared_type = 'money' then
    comparison_value := case
      when (operand_values[1] ->> 'amount')::numeric < (operand_values[2] ->> 'amount')::numeric then -1
      when (operand_values[1] ->> 'amount')::numeric > (operand_values[2] ->> 'amount')::numeric then 1 else 0 end;
  elsif shared_type in ('date', 'date_time') then
    comparison_value := case
      when vortex_access.typed_condition_temporal_value_internal(operand_values[1] #>> '{}', shared_type)
        < vortex_access.typed_condition_temporal_value_internal(operand_values[2] #>> '{}', shared_type) then -1
      when vortex_access.typed_condition_temporal_value_internal(operand_values[1] #>> '{}', shared_type)
        > vortex_access.typed_condition_temporal_value_internal(operand_values[2] #>> '{}', shared_type) then 1 else 0 end;
  else
    comparison_value := case
      when (operand_values[1] #>> '{}') collate "C" < (operand_values[2] #>> '{}') collate "C" then -1
      when (operand_values[1] #>> '{}') collate "C" > (operand_values[2] #>> '{}') collate "C" then 1 else 0 end;
  end if;
  return case operator_value
    when 'greater_than' then comparison_value > 0
    when 'greater_than_or_equal' then comparison_value >= 0
    when 'less_than' then comparison_value < 0
    else comparison_value <= 0 end;
end
$$;


ALTER FUNCTION vortex_access.evaluate_typed_condition_node_internal(p_condition jsonb, p_field_types jsonb, p_field_values jsonb, p_parameter_types jsonb, p_parameter_values jsonb, p_validate_only boolean) OWNER TO postgres;

--
-- Name: expire_stale_capability_reservations(uuid, uuid, text, text); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.expire_stale_capability_reservations(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) RETURNS TABLE(result jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  protected_context record;
  affected_count integer;
begin
  if not vortex_access.capability_policy_key_is_valid(p_capability_key)
    or not vortex_access.capability_policy_unit_is_valid(p_unit) then
    raise exception using errcode = '22023', message = 'Capability expiry scope is invalid';
  end if;
  select context.* into strict protected_context
  from vortex_access.capability_reservation_request_context(
    p_tenant_id, p_organization_id
  ) as context;
  update vortex_access.capability_reservations as reservation
  set state = 'expired', expired_at = evaluated_at, updated_at = evaluated_at
  where reservation.tenant_id = p_tenant_id
    and reservation.request_organization_id
      is not distinct from protected_context.request_organization_id
    and reservation.capability_key = p_capability_key and reservation.unit = p_unit
    and reservation.state = 'active' and reservation.expires_at <= evaluated_at;
  get diagnostics affected_count = row_count;
  return query select pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'tenantId', p_tenant_id,
    'organizationId', protected_context.request_organization_id,
    'capabilityKey', p_capability_key, 'unit', p_unit,
    'expiredCount', affected_count,
    'expiredAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'correlationId', protected_context.correlation_id
  ));
end
$$;


ALTER FUNCTION vortex_access.expire_stale_capability_reservations(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) OWNER TO postgres;

--
-- Name: FUNCTION expire_stale_capability_reservations(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.expire_stale_capability_reservations(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) IS 'Expires only the established request-scope capability reservations past their server deadline.';


--
-- Name: fence_record_owner_account_target_internal(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.fence_record_owner_account_target_internal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.owner_organisation_account_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.owner_organisation_account_id is not distinct from old.owner_organisation_account_id
      and new.organisation_id is not distinct from old.organisation_id then
      return new;
    end if;
  end if;

  perform 1
  from vortex_identity.organization_accounts as account
  where account.organization_id = new.organisation_id
    and account.organization_account_id = new.owner_organisation_account_id
    and account.state = 'active'
  for share of account;

  if not found then
    raise exception using errcode = '40001', message = 'Record owner account is not active';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_access.fence_record_owner_account_target_internal() OWNER TO postgres;

--
-- Name: FUNCTION fence_record_owner_account_target_internal(); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.fence_record_owner_account_target_internal() IS 'Row trigger on every Record table: an assigned account owner must be active in the row organisation, under a share lock on the account.';


--
-- Name: flow_execution_binding_authority_internal(uuid, uuid, uuid, text); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.flow_execution_binding_authority_internal(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_organization_id uuid, p_mode text) RETURNS TABLE(tenant_id uuid, access_version bigint, correlation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  context_value jsonb;
  decision record;
  operation_value text;
  organization_tenant_id uuid;
begin
  if p_mode is null or p_mode not in ('grant', 'revoke', 'read') then
    raise exception using errcode = '22023', message = 'Flow execution binding authority mode is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  if (context_value ->> 'identityId')::uuid is distinct from p_actor_identity_id
    or (context_value ->> 'organizationAccountId')::uuid is distinct from p_actor_organization_account_id
    or (context_value ->> 'organizationId')::uuid is distinct from p_organization_id then
    raise exception using errcode = '42501', message = 'Flow execution binding administration is unavailable';
  end if;

  operation_value := case p_mode
    when 'grant' then 'platform.organization.execution_bindings.grant'
    when 'revoke' then 'platform.organization.execution_bindings.revoke'
    else 'platform.organization.execution_bindings.read'
  end;

  select evaluated.* into strict decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', operation_value,
      'action', pg_catalog.jsonb_build_object(
        'actionKind', case when p_mode = 'read' then 'read' else 'manage' end),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', case when p_mode = 'read'
          then '9901c0dc-8bac-45c7-be0b-3642cb839bb1'
          else '156d01f3-8f80-45fb-8fc8-b31c47dbb1df'
        end
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', case p_mode
        when 'grant' then pg_catalog.jsonb_build_object(
          'kind', 'delegated_management',
          'before', pg_catalog.jsonb_build_object('kind', 'none'),
          'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'))
        when 'revoke' then pg_catalog.jsonb_build_object(
          'kind', 'delegated_management',
          'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
          'after', pg_catalog.jsonb_build_object('kind', 'none'))
        else pg_catalog.jsonb_build_object('kind', 'permission')
      end
    )
  ) as evaluated;

  if decision.outcome is distinct from 'eligible'
    or decision.operation_key is distinct from operation_value
    or decision.organization_id is distinct from p_organization_id
    or decision.organization_account_id is distinct from p_actor_organization_account_id
    or decision.access_version is distinct from (context_value ->> 'accessVersion')::bigint
    or decision.correlation_id is distinct from (context_value ->> 'correlationId')::uuid then
    raise exception using errcode = '42501', message = 'Flow execution binding administration is unavailable';
  end if;

  select organization.tenant_id into organization_tenant_id
  from vortex_identity.organizations as organization
  where organization.organization_id = p_organization_id
    and organization.state = 'active';
  if not found then
    raise exception using errcode = '42501', message = 'Flow execution binding administration is unavailable';
  end if;

  return query select organization_tenant_id,
    decision.access_version,
    decision.correlation_id;
end
$$;


ALTER FUNCTION vortex_access.flow_execution_binding_authority_internal(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_organization_id uuid, p_mode text) OWNER TO postgres;

--
-- Name: is_non_nil_uuid(text); Type: FUNCTION; Schema: vortex_context; Owner: postgres
--

create or replace function vortex_context.is_non_nil_uuid(candidate text)
returns boolean
language sql
immutable
parallel safe
security invoker
set search_path = ''
as $function$
  select
    coalesce(
      candidate ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      and candidate <> '00000000-0000-0000-0000-000000000000',
      false
    )
$function$;


ALTER FUNCTION vortex_context.is_non_nil_uuid(candidate text) OWNER TO postgres;

--
-- Name: FUNCTION is_non_nil_uuid(candidate text); Type: COMMENT; Schema: vortex_context; Owner: postgres
--

COMMENT ON FUNCTION vortex_context.is_non_nil_uuid(candidate text) IS 'Accepts only a non-nil RFC UUID with a version nibble from 1 through 8 and an RFC variant nibble.';


--
-- Name: flow_execution_bindings; Type: TABLE; Schema: vortex_access; Owner: postgres
--

CREATE TABLE vortex_access.flow_execution_bindings (
    execution_binding_id uuid NOT NULL,
    revision bigint NOT NULL,
    is_current boolean NOT NULL,
    organization_id uuid NOT NULL,
    application_root_id uuid NOT NULL,
    release_version text NOT NULL,
    flow_id uuid NOT NULL,
    node_id uuid NOT NULL,
    operation_owner_kind text NOT NULL,
    operation_owner_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    actor_kind text NOT NULL,
    actor_organization_account_id uuid,
    actor_system_actor_id uuid,
    permitted_invokers jsonb NOT NULL,
    permitted_surfaces jsonb NOT NULL,
    permitted_inputs jsonb NOT NULL,
    expires_at timestamp with time zone,
    state text NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    recorded_by_actor_id uuid NOT NULL,
    recorded_correlation_id uuid NOT NULL,
    revoked_at timestamp with time zone,
    CONSTRAINT flow_execution_bindings_actor_valid CHECK ((((actor_kind = 'specified_user'::text) AND (actor_organization_account_id IS NOT NULL) AND (actor_system_actor_id IS NULL)) OR ((actor_kind = 'system'::text) AND (actor_system_actor_id IS NOT NULL) AND (actor_organization_account_id IS NULL)))),
    CONSTRAINT flow_execution_bindings_bounds_shape CHECK (((jsonb_typeof(permitted_invokers) = 'array'::text) AND ((jsonb_array_length(permitted_invokers) >= 1) AND (jsonb_array_length(permitted_invokers) <= 20)) AND (jsonb_typeof(permitted_surfaces) = 'array'::text) AND ((jsonb_array_length(permitted_surfaces) >= 1) AND (jsonb_array_length(permitted_surfaces) <= 7)) AND (jsonb_typeof(permitted_inputs) = 'array'::text) AND (jsonb_array_length(permitted_inputs) <= 20))),
    CONSTRAINT flow_execution_bindings_ids_non_nil CHECK ((vortex_context.is_non_nil_uuid((execution_binding_id)::text) AND vortex_context.is_non_nil_uuid((organization_id)::text) AND vortex_context.is_non_nil_uuid((application_root_id)::text) AND vortex_context.is_non_nil_uuid((flow_id)::text) AND vortex_context.is_non_nil_uuid((node_id)::text) AND vortex_context.is_non_nil_uuid((operation_owner_id)::text) AND vortex_context.is_non_nil_uuid((operation_id)::text) AND vortex_context.is_non_nil_uuid((recorded_by_actor_id)::text) AND vortex_context.is_non_nil_uuid((recorded_correlation_id)::text) AND ((actor_organization_account_id IS NULL) OR vortex_context.is_non_nil_uuid((actor_organization_account_id)::text)) AND ((actor_system_actor_id IS NULL) OR vortex_context.is_non_nil_uuid((actor_system_actor_id)::text)))),
    CONSTRAINT flow_execution_bindings_operation_owner_valid CHECK (((operation_owner_kind = ANY (ARRAY['application'::text, 'module'::text, 'platform_service'::text])) AND ((operation_owner_kind <> 'application'::text) OR (operation_owner_id = application_root_id)))),
    CONSTRAINT flow_execution_bindings_release_version_valid CHECK ((release_version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'::text)),
    CONSTRAINT flow_execution_bindings_revision_valid CHECK (((revision >= 1) AND (revision <= '9007199254740991'::bigint))),
    CONSTRAINT flow_execution_bindings_state_valid CHECK ((((state = 'active'::text) AND (revoked_at IS NULL)) OR ((state = 'revoked'::text) AND (revoked_at IS NOT NULL) AND (revoked_at = recorded_at)))),
    CONSTRAINT flow_execution_bindings_timestamps_valid CHECK (((recorded_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND ((expires_at IS NULL) OR (expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])))))
);

