--

COMMENT ON FUNCTION vortex_access.initialize_platform_permission_catalogue_v1(p_organization_id uuid, p_changed_by uuid, p_correlation_id uuid) IS 'Owner-only exact historical 1.0.0 platform catalogue initializer retained for compatibility.';


--
-- Name: initialize_platform_permission_catalogue_v1_4_0(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.initialize_platform_permission_catalogue_v1_4_0(
  p_organization_id uuid,
  p_changed_by uuid,
  p_correlation_id uuid
)
returns table (
  organization_id uuid,
  registration_revision bigint,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  current_revision bigint;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_changed_by is null
    or p_changed_by = '00000000-0000-0000-0000-000000000000'::uuid
    or p_correlation_id is null
    or p_correlation_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Platform permission registration input is invalid';
  end if;

  select registration.revision into current_revision
  from vortex_access.permission_registrations as registration
  where registration.organization_id = p_organization_id
    and registration.registration_kind = 'platform'
    and registration.registration_owner_id =
      'cabe121e-0baf-4084-9471-cce915d460a8'::uuid;

  if not found then
    raise exception using errcode = '55000',
      message = 'Platform permission registration evidence is invalid';
  end if;

  if current_revision = 1 then
    perform 1
    from vortex_access.revise_platform_permission_catalogue_metadata(
      p_organization_id, 1, '1.0.0', '1.0.1',
      p_changed_by, p_correlation_id
    );
    current_revision := 2;
  end if;

  if current_revision = 2 then
    perform 1
    from vortex_access.adopt_shipped_platform_permission_catalogue(
      p_organization_id, 2, '1.1.0',
      'sha256:57453282c9a853912b2b67baeefaca81e21d076761d200ac812a7573d7dc7c9c',
      p_changed_by, p_correlation_id
    );
    current_revision := 3;
  end if;

  if current_revision = 3 then
    perform vortex_access.adopt_connection_administration_permission_catalogue(
      p_organization_id, p_changed_by, p_correlation_id
    );
    current_revision := 4;
  end if;

  if current_revision = 4 then
    perform vortex_access.adopt_security_and_support_operator_permission_catalogue(
      p_organization_id, p_changed_by, p_correlation_id
    );
    current_revision := 5;
  end if;

  if current_revision = 5 then
    perform vortex_access.adopt_builder_permission_catalogue(
      p_organization_id, p_changed_by, p_correlation_id
    );
    current_revision := 6;
  end if;

  if current_revision is distinct from 6
    or not vortex_access.platform_permission_catalogue_revision_is_exact(
      p_organization_id, 6
    ) then
    raise exception using errcode = '55000',
      message = 'Platform permission registration evidence is invalid';
  end if;

  return query
  select p_organization_id, 6::bigint, version.current_version
  from vortex_access.organization_access_versions as version
  where version.organization_id = p_organization_id;
end
$function$;


ALTER FUNCTION vortex_access.initialize_platform_permission_catalogue_v1_4_0(p_organization_id uuid, p_changed_by uuid, p_correlation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION initialize_platform_permission_catalogue_v1_4_0(p_organization_id uuid, p_changed_by uuid, p_correlation_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.initialize_platform_permission_catalogue_v1_4_0(p_organization_id uuid, p_changed_by uuid, p_correlation_id uuid) IS 'Owner-only platform catalogue initializer step: advances an existing platform registration through every immutable revision to revision 6 (1.4.0).';


--
-- Name: list_application_role_templates_for_administration(uuid, uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.list_application_role_templates_for_administration(p_after_application_root_id uuid, p_after_source_role_id uuid, p_page_size integer) RETURNS TABLE(organization_id uuid, templates jsonb, next_after_application_root_id uuid, next_after_source_role_id uuid, access_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scope record;
  template_items jsonb;
  page_application_root_ids uuid[];
  page_source_role_ids uuid[];
  candidate_count integer;
  cursor_absent boolean;
begin
  cursor_absent := p_after_application_root_id is null
    and p_after_source_role_id is null;
  if p_page_size is null or p_page_size not between 1 and 100
    or (
      cursor_absent
      or (
        p_after_application_root_id is not null
        and p_after_source_role_id is not null
      )
    ) is not true
    or p_after_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_after_source_role_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Application role template page input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_roles_administration_scope() as authorized;

  with candidates as (
    select registration.registration_owner_id as application_root_id,
      (template.value ->> 'roleId')::uuid as source_role_id,
      template.value ->> 'key' as role_key,
      template.value ->> 'name' as role_label,
      template.value #>> '{permissionSelection,kind}' as permission_selection_kind,
      template.value -> 'permissionKeys' as permission_keys,
      pg_catalog.row_number() over (
        order by registration.registration_owner_id,
          (template.value ->> 'roleId')::uuid
      ) as ordinal
    from vortex_access.permission_registrations as registration
    join vortex_definition.roots as root
      on root.root_id = registration.registration_owner_id
      and root.organization_id = registration.organization_id
      and root.kind = 'application'
      and root.key = registration.source_definition_key
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = registration.source_revision
      and release.release_version = registration.source_version
      and release.validation_contract_version = registration.validation_contract_version
      and release.content_fingerprint = registration.source_content_fingerprint
      and release.resolution_fingerprint = registration.source_resolution_fingerprint
    cross join lateral pg_catalog.jsonb_array_elements(
      release.compilation_output #> '{canonical,content,roles}'
    ) as template(value)
    join vortex_access.application_role_template_continuities as continuity
      on continuity.organization_id = registration.organization_id
      and continuity.application_root_id = registration.registration_owner_id
      and continuity.source_role_id = (template.value ->> 'roleId')::uuid
      and continuity.state = 'available'
      and continuity.last_processed_registration_revision = registration.revision
    where registration.organization_id = scope.organization_id
      and registration.registration_kind = 'application'
      and registration.state = 'active'
      and (
        cursor_absent
        or (
          registration.registration_owner_id,
          (template.value ->> 'roleId')::uuid
        ) > (p_after_application_root_id, p_after_source_role_id)
      )
    order by registration.registration_owner_id,
      (template.value ->> 'roleId')::uuid
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'reference', pg_catalog.jsonb_build_object(
            'applicationRootId', candidate.application_root_id,
            'sourceRoleId', candidate.source_role_id
          ),
          'key', candidate.role_key,
          'label', candidate.role_label,
          'permissionSelectionKind', candidate.permission_selection_kind,
          'publishedPermissionKeys', candidate.permission_keys
        ) order by candidate.application_root_id, candidate.source_role_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.application_root_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.array_agg(candidate.source_role_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into template_items, page_application_root_ids, page_source_role_ids,
    candidate_count
  from candidates as candidate;

  return query select scope.organization_id, template_items,
    case when candidate_count > p_page_size
      then page_application_root_ids[p_page_size] else null end,
    case when candidate_count > p_page_size
      then page_source_role_ids[p_page_size] else null end,
    scope.access_version;
end
$$;


ALTER FUNCTION vortex_access.list_application_role_templates_for_administration(p_after_application_root_id uuid, p_after_source_role_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_application_role_templates_for_administration(p_after_application_root_id uuid, p_after_source_role_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_application_role_templates_for_administration(p_after_application_root_id uuid, p_after_source_role_id uuid, p_page_size integer) IS 'Returns one bounded page of exact current registered application role templates.';


--
-- Name: list_application_role_templates_projection(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_application_role_templates_projection(
  p_record_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  record_id uuid,
  revision bigint,
  attribute_values jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope_row record;
  application_row record;
  template_value jsonb;
  source_role_id_value uuid;
  seen_role_ids uuid[];
  valid_roles boolean;
begin
  begin
    select authorized.* into strict scope_row
    from vortex_access.organization_roles_administration_scope() as authorized;
  exception
    when insufficient_privilege then
      return;
  end;

  -- Catalogue authority and current installed-application reachability are both
  -- required. Neither the organization nor the application is a caller input.
  for application_row in
    select root.root_id, registration.revision as registration_revision,
      release.compilation_output #> '{canonical,content,roles}' as roles
    from vortex_access.list_installed_applications_projection(
      null::uuid, null::integer
    ) as installed
    join vortex_access.permission_registrations as registration
      on registration.organization_id = installed.organization_id
      and registration.registration_owner_id = installed.record_id
      and registration.revision = installed.revision
      and registration.registration_kind = 'application'
      and registration.state = 'active'
    join vortex_definition.roots as root
      on root.root_id = registration.registration_owner_id
      and root.organization_id = registration.organization_id
      and root.kind = 'application'
      and root.key = registration.source_definition_key
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = registration.source_revision
      and release.release_version = registration.source_version
      and release.validation_contract_version = registration.validation_contract_version
      and release.content_fingerprint = registration.source_content_fingerprint
      and release.resolution_fingerprint = registration.source_resolution_fingerprint
    where registration.organization_id = scope_row.organization_id
      and release.compilation_output ->> 'kind' = 'application'
    order by root.root_id
  loop
    if pg_catalog.jsonb_typeof(application_row.roles) is distinct from 'array' then
      continue;
    end if;
    if pg_catalog.jsonb_array_length(application_row.roles) not between 1 and 100 then
      continue;
    end if;
    seen_role_ids := array[]::uuid[];
    valid_roles := true;
    -- Validate the complete array before returning any row. Duplicate UUIDs,
    -- including alternate casing, cannot become duplicate ordinary record IDs.
    for template_value in
      select template.value
      from pg_catalog.jsonb_array_elements(application_row.roles) as template(value)
    loop
      if pg_catalog.jsonb_typeof(template_value) is distinct from 'object'
        or pg_catalog.jsonb_typeof(template_value -> 'roleId') is distinct from 'string'
        or not vortex_context.is_non_nil_uuid(template_value ->> 'roleId')
        or pg_catalog.jsonb_typeof(template_value -> 'key') is distinct from 'string'
        or pg_catalog.char_length(template_value ->> 'key') not between 1 and 40
        or (template_value ->> 'key') !~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'
        or pg_catalog.jsonb_typeof(template_value -> 'name') is distinct from 'string'
        or pg_catalog.char_length(template_value ->> 'name') not between 1 and 60 then
        valid_roles := false;
        exit;
      end if;
      source_role_id_value := (template_value ->> 'roleId')::uuid;
      if source_role_id_value = any(seen_role_ids)
        or not vortex_definition.application_role_identity_is_exact_for_human_request_internal(
          application_row.root_id, source_role_id_value
        ) then
        valid_roles := false;
        exit;
      end if;
      seen_role_ids := pg_catalog.array_append(seen_role_ids, source_role_id_value);
    end loop;
    if not valid_roles then
      continue;
    end if;

    -- Generic Query applies its own filter and pagination after this relation;
    -- p_page_size must not truncate it before those predicates are evaluated.
    -- Registration revision is the row concurrency number. Continuity revision
    -- changes only on availability transitions and remains a separate attribute.
    return query
    select scope_row.organization_id,
      (template.value ->> 'roleId')::uuid,
      application_row.registration_revision,
      pg_catalog.jsonb_build_object(
        'application_root_id', application_row.root_id,
        'source_role_id', (template.value ->> 'roleId')::uuid,
        'key', template.value ->> 'key',
        'label', template.value ->> 'name',
        'continuity_revision', continuity.continuity_revision
      )
    from pg_catalog.jsonb_array_elements(application_row.roles) as template(value)
    join vortex_access.application_role_template_continuities as continuity
      on continuity.organization_id = scope_row.organization_id
      and continuity.application_root_id = application_row.root_id
      and continuity.source_role_id = (template.value ->> 'roleId')::uuid
      and continuity.state = 'available'
      and continuity.last_processed_registration_revision = application_row.registration_revision
    where p_record_id is null or p_record_id = (template.value ->> 'roleId')::uuid
    order by (template.value ->> 'roleId')::uuid;
  end loop;
end
$function$;


ALTER FUNCTION vortex_access.list_application_role_templates_projection(p_record_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_application_role_templates_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_application_role_templates_projection(p_record_id uuid, p_page_size integer) IS 'Registered application-role-template projection for the current human organization: fixed role-catalogue read authority, reachable active installation, exact registered application release, permanent Definition role identity and available continuity processed at the current registration are all required. Record identity is the source role UUID and row revision is the registration revision; only application root, source role, key, label and continuity revision are projected. Missing, refused, foreign or malformed candidates produce no revealing rows.';


--
-- Name: list_current_record_owner_groups(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_current_record_owner_groups()
returns table (group_id uuid, label text)
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
begin
  context_value := vortex_access.validated_human_request_context();

  return query
  select distinct organization_group.group_id, organization_group.label
  from vortex_access.organization_groups as organization_group
  join vortex_access.organization_group_memberships as membership
    on membership.organization_id = organization_group.organization_id
    and membership.group_id = organization_group.group_id
  where organization_group.organization_id = (context_value ->> 'organizationId')::uuid
    and organization_group.state = 'active'
    and membership.organization_account_id =
      (context_value ->> 'organizationAccountId')::uuid
    and membership.state = 'live'
    and membership.starts_at <= pg_catalog.statement_timestamp()
    and (membership.expires_at is null
      or membership.expires_at > pg_catalog.statement_timestamp())
  order by organization_group.label, organization_group.group_id;
end
$function$;


ALTER FUNCTION vortex_access.list_current_record_owner_groups() OWNER TO postgres;

--
-- Name: FUNCTION list_current_record_owner_groups(); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_current_record_owner_groups() IS 'Returns only the active Groups of which the verified current organisation account is a current member, for an explicit initial record ownership choice. The protected Record writer rechecks the selected Group under its own transaction lock.';


--
-- Name: list_installed_applications_projection(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_installed_applications_projection(
  p_record_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  record_id uuid,
  revision bigint,
  attribute_values jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  visible_organization_id uuid;
  actor_identity_id uuid;
  default_application_root_id uuid;
  application_row record;
  authorised boolean;
begin
  -- The projection keeps today's row visibility inside itself and neither the
  -- organisation nor the application is ever an input. An installed application is
  -- exactly the row the permitted-applications feed derives: an active application
  -- registration of the organisation whose published release still matches every
  -- fingerprint and whose installation binding is itself active, so a provisioned
  -- or draining installation is not an installed application. Each derived row is
  -- then authorised individually through the same application scope resolution the
  -- feed uses, so a viewer the scope refuses sees no row for that application,
  -- exactly as a missing or foreign record, and the record adapters return their
  -- identical refusal and a list page is empty rather than failing. The record
  -- identity is the application root and the revision is the registration's own
  -- revision, which every installation change advances. Compilation output,
  -- fingerprints, release evidence, binding evidence and the whole module set are
  -- never projected.
  begin
    context_value := vortex_access.validated_human_request_context();
  exception
    when insufficient_privilege then
      return;
  end;
  visible_organization_id := (context_value ->> 'organizationId')::uuid;
  actor_identity_id := (context_value ->> 'identityId')::uuid;
  if not vortex_context.is_non_nil_uuid(visible_organization_id::text)
    or not vortex_context.is_non_nil_uuid(actor_identity_id::text) then
    return;
  end if;
  select settings.default_application_root_id into default_application_root_id
  from vortex_identity.organization_runtime_settings as settings
  where settings.organization_id = visible_organization_id;
  for application_row in
    select
      root.root_id,
      root.key as application_key,
      registration.revision as registration_revision,
      registration.source_revision as release_revision
    from vortex_access.permission_registrations as registration
    join vortex_definition.roots as root
      on root.root_id = registration.registration_owner_id
      and root.organization_id = registration.organization_id
      and root.kind = 'application'
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = registration.source_revision
    where registration.organization_id = visible_organization_id
      and registration.registration_kind = 'application'
      and registration.state = 'active'
      and (p_record_id is null or p_record_id = root.root_id)
      and release.compilation_output ->> 'kind' = 'application'
      and registration.source_content_fingerprint = release.content_fingerprint
      and registration.source_resolution_fingerprint = release.resolution_fingerprint
      and exists (
        select 1
        from vortex_module.installation_bindings as binding
        where binding.organization_id = visible_organization_id
          and binding.application_root_id = root.root_id
          and binding.application_release_revision = registration.source_revision
          and binding.state = 'active'
      )
    order by root.key collate "C", root.root_id
  loop
    authorised := false;
    begin
      perform 1
      from vortex_access.resolve_human_application_scope(
        actor_identity_id, visible_organization_id, application_row.root_id
      ) as scope;
      authorised := true;
    exception
      when sqlstate '42501' or sqlstate 'P0002' then
        authorised := false;
    end;
    if authorised then
      return query select
        visible_organization_id,
        application_row.root_id,
        application_row.registration_revision,
        pg_catalog.jsonb_build_object(
          'key', application_row.application_key,
          'release_revision', application_row.release_revision,
          'is_default', application_row.root_id
            is not distinct from default_application_root_id
        );
    end if;
  end loop;
end
$function$;


ALTER FUNCTION vortex_access.list_installed_applications_projection(p_record_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_installed_applications_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_installed_applications_projection(p_record_id uuid, p_page_size integer) IS 'Registered installed-application projection: returns every application the current viewer may reach that is installed in the viewer''s organisation, being an active application registration whose published release still matches every fingerprint and whose installation binding is active, with the organisation, the application identity, the registration revision and the safe projected attribute values keyed by lowercase field key, or no row when the application scope refuses the viewer. Compilation output, fingerprints, release evidence and binding evidence are never projected.';


--
-- Name: list_landing_zone_applications_projection(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_landing_zone_applications_projection(
  p_record_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  record_id uuid,
  revision bigint,
  attribute_values jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  visible_organization_id uuid;
  actor_identity_id uuid;
  application_row record;
  authorised boolean;
begin
  -- Row visibility matches the installed-application projection: the viewer's
  -- validated human request context selects the organisation and identity; only
  -- active application registrations whose published release still matches both
  -- fingerprints and whose installation binding is active are considered; and
  -- each application must pass the same human application-scope resolution. A
  -- refused, uninstalled or withdrawn application therefore has no row, exactly
  -- like a missing record. The record identity is the application root and its
  -- revision is the registration revision. Only the application key, name and
  -- icon are projected; compilation output, pages, roles, fingerprints, release
  -- evidence and installation evidence are never returned. Page access is not
  -- evaluated here.
  begin
    context_value := vortex_access.validated_human_request_context();
  exception
    when insufficient_privilege then
      return;
  end;
  visible_organization_id := (context_value ->> 'organizationId')::uuid;
  actor_identity_id := (context_value ->> 'identityId')::uuid;
  if not vortex_context.is_non_nil_uuid(visible_organization_id::text)
    or not vortex_context.is_non_nil_uuid(actor_identity_id::text) then
    return;
  end if;
  for application_row in
    select
      root.root_id,
      root.key as application_key,
      registration.revision as registration_revision,
      release.compilation_output #>> '{canonical,content,name}' as application_name,
      release.compilation_output #>> '{canonical,content,icon}' as application_icon
    from vortex_access.permission_registrations as registration
    join vortex_definition.roots as root
      on root.root_id = registration.registration_owner_id
      and root.organization_id = registration.organization_id
      and root.kind = 'application'
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = registration.source_revision
    where registration.organization_id = visible_organization_id
      and registration.registration_kind = 'application'
      and registration.state = 'active'
      and (p_record_id is null or p_record_id = root.root_id)
      and release.compilation_output ->> 'kind' = 'application'
      and registration.source_content_fingerprint = release.content_fingerprint
      and registration.source_resolution_fingerprint = release.resolution_fingerprint
      and exists (
        select 1
        from vortex_module.installation_bindings as binding
        where binding.organization_id = visible_organization_id
          and binding.application_root_id = root.root_id
          and binding.application_release_revision = registration.source_revision
          and binding.state = 'active'
      )
    order by root.key collate "C", root.root_id
  loop
    authorised := false;
    begin
      perform 1
      from vortex_access.resolve_human_application_scope(
        actor_identity_id, visible_organization_id, application_row.root_id
      ) as scope;
      authorised := true;
    exception
      when sqlstate '42501' or sqlstate 'P0002' then
        authorised := false;
    end;
    if authorised then
      return query select
        visible_organization_id,
        application_row.root_id,
        application_row.registration_revision,
        pg_catalog.jsonb_build_object(
          'key', application_row.application_key,
          'name', application_row.application_name,
          'icon', application_row.application_icon
        );
    end if;
  end loop;
end
$function$;


ALTER FUNCTION vortex_access.list_landing_zone_applications_projection(p_record_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_landing_zone_applications_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_landing_zone_applications_projection(p_record_id uuid, p_page_size integer) IS 'Registered Landing Zone application projection: returns each installed application the current viewer may reach in the viewer''s organisation, with the application identity, registration revision and only its key, name and icon, or no row when the application scope refuses the viewer. Pages, roles, compilation output, fingerprints and installation evidence are never projected.';


