ALTER FUNCTION vortex_access.list_organization_account_choices(p_search text, p_page_size integer, p_after_sort_key text, p_after_organization_account_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION list_organization_account_choices(p_search text, p_page_size integer, p_after_sort_key text, p_after_organization_account_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

