--
-- Name: FUNCTION list_organization_accounts_for_administration(p_after_organization_account_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_organization_accounts_for_administration(p_after_organization_account_id uuid, p_page_size integer) IS 'Protected bounded local-ID account page under the fixed accounts.read decision.';


--
-- Name: list_organization_accounts_projection(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_organization_accounts_projection(
  p_record_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  record_id uuid,
  revision bigint,
  attribute_values jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope_row record;
  context_value jsonb;
  visible_organization_id uuid;
  active_members_only boolean;
begin
  -- The projection keeps today's row visibility inside itself, and the caller's
  -- current organisation is never an input. A viewer the fixed accounts.read
  -- decision admits sees every account of the organisation, exactly as the
  -- bespoke administration reader. Any other viewer whose human request context
  -- is still live sees only the active accounts of that organisation with their
  -- display name and state, exactly as the organisation-account choice reader.
  -- A viewer neither rule admits sees no rows, exactly as a missing or foreign
  -- record, so the record adapters return their identical refusal and a list
  -- page is empty rather than failing. The record identity is the organisation
  -- account, the revision is the account's own revision and the attribute
  -- names are the lowercase field keys a projection record type declares. The
  -- raw identity, invitation link and state-change evidence stay in the
  -- protected storage and are never projected.
  begin
    select authorized.* into strict scope_row
    from vortex_access.organization_accounts_administration_scope() as authorized;
    visible_organization_id := scope_row.organization_id;
    active_members_only := false;
  exception
    when insufficient_privilege then
      visible_organization_id := null;
  end;
  if visible_organization_id is null then
    begin
      context_value := vortex_access.validated_human_request_context();
    exception
      when insufficient_privilege then
        return;
    end;
    visible_organization_id := (context_value ->> 'organizationId')::uuid;
    active_members_only := true;
  end if;
  return query
  select
    visible_organization_id,
    projected.organization_account_id,
    projected.revision,
    pg_catalog.jsonb_build_object(
      'display_name', projected.display_name,
      'state', projected.account_state,
      'language', projected.language,
      'time_zone', projected.time_zone
    )
  from vortex_identity.list_organization_accounts_projection_internal(
    visible_organization_id, active_members_only
  ) as projected
  where p_record_id is null or p_record_id = projected.organization_account_id;
end
$function$;


ALTER FUNCTION vortex_access.list_organization_accounts_projection(p_record_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_organization_accounts_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_organization_accounts_projection(p_record_id uuid, p_page_size integer) IS 'Registered organisation-account projection: returns every account of the organisation to a viewer the fixed accounts.read decision admits, otherwise only the active accounts with their display name and state to a live human member, with the organisation, the account identity, the account revision and the safe projected attribute values keyed by lowercase field key, or no row when neither rule admits the viewer.';


--
-- Name: list_organization_delegation_authorities_for_administration(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.list_organization_delegation_authorities_for_administration(p_after_delegation_authority_id uuid, p_page_size integer) RETURNS TABLE(organization_id uuid, delegations jsonb, next_after_delegation_authority_id uuid, access_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scope record;
  checked_at timestamptz;
  delegation_items jsonb;
  page_delegation_ids uuid[];
  candidate_count integer;
begin
  if p_page_size is null or p_page_size not between 1 and 100
    or p_after_delegation_authority_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization delegation authority page input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_assignment_ledger_administration_scope()
    as authorized;
  checked_at := pg_catalog.clock_timestamp();

  with candidates as (
    select delegation.delegation_authority_id, delegation.holder_kind,
      delegation.organization_account_id, account.display_name,
      delegation.group_id, organization_group.group_key,
      organization_group.label as group_label,
      organization_group.state as group_state,
      delegation.scope_kind, delegation.bounded_permissions,
      delegation.revision, delegation.starts_at, delegation.expires_at,
      delegation.state,
      case
        when delegation.state = 'revoked' then 'revoked'
        when delegation.starts_at > checked_at then 'scheduled'
        when delegation.expires_at is not null
          and delegation.expires_at <= checked_at then 'expired'
        else 'active'
      end as temporal_state,
      pg_catalog.row_number() over (
        order by delegation.delegation_authority_id
      ) as ordinal
    from vortex_access.organization_delegation_authorities as delegation
    left join vortex_identity.organization_accounts as account
      on delegation.holder_kind = 'organization_account'
      and account.organization_id = delegation.organization_id
      and account.organization_account_id = delegation.organization_account_id
    left join vortex_access.organization_groups as organization_group
      on delegation.holder_kind = 'group'
      and organization_group.organization_id = delegation.organization_id
      and organization_group.group_id = delegation.group_id
    where delegation.organization_id = scope.organization_id
      and (
        p_after_delegation_authority_id is null
        or delegation.delegation_authority_id > p_after_delegation_authority_id
      )
    order by delegation.delegation_authority_id
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'delegationAuthorityId', candidate.delegation_authority_id,
          'holder', case candidate.holder_kind
            when 'organization_account' then pg_catalog.jsonb_build_object(
              'kind', 'organization_account',
              'organizationAccountId', candidate.organization_account_id,
              'displayName', candidate.display_name
            )
            else pg_catalog.jsonb_build_object(
              'kind', 'group',
              'groupId', candidate.group_id,
              'key', candidate.group_key,
              'label', candidate.group_label,
              'state', candidate.group_state
            )
          end,
          'scope', case candidate.scope_kind
            when 'organization_catalogue' then pg_catalog.jsonb_build_object(
              'kind', 'organization_catalogue'
            )
            else pg_catalog.jsonb_build_object(
              'kind', 'bounded',
              'permissions', (
                select coalesce(
                  pg_catalog.jsonb_agg(
                    pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                      'applicationRootId', permission.value -> 'applicationRootId',
                      'ownerKind', permission.value -> 'ownerKind',
                      'ownerId', permission.value -> 'ownerId',
                      'permissionId', permission.value -> 'permissionId'
                    )) order by permission.ordinality
                  ),
                  '[]'::jsonb
                )
                from pg_catalog.jsonb_array_elements(candidate.bounded_permissions)
                  with ordinality as permission(value, ordinality)
              )
            )
          end,
          'revision', candidate.revision,
          'startsAt', candidate.starts_at,
          'expiresAt', candidate.expires_at,
          'state', candidate.state,
          'temporalState', candidate.temporal_state
        )) order by candidate.delegation_authority_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.delegation_authority_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into delegation_items, page_delegation_ids, candidate_count
  from candidates as candidate;

  return query select scope.organization_id, delegation_items,
    case when candidate_count > p_page_size
      then page_delegation_ids[p_page_size] else null end,
    scope.access_version;
end
$$;


