--
-- Name: list_organization_permissions_for_administration(uuid, text, uuid, uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.list_organization_permissions_for_administration(
  p_after_application_root_id uuid,
  p_after_owner_kind text,
  p_after_owner_id uuid,
  p_after_permission_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  permissions jsonb,
  next_after_application_root_id uuid,
  next_after_owner_kind text,
  next_after_owner_id uuid,
  next_after_permission_id uuid,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  permission_items jsonb;
  page_application_root_ids uuid[];
  page_owner_kinds text[];
  page_owner_ids uuid[];
  page_permission_ids uuid[];
  candidate_count integer;
  cursor_absent boolean;
  cursor_valid boolean;
begin
  cursor_absent := p_after_application_root_id is null
    and p_after_owner_kind is null
    and p_after_owner_id is null
    and p_after_permission_id is null;
  cursor_valid := cursor_absent
    or (
      p_after_application_root_id is null
      and p_after_owner_kind = 'platform'
      and p_after_owner_id is not null
      and p_after_permission_id is not null
    )
    or (
      p_after_application_root_id is not null
      and p_after_owner_kind in ('application', 'module')
      and p_after_owner_id is not null
      and p_after_permission_id is not null
      and (
        p_after_owner_kind <> 'application'
        or p_after_owner_id = p_after_application_root_id
      )
    );

  if p_page_size is null or p_page_size not between 1 and 100
    or cursor_valid is not true
    or p_after_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_after_owner_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_after_permission_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization permission catalogue page input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_permissions_administration_scope() as authorized;

  with candidates as (
    select entry.application_root_id, entry.owner_kind, entry.owner_id,
      entry.permission_id, entry.permission_key, entry.label, entry.description,
      entry.record_type_id, entry.action_kind, entry.named_action,
      entry.administrative,
      pg_catalog.row_number() over (
        order by entry.application_root_id asc nulls last,
          entry.owner_kind, entry.owner_id, entry.permission_id
      ) as ordinal
    from vortex_access.permission_catalogue_entries as entry
    join vortex_access.permission_registrations as registration
      on registration.organization_id = entry.organization_id
      and registration.registration_kind = entry.registration_kind
      and registration.registration_owner_id = entry.registration_owner_id
      and registration.revision = entry.registration_revision
    where entry.organization_id = scope.organization_id
      and registration.state = 'active'
      and (
        cursor_absent
        or (
          p_after_application_root_id is not null
          and (
            entry.application_root_id is null
            or (
              entry.application_root_id is not null
              and (
                entry.application_root_id, entry.owner_kind,
                entry.owner_id, entry.permission_id
              ) > (
                p_after_application_root_id, p_after_owner_kind,
                p_after_owner_id, p_after_permission_id
              )
            )
          )
        )
        or (
          p_after_application_root_id is null
          and entry.application_root_id is null
          and (entry.owner_kind, entry.owner_id, entry.permission_id)
            > (p_after_owner_kind, p_after_owner_id, p_after_permission_id)
        )
      )
    order by entry.application_root_id asc nulls last,
      entry.owner_kind, entry.owner_id, entry.permission_id
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(
          pg_catalog.jsonb_build_object(
            'reference', pg_catalog.jsonb_strip_nulls(
              pg_catalog.jsonb_build_object(
                'applicationRootId', candidate.application_root_id,
                'ownerKind', candidate.owner_kind,
                'ownerId', candidate.owner_id,
                'permissionId', candidate.permission_id
              )
            ),
            'key', candidate.permission_key,
            'label', candidate.label,
            'description', candidate.description,
            'recordTypeId', candidate.record_type_id,
            'action', pg_catalog.jsonb_strip_nulls(
              pg_catalog.jsonb_build_object(
                'actionKind', candidate.action_kind,
                'namedAction', candidate.named_action
              )
            ),
            'administrative', candidate.administrative
          )
        ) order by candidate.application_root_id asc nulls last,
          candidate.owner_kind, candidate.owner_id, candidate.permission_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.application_root_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.array_agg(candidate.owner_kind order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.array_agg(candidate.owner_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.array_agg(candidate.permission_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into permission_items, page_application_root_ids, page_owner_kinds,
    page_owner_ids, page_permission_ids, candidate_count
  from candidates as candidate;

  return query select scope.organization_id, permission_items,
    case when candidate_count > p_page_size
      then page_application_root_ids[p_page_size] else null end,
    case when candidate_count > p_page_size
      then page_owner_kinds[p_page_size] else null end,
    case when candidate_count > p_page_size
      then page_owner_ids[p_page_size] else null end,
    case when candidate_count > p_page_size
      then page_permission_ids[p_page_size] else null end,
    scope.access_version;
end
$function$;


ALTER FUNCTION vortex_access.list_organization_permissions_for_administration(p_after_application_root_id uuid, p_after_owner_kind text, p_after_owner_id uuid, p_after_permission_id uuid, p_page_size integer) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION list_organization_permissions_for_administration(p_after_application_root_id uuid, p_after_owner_kind text, p_after_owner_id uuid, p_after_permission_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.list_organization_permissions_for_administration(p_after_application_root_id uuid, p_after_owner_kind text, p_after_owner_id uuid, p_after_permission_id uuid, p_page_size integer) IS 'Returns one bounded current permission-catalogue page without internal registration evidence.';


--
-- Name: list_organization_permissions_projection(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.list_organization_permissions_projection(
  p_record_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  record_id uuid,
  revision bigint,
  attribute_values jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope_row record;
begin
  -- The projection keeps today's row visibility inside itself: the same fixed
  -- platform.organization.permissions.read decision the bespoke permission
  -- catalogue administration reader applies is the only visibility, and the
  -- caller's current organisation is never an input. A viewer the decision
  -- refuses sees no rows, exactly as a missing or foreign record, so the record
  -- adapters return their identical refusal and a list page is empty rather than
  -- failing. A permission identity is unique only within its registration and
  -- owner, so the record identity is a stable version-8 UUID derived from the
  -- exact owner-qualified declaration (registration kind and owner, owner kind
  -- and owner, permission): two owners declaring the same permission identity
  -- stay two distinct records, and a new registration revision keeps the record
  -- identity. The revision is the active catalogue registration revision and the
  -- attribute names are the lowercase field keys a projection record type
  -- declares. Registration provenance, fingerprints, record-scope evidence and
  -- audit columns stay in the protected storage and are never projected.
  begin
    select authorized.* into strict scope_row
    from vortex_access.organization_permissions_administration_scope() as authorized;
  exception
    when insufficient_privilege then
      return;
  end;
  return query
  select
    scope_row.organization_id,
    projected.record_id,
    projected.registration_revision,
    projected.attribute_values
  from (
    select
      (
        pg_catalog.substr(derived.hash_hex, 1, 8) || '-'
        || pg_catalog.substr(derived.hash_hex, 9, 4) || '-'
        || '8' || pg_catalog.substr(derived.hash_hex, 14, 3) || '-'
        || pg_catalog.substr(
             '89ab',
             1 + ((pg_catalog.strpos(
               '0123456789abcdef', pg_catalog.substr(derived.hash_hex, 17, 1)
             ) - 1) % 4),
             1
           ) || pg_catalog.substr(derived.hash_hex, 18, 3) || '-'
        || pg_catalog.substr(derived.hash_hex, 21, 12)
      )::uuid as record_id,
      entry.registration_revision,
      pg_catalog.jsonb_build_object(
        'key', entry.permission_key,
        'label', entry.label,
        'description', entry.description,
        'owner_kind', entry.owner_kind,
        'action_kind', entry.action_kind,
        'named_action', entry.named_action,
        'administrative', entry.administrative
      ) as attribute_values
    from vortex_access.permission_catalogue_entries as entry
    join vortex_access.permission_registrations as registration
      on registration.organization_id = entry.organization_id
      and registration.registration_kind = entry.registration_kind
      and registration.registration_owner_id = entry.registration_owner_id
      and registration.revision = entry.registration_revision
    cross join lateral (
      select pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(
          'vortex.permission_projection' || E'\x1f'
            || entry.organization_id::text || E'\x1f'
            || entry.registration_kind || E'\x1f'
            || entry.registration_owner_id::text || E'\x1f'
            || entry.owner_kind || E'\x1f'
            || entry.owner_id::text || E'\x1f'
            || entry.permission_id::text,
          'UTF8'
        )),
        'hex'
      ) as hash_hex
    ) as derived
    where entry.organization_id = scope_row.organization_id
      and registration.state = 'active'
  ) as projected
  where p_record_id is null or p_record_id = projected.record_id
  order by projected.record_id;
end
$function$;


ALTER FUNCTION vortex_access.list_organization_permissions_projection(p_record_id uuid, p_page_size integer) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION list_organization_permissions_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.list_organization_permissions_projection(p_record_id uuid, p_page_size integer) IS 'Registered permission projection: returns every current registered permission catalogue entry the fixed platform.organization.permissions.read decision admits, with the organisation, a stable record identity derived from the exact owner-qualified permission, the active registration revision and the safe projected attribute values keyed by lowercase field key, or no row when the decision refuses the viewer. Registration provenance, fingerprints, record-scope evidence and audit columns are never projected.';


--
-- Name: list_organization_role_activations_for_administration(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.list_organization_role_activations_for_administration(p_after_role_activation_id uuid, p_page_size integer) RETURNS TABLE(organization_id uuid, activations jsonb, next_after_role_activation_id uuid, access_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scope record;
  checked_at timestamptz;
  activation_items jsonb;
  page_activation_ids uuid[];
  candidate_count integer;
begin
  if p_page_size is null or p_page_size not between 1 and 100
    or p_after_role_activation_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization role activation page input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_assignment_ledger_administration_scope()
    as authorized;
  checked_at := pg_catalog.clock_timestamp();

  with candidates as (
    select activation.role_activation_id,
      activation.organization_account_id, account.display_name,
      activation.role_id, role_revision.role_key, role_revision.label,
      role_revision.lifecycle, activation.revision,
      activation.historical_role_revision,
      activation.eligibility_source_kind, activation.activated_at,
      activation.expires_at, activation.state,
      case
        when activation.state = 'revoked' then 'revoked'
        when activation.expires_at <= checked_at then 'expired'
        else 'active'
      end as temporal_state,
      pg_catalog.row_number() over (
        order by activation.role_activation_id
      ) as ordinal
    from vortex_access.organization_role_activations as activation
    join vortex_identity.organization_accounts as account
      on account.organization_id = activation.organization_id
      and account.organization_account_id = activation.organization_account_id
    join vortex_access.organization_roles as role
      on role.organization_id = activation.organization_id
      and role.role_id = activation.role_id
    join vortex_access.organization_role_revisions as role_revision
      on role_revision.organization_id = role.organization_id
      and role_revision.role_id = role.role_id
      and role_revision.revision = role.live_revision
    where activation.organization_id = scope.organization_id
      and (
        p_after_role_activation_id is null
        or activation.role_activation_id > p_after_role_activation_id
      )
    order by activation.role_activation_id
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'roleActivationId', candidate.role_activation_id,
          'beneficiary', pg_catalog.jsonb_build_object(
            'organizationAccountId', candidate.organization_account_id,
            'displayName', candidate.display_name
          ),
          'role', pg_catalog.jsonb_build_object(
            'roleId', candidate.role_id,
            'key', candidate.role_key,
            'label', candidate.label,
            'lifecycle', candidate.lifecycle
          ),
          'revision', candidate.revision,
          'historicalRoleRevision', candidate.historical_role_revision,
          'eligibilitySourceKind', candidate.eligibility_source_kind,
          'activatedAt', candidate.activated_at,
          'expiresAt', candidate.expires_at,
          'state', candidate.state,
          'temporalState', candidate.temporal_state
        ) order by candidate.role_activation_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.role_activation_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into activation_items, page_activation_ids, candidate_count
  from candidates as candidate;

  return query select scope.organization_id, activation_items,
    case when candidate_count > p_page_size
      then page_activation_ids[p_page_size] else null end,
    scope.access_version;
end
$$;


