declare
  scope record;
  checked_at timestamptz;
  assignment_items jsonb;
  page_assignment_ids uuid[];
  candidate_count integer;
begin
  if p_page_size is null or p_page_size not between 1 and 100
    or p_after_role_assignment_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization role assignment page input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_assignment_ledger_administration_scope()
    as authorized;
  checked_at := pg_catalog.clock_timestamp();

  with candidates as (
    select assignment.role_assignment_id, assignment.assignment_kind,
      assignment.revision, assignment.starts_at, assignment.expires_at,
      assignment.state, role.role_id, revision.role_key, revision.label,
      revision.lifecycle, assignment.assignee_kind,
      assignment.organization_account_id, account.display_name,
      assignment.group_id, organization_group.group_key,
      organization_group.label as group_label,
      organization_group.state as group_state,
      case
        when assignment.state = 'revoked' then 'revoked'
        when assignment.starts_at > checked_at then 'scheduled'
        when assignment.expires_at is not null
          and assignment.expires_at <= checked_at then 'expired'
        else 'active'
      end as temporal_state,
      pg_catalog.row_number() over (
        order by assignment.role_assignment_id
      ) as ordinal
    from vortex_access.organization_role_assignments as assignment
    join vortex_access.organization_roles as role
      on role.organization_id = assignment.organization_id
      and role.role_id = assignment.role_id
    join vortex_access.organization_role_revisions as revision
      on revision.organization_id = role.organization_id
      and revision.role_id = role.role_id
      and revision.revision = role.live_revision
    left join vortex_identity.organization_accounts as account
      on assignment.assignee_kind = 'organization_account'
      and account.organization_id = assignment.organization_id
      and account.organization_account_id = assignment.organization_account_id
    left join vortex_access.organization_groups as organization_group
      on assignment.assignee_kind = 'group'
      and organization_group.organization_id = assignment.organization_id
      and organization_group.group_id = assignment.group_id
    where assignment.organization_id = scope.organization_id
      and (
        p_after_role_assignment_id is null
        or assignment.role_assignment_id > p_after_role_assignment_id
      )
    order by assignment.role_assignment_id
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'roleAssignmentId', candidate.role_assignment_id,
          'role', pg_catalog.jsonb_build_object(
            'roleId', candidate.role_id,
            'key', candidate.role_key,
            'label', candidate.label,
            'lifecycle', candidate.lifecycle
          ),
          'assignee', case candidate.assignee_kind
            when 'organization_account' then pg_catalog.jsonb_build_object(
              'kind', 'organization_account',
              'organizationAccountId', candidate.organization_account_id,
              'displayName', candidate.display_name
            )
            else pg_catalog.jsonb_build_object(
              'kind', 'group',
              'groupId', candidate.group_id,
              'key', candidate.group_key,
              'label', candidate.group_label,
              'state', candidate.group_state
            )
          end,
          'assignmentKind', candidate.assignment_kind,
          'revision', candidate.revision,
          'startsAt', candidate.starts_at,
          'expiresAt', candidate.expires_at,
          'state', candidate.state,
          'temporalState', candidate.temporal_state
        )) order by candidate.role_assignment_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.role_assignment_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into assignment_items, page_assignment_ids, candidate_count
  from candidates as candidate;

  return query select scope.organization_id, assignment_items,
    case when candidate_count > p_page_size
      then page_assignment_ids[p_page_size] else null end,
    scope.access_version;
end
$$;


ALTER FUNCTION vortex_access.list_organization_role_assignments_for_administration(p_after_role_assignment_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_organization_role_assignments_for_administration(p_after_role_assignment_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_organization_role_assignments_for_administration(p_after_role_assignment_id uuid, p_page_size integer) IS 'Returns one bounded role-assignment page with descriptive window state, not effective permission.';


--
-- Name: list_organization_role_assignments_projection(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_organization_role_assignments_projection(
  p_record_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  record_id uuid,
  revision bigint,
  attribute_values jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope_row record;
  checked_at timestamptz;
begin
  -- The projection keeps today's row visibility inside itself: the same fixed
  -- platform.organization.assignments.read decision the bespoke assignment
  -- ledger administration reader applies is the only visibility, and the
  -- caller's current organisation is never an input. A viewer the decision
  -- refuses sees no rows, exactly as a missing or foreign record, so the record
  -- adapters return their identical refusal and a list page is empty rather than
  -- failing. The record identity is the assignment, the revision is the
  -- assignment's own revision and the attribute names are the lowercase field
  -- keys a projection record type declares. The temporal state is descriptive
  -- and grants no permission; grant and revocation evidence is never projected.
  begin
    select authorized.* into strict scope_row
    from vortex_access.organization_assignment_ledger_administration_scope() as authorized;
  exception
    when insufficient_privilege then
      return;
  end;
  checked_at := pg_catalog.statement_timestamp();
  return query
  select
    scope_row.organization_id,
    assignment.role_assignment_id,
    assignment.revision,
    pg_catalog.jsonb_build_object(
      'role_id', assignment.role_id,
      'role_key', role_revision.role_key,
      'role_label', role_revision.label,
      'assignee_kind', assignment.assignee_kind,
      'organization_account_id', assignment.organization_account_id,
      'group_id', assignment.group_id,
      'assignment_kind', assignment.assignment_kind,
      'starts_at', assignment.starts_at,
      'expires_at', assignment.expires_at,
      'state', assignment.state,
      'temporal_state', case
        when assignment.state = 'revoked' then 'revoked'
        when assignment.starts_at > checked_at then 'scheduled'
        when assignment.expires_at is not null
          and assignment.expires_at <= checked_at then 'expired'
        else 'active'
      end
    )
  from vortex_access.organization_role_assignments as assignment
  join vortex_access.organization_roles as role
    on role.organization_id = assignment.organization_id
    and role.role_id = assignment.role_id
  join vortex_access.organization_role_revisions as role_revision
    on role_revision.organization_id = role.organization_id
    and role_revision.role_id = role.role_id
    and role_revision.revision = role.live_revision
  where assignment.organization_id = scope_row.organization_id
    and (p_record_id is null or p_record_id = assignment.role_assignment_id)
  order by assignment.role_assignment_id;
end
$function$;


ALTER FUNCTION vortex_access.list_organization_role_assignments_projection(p_record_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_organization_role_assignments_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_organization_role_assignments_projection(p_record_id uuid, p_page_size integer) IS 'Registered role-assignment projection: returns every standing or eligible assignment of the viewer''s organisation, whether active, scheduled, expired or revoked, under the fixed platform.organization.assignments.read decision, with the organisation, the assignment identity, the assignment revision and the safe projected attribute values keyed by lowercase field key, or no row when the decision refuses the viewer. Grant and revocation evidence is never projected.';


--
-- Name: list_organization_roles_for_administration(uuid, integer); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.list_organization_roles_for_administration(
  p_after_role_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  roles jsonb,
  next_after_role_id uuid,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  role_items jsonb;
  page_role_ids uuid[];
  candidate_count integer;
begin
  if p_page_size is null or p_page_size not between 1 and 100
    or p_after_role_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization role page input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_roles_administration_scope() as authorized;

  with candidates as (
    select role.role_id, role.role_kind, role.application_root_id,
      role.source_role_id, revision.role_key, revision.label,
      revision.lifecycle, revision.revision, revision.privilege_classification,
      revision.assignment_policy, policy.maximum_activation_duration_seconds,
      policy.reason_required, policy.authentication_requirement,
      policy.authentication_maximum_age_seconds,
      policy.required_caller_execution_binding_id,
      (
        select pg_catalog.count(*)
        from vortex_access.organization_role_permission_entries as permission
        where permission.organization_id = revision.organization_id
          and permission.role_id = revision.role_id
          and permission.role_revision = revision.revision
      ) as accepted_permission_count,
      pg_catalog.row_number() over (order by role.role_id) as ordinal
    from vortex_access.organization_roles as role
    join vortex_access.organization_role_revisions as revision
      on revision.organization_id = role.organization_id
      and revision.role_id = role.role_id
      and revision.revision = role.live_revision
    left join vortex_access.organization_role_activation_policy_revisions as policy
      on policy.organization_id = revision.organization_id
      and policy.role_id = revision.role_id
      and policy.activation_policy_id = revision.activation_policy_id
      and policy.revision = revision.activation_policy_revision
      and policy.policy_fingerprint = revision.activation_policy_fingerprint
    where role.organization_id = scope.organization_id
      and (p_after_role_id is null or role.role_id > p_after_role_id)
    order by role.role_id
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'roleId', candidate.role_id,
          'key', candidate.role_key,
          'label', candidate.label,
          'roleKind', candidate.role_kind,
          'lifecycle', candidate.lifecycle,
          'liveRevision', candidate.revision,
          'privilegeClassification', candidate.privilege_classification,
          'assignmentPolicy', case candidate.assignment_policy
            when 'standing' then pg_catalog.jsonb_build_object('kind', 'standing')
            else pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
              'kind', 'activation_required',
              'maximumActivationDurationSeconds',
                candidate.maximum_activation_duration_seconds,
              'reasonRequired', candidate.reason_required,
              'recentAuthentication', case candidate.authentication_requirement
                when 'none' then pg_catalog.jsonb_build_object('kind', 'none')
                else pg_catalog.jsonb_build_object(
                  'kind', candidate.authentication_requirement,
                  'maximumAgeSeconds', candidate.authentication_maximum_age_seconds
                )
              end,
              'requiredCallerExecutionBindingId',
                candidate.required_caller_execution_binding_id
            ))
          end,
          'source', case candidate.role_kind
            when 'custom' then pg_catalog.jsonb_build_object('kind', 'custom')
            else pg_catalog.jsonb_build_object(
              'kind', 'application',
              'applicationRootId', candidate.application_root_id,
              'sourceRoleId', candidate.source_role_id
            )
          end,
          'acceptedPermissionCount', candidate.accepted_permission_count
        ) order by candidate.role_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.role_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into role_items, page_role_ids, candidate_count
  from candidates as candidate;

  return query select scope.organization_id, role_items,
    case when candidate_count > p_page_size
      then page_role_ids[p_page_size] else null end,
    scope.access_version;
end
$function$;


