-- Name: FUNCTION list_organization_runtime_settings_projection(p_record_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.list_organization_runtime_settings_projection(p_record_id uuid, p_page_size integer) IS 'Registered organisation runtime-settings projection: returns the one settings row the current viewer may read under the fixed runtime-settings decision, with the organisation, the record identity, the settings revision and the safe projected attribute values keyed by lowercase field key, or no row when the decision refuses the viewer or no settings exist.';


--
-- Name: lock_active_record_ownership_target_internal(text, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.lock_active_record_ownership_target_internal(
  p_kind text,
  p_target_id uuid
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  matched boolean;
begin
  if p_kind is null
    or p_kind not in ('organization_account', 'group')
    or p_target_id is null
    or p_target_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return false;
  end if;
  context_value := vortex_access.validated_human_request_context();
  if p_kind = 'organization_account' then
    select true into matched
    from vortex_identity.organization_accounts as account
    join vortex_identity.identity_projections as projection
      on projection.identity_id = account.identity_id
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where account.organization_id = (context_value ->> 'organizationId')::uuid
      and account.organization_account_id = p_target_id
      and account.state = 'active'
      and projection.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
    for share of account, projection;
  else
    select true into matched
    from vortex_access.organization_groups as organization_group
    where organization_group.organization_id = (context_value ->> 'organizationId')::uuid
      and organization_group.group_id = p_target_id
      and organization_group.state = 'active'
    for share of organization_group;
  end if;
  return coalesce(matched, false);
end
$function$;


