--
-- Name: lock_effective_capability_policy(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.lock_effective_capability_policy(
  p_tenant_id uuid,
  p_organization_id uuid,
  p_capability_key text,
  p_unit text,
  p_evaluated_at timestamptz
)
returns table (
  request_organization_id uuid,
  correlation_id uuid,
  request_expires_at timestamptz,
  applied_scope text,
  assignment_organization_id uuid,
  policy_id uuid,
  policy_revision bigint,
  assignment_id uuid,
  assignment_revision bigint,
  quantity_limit numeric,
  assignment_expires_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  protected_context record;
  selected record;
begin
  if not vortex_access.capability_policy_key_is_valid(p_capability_key)
    or not vortex_access.capability_policy_unit_is_valid(p_unit)
    or p_evaluated_at is null
    or p_evaluated_at in ('-infinity'::timestamptz, 'infinity'::timestamptz) then
    raise exception using errcode = '22023', message = 'Capability reservation policy request is invalid';
  end if;
  select context.* into strict protected_context
  from vortex_access.capability_reservation_request_context(
    p_tenant_id, p_organization_id
  ) as context;
  -- The same rule as the read path: the lowest of the live platform ceiling
  -- and the tenant and organisation allocations, the narrower scope on a tie.
  select bound.* into selected
  from vortex_access.capability_limit_bounds_internal(
    p_tenant_id, protected_context.request_organization_id, p_capability_key, p_unit,
    p_evaluated_at, true
  ) as bound
  order by bound.quantity_limit, bound.precedence
  limit 1;
  if not found then return; end if;
  return query select protected_context.request_organization_id,
    protected_context.correlation_id, protected_context.request_expires_at,
    selected.applied_scope, selected.assignment_organization_id,
    selected.policy_id, selected.policy_revision, selected.assignment_id,
    selected.assignment_revision, selected.quantity_limit, selected.expires_at;
end
$function$;


ALTER FUNCTION vortex_access.lock_effective_capability_policy(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_evaluated_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION lock_effective_capability_policy(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_evaluated_at timestamp with time zone); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.lock_effective_capability_policy(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_evaluated_at timestamp with time zone) IS 'Locks the live platform ceiling and the tenant and organisation allocations for the scope, then returns the lowest of them as the effective limit; an allocation can only narrow the ceiling.';


--
-- Name: lock_human_request_access_version_internal(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.lock_human_request_access_version_internal()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_context jsonb;
  rechecked_context jsonb;
  locked_access_version bigint;
begin
  initial_context := vortex_access.validated_human_request_context();
  if pg_catalog.jsonb_typeof(initial_context) is distinct from 'object'
    or not (initial_context ?& array[
      'callerKind', 'tenantId', 'organizationId', 'organizationAccountId',
      'applicationRootId', 'accessVersion', 'correlationId'
    ])
    or initial_context ->> 'callerKind' is distinct from 'human'
    or not vortex_context.is_non_nil_uuid(initial_context ->> 'tenantId')
    or not vortex_context.is_non_nil_uuid(initial_context ->> 'organizationId')
    or not vortex_context.is_non_nil_uuid(initial_context ->> 'organizationAccountId')
    or not vortex_context.is_non_nil_uuid(initial_context ->> 'applicationRootId')
    or not vortex_context.is_non_nil_uuid(initial_context ->> 'correlationId')
    or not pg_catalog.pg_input_is_valid(initial_context ->> 'accessVersion', 'bigint')
    or (initial_context ->> 'accessVersion')::bigint not between 1 and 9007199254740991 then
    raise exception using errcode = '42501',
      message = 'Human ownership transfer access scope is unavailable';
  end if;

  select version.current_version into locked_access_version
  from vortex_access.organization_access_versions as version
  join vortex_identity.organizations as organization
    on organization.organization_id = version.organization_id
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  where version.organization_id = (initial_context ->> 'organizationId')::uuid
    and organization.tenant_id = (initial_context ->> 'tenantId')::uuid
    and organization.state = 'active'
    and tenant.state = 'active'
  for share of version;

  if not found then
    raise exception using errcode = '42501',
      message = 'Human ownership transfer access scope is unavailable';
  end if;
  if locked_access_version is distinct from (initial_context ->> 'accessVersion')::bigint then
    raise exception using errcode = '40001',
      message = 'Human ownership transfer access version changed';
  end if;

  rechecked_context := vortex_access.validated_human_request_context();
  if rechecked_context is distinct from initial_context then
    raise exception using errcode = '40001',
      message = 'Human ownership transfer context changed while acquiring access lock';
  end if;

  return initial_context;
end
$function$;


ALTER FUNCTION vortex_access.lock_human_request_access_version_internal() OWNER TO postgres;

--
-- Name: FUNCTION lock_human_request_access_version_internal(); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.lock_human_request_access_version_internal() IS 'Locks the exact active Human organization access version with a shared row lock and revalidates the full original request context.';


--
-- Name: lock_organization_runtime_settings_record_for_event_internal(uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.lock_organization_runtime_settings_record_for_event_internal(
  p_record_id uuid
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  locked_organization_id uuid;
begin
  if p_record_id is null
    or p_record_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return false;
  end if;

  context_value := vortex_access.validated_human_request_context();
  if context_value ->> 'callerKind' is distinct from 'human'
    or not context_value ?& array[
      'organizationId', 'applicationRootId', 'organizationAccountId', 'correlationId'
    ]
    or p_record_id is distinct from (context_value ->> 'organizationId')::uuid
    or not vortex_access.organization_runtime_settings_manage_is_current() then
    return false;
  end if;

  select settings.organization_id into locked_organization_id
  from vortex_identity.organization_runtime_settings as settings
  where settings.organization_id = p_record_id
  for update;
  return found and locked_organization_id = p_record_id;
exception
  when no_data_found or too_many_rows or insufficient_privilege
    or object_not_in_prerequisite_state or invalid_text_representation then
    return false;
end
$function$;


ALTER FUNCTION vortex_access.lock_organization_runtime_settings_record_for_event_internal(p_record_id uuid) OWNER TO postgres;

