--
-- Name: lock_system_projection_link_target_internal(text, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.lock_system_projection_link_target_internal(
  p_protected_read_model_key text,
  p_target_record_id uuid,
  p_organization_id uuid
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  matched boolean;
begin
  if p_protected_read_model_key is null
    or p_protected_read_model_key not in ('organization_accounts', 'groups')
    or p_target_record_id is null
    or p_target_record_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return false;
  end if;

  context_value := vortex_access.validated_human_request_context();
  if (context_value ->> 'organizationId')::uuid is distinct from p_organization_id
    or not exists (
      select 1
      from vortex_record.protected_read_model_views as registered
      where registered.protected_read_model_key = p_protected_read_model_key
        and (
          (p_protected_read_model_key = 'organization_accounts'
            and registered.reader_schema = 'vortex_access'
            and registered.reader_function = 'list_organization_accounts_projection')
          or (p_protected_read_model_key = 'groups'
            and registered.reader_schema = 'vortex_access'
            and registered.reader_function = 'list_organization_groups_projection')
        )
    ) then
    return false;
  end if;

  if p_protected_read_model_key = 'organization_accounts' then
    select true into matched
    from vortex_identity.organization_accounts as account
    join vortex_identity.identity_projections as projection
      on projection.identity_id = account.identity_id
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where account.organization_id = p_organization_id
      and account.organization_account_id = p_target_record_id
      and account.state = 'active'
      and projection.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
    for share of account, projection;
  else
    select true into matched
    from vortex_access.organization_groups as organization_group
    join vortex_identity.organizations as organization
      on organization.organization_id = organization_group.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where organization_group.organization_id = p_organization_id
      and organization_group.group_id = p_target_record_id
      and organization_group.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
    for share of organization_group;
  end if;

  return coalesce(matched, false);
end
$function$;


ALTER FUNCTION vortex_access.lock_system_projection_link_target_internal(p_protected_read_model_key text, p_target_record_id uuid, p_organization_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION lock_system_projection_link_target_internal(p_protected_read_model_key text, p_target_record_id uuid, p_organization_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.lock_system_projection_link_target_internal(p_protected_read_model_key text, p_target_record_id uuid, p_organization_id uuid) IS 'Private protected system-projection link lock: share-locks only an active same-organisation People account and its active identity projection, or an active Group, after confirming the registered reader and current organisation; read authority remains with the Record access decision.';


--
-- Name: metering_event_dimensions_are_valid(jsonb); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.metering_event_dimensions_are_valid(p_dimensions jsonb)
returns boolean
language sql
stable
strict
security invoker
set search_path = ''
as $function$
  select pg_catalog.jsonb_typeof(p_dimensions) = 'object'
    and pg_catalog.pg_column_size(p_dimensions) <= 4096
    and (
      select pg_catalog.count(*)
      from pg_catalog.jsonb_object_keys(p_dimensions)
    ) <= 16
    and not exists (
      select 1
      from pg_catalog.jsonb_each(p_dimensions) as entry(key, value)
      where pg_catalog.length(entry.key) > 40
        or entry.key !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
        or pg_catalog.string_to_array(entry.key, '_')
          && vortex_access.validation_reference_list('metering_forbidden_dimension_word')
        or not (
          (pg_catalog.jsonb_typeof(entry.value) = 'string'
            and pg_catalog.length(entry.value #>> '{}') between 1 and 120
            and (entry.value #>> '{}') ~ '^[a-z0-9](?:[a-z0-9_.:-]*[a-z0-9])?$')
          or pg_catalog.jsonb_typeof(entry.value) = 'boolean'
          or (pg_catalog.jsonb_typeof(entry.value) = 'number'
            and (entry.value #>> '{}') ~ '^-?[0-9]+$'
            and (entry.value #>> '{}')::numeric
              between -9007199254740991 and 9007199254740991)
        )
    );
$function$;


ALTER FUNCTION vortex_access.metering_event_dimensions_are_valid(p_dimensions jsonb) OWNER TO postgres;

--
-- Name: FUNCTION metering_event_dimensions_are_valid(p_dimensions jsonb); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.metering_event_dimensions_are_valid(p_dimensions jsonb) IS 'Storage check for safe metering dimensions: a small flat map of bounded scalars whose keys name no word in the metering_forbidden_dimension_word reference list.';


--
-- Name: organization_account_has_current_application_access_internal(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.organization_account_has_current_application_access_internal(
  p_organization_id uuid,
  p_organization_account_id uuid,
  p_application_root_id uuid
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  checked_at timestamptz := pg_catalog.clock_timestamp();
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_organization_account_id is null
    or p_organization_account_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return false;
  end if;

  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId'
    or (context_value ->> 'expiresAt')::timestamptz <= checked_at
    or (context_value ->> 'organizationId')::uuid is distinct from p_organization_id
    or (context_value ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    return false;
  end if;

  -- The Record writer invokes this helper only after locking the exact active
  -- organisation-account projection and its active identity in this organisation.
  return exists (
    with current_roles as (
      select role.role_id, role.source_role_id, revision.assignment_policy,
        revision.authority_continuity_revision,
        revision.policy_continuity_revision, revision.activation_policy_id,
        revision.activation_policy_revision, revision.activation_policy_fingerprint
      from vortex_access.organization_roles as role
      join vortex_access.organization_role_revisions as revision
        on revision.organization_id = role.organization_id
        and revision.role_id = role.role_id
        and revision.revision = role.live_revision
      where role.organization_id = p_organization_id
        and role.application_root_id = p_application_root_id
        and role.role_kind = 'application'
        and revision.lifecycle in ('active', 'acceptance_required')
    ), active_roles as (
      select role.source_role_id
      from current_roles as role
      join vortex_access.organization_role_assignments as assignment
        on assignment.organization_id = p_organization_id
        and assignment.role_id = role.role_id
        and assignment.assignee_kind = 'organization_account'
        and assignment.organization_account_id = p_organization_account_id
        and assignment.assignment_kind = 'standing'
        and assignment.state = 'live'
        and assignment.starts_at <= checked_at
        and (assignment.expires_at is null or assignment.expires_at > checked_at)
      where role.assignment_policy = 'standing'

      union

      select role.source_role_id
      from current_roles as role
      join vortex_access.organization_role_assignments as assignment
        on assignment.organization_id = p_organization_id
        and assignment.role_id = role.role_id
        and assignment.assignee_kind = 'group'
        and assignment.assignment_kind = 'standing'
        and assignment.state = 'live'
        and assignment.starts_at <= checked_at
        and (assignment.expires_at is null or assignment.expires_at > checked_at)
      join vortex_access.organization_groups as organization_group
        on organization_group.organization_id = assignment.organization_id
        and organization_group.group_id = assignment.group_id
        and organization_group.state = 'active'
      join vortex_access.organization_group_memberships as membership
        on membership.organization_id = assignment.organization_id
        and membership.group_id = assignment.group_id
        and membership.organization_account_id = p_organization_account_id
        and membership.state = 'live'
        and membership.starts_at <= checked_at
        and (membership.expires_at is null or membership.expires_at > checked_at)
      where role.assignment_policy = 'standing'

      union

      select role.source_role_id
      from current_roles as role
      join vortex_access.organization_role_assignments as assignment
        on assignment.organization_id = p_organization_id
        and assignment.role_id = role.role_id
        and assignment.assignee_kind = 'organization_account'
        and assignment.organization_account_id = p_organization_account_id
        and assignment.assignment_kind = 'eligible'
        and assignment.state = 'live'
        and assignment.starts_at <= checked_at
        and (assignment.expires_at is null or assignment.expires_at > checked_at)
      join vortex_access.organization_role_activations as activation
        on activation.organization_id = assignment.organization_id
        and activation.organization_account_id = p_organization_account_id
        and activation.role_id = assignment.role_id
        and activation.eligibility_source_kind = 'direct'
        and activation.role_assignment_id = assignment.role_assignment_id
        and activation.role_assignment_revision = assignment.revision
        and activation.state = 'live'
        and activation.activated_at <= checked_at
        and activation.expires_at > checked_at
        and activation.authority_continuity_revision = role.authority_continuity_revision
        and activation.policy_continuity_revision = role.policy_continuity_revision
        and activation.activation_policy_id = role.activation_policy_id
        and activation.activation_policy_revision = role.activation_policy_revision
        and activation.activation_policy_fingerprint = role.activation_policy_fingerprint
      where role.assignment_policy = 'activation_required'

      union

      select role.source_role_id
      from current_roles as role
      join vortex_access.organization_role_assignments as assignment
        on assignment.organization_id = p_organization_id
        and assignment.role_id = role.role_id
        and assignment.assignee_kind = 'group'
        and assignment.assignment_kind = 'eligible'
        and assignment.state = 'live'
        and assignment.starts_at <= checked_at
        and (assignment.expires_at is null or assignment.expires_at > checked_at)
      join vortex_access.organization_groups as organization_group
        on organization_group.organization_id = assignment.organization_id
        and organization_group.group_id = assignment.group_id
        and organization_group.state = 'active'
      join vortex_access.organization_role_activations as activation
        on activation.organization_id = assignment.organization_id
        and activation.organization_account_id = p_organization_account_id
        and activation.role_id = assignment.role_id
        and activation.eligibility_source_kind = 'group'
        and activation.role_assignment_id = assignment.role_assignment_id
        and activation.role_assignment_revision = assignment.revision
        and activation.state = 'live'
        and activation.activated_at <= checked_at
        and activation.expires_at > checked_at
        and activation.authority_continuity_revision = role.authority_continuity_revision
        and activation.policy_continuity_revision = role.policy_continuity_revision
        and activation.activation_policy_id = role.activation_policy_id
        and activation.activation_policy_revision = role.activation_policy_revision
        and activation.activation_policy_fingerprint = role.activation_policy_fingerprint
      join vortex_access.organization_group_memberships as membership
        on membership.organization_id = assignment.organization_id
        and membership.group_id = assignment.group_id
        and membership.organization_account_id = p_organization_account_id
        and membership.membership_id = activation.membership_id
        and membership.revision = activation.membership_revision
        and membership.state = 'live'
        and membership.starts_at <= checked_at
        and (membership.expires_at is null or membership.expires_at > checked_at)
      where role.assignment_policy = 'activation_required'
    )
    select 1 from active_roles
  );
end
$function$;


