--

COMMENT ON FUNCTION vortex_access.platform_permission_catalogue_revision_is_exact_v1_4_0(p_organization_id uuid, p_registration_revision bigint) IS 'Owner-only fixed evidence assertion for exact platform catalogue revision 6 (1.4.0), which adds the four builder permissions to revision 5.';


--
-- Name: private_current_role_management_scope(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.private_current_role_management_scope(p_organization_id uuid, p_role_id uuid, p_role_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  permissions jsonb;
begin
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'applicationRootId', permission.application_root_id,
      'ownerKind', permission.owner_kind,
      'ownerId', permission.owner_id,
      'permissionId', permission.permission_id
    )) order by permission.application_root_id nulls first,
      permission.owner_kind collate "C", permission.owner_id,
      permission.permission_id
  ), '[]'::jsonb)
  into permissions
  from vortex_access.organization_role_permission_entries as permission
  where permission.organization_id = p_organization_id
    and permission.role_id = p_role_id
    and permission.role_revision = p_role_revision;

  if pg_catalog.jsonb_array_length(permissions) = 0 then
    return pg_catalog.jsonb_build_object('kind', 'none');
  end if;
  return pg_catalog.jsonb_build_object(
    'kind', 'bounded', 'permissions', permissions
  );
end
$$;


ALTER FUNCTION vortex_access.private_current_role_management_scope(p_organization_id uuid, p_role_id uuid, p_role_revision bigint) OWNER TO postgres;

--
-- Name: private_management_scope_from_permission_evidence(jsonb); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.private_management_scope_from_permission_evidence(p_permissions jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  projected jsonb;
begin
  if p_permissions is null
    or pg_catalog.jsonb_typeof(p_permissions) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Private management permission evidence is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_permissions) = 0 then
    return pg_catalog.jsonb_build_object('kind', 'none');
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_permissions) as item(value)
    where (
      pg_catalog.jsonb_typeof(item.value) = 'object'
      and item.value ?& array['ownerKind', 'ownerId', 'permissionId']
      and pg_catalog.jsonb_typeof(item.value -> 'ownerKind') = 'string'
      and item.value ->> 'ownerKind' in ('platform', 'application', 'module')
      and pg_catalog.jsonb_typeof(item.value -> 'ownerId') = 'string'
      and vortex_context.is_non_nil_uuid(item.value ->> 'ownerId')
      and pg_catalog.jsonb_typeof(item.value -> 'permissionId') = 'string'
      and vortex_context.is_non_nil_uuid(item.value ->> 'permissionId')
      and (
        (
          item.value ->> 'ownerKind' = 'platform'
          and not item.value ? 'applicationRootId'
        ) or (
          item.value ->> 'ownerKind' in ('application', 'module')
          and pg_catalog.jsonb_typeof(item.value -> 'applicationRootId') = 'string'
          and vortex_context.is_non_nil_uuid(item.value ->> 'applicationRootId')
          and (
            item.value ->> 'ownerKind' <> 'application'
            or (item.value ->> 'ownerId')::uuid =
              (item.value ->> 'applicationRootId')::uuid
          )
        )
      )
    ) is not true
  ) then
    raise exception using errcode = '22023',
      message = 'Private management permission evidence is invalid';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_strip_nulls(
    pg_catalog.jsonb_build_object(
      'applicationRootId', parsed.application_root_id,
      'ownerKind', parsed.owner_kind,
      'ownerId', parsed.owner_id,
      'permissionId', parsed.permission_id
    )
  ) order by parsed.application_root_id nulls first,
    parsed.owner_kind collate "C", parsed.owner_id, parsed.permission_id)
  into projected
  from (
    select distinct
      case when item.value ->> 'ownerKind' = 'platform' then null::uuid
        else (item.value ->> 'applicationRootId')::uuid end as application_root_id,
      item.value ->> 'ownerKind' as owner_kind,
      (item.value ->> 'ownerId')::uuid as owner_id,
      (item.value ->> 'permissionId')::uuid as permission_id
    from pg_catalog.jsonb_array_elements(p_permissions) as item(value)
  ) as parsed;

  return pg_catalog.jsonb_build_object(
    'kind', 'bounded', 'permissions', projected
  );
end
$$;


ALTER FUNCTION vortex_access.private_management_scope_from_permission_evidence(p_permissions jsonb) OWNER TO postgres;

--
-- Name: project_organization_delegation_summary(uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.project_organization_delegation_summary(p_organization_id uuid, p_delegation_authority_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'delegationAuthorityId', delegation.delegation_authority_id,
    'holder', case delegation.holder_kind
      when 'organization_account' then pg_catalog.jsonb_build_object(
        'kind', 'organization_account',
        'organizationAccountId', delegation.organization_account_id,
        'displayName', account.display_name)
      else pg_catalog.jsonb_build_object('kind', 'group',
        'groupId', delegation.group_id, 'key', organization_group.group_key,
        'label', organization_group.label, 'state', organization_group.state) end,
    'scope', case delegation.scope_kind
      when 'organization_catalogue' then pg_catalog.jsonb_build_object(
        'kind', 'organization_catalogue')
      else pg_catalog.jsonb_build_object('kind', 'bounded', 'permissions',
        (select pg_catalog.jsonb_agg(pg_catalog.jsonb_strip_nulls(
          pg_catalog.jsonb_build_object(
            'applicationRootId', permission.value -> 'applicationRootId',
            'ownerKind', permission.value -> 'ownerKind',
            'ownerId', permission.value -> 'ownerId',
            'permissionId', permission.value -> 'permissionId'))
          order by permission.ordinality)
         from pg_catalog.jsonb_array_elements(delegation.bounded_permissions)
           with ordinality as permission(value, ordinality))) end,
    'revision', delegation.revision, 'startsAt', delegation.starts_at,
    'expiresAt', delegation.expires_at, 'state', delegation.state,
    'temporalState', case when delegation.state = 'revoked' then 'revoked'
      when delegation.starts_at > pg_catalog.clock_timestamp() then 'scheduled'
      when delegation.expires_at is not null
        and delegation.expires_at <= pg_catalog.clock_timestamp() then 'expired'
      else 'active' end))
  from vortex_access.organization_delegation_authorities as delegation
  left join vortex_identity.organization_accounts as account
    on delegation.holder_kind = 'organization_account'
    and account.organization_id = delegation.organization_id
    and account.organization_account_id = delegation.organization_account_id
  left join vortex_access.organization_groups as organization_group
    on delegation.holder_kind = 'group'
    and organization_group.organization_id = delegation.organization_id
    and organization_group.group_id = delegation.group_id
  where delegation.organization_id = p_organization_id
    and delegation.delegation_authority_id = p_delegation_authority_id
$$;


ALTER FUNCTION vortex_access.project_organization_delegation_summary(p_organization_id uuid, p_delegation_authority_id uuid) OWNER TO postgres;

--
-- Name: project_organization_role_activation_summary(uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.project_organization_role_activation_summary(p_organization_id uuid, p_role_activation_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'roleActivationId', activation.role_activation_id,
    'beneficiary', pg_catalog.jsonb_build_object(
      'organizationAccountId', activation.organization_account_id,
      'displayName', account.display_name),
    'role', pg_catalog.jsonb_build_object(
      'roleId', activation.role_id, 'key', revision.role_key,
      'label', revision.label, 'lifecycle', revision.lifecycle),
    'revision', activation.revision,
    'historicalRoleRevision', activation.historical_role_revision,
    'eligibilitySourceKind', activation.eligibility_source_kind,
    'activatedAt', activation.activated_at, 'expiresAt', activation.expires_at,
    'state', activation.state,
    'temporalState', case when activation.state = 'revoked' then 'revoked'
      when activation.expires_at <= pg_catalog.clock_timestamp() then 'expired'
      else 'active' end)
  from vortex_access.organization_role_activations as activation
  join vortex_identity.organization_accounts as account
    on account.organization_id = activation.organization_id
    and account.organization_account_id = activation.organization_account_id
  join vortex_access.organization_roles as role
    on role.organization_id = activation.organization_id
    and role.role_id = activation.role_id
  join vortex_access.organization_role_revisions as revision
    on revision.organization_id = role.organization_id
    and revision.role_id = role.role_id and revision.revision = role.live_revision
  where activation.organization_id = p_organization_id
    and activation.role_activation_id = p_role_activation_id
$$;


ALTER FUNCTION vortex_access.project_organization_role_activation_summary(p_organization_id uuid, p_role_activation_id uuid) OWNER TO postgres;

--
-- Name: project_organization_role_change_summary(uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.project_organization_role_change_summary(
  p_organization_id uuid,
  p_role_id uuid
)
returns jsonb
language sql
volatile
security invoker
set search_path = ''
as $function$
  select pg_catalog.jsonb_build_object(
    'roleId', role.role_id,
    'key', revision.role_key,
    'label', revision.label,
    'roleKind', role.role_kind,
    'lifecycle', revision.lifecycle,
    'liveRevision', revision.revision,
    'privilegeClassification', revision.privilege_classification,
    'assignmentPolicy', case revision.assignment_policy
      when 'standing' then pg_catalog.jsonb_build_object('kind', 'standing')
      else pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'kind', 'activation_required',
        'maximumActivationDurationSeconds',
          policy.maximum_activation_duration_seconds,
        'reasonRequired', policy.reason_required,
        'recentAuthentication', case policy.authentication_requirement
          when 'none' then pg_catalog.jsonb_build_object('kind', 'none')
          else pg_catalog.jsonb_build_object(
            'kind', policy.authentication_requirement,
            'maximumAgeSeconds', policy.authentication_maximum_age_seconds
          )
        end,
        'requiredCallerExecutionBindingId', policy.required_caller_execution_binding_id
      ))
    end,
    'source', case role.role_kind
      when 'custom' then pg_catalog.jsonb_build_object('kind', 'custom')
      else pg_catalog.jsonb_build_object(
        'kind', 'application',
        'applicationRootId', role.application_root_id,
        'sourceRoleId', role.source_role_id
      )
    end,
    'acceptedPermissionCount', (
      select pg_catalog.count(*)
      from vortex_access.organization_role_permission_entries as permission
      where permission.organization_id = revision.organization_id
        and permission.role_id = revision.role_id
        and permission.role_revision = revision.revision
    )
  )
  from vortex_access.organization_roles as role
  join vortex_access.organization_role_revisions as revision
    on revision.organization_id = role.organization_id
    and revision.role_id = role.role_id
    and revision.revision = role.live_revision
  left join vortex_access.organization_role_activation_policy_revisions as policy
    on policy.organization_id = revision.organization_id
    and policy.role_id = revision.role_id
    and policy.activation_policy_id = revision.activation_policy_id
    and policy.revision = revision.activation_policy_revision
    and policy.policy_fingerprint = revision.activation_policy_fingerprint
  where role.organization_id = p_organization_id
    and role.role_id = p_role_id
$function$;


ALTER FUNCTION vortex_access.project_organization_role_change_summary(p_organization_id uuid, p_role_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION project_organization_role_change_summary(p_organization_id uuid, p_role_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.project_organization_role_change_summary(p_organization_id uuid, p_role_id uuid) IS 'Private safe current role projection for protected structural changes.';


--
-- Name: propose_record_share_grant_for_administration(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.propose_record_share_grant_for_administration(
  p_grant_id uuid,
  p_consent_request_id uuid,
  p_terms jsonb,
  p_proposal_fingerprint text,
  p_activity_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  context_organization_id uuid;
  context_account_id uuid;
  context_access_version bigint;
  context_correlation_id uuid;
  context_application_root_id uuid;
  locked_access_version bigint;
  cross_organization boolean;
  now_value timestamptz := pg_catalog.statement_timestamp();
  append_result text;
begin
  if p_grant_id is null or p_grant_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_activity_id is null or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_proposal_fingerprint is null or p_proposal_fingerprint !~ '^sha256:[a-f0-9]{64}$'
    or p_terms is null or pg_catalog.jsonb_typeof(p_terms) <> 'object'
    or (p_consent_request_id is not null
      and p_consent_request_id = '00000000-0000-0000-0000-000000000000'::uuid) then
    raise exception using errcode = '22023',
      message = 'Record-share grant proposal is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  context_organization_id := (context_value ->> 'organizationId')::uuid;
  context_account_id := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version := (context_value ->> 'accessVersion')::bigint;
  context_correlation_id := (context_value ->> 'correlationId')::uuid;
  context_application_root_id := case
    when context_value ? 'applicationRootId' then (context_value ->> 'applicationRootId')::uuid
    else null end;
  if context_application_root_id is null then
    raise exception using errcode = '42501',
      message = 'Record-share grant proposal requires an application context';
  end if;

  -- Take the organisation governance lock before evaluating any authority, so a
  -- concurrent authority change cannot land between the check and the write.
  select version.current_version into locked_access_version
  from vortex_access.organization_access_versions as version
  join vortex_identity.organizations as organization
    on organization.organization_id = version.organization_id
  join vortex_identity.tenants as tenant on tenant.tenant_id = organization.tenant_id
  where version.organization_id = context_organization_id
    and organization.state = 'active' and tenant.state = 'active'
  for update of version;
  if not found or locked_access_version is distinct from context_access_version then
    raise exception using errcode = '42501',
      message = 'Record-share grant proposal is unavailable';
  end if;

  perform vortex_access.check_record_share_grant_terms_internal(p_terms, context_value);

  cross_organization := (p_terms ->> 'recipientOrganizationId')::uuid
    <> context_organization_id;
  if cross_organization is distinct from (p_consent_request_id is not null) then
    raise exception using errcode = '22023',
      message = 'Record-share grant proposal is invalid';
  end if;

  insert into vortex_access.record_share_grants (
    grant_id, source_organization_id, source_cluster_id, source_application_root_id,
    recipient_cluster_id, recipient_organization_id, recipient_application_root_id,
    scope_kind, module_root_id, record_type_id, record_id, saved_condition_id,
    saved_condition_revision, saved_condition_fingerprint, saved_condition_parameters,
    readable_field_ids, changeable_field_ids, recipient_role_ids, allowed_action_keys,
    export_allowed, approved_recipient_region, starts_at, expires_at, status,
    created_by_organization_account_id, consent_request_id, contract_version,
    contract_fingerprint, recipient_binding_id, definition_mapping_fingerprint,
    proposal_fingerprint, revision, created_at, changed_at
  ) values (
    p_grant_id, context_organization_id, (p_terms ->> 'sourceClusterId')::uuid,
    context_application_root_id, (p_terms ->> 'recipientClusterId')::uuid,
    (p_terms ->> 'recipientOrganizationId')::uuid,
    (p_terms ->> 'recipientApplicationRootId')::uuid,
    p_terms ->> 'scopeKind', (p_terms ->> 'moduleRootId')::uuid,
    (p_terms ->> 'recordTypeId')::uuid, (p_terms ->> 'recordId')::uuid,
    (p_terms ->> 'savedConditionId')::uuid, (p_terms ->> 'savedConditionRevision')::bigint,
    p_terms ->> 'savedConditionFingerprint', p_terms -> 'parameters',
    vortex_access.record_share_grant_uuid_array_internal(p_terms -> 'readableFieldIds', 1, 500),
    vortex_access.record_share_grant_uuid_array_internal(p_terms -> 'changeableFieldIds', 0, 500),
    vortex_access.record_share_grant_uuid_array_internal(p_terms -> 'recipientRoleIds', 1, 100),
    array(select pg_catalog.jsonb_array_elements_text(p_terms -> 'allowedActionKeys')),
    (p_terms ->> 'exportAllowed')::boolean, p_terms ->> 'approvedRecipientRegion',
    (p_terms ->> 'startsAt')::timestamptz, (p_terms ->> 'expiresAt')::timestamptz,
    case when cross_organization then 'pending_consent' else 'draft' end,
    context_account_id, p_consent_request_id, p_terms ->> 'contractVersion',
    p_terms ->> 'contractFingerprint', (p_terms ->> 'recipientBindingId')::uuid,
    p_terms ->> 'definitionMappingFingerprint', p_proposal_fingerprint, 1,
    now_value, now_value
  );

  -- The grant's foreign key to its consent request is deferred, so the request
  -- follows the grant it names.
  if cross_organization then
    insert into vortex_access.record_share_grant_consent_requests (
      request_id, grant_id, source_organization_id, source_cluster_id,
      recipient_organization_id, recipient_cluster_id, proposed_grant_fingerprint,
      status, requested_by_organization_account_id, requested_at,
      source_authorizing_role_ids, recipient_accepting_role_ids, expires_at,
      revision, changed_at
    ) values (
      p_consent_request_id, p_grant_id, context_organization_id,
      (p_terms ->> 'sourceClusterId')::uuid,
      (p_terms ->> 'recipientOrganizationId')::uuid,
      (p_terms ->> 'recipientClusterId')::uuid, p_proposal_fingerprint,
      'pending', context_account_id, now_value,
      vortex_access.record_share_grant_uuid_array_internal(
        p_terms -> 'sourceAuthorizingRoleIds', 1, 100),
      vortex_access.record_share_grant_uuid_array_internal(
        p_terms -> 'recipientAcceptingRoleIds', 1, 100),
      (p_terms ->> 'expiresAt')::timestamptz, 1, now_value
    );
  end if;


  append_result := vortex_activity.append_organization_activity_entry(
    context_organization_id, p_activity_id, now_value, 'organization_account',
    context_account_id, 'propose_record_share_grant', array[p_grant_id]::uuid[],
    array[]::uuid[], vortex_context.channel(), context_correlation_id, 'completed'
  );
  if append_result is distinct from 'inserted' then
    raise exception using errcode = '40001',
      message = 'Record-share grant proposal Activity is stale';
  end if;

  return vortex_access.record_share_grant_json_internal(p_grant_id);
end
$function$;


ALTER FUNCTION vortex_access.propose_record_share_grant_for_administration(p_grant_id uuid, p_consent_request_id uuid, p_terms jsonb, p_proposal_fingerprint text, p_activity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION propose_record_share_grant_for_administration(p_grant_id uuid, p_consent_request_id uuid, p_terms jsonb, p_proposal_fingerprint text, p_activity_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.propose_record_share_grant_for_administration(p_grant_id uuid, p_consent_request_id uuid, p_terms jsonb, p_proposal_fingerprint text, p_activity_id uuid) IS 'Fixed protected proposer: stores one exact record-share grant proposal for the context organisation after re-checking its current share authority; cross-organisation proposals stop at pending_consent with a consent request bound to the proposal fingerprint.';


--
-- Name: protect_application_role_template_continuity(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.protect_application_role_template_continuity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '23514',
      message = 'Application role template continuity cannot be deleted';
  end if;

  if new.organization_id is distinct from old.organization_id
    or new.application_root_id is distinct from old.application_root_id
    or new.source_role_id is distinct from old.source_role_id
    or old.last_processed_registration_revision = 9007199254740991
    or new.last_processed_registration_revision <= old.last_processed_registration_revision
    or new.continuity_revision not in (
      old.continuity_revision,
      old.continuity_revision + 1
    )
    or (
      new.continuity_revision = old.continuity_revision
      and new.state is distinct from old.state
    )
    or (
      new.continuity_revision = old.continuity_revision + 1
      and new.state is not distinct from old.state
    ) then
    raise exception using errcode = '23514',
      message = 'Application role template continuity transition is invalid';
  end if;

  return new;
end;
$$;


ALTER FUNCTION vortex_access.protect_application_role_template_continuity() OWNER TO postgres;

--
-- Name: protect_organization_access_version(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.protect_organization_access_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.organization_id is distinct from old.organization_id then
    raise exception using errcode = '23514', message = 'Access-version organisation is permanent';
  end if;

  if new.current_version <> old.current_version + 1
    or new.changed_at < old.changed_at
    or new.change_reason is null then
    raise exception using errcode = '23514', message = 'Access-version updates require one complete increment';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_access.protect_organization_access_version() OWNER TO postgres;

--
-- Name: protect_organization_delegation_authority(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.protect_organization_delegation_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  permissions_changed boolean;
  fingerprint_changed boolean;
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '23514',
      message = 'Organization delegation authorities cannot be deleted';
  end if;

  if old.revision = 9007199254740991 then
    raise exception using errcode = '22003',
      message = 'Organization delegation authority revision is exhausted';
  end if;

  if old.state = 'revoked'
    or new.organization_id is distinct from old.organization_id
    or new.delegation_authority_id is distinct from
      old.delegation_authority_id
    or new.holder_kind is distinct from old.holder_kind
    or new.organization_account_id is distinct from old.organization_account_id
    or new.group_id is distinct from old.group_id
    or new.starts_at is distinct from old.starts_at
    or new.expires_at is distinct from old.expires_at
    or new.granted_by is distinct from old.granted_by
    or new.granted_at is distinct from old.granted_at
    or new.grant_correlation_id is distinct from old.grant_correlation_id
    or new.revision <> old.revision + 1
    or new.changed_at < old.changed_at
    or (new.changed_by, new.changed_at, new.change_correlation_id)
      is not distinct from
      (old.changed_by, old.changed_at, old.change_correlation_id) then
    raise exception using errcode = '23514',
      message = 'Organization delegation authority identity or evidence is immutable';
  end if;

  permissions_changed := new.bounded_permissions is distinct from
    old.bounded_permissions;
  fingerprint_changed := new.scope_fingerprint is distinct from
    old.scope_fingerprint;

  if new.state = 'revoked' then
    if new.revoked_at is null
      or new.revoked_at < old.changed_at
      or new.scope_kind is distinct from old.scope_kind
      or permissions_changed
      or fingerprint_changed then
      raise exception using errcode = '23514',
        message = 'Delegation revocation cannot alter scope or predate current evidence';
    end if;
    return new;
  end if;

  if new.state <> 'live'
    or (
      new.scope_kind is not distinct from old.scope_kind
      and not permissions_changed
      and not fingerprint_changed
    )
    or (
      new.scope_kind = 'bounded'
      and old.scope_kind = 'bounded'
      and permissions_changed <> fingerprint_changed
    ) then
    raise exception using errcode = '23514',
      message = 'Delegation scope replacement must replace one exact whole scope';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_access.protect_organization_delegation_authority() OWNER TO postgres;

--
-- Name: protect_organization_direct_record_share(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.protect_organization_direct_record_share() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '23514',
      message = 'Direct record shares cannot be deleted';
  end if;

  if old.revision = 9007199254740991 then
    raise exception using errcode = '22003',
      message = 'Direct record-share revision is exhausted';
  end if;

  if old.state = 'revoked'
    or new.organization_id is distinct from old.organization_id
    or new.direct_share_id is distinct from old.direct_share_id
    or new.storage_scope is distinct from old.storage_scope
    or new.application_root_id is distinct from old.application_root_id
    or new.module_root_id is distinct from old.module_root_id
    or new.record_type_id is distinct from old.record_type_id
    or new.storage_contract_id is distinct from old.storage_contract_id
    or new.record_id is distinct from old.record_id
    or new.recipient_kind is distinct from old.recipient_kind
    or new.organization_account_id is distinct from old.organization_account_id
    or new.group_id is distinct from old.group_id
    or new.readable_field_ids is distinct from old.readable_field_ids
    or new.changeable_field_ids is distinct from old.changeable_field_ids
    or new.starts_at is distinct from old.starts_at
    or new.expires_at is distinct from old.expires_at
    or new.granted_by is distinct from old.granted_by
    or new.granted_at is distinct from old.granted_at
    or new.grant_correlation_id is distinct from old.grant_correlation_id
    or new.reason is distinct from old.reason
    or new.state <> 'revoked'
    or new.revision <> old.revision + 1
    or new.changed_at < old.changed_at then
    raise exception using errcode = '23514',
      message = 'Direct record-share identity, grant evidence or lifecycle is immutable';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_access.protect_organization_direct_record_share() OWNER TO postgres;

--
-- Name: protect_organization_group(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.protect_organization_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.revision <> 1 or new.state <> 'active' then
      raise exception using errcode = '23514',
        message = 'An organization Group must begin active at revision one';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception using errcode = '23514',
      message = 'Organization Groups cannot be deleted';
  end if;

  if old.revision = 9007199254740991 then
    raise exception using errcode = '22003',
      message = 'Organization Group revision is exhausted';
  end if;

  if old.state = 'retired'
    or new.organization_id is distinct from old.organization_id
    or new.group_id is distinct from old.group_id
    or new.group_key is distinct from old.group_key
    or new.created_by is distinct from old.created_by
    or new.created_at is distinct from old.created_at
    or new.revision <> old.revision + 1
    or new.changed_at < old.changed_at
    or (new.changed_by, new.changed_at, new.change_correlation_id)
      is not distinct from
      (old.changed_by, old.changed_at, old.change_correlation_id)
    or (old.state = 'active' and new.state not in ('active', 'retired')) then
    raise exception using errcode = '23514',
      message = 'Organization Group transition is invalid';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_access.protect_organization_group() OWNER TO postgres;

--
-- Name: protect_organization_group_membership(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.protect_organization_group_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '23514',
      message = 'Organization Group memberships cannot be deleted';
  end if;

  if old.revision = 9007199254740991 then
    raise exception using errcode = '22003',
      message = 'Organization Group membership revision is exhausted';
  end if;

  if new.organization_id is distinct from old.organization_id
    or new.membership_id is distinct from old.membership_id
    or new.group_id is distinct from old.group_id
    or new.organization_account_id is distinct from old.organization_account_id
    or new.starts_at is distinct from old.starts_at
    or new.expires_at is distinct from old.expires_at
    or new.granted_by is distinct from old.granted_by
    or new.granted_at is distinct from old.granted_at
    or new.grant_correlation_id is distinct from old.grant_correlation_id
    or new.revision <> old.revision + 1
    or new.changed_at < old.changed_at
    or (new.changed_by, new.changed_at, new.change_correlation_id)
      is not distinct from
      (old.changed_by, old.changed_at, old.change_correlation_id) then
    raise exception using errcode = '23514',
      message = 'Organization Group membership identity or evidence is immutable';
  end if;

  if old.state = 'live' and new.state = 'revoked' then
    if new.revoked_at is null or new.revoked_at < old.changed_at then
      raise exception using errcode = '23514',
        message = 'Group membership revocation cannot predate current evidence';
    end if;
    return new;
  end if;

  if old.state = 'revoked' and new.state = 'live' then
    if new.expires_at is not null
      and new.expires_at <= pg_catalog.statement_timestamp() then
      raise exception using errcode = '23514',
        message = 'An expired Group membership requires a new identity';
    end if;

    if not exists (
      select 1
      from vortex_access.organization_groups as organization_group
      where organization_group.organization_id = new.organization_id
        and organization_group.group_id = new.group_id
        and organization_group.state = 'active'
    ) or not exists (
      select 1
      from vortex_identity.organization_accounts as account
      where account.organization_id = new.organization_id
        and account.organization_account_id = new.organization_account_id
        and account.state = 'active'
    ) then
      raise exception using errcode = '23514',
        message = 'Group membership restoration requires active same-organization sources';
    end if;

    return new;
  end if;

  raise exception using errcode = '23514',
    message = 'Organization Group membership transition is invalid';
end
$$;


