--

COMMENT ON FUNCTION vortex_access.protect_platform_permission_declarations() IS 'Rejects removal or silent substitution of a guarded platform permission declaration.';


--
-- Name: publish_capability_policy_definition(uuid, uuid, uuid, uuid, text, text, numeric, bigint); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.publish_capability_policy_definition(
  p_operator_actor_id uuid,
  p_duplicate_key uuid,
  p_tenant_id uuid,
  p_policy_id uuid,
  p_capability_key text,
  p_unit text,
  p_quantity_limit numeric,
  p_expected_revision bigint
)
returns table (
  outcome text, policy_id uuid, tenant_id uuid, capability_key text, unit text,
  quantity_limit numeric, revision bigint, correlation_id uuid, accepted_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  current_definition vortex_access.capability_policy_definitions%rowtype;
  current_revision bigint;
  resulting_revision bigint;
  correlation uuid := pg_catalog.gen_random_uuid();
  receipt vortex_identity.accepted_administration_receipts%rowtype;
  command_fingerprint text;
begin
  if p_duplicate_key is null or not vortex_context.is_non_nil_uuid(p_duplicate_key::text)
    or p_tenant_id is null or not vortex_context.is_non_nil_uuid(p_tenant_id::text)
    or p_policy_id is null or not vortex_context.is_non_nil_uuid(p_policy_id::text)
    or not vortex_access.capability_policy_key_is_valid(p_capability_key)
    or not vortex_access.capability_policy_unit_is_valid(p_unit)
    or not vortex_access.capability_policy_quantity_is_valid(p_quantity_limit)
    or (p_expected_revision is not null
      and p_expected_revision not between 1 and 9007199254740991) then
    raise exception using errcode = '22023', message = 'Capability policy definition is invalid';
  end if;
  -- Only the platform operator defines policies; no tenant or organisation
  -- authority reaches this command.
  perform vortex_access.require_platform_operator_internal(p_operator_actor_id);
  perform 1 from vortex_identity.tenants tenant where tenant.tenant_id = p_tenant_id for no key update;
  if not found then
    raise exception using errcode = 'V3101', message = 'Capability policy tenant is unavailable';
  end if;
  command_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f', 'publish_capability_policy_definition',
      p_tenant_id::text, p_policy_id::text, p_capability_key, p_unit,
      p_quantity_limit::text, coalesce(p_expected_revision::text, '')), 'UTF8'), 'sha256'), 'hex');
  select stored.* into receipt
  from vortex_identity.accepted_administration_receipts as stored
  where stored.actor_id = p_operator_actor_id and stored.tenant_id = p_tenant_id
    and stored.operation_key = 'publish_capability_policy_definition'
    and stored.duplicate_key = p_duplicate_key for update;
  if found then
    if receipt.command_fingerprint <> command_fingerprint
      or receipt.subject_ids <> array[p_policy_id]
      or pg_catalog.cardinality(receipt.subject_revisions) <> 1 then
      raise exception using errcode = 'V3001', message = 'Capability policy duplicate conflicts';
    end if;
    return query
      select 'replayed'::text, definition.policy_id, definition.tenant_id,
        definition.capability_key, definition.unit, definition.quantity_limit,
        definition.revision, receipt.receipt_id, receipt.accepted_at
      from vortex_access.capability_policy_definitions as definition
      where definition.policy_id = p_policy_id
        and definition.revision = receipt.subject_revisions[1];
    if not found then
      raise exception using errcode = '42501', message = 'Capability policy replay is unavailable';
    end if;
    return;
  end if;
  select definition.* into current_definition
  from vortex_access.capability_policy_definitions as definition
  where definition.tenant_id = p_tenant_id and definition.policy_id = p_policy_id
  order by definition.revision desc limit 1;
  current_revision := current_definition.revision;
  if (current_revision is null and p_expected_revision is not null)
    or (current_revision is not null and p_expected_revision is distinct from current_revision)
    or (current_revision is null and p_expected_revision is null and exists (
      select 1 from vortex_access.capability_policy_definitions definition
      where definition.policy_id = p_policy_id
    )) then
    raise exception using errcode = 'V3102', message = 'Capability policy definition revision is stale';
  end if;
  -- A policy names one capability and unit for its whole life.  Only the
  -- quantity limit is revisable, so publishing a later revision can never
  -- re-point a ceiling that pinned an earlier one at another capability.
  if current_revision is not null
    and (current_definition.capability_key <> p_capability_key
      or current_definition.unit <> p_unit) then
    raise exception using errcode = '22023',
      message = 'Capability policy scope cannot change between revisions';
  end if;
  resulting_revision := coalesce(current_revision, 0) + 1;
  if resulting_revision > 9007199254740991 then
    raise exception using errcode = '40001', message = 'Capability policy revision is exhausted';
  end if;
  insert into vortex_access.capability_policy_definitions(
    policy_id, tenant_id, capability_key, unit, quantity_limit, revision,
    published_at, published_by_actor_id, publication_correlation_id
  ) values (
    p_policy_id, p_tenant_id, p_capability_key, p_unit, p_quantity_limit, resulting_revision,
    evaluated_at, p_operator_actor_id, correlation
  );
  insert into vortex_identity.accepted_administration_receipts(
    receipt_id, actor_id, tenant_id, operation_key, duplicate_key,
    command_fingerprint, subject_ids, subject_revisions, accepted_at
  ) values (
    correlation, p_operator_actor_id, p_tenant_id, 'publish_capability_policy_definition',
    p_duplicate_key, command_fingerprint, array[p_policy_id], array[resulting_revision], evaluated_at
  );
  insert into vortex_access.capability_limit_changes(
    change_id, tenant_id, organization_id, change_kind, actor_kind, actor_id,
    policy_id, policy_revision, assignment_id, assignment_revision,
    capability_key, unit, quantity_limit, expires_at, source, correlation_id, occurred_at
  ) values (
    correlation, p_tenant_id, null, 'policy_published', 'platform_operator', p_operator_actor_id,
    p_policy_id, resulting_revision, null, null,
    p_capability_key, p_unit, p_quantity_limit, null, 'system', correlation, evaluated_at
  );
  return query select 'accepted'::text, p_policy_id, p_tenant_id, p_capability_key,
    p_unit, p_quantity_limit, resulting_revision, correlation, evaluated_at;
end
$function$;


ALTER FUNCTION vortex_access.publish_capability_policy_definition(p_operator_actor_id uuid, p_duplicate_key uuid, p_tenant_id uuid, p_policy_id uuid, p_capability_key text, p_unit text, p_quantity_limit numeric, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION publish_capability_policy_definition(p_operator_actor_id uuid, p_duplicate_key uuid, p_tenant_id uuid, p_policy_id uuid, p_capability_key text, p_unit text, p_quantity_limit numeric, p_expected_revision bigint); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.publish_capability_policy_definition(p_operator_actor_id uuid, p_duplicate_key uuid, p_tenant_id uuid, p_policy_id uuid, p_capability_key text, p_unit text, p_quantity_limit numeric, p_expected_revision bigint) IS 'Platform-operator-only capability policy publication for one tenant: an immutable revision with an accepted receipt and append-only change evidence.';


--
-- Name: reactivate_organization_account_for_administration(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.reactivate_organization_account_for_administration(
  p_duplicate_key uuid, p_organization_account_id uuid,
  p_expected_revision bigint
)
returns table (
  outcome text, operation text, organization_id uuid,
  organization_account_id uuid, revision bigint, correlation_id uuid,
  accepted_at timestamptz, access_version bigint
)
language plpgsql volatile security definer set search_path = ''
as $function$
declare
  scope record;
  receipt vortex_identity.accepted_administration_receipts%rowtype;
  target record; changed record; command_fingerprint text;
  subject_ids uuid[]; subject_revisions bigint[];
begin
  if p_duplicate_key is null or not vortex_context.is_non_nil_uuid(p_duplicate_key::text)
    or p_organization_account_id is null
    or not vortex_context.is_non_nil_uuid(p_organization_account_id::text)
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023', message = 'Account reactivation command is invalid';
  end if;
  select authorized.* into strict scope
  from vortex_access.organization_accounts_administration_change_scope() as authorized;
  command_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f', 'reactivate_organization_account',
      scope.organization_id::text, p_organization_account_id::text,
      p_expected_revision::text), 'UTF8'), 'sha256'), 'hex');
  select stored.* into receipt
  from vortex_identity.accepted_administration_receipts as stored
  where stored.actor_id = scope.organization_account_id
    and stored.tenant_id = scope.tenant_id
    and stored.operation_key = 'reactivate_organization_account'
    and stored.duplicate_key = p_duplicate_key
  for update;
  if found then
    if receipt.command_fingerprint <> command_fingerprint then
      raise exception using errcode = 'V3001', message = 'Administration duplicate conflicts';
    end if;
    if pg_catalog.cardinality(receipt.subject_ids) <> 2
      or not scope.organization_id = any(receipt.subject_ids)
      or not p_organization_account_id = any(receipt.subject_ids) then
      raise exception using errcode = '42501', message = 'Account reactivation receipt is unavailable';
    end if;
    return query select 'replayed'::text, 'reactivate_organization_account'::text,
      scope.organization_id, p_organization_account_id,
      receipt.subject_revisions[pg_catalog.array_position(receipt.subject_ids, p_organization_account_id)],
      receipt.receipt_id, receipt.accepted_at,
      receipt.subject_revisions[pg_catalog.array_position(receipt.subject_ids, scope.organization_id)];
    return;
  end if;
  -- Lock order: organization access version, then the account row, the same
  -- order invitation acceptance uses.
  perform 1
  from vortex_access.organization_access_versions as version
  where version.organization_id = scope.organization_id
  for update;
  select account.state, account.revision into target
  from vortex_identity.organization_accounts as account
  where account.organization_id = scope.organization_id
    and account.organization_account_id = p_organization_account_id
  for update;
  if not found or target.state not in ('suspended', 'closed')
    or target.revision <> p_expected_revision
    or p_expected_revision = 9007199254740991 then
    raise exception using errcode = '40001', message = 'Account reactivation is stale or unavailable';
  end if;
  select result.* into strict changed
  from vortex_access.change_organization_account_state(
    p_organization_account_id, p_expected_revision, 'active'
  ) as result;
  if changed.organization_id <> scope.organization_id
    or changed.organization_account_id <> p_organization_account_id
    or changed.state <> 'active' or changed.revision <> p_expected_revision + 1
    or changed.access_version <> scope.access_version + 1 then
    raise exception using errcode = '42501', message = 'Account reactivation result is unavailable';
  end if;
  if scope.organization_id < p_organization_account_id then
    subject_ids := array[scope.organization_id, p_organization_account_id];
    subject_revisions := array[changed.access_version, changed.revision];
  else
    subject_ids := array[p_organization_account_id, scope.organization_id];
    subject_revisions := array[changed.revision, changed.access_version];
  end if;
  insert into vortex_identity.accepted_administration_receipts(
    receipt_id, actor_id, tenant_id, operation_key, duplicate_key,
    command_fingerprint, subject_ids, subject_revisions, accepted_at
  ) values (
    changed.state_change_correlation_id, scope.organization_account_id,
    scope.tenant_id, 'reactivate_organization_account', p_duplicate_key,
    command_fingerprint, subject_ids, subject_revisions, changed.changed_at
  );
  return query select 'accepted'::text, 'reactivate_organization_account'::text,
    scope.organization_id, p_organization_account_id, changed.revision,
    changed.state_change_correlation_id, changed.changed_at, changed.access_version;
end
$function$;


ALTER FUNCTION vortex_access.reactivate_organization_account_for_administration(p_duplicate_key uuid, p_organization_account_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION reactivate_organization_account_for_administration(p_duplicate_key uuid, p_organization_account_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.reactivate_organization_account_for_administration(p_duplicate_key uuid, p_organization_account_id uuid, p_expected_revision bigint) IS 'Protected suspended-or-closed-to-active account command using the existing guarded owner and accepted receipt.';


--
-- Name: read_application_address_candidates(uuid, text, text); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.read_application_address_candidates(
  p_identity_id uuid,
  p_tenant_short_name text,
  p_organization_short_name text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  addressed_organization record;
  application_row record;
  application_values jsonb := '[]'::jsonb;
  page_values jsonb;
  experience_values jsonb;
  role_values jsonb;
  permission_values jsonb;
  home_page_key text;
begin
  if p_identity_id is null
    or p_identity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_tenant_short_name is null
    or pg_catalog.char_length(p_tenant_short_name) not between 1 and 40
    or p_tenant_short_name !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
    or p_organization_short_name is null
    or pg_catalog.char_length(p_organization_short_name) not between 1 and 40
    or p_organization_short_name !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$' then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  select tenant.tenant_id, tenant.short_name as tenant_short_name,
    organization.organization_id, organization.short_name as organization_short_name
  into addressed_organization
  from vortex_identity.tenants as tenant
  join vortex_identity.organizations as organization
    on organization.tenant_id = tenant.tenant_id
  where tenant.short_name = p_tenant_short_name
    and organization.short_name = p_organization_short_name
    and tenant.state = 'active'
    and organization.state = 'active';

  if not found then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  begin
    perform 1
    from vortex_access.resolve_human_organization_scope(
      p_identity_id, addressed_organization.organization_id
    ) as scope;
  exception
    when sqlstate 'V3140' then
      return pg_catalog.jsonb_build_object(
        'kind', 'suspended_super_administrator_account'
      );
    when sqlstate '42501' or sqlstate 'P0002' then
      return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end;

  for application_row in
    select root.root_id, root.key as application_key, release.compilation_output,
      registration.revision as registration_revision,
      registration.source_revision as release_revision
    from vortex_access.permission_registrations as registration
    join vortex_definition.roots as root
      on root.root_id = registration.registration_owner_id
      and root.organization_id = addressed_organization.organization_id
      and root.kind = 'application'
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = registration.source_revision
    where registration.organization_id = addressed_organization.organization_id
      and registration.registration_kind = 'application'
      and registration.state = 'active'
      and exists (
        select 1
        from vortex_module.installation_bindings as binding
        where binding.organization_id = addressed_organization.organization_id
          and binding.application_root_id = root.root_id
          and binding.application_release_revision = registration.source_revision
          and binding.state = 'active'
      )
      and registration.source_content_fingerprint = release.content_fingerprint
      and registration.source_resolution_fingerprint = release.resolution_fingerprint
      and release.compilation_output ->> 'kind' = 'application'
    order by root.key collate "C", root.root_id
  loop
    begin
      perform 1
      from vortex_access.resolve_human_application_scope(
        p_identity_id,
        addressed_organization.organization_id,
        application_row.root_id
      ) as scope;
    exception
      when sqlstate '42501' or sqlstate 'P0002' then
        continue;
    end;

    page_values := application_row.compilation_output #> '{canonical,content,pages}';
    if pg_catalog.jsonb_typeof(page_values) is distinct from 'array' then
      continue;
    end if;
    if pg_catalog.jsonb_array_length(page_values) = 0 then
      continue;
    end if;

    select page.value ->> 'key'
    into home_page_key
    from pg_catalog.jsonb_array_elements(page_values) as page(value)
    where page.value ->> 'pageId' =
      application_row.compilation_output #>> '{canonical,content,homePageId}';

    if home_page_key is null then
      continue;
    end if;

    -- Declared experience pages are resolved to their exact compiled page definitions here, so
    -- App can render an application's own not-found, unavailable and error surfaces. A refused
    -- page and a missing page both resolve to the same not_found experience.
    experience_values := application_row.compilation_output #> '{canonical,content,experiences}';
    if pg_catalog.jsonb_typeof(experience_values) is distinct from 'array' then
      experience_values := '[]'::jsonb;
    end if;

    role_values := application_row.compilation_output #> '{canonical,content,roles}';
    if pg_catalog.jsonb_typeof(role_values) is distinct from 'array' then
      continue;
    end if;

    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'key', entry.permission_key,
        'applicationRootId', entry.application_root_id,
        'ownerKind', entry.owner_kind,
        'ownerId', entry.owner_id,
        'permissionId', entry.permission_id,
        'actionKind', entry.action_kind,
        'namedAction', entry.named_action
      ) order by entry.permission_key collate "C", entry.permission_id
    ) into permission_values
    from vortex_access.permission_catalogue_entries as entry
    where entry.organization_id = addressed_organization.organization_id
      and entry.registration_kind = 'application'
      and entry.registration_owner_id = application_row.root_id
      and entry.registration_revision = application_row.registration_revision
      and entry.application_root_id = application_row.root_id;

    application_values := application_values || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'applicationRootId', application_row.root_id,
        'releaseRevision', application_row.release_revision,
        'key', application_row.application_key,
        'name', application_row.compilation_output #>> '{canonical,content,name}',
        'icon', application_row.compilation_output #>> '{canonical,content,icon}',
        'homePageKey', home_page_key,
        'pages', (
          select pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'pageId', page.value ->> 'pageId',
              'key', page.value ->> 'key',
              'accessPermissionKey', page.value ->> 'accessPermissionKey'
            ) order by page.value ->> 'key' collate "C"
          )
          from pg_catalog.jsonb_array_elements(page_values) as page(value)
        ),
        'experiences', coalesce((
          select pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object('state', experience.value ->> 'state', 'page', page.value)
            order by experience.value ->> 'state' collate "C"
          )
          from pg_catalog.jsonb_array_elements(experience_values) as experience(value)
          join pg_catalog.jsonb_array_elements(page_values) as page(value)
            on page.value ->> 'pageId' = experience.value ->> 'pageId'
        ), '[]'::jsonb),
        'shells', case
          when pg_catalog.jsonb_array_length(experience_values) > 0
            then coalesce(
              application_row.compilation_output #> '{canonical,content,shells}',
              '[]'::jsonb
            )
          else '[]'::jsonb
        end,
        'roles', (
          select pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'roleId', role.value ->> 'roleId',
              'key', role.value ->> 'key',
              'homePageId', role.value ->> 'homePageId'
            ) order by role.value ->> 'key' collate "C"
          )
          from pg_catalog.jsonb_array_elements(role_values) as role(value)
        ),
        'permissions', coalesce(permission_values, '[]'::jsonb)
      ) || case
        when pg_catalog.jsonb_array_length(experience_values) > 0
          then pg_catalog.jsonb_build_object(
            'theme', application_row.compilation_output #> '{canonical,content,theme}'
          )
        else '{}'::jsonb
      end
    );
  end loop;

  return pg_catalog.jsonb_build_object(
    'kind', 'available',
    'organizationId', addressed_organization.organization_id,
    'tenantShortName', addressed_organization.tenant_short_name,
    'organizationShortName', addressed_organization.organization_short_name,
    'applications', application_values
  );
end
$function$;


ALTER FUNCTION vortex_access.read_application_address_candidates(p_identity_id uuid, p_tenant_short_name text, p_organization_short_name text) OWNER TO postgres;

--
-- Name: FUNCTION read_application_address_candidates(p_identity_id uuid, p_tenant_short_name text, p_organization_short_name text); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.read_application_address_candidates(p_identity_id uuid, p_tenant_short_name text, p_organization_short_name text) IS 'Private App candidate read for one exact live human organisation address; only App may project metadata after current page Access decisions.';


--
-- Name: read_application_permission_snapshot(uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.read_application_permission_snapshot(
  p_organization_id uuid,
  p_application_root_id uuid
)
returns table (
  organization_id uuid,
  application_root_id uuid,
  registration_revision bigint,
  release_revision bigint,
  definition_key text,
  release_version text,
  validation_contract_version text,
  content_fingerprint text,
  resolution_fingerprint text,
  catalogue_fingerprint text,
  permission_ids uuid[]
)
language sql
stable
security definer
set search_path = ''
as $function$
  select registration.organization_id, registration.registration_owner_id,
    registration.revision, registration.source_revision, registration.source_definition_key,
    registration.source_version,
    registration.validation_contract_version, registration.source_content_fingerprint,
    registration.source_resolution_fingerprint,
    registration.permission_catalogue_fingerprint,
    coalesce(
      pg_catalog.array_agg(entry.permission_id order by
        entry.permission_key collate "C", entry.permission_id)
        filter (where entry.permission_id is not null),
      array[]::uuid[]
    )
  from vortex_access.permission_registrations as registration
  left join vortex_access.permission_catalogue_entries as entry
    on entry.organization_id = registration.organization_id
    and entry.registration_kind = registration.registration_kind
    and entry.registration_owner_id = registration.registration_owner_id
    and entry.registration_revision = registration.revision
    and entry.owner_kind = 'application'
    and entry.administrative = false
  where registration.organization_id = p_organization_id
    and registration.registration_kind = 'application'
    and registration.registration_owner_id = p_application_root_id
    and registration.state = 'active'
  group by registration.organization_id, registration.registration_owner_id,
    registration.revision, registration.source_revision, registration.source_definition_key,
    registration.source_version,
    registration.validation_contract_version, registration.source_content_fingerprint,
    registration.source_resolution_fingerprint,
    registration.permission_catalogue_fingerprint
$function$;


ALTER FUNCTION vortex_access.read_application_permission_snapshot(p_organization_id uuid, p_application_root_id uuid) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION read_application_permission_snapshot(p_organization_id uuid, p_application_root_id uuid); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.read_application_permission_snapshot(p_organization_id uuid, p_application_root_id uuid) IS 'Owner-only active exact release reference and deterministic application-only permission snapshot; role templates remain in Definition.';


--
-- Name: read_application_role_template_for_administration(uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.read_application_role_template_for_administration(p_application_root_id uuid, p_source_role_id uuid) RETURNS TABLE(organization_id uuid, outcome text, template_summary jsonb, access_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scope record;
  template_value jsonb;
begin
  if p_application_root_id is null or p_source_role_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_source_role_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Application role template detail input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_roles_administration_scope() as authorized;

  select pg_catalog.jsonb_build_object(
    'reference', pg_catalog.jsonb_build_object(
      'applicationRootId', registration.registration_owner_id,
      'sourceRoleId', (template.value ->> 'roleId')::uuid
    ),
    'key', template.value ->> 'key',
    'label', template.value ->> 'name',
    'permissionSelectionKind', template.value #>> '{permissionSelection,kind}',
    'publishedPermissionKeys', template.value -> 'permissionKeys'
  )
  into template_value
  from vortex_access.permission_registrations as registration
  join vortex_definition.roots as root
    on root.root_id = registration.registration_owner_id
    and root.organization_id = registration.organization_id
    and root.kind = 'application'
    and root.key = registration.source_definition_key
  join vortex_definition.releases as release
    on release.root_id = root.root_id
    and release.release_revision = registration.source_revision
    and release.release_version = registration.source_version
    and release.validation_contract_version = registration.validation_contract_version
    and release.content_fingerprint = registration.source_content_fingerprint
    and release.resolution_fingerprint = registration.source_resolution_fingerprint
  cross join lateral pg_catalog.jsonb_array_elements(
    release.compilation_output #> '{canonical,content,roles}'
  ) as template(value)
  join vortex_access.application_role_template_continuities as continuity
    on continuity.organization_id = registration.organization_id
    and continuity.application_root_id = registration.registration_owner_id
    and continuity.source_role_id = (template.value ->> 'roleId')::uuid
    and continuity.state = 'available'
    and continuity.last_processed_registration_revision = registration.revision
  where registration.organization_id = scope.organization_id
    and registration.registration_kind = 'application'
    and registration.registration_owner_id = p_application_root_id
    and registration.state = 'active'
    and (template.value ->> 'roleId')::uuid = p_source_role_id;

  return query select scope.organization_id,
    case when template_value is null then 'unavailable' else 'available' end,
    template_value, scope.access_version;
end
$$;


ALTER FUNCTION vortex_access.read_application_role_template_for_administration(p_application_root_id uuid, p_source_role_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION read_application_role_template_for_administration(p_application_root_id uuid, p_source_role_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.read_application_role_template_for_administration(p_application_root_id uuid, p_source_role_id uuid) IS 'Returns one exact template from an active current application registration.';


--
-- Name: read_available_permission(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.read_available_permission(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_owner_kind text,
  p_owner_id uuid,
  p_permission_id uuid
)
returns table (
  organization_id uuid,
  application_root_id uuid,
  registration_revision bigint,
  owner_kind text,
  owner_id uuid,
  permission_id uuid,
  permission_key text,
  label text,
  description text,
  record_type_id uuid,
  record_scope jsonb,
  field_policy jsonb,
  action_kind text,
  named_action text,
  administrative boolean,
  source_kind text,
  source_definition_key text,
  source_root_id uuid,
  source_version text,
  source_revision bigint,
  source_validation_contract_version text,
  source_content_fingerprint text,
  source_resolution_fingerprint text,
  source_catalogue_fingerprint text,
  meaning_fingerprint text
)
language sql
stable
security definer
set search_path = ''
as $function$
  select entry.organization_id, entry.application_root_id, entry.registration_revision,
    entry.owner_kind, entry.owner_id, entry.permission_id, entry.permission_key,
    entry.label, entry.description, entry.record_type_id, entry.record_scope,
    entry.field_policy,
    entry.action_kind, entry.named_action, entry.administrative, entry.source_kind,
    entry.source_definition_key, entry.source_root_id, entry.source_version,
    entry.source_revision, entry.source_validation_contract_version,
    entry.source_content_fingerprint, entry.source_resolution_fingerprint,
    entry.source_catalogue_fingerprint, entry.meaning_fingerprint
  from vortex_access.permission_registrations as registration
  join vortex_access.permission_catalogue_entries as entry
    on entry.organization_id = registration.organization_id
    and entry.registration_kind = registration.registration_kind
    and entry.registration_owner_id = registration.registration_owner_id
    and entry.registration_revision = registration.revision
  where registration.organization_id = p_organization_id
    and registration.state = 'active'
    and entry.owner_kind = p_owner_kind
    and entry.owner_id = p_owner_id
    and entry.permission_id = p_permission_id
    and (
      (p_owner_kind = 'platform' and p_application_root_id is null and entry.application_root_id is null)
      or (
        p_owner_kind in ('application', 'module')
        and p_application_root_id is not null
        and registration.registration_kind = 'application'
        and registration.registration_owner_id = p_application_root_id
        and entry.application_root_id = p_application_root_id
      )
    )
$function$;


ALTER FUNCTION vortex_access.read_available_permission(p_organization_id uuid, p_application_root_id uuid, p_owner_kind text, p_owner_id uuid, p_permission_id uuid) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION read_available_permission(p_organization_id uuid, p_application_root_id uuid, p_owner_kind text, p_owner_id uuid, p_permission_id uuid); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.read_available_permission(p_organization_id uuid, p_application_root_id uuid, p_owner_kind text, p_owner_id uuid, p_permission_id uuid) IS 'Owner-only exact current permission lookup retaining application context, record scope and field policy.';


--
-- Name: read_capability_reservation_balance(uuid, uuid, text, text); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.read_capability_reservation_balance(
  p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text
)
returns table (result jsonb)
language plpgsql volatile security definer set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  effective record;
  balance record;
begin
  select locked.* into effective
  from vortex_access.lock_effective_capability_policy(
    p_tenant_id, p_organization_id, p_capability_key, p_unit, evaluated_at
  ) as locked;
  if effective.assignment_id is null then
    raise exception using errcode = 'V3101', message = 'Capability balance is unavailable';
  end if;
  select refreshed.* into strict balance
  from vortex_access.refresh_capability_reservation_balance(
    p_tenant_id, effective.request_organization_id, p_capability_key, p_unit,
    effective.applied_scope, effective.assignment_organization_id,
    effective.policy_id, effective.policy_revision, effective.assignment_id,
    effective.assignment_revision, effective.quantity_limit, evaluated_at
  ) as refreshed;
  return query select pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'tenantId', p_tenant_id, 'organizationId', effective.request_organization_id,
    'capabilityKey', p_capability_key, 'unit', p_unit,
    'policyId', effective.policy_id, 'policyRevision', effective.policy_revision,
    'assignmentId', effective.assignment_id,
    'assignmentRevision', effective.assignment_revision,
    'appliedScope', effective.applied_scope,
    'balance', pg_catalog.jsonb_build_object(
      'policyLimit', balance.policy_quantity_limit::text,
      'activeReservedQuantity', balance.active_reserved_quantity::text,
      'consumedQuantity', balance.consumed_quantity::text,
      'releasedQuantity', balance.released_quantity::text,
      'availableQuantity', balance.available_quantity::text),
    'evaluatedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  ));
end
$function$;


ALTER FUNCTION vortex_access.read_capability_reservation_balance(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION read_capability_reservation_balance(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.read_capability_reservation_balance(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) IS 'Returns current balance evidence after exact request-scope validation and policy resolution.';


--
-- Name: read_current_application_role_ids_for_launcher(); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.read_current_application_role_ids_for_launcher()
returns table (source_role_id uuid)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  checked_at timestamptz := pg_catalog.clock_timestamp();
begin
  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId'
    or (context_value ->> 'expiresAt')::timestamptz <= checked_at then
    return;
  end if;

  return query
  with current_roles as (
    select role.role_id, role.source_role_id, revision.assignment_policy,
      revision.authority_continuity_revision,
      revision.policy_continuity_revision, revision.activation_policy_id,
      revision.activation_policy_revision, revision.activation_policy_fingerprint
    from vortex_access.organization_roles as role
    join vortex_access.organization_role_revisions as revision
      on revision.organization_id = role.organization_id
      and revision.role_id = role.role_id
      and revision.revision = role.live_revision
    where role.organization_id = (context_value ->> 'organizationId')::uuid
      and role.application_root_id = (context_value ->> 'applicationRootId')::uuid
      and role.role_kind = 'application'
      and revision.lifecycle in ('active', 'acceptance_required')
  ), active_roles as (
    select role.source_role_id
    from current_roles as role
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = (context_value ->> 'organizationId')::uuid
      and assignment.role_id = role.role_id
      and assignment.assignee_kind = 'organization_account'
      and assignment.organization_account_id = (context_value ->> 'organizationAccountId')::uuid
      and assignment.assignment_kind = 'standing'
      and assignment.state = 'live'
      and assignment.starts_at <= checked_at
      and (assignment.expires_at is null or assignment.expires_at > checked_at)
    where role.assignment_policy = 'standing'

    union

    select role.source_role_id
    from current_roles as role
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = (context_value ->> 'organizationId')::uuid
      and assignment.role_id = role.role_id
      and assignment.assignee_kind = 'group'
      and assignment.assignment_kind = 'standing'
      and assignment.state = 'live'
      and assignment.starts_at <= checked_at
      and (assignment.expires_at is null or assignment.expires_at > checked_at)
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = assignment.organization_id
      and organization_group.group_id = assignment.group_id
      and organization_group.state = 'active'
    join vortex_access.organization_group_memberships as membership
      on membership.organization_id = assignment.organization_id
      and membership.group_id = assignment.group_id
      and membership.organization_account_id =
        (context_value ->> 'organizationAccountId')::uuid
      and membership.state = 'live'
      and membership.starts_at <= checked_at
      and (membership.expires_at is null or membership.expires_at > checked_at)
    where role.assignment_policy = 'standing'

    union

    select role.source_role_id
    from current_roles as role
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = (context_value ->> 'organizationId')::uuid
      and assignment.role_id = role.role_id
      and assignment.assignee_kind = 'organization_account'
      and assignment.organization_account_id = (context_value ->> 'organizationAccountId')::uuid
      and assignment.assignment_kind = 'eligible'
      and assignment.state = 'live'
      and assignment.starts_at <= checked_at
      and (assignment.expires_at is null or assignment.expires_at > checked_at)
    join vortex_access.organization_role_activations as activation
      on activation.organization_id = assignment.organization_id
      and activation.organization_account_id =
        (context_value ->> 'organizationAccountId')::uuid
      and activation.role_id = assignment.role_id
      and activation.eligibility_source_kind = 'direct'
      and activation.role_assignment_id = assignment.role_assignment_id
      and activation.role_assignment_revision = assignment.revision
      and activation.state = 'live'
      and activation.activated_at <= checked_at
      and activation.expires_at > checked_at
      and activation.authority_continuity_revision = role.authority_continuity_revision
      and activation.policy_continuity_revision = role.policy_continuity_revision
      and activation.activation_policy_id = role.activation_policy_id
      and activation.activation_policy_revision = role.activation_policy_revision
      and activation.activation_policy_fingerprint = role.activation_policy_fingerprint
    where role.assignment_policy = 'activation_required'

    union

    select role.source_role_id
    from current_roles as role
    join vortex_access.organization_role_assignments as assignment
      on assignment.organization_id = (context_value ->> 'organizationId')::uuid
      and assignment.role_id = role.role_id
      and assignment.assignee_kind = 'group'
      and assignment.assignment_kind = 'eligible'
      and assignment.state = 'live'
      and assignment.starts_at <= checked_at
      and (assignment.expires_at is null or assignment.expires_at > checked_at)
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = assignment.organization_id
      and organization_group.group_id = assignment.group_id
      and organization_group.state = 'active'
    join vortex_access.organization_role_activations as activation
      on activation.organization_id = assignment.organization_id
      and activation.organization_account_id =
        (context_value ->> 'organizationAccountId')::uuid
      and activation.role_id = assignment.role_id
      and activation.eligibility_source_kind = 'group'
      and activation.role_assignment_id = assignment.role_assignment_id
      and activation.role_assignment_revision = assignment.revision
      and activation.state = 'live'
      and activation.activated_at <= checked_at
      and activation.expires_at > checked_at
      and activation.authority_continuity_revision = role.authority_continuity_revision
      and activation.policy_continuity_revision = role.policy_continuity_revision
      and activation.activation_policy_id = role.activation_policy_id
      and activation.activation_policy_revision = role.activation_policy_revision
      and activation.activation_policy_fingerprint = role.activation_policy_fingerprint
    join vortex_access.organization_group_memberships as membership
      on membership.organization_id = assignment.organization_id
      and membership.group_id = assignment.group_id
      and membership.organization_account_id =
        (context_value ->> 'organizationAccountId')::uuid
      and membership.membership_id = activation.membership_id
      and membership.revision = activation.membership_revision
      and membership.state = 'live'
      and membership.starts_at <= checked_at
      and (membership.expires_at is null or membership.expires_at > checked_at)
    where role.assignment_policy = 'activation_required'
  )
  select active.source_role_id from active_roles as active
  order by active.source_role_id;
end
$function$;


