--
-- Name: read_flow_execution_binding(uuid, uuid, uuid, uuid, uuid, text, uuid, uuid, text, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.read_flow_execution_binding(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid) RETURNS TABLE(outcome text, effective_state text, result jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  authority record;
  current_binding vortex_access.flow_execution_bindings%rowtype;
begin
  if p_actor_identity_id is null or not vortex_context.is_non_nil_uuid(p_actor_identity_id::text)
    or p_actor_organization_account_id is null
    or not vortex_context.is_non_nil_uuid(p_actor_organization_account_id::text)
    or p_execution_binding_id is null or not vortex_context.is_non_nil_uuid(p_execution_binding_id::text)
    or p_organization_id is null or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_release_version is null
    or p_release_version !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or p_flow_id is null or not vortex_context.is_non_nil_uuid(p_flow_id::text)
    or p_node_id is null or not vortex_context.is_non_nil_uuid(p_node_id::text)
    or p_operation_owner_kind is null
    or p_operation_owner_kind not in ('application', 'module', 'platform_service')
    or p_operation_owner_id is null or not vortex_context.is_non_nil_uuid(p_operation_owner_id::text)
    or p_operation_id is null or not vortex_context.is_non_nil_uuid(p_operation_id::text)
    or p_actor_kind is null or p_actor_kind not in ('specified_user', 'system')
    or (p_actor_kind = 'specified_user' and (
      p_actor_account_id is null or not vortex_context.is_non_nil_uuid(p_actor_account_id::text)
      or p_actor_system_actor_id is not null))
    or (p_actor_kind = 'system' and (
      p_actor_system_actor_id is null or not vortex_context.is_non_nil_uuid(p_actor_system_actor_id::text)
      or p_actor_account_id is not null)) then
    raise exception using errcode = '22023', message = 'Flow execution binding read command is invalid';
  end if;

  select granted.* into strict authority
  from vortex_access.flow_execution_binding_authority_internal(
    p_actor_identity_id, p_actor_organization_account_id, p_organization_id, 'read'
  ) as granted;

  select binding.* into current_binding
  from vortex_access.flow_execution_bindings as binding
  where binding.execution_binding_id = p_execution_binding_id
    and binding.organization_id = p_organization_id
    and binding.is_current
    and binding.application_root_id = p_application_root_id
    and binding.release_version = p_release_version
    and binding.flow_id = p_flow_id
    and binding.node_id = p_node_id
    and binding.operation_owner_kind = p_operation_owner_kind
    and binding.operation_owner_id = p_operation_owner_id
    and binding.operation_id = p_operation_id
    and binding.actor_kind = p_actor_kind
    and binding.actor_organization_account_id is not distinct from p_actor_account_id
    and binding.actor_system_actor_id is not distinct from p_actor_system_actor_id;

  if not found then
    return query select 'unavailable'::text, null::text, null::jsonb;
    return;
  end if;

  return query select 'available'::text,
    case
      when current_binding.state = 'revoked' then 'revoked'
      when current_binding.expires_at is not null
        and current_binding.expires_at <= pg_catalog.clock_timestamp() then 'expired'
      else 'active'
    end,
    vortex_access.flow_execution_binding_to_json_internal(current_binding);
end
$_$;


ALTER FUNCTION vortex_access.read_flow_execution_binding(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid) OWNER TO postgres;

--
-- Name: read_flow_execution_binding_for_run(uuid, uuid, uuid, text, uuid, uuid, text, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.read_flow_execution_binding_for_run(
  p_execution_binding_id uuid,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_release_version text,
  p_flow_id uuid,
  p_node_id uuid,
  p_operation_owner_kind text,
  p_operation_owner_id uuid,
  p_operation_id uuid,
  p_actor_kind text,
  p_actor_account_id uuid,
  p_actor_system_actor_id uuid
)
returns table (
  outcome text,
  effective_state text,
  actor_state text,
  result jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  current_binding vortex_access.flow_execution_bindings%rowtype;
  account_state text;
begin
  if p_execution_binding_id is null or not vortex_context.is_non_nil_uuid(p_execution_binding_id::text)
    or p_organization_id is null or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_release_version is null
    or p_release_version !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or p_flow_id is null or not vortex_context.is_non_nil_uuid(p_flow_id::text)
    or p_node_id is null or not vortex_context.is_non_nil_uuid(p_node_id::text)
    or p_operation_owner_kind is null
    or p_operation_owner_kind not in ('application', 'module', 'platform_service')
    or p_operation_owner_id is null or not vortex_context.is_non_nil_uuid(p_operation_owner_id::text)
    or p_operation_id is null or not vortex_context.is_non_nil_uuid(p_operation_id::text)
    or p_actor_kind is null or p_actor_kind not in ('specified_user', 'system')
    or (p_actor_kind = 'specified_user' and (
      p_actor_account_id is null or not vortex_context.is_non_nil_uuid(p_actor_account_id::text)
      or p_actor_system_actor_id is not null))
    or (p_actor_kind = 'system' and (
      p_actor_system_actor_id is null or not vortex_context.is_non_nil_uuid(p_actor_system_actor_id::text)
      or p_actor_account_id is not null)) then
    raise exception using errcode = '22023', message = 'Flow execution binding run read command is invalid';
  end if;

  -- Share-lock the current revision. A writer that is mid-replace or mid-revoke
  -- holds the row FOR UPDATE, so this waits for it. Once that writer commits the
  -- row is no longer current for this statement's re-check and is skipped; the
  -- next statement takes a fresh snapshot and finds the new current revision.
  for attempt in 1..2 loop
    select binding.* into current_binding
    from vortex_access.flow_execution_bindings as binding
    where binding.execution_binding_id = p_execution_binding_id
      and binding.organization_id = p_organization_id
      and binding.is_current
      and binding.application_root_id = p_application_root_id
      and binding.release_version = p_release_version
      and binding.flow_id = p_flow_id
      and binding.node_id = p_node_id
      and binding.operation_owner_kind = p_operation_owner_kind
      and binding.operation_owner_id = p_operation_owner_id
      and binding.operation_id = p_operation_id
      and binding.actor_kind = p_actor_kind
      and binding.actor_organization_account_id is not distinct from p_actor_account_id
      and binding.actor_system_actor_id is not distinct from p_actor_system_actor_id
    for share;
    exit when found;
  end loop;

  -- A completed FOR loop overwrites FOUND, so test the selected row itself.
  if current_binding.execution_binding_id is null then
    return query select 'unavailable'::text, null::text, null::text, null::jsonb;
    return;
  end if;

  if current_binding.actor_kind = 'specified_user' then
    -- Ordered against a concurrent suspension or closure of the effective person,
    -- in main's Access-first order: the organisation access-version row before the
    -- Identity account row, as the request resolver and account lifecycle writers
    -- take them. Binding writers lock the binding before the access version, so
    -- taking the binding first above keeps this path consistent with them too.
    perform 1
    from vortex_access.organization_access_versions as version
    where version.organization_id = current_binding.organization_id
    for share of version;

    select account.state into account_state
    from vortex_identity.organization_accounts as account
    where account.organization_account_id = current_binding.actor_organization_account_id
      and account.organization_id = current_binding.organization_id
    for share of account;
    -- Only an active or suspended account in an active organisation keeps its
    -- state; closing, closed, deleted or missing is closed.
    if account_state is distinct from 'suspended' and (
      account_state is distinct from 'active' or not exists (
        select 1 from vortex_identity.organizations as organization
        where organization.organization_id = current_binding.organization_id
          and organization.state = 'active'
      )
    ) then
      account_state := 'closed';
    end if;
  else
    -- A system actor is active only while the one system actor grant registry
    -- holds an active grant for this actor, this protected operation and this
    -- flow in this organisation, and only in an active organisation; a missing
    -- or revoked grant, or an organisation that is not active, fails closed.
    account_state := case
      when vortex_access.resolve_system_actor_grant_internal(
        current_binding.actor_system_actor_id,
        current_binding.operation_id::text,
        current_binding.organization_id,
        current_binding.flow_id,
        null
      ) = 'active' and exists (
        select 1 from vortex_identity.organizations as organization
        where organization.organization_id = current_binding.organization_id
          and organization.state = 'active'
      ) then 'active'
      else 'closed'
    end;
  end if;

  return query select 'available'::text,
    case
      when current_binding.state = 'revoked' then 'revoked'
      when current_binding.expires_at is not null
        and current_binding.expires_at <= pg_catalog.clock_timestamp() then 'expired'
      else 'active'
    end,
    account_state,
    vortex_access.flow_execution_binding_to_json_internal(current_binding);
end
$function$;


ALTER FUNCTION vortex_access.read_flow_execution_binding_for_run(p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION read_flow_execution_binding_for_run(p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.read_flow_execution_binding_for_run(p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid) IS 'Runtime-only, share-locked read of one exact current flow execution binding and its effective actor state; a system actor is active only under an active system actor grant in an active organisation.';


--
-- Name: read_flow_run_as_principal_for_run(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.read_flow_run_as_principal_for_run(
  p_execution_binding_id uuid,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_release_version text,
  p_flow_id uuid
)
returns table (
  outcome text,
  result jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  current_principal vortex_access.flow_run_as_principals%rowtype;
  actor_state text;
begin
  if p_execution_binding_id is null or not vortex_context.is_non_nil_uuid(p_execution_binding_id::text)
    or p_organization_id is null or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_release_version is null
    or p_release_version !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or p_flow_id is null or not vortex_context.is_non_nil_uuid(p_flow_id::text) then
    raise exception using errcode = '22023', message = 'Flow run-as principal read command is invalid';
  end if;

  -- Share-lock the exact current revision. A concurrent replace or revoke either commits first
  -- and becomes the row this statement sees, or waits until this run has established its actor.
  for attempt in 1..2 loop
    select principal.* into current_principal
    from vortex_access.flow_run_as_principals as principal
    where principal.execution_binding_id = p_execution_binding_id
      and principal.organization_id = p_organization_id
      and principal.application_root_id = p_application_root_id
      and principal.release_version = p_release_version
      and principal.flow_id = p_flow_id
      and principal.is_current
    for share;
    exit when found;
  end loop;

  if current_principal.execution_binding_id is null
    or current_principal.state <> 'active'
    or (current_principal.expires_at is not null
      and current_principal.expires_at <= pg_catalog.clock_timestamp()) then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  -- Keep lifecycle changes ordered with a concurrent account suspension or closure.
  perform 1
  from vortex_access.organization_access_versions as version
  where version.organization_id = current_principal.organization_id
  for share of version;
  if not found then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  if current_principal.actor_kind = 'specified_account' then
    select account.state into actor_state
    from vortex_identity.organization_accounts as account
    where account.organization_account_id = current_principal.actor_organization_account_id
      and account.organization_id = current_principal.organization_id
    for share of account;
    if actor_state is distinct from 'active' then
      return query select 'unavailable'::text, null::jsonb;
      return;
    end if;
  else
    select actor_grant.state into actor_state
    from vortex_access.system_actor_grants as actor_grant
    where actor_grant.system_actor_id = current_principal.actor_system_actor_id
      and actor_grant.organization_id = current_principal.organization_id
      and (actor_grant.flow_id is null or actor_grant.flow_id = current_principal.flow_id)
      and actor_grant.state = 'active'
    order by (actor_grant.flow_id = current_principal.flow_id) desc
    limit 1
    for share of actor_grant;
    if actor_state is distinct from 'active' then
      return query select 'unavailable'::text, null::jsonb;
      return;
    end if;
  end if;

  if not exists (
    select 1 from vortex_identity.organizations as organization
    where organization.organization_id = current_principal.organization_id
      and organization.state = 'active'
  ) then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  if current_principal.expires_at is not null
    and current_principal.expires_at <= pg_catalog.clock_timestamp() then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  return query select 'available'::text,
    vortex_access.flow_run_as_principal_to_json_internal(current_principal);
end
$function$;


ALTER FUNCTION vortex_access.read_flow_run_as_principal_for_run(p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid) OWNER TO postgres;

