--
-- Name: read_organization_permission_for_administration(uuid, text, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: vortex_access_owner
--

create or replace function vortex_access.read_organization_permission_for_administration(
  p_application_root_id uuid,
  p_owner_kind text,
  p_owner_id uuid,
  p_permission_id uuid
)
returns table (
  organization_id uuid,
  outcome text,
  permission_summary jsonb,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  permission_value jsonb;
begin
  if p_owner_id is null or p_permission_id is null
    or p_owner_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_permission_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (
      (
        p_application_root_id is null
        and p_owner_kind = 'platform'
      )
      or (
        p_application_root_id is not null
        and p_owner_kind in ('application', 'module')
        and (
          p_owner_kind <> 'application'
          or p_owner_id = p_application_root_id
        )
      )
    ) is not true then
    raise exception using errcode = '22023',
      message = 'Organization permission catalogue detail input is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_permissions_administration_scope() as authorized;

  select pg_catalog.jsonb_strip_nulls(
    pg_catalog.jsonb_build_object(
      'reference', pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
          'applicationRootId', entry.application_root_id,
          'ownerKind', entry.owner_kind,
          'ownerId', entry.owner_id,
          'permissionId', entry.permission_id
        )
      ),
      'key', entry.permission_key,
      'label', entry.label,
      'description', entry.description,
      'recordTypeId', entry.record_type_id,
      'action', pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
          'actionKind', entry.action_kind,
          'namedAction', entry.named_action
        )
      ),
      'administrative', entry.administrative
    )
  )
  into permission_value
  from vortex_access.permission_catalogue_entries as entry
  join vortex_access.permission_registrations as registration
    on registration.organization_id = entry.organization_id
    and registration.registration_kind = entry.registration_kind
    and registration.registration_owner_id = entry.registration_owner_id
    and registration.revision = entry.registration_revision
  where entry.organization_id = scope.organization_id
    and registration.state = 'active'
    and entry.application_root_id is not distinct from p_application_root_id
    and entry.owner_kind = p_owner_kind
    and entry.owner_id = p_owner_id
    and entry.permission_id = p_permission_id;

  return query select scope.organization_id,
    case when permission_value is null then 'unavailable' else 'available' end,
    permission_value, scope.access_version;
end
$function$;


ALTER FUNCTION vortex_access.read_organization_permission_for_administration(p_application_root_id uuid, p_owner_kind text, p_owner_id uuid, p_permission_id uuid) OWNER TO vortex_access_owner;

--
-- Name: FUNCTION read_organization_permission_for_administration(p_application_root_id uuid, p_owner_kind text, p_owner_id uuid, p_permission_id uuid); Type: COMMENT; Schema: vortex_access; Owner: vortex_access_owner
--

COMMENT ON FUNCTION vortex_access.read_organization_permission_for_administration(p_application_root_id uuid, p_owner_kind text, p_owner_id uuid, p_permission_id uuid) IS 'Returns one safe current permission-catalogue detail under the fixed permissions-read decision.';


--
-- Name: read_organization_role_activation(uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.read_organization_role_activation(p_organization_id uuid, p_role_activation_id uuid) RETURNS TABLE(organization_id uuid, role_activation_id uuid, organization_account_id uuid, role_id uuid, revision bigint, historical_role_revision bigint, authority_continuity_revision bigint, policy_continuity_revision bigint, activation_policy_id uuid, activation_policy_revision bigint, activation_policy_fingerprint text, eligibility_source_kind text, role_assignment_id uuid, role_assignment_revision bigint, membership_id uuid, membership_revision bigint, state text, activated_by_actor_id uuid, activated_at timestamp with time zone, expires_at timestamp with time zone, activation_correlation_id uuid, changed_by_actor_id uuid, changed_at timestamp with time zone, change_correlation_id uuid, revoked_by_actor_id uuid, revoked_at timestamp with time zone, revocation_correlation_id uuid, temporal_state text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select activation.organization_id, activation.role_activation_id,
    activation.organization_account_id, activation.role_id,
    activation.revision, activation.historical_role_revision,
    activation.authority_continuity_revision,
    activation.policy_continuity_revision, activation.activation_policy_id,
    activation.activation_policy_revision,
    activation.activation_policy_fingerprint,
    activation.eligibility_source_kind, activation.role_assignment_id,
    activation.role_assignment_revision, activation.membership_id,
    activation.membership_revision, activation.state,
    activation.activated_by, activation.activated_at, activation.expires_at,
    activation.activation_correlation_id, activation.changed_by,
    activation.changed_at, activation.change_correlation_id,
    activation.revoked_by, activation.revoked_at,
    activation.revocation_correlation_id,
    case
      when activation.state = 'revoked' then 'revoked'
      when activation.expires_at <= clock.checked_at then 'expired'
      else 'active'
    end
  from vortex_access.organization_role_activations as activation
  cross join (
    select pg_catalog.statement_timestamp() as checked_at
  ) as clock
  where activation.organization_id = p_organization_id
    and activation.role_activation_id = p_role_activation_id
$$;


