--
-- Name: register_flow_execution_binding(uuid, uuid, uuid, uuid, uuid, uuid, text, uuid, uuid, text, uuid, uuid, text, uuid, uuid, jsonb, jsonb, jsonb, timestamp with time zone, bigint, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.register_flow_execution_binding(
  p_actor_identity_id uuid,
  p_actor_organization_account_id uuid,
  p_duplicate_key uuid,
  p_execution_binding_id uuid,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_release_version text,
  p_flow_id uuid,
  p_node_id uuid,
  p_operation_owner_kind text,
  p_operation_owner_id uuid,
  p_operation_id uuid,
  p_actor_kind text,
  p_actor_account_id uuid,
  p_actor_system_actor_id uuid,
  p_permitted_invokers jsonb,
  p_permitted_surfaces jsonb,
  p_permitted_inputs jsonb,
  p_expires_at timestamptz,
  p_expected_revision bigint,
  p_activity_id uuid
)
returns table (
  outcome text,
  result jsonb,
  correlation_id uuid,
  accepted_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  authority record;
  command_fingerprint text;
  receipt vortex_identity.accepted_administration_receipts%rowtype;
  current_binding vortex_access.flow_execution_bindings%rowtype;
  stored_binding vortex_access.flow_execution_bindings%rowtype;
  operation_at timestamptz;
  receipt_id uuid := pg_catalog.gen_random_uuid();
  next_revision bigint;
  activity_result text;
  permits_system boolean;
begin
  if p_actor_identity_id is null or not vortex_context.is_non_nil_uuid(p_actor_identity_id::text)
    or p_actor_organization_account_id is null
    or not vortex_context.is_non_nil_uuid(p_actor_organization_account_id::text)
    or p_duplicate_key is null or not vortex_context.is_non_nil_uuid(p_duplicate_key::text)
    or p_execution_binding_id is null or not vortex_context.is_non_nil_uuid(p_execution_binding_id::text)
    or p_organization_id is null or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_release_version is null
    or p_release_version !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or p_flow_id is null or not vortex_context.is_non_nil_uuid(p_flow_id::text)
    or p_node_id is null or not vortex_context.is_non_nil_uuid(p_node_id::text)
    or p_operation_owner_kind is null
    or p_operation_owner_kind not in ('application', 'module', 'platform_service')
    or p_operation_owner_id is null or not vortex_context.is_non_nil_uuid(p_operation_owner_id::text)
    or (p_operation_owner_kind = 'application' and p_operation_owner_id <> p_application_root_id)
    or p_operation_id is null or not vortex_context.is_non_nil_uuid(p_operation_id::text)
    or p_actor_kind is null or p_actor_kind not in ('specified_user', 'system')
    or (p_actor_kind = 'specified_user' and (
      p_actor_account_id is null or not vortex_context.is_non_nil_uuid(p_actor_account_id::text)
      or p_actor_system_actor_id is not null))
    or (p_actor_kind = 'system' and (
      p_actor_system_actor_id is null or not vortex_context.is_non_nil_uuid(p_actor_system_actor_id::text)
      or p_actor_account_id is not null))
    or p_permitted_invokers is null or pg_catalog.jsonb_typeof(p_permitted_invokers) <> 'array'
    or pg_catalog.jsonb_array_length(p_permitted_invokers) not between 1 and 20
    or p_permitted_surfaces is null or pg_catalog.jsonb_typeof(p_permitted_surfaces) <> 'array'
    or pg_catalog.jsonb_array_length(p_permitted_surfaces) not between 1 and 5
    or p_permitted_inputs is null or pg_catalog.jsonb_typeof(p_permitted_inputs) <> 'array'
    or pg_catalog.jsonb_array_length(p_permitted_inputs) > 20
    or (p_expected_revision is not null and p_expected_revision not between 1 and 9007199254740991)
    or (p_expires_at is not null and p_expires_at in ('-infinity'::timestamptz, 'infinity'::timestamptz))
    or p_activity_id is null or not vortex_context.is_non_nil_uuid(p_activity_id::text) then
    raise exception using errcode = '22023', message = 'Flow execution binding command is invalid';
  end if;

  -- Exact invoker, surface and input bounds: known shapes only, no duplicates.
  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_permitted_invokers) as invoker(value)
      where pg_catalog.jsonb_typeof(invoker.value) <> 'object'
        or not (
          (invoker.value = '{"kind":"system"}'::jsonb)
          or (
            invoker.value ->> 'kind' = 'organization_account'
            and (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(invoker.value)) = 2
            and pg_catalog.jsonb_typeof(invoker.value -> 'organizationAccountId') = 'string'
            and vortex_context.is_non_nil_uuid(invoker.value ->> 'organizationAccountId')
          )
        )
    )
    or (
      select pg_catalog.count(distinct case invoker.value ->> 'kind'
        when 'system' then 'system'
        else 'account:' || pg_catalog.lower(invoker.value ->> 'organizationAccountId')
      end)
      from pg_catalog.jsonb_array_elements(p_permitted_invokers) as invoker(value)
    ) <> pg_catalog.jsonb_array_length(p_permitted_invokers)
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_permitted_surfaces) as surface(value)
      where pg_catalog.jsonb_typeof(surface.value) <> 'string'
        or surface.value #>> '{}' not in (
          'web', 'mcp', 'programmatic_interface', 'connection', 'federation',
          'durable_workflow', 'system')
    )
    or (
      select pg_catalog.count(distinct surface.value)
      from pg_catalog.jsonb_array_elements(p_permitted_surfaces) as surface(value)
    ) <> pg_catalog.jsonb_array_length(p_permitted_surfaces)
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_permitted_inputs) as input(value)
      where pg_catalog.jsonb_typeof(input.value) <> 'string'
        or pg_catalog.char_length(input.value #>> '{}') not between 1 and 40
        or (input.value #>> '{}') !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
    )
    or (
      select pg_catalog.count(distinct input.value)
      from pg_catalog.jsonb_array_elements(p_permitted_inputs) as input(value)
    ) <> pg_catalog.jsonb_array_length(p_permitted_inputs) then
    raise exception using errcode = '22023', message = 'Flow execution binding bounds are invalid';
  end if;

  permits_system := p_permitted_invokers @> '[{"kind":"system"}]'::jsonb;
  if (p_actor_kind = 'system') <> permits_system then
    raise exception using errcode = '22023',
      message = 'Only a system execution binding permits, and must permit, the system origin';
  end if;

  select granted.* into strict authority
  from vortex_access.flow_execution_binding_authority_internal(
    p_actor_identity_id, p_actor_organization_account_id, p_organization_id, 'grant'
  ) as granted;

  command_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f',
      'register_flow_execution_binding',
      p_organization_id::text,
      p_execution_binding_id::text,
      p_application_root_id::text,
      p_release_version,
      p_flow_id::text,
      p_node_id::text,
      p_operation_owner_kind,
      p_operation_owner_id::text,
      p_operation_id::text,
      p_actor_kind,
      coalesce(p_actor_account_id::text, ''),
      coalesce(p_actor_system_actor_id::text, ''),
      p_permitted_invokers::text,
      p_permitted_surfaces::text,
      p_permitted_inputs::text,
      coalesce(vortex_context.format_timestamp_utc(p_expires_at), ''),
      coalesce(p_expected_revision::text, '')
    ), 'UTF8'),
    'sha256'), 'hex');

  select stored.* into receipt
  from vortex_identity.accepted_administration_receipts as stored
  where stored.actor_id = p_actor_organization_account_id
    and stored.tenant_id = authority.tenant_id
    and stored.operation_key = 'register_flow_execution_binding'
    and stored.duplicate_key = p_duplicate_key
  for update;

  if found then
    if receipt.command_fingerprint <> command_fingerprint
      or receipt.subject_ids <> array[p_execution_binding_id]
      or receipt.subject_revisions[1] is null then
      raise exception using errcode = 'V3001', message = 'Flow execution binding duplicate conflicts';
    end if;
    select binding.* into stored_binding
    from vortex_access.flow_execution_bindings as binding
    where binding.execution_binding_id = p_execution_binding_id
      and binding.revision = receipt.subject_revisions[1]
      and binding.organization_id = p_organization_id;
    if not found then
      raise exception using errcode = '42501', message = 'Flow execution binding replay is unavailable';
    end if;
    return query select 'replayed'::text,
      vortex_access.flow_execution_binding_to_json_internal(stored_binding),
      receipt.receipt_id,
      receipt.accepted_at;
    return;
  end if;

  -- The effective person and every named invoker must be active accounts of
  -- this organisation now; #686 re-checks their lifecycle at each use.
  if p_actor_kind = 'specified_user' and not exists (
      select 1 from vortex_identity.organization_accounts as account
      where account.organization_account_id = p_actor_account_id
        and account.organization_id = p_organization_id
        and account.state = 'active'
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_permitted_invokers) as invoker(value)
      where invoker.value ->> 'kind' = 'organization_account'
        and not exists (
          select 1 from vortex_identity.organization_accounts as account
          where account.organization_account_id = (invoker.value ->> 'organizationAccountId')::uuid
            and account.organization_id = p_organization_id
            and account.state = 'active'
        )
    ) then
    raise exception using errcode = '42501', message = 'Flow execution binding account is unavailable';
  end if;

  select binding.* into current_binding
  from vortex_access.flow_execution_bindings as binding
  where binding.execution_binding_id = p_execution_binding_id
    and binding.is_current
  for update;

  if found then
    if current_binding.organization_id is distinct from p_organization_id then
      raise exception using errcode = '23505', message = 'Flow execution binding identity is unavailable';
    end if;
    if p_expected_revision is null then
      raise exception using errcode = '23505', message = 'Flow execution binding already exists';
    end if;
    if current_binding.state = 'revoked' then
      raise exception using errcode = 'V3101', message = 'A revoked flow execution binding cannot be revived';
    end if;
    if current_binding.revision <> p_expected_revision then
      raise exception using errcode = 'V3102', message = 'Flow execution binding revision is stale';
    end if;
    if current_binding.application_root_id is distinct from p_application_root_id
      or current_binding.release_version is distinct from p_release_version
      or current_binding.flow_id is distinct from p_flow_id
      or current_binding.node_id is distinct from p_node_id
      or current_binding.operation_owner_kind is distinct from p_operation_owner_kind
      or current_binding.operation_owner_id is distinct from p_operation_owner_id
      or current_binding.operation_id is distinct from p_operation_id
      or current_binding.actor_kind is distinct from p_actor_kind
      or current_binding.actor_organization_account_id is distinct from p_actor_account_id
      or current_binding.actor_system_actor_id is distinct from p_actor_system_actor_id then
      raise exception using errcode = '22023', message = 'Flow execution binding scope is immutable';
    end if;
    next_revision := current_binding.revision + 1;
  else
    if p_expected_revision is not null then
      raise exception using errcode = 'V3102', message = 'Flow execution binding is unavailable';
    end if;
    next_revision := 1;
  end if;

  operation_at := pg_catalog.clock_timestamp();
  if p_expires_at is not null and p_expires_at <= operation_at then
    raise exception using errcode = '22023', message = 'Flow execution binding expiry must be in the future';
  end if;

  if next_revision > 1 then
    update vortex_access.flow_execution_bindings as binding
    set is_current = false
    where binding.execution_binding_id = p_execution_binding_id
      and binding.revision = current_binding.revision;
  end if;

  insert into vortex_access.flow_execution_bindings (
    execution_binding_id, revision, is_current,
    organization_id, application_root_id, release_version,
    flow_id, node_id, operation_owner_kind, operation_owner_id, operation_id,
    actor_kind, actor_organization_account_id, actor_system_actor_id,
    permitted_invokers, permitted_surfaces, permitted_inputs,
    expires_at, state, recorded_at, recorded_by_actor_id, recorded_correlation_id, revoked_at
  ) values (
    p_execution_binding_id, next_revision, true,
    p_organization_id, p_application_root_id, p_release_version,
    p_flow_id, p_node_id, p_operation_owner_kind, p_operation_owner_id, p_operation_id,
    p_actor_kind, p_actor_account_id, p_actor_system_actor_id,
    p_permitted_invokers, p_permitted_surfaces, p_permitted_inputs,
    p_expires_at, 'active', operation_at, p_actor_organization_account_id, authority.correlation_id, null
  ) returning * into stored_binding;

  perform 1 from vortex_access.increment_organization_access_version(
    p_organization_id, p_actor_organization_account_id, authority.correlation_id,
    'access_grant_changed'
  );

  activity_result := vortex_activity.append_organization_activity_entry(
    p_organization_id,
    p_activity_id,
    operation_at,
    'organization_account',
    p_actor_organization_account_id,
    case when next_revision = 1
      then 'register_flow_execution_binding'
      else 'replace_flow_execution_binding'
    end,
    array[p_execution_binding_id]::uuid[],
    array[]::uuid[],
    vortex_context.channel(),
    authority.correlation_id,
    'completed'
  );
  if activity_result is distinct from 'inserted' then
    raise exception using errcode = '40001', message = 'Flow execution binding Activity is stale';
  end if;

  insert into vortex_identity.accepted_administration_receipts (
    receipt_id, actor_id, tenant_id, operation_key, duplicate_key,
    command_fingerprint, subject_ids, subject_revisions, accepted_at
  ) values (
    receipt_id, p_actor_organization_account_id, authority.tenant_id,
    'register_flow_execution_binding', p_duplicate_key, command_fingerprint,
    array[p_execution_binding_id], array[next_revision], operation_at
  );

  return query select 'accepted'::text,
    vortex_access.flow_execution_binding_to_json_internal(stored_binding),
    receipt_id,
    operation_at;
end
$function$;


ALTER FUNCTION vortex_access.register_flow_execution_binding(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_duplicate_key uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid, p_permitted_invokers jsonb, p_permitted_surfaces jsonb, p_permitted_inputs jsonb, p_expires_at timestamp with time zone, p_expected_revision bigint, p_activity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION register_flow_execution_binding(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_duplicate_key uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid, p_permitted_invokers jsonb, p_permitted_surfaces jsonb, p_permitted_inputs jsonb, p_expires_at timestamp with time zone, p_expected_revision bigint, p_activity_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.register_flow_execution_binding(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_duplicate_key uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_node_id uuid, p_operation_owner_kind text, p_operation_owner_id uuid, p_operation_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid, p_permitted_invokers jsonb, p_permitted_surfaces jsonb, p_permitted_inputs jsonb, p_expires_at timestamp with time zone, p_expected_revision bigint, p_activity_id uuid) IS 'Registers or replaces one exact flow execution binding at its next revision; permitted surfaces are drawn from the one channel vocabulary.';


--
-- Name: register_flow_run_as_principal(uuid, uuid, uuid, uuid, uuid, uuid, text, uuid, text, uuid, uuid, timestamp with time zone, bigint, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.register_flow_run_as_principal(
  p_actor_identity_id uuid,
  p_actor_organization_account_id uuid,
  p_duplicate_key uuid,
  p_execution_binding_id uuid,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_release_version text,
  p_flow_id uuid,
  p_actor_kind text,
  p_actor_account_id uuid,
  p_actor_system_actor_id uuid,
  p_expires_at timestamptz,
  p_expected_revision bigint,
  p_activity_id uuid
)
returns table (
  outcome text,
  result jsonb,
  correlation_id uuid,
  accepted_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  authority record;
  command_fingerprint text;
  receipt vortex_identity.accepted_administration_receipts%rowtype;
  current_principal vortex_access.flow_run_as_principals%rowtype;
  stored_principal vortex_access.flow_run_as_principals%rowtype;
  operation_at timestamptz;
  receipt_id uuid := pg_catalog.gen_random_uuid();
  next_revision bigint;
  activity_result text;
begin
  if p_actor_identity_id is null or not vortex_context.is_non_nil_uuid(p_actor_identity_id::text)
    or p_actor_organization_account_id is null
    or not vortex_context.is_non_nil_uuid(p_actor_organization_account_id::text)
    or p_duplicate_key is null or not vortex_context.is_non_nil_uuid(p_duplicate_key::text)
    or p_execution_binding_id is null or not vortex_context.is_non_nil_uuid(p_execution_binding_id::text)
    or p_organization_id is null or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_release_version is null
    or p_release_version !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or p_flow_id is null or not vortex_context.is_non_nil_uuid(p_flow_id::text)
    or p_actor_kind is null or p_actor_kind not in ('specified_account', 'system')
    or (p_actor_kind = 'specified_account' and (
      p_actor_account_id is null or not vortex_context.is_non_nil_uuid(p_actor_account_id::text)
      or p_actor_system_actor_id is not null))
    or (p_actor_kind = 'system' and (
      p_actor_system_actor_id is null or not vortex_context.is_non_nil_uuid(p_actor_system_actor_id::text)
      or p_actor_account_id is not null))
    or (p_expected_revision is not null and p_expected_revision not between 1 and 9007199254740991)
    or (p_expires_at is not null and p_expires_at in ('-infinity'::timestamptz, 'infinity'::timestamptz))
    or p_activity_id is null or not vortex_context.is_non_nil_uuid(p_activity_id::text) then
    raise exception using errcode = '22023', message = 'Flow run-as principal command is invalid';
  end if;

  select granted.* into strict authority
  from vortex_access.flow_execution_binding_authority_internal(
    p_actor_identity_id, p_actor_organization_account_id, p_organization_id, 'grant'
  ) as granted;

  command_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f',
      'register_flow_run_as_principal',
      p_organization_id::text,
      p_execution_binding_id::text,
      p_application_root_id::text,
      p_release_version,
      p_flow_id::text,
      p_actor_kind,
      coalesce(p_actor_account_id::text, ''),
      coalesce(p_actor_system_actor_id::text, ''),
      coalesce(vortex_context.format_timestamp_utc(p_expires_at), ''),
      coalesce(p_expected_revision::text, '')
    ), 'UTF8'),
    'sha256'), 'hex');

  select stored.* into receipt
  from vortex_identity.accepted_administration_receipts as stored
  where stored.actor_id = p_actor_organization_account_id
    and stored.tenant_id = authority.tenant_id
    and stored.operation_key = 'register_flow_run_as_principal'
    and stored.duplicate_key = p_duplicate_key
  for update;

  if found then
    if receipt.command_fingerprint <> command_fingerprint
      or receipt.subject_ids <> array[p_execution_binding_id]
      or receipt.subject_revisions[1] is null then
      raise exception using errcode = 'V3001', message = 'Flow run-as principal duplicate conflicts';
    end if;
    select principal.* into stored_principal
    from vortex_access.flow_run_as_principals as principal
    where principal.execution_binding_id = p_execution_binding_id
      and principal.revision = receipt.subject_revisions[1]
      and principal.organization_id = p_organization_id;
    if not found then
      raise exception using errcode = '42501', message = 'Flow run-as principal replay is unavailable';
    end if;
    return query select 'replayed'::text,
      vortex_access.flow_run_as_principal_to_json_internal(stored_principal),
      receipt.receipt_id,
      receipt.accepted_at;
    return;
  end if;

  -- An account principal must be active in the named organisation. A System principal must
  -- already have an active Access registration scoped to that organisation and flow.
  if p_actor_kind = 'specified_account' and not exists (
      select 1 from vortex_identity.organization_accounts as account
      where account.organization_account_id = p_actor_account_id
        and account.organization_id = p_organization_id
        and account.state = 'active'
    )
    or p_actor_kind = 'system' and not exists (
      select 1 from vortex_access.system_actor_grants as actor_grant
      where actor_grant.system_actor_id = p_actor_system_actor_id
        and actor_grant.organization_id = p_organization_id
        and (actor_grant.flow_id is null or actor_grant.flow_id = p_flow_id)
        and actor_grant.state = 'active'
    ) then
    raise exception using errcode = '42501', message = 'Flow run-as principal actor is unavailable';
  end if;

  select principal.* into current_principal
  from vortex_access.flow_run_as_principals as principal
  where principal.execution_binding_id = p_execution_binding_id
    and principal.is_current
  for update;

  if found then
    if current_principal.organization_id is distinct from p_organization_id then
      raise exception using errcode = '42501', message = 'Flow run-as principal scope is unavailable';
    end if;
    if p_expected_revision is null then
      raise exception using errcode = '23505', message = 'Flow run-as principal already exists';
    end if;
    if current_principal.state = 'revoked' then
      raise exception using errcode = 'V3101', message = 'A revoked flow run-as principal cannot be revived';
    end if;
    if current_principal.revision <> p_expected_revision then
      raise exception using errcode = 'V3102', message = 'Flow run-as principal revision is stale';
    end if;
    if current_principal.application_root_id is distinct from p_application_root_id
      or current_principal.release_version is distinct from p_release_version
      or current_principal.flow_id is distinct from p_flow_id then
      raise exception using errcode = '22023', message = 'Flow run-as principal scope is immutable';
    end if;
    if current_principal.revision >= 9007199254740991 then
      raise exception using errcode = 'V3102', message = 'Flow run-as principal revision is exhausted';
    end if;
    next_revision := current_principal.revision + 1;
  else
    if p_expected_revision is not null then
      raise exception using errcode = 'V3102', message = 'Flow run-as principal is unavailable';
    end if;
    next_revision := 1;
  end if;

  operation_at := pg_catalog.clock_timestamp();
  if p_expires_at is not null and p_expires_at <= operation_at then
    raise exception using errcode = '22023', message = 'Flow run-as principal expiry must be in the future';
  end if;

  if next_revision > 1 then
    update vortex_access.flow_run_as_principals as principal
    set is_current = false
    where principal.execution_binding_id = p_execution_binding_id
      and principal.revision = current_principal.revision;
  end if;

  insert into vortex_access.flow_run_as_principals (
    execution_binding_id, revision, is_current,
    organization_id, application_root_id, release_version, flow_id,
    actor_kind, actor_organization_account_id, actor_system_actor_id,
    expires_at, state, recorded_at, recorded_by_actor_id, recorded_correlation_id, revoked_at
  ) values (
    p_execution_binding_id, next_revision, true,
    p_organization_id, p_application_root_id, p_release_version, p_flow_id,
    p_actor_kind, p_actor_account_id, p_actor_system_actor_id,
    p_expires_at, 'active', operation_at, p_actor_organization_account_id,
    authority.correlation_id, null
  ) returning * into stored_principal;

  perform 1 from vortex_access.increment_organization_access_version(
    p_organization_id, p_actor_organization_account_id, authority.correlation_id,
    'access_grant_changed'
  );

  activity_result := vortex_activity.append_organization_activity_entry(
    p_organization_id,
    p_activity_id,
    operation_at,
    'organization_account',
    p_actor_organization_account_id,
    case when next_revision = 1
      then 'register_flow_run_as_principal'
      else 'replace_flow_run_as_principal'
    end,
    array[p_execution_binding_id]::uuid[],
    array[]::uuid[],
    vortex_context.channel(),
    authority.correlation_id,
    'completed'
  );
  if activity_result is distinct from 'inserted' then
    raise exception using errcode = '40001', message = 'Flow run-as principal Activity is stale';
  end if;

  insert into vortex_identity.accepted_administration_receipts (
    receipt_id, actor_id, tenant_id, operation_key, duplicate_key,
    command_fingerprint, subject_ids, subject_revisions, accepted_at
  ) values (
    receipt_id, p_actor_organization_account_id, authority.tenant_id,
    'register_flow_run_as_principal', p_duplicate_key, command_fingerprint,
    array[p_execution_binding_id], array[next_revision], operation_at
  );

  return query select 'accepted'::text,
    vortex_access.flow_run_as_principal_to_json_internal(stored_principal),
    receipt_id,
    operation_at;
end
$function$;


ALTER FUNCTION vortex_access.register_flow_run_as_principal(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_duplicate_key uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid, p_expires_at timestamp with time zone, p_expected_revision bigint, p_activity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION register_flow_run_as_principal(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_duplicate_key uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid, p_expires_at timestamp with time zone, p_expected_revision bigint, p_activity_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.register_flow_run_as_principal(p_actor_identity_id uuid, p_actor_organization_account_id uuid, p_duplicate_key uuid, p_execution_binding_id uuid, p_organization_id uuid, p_application_root_id uuid, p_release_version text, p_flow_id uuid, p_actor_kind text, p_actor_account_id uuid, p_actor_system_actor_id uuid, p_expires_at timestamp with time zone, p_expected_revision bigint, p_activity_id uuid) IS 'Registers or replaces one exact compiled flow run-as principal under the existing execution-binding administration authority.';


--
-- Name: release_capability_reservation(uuid, uuid, text, text, uuid, bigint, uuid, bigint, uuid, uuid, numeric); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.release_capability_reservation(
  p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text,
  p_policy_id uuid, p_policy_revision bigint, p_assignment_id uuid,
  p_assignment_revision bigint, p_reservation_id uuid, p_duplicate_key uuid,
  p_quantity numeric default null
)
returns table (result jsonb)
language plpgsql volatile security definer set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  protected_context record;
  target vortex_access.capability_reservations%rowtype;
  existing_command vortex_access.capability_reservation_commands%rowtype;
  command_fingerprint text;
  remaining numeric;
  release_amount numeric;
  new_released numeric;
  new_remaining numeric;
  new_state text;
  balance record;
  safe_result jsonb;
  refusal_reason text;
begin
  if not vortex_access.capability_policy_key_is_valid(p_capability_key)
    or not vortex_access.capability_policy_unit_is_valid(p_unit)
    or p_policy_id is null or not vortex_context.is_non_nil_uuid(p_policy_id::text)
    or p_policy_revision not between 1 and 9007199254740991
    or p_assignment_id is null or not vortex_context.is_non_nil_uuid(p_assignment_id::text)
    or p_assignment_revision not between 1 and 9007199254740991
    or p_reservation_id is null or not vortex_context.is_non_nil_uuid(p_reservation_id::text)
    or (p_quantity is not null
      and not vortex_access.capability_policy_quantity_is_valid(p_quantity))
    or p_duplicate_key is null
    or not vortex_context.is_non_nil_uuid(p_duplicate_key::text) then
    raise exception using errcode = '22023', message = 'Capability release command is invalid';
  end if;
  select context.* into strict protected_context
  from vortex_access.capability_reservation_request_context(
    p_tenant_id, p_organization_id
  ) as context;
  command_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f',
      'release_capability_reservation', p_tenant_id::text,
      coalesce(protected_context.request_organization_id::text, ''),
      p_capability_key, p_unit, p_policy_id::text, p_policy_revision::text,
      p_assignment_id::text, p_assignment_revision::text,
      p_reservation_id::text, coalesce(p_quantity::text, 'all')), 'UTF8'), 'sha256'), 'hex');
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f', p_tenant_id::text,
      coalesce(protected_context.request_organization_id::text, ''),
      p_duplicate_key::text), 650)
  );
  select stored.* into existing_command
  from vortex_access.capability_reservation_commands as stored
  where stored.tenant_id = p_tenant_id
    and stored.request_organization_id
      is not distinct from protected_context.request_organization_id
    and stored.duplicate_key = p_duplicate_key for update;
  if found then
    if existing_command.operation_kind <> 'release'
      or existing_command.command_fingerprint <> command_fingerprint then
      raise exception using errcode = 'V3001', message = 'Capability release duplicate conflicts';
    end if;
    return query select pg_catalog.jsonb_set(
      existing_command.result, '{status}', '"replayed"'::jsonb, false
    );
    return;
  end if;
  select reservation.* into target
  from vortex_access.capability_reservations as reservation
  where reservation.reservation_id = p_reservation_id for update;
  if not found
    or target.tenant_id <> p_tenant_id
    or target.request_organization_id is distinct from protected_context.request_organization_id
    or target.capability_key <> p_capability_key or target.unit <> p_unit
    or target.policy_id <> p_policy_id or target.policy_revision <> p_policy_revision
    or target.assignment_id <> p_assignment_id
    or target.assignment_revision <> p_assignment_revision then
    refusal_reason := 'reservation_unavailable';
  elsif target.state <> 'active' or target.expires_at <= evaluated_at then
    if target.state = 'active' then
      update vortex_access.capability_reservations as reservation
      set state = 'expired', expired_at = evaluated_at, updated_at = evaluated_at
      where reservation.reservation_id = p_reservation_id;
    end if;
    refusal_reason := 'reservation_stale';
  else
    remaining := target.reserved_quantity - target.consumed_quantity - target.released_quantity;
    release_amount := coalesce(p_quantity, remaining);
    if release_amount <= 0 or release_amount > remaining then
      refusal_reason := 'insufficient_reserved_quantity';
    end if;
  end if;
  if refusal_reason is not null then
    safe_result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'status', 'accepted', 'reservationId', p_reservation_id,
      'tenantId', p_tenant_id,
      'organizationId', protected_context.request_organization_id,
      'capabilityKey', p_capability_key, 'unit', p_unit,
      'reasonCode', refusal_reason,
      'decidedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'correlationId', protected_context.correlation_id
    ));
    insert into vortex_access.capability_reservation_commands (
      tenant_id, request_organization_id, duplicate_key,
      operation_kind, command_fingerprint, reservation_id,
      result, correlation_id, accepted_at
    ) values (
      p_tenant_id, protected_context.request_organization_id, p_duplicate_key,
      'release', command_fingerprint,
      case when target.reservation_id is null then null else target.reservation_id end,
      safe_result, protected_context.correlation_id, evaluated_at
    );
    return query select safe_result;
    return;
  end if;
  new_released := target.released_quantity + release_amount;
  new_remaining := remaining - release_amount;
  new_state := case when new_remaining = 0 then 'released' else 'active' end;
  update vortex_access.capability_reservations as reservation
  set released_quantity = new_released, state = new_state,
      released_at = evaluated_at, updated_at = evaluated_at
  where reservation.reservation_id = p_reservation_id;
  select refreshed.* into strict balance
  from vortex_access.refresh_capability_reservation_balance(
    target.tenant_id, target.request_organization_id, target.capability_key, target.unit,
    target.applied_scope,
    case when target.applied_scope = 'organization'
      then target.request_organization_id else null::uuid end,
    target.policy_id, target.policy_revision, target.assignment_id,
    target.assignment_revision, target.policy_quantity_limit, evaluated_at
  ) as refreshed;
  safe_result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'outcome', 'released', 'status', 'accepted', 'reservationId', p_reservation_id,
    'tenantId', p_tenant_id, 'organizationId', target.request_organization_id,
    'capabilityKey', target.capability_key, 'unit', target.unit,
    'policyId', target.policy_id, 'policyRevision', target.policy_revision,
    'assignmentId', target.assignment_id,
    'assignmentRevision', target.assignment_revision,
    'appliedScope', target.applied_scope, 'releasedAmount', release_amount::text,
    'totalReleasedQuantity', new_released::text,
    'remainingReservedQuantity', new_remaining::text,
    'reservationState', new_state,
    'releasedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'correlationId', protected_context.correlation_id,
    'balance', pg_catalog.jsonb_build_object(
      'policyLimit', balance.policy_quantity_limit::text,
      'activeReservedQuantity', balance.active_reserved_quantity::text,
      'consumedQuantity', balance.consumed_quantity::text,
      'releasedQuantity', balance.released_quantity::text,
      'availableQuantity', balance.available_quantity::text)
  ));
  insert into vortex_access.capability_reservation_commands (
    tenant_id, request_organization_id, duplicate_key,
    operation_kind, command_fingerprint, reservation_id,
    result, correlation_id, accepted_at
  ) values (
    p_tenant_id, protected_context.request_organization_id, p_duplicate_key,
    'release', command_fingerprint, p_reservation_id,
    safe_result, protected_context.correlation_id, evaluated_at
  );
  return query select safe_result;
end
$function$;


ALTER FUNCTION vortex_access.release_capability_reservation(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_policy_id uuid, p_policy_revision bigint, p_assignment_id uuid, p_assignment_revision bigint, p_reservation_id uuid, p_duplicate_key uuid, p_quantity numeric) OWNER TO postgres;

--
-- Name: FUNCTION release_capability_reservation(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_policy_id uuid, p_policy_revision bigint, p_assignment_id uuid, p_assignment_revision bigint, p_reservation_id uuid, p_duplicate_key uuid, p_quantity numeric); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.release_capability_reservation(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_policy_id uuid, p_policy_revision bigint, p_assignment_id uuid, p_assignment_revision bigint, p_reservation_id uuid, p_duplicate_key uuid, p_quantity numeric) IS 'Releases an exact unexpired reservation and records the canonical refreshed balance in its immutable duplicate-protected outcome.';


--
-- Name: remove_organization_group_membership_for_administration(uuid, bigint, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.remove_organization_group_membership_for_administration(
  p_membership_id uuid,
  p_expected_membership_revision bigint,
  p_activity_id uuid
)
returns table (
  outcome text,
  organization_id uuid,
  membership_summary jsonb,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  context_organization_id uuid;
  context_account_id uuid;
  context_access_version bigint;
  context_correlation_id uuid;
  locked_access_version bigint;
  membership_fact vortex_access.organization_group_memberships%rowtype;
  authority_before jsonb;
  authority_requirement jsonb;
  decision record;
  changed record;
  changed_summary jsonb;
  activity_result text;
begin
  if p_membership_id is null
    or p_membership_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_membership_revision is null
    or p_expected_membership_revision not between 1 and 9007199254740991
    or p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization Group membership removal input is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  context_organization_id := (context_value ->> 'organizationId')::uuid;
  context_account_id := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version := (context_value ->> 'accessVersion')::bigint;
  context_correlation_id := (context_value ->> 'correlationId')::uuid;

  select version.current_version into locked_access_version
  from vortex_access.organization_access_versions as version
  join vortex_identity.organizations as organization
    on organization.organization_id = version.organization_id
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  where version.organization_id = context_organization_id
    and organization.state = 'active'
    and tenant.state = 'active'
  for update of version;
  if not found or locked_access_version is distinct from context_access_version then
    raise exception using errcode = '42501',
      message = 'Organization Group membership removal is unavailable';
  end if;

  select membership.* into membership_fact
  from vortex_access.organization_group_memberships as membership
  where membership.organization_id = context_organization_id
    and membership.membership_id = p_membership_id
  for update;
  if not found or membership_fact.revision <> p_expected_membership_revision
    or membership_fact.state <> 'live' then
    raise exception using errcode = '40001',
      message = 'Organization Group membership removal is stale or unavailable';
  end if;

  perform 1
  from vortex_access.organization_groups as organization_group
  where organization_group.organization_id = context_organization_id
    and organization_group.group_id = membership_fact.group_id
  for update;
  if not found then
    raise exception using errcode = '40001',
      message = 'Organization Group membership source is unavailable';
  end if;

  authority_before := vortex_access.organization_group_reduction_authority(
    context_organization_id, membership_fact.group_id
  );
  authority_requirement := case authority_before ->> 'kind'
    when 'none' then pg_catalog.jsonb_build_object('kind', 'permission')
    else pg_catalog.jsonb_build_object(
      'kind', 'delegated_management',
      'before', authority_before,
      'after', pg_catalog.jsonb_build_object('kind', 'none')
    )
  end;

  select evaluated.* into strict decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.group_memberships.remove',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '6185dc64-464b-4776-97dc-c64a6f299550'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', authority_requirement
    )
  ) as evaluated;
  if decision.outcome = 'refused'
    and decision.operation_key = 'platform.organization.group_memberships.remove'
    and decision.target_kind = 'organization'
    and decision.target_application_root_id is null
    and decision.organization_id = context_organization_id
    and decision.organization_account_id = context_account_id
    and decision.access_version = context_access_version
    and decision.correlation_id = context_correlation_id
    and decision.reason_code in (
      'permission_unavailable', 'permission_not_effective',
      'authentication_unsatisfied', 'delegation_insufficient'
    ) then
    activity_result := vortex_activity.append_organization_activity_entry(
      context_organization_id, p_activity_id, decision.checked_at,
      'organization_account', context_account_id, 'remove_group_membership',
      array[context_organization_id]::uuid[], array[]::uuid[], vortex_context.channel(),
      context_correlation_id, 'refused'
    );
    if activity_result is distinct from 'inserted' then
      raise exception using errcode = '40001',
        message = 'Organization Group membership removal refusal Activity is stale';
    end if;
    return query select 'refused'::text, context_organization_id,
      null::jsonb, context_access_version;
    return;
  end if;

  if decision.outcome is distinct from 'eligible'
    or decision.operation_key is distinct from 'platform.organization.group_memberships.remove'
    or decision.target_kind is distinct from 'organization'
    or decision.target_application_root_id is not null
    or decision.organization_id is distinct from context_organization_id
    or decision.organization_account_id is distinct from context_account_id
    or decision.access_version is distinct from context_access_version
    or decision.correlation_id is distinct from context_correlation_id then
    raise exception using errcode = '42501',
      message = 'Organization Group membership removal is unavailable';
  end if;

  select result.* into strict changed
  from vortex_access.coordinate_organization_group_membership_change(
    'remove_membership', context_organization_id, p_membership_id,
    p_expected_membership_revision, null, null, null, null, null,
    context_account_id, context_correlation_id
  ) as result;

  select pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'membershipId', membership.membership_id,
    'groupId', membership.group_id,
    'organizationAccountId', membership.organization_account_id,
    'accountDisplayName', account.display_name,
    'revision', membership.revision,
    'startsAt', membership.starts_at,
    'expiresAt', membership.expires_at,
    'state', membership.state,
    'temporalState', 'revoked'
  )) into strict changed_summary
  from vortex_access.organization_group_memberships as membership
  join vortex_identity.organization_accounts as account
    on account.organization_id = membership.organization_id
    and account.organization_account_id = membership.organization_account_id
  where membership.organization_id = context_organization_id
    and membership.membership_id = p_membership_id;

  activity_result := vortex_activity.append_organization_activity_entry(
    context_organization_id, p_activity_id,
    (changed.membership ->> 'changedAt')::timestamptz,
    'organization_account', context_account_id, 'remove_group_membership',
    array[p_membership_id]::uuid[], array[]::uuid[], vortex_context.channel(),
    context_correlation_id, 'completed'
  );
  if activity_result is distinct from 'inserted' then
    raise exception using errcode = '40001',
      message = 'Organization Group membership removal Activity is stale';
  end if;

  return query select 'completed'::text, context_organization_id, changed_summary,
    changed.access_version;
end
$function$;


ALTER FUNCTION vortex_access.remove_organization_group_membership_for_administration(p_membership_id uuid, p_expected_membership_revision bigint, p_activity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION remove_organization_group_membership_for_administration(p_membership_id uuid, p_expected_membership_revision bigint, p_activity_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.remove_organization_group_membership_for_administration(p_membership_id uuid, p_expected_membership_revision bigint, p_activity_id uuid) IS 'Standalone request entry: performs remove_group_membership after fixed protected checks, records one atomic completed Activity or returns one content-free refused Activity row; no SQL function composes this result.';


--
-- Name: rename_organization_group_for_administration(uuid, bigint, text, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.rename_organization_group_for_administration(
  p_group_id uuid,
  p_expected_group_revision bigint,
  p_label text,
  p_activity_id uuid
)
returns table (
  outcome text,
  organization_id uuid,
  group_summary jsonb,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  context_organization_id uuid;
  context_account_id uuid;
  context_access_version bigint;
  context_correlation_id uuid;
  locked_access_version bigint;
  group_fact vortex_access.organization_groups%rowtype;
  decision record;
  changed record;
  activity_result text;
begin
  if p_group_id is null
    or p_group_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_group_revision is null
    or p_expected_group_revision not between 1 and 9007199254740991
    or p_label is null
    or p_label <> pg_catalog.btrim(p_label)
    or pg_catalog.char_length(p_label) not between 1 and 60
    or p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization Group label revision input is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  context_organization_id := (context_value ->> 'organizationId')::uuid;
  context_account_id := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version := (context_value ->> 'accessVersion')::bigint;
  context_correlation_id := (context_value ->> 'correlationId')::uuid;

  select version.current_version into locked_access_version
  from vortex_access.organization_access_versions as version
  join vortex_identity.organizations as organization
    on organization.organization_id = version.organization_id
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  where version.organization_id = context_organization_id
    and organization.state = 'active'
    and tenant.state = 'active'
  for update of version;
  if not found or locked_access_version is distinct from context_access_version then
    raise exception using errcode = '42501',
      message = 'Organization Group label revision is unavailable';
  end if;

  select organization_group.* into group_fact
  from vortex_access.organization_groups as organization_group
  where organization_group.organization_id = context_organization_id
    and organization_group.group_id = p_group_id
  for update;
  if not found or group_fact.revision <> p_expected_group_revision
    or group_fact.state <> 'active' then
    raise exception using errcode = '40001',
      message = 'Organization Group change is stale or unavailable';
  end if;
  if group_fact.label is not distinct from p_label then
    raise exception using errcode = '40001',
      message = 'Organization Group label is unchanged';
  end if;

  select evaluated.* into strict decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.groups.rename',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '6185dc64-464b-4776-97dc-c64a6f299550'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;

  if decision.outcome = 'refused'
    and decision.operation_key = 'platform.organization.groups.rename'
    and decision.target_kind = 'organization'
    and decision.target_application_root_id is null
    and decision.organization_id = context_organization_id
    and decision.organization_account_id = context_account_id
    and decision.access_version = context_access_version
    and decision.correlation_id = context_correlation_id
    and decision.reason_code in (
      'permission_unavailable', 'permission_not_effective',
      'authentication_unsatisfied', 'delegation_insufficient'
    ) then
    activity_result := vortex_activity.append_organization_activity_entry(
      context_organization_id, p_activity_id, decision.checked_at,
      'organization_account', context_account_id, 'revise_group_label',
      array[context_organization_id]::uuid[], array[]::uuid[], vortex_context.channel(),
      context_correlation_id, 'refused'
    );
    if activity_result is distinct from 'inserted' then
      raise exception using errcode = '40001',
        message = 'Organization Group label revision refusal Activity is stale';
    end if;
    return query select 'refused'::text, context_organization_id,
      null::jsonb, context_access_version;
    return;
  end if;

  if decision.outcome is distinct from 'eligible'
    or decision.operation_key is distinct from
      'platform.organization.groups.rename'
    or decision.target_kind is distinct from 'organization'
    or decision.target_application_root_id is not null
    or decision.organization_id is distinct from context_organization_id
    or decision.organization_account_id is distinct from context_account_id
    or decision.access_version is distinct from context_access_version
    or decision.correlation_id is distinct from context_correlation_id then
    raise exception using errcode = '42501',
      message = 'Organization Group label revision is unavailable';
  end if;

  select group_change.* into strict changed
  from vortex_access.coordinate_organization_group_change(
    'revise_group_label', context_organization_id, p_group_id,
    p_expected_group_revision, null, p_label,
    context_account_id, context_correlation_id
  ) as group_change;

  activity_result := vortex_activity.append_organization_activity_entry(
    context_organization_id, p_activity_id, changed.changed_at,
    'organization_account', context_account_id, 'revise_group_label',
    array[p_group_id]::uuid[], array[]::uuid[], vortex_context.channel(),
    context_correlation_id, 'completed'
  );
  if activity_result is distinct from 'inserted' then
    raise exception using errcode = '40001',
      message = 'Organization Group label revision Activity is stale';
  end if;

  return query select 'completed'::text, context_organization_id,
    pg_catalog.jsonb_build_object(
      'groupId', changed.group_id, 'key', changed.group_key,
      'label', changed.label, 'state', changed.state,
      'revision', changed.revision
    ), changed.access_version;
end
$function$;


ALTER FUNCTION vortex_access.rename_organization_group_for_administration(p_group_id uuid, p_expected_group_revision bigint, p_label text, p_activity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rename_organization_group_for_administration(p_group_id uuid, p_expected_group_revision bigint, p_label text, p_activity_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.rename_organization_group_for_administration(p_group_id uuid, p_expected_group_revision bigint, p_label text, p_activity_id uuid) IS 'Standalone request entry: revises one Group label after fixed teams-manage authorization, records one atomic completed Activity or returns one content-free refused Activity row; no SQL function composes this result.';


--
-- Name: require_platform_operator_internal(uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.require_platform_operator_internal(
  p_operator_actor_id uuid
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  if p_operator_actor_id is null
    or not vortex_context.is_non_nil_uuid(p_operator_actor_id::text) then
    raise exception using errcode = '22023', message = 'Platform operator is invalid';
  end if;
  -- The platform operator is the configured system operator: trusted server
  -- configuration reached only through the runtime role, never a person's
  -- request. A transaction that carries a request context is a customer path,
  -- so no tenant or organisation role, delegation or session can reach here.
  if exists (
    select 1
    from vortex_context.request_contexts as established
    where established.backend_pid = pg_catalog.pg_backend_pid()
      and established.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
  ) then
    raise exception using errcode = '42501', message = 'Platform operator authority is unavailable';
  end if;
end
$function$;


ALTER FUNCTION vortex_access.require_platform_operator_internal(p_operator_actor_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION require_platform_operator_internal(p_operator_actor_id uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.require_platform_operator_internal(p_operator_actor_id uuid) IS 'Private: refuses unless the caller is the configured platform operator in a transaction that carries no request context, so no customer role or request can act as the operator.';


--
-- Name: reserve_capability_quantity(uuid, uuid, text, text, jsonb, numeric, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.reserve_capability_quantity(
  p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text,
  p_policy_claim jsonb, p_requested_quantity numeric, p_duplicate_key uuid
)
returns table (result jsonb)
language plpgsql volatile security definer set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  effective record;
  protected_context record;
  balance record;
  existing_command vortex_access.capability_reservation_commands%rowtype;
  command_fingerprint text;
  reservation_id uuid;
  expires_at timestamptz;
  safe_result jsonb;
begin
  if not vortex_access.capability_policy_key_is_valid(p_capability_key)
    or not vortex_access.capability_policy_unit_is_valid(p_unit)
    or p_policy_claim is null or pg_catalog.jsonb_typeof(p_policy_claim) <> 'object'
    or not vortex_access.capability_policy_quantity_is_valid(p_requested_quantity)
    or p_duplicate_key is null
    or not vortex_context.is_non_nil_uuid(p_duplicate_key::text) then
    raise exception using errcode = '22023', message = 'Capability reservation command is invalid';
  end if;
  select locked.* into effective
  from vortex_access.lock_effective_capability_policy(
    p_tenant_id, p_organization_id, p_capability_key, p_unit, evaluated_at
  ) as locked;
  if effective.correlation_id is null then
    select context.* into strict protected_context
    from vortex_access.capability_reservation_request_context(
      p_tenant_id, p_organization_id
    ) as context;
  else
    protected_context := effective;
  end if;
  command_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f',
      'reserve_capability_quantity', p_tenant_id::text,
      coalesce(protected_context.request_organization_id::text, ''),
      p_capability_key, p_unit, p_policy_claim::text,
      p_requested_quantity::text), 'UTF8'), 'sha256'), 'hex');
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f', p_tenant_id::text,
      coalesce(protected_context.request_organization_id::text, ''),
      p_duplicate_key::text), 650)
  );
  select stored.* into existing_command
  from vortex_access.capability_reservation_commands as stored
  where stored.tenant_id = p_tenant_id
    and stored.request_organization_id
      is not distinct from protected_context.request_organization_id
    and stored.duplicate_key = p_duplicate_key for update;
  if found then
    if existing_command.operation_kind <> 'reserve'
      or existing_command.command_fingerprint <> command_fingerprint then
      raise exception using errcode = 'V3001', message = 'Capability reservation duplicate conflicts';
    end if;
    return query select pg_catalog.jsonb_set(
      existing_command.result, '{status}', '"replayed"'::jsonb, false
    );
    return;
  end if;
  if effective.assignment_id is null then
    safe_result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'status', 'accepted', 'tenantId', p_tenant_id,
      'organizationId', protected_context.request_organization_id,
      'capabilityKey', p_capability_key, 'unit', p_unit,
      'requestedQuantity', p_requested_quantity::text,
      'reasonCode', 'capability_not_assigned',
      'decidedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'correlationId', protected_context.correlation_id
    ));
    insert into vortex_access.capability_reservation_commands (
      tenant_id, request_organization_id, duplicate_key,
      operation_kind, command_fingerprint, result,
      correlation_id, accepted_at
    ) values (
      p_tenant_id, protected_context.request_organization_id, p_duplicate_key,
      'reserve', command_fingerprint, safe_result,
      protected_context.correlation_id, evaluated_at
    );
    return query select safe_result;
    return;
  end if;
  select refreshed.* into strict balance
  from vortex_access.refresh_capability_reservation_balance(
    p_tenant_id, effective.request_organization_id, p_capability_key, p_unit,
    effective.applied_scope, effective.assignment_organization_id,
    effective.policy_id, effective.policy_revision, effective.assignment_id,
    effective.assignment_revision, effective.quantity_limit, evaluated_at
  ) as refreshed;
  if balance.available_quantity < p_requested_quantity then
    safe_result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'status', 'accepted', 'tenantId', p_tenant_id,
      'organizationId', effective.request_organization_id,
      'capabilityKey', p_capability_key, 'unit', p_unit,
      'policyId', effective.policy_id, 'policyRevision', effective.policy_revision,
      'assignmentId', effective.assignment_id,
      'assignmentRevision', effective.assignment_revision,
      'appliedScope', effective.applied_scope,
      'requestedQuantity', p_requested_quantity::text,
      'reasonCode', 'insufficient_capacity',
      'decidedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'correlationId', effective.correlation_id,
      'balance', pg_catalog.jsonb_build_object(
        'policyLimit', balance.policy_quantity_limit::text,
        'activeReservedQuantity', balance.active_reserved_quantity::text,
        'consumedQuantity', balance.consumed_quantity::text,
        'releasedQuantity', balance.released_quantity::text,
        'availableQuantity', balance.available_quantity::text)
    ));
    insert into vortex_access.capability_reservation_commands (
      tenant_id, request_organization_id, duplicate_key,
      operation_kind, command_fingerprint, result,
      correlation_id, accepted_at
    ) values (
      p_tenant_id, effective.request_organization_id, p_duplicate_key,
      'reserve', command_fingerprint, safe_result,
      effective.correlation_id, evaluated_at
    );
    return query select safe_result;
    return;
  end if;
  expires_at := least(evaluated_at + interval '300 seconds',
    effective.request_expires_at,
    coalesce(effective.assignment_expires_at, 'infinity'::timestamptz));
  if expires_at <= evaluated_at then
    safe_result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'status', 'accepted', 'tenantId', p_tenant_id,
      'organizationId', effective.request_organization_id,
      'capabilityKey', p_capability_key, 'unit', p_unit,
      'policyId', effective.policy_id, 'policyRevision', effective.policy_revision,
      'assignmentId', effective.assignment_id,
      'assignmentRevision', effective.assignment_revision,
      'appliedScope', effective.applied_scope,
      'requestedQuantity', p_requested_quantity::text, 'reasonCode', 'policy_stale',
      'decidedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'correlationId', effective.correlation_id
    ));
    insert into vortex_access.capability_reservation_commands (
      tenant_id, request_organization_id, duplicate_key,
      operation_kind, command_fingerprint, result,
      correlation_id, accepted_at
    ) values (
      p_tenant_id, effective.request_organization_id, p_duplicate_key,
      'reserve', command_fingerprint, safe_result,
      effective.correlation_id, evaluated_at
    );
    return query select safe_result;
    return;
  end if;
  reservation_id := pg_catalog.gen_random_uuid();
  insert into vortex_access.capability_reservations (
    reservation_id, tenant_id, request_organization_id, capability_key, unit,
    policy_id, policy_revision, assignment_id, assignment_revision,
    applied_scope, policy_quantity_limit, reserved_quantity,
    consumed_quantity, released_quantity, state, created_at, expires_at,
    updated_at, reserve_duplicate_key, correlation_id
  ) values (
    reservation_id, p_tenant_id, effective.request_organization_id,
    p_capability_key, p_unit, effective.policy_id, effective.policy_revision,
    effective.assignment_id, effective.assignment_revision,
    effective.applied_scope, effective.quantity_limit, p_requested_quantity,
    0, 0, 'active', evaluated_at, expires_at, evaluated_at,
    p_duplicate_key, effective.correlation_id
  );
  select refreshed.* into strict balance
  from vortex_access.refresh_capability_reservation_balance(
    p_tenant_id, effective.request_organization_id, p_capability_key, p_unit,
    effective.applied_scope, effective.assignment_organization_id,
    effective.policy_id, effective.policy_revision, effective.assignment_id,
    effective.assignment_revision, effective.quantity_limit, evaluated_at
  ) as refreshed;
  safe_result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'outcome', 'reserved', 'status', 'accepted', 'reservationId', reservation_id,
    'tenantId', p_tenant_id, 'organizationId', effective.request_organization_id,
    'capabilityKey', p_capability_key, 'unit', p_unit,
    'policyId', effective.policy_id, 'policyRevision', effective.policy_revision,
    'assignmentId', effective.assignment_id,
    'assignmentRevision', effective.assignment_revision,
    'appliedScope', effective.applied_scope,
    'reservedQuantity', p_requested_quantity::text,
    'reservedAt', pg_catalog.to_char(evaluated_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'expiresAt', pg_catalog.to_char(expires_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'correlationId', effective.correlation_id,
    'balance', pg_catalog.jsonb_build_object(
      'policyLimit', balance.policy_quantity_limit::text,
      'activeReservedQuantity', balance.active_reserved_quantity::text,
      'consumedQuantity', balance.consumed_quantity::text,
      'releasedQuantity', balance.released_quantity::text,
      'availableQuantity', balance.available_quantity::text)
  ));
  insert into vortex_access.capability_reservation_commands (
    tenant_id, request_organization_id, duplicate_key,
    operation_kind, command_fingerprint, reservation_id,
    result, correlation_id, accepted_at
  ) values (
    p_tenant_id, effective.request_organization_id, p_duplicate_key,
    'reserve', command_fingerprint, reservation_id,
    safe_result, effective.correlation_id, evaluated_at
  );
  return query select safe_result;
end
$function$;


ALTER FUNCTION vortex_access.reserve_capability_quantity(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_policy_claim jsonb, p_requested_quantity numeric, p_duplicate_key uuid) OWNER TO postgres;

--
-- Name: FUNCTION reserve_capability_quantity(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_policy_claim jsonb, p_requested_quantity numeric, p_duplicate_key uuid); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.reserve_capability_quantity(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text, p_policy_claim jsonb, p_requested_quantity numeric, p_duplicate_key uuid) IS 'Resolves and locks current organisation-preferred policy, then atomically reserves or records a safe refusal.';


--
-- Name: resolve_durable_system_actor_scope(uuid, uuid, uuid, text); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.resolve_durable_system_actor_scope(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_flow_id uuid,
  p_operation_key text
)
returns table (
  system_actor_id uuid,
  tenant_id uuid,
  organization_id uuid,
  application_root_id uuid,
  access_version bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  resolved_tenant_id uuid;
  resolved_access_version bigint;
  granted_actor_ids uuid[];
begin
  if p_organization_id is null or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_flow_id is null or not vortex_context.is_non_nil_uuid(p_flow_id::text)
    or p_operation_key is null
    or pg_catalog.octet_length(p_operation_key) not between 1 and 128
    or p_operation_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' then
    raise exception using errcode = '22023',
      message = 'Durable system actor selection is invalid';
  end if;

  -- The organisation and its access version are share-locked before the grant
  -- is read, in the request resolver's Access-first order, so a concurrent
  -- suspension or grant revocation either commits first and is seen here or
  -- waits for this transaction.
  select organization.tenant_id, version.current_version
  into resolved_tenant_id, resolved_access_version
  from vortex_identity.organizations as organization
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  join vortex_access.organization_access_versions as version
    on version.organization_id = organization.organization_id
  where organization.organization_id = p_organization_id
    and organization.state = 'active'
    and tenant.state = 'active'
  for share of organization, tenant, version;

  if resolved_tenant_id is null
    or not exists (
      select 1
      from vortex_access.permission_registrations as registration
      where registration.organization_id = p_organization_id
        and registration.registration_kind = 'application'
        and registration.registration_owner_id = p_application_root_id
        and registration.state = 'active'
    ) then
    raise exception using errcode = '42501',
      message = 'Durable system actor selection is unavailable';
  end if;

  -- The effective system actor is the holder of the one active system actor
  -- grant for exactly this protected operation, organisation, flow and
  -- application source (scope key `application:<application root id>`). The
  -- matched rows stay share-locked until the transaction ends. No grant, or more
  -- than one, refuses: an engine signature, run-as label or installation names
  -- no actor and confers no authority.
  select pg_catalog.array_agg(matched.system_actor_id)
  into granted_actor_ids
  from (
    select actor_grant.system_actor_id
    from vortex_access.system_actor_grants as actor_grant
    where actor_grant.operation_key = p_operation_key
      and actor_grant.organization_id = p_organization_id
      and (actor_grant.flow_id is null or actor_grant.flow_id = p_flow_id)
      and actor_grant.scope_key =
        'application:' || pg_catalog.lower(p_application_root_id::text)
      and actor_grant.state = 'active'
    for share of actor_grant
  ) as matched;

  if granted_actor_ids is null or pg_catalog.cardinality(granted_actor_ids) <> 1 then
    raise exception using errcode = '42501',
      message = 'Durable system actor selection is unavailable';
  end if;

  return query select granted_actor_ids[1], resolved_tenant_id, p_organization_id,
    p_application_root_id, resolved_access_version;
end
$function$;


ALTER FUNCTION vortex_access.resolve_durable_system_actor_scope(p_organization_id uuid, p_application_root_id uuid, p_flow_id uuid, p_operation_key text) OWNER TO postgres;

--
-- Name: FUNCTION resolve_durable_system_actor_scope(p_organization_id uuid, p_application_root_id uuid, p_flow_id uuid, p_operation_key text); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.resolve_durable_system_actor_scope(p_organization_id uuid, p_application_root_id uuid, p_flow_id uuid, p_operation_key text) IS 'Resolves the system actor and closed request scope of one durable workflow protected operation from the system actor grant registry. Refuses unless an active organisation holds an active application registration and exactly one active grant exists for this operation, organisation, flow and application source; an engine signature, run-as label or installation names no actor and confers nothing. Runtime-only.';


--
-- Name: resolve_effective_capability_policy(uuid, uuid, text, text); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.resolve_effective_capability_policy(
  p_tenant_id uuid,
  p_organization_id uuid,
  p_capability_key text,
  p_unit text
)
returns table (
  outcome text,
  tenant_id uuid,
  organization_id uuid,
  capability_key text,
  unit text,
  applied_scope text,
  applied_limit text,
  policy_id uuid,
  policy_revision bigint,
  assignment_id uuid,
  assignment_revision bigint,
  quantity_limit numeric,
  ceiling_quantity_limit numeric,
  resolved_at timestamptz,
  reason_code text
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  context jsonb := vortex_context.current_context();
  context_organization_id uuid;
  effective_organization_id uuid;
  actor_identity_id uuid;
  selected record;
begin
  if p_tenant_id is null or not vortex_context.is_non_nil_uuid(p_tenant_id::text)
    or (p_organization_id is not null and not vortex_context.is_non_nil_uuid(p_organization_id::text))
    or not vortex_access.capability_policy_key_is_valid(p_capability_key)
    or not vortex_access.capability_policy_unit_is_valid(p_unit) then
    raise exception using errcode = '22023', message = 'Capability policy resolution is invalid';
  end if;
  context_organization_id := (context ->> 'organizationId')::uuid;
  -- The established organisation always belongs to the resolved scope.  An
  -- organisation-scoped request can never omit its organisation and fall back
  -- to the wider tenant limit that its own allocation narrows.
  effective_organization_id := coalesce(p_organization_id, context_organization_id);
  if (context ->> 'tenantId')::uuid is distinct from p_tenant_id
    or effective_organization_id is distinct from context_organization_id then
    raise exception using errcode = '42501', message = 'Capability policy scope is unavailable';
  end if;
  if effective_organization_id is not null and not exists (
    select 1 from vortex_identity.organizations organization
    where organization.tenant_id = p_tenant_id
      and organization.organization_id = effective_organization_id
      and organization.state = 'active'
  ) then
    raise exception using errcode = '42501', message = 'Capability policy scope is unavailable';
  end if;
  -- Tenant-scoped reads require tenant authority. Organisation-scoped
  -- entitlement reads also serve system actors, which have no person identity.
  if effective_organization_id is null then
    actor_identity_id := vortex_identity.tenant_request_actor_id();
    perform vortex_identity.require_current_tenant_capability(
      actor_identity_id, p_tenant_id,
      'platform.tenant.capability_limits.read', evaluated_at
    );
  elsif (context ->> 'callerKind') in ('human', 'federated')
    and vortex_context.is_non_nil_uuid(context ->> 'identityId')
    and exists (
      select 1
      from vortex_identity.tenant_administrator_assignments as assignment
      where assignment.tenant_id = p_tenant_id
        and assignment.identity_id = (context ->> 'identityId')::uuid
        and assignment.revoked_at is null
        and assignment.starts_at <= evaluated_at
        and (assignment.expires_at is null or assignment.expires_at > evaluated_at)
    ) then
    actor_identity_id := vortex_identity.tenant_request_actor_id();
    perform vortex_identity.require_current_tenant_capability(
      actor_identity_id, p_tenant_id,
      'platform.tenant.capability_limits.read', evaluated_at
    );
  end if;
  -- The effective limit is the lowest of the platform ceiling and every
  -- allocation beneath it; on a tie the narrower scope is reported. No
  -- allocation can raise a limit, and nothing applies without a live ceiling.
  select bound.*,
    max(bound.quantity_limit) filter (where bound.limit_source = 'platform_ceiling')
      over () as ceiling_limit
  into selected
  from vortex_access.capability_limit_bounds_internal(
    p_tenant_id, effective_organization_id, p_capability_key, p_unit, evaluated_at, false
  ) as bound
  order by bound.quantity_limit, bound.precedence
  limit 1;
  if not found then
    return query select 'refused'::text, p_tenant_id, effective_organization_id,
      p_capability_key, p_unit, null::text, null::text, null::uuid, null::bigint, null::uuid,
      null::bigint, null::numeric, null::numeric, evaluated_at, 'capability_not_assigned'::text;
    return;
  end if;
  return query select 'available'::text, p_tenant_id, effective_organization_id,
    p_capability_key, p_unit, selected.applied_scope, selected.limit_source,
    selected.policy_id, selected.policy_revision, selected.assignment_id,
    selected.assignment_revision, selected.quantity_limit, selected.ceiling_limit,
    evaluated_at, null::text;
end
$function$;


ALTER FUNCTION vortex_access.resolve_effective_capability_policy(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) OWNER TO postgres;

--
-- Name: FUNCTION resolve_effective_capability_policy(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.resolve_effective_capability_policy(p_tenant_id uuid, p_organization_id uuid, p_capability_key text, p_unit text) IS 'Returns the lowest of the live platform ceiling and the tenant and organisation allocations for the established request scope, the ceiling itself, and which limit applied; tenant administrators require the capability-limits read permission, and an allocation can only narrow the ceiling.';


--
-- Name: resolve_event_dispatcher_actor(); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

create or replace function vortex_access.resolve_event_dispatcher_actor()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  active_grant_count bigint;
  dispatcher_actor_id uuid;
begin
  -- The dispatcher claims occurrences of every organisation, so only a
  -- platform-wide grant (no organisation, flow or scope subject) authorises it.
  -- A grant confined to an organisation, flow or scope never does. One
  -- statement counts and reads under a single snapshot, so the actor returned
  -- is the only active grant that statement saw.
  select pg_catalog.count(*), (pg_catalog.array_agg(actor_grant.system_actor_id))[1]
    into active_grant_count, dispatcher_actor_id
  from vortex_access.system_actor_grants as actor_grant
  where actor_grant.operation_key = 'dispatch_event_occurrences'
    and actor_grant.state = 'active'
    and actor_grant.organization_id is null
    and actor_grant.flow_id is null
    and actor_grant.scope_key is null;

  if active_grant_count = 0 or dispatcher_actor_id is null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reason', 'dispatcher_grant_missing'
    );
  end if;
  if active_grant_count > 1 then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reason', 'dispatcher_grant_ambiguous'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'outcome', 'authorised', 'systemActorId', dispatcher_actor_id
  );
end
$function$;


ALTER FUNCTION vortex_access.resolve_event_dispatcher_actor() OWNER TO postgres;

--
-- Name: FUNCTION resolve_event_dispatcher_actor(); Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON FUNCTION vortex_access.resolve_event_dispatcher_actor() IS 'Resolves the event dispatcher''s system actor from the single active platform-wide system actor grant for the dispatch_event_occurrences operation; refuses when none or more than one exists. A grant confined to an organisation, flow or scope never authorises dispatch. Runtime-only; the actor is never taken from the caller.';


--
-- Name: resolve_human_application_change_scope(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_access; Owner: postgres
--

CREATE FUNCTION vortex_access.resolve_human_application_change_scope(p_identity_id uuid, p_organization_id uuid, p_application_root_id uuid) RETURNS TABLE(tenant_id uuid, organization_id uuid, organization_account_id uuid, application_root_id uuid, access_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  resolved_tenant_id uuid;
  resolved_organization_id uuid;
  resolved_organization_account_id uuid;
  resolved_access_version bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Application change selection is invalid';
  end if;

  select scope.tenant_id, scope.organization_id,
    scope.organization_account_id, scope.access_version
  into resolved_tenant_id, resolved_organization_id,
    resolved_organization_account_id, resolved_access_version
  from vortex_access.resolve_human_organization_change_scope(
    p_identity_id,
    p_organization_id
  ) as scope;

  if not exists (
    select 1
    from vortex_access.permission_registrations as registration
    where registration.organization_id = resolved_organization_id
      and registration.registration_kind = 'application'
      and registration.registration_owner_id = p_application_root_id
      and registration.state = 'active'
  ) then
    raise exception using errcode = '42501',
      message = 'Application change selection is unavailable';
  end if;

  return query select resolved_tenant_id, resolved_organization_id,
    resolved_organization_account_id, p_application_root_id,
    resolved_access_version;
end
$$;


