--
-- Name: append_application_grant_activity_internal(jsonb, uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: vortex_connection; Owner: postgres
--

create or replace function vortex_connection.append_application_grant_activity_internal(
  p_context jsonb,
  p_activity_id uuid,
  p_connection_instance_id uuid,
  p_application_root_id uuid,
  p_action text,
  p_occurred_at timestamptz
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  actor_kind text;
  actor_id uuid;
  subject_ids uuid[];
begin
  if p_context ->> 'callerKind' = 'human' then
    actor_kind := 'organization_account';
    actor_id := (p_context ->> 'organizationAccountId')::uuid;
  elsif p_context ->> 'callerKind' = 'system' then
    actor_kind := 'system';
    actor_id := (p_context ->> 'systemActorId')::uuid;
  else
    raise exception using
      errcode = '42501',
      message = 'Connection grant Activity requires validated human or system context';
  end if;

  select pg_catalog.array_agg(subject_id order by subject_id)
  into subject_ids
  from (
    select distinct candidate.subject_id
    from pg_catalog.unnest(array[p_connection_instance_id, p_application_root_id])
      as candidate(subject_id)
  ) as canonical_subjects;

  perform vortex_activity.append_organization_activity_entry(
    (p_context ->> 'organizationId')::uuid,
    p_activity_id,
    p_occurred_at,
    actor_kind,
    actor_id,
    p_action,
    subject_ids,
    array[]::uuid[],
    'connection',
    (p_context ->> 'correlationId')::uuid,
    'completed'
  );
end;
$function$;


ALTER FUNCTION vortex_connection.append_application_grant_activity_internal(p_context jsonb, p_activity_id uuid, p_connection_instance_id uuid, p_application_root_id uuid, p_action text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: append_connection_instance_activity_internal(jsonb, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: vortex_connection; Owner: postgres
--

create or replace function vortex_connection.append_connection_instance_activity_internal(
  p_context jsonb,
  p_activity_id uuid,
  p_connection_instance_id uuid,
  p_action text,
  p_occurred_at timestamptz
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  actor_kind text;
  actor_id uuid;
begin
  if p_context ->> 'callerKind' = 'human' then
    actor_kind := 'organization_account';
    actor_id := (p_context ->> 'organizationAccountId')::uuid;
  elsif p_context ->> 'callerKind' = 'system' then
    actor_kind := 'system';
    actor_id := (p_context ->> 'systemActorId')::uuid;
  else
    raise exception using
      errcode = '42501',
      message = 'Connection Activity requires validated human or system context';
  end if;

  perform vortex_activity.append_organization_activity_entry(
    (p_context ->> 'organizationId')::uuid,
    p_activity_id,
    p_occurred_at,
    actor_kind,
    actor_id,
    p_action,
    array[p_connection_instance_id],
    array[]::uuid[],
    'connection',
    (p_context ->> 'correlationId')::uuid,
    'completed'
  );
end
$function$;


ALTER FUNCTION vortex_connection.append_connection_instance_activity_internal(p_context jsonb, p_activity_id uuid, p_connection_instance_id uuid, p_action text, p_occurred_at timestamp with time zone) OWNER TO postgres;

--
-- Name: assert_connection_administration_authority(jsonb); Type: FUNCTION; Schema: vortex_connection; Owner: vortex_connection_owner
--

create or replace function vortex_connection.assert_connection_administration_authority(
  p_context jsonb
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  decision record;
  operation_value constant text := 'platform.organization.connections.manage';
begin
  select evaluated.* into strict decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', operation_value,
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', 'ec2908a1-f3cd-4c4a-8bf7-91bffbf4cb3d'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;

  if decision.outcome is distinct from 'eligible'
    or decision.operation_key is distinct from operation_value
    or decision.organization_id is distinct from (p_context ->> 'organizationId')::uuid
    or decision.organization_account_id is distinct from
      (p_context ->> 'organizationAccountId')::uuid
    or decision.access_version is distinct from (p_context ->> 'accessVersion')::bigint
    or decision.correlation_id is distinct from (p_context ->> 'correlationId')::uuid then
    raise exception using
      errcode = '42501',
      message = 'Connection administration is unavailable';
  end if;
exception
  when others then
    raise exception using
      errcode = '42501',
      message = 'Connection administration is unavailable';
end
$function$;


ALTER FUNCTION vortex_connection.assert_connection_administration_authority(p_context jsonb) OWNER TO vortex_connection_owner;

