--
-- Name: FUNCTION grant_connection_application_for_administration(p_connection_instance_id uuid, p_application_root_id uuid, p_administrator_activity_id uuid); Type: COMMENT; Schema: vortex_connection; Owner: vortex_connection_owner
--

COMMENT ON FUNCTION vortex_connection.grant_connection_application_for_administration(p_connection_instance_id uuid, p_application_root_id uuid, p_administrator_activity_id uuid) IS 'Human request entry point for granting an application use of a connection instance; delegates to grant_connection_application_internal.';


--
-- Name: grant_connection_application_internal(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_connection; Owner: postgres
--

create or replace function vortex_connection.grant_connection_application_internal(
  p_connection_instance_id uuid,
  p_application_root_id uuid,
  p_administrator_activity_id uuid
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  operation_at timestamptz := pg_catalog.statement_timestamp();
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  conn_row vortex_connection.connection_instances%rowtype;
  app_org_id uuid;
  app_kind text;
  administration_context jsonb;
  inserted_connection_instance_id uuid;
begin
  if p_administrator_activity_id is null or p_administrator_activity_id = nil_uuid then
    raise exception using
      errcode = '22023',
      message = 'Connection grant requires non-nil administrator activity ID';
  end if;

  -- Validate administration context before locking, then bind the lock to the
  -- context organisation so a foreign or missing identifier is indistinguishable.
  administration_context := vortex_connection.validated_administration_context(vortex_context.organization_id());

  select conn.* into conn_row
  from vortex_connection.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = (administration_context ->> 'organizationId')::uuid
  for share;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Connection instance not found';
  end if;

  -- Resolve and lock application root
  select root.organization_id, root.kind into app_org_id, app_kind
  from vortex_definition.roots as root
  where root.root_id = p_application_root_id
    and root.organization_id = (administration_context ->> 'organizationId')::uuid
  for share;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'Referenced application root is unavailable';
  end if;

  if app_kind <> 'application' then
    raise exception using
      errcode = '23514',
      message = 'Referenced root must be of kind application';
  end if;

  if app_org_id <> conn_row.organization_id then
    raise exception using
      errcode = '23514',
      message = 'Referenced application root organization does not match connection organization';
  end if;

  insert into vortex_connection.connection_application_grants (
    connection_instance_id,
    application_root_id,
    organization_id,
    granted_at
  ) values (
    p_connection_instance_id,
    p_application_root_id,
    conn_row.organization_id,
    operation_at
  )
  on conflict (connection_instance_id, application_root_id) do nothing
  returning connection_instance_id into inserted_connection_instance_id;

  if inserted_connection_instance_id is null then
    raise exception using
      errcode = '23514',
      message = 'Connection application grant already exists';
  end if;

  perform vortex_connection.append_application_grant_activity_internal(
    administration_context,
    p_administrator_activity_id,
    p_connection_instance_id,
    p_application_root_id,
    'connection_application_granted',
    operation_at
  );
end
$function$;


ALTER FUNCTION vortex_connection.grant_connection_application_internal(p_connection_instance_id uuid, p_application_root_id uuid, p_administrator_activity_id uuid) OWNER TO postgres;

--
-- Name: list_connection_instances_for_administration(uuid, uuid, integer); Type: FUNCTION; Schema: vortex_connection; Owner: postgres
--

create or replace function vortex_connection.list_connection_instances_for_administration(
  p_organization_id uuid,
  p_after_connection_instance_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  connection_instances jsonb,
  next_after_connection_instance_id uuid
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  administration_context jsonb;
  page_items jsonb;
  page_connection_instance_ids uuid[];
  candidate_count integer;
begin
  if p_organization_id is null or p_organization_id = nil_uuid
    or p_after_connection_instance_id = nil_uuid
    or p_page_size is null or p_page_size not between 1 and 100 then
    raise exception using
      errcode = '22023',
      message = 'Connection instance page input is invalid';
  end if;

  perform vortex_connection.assert_human_administration_request();
  administration_context :=
    vortex_connection.validated_administration_context(p_organization_id);

  with candidates as (
    select
      conn.connection_instance_id,
      conn.connection_type_id,
      conn.connection_type_version,
      conn.state,
      conn.last_health_outcome,
      conn.revision,
      conn.token_expires_at,
      coalesce(
        (
          select pg_catalog.array_agg(
            grant_entry.application_root_id order by grant_entry.application_root_id
          )
          from vortex_connection.connection_application_grants as grant_entry
          join vortex_definition.roots as app_root
            on app_root.root_id = grant_entry.application_root_id
            and app_root.organization_id = grant_entry.organization_id
            and app_root.kind = 'application'
          where grant_entry.connection_instance_id = conn.connection_instance_id
            and grant_entry.organization_id = conn.organization_id
        ),
        array[]::uuid[]
      ) as authorized_application_ids,
      pg_catalog.row_number() over (order by conn.connection_instance_id) as ordinal
    from vortex_connection.connection_instances as conn
    where conn.organization_id = (administration_context ->> 'organizationId')::uuid
      and (p_after_connection_instance_id is null
        or conn.connection_instance_id > p_after_connection_instance_id)
    order by conn.connection_instance_id
    limit p_page_size + 1
  )
  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(
          pg_catalog.jsonb_build_object(
            'connectionInstanceId', candidate.connection_instance_id,
            'connectionTypeId', candidate.connection_type_id,
            'connectionTypeVersion', candidate.connection_type_version,
            'state', candidate.state,
            'lastHealthOutcome', candidate.last_health_outcome,
            'revision', candidate.revision,
            'tokenExpiresAt', case
              when candidate.token_expires_at is null
                or not pg_catalog.isfinite(candidate.token_expires_at)
              then null
              else pg_catalog.to_jsonb(candidate.token_expires_at)
            end,
            'authorizedApplicationIds',
              pg_catalog.to_jsonb(candidate.authorized_application_ids),
            'grantedScopes', '[]'::jsonb
          )
        ) order by candidate.connection_instance_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.connection_instance_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into page_items, page_connection_instance_ids, candidate_count
  from candidates as candidate;

  return query
  select
    (administration_context ->> 'organizationId')::uuid,
    page_items,
    case when candidate_count > p_page_size
      then page_connection_instance_ids[p_page_size] else null end;
end
$function$;


ALTER FUNCTION vortex_connection.list_connection_instances_for_administration(p_organization_id uuid, p_after_connection_instance_id uuid, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION list_connection_instances_for_administration(p_organization_id uuid, p_after_connection_instance_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_connection; Owner: postgres
--

COMMENT ON FUNCTION vortex_connection.list_connection_instances_for_administration(p_organization_id uuid, p_after_connection_instance_id uuid, p_page_size integer) IS 'Reads one bounded page of connection instance safe statuses for the administration page in the request context organisation. Returns state, health, expiry, authority revision and both scope lists per instance; never a secret, a secret reference, an organisation identity or another organisation instance.';


--
-- Name: read_active_connection_evidence(uuid); Type: FUNCTION; Schema: vortex_connection; Owner: postgres
--

create or replace function vortex_connection.read_active_connection_evidence(
  p_connection_instance_id uuid
)
returns table (
  connection_instance_id uuid,
  destination_key text,
  destination_fingerprint text,
  organization_id uuid,
  authorized_application_ids uuid[],
  state text,
  revision bigint,
  last_health_outcome text
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_org_id uuid;
  conn_row vortex_connection.connection_instances%rowtype;
  locked_authorized_application_ids uuid[];
begin
  context_org_id := vortex_context.organization_id();

  select conn.* into conn_row
  from vortex_connection.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = context_org_id
    and conn.state = 'active'
    and conn.last_health_outcome = 'healthy'
    and (conn.token_expires_at is null
      or (pg_catalog.isfinite(conn.token_expires_at)
        and conn.token_expires_at > pg_catalog.statement_timestamp()))
  for share;

  if not found then
    return;
  end if;

  select pg_catalog.array_agg(
    locked_grant.application_root_id order by locked_grant.application_root_id
  )
  into locked_authorized_application_ids
  from (
    select grant_entry.application_root_id
    from vortex_connection.connection_application_grants as grant_entry
    join vortex_definition.roots as app_root
      on app_root.root_id = grant_entry.application_root_id
      and app_root.organization_id = grant_entry.organization_id
      and app_root.kind = 'application'
    where grant_entry.connection_instance_id = conn_row.connection_instance_id
      and grant_entry.organization_id = conn_row.organization_id
    for share of grant_entry, app_root
  ) as locked_grant;

  if locked_authorized_application_ids is null then
    return;
  end if;

  return query
  select
    conn_row.connection_instance_id,
    conn_row.destination_key,
    conn_row.destination_fingerprint,
    conn_row.organization_id,
    locked_authorized_application_ids,
    conn_row.state,
    conn_row.revision,
    conn_row.last_health_outcome;
end
$function$;


ALTER FUNCTION vortex_connection.read_active_connection_evidence(p_connection_instance_id uuid) OWNER TO postgres;

