--
-- Name: create_root(text, text, jsonb, text, jsonb, text); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

create or replace function vortex_definition.create_root(
  p_kind text,
  p_key text,
  p_draft_source jsonb,
  p_source_fingerprint text,
  p_identity_requirements jsonb,
  p_application_origin_kind text
)
returns table (
  root_id uuid,
  organization_id uuid,
  kind text,
  definition_key text,
  draft_revision bigint,
  published_revision bigint,
  authored_source jsonb,
  source_contract_version text,
  source_fingerprint text,
  created_at timestamptz,
  created_by uuid,
  updated_at timestamptz,
  updated_by uuid
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  new_root_id uuid;
  operation_at timestamptz := pg_catalog.statement_timestamp();
  actor_id uuid;
  human_write boolean;
begin
  human_write := vortex_context.current_context() ->> 'callerKind' = 'human';
  if human_write then
    checked_context := vortex_definition.validated_builder_draft_write_context_internal(null);
    if p_kind is distinct from 'application'
      or p_application_origin_kind is distinct from 'ordinary'
      or p_draft_source ->> 'kind' is distinct from p_kind
      or p_draft_source ->> 'key' is distinct from p_key then
      raise exception using errcode = '22023',
        message = 'Definition draft write source is invalid';
    end if;
    actor_id := (checked_context ->> 'organizationAccountId')::uuid;
  else
    checked_context := vortex_definition.validated_system_context();
    actor_id := (checked_context ->> 'systemActorId')::uuid;
  end if;

  if p_draft_source ->> 'kind' is distinct from p_kind
    or p_draft_source ->> 'key' is distinct from p_key
    or p_kind is null
    or p_kind not in ('application', 'module')
    or (p_kind = 'application' and (
      p_application_origin_kind is null
      or p_application_origin_kind not in ('ordinary', 'platform_system_application')
    ))
    or (p_kind = 'module' and p_application_origin_kind is not null) then
    raise exception using errcode = '22023',
      message = 'Definition root source or provenance is invalid';
  end if;

  loop
    new_root_id := pg_catalog.gen_random_uuid();
    exit when new_root_id <> '00000000-0000-0000-0000-000000000000'::uuid;
  end loop;

  insert into vortex_definition.roots (
    root_id, organization_id, kind, key, created_at, created_by, application_origin_kind
  ) values (
    new_root_id,
    (checked_context ->> 'organizationId')::uuid,
    p_kind,
    p_key,
    operation_at,
    actor_id,
    p_application_origin_kind
  );

  perform vortex_definition.record_source_identities(
    new_root_id, p_identity_requirements, actor_id, operation_at
  );

  insert into vortex_definition.drafts (
    root_id, draft_revision, draft_source, source_contract_version,
    identity_requirements, source_fingerprint, updated_at, updated_by
  ) values (
    new_root_id,
    1,
    p_draft_source,
    p_draft_source ->> 'source_contract_version',
    p_identity_requirements,
    p_source_fingerprint,
    operation_at,
    actor_id
  );

  if human_write then
    perform vortex_definition.validated_builder_draft_write_context_internal(new_root_id);
  end if;

  return query
  select
    root.root_id,
    root.organization_id,
    root.kind,
    root.key,
    draft.draft_revision,
    root.current_release_revision,
    draft.draft_source,
    draft.source_contract_version,
    draft.source_fingerprint,
    root.created_at,
    root.created_by,
    draft.updated_at,
    draft.updated_by
  from vortex_definition.roots as root
  join vortex_definition.drafts as draft on draft.root_id = root.root_id
  where root.root_id = new_root_id;
end
$function$;


ALTER FUNCTION vortex_definition.create_root(p_kind text, p_key text, p_draft_source jsonb, p_source_fingerprint text, p_identity_requirements jsonb, p_application_origin_kind text) OWNER TO postgres;

--
-- Name: FUNCTION create_root(p_kind text, p_key text, p_draft_source jsonb, p_source_fingerprint text, p_identity_requirements jsonb, p_application_origin_kind text); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.create_root(p_kind text, p_key text, p_draft_source jsonb, p_source_fingerprint text, p_identity_requirements jsonb, p_application_origin_kind text) IS 'Creates a Definition root with explicit Application provenance, permanent component identities and initial draft atomically; Modules remain unclassified.';


--
-- Name: flow_target_dependency_reference(jsonb); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

CREATE FUNCTION vortex_definition.flow_target_dependency_reference(p_dependency jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_dependency ->> 'kind'
    when 'platform_flow' then p_dependency ->> 'flowId'
    when 'application_flow' then
      (p_dependency ->> 'applicationRootId') || ':' || (p_dependency ->> 'flowId')
    when 'application_flow_node' then
      (p_dependency ->> 'applicationRootId') || ':' || (p_dependency ->> 'flowId')
        || ':' || (p_dependency ->> 'nodeId')
    when 'application_query' then
      (p_dependency ->> 'applicationRootId') || ':' || (p_dependency ->> 'queryId')
    when 'module_query' then
      (p_dependency ->> 'moduleRootId') || ':' || (p_dependency ->> 'queryId')
    when 'application_form' then
      (p_dependency ->> 'applicationRootId') || ':' || (p_dependency ->> 'formId')
    when 'application_workflow' then
      (p_dependency ->> 'applicationRootId') || ':' || (p_dependency ->> 'workflowId')
    when 'application_action' then
      (p_dependency ->> 'applicationRootId') || ':' || (p_dependency ->> 'actionId')
    when 'protected_operation' then
      (p_dependency #>> '{operation,owner,kind}') || ':'
        || case p_dependency #>> '{operation,owner,kind}'
          when 'application' then p_dependency #>> '{operation,owner,applicationRootId}'
          when 'module' then p_dependency #>> '{operation,owner,moduleRootId}'
          when 'platform_service' then p_dependency #>> '{operation,owner,serviceId}'
        end
        || ':' || (p_dependency #>> '{operation,operationId}')
    else null
  end
$$;


ALTER FUNCTION vortex_definition.flow_target_dependency_reference(p_dependency jsonb) OWNER TO postgres;

--
-- Name: FUNCTION flow_target_dependency_reference(p_dependency jsonb); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.flow_target_dependency_reference(p_dependency jsonb) IS 'Owner-private canonical subject reference of one flow-target dependency manifest entry.';


--
-- Name: list_release_history(text, uuid, integer, bigint); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

create or replace function vortex_definition.list_release_history(
  p_kind text,
  p_root_id uuid,
  p_page_size integer,
  p_before_release_revision bigint default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  history_result jsonb;
begin
  checked_context := vortex_definition.validated_system_context();

  if p_kind is null
    or p_kind not in ('module', 'application')
    or p_root_id is null
    or p_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_page_size is null
    or p_page_size not between 1 and 100
    or (
      p_before_release_revision is not null
      and p_before_release_revision not between 1 and 9007199254740991
    ) then
    raise exception using
      errcode = '22023',
      message = 'Definition release history has an invalid selector';
  end if;

  select pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'organizationId', root.organization_id,
    'kind', root.kind,
    'definitionKey', root.key,
    'rootId', root.root_id,
    'currentReleaseRevision', root.current_release_revision,
    'entries', page.entries,
    'nextBeforeReleaseRevision', page.next_before_release_revision
  ))
  into history_result
  from vortex_definition.roots as root
  cross join lateral (
    select
      coalesce(
        pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'releaseRevision', candidate.release_revision,
            'releaseVersion', candidate.release_version,
            'sourceFingerprint', candidate.authored_source_fingerprint,
            'contentFingerprint', candidate.content_fingerprint,
            'releaseNote', candidate.release_note,
            'publishedAt', candidate.published_at,
            'publishedBy', candidate.published_by,
            'isCurrent', candidate.release_revision = root.current_release_revision
          ) order by candidate.release_revision desc
        ) filter (where candidate.ordinal <= p_page_size),
        '[]'::jsonb
      ) as entries,
      case
        when pg_catalog.count(*) > p_page_size then
          pg_catalog.min(candidate.release_revision)
            filter (where candidate.ordinal <= p_page_size)
        else null
      end as next_before_release_revision
    from (
      select
        release.*,
        pg_catalog.row_number() over (order by release.release_revision desc) as ordinal
      from vortex_definition.releases as release
      where release.root_id = root.root_id
        and (
          p_before_release_revision is null
          or release.release_revision < p_before_release_revision
        )
      order by release.release_revision desc
      limit p_page_size + 1
    ) as candidate
  ) as page
  where root.root_id = p_root_id
    and root.kind = p_kind
    and root.organization_id = (checked_context ->> 'organizationId')::uuid;

  return history_result;
end
$function$;


ALTER FUNCTION vortex_definition.list_release_history(p_kind text, p_root_id uuid, p_page_size integer, p_before_release_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION list_release_history(p_kind text, p_root_id uuid, p_page_size integer, p_before_release_revision bigint); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.list_release_history(p_kind text, p_root_id uuid, p_page_size integer, p_before_release_revision bigint) IS 'Returns one bounded newest-first metadata page from a same-organization Definition release history.';


--
-- Name: lock_application_page_adoption_draft_internal(uuid, bigint, bigint); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

create or replace function vortex_definition.lock_application_page_adoption_draft_internal(
  p_root_id uuid,
  p_expected_draft_revision bigint,
  p_expected_release_revision bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  root_row vortex_definition.roots%rowtype;
  locked_draft_revision bigint;
  result_value jsonb;
begin
  if p_root_id is null or p_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_draft_revision is null
    or p_expected_draft_revision not between 1 and 9007199254740991
    or p_expected_release_revision is null
    or p_expected_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023', message = 'Page adoption draft selector is invalid';
  end if;
  -- This existing guard locks Access before the classified Application root.
  checked_context := vortex_definition.validated_builder_draft_write_context_internal(p_root_id);
  select root.* into strict root_row
  from vortex_definition.roots as root
  where root.root_id = p_root_id
    and root.organization_id = (checked_context ->> 'organizationId')::uuid
    and root.kind = 'application';
  if root_row.application_origin_kind is distinct from 'ordinary' then
    raise exception using errcode = '42501', message = 'Page adoption source is unavailable';
  end if;
  if root_row.current_release_revision is distinct from p_expected_release_revision then
    raise exception using errcode = '40001', message = 'Page adoption publication changed';
  end if;
  select draft.draft_revision into locked_draft_revision
  from vortex_definition.drafts as draft
  where draft.root_id = p_root_id for update;
  if not found or locked_draft_revision is distinct from p_expected_draft_revision then
    raise exception using errcode = '40001', message = 'Page adoption draft changed';
  end if;
  perform vortex_definition.validated_builder_draft_write_context_internal(p_root_id);
  result_value := vortex_definition.read_publication_state(p_root_id);
  if result_value is null then
    raise exception using errcode = '55000', message = 'Page adoption draft is unavailable';
  end if;
  return result_value;
end
$function$;


ALTER FUNCTION vortex_definition.lock_application_page_adoption_draft_internal(p_root_id uuid, p_expected_draft_revision bigint, p_expected_release_revision bigint) OWNER TO postgres;

