-- Name: FUNCTION lock_application_page_adoption_draft_internal(p_root_id uuid, p_expected_draft_revision bigint, p_expected_release_revision bigint); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.lock_application_page_adoption_draft_internal(p_root_id uuid, p_expected_draft_revision bigint, p_expected_release_revision bigint) IS 'Locks an ordinary Application draft for current HUMAN page adoption derivation in Access, root and draft order; returns only its existing protected publication state and writes no source or release.';


--
-- Name: project_consumer_release_evidence(text, uuid, bigint); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

create or replace function vortex_definition.project_consumer_release_evidence(
  p_kind text,
  p_root_id uuid,
  p_release_revision bigint
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $function$
  select pg_catalog.jsonb_build_object(
    'organizationId', root.organization_id,
    'kind', root.kind,
    'key', root.key,
    'rootId', release.root_id,
    'releaseRevision', release.release_revision,
    'releaseVersion', release.release_version,
    'sourceContractVersion', release.source_contract_version,
    'validationContractVersion', release.validation_contract_version,
    'contentFingerprint', release.content_fingerprint,
    'resolutionFingerprint', release.resolution_fingerprint,
    'compilationOutput', release.compilation_output,
    'resolutionSnapshot', release.resolution_snapshot,
    'dependencyManifest', coalesce((
      select pg_catalog.jsonb_agg(
        case dependency.dependency_kind
          when 'module' then pg_catalog.jsonb_build_object(
            'kind', 'module',
            'key', dependency.dependency_reference,
            'rootId', dependency.target_root_id,
            'releaseRevision', dependency.target_release_revision,
            'releaseVersion', dependency.dependency_version,
            'contentFingerprint', dependency.dependency_content_fingerprint,
            'resolutionFingerprint', dependency.evidence_fingerprint
          )
          when 'connection_type' then pg_catalog.jsonb_build_object(
            'kind', 'connection_type',
            'key', dependency.dependency_reference,
            'rootId', dependency.catalogue_item_id,
            'releaseVersion', dependency.dependency_version,
            'contentFingerprint', dependency.dependency_content_fingerprint,
            'catalogueFingerprint', dependency.evidence_fingerprint
          )
          when 'platform_block' then pg_catalog.jsonb_build_object(
            'kind', 'platform_block',
            'blockId', dependency.catalogue_item_id,
            'releaseVersion', dependency.dependency_version,
            'contentFingerprint', dependency.dependency_content_fingerprint,
            'catalogueFingerprint', dependency.evidence_fingerprint
          )
          when 'platform_theme' then pg_catalog.jsonb_build_object(
            'kind', 'platform_theme',
            'catalogueThemeId', dependency.dependency_reference,
            'releaseVersion', dependency.dependency_version,
            'contentFingerprint', dependency.dependency_content_fingerprint,
            'catalogueFingerprint', dependency.evidence_fingerprint
          )
          else dependency.dependency_entry
        end
        order by dependency.dependency_kind collate "C",
          dependency.dependency_reference collate "C",
          dependency.dependency_version collate "C"
      )
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = release.root_id
        and dependency.release_revision = release.release_revision
    ), '[]'::jsonb),
    'moduleDependencyTargets', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'rootId', target.root_id,
          'releaseRevision', target.release_revision,
          'releaseVersion', target.release_version,
          'contentFingerprint', target.content_fingerprint,
          'resolutionFingerprint', target.resolution_fingerprint
        ) order by dependency.dependency_reference collate "C",
          target.root_id, target.release_revision
      )
      from vortex_definition.release_dependencies as dependency
      join vortex_definition.releases as target
        on target.root_id = dependency.target_root_id
        and target.release_revision = dependency.target_release_revision
      where dependency.root_id = release.root_id
        and dependency.release_revision = release.release_revision
        and dependency.dependency_kind = 'module'
    ), '[]'::jsonb)
  )
  from vortex_definition.roots as root
  join vortex_definition.releases as release
    on release.root_id = root.root_id
    and release.release_revision = p_release_revision
  where root.root_id = p_root_id
    and root.kind = p_kind
$function$;


ALTER FUNCTION vortex_definition.project_consumer_release_evidence(p_kind text, p_root_id uuid, p_release_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION project_consumer_release_evidence(p_kind text, p_root_id uuid, p_release_revision bigint); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.project_consumer_release_evidence(p_kind text, p_root_id uuid, p_release_revision bigint) IS 'Owner-private projection of one exact immutable release; performs no scope selection.';


--
-- Name: protect_root_identity(); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

CREATE FUNCTION vortex_definition.protect_root_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.root_id is distinct from old.root_id
    or new.organization_id is distinct from old.organization_id
    or new.kind is distinct from old.kind
    or new.key is distinct from old.key
    or new.created_at is distinct from old.created_at
    or new.created_by is distinct from old.created_by then
    raise exception using
      errcode = '23514',
      message = 'Definition root identity, ownership, kind, key and creation evidence are permanent';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_definition.protect_root_identity() OWNER TO postgres;

--
-- Name: reachable_module_dependency_edges(uuid, bigint); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

CREATE FUNCTION vortex_definition.reachable_module_dependency_edges(p_root_id uuid, p_release_revision bigint) RETURNS TABLE(target_root_id uuid, target_release_revision bigint, dependency_reference text, dependency_version text, dependency_content_fingerprint text, evidence_fingerprint text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  pin record;
begin
  -- UNION collapses edges that reach one target with identical evidence, so a
  -- root has one tuple exactly when every edge pins it at one revision with
  -- the same evidence. The release being resolved already pins its own root,
  -- so reaching that root again would pin it twice; this is also how a
  -- root-level cycle is refused.
  for pin in
    with recursive module_edges as (
      select dependency.target_root_id, dependency.target_release_revision,
        dependency.dependency_reference, dependency.dependency_version,
        dependency.dependency_content_fingerprint, dependency.evidence_fingerprint
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = p_root_id
        and dependency.release_revision = p_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision,
        dependency.dependency_reference, dependency.dependency_version,
        dependency.dependency_content_fingerprint, dependency.evidence_fingerprint
      from module_edges as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select edge.target_root_id, edge.target_release_revision,
      edge.dependency_reference, edge.dependency_version,
      edge.dependency_content_fingerprint, edge.evidence_fingerprint,
      pg_catalog.count(*) over (partition by edge.target_root_id) as root_pin_count,
      root.kind is distinct from 'module'
        or root.key is distinct from edge.dependency_reference
        or release.release_version is distinct from edge.dependency_version
        or release.content_fingerprint is distinct from edge.dependency_content_fingerprint
        or release.resolution_fingerprint is distinct from edge.evidence_fingerprint
        as disagrees_with_target
    from module_edges as edge
    left join vortex_definition.roots as root on root.root_id = edge.target_root_id
    left join vortex_definition.releases as release
      on release.root_id = edge.target_root_id
      and release.release_revision = edge.target_release_revision
  loop
    if pin.root_pin_count <> 1
      or pin.disagrees_with_target
      or pin.target_root_id = p_root_id then
      raise exception using errcode = '23514', message = 'Exact bound Module dependency evidence is inconsistent';
    end if;
    target_root_id := pin.target_root_id;
    target_release_revision := pin.target_release_revision;
    dependency_reference := pin.dependency_reference;
    dependency_version := pin.dependency_version;
    dependency_content_fingerprint := pin.dependency_content_fingerprint;
    evidence_fingerprint := pin.evidence_fingerprint;
    return next;
  end loop;
end
$$;


ALTER FUNCTION vortex_definition.reachable_module_dependency_edges(p_root_id uuid, p_release_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION reachable_module_dependency_edges(p_root_id uuid, p_release_revision bigint); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.reachable_module_dependency_edges(p_root_id uuid, p_release_revision bigint) IS 'Owner-private Module dependency pin set of one exact release: one row per Module root; raises 23514 when a root is pinned at more than one revision or an edge disagrees with its target release.';


--
-- Name: read_application_bound_release_set(bigint); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

create or replace function vortex_definition.read_application_bound_release_set(
  p_application_release_revision bigint
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  application_root_id uuid;
  application_evidence jsonb;
  module_evidence jsonb;
begin
  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId'
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023', message = 'Application release-set context is invalid';
  end if;
  application_root_id := (checked_context ->> 'applicationRootId')::uuid;

  select vortex_definition.project_consumer_release_evidence(
    'application', root.root_id, p_application_release_revision
  ) into application_evidence
  from vortex_definition.roots as root
  where root.root_id = application_root_id
    and root.kind = 'application'
    and root.organization_id = (checked_context ->> 'organizationId')::uuid;
  if application_evidence is null then
    raise exception using errcode = 'P0002', message = 'Exact bound Application release is unavailable';
  end if;

  select pg_catalog.jsonb_agg(
    vortex_definition.project_consumer_release_evidence(
      'module', pin.target_root_id, pin.target_release_revision
    ) order by pin.target_root_id
  ) into module_evidence
  from vortex_definition.reachable_module_dependency_edges(
    application_root_id, p_application_release_revision
  ) as pin;

  if module_evidence is null then
    raise exception using errcode = '23514', message = 'Application has no exact Module dependency set';
  end if;

  return pg_catalog.jsonb_build_object(
    'correlationId', checked_context ->> 'correlationId',
    'application', application_evidence,
    'modules', module_evidence
  );
end
$function$;


ALTER FUNCTION vortex_definition.read_application_bound_release_set(p_application_release_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION read_application_bound_release_set(p_application_release_revision bigint); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.read_application_bound_release_set(p_application_release_revision bigint) IS 'Returns the exact local Application and complete exact Module dependency closure selected by validated human application context.';


--
-- Name: read_application_release_adoption_release_set(uuid, bigint); Type: FUNCTION; Schema: vortex_definition; Owner: vortex_definition_owner
--

create or replace function vortex_definition.read_application_release_adoption_release_set(
  p_application_root_id uuid,
  p_application_release_revision bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  permission_decision record;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Application release adoption release-set command is invalid';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId'
    or (checked_context ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    raise exception using errcode = '42501',
      message = 'Application release adoption release-set context is unavailable';
  end if;

  -- The exact release evidence is only revealed to a caller who may manage this
  -- organisation's application installations, decided by the same Access
  -- evaluator every other platform-permission check uses.
  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.manage',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible'
    or (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '42501',
      message = 'Application release adoption release-set authority is unavailable';
  end if;

  -- The same protected projection the ordinary human bound-release read returns;
  -- this caller has already proved installation-management authority above.
  return vortex_definition.read_application_bound_release_set(p_application_release_revision);
end
$function$;


ALTER FUNCTION vortex_definition.read_application_release_adoption_release_set(p_application_root_id uuid, p_application_release_revision bigint) OWNER TO vortex_definition_owner;

