-- Name: FUNCTION read_builder_application_root_classification(p_root_id uuid); Type: COMMENT; Schema: vortex_definition; Owner: postgres
--

COMMENT ON FUNCTION vortex_definition.read_builder_application_root_classification(p_root_id uuid) IS 'Returns only the persisted classification for the exact Application root in the validated current request organisation; missing, foreign, wrong-kind and unknown roots share one unavailable result.';


--
-- Name: read_builder_application_root_key(uuid); Type: FUNCTION; Schema: vortex_definition; Owner: postgres
--

create or replace function vortex_definition.read_builder_application_root_key(
  p_root_id uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  application_key text;
begin
  checked_context := vortex_definition.validated_builder_evidence_read_context_internal();
  if p_root_id is null or p_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Definition builder root key requires a non-nil root identifier';
  end if;

  select root.key into application_key
  from vortex_definition.roots as root
  where root.root_id = p_root_id
    and root.organization_id = (checked_context ->> 'organizationId')::uuid
    and root.kind = 'application';

  if not found then
    return null;
  end if;
  return application_key;
end
$function$;


