ALTER FUNCTION vortex_event.append_record_occurrences(p_storage_contract_id uuid, p_record_id uuid, p_occurrences jsonb) OWNER TO vortex_event_owner;

--
-- Name: FUNCTION append_record_occurrences(p_storage_contract_id uuid, p_record_id uuid, p_occurrences jsonb); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.append_record_occurrences(p_storage_contract_id uuid, p_record_id uuid, p_occurrences jsonb) IS 'Appends an exact validated record occurrence batch and minimal logged queue messages in the caller transaction.';


--
-- Name: append_record_occurrences_for_resolved_installation_internal(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_event; Owner: postgres
--

create or replace function vortex_event.append_record_occurrences_for_resolved_installation_internal(
  p_storage_contract_id uuid,
  p_record_id uuid,
  p_occurrences jsonb,
  p_installation jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  maximum_safe_revision constant bigint := 9007199254740991;
  context_value jsonb;
  installation jsonb;
  context_organization_id uuid;
  context_application_root_id uuid;
  context_actor_id uuid;
  context_correlation_id uuid;
  application_release_revision bigint;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  binding_value jsonb;
  binding_count integer;
  binding_module_root_id uuid;
  binding_module_release_revision bigint;
  binding_revision bigint;
  module_release vortex_definition.releases%rowtype;
  application_release vortex_definition.releases%rowtype;
  module_content jsonb;
  application_content jsonb;
  record_type jsonb;
  record_type_count integer;
  locked_definition_revision bigint;
  locked_record_count integer;
  sequence_application_scope_id uuid;
  next_sequence bigint;
  occurrence_time timestamptz := pg_catalog.statement_timestamp();
  occurrence_time_text text;
  occurrence_item jsonb;
  occurrence_id uuid;
  descriptor jsonb;
  payload jsonb;
  event_kind text;
  owner_kind text;
  owner_root_id uuid;
  declared_event jsonb;
  declared_event_count integer;
  definition_release jsonb;
  field_item jsonb;
  field_id_text text;
  previous_field_id_text text;
  field_definition jsonb;
  queued_message_id bigint;
  envelope jsonb;
  envelopes jsonb := '[]'::jsonb;
begin
  if p_storage_contract_id is null or p_storage_contract_id = nil_uuid
    or p_record_id is null or p_record_id = nil_uuid
    or pg_catalog.jsonb_typeof(p_occurrences) is distinct from 'array' then
    raise exception using errcode = '22023', message = 'Event append input is invalid';
  end if;

  if pg_catalog.jsonb_array_length(p_occurrences) = 0 then
    return envelopes;
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_occurrences) as candidate(value)
    where pg_catalog.jsonb_typeof(candidate.value) is distinct from 'object'
      or not candidate.value ?& array['occurrenceId', 'descriptor', 'payload']
      or candidate.value - array['occurrenceId', 'descriptor', 'payload'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(candidate.value -> 'occurrenceId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(candidate.value -> 'descriptor') is distinct from 'object'
      or pg_catalog.jsonb_typeof(candidate.value -> 'payload') is distinct from 'object'
  ) then
    raise exception using errcode = '22023', message = 'Event occurrence batch is invalid';
  end if;

  begin
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_occurrences) as candidate(value)
      where (candidate.value ->> 'occurrenceId')::uuid = nil_uuid
    ) or (
      select pg_catalog.count(*)
      from pg_catalog.jsonb_array_elements(p_occurrences)
    ) <> (
      select pg_catalog.count(distinct (candidate.value ->> 'occurrenceId')::uuid)
      from pg_catalog.jsonb_array_elements(p_occurrences) as candidate(value)
    ) then
      raise exception using errcode = '22023', message = 'Event occurrence identities are invalid';
    end if;
  exception when invalid_text_representation then
    raise exception using errcode = '22023', message = 'Event occurrence identities are invalid';
  end;

  context_value := vortex_access.validated_human_request_context();
  if context_value ->> 'callerKind' is distinct from 'human'
    or not context_value ?& array[
      'organizationId', 'applicationRootId', 'organizationAccountId', 'correlationId'
    ] then
    raise exception using errcode = '42501', message = 'Human Application context is required';
  end if;
  context_actor_id := (context_value ->> 'organizationAccountId')::uuid;
  context_organization_id := (context_value ->> 'organizationId')::uuid;
  context_application_root_id := (context_value ->> 'applicationRootId')::uuid;
  context_correlation_id := (context_value ->> 'correlationId')::uuid;
  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = p_storage_contract_id;
  if not found
    or catalogue_row.state is distinct from 'active'
    or catalogue_row.physical_schema_token is null
    or catalogue_row.physical_schema_token not in ('record_data', 'system_projection')
    or (catalogue_row.physical_schema_token = 'system_projection'
      and catalogue_row.protected_read_model_key
        is distinct from 'organization_runtime_settings') then
    raise exception using errcode = 'P0002', message = 'Event record is unavailable';
  end if;

  -- Coordinate with the approved installation lifecycle writer before trusting
  -- the exact Module binding. The actual generated row is locked below and is
  -- the ordering lock shared by every consuming Application.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    pg_catalog.hashtextextended(
      'vortex_module.binding:' || context_organization_id::text || ':' ||
        context_application_root_id::text || ':' || catalogue_row.module_root_id::text,
      0
    )
  );
  -- Installation evidence is resolved here, inside the protected region, and
  -- never before it.  A lifecycle detach that commits while this append waits
  -- for the canonical binding lock above is only observed by a read taken
  -- after that wait: this assignment is its own statement, so in read
  -- committed it sees the committed lifecycle state.  `p_installation` carries
  -- an exact pin-set only from a trusted reader that already resolved it while
  -- holding the same canonical lifecycle lock.
  if p_installation is null then
    installation := vortex_module.read_current_active_installation();
  else
    installation := p_installation;
  end if;
  if installation is null
    or pg_catalog.jsonb_typeof(installation) <> 'object'
    or not installation ?& array[
      'organizationId', 'applicationRootId', 'applicationReleaseRevision',
      'moduleBindings'
    ]
    or (installation ->> 'organizationId')::uuid is distinct from context_organization_id
    or (installation ->> 'applicationRootId')::uuid is distinct from context_application_root_id
    or pg_catalog.jsonb_typeof(installation -> 'moduleBindings') <> 'array' then
    raise exception using errcode = '42501', message = 'Resolved Event installation is unavailable';
  end if;
  application_release_revision :=
    (installation ->> 'applicationReleaseRevision')::bigint;
  -- Module's existing reader has already proved the complete binding set
  -- against the published dependency closure. Read the one exact binding from
  -- that result while its canonical lifecycle lock is held; do not add a
  -- second binding reader or broader cross-owner table grants.
  select pg_catalog.count(*), pg_catalog.jsonb_agg(item.value) -> 0
  into binding_count, binding_value
  from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as item(value)
  where (item.value ->> 'moduleRootId')::uuid = catalogue_row.module_root_id;
  if binding_count <> 1 then
    raise exception using errcode = '55000', message = 'Installed Event binding is unavailable';
  end if;
  binding_module_root_id := (binding_value ->> 'moduleRootId')::uuid;
  binding_module_release_revision :=
    (binding_value ->> 'moduleReleaseRevision')::bigint;
  binding_revision := (binding_value ->> 'bindingRevision')::bigint;

  select release.* into module_release
  from vortex_definition.releases as release
  where release.root_id = binding_module_root_id
    and release.release_revision = binding_module_release_revision;
  if not found
    or not exists (
      select 1 from vortex_record.release_provisions as provision
      where provision.module_root_id = module_release.root_id
        and provision.release_revision = module_release.release_revision
        and p_storage_contract_id = any (provision.storage_contract_ids)
    ) then
    raise exception using errcode = '55000', message = 'Installed Event storage is unavailable';
  end if;
  module_content := module_release.compilation_output #> '{canonical,content}';

  select pg_catalog.count(*), pg_catalog.jsonb_agg(item.value) -> 0
  into record_type_count, record_type
  from pg_catalog.jsonb_array_elements(module_content -> 'recordTypes') as item(value)
  where (item.value ->> 'recordTypeId')::uuid = catalogue_row.record_type_id;
  if record_type_count <> 1
    or (record_type ->> 'storageContractId')::uuid is distinct from p_storage_contract_id
    or record_type ->> 'storageScope' is distinct from catalogue_row.storage_scope then
    raise exception using errcode = '55000', message = 'Installed Event record type is unavailable';
  end if;

  select release.* into application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = context_application_root_id
    and release.release_revision = application_release_revision
    and root.organization_id = context_organization_id
    and root.kind = 'application';
  if not found then
    raise exception using errcode = '55000', message = 'Installed Application release is unavailable';
  end if;
  application_content := application_release.compilation_output #> '{canonical,content}';

  if catalogue_row.storage_scope = 'organization_shared' then
    sequence_application_scope_id := null;
  else
    sequence_application_scope_id := context_application_root_id;
  end if;
  if catalogue_row.physical_schema_token = 'system_projection' then
    locked_definition_revision := null;
    locked_record_count := case when
      vortex_access.lock_organization_runtime_settings_record_for_event_internal(p_record_id)
      then 1 else 0 end;
    if locked_record_count = 1 then
      locked_definition_revision := binding_module_release_revision;
    end if;
  elsif catalogue_row.storage_scope = 'organization_shared' then
    locked_definition_revision := null;
    execute pg_catalog.format(
      'select stored.definition_revision
       from record_data.%I as stored
       where stored.organisation_id = $1 and stored.record_id = $2
         and stored.application_root_id is null
       for update',
      catalogue_row.physical_table_token
    ) into locked_definition_revision
    using context_organization_id, p_record_id;
    get diagnostics locked_record_count = row_count;
  else
    locked_definition_revision := null;
    execute pg_catalog.format(
      'select stored.definition_revision
       from record_data.%I as stored
       where stored.organisation_id = $1 and stored.record_id = $2
         and stored.application_root_id = $3
       for update',
      catalogue_row.physical_table_token
    ) into locked_definition_revision
    using context_organization_id, p_record_id, context_application_root_id;
    get diagnostics locked_record_count = row_count;
  end if;
  if locked_record_count <> 1 or locked_definition_revision is null
    or locked_definition_revision < catalogue_row.first_compatible_release_revision
    or (catalogue_row.last_compatible_release_revision is not null
      and locked_definition_revision > catalogue_row.last_compatible_release_revision) then
    raise exception using errcode = 'P0002', message = 'Event record is unavailable';
  end if;

  select coalesce(pg_catalog.max(stored.record_sequence), 0) + 1
  into next_sequence
  from vortex_event.event_outbox as stored
  where stored.organization_id = context_organization_id
    and stored.storage_contract_id = p_storage_contract_id
    and stored.sequence_application_root_id is not distinct from
      sequence_application_scope_id
    and stored.record_id = p_record_id;
  if next_sequence + pg_catalog.jsonb_array_length(p_occurrences) - 1 >
      maximum_safe_revision then
    raise exception using errcode = '22003', message = 'Event record sequence is exhausted';
  end if;

  occurrence_time_text := vortex_context.format_timestamp_utc(occurrence_time);

  for occurrence_item in
    select item.value
    from pg_catalog.jsonb_array_elements(p_occurrences) with ordinality as item(value, ordinal)
    order by item.ordinal
  loop
    occurrence_id := (occurrence_item ->> 'occurrenceId')::uuid;
    descriptor := occurrence_item -> 'descriptor';
    payload := occurrence_item -> 'payload';

    if descriptor ->> 'kind' = 'standard' then
      if not descriptor ?& array['kind', 'eventKind', 'recordTypeId']
        or descriptor - array['kind', 'eventKind', 'recordTypeId'] <> '{}'::jsonb
        or pg_catalog.jsonb_typeof(descriptor -> 'eventKind') is distinct from 'string'
        or pg_catalog.jsonb_typeof(descriptor -> 'recordTypeId') is distinct from 'string'
        or (descriptor ->> 'recordTypeId')::uuid is distinct from catalogue_row.record_type_id
        or descriptor ->> 'eventKind' is null
        or descriptor ->> 'eventKind' not in (
          'created', 'changed', 'deleted', 'linked', 'unlinked', 'reassigned',
          'state_changed'
        ) then
        raise exception using errcode = '22023', message = 'Installed Event descriptor is invalid';
      end if;
      event_kind := descriptor ->> 'eventKind';

      if event_kind = 'changed' then
        if not payload ?& array['kind', 'changedFieldIds']
          or payload - array['kind', 'changedFieldIds'] <> '{}'::jsonb
          or payload ->> 'kind' is distinct from event_kind
          or pg_catalog.jsonb_typeof(payload -> 'changedFieldIds') is distinct from 'array'
          or pg_catalog.jsonb_array_length(payload -> 'changedFieldIds') = 0 then
          raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
        end if;
        previous_field_id_text := null;
        for field_item in
          select item.value
          from pg_catalog.jsonb_array_elements(payload -> 'changedFieldIds')
            with ordinality as item(value, ordinal)
          order by item.ordinal
        loop
          if pg_catalog.jsonb_typeof(field_item) is distinct from 'string' then
            raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
          end if;
          field_id_text := pg_catalog.lower(field_item #>> '{}');
          if previous_field_id_text is not null
              and previous_field_id_text >= field_id_text
            or not exists (
              select 1 from pg_catalog.jsonb_array_elements(record_type -> 'fields') as field(value)
              where pg_catalog.lower(field.value ->> 'fieldId') = field_id_text
            ) then
            raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
          end if;
          previous_field_id_text := field_id_text;
        end loop;
      elsif event_kind = 'state_changed' then
        if not payload ?& array['kind', 'fieldId']
          or payload - array['kind', 'fieldId', 'previousValue', 'newValue'] <> '{}'::jsonb
          or payload ->> 'kind' is distinct from event_kind
          or pg_catalog.jsonb_typeof(payload -> 'fieldId') is distinct from 'string' then
          raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
        end if;
        select field.value into field_definition
        from pg_catalog.jsonb_array_elements(record_type -> 'fields') as field(value)
        where (field.value ->> 'fieldId')::uuid = (payload ->> 'fieldId')::uuid;
        if not found
          or (field_definition ->> 'personalData' = 'none'
            and not (payload ? 'previousValue' or payload ? 'newValue'))
          or (field_definition ->> 'personalData' <> 'none'
            and (payload ? 'previousValue' or payload ? 'newValue')) then
          raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
        end if;
      elsif payload <> pg_catalog.jsonb_build_object('kind', event_kind) then
        raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
      end if;

      definition_release := pg_catalog.jsonb_build_object(
        'kind', 'module',
        'rootId', module_release.root_id,
        'releaseRevision', module_release.release_revision,
        'releaseVersion', module_release.release_version,
        'contentFingerprint', module_release.content_fingerprint,
        'resolutionFingerprint', module_release.resolution_fingerprint
      );
    elsif descriptor ->> 'kind' = 'declared' then
      if not descriptor ?& array[
          'kind', 'owner', 'declarationId', 'key', 'recordTypeId', 'carriedFieldIds'
        ]
        or descriptor - array[
          'kind', 'owner', 'declarationId', 'key', 'recordTypeId', 'carriedFieldIds'
        ] <> '{}'::jsonb
        or pg_catalog.jsonb_typeof(descriptor -> 'owner') is distinct from 'object'
        or pg_catalog.jsonb_typeof(descriptor -> 'declarationId') is distinct from 'string'
        or pg_catalog.jsonb_typeof(descriptor -> 'key') is distinct from 'string'
        or pg_catalog.jsonb_typeof(descriptor -> 'recordTypeId') is distinct from 'string'
        or pg_catalog.jsonb_typeof(descriptor -> 'carriedFieldIds') is distinct from 'array'
        or (descriptor ->> 'recordTypeId')::uuid is distinct from catalogue_row.record_type_id then
        raise exception using errcode = '22023', message = 'Installed Event descriptor is invalid';
      end if;

      owner_kind := descriptor #>> '{owner,kind}';
      if owner_kind = 'application'
        and (descriptor -> 'owner') - array['kind', 'applicationRootId'] = '{}'::jsonb
        and (descriptor -> 'owner') ?& array['kind', 'applicationRootId']
        and pg_catalog.jsonb_typeof(
          descriptor #> '{owner,applicationRootId}'
        ) is not distinct from 'string' then
        owner_root_id := (descriptor #>> '{owner,applicationRootId}')::uuid;
        if owner_root_id <> context_application_root_id then
          raise exception using errcode = '22023', message = 'Installed Event descriptor is invalid';
        end if;
        select pg_catalog.count(*), pg_catalog.jsonb_agg(event.value) -> 0
        into declared_event_count, declared_event
        from pg_catalog.jsonb_array_elements(application_content -> 'events') as event(value)
        where (event.value ->> 'eventId')::uuid = (descriptor ->> 'declarationId')::uuid
          and event.value ->> 'key' = descriptor ->> 'key';
        definition_release := pg_catalog.jsonb_build_object(
          'kind', 'application',
          'rootId', application_release.root_id,
          'releaseRevision', application_release.release_revision,
          'releaseVersion', application_release.release_version,
          'contentFingerprint', application_release.content_fingerprint,
          'resolutionFingerprint', application_release.resolution_fingerprint
        );
      elsif owner_kind = 'module'
        and (descriptor -> 'owner') - array['kind', 'moduleRootId'] = '{}'::jsonb
        and (descriptor -> 'owner') ?& array['kind', 'moduleRootId']
        and pg_catalog.jsonb_typeof(
          descriptor #> '{owner,moduleRootId}'
        ) is not distinct from 'string' then
        owner_root_id := (descriptor #>> '{owner,moduleRootId}')::uuid;
        if owner_root_id <> module_release.root_id then
          raise exception using errcode = '22023', message = 'Installed Event descriptor is invalid';
        end if;
        select pg_catalog.count(*), pg_catalog.jsonb_agg(event.value) -> 0
        into declared_event_count, declared_event
        from pg_catalog.jsonb_array_elements(module_content -> 'events') as event(value)
        where (event.value ->> 'eventId')::uuid = (descriptor ->> 'declarationId')::uuid
          and event.value ->> 'key' = descriptor ->> 'key';
        definition_release := pg_catalog.jsonb_build_object(
          'kind', 'module',
          'rootId', module_release.root_id,
          'releaseRevision', module_release.release_revision,
          'releaseVersion', module_release.release_version,
          'contentFingerprint', module_release.content_fingerprint,
          'resolutionFingerprint', module_release.resolution_fingerprint
        );
      else
        raise exception using errcode = '22023', message = 'Installed Event descriptor is invalid';
      end if;

      if declared_event_count <> 1
        or (declared_event ->> 'recordTypeId')::uuid <> catalogue_row.record_type_id
        or declared_event -> 'carriedFieldIds' is distinct from
          descriptor -> 'carriedFieldIds'
        or declared_event -> 'personalOrSensitiveValuesAllowed' is distinct from
          'false'::jsonb
        or not payload ?& array['kind', 'carriedValues']
        or payload - array['kind', 'carriedValues'] <> '{}'::jsonb
        or payload ->> 'kind' is distinct from 'declared'
        or pg_catalog.jsonb_typeof(payload -> 'carriedValues') is distinct from 'object' then
        raise exception using errcode = '22023', message = 'Installed Event declaration is invalid';
      end if;

      if exists (
        select 1
        from pg_catalog.jsonb_each(payload -> 'carriedValues') as carried(field_id, value)
        where not (descriptor -> 'carriedFieldIds') ? carried.field_id
          or not exists (
            select 1
            from pg_catalog.jsonb_array_elements(record_type -> 'fields') as field(value)
            where pg_catalog.lower(field.value ->> 'fieldId') = pg_catalog.lower(carried.field_id)
              and field.value ->> 'personalData' = 'none'
          )
      ) then
        raise exception using errcode = '22023', message = 'Installed Event payload is invalid';
      end if;
    else
      raise exception using errcode = '22023', message = 'Installed Event descriptor is invalid';
    end if;

    envelope := pg_catalog.jsonb_build_object(
      'contractVersion', '2.0.0',
      'occurrenceId', occurrence_id,
      'organizationId', context_organization_id,
      'installation', pg_catalog.jsonb_build_object(
        'applicationRootId', context_application_root_id,
        'applicationReleaseRevision', application_release_revision,
        'moduleBinding', pg_catalog.jsonb_build_object(
          'moduleRootId', binding_module_root_id,
          'moduleReleaseRevision', binding_module_release_revision,
          'bindingRevision', binding_revision
        )
      ),
      'descriptor', descriptor,
      'definitionRelease', definition_release,
      'recordId', p_record_id,
      'occurredAt', occurrence_time_text,
      'actorId', context_actor_id,
      'correlationId', context_correlation_id,
      'recordSequence', next_sequence,
      'payload', payload
    );

    insert into vortex_event.event_outbox (
      occurrence_id, organization_id, storage_contract_id, storage_scope,
      sequence_application_root_id, record_id, record_sequence, occurred_at,
      envelope
    ) values (
      occurrence_id, context_organization_id, p_storage_contract_id,
      catalogue_row.storage_scope, sequence_application_scope_id, p_record_id,
      next_sequence, occurrence_time, envelope
    );

    select sent.msg_id into strict queued_message_id
    from pgmq.send(
      'vortex_event_occurrences',
      pg_catalog.jsonb_build_object(
        'contractVersion', '2.0.0', 'occurrenceId', occurrence_id
      )
    ) as sent(msg_id);
    if queued_message_id is null then
      raise exception using errcode = '55000', message = 'Event queue append failed';
    end if;

    envelopes := envelopes || pg_catalog.jsonb_build_array(envelope);
    next_sequence := next_sequence + 1;
  end loop;

  return envelopes;
end
$function$;


ALTER FUNCTION vortex_event.append_record_occurrences_for_resolved_installation_internal(p_storage_contract_id uuid, p_record_id uuid, p_occurrences jsonb, p_installation jsonb) OWNER TO postgres;

--
-- Name: FUNCTION append_record_occurrences_for_resolved_installation_internal(p_storage_contract_id uuid, p_record_id uuid, p_occurrences jsonb, p_installation jsonb); Type: COMMENT; Schema: vortex_event; Owner: postgres
--

COMMENT ON FUNCTION vortex_event.append_record_occurrences_for_resolved_installation_internal(p_storage_contract_id uuid, p_record_id uuid, p_occurrences jsonb, p_installation jsonb) IS 'Appends an exact validated record occurrence batch; resolves the active installation under the canonical binding lock unless a trusted reader supplies an exact pin-set it resolved under that same lock.';


--
-- Name: claim_consumer_occurrences(text, integer, integer); Type: FUNCTION; Schema: vortex_event; Owner: vortex_event_owner
--

create or replace function vortex_event.claim_consumer_occurrences(
  p_consumer_key text,
  p_batch_size integer,
  p_lease_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  maximum_batch_size constant integer := 100;
  maximum_lease_seconds constant integer := 300;
  maximum_causal_depth constant integer := 16;
  maximum_delivery_attempts constant integer := 20;
  maximum_terminal_sweep constant integer := 400;
  claim_time timestamptz := pg_catalog.statement_timestamp();
  claim_cursor uuid := pg_catalog.gen_random_uuid();
  claimed jsonb;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_batch_size is null
    or p_batch_size not between 1 and maximum_batch_size
    or p_lease_seconds is null
    or p_lease_seconds not between 1 and maximum_lease_seconds then
    raise exception using errcode = '22023', message = 'Event consumer claim input is invalid';
  end if;

  -- A worker that dies mid-delivery reports nothing, so the lease simply
  -- lapses.  Counting the lapsed attempt here is what makes the retry budget
  -- bounded for interrupted work as well as for reported failures, and moves
  -- a blocked sequence to an operator-visible failure state rather than
  -- retrying it forever.  This must be its own statement: a data-modifying CTE
  -- in the claim query below would still read the pre-update snapshot.  The
  -- sweep is bounded and skips locked rows, so the reclaim below independently
  -- refuses to issue attempt maximum_delivery_attempts + 1; anything the sweep
  -- did not reach this time is simply terminalised on a later claim.
  update vortex_event.consumer_occurrence_progress as progress
  set last_failed_at = coalesce(progress.last_failed_at, claim_time),
      last_failure_code = coalesce(progress.last_failure_code, 'unclassified'),
      terminally_failed_at = case
        when progress.last_failed_at is not null and progress.last_failed_at > claim_time
          then progress.last_failed_at
        else claim_time
      end
  where (progress.consumer_key, progress.occurrence_id) in (
    select exhausted.consumer_key, exhausted.occurrence_id
    from vortex_event.consumer_occurrence_progress as exhausted
    where exhausted.consumer_key = p_consumer_key
      and exhausted.acknowledged_at is null
      and exhausted.terminally_failed_at is null
      and exhausted.lease_expires_at <= claim_time
      and exhausted.attempt_count >= maximum_delivery_attempts
    order by exhausted.lease_expires_at, exhausted.occurrence_id
    limit maximum_terminal_sweep
    for update skip locked
  );

  -- There is no mutable delivery state on an outbox occurrence.  Missing
  -- progress for an earlier sequence is therefore also an unacknowledged
  -- predecessor, which makes the barrier correct for a newly registered
  -- consumer as well as for a consumer recovering an expired lease.
  with candidate_window as materialized (
    select occurrence.*
    from vortex_event.event_outbox as occurrence
    left join vortex_event.consumer_occurrence_progress as progress
      on progress.consumer_key = p_consumer_key
      and progress.occurrence_id = occurrence.occurrence_id
    where progress.acknowledged_at is null
      and progress.terminally_failed_at is null
      and (progress.lease_expires_at is null or progress.lease_expires_at <= claim_time)
      and not exists (
        select 1
        from vortex_event.event_outbox as predecessor
        left join vortex_event.consumer_occurrence_progress as predecessor_progress
          on predecessor_progress.consumer_key = p_consumer_key
          and predecessor_progress.occurrence_id = predecessor.occurrence_id
        where predecessor.organization_id = occurrence.organization_id
          and predecessor.storage_contract_id = occurrence.storage_contract_id
          and predecessor.sequence_application_root_id is not distinct from
            occurrence.sequence_application_root_id
          and predecessor.record_id = occurrence.record_id
          and predecessor.record_sequence < occurrence.record_sequence
          and predecessor_progress.acknowledged_at is null
      )
    order by occurrence.occurred_at, occurrence.occurrence_id
    limit 400
  ), candidate as materialized (
    select occurrence.*, causal.depth as causal_depth
    from candidate_window as occurrence
    cross join lateral (
      select pg_catalog.pg_try_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'vortex_event.consumer:' || p_consumer_key || ':' || occurrence.occurrence_id::text,
          0
        )
      ) as acquired
    ) as claim_lock
    cross join lateral (
      with recursive causal_chain(occurrence_id, causation_id, depth, path) as (
        select occurrence.occurrence_id,
          case
            when occurrence.envelope ->> 'causationId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (occurrence.envelope ->> 'causationId')::uuid
            else null::uuid
          end,
          0,
          array[occurrence.occurrence_id]
        union all
        select parent.occurrence_id,
          case
            when parent.envelope ->> 'causationId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (parent.envelope ->> 'causationId')::uuid
            else null::uuid
          end,
          causal_chain.depth + 1,
          causal_chain.path || parent.occurrence_id
        from causal_chain
        join vortex_event.event_outbox as parent
          on parent.occurrence_id = causal_chain.causation_id
          and parent.organization_id = occurrence.organization_id
        where causal_chain.depth < maximum_causal_depth
          and not parent.occurrence_id = any (causal_chain.path)
      )
      select pg_catalog.max(depth)::integer as depth,
        coalesce(pg_catalog.bool_or(
          depth = maximum_causal_depth
          and causation_id is not null
          and exists (
            select 1 from vortex_event.event_outbox as deeper
            where deeper.occurrence_id = causal_chain.causation_id
              and deeper.organization_id = occurrence.organization_id
          )
        ), false) as exceeds_limit,
        coalesce(pg_catalog.bool_or(
          causation_id is not null
          and exists (
            select 1 from vortex_event.event_outbox as repeated
            where repeated.occurrence_id = causal_chain.causation_id
              and repeated.organization_id = occurrence.organization_id
              and repeated.occurrence_id = any (causal_chain.path)
          )
        ), false) as has_cycle
      from causal_chain
    ) as causal
    where claim_lock.acquired
      and not causal.exceeds_limit
      and not causal.has_cycle
    order by occurrence.occurred_at, occurrence.occurrence_id
    limit p_batch_size
  ), claimed as (
    insert into vortex_event.consumer_occurrence_progress (
      consumer_key, occurrence_id, claim_cursor, claimed_at, lease_expires_at, attempt_count
    )
    select p_consumer_key, occurrence_id, claim_cursor, claim_time,
      claim_time + pg_catalog.make_interval(secs => p_lease_seconds), 1
    from candidate
    on conflict (consumer_key, occurrence_id) do update
      set claim_cursor = excluded.claim_cursor,
          claimed_at = excluded.claimed_at,
          lease_expires_at = excluded.lease_expires_at,
          attempt_count = consumer_occurrence_progress.attempt_count + 1
      where consumer_occurrence_progress.acknowledged_at is null
        and consumer_occurrence_progress.terminally_failed_at is null
        and consumer_occurrence_progress.attempt_count < maximum_delivery_attempts
        and consumer_occurrence_progress.lease_expires_at <= claim_time
    returning occurrence_id, lease_expires_at
  )
  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'occurrence', candidate.envelope,
      'causalDepth', candidate.causal_depth,
      'leaseExpiresAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', claimed.lease_expires_at),
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    ) order by candidate.occurred_at, candidate.occurrence_id
  ) into claimed
  from claimed
  join candidate using (occurrence_id);

  return pg_catalog.jsonb_build_object(
    'ackCursor', case when claimed is null then null else claim_cursor end,
    'occurrences', coalesce(claimed, '[]'::jsonb)
  );
end
$function$;


ALTER FUNCTION vortex_event.claim_consumer_occurrences(p_consumer_key text, p_batch_size integer, p_lease_seconds integer) OWNER TO vortex_event_owner;

--
-- Name: FUNCTION claim_consumer_occurrences(p_consumer_key text, p_batch_size integer, p_lease_seconds integer); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.claim_consumer_occurrences(p_consumer_key text, p_batch_size integer, p_lease_seconds integer) IS 'Claims a bounded ordered set of unacknowledged Event occurrences for one consumer with a short renewable lease.';


--
-- Name: event_dispatch_backlog_status(); Type: FUNCTION; Schema: vortex_event; Owner: vortex_event_owner
--

create or replace function vortex_event.event_dispatch_backlog_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $function$
  with pending as (
    select pg_catalog.min(occurrence.occurred_at) as oldest_occurred_at
    from vortex_event.consumer_occurrence_progress as progress
    join vortex_event.event_outbox as occurrence
      on occurrence.occurrence_id = progress.occurrence_id
    where progress.acknowledged_at is null
      and progress.terminally_failed_at is null
  ), failed as (
    select pg_catalog.count(*) as failure_count
    from (
      select 1
      from vortex_event.consumer_occurrence_progress as progress
      where progress.terminally_failed_at is not null
      limit 1000000
    ) as bounded
  )
  select pg_catalog.jsonb_build_object(
    'oldestPendingAgeSeconds',
      case
        when pending.oldest_occurred_at is null then null
        else least(
          2592000,
          greatest(
            0,
            -- EXTRACT is SQL syntax, not a schema-qualifiable call; it always
            -- resolves from pg_catalog even under the empty search_path.
            pg_catalog.floor(
              extract(
                epoch from (pg_catalog.statement_timestamp() - pending.oldest_occurred_at)
              )
            )
          )
        )::integer
      end,
    'terminalFailureCount', failed.failure_count::integer
  )
  from pending, failed;
$function$;


ALTER FUNCTION vortex_event.event_dispatch_backlog_status() OWNER TO vortex_event_owner;

--
-- Name: FUNCTION event_dispatch_backlog_status(); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.event_dispatch_backlog_status() IS 'Bounded, content-free event delivery backlog: age in seconds of the oldest claimed occurrence not yet acknowledged or terminally failed, and the terminal failure count. Reveals no occurrence identity, consumer identity or payload.';


--
-- Name: list_terminally_failed_consumer_occurrences(text, integer); Type: FUNCTION; Schema: vortex_event; Owner: vortex_event_owner
--

create or replace function vortex_event.list_terminally_failed_consumer_occurrences(
  p_consumer_key text,
  p_limit integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  maximum_limit constant integer := 100;
  results jsonb;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_limit is null or p_limit not between 1 and maximum_limit then
    raise exception using errcode = '22023',
      message = 'Event delivery recovery listing input is invalid';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'occurrenceId', bounded.occurrence_id,
      'attemptCount', bounded.attempt_count,
      'failureCount', bounded.failure_count,
      'lastFailureCode', bounded.last_failure_code,
      'lastFailedAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', bounded.last_failed_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'terminallyFailedAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', bounded.terminally_failed_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'claimedAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', bounded.claimed_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    ) order by bounded.terminally_failed_at, bounded.occurrence_id
  ), '[]'::jsonb) into results
  from (
    select progress.occurrence_id, progress.attempt_count, progress.failure_count,
      progress.last_failure_code, progress.last_failed_at, progress.terminally_failed_at,
      progress.claimed_at
    from vortex_event.consumer_occurrence_progress as progress
    where progress.consumer_key = p_consumer_key
      and progress.terminally_failed_at is not null
    order by progress.terminally_failed_at, progress.occurrence_id
    limit p_limit
  ) as bounded;

  return results;
end
$function$;


ALTER FUNCTION vortex_event.list_terminally_failed_consumer_occurrences(p_consumer_key text, p_limit integer) OWNER TO vortex_event_owner;

--
-- Name: FUNCTION list_terminally_failed_consumer_occurrences(p_consumer_key text, p_limit integer); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.list_terminally_failed_consumer_occurrences(p_consumer_key text, p_limit integer) IS 'Bounded inspection of currently exhausted, replayable claims for one consumer.';


--
-- Name: record_consumer_occurrence_delivery_failure(text, uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: vortex_event; Owner: vortex_event_owner
--

create or replace function vortex_event.record_consumer_occurrence_delivery_failure(
  p_consumer_key text,
  p_occurrence_id uuid,
  p_claim_cursor uuid,
  p_failure_code text,
  p_max_attempts integer,
  p_retry_backoff_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  maximum_retry_attempts constant integer := 20;
  maximum_retry_backoff_seconds constant integer := 86400;
  failure_time timestamptz := pg_catalog.statement_timestamp();
  progress_row vortex_event.consumer_occurrence_progress%rowtype;
  next_failure_count integer;
  next_lease_expires_at timestamptz;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_occurrence_id is null or p_occurrence_id = nil_uuid
    or p_claim_cursor is null or p_claim_cursor = nil_uuid
    or p_failure_code is null
    or p_failure_code not in (
      'transient_dependency_unavailable', 'transient_timeout', 'validation_rejected',
      'authorization_denied', 'conflict_or_duplicate', 'unclassified'
    )
    or p_max_attempts is null or p_max_attempts not between 1 and maximum_retry_attempts
    or p_retry_backoff_seconds is null
      or p_retry_backoff_seconds not between 1 and maximum_retry_backoff_seconds then
    raise exception using errcode = '22023',
      message = 'Event delivery failure input is invalid';
  end if;

  select progress.* into progress_row
  from vortex_event.consumer_occurrence_progress as progress
  where progress.consumer_key = p_consumer_key
    and progress.occurrence_id = p_occurrence_id
  for update;

  if not found then
    return pg_catalog.jsonb_build_object('outcome', 'claim_unavailable');
  end if;
  if progress_row.claim_cursor <> p_claim_cursor then
    return pg_catalog.jsonb_build_object('outcome', 'mismatched');
  end if;
  if progress_row.acknowledged_at is not null then
    return pg_catalog.jsonb_build_object('outcome', 'already_acknowledged');
  end if;
  if progress_row.terminally_failed_at is not null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'terminal_failure',
      'failureCount', progress_row.failure_count,
      'failureCode', progress_row.last_failure_code
    );
  end if;

  next_failure_count := progress_row.failure_count + 1;

  if next_failure_count >= p_max_attempts then
    update vortex_event.consumer_occurrence_progress
    set failure_count = next_failure_count,
        last_failure_code = p_failure_code,
        last_failed_at = failure_time,
        terminally_failed_at = failure_time
    where consumer_key = p_consumer_key and occurrence_id = p_occurrence_id;

    return pg_catalog.jsonb_build_object(
      'outcome', 'terminal_failure',
      'failureCount', next_failure_count,
      'failureCode', p_failure_code
    );
  end if;

  -- Releasing the lease at the backoff instant is what schedules the retry:
  -- #639's claim reclaims exactly this consumer/occurrence row once the lease
  -- has lapsed, so no fresh work is claimed and no ordering is skipped.
  next_lease_expires_at := failure_time + pg_catalog.make_interval(secs => p_retry_backoff_seconds);
  update vortex_event.consumer_occurrence_progress
  set failure_count = next_failure_count,
      last_failure_code = p_failure_code,
      last_failed_at = failure_time,
      lease_expires_at = next_lease_expires_at
  where consumer_key = p_consumer_key and occurrence_id = p_occurrence_id;

  return pg_catalog.jsonb_build_object(
    'outcome', 'retry_scheduled',
    'failureCount', next_failure_count,
    'retryNotBefore', pg_catalog.to_char(
      pg_catalog.timezone('UTC', next_lease_expires_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
end
$function$;


ALTER FUNCTION vortex_event.record_consumer_occurrence_delivery_failure(p_consumer_key text, p_occurrence_id uuid, p_claim_cursor uuid, p_failure_code text, p_max_attempts integer, p_retry_backoff_seconds integer) OWNER TO vortex_event_owner;

--
-- Name: FUNCTION record_consumer_occurrence_delivery_failure(p_consumer_key text, p_occurrence_id uuid, p_claim_cursor uuid, p_failure_code text, p_max_attempts integer, p_retry_backoff_seconds integer); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.record_consumer_occurrence_delivery_failure(p_consumer_key text, p_occurrence_id uuid, p_claim_cursor uuid, p_failure_code text, p_max_attempts integer, p_retry_backoff_seconds integer) IS 'Records one failed delivery attempt against an existing claim, scheduling a bounded retry or marking it terminally failed.';


--
-- Name: recover_consumer_occurrence_claim(text, uuid, integer, uuid); Type: FUNCTION; Schema: vortex_event; Owner: vortex_event_owner
--

create or replace function vortex_event.recover_consumer_occurrence_claim(
  p_consumer_key text,
  p_occurrence_id uuid,
  p_expected_failure_count integer,
  p_system_actor_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  recovery_time timestamptz := pg_catalog.statement_timestamp();
  grant_state text;
  progress_row vortex_event.consumer_occurrence_progress%rowtype;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_occurrence_id is null or p_occurrence_id = nil_uuid
    or p_expected_failure_count is null or p_expected_failure_count < 0
    or p_system_actor_id is null or p_system_actor_id = nil_uuid then
    raise exception using errcode = '22023',
      message = 'Event delivery recovery input is invalid';
  end if;

  grant_state := vortex_access.resolve_system_actor_grant_internal(
    p_system_actor_id, 'recover_consumer_occurrence_claim', null, null, p_consumer_key
  );
  if grant_state is null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'unauthorised', 'reason', 'authority_not_configured'
    );
  end if;
  if grant_state <> 'active' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'unauthorised', 'reason', 'authority_revoked'
    );
  end if;

  select progress.* into progress_row
  from vortex_event.consumer_occurrence_progress as progress
  where progress.consumer_key = p_consumer_key
    and progress.occurrence_id = p_occurrence_id
  for update;

  if not found then
    return pg_catalog.jsonb_build_object('outcome', 'claim_unavailable');
  end if;
  if progress_row.acknowledged_at is not null then
    return pg_catalog.jsonb_build_object('outcome', 'already_acknowledged');
  end if;
  if progress_row.terminally_failed_at is null then
    if progress_row.lease_expires_at > recovery_time then
      return pg_catalog.jsonb_build_object('outcome', 'active');
    end if;
    -- Lapsed but never exhausted: ordinary reclaim already covers it, so the
    -- privileged override is not the right path for this claim.
    return pg_catalog.jsonb_build_object('outcome', 'not_exhausted');
  end if;
  if progress_row.failure_count <> p_expected_failure_count then
    return pg_catalog.jsonb_build_object(
      'outcome', 'stale',
      'failureCount', progress_row.failure_count
    );
  end if;

  -- Clearing the terminal hold and both budgets hands the claim back to
  -- #639's ordinary reclaim for exactly this consumer and occurrence. Failure
  -- evidence and the recovery attribution stay on the row.
  update vortex_event.consumer_occurrence_progress
  set terminally_failed_at = null,
      failure_count = 0,
      attempt_count = 0,
      recovered_at = recovery_time,
      recovered_by = p_system_actor_id,
      recovery_count = recovery_count + 1,
      lease_expires_at = recovery_time
  where consumer_key = p_consumer_key and occurrence_id = p_occurrence_id;

  return pg_catalog.jsonb_build_object(
    'outcome', 'recovered',
    'recoveredBy', p_system_actor_id,
    'leaseExpiresAt', vortex_context.format_timestamp_utc(recovery_time)
  );
end
$function$;


ALTER FUNCTION vortex_event.recover_consumer_occurrence_claim(p_consumer_key text, p_occurrence_id uuid, p_expected_failure_count integer, p_system_actor_id uuid) OWNER TO vortex_event_owner;

--
-- Name: FUNCTION recover_consumer_occurrence_claim(p_consumer_key text, p_occurrence_id uuid, p_expected_failure_count integer, p_system_actor_id uuid); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.recover_consumer_occurrence_claim(p_consumer_key text, p_occurrence_id uuid, p_expected_failure_count integer, p_system_actor_id uuid) IS 'Recovery of one exhausted claim for the same consumer and occurrence identity, authorised by the system actor grant scoped to that consumer and attributed to the granted system actor.';


