--
-- Name: renew_consumer_occurrence_lease(text, uuid, uuid, integer); Type: FUNCTION; Schema: vortex_event; Owner: vortex_event_owner
--

create or replace function vortex_event.renew_consumer_occurrence_lease(
  p_consumer_key text,
  p_ack_cursor uuid,
  p_occurrence_id uuid,
  p_lease_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  maximum_lease_seconds constant integer := 300;
  renewal_time timestamptz := pg_catalog.statement_timestamp();
  renewed_until timestamptz;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_ack_cursor is null or p_ack_cursor = nil_uuid
    or p_occurrence_id is null or p_occurrence_id = nil_uuid
    or p_lease_seconds is null
    or p_lease_seconds not between 1 and maximum_lease_seconds then
    raise exception using errcode = '22023', message = 'Event consumer lease renewal input is invalid';
  end if;

  update vortex_event.consumer_occurrence_progress
  set lease_expires_at = renewal_time + pg_catalog.make_interval(secs => p_lease_seconds)
  where consumer_key = p_consumer_key
    and occurrence_id = p_occurrence_id
    and claim_cursor = p_ack_cursor
    and acknowledged_at is null
    and terminally_failed_at is null
    and lease_expires_at > renewal_time
  returning lease_expires_at into renewed_until;

  if renewed_until is null then
    return pg_catalog.jsonb_build_object('outcome', 'claim_unavailable');
  end if;
  return pg_catalog.jsonb_build_object(
    'outcome', 'renewed',
    'leaseExpiresAt', pg_catalog.to_char(
      pg_catalog.timezone('UTC', renewed_until), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
end
$function$;


ALTER FUNCTION vortex_event.renew_consumer_occurrence_lease(p_consumer_key text, p_ack_cursor uuid, p_occurrence_id uuid, p_lease_seconds integer) OWNER TO vortex_event_owner;

--
-- Name: FUNCTION renew_consumer_occurrence_lease(p_consumer_key text, p_ack_cursor uuid, p_occurrence_id uuid, p_lease_seconds integer); Type: COMMENT; Schema: vortex_event; Owner: vortex_event_owner
--

COMMENT ON FUNCTION vortex_event.renew_consumer_occurrence_lease(p_consumer_key text, p_ack_cursor uuid, p_occurrence_id uuid, p_lease_seconds integer) IS 'Renews one still-live consumer Event occurrence claim without changing immutable occurrence evidence.';


--
-- Name: request_event_dispatch_wakeup(); Type: FUNCTION; Schema: vortex_event; Owner: postgres
--

create or replace function vortex_event.request_event_dispatch_wakeup()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  endpoint_url text := nullif(
    pg_catalog.current_setting('vortex.event_dispatch_wakeup_url', true), ''
  );
  bearer_credential text := nullif(
    pg_catalog.current_setting('vortex.event_dispatch_wakeup_bearer', true), ''
  );
begin
  -- Fail closed: an unconfigured endpoint or credential sends nothing.
  if endpoint_url is null or bearer_credential is null then
    return null;
  end if;
  -- Only a whitespace-free HTTPS endpoint is accepted, so a database setting
  -- cannot point the hint at a plaintext or non-HTTP target.
  if endpoint_url !~ '^https://[^[:space:]]+$' then
    return null;
  end if;
  -- The bearer must have the exact printable-ASCII shape and length the #641
  -- route accepts; anything else would only queue a doomed request.
  if bearer_credential !~ '^[!-~]+$'
    or pg_catalog.octet_length(bearer_credential) not between 32 and 512 then
    return null;
  end if;

  -- One hint per transaction is enough: a multi-occurrence append is one
  -- durable unit of work, and the scheduled recovery tick covers a missed
  -- hint. A later inserted row in the same transaction queues no second
  -- request.
  if pg_catalog.current_setting('vortex.event_dispatch_wakeup_sent', true) = 'true' then
    return null;
  end if;
  perform pg_catalog.set_config('vortex.event_dispatch_wakeup_sent', 'true', true);

  -- pg_net queues the request transactionally and sends it only after this
  -- transaction commits; a rolled-back append sends nothing. Best effort only:
  -- the hint must never make the durable append fail.
  begin
    perform net.http_post(
      url := endpoint_url,
      headers := pg_catalog.jsonb_build_object(
        'Authorization', 'Bearer ' || bearer_credential,
        'Content-Type', 'application/json'
      ),
      body := pg_catalog.jsonb_build_object('source', 'database_webhook'),
      timeout_milliseconds := 5000
    );
  exception when others then
    return null;
  end;
  return null;
end
$function$;


ALTER FUNCTION vortex_event.request_event_dispatch_wakeup() OWNER TO postgres;

--
-- Name: FUNCTION request_event_dispatch_wakeup(); Type: COMMENT; Schema: vortex_event; Owner: postgres
--

COMMENT ON FUNCTION vortex_event.request_event_dispatch_wakeup() IS 'Best-effort database-webhook wake-up hint for the protected Vercel event dispatcher, queued once per appending transaction and sent after commit. Reads its HTTPS endpoint and bearer credential from the vortex.event_dispatch_wakeup_url and vortex.event_dispatch_wakeup_bearer database settings at runtime and sends nothing when either is absent or unusable.';


--
-- Name: activate_uploaded_file(uuid, bigint, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_file; Owner: vortex_file_owner
--

create or replace function vortex_file.activate_uploaded_file(
  p_file_id uuid,
  p_expected_revision bigint,
  p_owner_record_type_id uuid,
  p_owner_record_id uuid,
  p_owner_field_id uuid,
  p_attachment_reference_id uuid,
  p_replacing_file_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_file.upload_validated_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  reservation vortex_file.upload_reservations%rowtype;
  uploaded vortex_file.file_records%rowtype;
  attached_count bigint;
begin
  if p_attachment_reference_id is null
    or not vortex_context.is_non_nil_uuid(p_attachment_reference_id::text) then
    raise exception using errcode = '22023', message = 'File activation is invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f',
      'vortex_file.upload_field', (established ->> 'organizationId')::uuid::text,
      p_owner_record_type_id::text, p_owner_record_id::text, p_owner_field_id::text), 652)
  );

  select stored.* into reservation
  from vortex_file.upload_reservations as stored
  where stored.file_id = p_file_id
    and stored.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found then
    return vortex_file.upload_refusal('file_not_found');
  end if;
  if request_actor is null or reservation.uploaded_by is distinct from request_actor then
    perform vortex_file.append_file_activity_internal(
      'file_activation_refused', p_file_id);
    return vortex_file.upload_refusal('caller_not_authorized');
  end if;
  if reservation.owner_record_type_id is distinct from p_owner_record_type_id
    or reservation.owner_record_id is distinct from p_owner_record_id
    or reservation.owner_field_id is distinct from p_owner_field_id then
    return vortex_file.upload_refusal('owner_mismatch');
  end if;

  select stored.* into strict uploaded
  from vortex_file.file_records as stored
  where stored.file_id = p_file_id
  for update;

  if uploaded.lifecycle_state = 'active'
    and p_attachment_reference_id = any (uploaded.owning_attachment_references) then
    return pg_catalog.jsonb_build_object(
      'outcome', 'activated',
      'fileRecord', vortex_file.upload_file_record(uploaded)
    );
  end if;
  if uploaded.lifecycle_state <> 'scanning' or uploaded.scanner_result <> 'clean' then
    return vortex_file.upload_refusal('invalid_lifecycle_state');
  end if;
  if reservation.upload_expires_at <= evaluated_at then
    return vortex_file.upload_refusal('upload_expired');
  end if;
  if reservation.revision is distinct from p_expected_revision then
    return vortex_file.upload_refusal('revision_conflict');
  end if;
  if reservation.replacing_file_id is distinct from p_replacing_file_id then
    return vortex_file.upload_refusal('replacement_file_not_found');
  end if;
  if p_replacing_file_id is not null then
    perform 1
    from vortex_file.file_records as replaced
    where replaced.file_id = p_replacing_file_id
      and replaced.organization_id = reservation.organization_id
      and replaced.owner_record_type_id = reservation.owner_record_type_id
      and replaced.owner_record_id = reservation.owner_record_id
      and replaced.owner_field_id = reservation.owner_field_id
      and replaced.lifecycle_state = 'active'
    for share;
    if not found then
      return vortex_file.upload_refusal('replacement_file_not_found');
    end if;
  end if;

  if reservation.max_files is not null then
    select pg_catalog.count(*) into attached_count
    from vortex_file.file_records as attached
    where attached.organization_id = reservation.organization_id
      and attached.owner_record_type_id = reservation.owner_record_type_id
      and attached.owner_record_id = reservation.owner_record_id
      and attached.owner_field_id = reservation.owner_field_id
      and attached.lifecycle_state = 'active'
      and attached.file_id <> p_file_id
      and attached.file_id is distinct from p_replacing_file_id;
    if attached_count >= reservation.max_files then
      raise exception using errcode = '23514',
        message = 'Attachment field already holds its maximum number of files';
    end if;
  end if;

  update vortex_file.file_records
  set
    lifecycle_state = 'active',
    activated_at = evaluated_at,
    owning_attachment_references = pg_catalog.array_append(
      owning_attachment_references, p_attachment_reference_id
    )
  where file_id = p_file_id
  returning * into uploaded;

  update vortex_file.upload_reservations
  set revision = revision + 1, updated_at = evaluated_at
  where file_id = p_file_id;

  perform vortex_file.append_file_activity_internal(
    'file_activated', p_file_id);

  return pg_catalog.jsonb_build_object(
    'outcome', 'activated',
    'fileRecord', vortex_file.upload_file_record(uploaded)
  );
end
$function$;


ALTER FUNCTION vortex_file.activate_uploaded_file(p_file_id uuid, p_expected_revision bigint, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_attachment_reference_id uuid, p_replacing_file_id uuid) OWNER TO vortex_file_owner;

--
-- Name: FUNCTION activate_uploaded_file(p_file_id uuid, p_expected_revision bigint, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_attachment_reference_id uuid, p_replacing_file_id uuid); Type: COMMENT; Schema: vortex_file; Owner: vortex_file_owner
--

COMMENT ON FUNCTION vortex_file.activate_uploaded_file(p_file_id uuid, p_expected_revision bigint, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_attachment_reference_id uuid, p_replacing_file_id uuid) IS 'Activates a clean scanned upload inside the record save that attaches it.';


--
-- Name: advance_file_metadata_revision(); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

create or replace function vortex_file.advance_file_metadata_revision()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $function$
begin
  if tg_op = 'INSERT' then
    if new.metadata_revision is distinct from 1 then
      raise exception using
        errcode = '22023',
        message = 'File metadata revision must start at one';
    end if;
    new.metadata_revision := 1;
    return new;
  end if;

  if new.metadata_revision is distinct from old.metadata_revision then
    raise exception using
      errcode = '22023',
      message = 'File metadata revision is managed by the File metadata trigger';
  end if;

  if old.metadata_revision >= 9007199254740991 then
    raise exception using
      errcode = '22003',
      message = 'File metadata revision is exhausted';
  end if;

  new.metadata_revision := old.metadata_revision + 1;
  return new;
end
$function$;


ALTER FUNCTION vortex_file.advance_file_metadata_revision() OWNER TO postgres;

--
-- Name: FUNCTION advance_file_metadata_revision(); Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON FUNCTION vortex_file.advance_file_metadata_revision() IS 'Maintains the File metadata revision on each file record insert or update.';


--
-- Name: append_file_activity_internal(text, uuid); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

create or replace function vortex_file.append_file_activity_internal(
  p_action text,
  p_subject_id uuid
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  established jsonb := vortex_context.current_context();
  request_actor jsonb;
  organization_id_value uuid;
  correlation_id_value uuid;
  outcome_value text;
  actor_kind text;
  actor_identifier uuid;
  source_value text;
  activity_id_value uuid;
begin
  outcome_value := case p_action
    when 'file_upload_admitted' then 'completed'
    when 'file_upload_refused' then 'refused'
    when 'file_activated' then 'completed'
    when 'file_activation_refused' then 'refused'
    when 'file_download_granted' then 'completed'
  end;
  if outcome_value is null
    or p_subject_id is null
    or p_subject_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'File Activity input is invalid';
  end if;

  request_actor := vortex_file.upload_request_actor(established);
  if request_actor is null then
    return;
  end if;

  if request_actor ->> 'kind' = 'human' then
    actor_kind := 'organization_account';
    actor_identifier := (request_actor ->> 'organizationAccountId')::uuid;
    source_value := 'web';
  else
    actor_kind := 'system';
    actor_identifier := (request_actor ->> 'systemActorId')::uuid;
    source_value := 'system';
  end if;

  organization_id_value := (established ->> 'organizationId')::uuid;
  correlation_id_value := (established ->> 'correlationId')::uuid;
  activity_id_value := vortex_file.file_activity_id(
    p_action, organization_id_value, correlation_id_value, p_subject_id
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f',
      'vortex_file.activity', organization_id_value::text, activity_id_value::text), 744)
  );

  if exists (
    select 1
    from vortex_activity.organization_activity_entries as existing
    where existing.organization_id = organization_id_value
      and existing.activity_id = activity_id_value
  ) then
    return;
  end if;

  perform vortex_activity.append_organization_activity_entry(
    organization_id_value,
    activity_id_value,
    pg_catalog.statement_timestamp(),
    actor_kind,
    actor_identifier,
    p_action,
    array[p_subject_id]::uuid[],
    array[]::uuid[],
    source_value,
    correlation_id_value,
    outcome_value
  );
end
$function$;


ALTER FUNCTION vortex_file.append_file_activity_internal(p_action text, p_subject_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION append_file_activity_internal(p_action text, p_subject_id uuid); Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON FUNCTION vortex_file.append_file_activity_internal(p_action text, p_subject_id uuid) IS 'Appends one content-free File Activity entry for the verified request actor; used by the admission, activation and download-grant owners.';


--
-- Name: claim_file_download_grant(uuid); Type: FUNCTION; Schema: vortex_file; Owner: vortex_file_owner
--

create or replace function vortex_file.claim_file_download_grant(p_one_time_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_context.validated_service_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  claimed vortex_file.download_grants%rowtype;
  stored vortex_file.file_records%rowtype;
begin
  if request_actor is null then
    return null;
  end if;

  select candidate.* into claimed
  from vortex_file.download_grants as candidate
  where candidate.one_time_id = p_one_time_id
    and candidate.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found
    or claimed.credential_issued_at is not null
    or claimed.expires_at <= evaluated_at
    or claimed.actor is distinct from request_actor then
    return null;
  end if;

  select candidate.* into stored
  from vortex_file.file_records as candidate
  where candidate.file_id = claimed.file_id
    and candidate.organization_id = claimed.organization_id;
  if not found
    or stored.lifecycle_state <> 'active'
    or stored.scanner_result <> 'clean'
    or stored.owner_record_type_id is distinct from claimed.owner_record_type_id
    or stored.owner_record_id is distinct from claimed.owner_record_id
    or stored.owner_field_id is distinct from claimed.owner_field_id then
    return null;
  end if;

  update vortex_file.download_grants
  set credential_issued_at = evaluated_at
  where one_time_id = claimed.one_time_id;

  return pg_catalog.jsonb_build_object(
    'grant', pg_catalog.jsonb_build_object(
      'kind', 'download',
      'organizationId', claimed.organization_id,
      'actor', claimed.actor,
      'recordTypeId', claimed.owner_record_type_id,
      'recordId', claimed.owner_record_id,
      'fieldId', claimed.owner_field_id,
      'fileId', claimed.file_id,
      'oneTimeId', claimed.one_time_id,
      'expiresAt', vortex_context.format_timestamp_utc(claimed.expires_at)
    ),
    'fileRecord', vortex_file.upload_file_record(stored),
    'correlationId', claimed.correlation_id
  );
end
$function$;


ALTER FUNCTION vortex_file.claim_file_download_grant(p_one_time_id uuid) OWNER TO vortex_file_owner;

