-- Name: FUNCTION claim_file_download_grant(p_one_time_id uuid); Type: COMMENT; Schema: vortex_file; Owner: vortex_file_owner
--

COMMENT ON FUNCTION vortex_file.claim_file_download_grant(p_one_time_id uuid) IS 'Claims an unexpired read grant of the request actor exactly once with its current FileRecord.';


--
-- Name: claim_file_upload_grant(uuid); Type: FUNCTION; Schema: vortex_file; Owner: vortex_file_owner
--

create or replace function vortex_file.claim_file_upload_grant(p_one_time_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_file.upload_validated_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  claimed_file_id uuid;
  reservation vortex_file.upload_reservations%rowtype;
  claimed vortex_file.upload_grants%rowtype;
  uploaded vortex_file.file_records%rowtype;
begin
  select candidate.file_id into claimed_file_id
  from vortex_file.upload_grants as candidate
  where candidate.one_time_id = p_one_time_id
    and candidate.organization_id = (established ->> 'organizationId')::uuid;
  if not found or request_actor is null then
    return null;
  end if;

  -- Reservation first, then grant: the same order renewal and completion use.
  select stored.* into strict reservation
  from vortex_file.upload_reservations as stored
  where stored.file_id = claimed_file_id
  for update;

  select stored.* into strict claimed
  from vortex_file.upload_grants as stored
  where stored.one_time_id = p_one_time_id
  for update;

  select stored.* into strict uploaded
  from vortex_file.file_records as stored
  where stored.file_id = claimed_file_id;

  if claimed.superseded_at is not null
    or claimed.credential_issued_at is not null
    or claimed.expires_at <= evaluated_at
    or claimed.actor is distinct from request_actor
    or reservation.uploaded_by is distinct from request_actor
    or reservation.upload_expires_at <= evaluated_at
    or uploaded.lifecycle_state <> 'pending' then
    return null;
  end if;

  update vortex_file.upload_grants
  set credential_issued_at = evaluated_at
  where one_time_id = claimed.one_time_id;

  return pg_catalog.jsonb_build_object(
    'grant', pg_catalog.jsonb_build_object(
      'kind', 'upload',
      'organizationId', claimed.organization_id,
      'actor', claimed.actor,
      'recordTypeId', reservation.owner_record_type_id,
      'recordId', reservation.owner_record_id,
      'fieldId', reservation.owner_field_id,
      'maximumBytes', claimed.maximum_bytes,
      'policyFingerprint', claimed.policy_fingerprint,
      'expiresAt', vortex_context.format_timestamp_utc(claimed.expires_at),
      'oneTimeId', claimed.one_time_id
    ),
    'fileRecord', vortex_file.upload_file_record(uploaded),
    'correlationId', reservation.correlation_id
  );
end
$function$;


ALTER FUNCTION vortex_file.claim_file_upload_grant(p_one_time_id uuid) OWNER TO vortex_file_owner;

--
-- Name: FUNCTION claim_file_upload_grant(p_one_time_id uuid); Type: COMMENT; Schema: vortex_file; Owner: vortex_file_owner
--

COMMENT ON FUNCTION vortex_file.claim_file_upload_grant(p_one_time_id uuid) IS 'Issues the one Storage credential of a current, unexpired grant for the uploader of a pending upload.';


--
-- Name: decide_file_read(uuid); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

CREATE FUNCTION vortex_file.decide_file_read(p_file_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  stored_organization_id uuid;
  stored_application_root_id uuid;
  stored_record_type_id uuid;
  stored_record_id uuid;
  stored_field_id uuid;
  stored_lifecycle_state text;
  stored_scanner_result text;
  projection jsonb;
  attached jsonb;
begin
  if p_file_id is null
    or p_file_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  select stored.organization_id, stored.application_root_id,
    stored.owner_record_type_id, stored.owner_record_id, stored.owner_field_id,
    stored.lifecycle_state, stored.scanner_result
  into stored_organization_id, stored_application_root_id,
    stored_record_type_id, stored_record_id, stored_field_id,
    stored_lifecycle_state, stored_scanner_result
  from vortex_file.file_records as stored
  where stored.file_id = p_file_id;
  if not found
    or stored_record_id is null
    or stored_lifecycle_state <> 'active'
    or stored_scanner_result <> 'clean' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  projection := vortex_record.read_record(stored_record_type_id, stored_record_id);
  if projection ->> 'outcome' is distinct from 'allowed' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  attached := projection -> 'values' -> (stored_field_id::text);
  if pg_catalog.jsonb_typeof(attached) is distinct from 'array'
    or not exists (
      select 1
      from pg_catalog.jsonb_array_elements(attached) as member(value)
      where pg_catalog.jsonb_typeof(member.value) = 'string'
        and pg_catalog.lower(member.value #>> '{}') = p_file_id::text
    ) then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  return pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'outcome', 'allowed',
    'organizationId', stored_organization_id,
    'applicationRootId', stored_application_root_id,
    'recordTypeId', stored_record_type_id,
    'recordId', stored_record_id,
    'fieldId', stored_field_id
  ));
end
$$;


ALTER FUNCTION vortex_file.decide_file_read(p_file_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION decide_file_read(p_file_id uuid); Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON FUNCTION vortex_file.decide_file_read(p_file_id uuid) IS 'Decides current read authority for a file through the protected record read and the attachment value that names it.';


--
-- Name: enforce_file_application_root(); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

create or replace function vortex_file.enforce_file_application_root()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  application_root record;
begin
  if new.application_root_id is null then
    return new;
  end if;

  select root.organization_id, root.kind into application_root
  from vortex_definition.roots as root
  where root.root_id = new.application_root_id;

  if not found then
    raise exception using errcode = '23503',
      message = 'Referenced application root does not exist';
  end if;

  if application_root.kind <> 'application' then
    raise exception using errcode = '23514',
      message = 'Referenced root must be of kind application';
  end if;

  if application_root.organization_id <> new.organization_id then
    raise exception using errcode = '23514',
      message = 'Referenced application root organization does not match file organization';
  end if;

  return new;
end
$function$;


ALTER FUNCTION vortex_file.enforce_file_application_root() OWNER TO postgres;

