--
-- Name: record_file_download_grant(uuid, uuid, uuid, uuid, uuid, jsonb, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: vortex_file; Owner: vortex_file_owner
--

create or replace function vortex_file.record_file_download_grant(
  p_one_time_id uuid,
  p_file_id uuid,
  p_owner_record_type_id uuid,
  p_owner_record_id uuid,
  p_owner_field_id uuid,
  p_actor jsonb,
  p_purpose text,
  p_correlation_id uuid,
  p_expires_at timestamptz
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_context.validated_service_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  request_organization_id uuid := (established ->> 'organizationId')::uuid;
  stored vortex_file.file_records%rowtype;
begin
  if request_actor is null
    or p_actor is distinct from request_actor then
    raise exception using errcode = '42501', message = 'File read scope is unavailable';
  end if;

  if p_one_time_id is null
    or p_file_id is null
    or p_owner_record_type_id is null
    or p_owner_record_id is null
    or p_owner_field_id is null
    or p_correlation_id is null
    or p_purpose is null or p_purpose not in ('download', 'preview')
    or p_expires_at is null
    or p_expires_at <= evaluated_at
    or p_expires_at > evaluated_at + interval '65 seconds' then
    raise exception using errcode = '22023', message = 'File read grant is invalid';
  end if;

  select candidate.* into stored
  from vortex_file.file_records as candidate
  where candidate.file_id = p_file_id
    and candidate.organization_id = request_organization_id;
  if not found
    or stored.lifecycle_state <> 'active'
    or stored.scanner_result <> 'clean'
    or stored.owner_record_type_id is distinct from p_owner_record_type_id
    or stored.owner_record_id is distinct from p_owner_record_id
    or stored.owner_field_id is distinct from p_owner_field_id then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  delete from vortex_file.download_grants as expired
  where expired.ctid in (
    select candidate.ctid
    from vortex_file.download_grants as candidate
    where candidate.organization_id = request_organization_id
      and candidate.expires_at < evaluated_at - interval '1 hour'
    order by candidate.expires_at
    limit 100
  );

  insert into vortex_file.download_grants (
    one_time_id, file_id, organization_id,
    owner_record_type_id, owner_record_id, owner_field_id,
    actor, purpose, correlation_id, expires_at, created_at
  ) values (
    p_one_time_id, p_file_id, request_organization_id,
    p_owner_record_type_id, p_owner_record_id, p_owner_field_id,
    request_actor, p_purpose, p_correlation_id, p_expires_at, evaluated_at
  );

  return pg_catalog.jsonb_build_object('outcome', 'recorded');
end
$function$;


ALTER FUNCTION vortex_file.record_file_download_grant(p_one_time_id uuid, p_file_id uuid, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_actor jsonb, p_purpose text, p_correlation_id uuid, p_expires_at timestamp with time zone) OWNER TO vortex_file_owner;

--
-- Name: FUNCTION record_file_download_grant(p_one_time_id uuid, p_file_id uuid, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_actor jsonb, p_purpose text, p_correlation_id uuid, p_expires_at timestamp with time zone); Type: COMMENT; Schema: vortex_file; Owner: vortex_file_owner
--

COMMENT ON FUNCTION vortex_file.record_file_download_grant(p_one_time_id uuid, p_file_id uuid, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_actor jsonb, p_purpose text, p_correlation_id uuid, p_expires_at timestamp with time zone) IS 'Records one unclaimed short-lived read grant for the request actor on an active clean attached file.';


--
-- Name: record_file_upload_outcome(uuid, bigint, text, bigint, text, text, text, text); Type: FUNCTION; Schema: vortex_file; Owner: vortex_file_owner
--

create or replace function vortex_file.record_file_upload_outcome(
  p_file_id uuid,
  p_expected_revision bigint,
  p_detected_media_type text,
  p_size_bytes bigint,
  p_checksum text,
  p_scanner_name text,
  p_scanner_version text,
  p_scanner_result text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_file.upload_validated_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  reservation vortex_file.upload_reservations%rowtype;
  uploaded vortex_file.file_records%rowtype;
begin
  select stored.* into reservation
  from vortex_file.upload_reservations as stored
  where stored.file_id = p_file_id
    and stored.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found then
    return vortex_file.upload_refusal('file_not_found');
  end if;
  if request_actor is null or reservation.uploaded_by is distinct from request_actor then
    return vortex_file.upload_refusal('caller_not_authorized');
  end if;

  select stored.* into strict uploaded
  from vortex_file.file_records as stored
  where stored.file_id = p_file_id
  for update;
  if uploaded.lifecycle_state <> 'pending' then
    return vortex_file.upload_refusal('invalid_lifecycle_state');
  end if;
  if reservation.upload_expires_at <= evaluated_at then
    return vortex_file.upload_refusal('upload_expired');
  end if;
  if reservation.revision is distinct from p_expected_revision then
    return vortex_file.upload_refusal('revision_conflict');
  end if;

  -- Bytes beyond the admitted reservation are never accepted as clean.
  if p_scanner_result is null
    or p_scanner_result not in ('clean', 'quarantined', 'refused')
    or p_size_bytes is null or p_size_bytes < 0
    or (p_scanner_result = 'clean' and p_size_bytes > reservation.maximum_bytes)
    or p_scanner_name is null
    or p_scanner_version is null then
    raise exception using errcode = '22023', message = 'File upload outcome is invalid';
  end if;

  update vortex_file.file_records
  set
    detected_media_type = p_detected_media_type,
    size_bytes = p_size_bytes,
    checksum = p_checksum,
    scanner_name = p_scanner_name,
    scanner_version = p_scanner_version,
    scanner_result = p_scanner_result,
    lifecycle_state = case when p_scanner_result = 'clean' then 'scanning' else 'quarantined' end
  where file_id = p_file_id
  returning * into uploaded;

  update vortex_file.upload_grants
  set superseded_at = evaluated_at
  where file_id = p_file_id
    and superseded_at is null;

  update vortex_file.upload_reservations
  set revision = revision + 1, updated_at = evaluated_at
  where file_id = p_file_id;

  return pg_catalog.jsonb_build_object(
    'outcome', 'recorded',
    'fileRecord', vortex_file.upload_file_record(uploaded)
  );
end
$function$;


