--

COMMENT ON FUNCTION vortex_file.record_file_upload_outcome(p_file_id uuid, p_expected_revision bigint, p_detected_media_type text, p_size_bytes bigint, p_checksum text, p_scanner_name text, p_scanner_version text, p_scanner_result text) IS 'Records trusted inspection and the safety result of a pending upload, leaving it scanning or quarantined.';


--
-- Name: renew_file_upload(uuid, bigint, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: vortex_file; Owner: vortex_file_owner
--

create or replace function vortex_file.renew_file_upload(
  p_file_id uuid,
  p_expected_revision bigint,
  p_previous_one_time_id uuid,
  p_new_one_time_id uuid,
  p_policy_fingerprint text,
  p_grant_expires_at timestamptz
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_file.upload_validated_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  reservation vortex_file.upload_reservations%rowtype;
  uploaded vortex_file.file_records%rowtype;
  current_grant_id uuid;
begin
  select stored.* into reservation
  from vortex_file.upload_reservations as stored
  where stored.file_id = p_file_id
    and stored.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found then
    return vortex_file.upload_refusal('file_not_found');
  end if;
  if request_actor is null or reservation.uploaded_by is distinct from request_actor then
    return vortex_file.upload_refusal('caller_not_authorized');
  end if;

  select stored.* into strict uploaded
  from vortex_file.file_records as stored
  where stored.file_id = p_file_id;
  if uploaded.lifecycle_state <> 'pending' then
    return vortex_file.upload_refusal('invalid_lifecycle_state');
  end if;
  if reservation.upload_expires_at <= evaluated_at then
    return vortex_file.upload_refusal('upload_expired');
  end if;

  select current_grant.one_time_id into current_grant_id
  from vortex_file.upload_grants as current_grant
  where current_grant.file_id = p_file_id
    and current_grant.superseded_at is null
  for update;
  if reservation.revision is distinct from p_expected_revision
    or current_grant_id is distinct from p_previous_one_time_id then
    return vortex_file.upload_refusal('grant_mismatch');
  end if;

  if p_new_one_time_id is null
    or p_policy_fingerprint is null
    or p_grant_expires_at is null
    or p_grant_expires_at <= evaluated_at
    or p_grant_expires_at > evaluated_at + interval '65 seconds'
    or p_grant_expires_at > reservation.upload_expires_at then
    raise exception using errcode = '22023', message = 'File upload renewal is invalid';
  end if;

  update vortex_file.upload_grants
  set superseded_at = evaluated_at
  where one_time_id = p_previous_one_time_id;

  insert into vortex_file.upload_grants (
    one_time_id, file_id, organization_id, actor, maximum_bytes,
    policy_fingerprint, expires_at, created_at
  ) values (
    p_new_one_time_id, p_file_id, reservation.organization_id, reservation.uploaded_by,
    reservation.maximum_bytes, p_policy_fingerprint, p_grant_expires_at, evaluated_at
  );

  update vortex_file.upload_reservations
  set revision = revision + 1, updated_at = evaluated_at
  where file_id = p_file_id;

  return pg_catalog.jsonb_build_object('outcome', 'renewed');
end
$function$;


ALTER FUNCTION vortex_file.renew_file_upload(p_file_id uuid, p_expected_revision bigint, p_previous_one_time_id uuid, p_new_one_time_id uuid, p_policy_fingerprint text, p_grant_expires_at timestamp with time zone) OWNER TO vortex_file_owner;

--
-- Name: FUNCTION renew_file_upload(p_file_id uuid, p_expected_revision bigint, p_previous_one_time_id uuid, p_new_one_time_id uuid, p_policy_fingerprint text, p_grant_expires_at timestamp with time zone); Type: COMMENT; Schema: vortex_file; Owner: vortex_file_owner
--

COMMENT ON FUNCTION vortex_file.renew_file_upload(p_file_id uuid, p_expected_revision bigint, p_previous_one_time_id uuid, p_new_one_time_id uuid, p_policy_fingerprint text, p_grant_expires_at timestamp with time zone) IS 'Supersedes the current grant of a pending upload with a new short-lived grant for its uploader.';


--
-- Name: reserve_file_upload(uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, jsonb, bigint, integer, integer, uuid, uuid, uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

create or replace function vortex_file.reserve_file_upload(
  p_file_id uuid,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_owner_record_type_id uuid,
  p_owner_record_id uuid,
  p_owner_field_id uuid,
  p_original_safe_display_name text,
  p_extension text,
  p_storage_key text,
  p_uploaded_by jsonb,
  p_maximum_bytes bigint,
  p_max_files integer,
  p_existing_attachment_count integer,
  p_replacing_file_id uuid,
  p_capability_reservation_id uuid,
  p_one_time_id uuid,
  p_policy_fingerprint text,
  p_grant_expires_at timestamptz,
  p_upload_expires_at timestamptz
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_file.upload_validated_context();
  request_actor jsonb := vortex_file.upload_request_actor(established);
  in_flight_count bigint;
  existing_count bigint;
  reserved vortex_file.file_records%rowtype;
begin
  if request_actor is null
    or p_organization_id is distinct from (established ->> 'organizationId')::uuid
    or p_application_root_id is distinct from (established ->> 'applicationRootId')::uuid
    or p_uploaded_by is distinct from request_actor then
    raise exception using errcode = '42501', message = 'File upload scope is unavailable';
  end if;

  if p_file_id is null
    or p_owner_record_type_id is null
    or p_owner_record_id is null
    or p_owner_field_id is null
    or p_maximum_bytes is null or p_maximum_bytes < 1
    or p_maximum_bytes > vortex_file.upload_maximum_bytes_limit()
    or p_max_files is null or p_max_files < 1
    or p_existing_attachment_count is null or p_existing_attachment_count < 0
    or p_capability_reservation_id is null
    or p_one_time_id is null
    or p_policy_fingerprint is null
    or p_grant_expires_at is null
    or p_grant_expires_at <= evaluated_at
    or p_grant_expires_at > evaluated_at + interval '65 seconds'
    or p_upload_expires_at is null
    or p_upload_expires_at < p_grant_expires_at
    or p_upload_expires_at > evaluated_at + interval '24 hours 5 minutes' then
    raise exception using errcode = '22023', message = 'File upload reservation is invalid';
  end if;

  -- Admissions to one attachment field are serialised so concurrent uploads
  -- cannot together exceed its file count.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f',
      'vortex_file.upload_field', p_organization_id::text,
      p_owner_record_type_id::text, p_owner_record_id::text, p_owner_field_id::text), 652)
  );

  perform 1
  from vortex_access.capability_reservations as funding
  where funding.reservation_id = p_capability_reservation_id
    and funding.tenant_id = (established ->> 'tenantId')::uuid
    and funding.request_organization_id = p_organization_id
    and funding.correlation_id = (established ->> 'correlationId')::uuid
    and funding.state = 'active'
    and funding.expires_at > evaluated_at
    and funding.reserved_quantity - funding.consumed_quantity - funding.released_quantity > 0
  for update;
  if not found then
    if not exists (
      select 1 from vortex_file.upload_reservations as retried
      where retried.capability_reservation_id = p_capability_reservation_id
        and retried.file_id = p_file_id
    ) then
      perform vortex_file.append_file_activity_internal(
        'file_upload_refused', p_organization_id);
    end if;
    return vortex_file.upload_refusal('capability_refused');
  end if;

  if exists (
    select 1 from vortex_file.upload_reservations as reservation
    where reservation.capability_reservation_id = p_capability_reservation_id
  ) then
    if not exists (
      select 1 from vortex_file.upload_reservations as retried
      where retried.capability_reservation_id = p_capability_reservation_id
        and retried.file_id = p_file_id
    ) then
      perform vortex_file.append_file_activity_internal(
        'file_upload_refused', p_organization_id);
    end if;
    return vortex_file.upload_refusal('capability_refused');
  end if;

  select pg_catalog.count(*) into existing_count
  from vortex_file.file_records as attached
  where attached.organization_id = p_organization_id
    and attached.owner_record_type_id = p_owner_record_type_id
    and attached.owner_record_id = p_owner_record_id
    and attached.owner_field_id = p_owner_field_id
    and attached.lifecycle_state = 'active';

  if p_replacing_file_id is not null and (
    existing_count < 1
    or not exists (
      select 1 from vortex_file.file_records as replaced
      where replaced.file_id = p_replacing_file_id
        and replaced.organization_id = p_organization_id
        and replaced.owner_record_type_id = p_owner_record_type_id
        and replaced.owner_record_id = p_owner_record_id
        and replaced.owner_field_id = p_owner_field_id
        and replaced.lifecycle_state = 'active'
    )
  ) then
    return vortex_file.upload_refusal('replacement_file_not_found');
  end if;

  select pg_catalog.count(*) into in_flight_count
  from vortex_file.upload_reservations as reservation
  join vortex_file.file_records as uploaded
    on uploaded.file_id = reservation.file_id
  where reservation.organization_id = p_organization_id
    and reservation.owner_record_type_id = p_owner_record_type_id
    and reservation.owner_record_id = p_owner_record_id
    and reservation.owner_field_id = p_owner_field_id
    and reservation.upload_expires_at > evaluated_at
    and uploaded.lifecycle_state in ('pending', 'uploaded', 'scanning');

  if existing_count
    - (case when p_replacing_file_id is null then 0 else 1 end)
    + in_flight_count >= p_max_files then
    return vortex_file.upload_refusal('field_capacity_exceeded');
  end if;

  insert into vortex_file.file_records (
    file_id, organization_id, application_root_id,
    owner_record_type_id, owner_record_id, owner_field_id,
    owning_attachment_references, lifecycle_state, original_safe_display_name,
    detected_media_type, extension, size_bytes, checksum,
    storage_key, bucket_id, scanner_name, scanner_version, scanner_result,
    preview_references, uploaded_by, legal_hold, created_at
  ) values (
    p_file_id, p_organization_id, p_application_root_id,
    p_owner_record_type_id, p_owner_record_id, p_owner_field_id,
    '{}'::uuid[], 'pending', p_original_safe_display_name,
    'application/octet-stream', p_extension, 0, 'sha256:' || pg_catalog.repeat('0', 64),
    p_storage_key, 'private_files', 'vortex_file_preflight', '1', 'pending',
    '[]'::jsonb, request_actor, false, evaluated_at
  )
  returning * into reserved;

  insert into vortex_file.upload_reservations (
    file_id, organization_id, owner_record_type_id, owner_record_id, owner_field_id,
    uploaded_by, maximum_bytes, capability_reservation_id, replacing_file_id,
    correlation_id, upload_expires_at, revision, created_at, updated_at, max_files
  ) values (
    p_file_id, p_organization_id, p_owner_record_type_id, p_owner_record_id, p_owner_field_id,
    request_actor, p_maximum_bytes, p_capability_reservation_id, p_replacing_file_id,
    (established ->> 'correlationId')::uuid, p_upload_expires_at, 1, evaluated_at, evaluated_at,
    p_max_files
  );

  insert into vortex_file.upload_grants (
    one_time_id, file_id, organization_id, actor, maximum_bytes,
    policy_fingerprint, expires_at, created_at
  ) values (
    p_one_time_id, p_file_id, p_organization_id, request_actor, p_maximum_bytes,
    p_policy_fingerprint, p_grant_expires_at, evaluated_at
  );

  perform vortex_file.append_file_activity_internal(
    'file_upload_admitted', p_file_id);

  return pg_catalog.jsonb_build_object(
    'outcome', 'reserved',
    'fileRecord', vortex_file.upload_file_record(reserved)
  );
end
$function$;


ALTER FUNCTION vortex_file.reserve_file_upload(p_file_id uuid, p_organization_id uuid, p_application_root_id uuid, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_original_safe_display_name text, p_extension text, p_storage_key text, p_uploaded_by jsonb, p_maximum_bytes bigint, p_max_files integer, p_existing_attachment_count integer, p_replacing_file_id uuid, p_capability_reservation_id uuid, p_one_time_id uuid, p_policy_fingerprint text, p_grant_expires_at timestamp with time zone, p_upload_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION reserve_file_upload(p_file_id uuid, p_organization_id uuid, p_application_root_id uuid, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_original_safe_display_name text, p_extension text, p_storage_key text, p_uploaded_by jsonb, p_maximum_bytes bigint, p_max_files integer, p_existing_attachment_count integer, p_replacing_file_id uuid, p_capability_reservation_id uuid, p_one_time_id uuid, p_policy_fingerprint text, p_grant_expires_at timestamp with time zone, p_upload_expires_at timestamp with time zone); Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON FUNCTION vortex_file.reserve_file_upload(p_file_id uuid, p_organization_id uuid, p_application_root_id uuid, p_owner_record_type_id uuid, p_owner_record_id uuid, p_owner_field_id uuid, p_original_safe_display_name text, p_extension text, p_storage_key text, p_uploaded_by jsonb, p_maximum_bytes bigint, p_max_files integer, p_existing_attachment_count integer, p_replacing_file_id uuid, p_capability_reservation_id uuid, p_one_time_id uuid, p_policy_fingerprint text, p_grant_expires_at timestamp with time zone, p_upload_expires_at timestamp with time zone) IS 'Reserves a pending file, its capacity binding and its first grant under a lock on the owning attachment field.';


--
-- Name: file_records; Type: TABLE; Schema: vortex_file; Owner: postgres
--

CREATE TABLE vortex_file.file_records (
    file_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    application_root_id uuid,
    owner_record_type_id uuid,
    owner_record_id uuid,
    owner_field_id uuid,
    owning_attachment_references uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    lifecycle_state text NOT NULL,
    original_safe_display_name text NOT NULL,
    detected_media_type text NOT NULL,
    extension text NOT NULL,
    size_bytes bigint NOT NULL,
    checksum text NOT NULL,
    storage_key text NOT NULL,
    bucket_id text DEFAULT 'private_files'::text NOT NULL,
    scanner_name text NOT NULL,
    scanner_version text NOT NULL,
    scanner_result text NOT NULL,
    preview_references jsonb DEFAULT '[]'::jsonb NOT NULL,
    uploaded_by jsonb NOT NULL,
    legal_hold boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    activated_at timestamp with time zone,
    deleted_at timestamp with time zone,
    removal_due_at timestamp with time zone,
    metadata_revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT file_records_active_shape CHECK (((lifecycle_state <> 'active'::text) OR ((scanner_result = 'clean'::text) AND (activated_at IS NOT NULL) AND (deleted_at IS NULL)))),
    CONSTRAINT file_records_application_non_nil CHECK ((application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT file_records_bucket_private CHECK ((bucket_id = 'private_files'::text)),
    CONSTRAINT file_records_checksum_valid CHECK ((checksum ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT file_records_deleted_after_creation CHECK (((deleted_at IS NULL) OR (deleted_at >= created_at))),
    CONSTRAINT file_records_display_name_valid CHECK ((((char_length(original_safe_display_name) >= 1) AND (char_length(original_safe_display_name) <= 255)) AND (original_safe_display_name !~ '[\r\n\t]'::text))),
    CONSTRAINT file_records_extension_valid CHECK ((extension ~ '^\.[a-z0-9]+$'::text)),
    CONSTRAINT file_records_file_id_non_nil CHECK ((file_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT file_records_lifecycle_state_valid CHECK ((lifecycle_state = ANY (ARRAY['pending'::text, 'uploaded'::text, 'scanning'::text, 'active'::text, 'quarantined'::text, 'abandoned'::text, 'soft_deleted'::text, 'removed'::text]))),
    CONSTRAINT file_records_media_type_valid CHECK (((char_length(detected_media_type) >= 1) AND (char_length(detected_media_type) <= 200))),
    CONSTRAINT file_records_metadata_revision_safe_integer CHECK (((metadata_revision >= 1) AND (metadata_revision <= '9007199254740991'::bigint))),
    CONSTRAINT file_records_organization_non_nil CHECK ((organization_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT file_records_owner_complete CHECK ((num_nonnulls(owner_record_type_id, owner_record_id, owner_field_id) = ANY (ARRAY[0, 3]))),
    CONSTRAINT file_records_quarantined_shape CHECK (((lifecycle_state <> 'quarantined'::text) OR (scanner_result = ANY (ARRAY['quarantined'::text, 'refused'::text])))),
    CONSTRAINT file_records_scanner_result_valid CHECK ((scanner_result = ANY (ARRAY['pending'::text, 'clean'::text, 'quarantined'::text, 'refused'::text]))),
    CONSTRAINT file_records_size_bytes_non_negative CHECK ((size_bytes >= 0)),
    CONSTRAINT file_records_soft_deleted_shape CHECK (((lifecycle_state <> 'soft_deleted'::text) OR (deleted_at IS NOT NULL))),
    CONSTRAINT file_records_storage_key_valid CHECK (((storage_key ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f]{32}$'::text) AND starts_with(storage_key, ((((organization_id)::text || '/'::text) || (file_id)::text) || '/'::text)))),
    CONSTRAINT file_records_uploaded_by_actor CHECK (((jsonb_typeof(uploaded_by) = 'object'::text) AND ((((uploaded_by ->> 'kind'::text) = 'human'::text) AND (uploaded_by ?& ARRAY['kind'::text, 'organizationAccountId'::text, 'identityId'::text]) AND (NOT (uploaded_by ? 'systemActorId'::text)) AND vortex_context.is_non_nil_uuid((uploaded_by ->> 'organizationAccountId'::text)) AND vortex_context.is_non_nil_uuid((uploaded_by ->> 'identityId'::text))) OR (((uploaded_by ->> 'kind'::text) = 'system'::text) AND (uploaded_by ?& ARRAY['kind'::text, 'systemActorId'::text]) AND (NOT (uploaded_by ?| ARRAY['organizationAccountId'::text, 'identityId'::text])) AND vortex_context.is_non_nil_uuid((uploaded_by ->> 'systemActorId'::text))))))
);

ALTER TABLE ONLY vortex_file.file_records FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_file.file_records OWNER TO postgres;

--
-- Name: TABLE file_records; Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON TABLE vortex_file.file_records IS 'One private organisation-owned file: owning application, record type, record and attachment field, safe display name, verified media type, size and checksum, verified human-or-system uploader, private bucket and organisation-scoped unguessable object path.';


--
-- Name: COLUMN file_records.metadata_revision; Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON COLUMN vortex_file.file_records.metadata_revision IS 'Monotonic File metadata revision, independent of upload reservation revisions.';


--
-- Name: upload_file_record(vortex_file.file_records); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

create or replace function vortex_file.upload_file_record(p_file vortex_file.file_records)
returns jsonb
language sql
stable
set search_path = ''
as $function$
  select pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'fileId', p_file.file_id,
    'organizationId', p_file.organization_id,
    'applicationRootId', p_file.application_root_id,
    'lifecycleState', p_file.lifecycle_state,
    'originalSafeDisplayName', p_file.original_safe_display_name,
    'detectedMediaType', p_file.detected_media_type,
    'extension', p_file.extension,
    'sizeBytes', p_file.size_bytes,
    'checksum', p_file.checksum,
    'storageKey', p_file.storage_key,
    'bucketId', p_file.bucket_id,
    'scannerName', p_file.scanner_name,
    'scannerVersion', p_file.scanner_version,
    'scannerResult', p_file.scanner_result,
    'previewReferences', p_file.preview_references,
    'uploadedBy', p_file.uploaded_by,
    'createdAt', vortex_context.format_timestamp_utc(p_file.created_at),
    'activatedAt', vortex_context.format_timestamp_utc(p_file.activated_at),
    'deletedAt', vortex_context.format_timestamp_utc(p_file.deleted_at),
    'removalDueAt', vortex_context.format_timestamp_utc(p_file.removal_due_at),
    'owningAttachmentReferences', pg_catalog.to_jsonb(p_file.owning_attachment_references),
    'ownerRecordTypeId', p_file.owner_record_type_id,
    'ownerRecordId', p_file.owner_record_id,
    'ownerFieldId', p_file.owner_field_id,
    'legalHold', pg_catalog.jsonb_build_object('isHeld', p_file.legal_hold)
  ))
$function$;


ALTER FUNCTION vortex_file.upload_file_record(p_file vortex_file.file_records) OWNER TO postgres;

--
-- Name: FUNCTION upload_file_record(p_file vortex_file.file_records); Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON FUNCTION vortex_file.upload_file_record(p_file vortex_file.file_records) IS 'Returns the canonical FileRecord projection with UTC timestamp values.';


--
-- Name: upload_maximum_bytes_limit(); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

CREATE FUNCTION vortex_file.upload_maximum_bytes_limit() RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 5000::bigint * 1024 * 1024
$$;


ALTER FUNCTION vortex_file.upload_maximum_bytes_limit() OWNER TO postgres;

--
-- Name: FUNCTION upload_maximum_bytes_limit(); Type: COMMENT; Schema: vortex_file; Owner: postgres
--

COMMENT ON FUNCTION vortex_file.upload_maximum_bytes_limit() IS 'The platform ceiling for one uploaded file, matching the 5000 MB field maximum.';


--
-- Name: upload_refusal(text); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

CREATE FUNCTION vortex_file.upload_refusal(p_reason text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object('outcome', 'refused', 'reason', p_reason)
$$;


ALTER FUNCTION vortex_file.upload_refusal(p_reason text) OWNER TO postgres;

--
-- Name: upload_request_actor(jsonb); Type: FUNCTION; Schema: vortex_file; Owner: postgres
--

CREATE FUNCTION vortex_file.upload_request_actor(p_context jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_context ->> 'callerKind'
    when 'human' then pg_catalog.jsonb_build_object(
      'kind', 'human',
      'organizationAccountId', p_context ->> 'organizationAccountId',
      'identityId', p_context ->> 'identityId'
    )
    when 'system' then pg_catalog.jsonb_build_object(
      'kind', 'system',
      'systemActorId', p_context ->> 'systemActorId'
    )
  end
$$;


