--

COMMENT ON FUNCTION vortex_identity.assert_organization_runtime_settings_values(p_language text, p_time_zone text, p_currency text, p_date_format text, p_number_format text) IS 'Private boundary validation for organisation runtime settings; currency and display-format membership comes from the seeded validation reference lists.';


--
-- Name: begin_identity_disablement(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

CREATE FUNCTION vortex_identity.begin_identity_disablement(p_actor_identity_id uuid, p_subject_identity_id uuid, p_command_id uuid, p_command_fingerprint text, p_correlation_id uuid) RETURNS TABLE(outcome text, sessions_revoked integer, correlation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  operation_at timestamptz := pg_catalog.clock_timestamp();
  existing vortex_identity.identity_disablement_commands%rowtype;
begin
  if p_actor_identity_id is null
    or p_subject_identity_id is null
    or p_command_id is null
    or p_correlation_id is null
    or p_command_fingerprint is null
    or p_actor_identity_id = p_subject_identity_id
    or not vortex_context.is_non_nil_uuid(p_actor_identity_id::text)
    or not vortex_context.is_non_nil_uuid(p_subject_identity_id::text)
    or not vortex_context.is_non_nil_uuid(p_command_id::text)
    or not vortex_context.is_non_nil_uuid(p_correlation_id::text)
    or p_command_fingerprint !~ '^sha256:[0-9a-f]{64}$'
  then
    raise exception 'invalid identity disablement command' using errcode = '22023';
  end if;

  insert into vortex_identity.identity_disablement_commands (
    command_id, actor_identity_id, subject_identity_id, command_fingerprint,
    correlation_id, outcome, requested_at
  ) values (
    p_command_id, p_actor_identity_id, p_subject_identity_id, p_command_fingerprint,
    p_correlation_id, 'started', operation_at
  )
  on conflict (command_id) do nothing;

  if found then
    insert into vortex_identity.identity_disablement_events (
      command_id, actor_identity_id, subject_identity_id, correlation_id, event,
      recorded_at
    ) values (
      p_command_id, p_actor_identity_id, p_subject_identity_id, p_correlation_id,
      'started', operation_at
    );
    return query select 'started'::text, null::integer, p_correlation_id;
    return;
  end if;

  select * into strict existing
  from vortex_identity.identity_disablement_commands as recorded
  where recorded.command_id = p_command_id
  for update;

  if existing.command_fingerprint is distinct from p_command_fingerprint
    or existing.actor_identity_id is distinct from p_actor_identity_id
    or existing.subject_identity_id is distinct from p_subject_identity_id
  then
    -- The attempted (not the recorded) actor and subject are attributed.
    insert into vortex_identity.identity_disablement_events (
      command_id, actor_identity_id, subject_identity_id, correlation_id, event,
      recorded_at
    ) values (
      p_command_id, p_actor_identity_id, p_subject_identity_id, p_correlation_id,
      'conflict', operation_at
    );
    return query select 'conflict'::text, null::integer, existing.correlation_id;
    return;
  end if;

  if existing.outcome = 'disabled' then
    insert into vortex_identity.identity_disablement_events (
      command_id, actor_identity_id, subject_identity_id, correlation_id, event,
      recorded_at
    ) values (
      p_command_id, p_actor_identity_id, p_subject_identity_id, p_correlation_id,
      'replayed', operation_at
    );
    return query select 'replayed'::text, existing.sessions_revoked, existing.correlation_id;
    return;
  end if;

  update vortex_identity.identity_disablement_commands as recorded
  set outcome = 'started',
      completed_at = null,
      sessions_revoked = null,
      attempt_count = recorded.attempt_count + 1
  where recorded.command_id = p_command_id;

  insert into vortex_identity.identity_disablement_events (
    command_id, actor_identity_id, subject_identity_id, correlation_id, event,
    recorded_at
  ) values (
    p_command_id, p_actor_identity_id, p_subject_identity_id, p_correlation_id,
    'started', operation_at
  );
  return query select 'started'::text, null::integer, existing.correlation_id;
end
$_$;


ALTER FUNCTION vortex_identity.begin_identity_disablement(p_actor_identity_id uuid, p_subject_identity_id uuid, p_command_id uuid, p_command_fingerprint text, p_correlation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION begin_identity_disablement(p_actor_identity_id uuid, p_subject_identity_id uuid, p_command_id uuid, p_command_fingerprint text, p_correlation_id uuid); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.begin_identity_disablement(p_actor_identity_id uuid, p_subject_identity_id uuid, p_command_id uuid, p_command_fingerprint text, p_correlation_id uuid) IS 'Server-only Identity Authority adapter step: records or re-opens one identity disablement command and replays a completed exact retry.';


--
-- Name: begin_organization_account_closing(uuid, bigint); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.begin_organization_account_closing(
  p_organization_account_id uuid,
  p_expected_revision bigint
)
returns table (
  organization_account_id uuid,
  organization_id uuid,
  state text,
  closing_at timestamptz,
  state_change_correlation_id uuid,
  revision bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked jsonb;
begin
  checked := vortex_identity.validated_human_account_context();

  return query
  update vortex_identity.organization_accounts as account
  set state = 'closing',
      closing_at = greatest(
        pg_catalog.statement_timestamp(), account.changed_at, account.state_changed_at
      ),
      activated_at = account.activated_at,
      changed_at = greatest(
        pg_catalog.statement_timestamp(), account.changed_at, account.state_changed_at
      ),
      state_changed_at = greatest(
        pg_catalog.statement_timestamp(), account.changed_at, account.state_changed_at
      ),
      state_changed_by = (checked ->> 'organizationAccountId')::uuid,
      state_change_correlation_id = (checked ->> 'correlationId')::uuid,
      revision = account.revision + 1
  where account.organization_account_id = p_organization_account_id
    and account.organization_id = (checked ->> 'organizationId')::uuid
    and account.revision = p_expected_revision
    and account.state in ('active', 'suspended', 'closed')
  returning account.organization_account_id, account.organization_id, account.state,
    account.closing_at, account.state_change_correlation_id, account.revision;

  if not found then
    raise exception using errcode = '40001', message = 'Organisation account closing is stale or unavailable';
  end if;
end
$function$;


ALTER FUNCTION vortex_identity.begin_organization_account_closing(p_organization_account_id uuid, p_expected_revision bigint) OWNER TO vortex_identity_owner;

