--
-- Name: initialize_organization_runtime_settings(uuid, text, text, text, text, text); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.initialize_organization_runtime_settings(
  p_organization_id uuid,
  p_language text,
  p_time_zone text,
  p_currency text,
  p_date_format text,
  p_number_format text
)
returns table (
  organization_id uuid,
  language text,
  time_zone text,
  currency text,
  date_format text,
  number_format text,
  revision bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  existing vortex_identity.organization_runtime_settings%rowtype;
  operation_at timestamptz := pg_catalog.statement_timestamp();
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization runtime settings initialization is invalid';
  end if;
  perform vortex_identity.assert_organization_runtime_settings_values(
    p_language, p_time_zone, p_currency, p_date_format, p_number_format
  );

  -- Serialize setup through the organisation itself.  That makes two
  -- simultaneous identical setup calls behave as retries rather than leaving
  -- one with a unique-constraint error, and it refuses an unknown organisation
  -- before any settings row can be created.
  perform 1
  from vortex_identity.organizations as organization
  where organization.organization_id = p_organization_id
  for update;
  if not found then
    raise exception using errcode = '22023',
      message = 'Organization runtime settings initialization is unavailable';
  end if;

  -- The organisation lock makes this read and the following insert one
  -- serializable setup decision for an organisation.
  select settings.* into existing
  from vortex_identity.organization_runtime_settings as settings
  where settings.organization_id = p_organization_id
  for update;

  if found then
    if existing.language is distinct from p_language
      or existing.time_zone is distinct from p_time_zone
      or existing.currency is distinct from p_currency
      or existing.date_format is distinct from p_date_format
      or existing.number_format is distinct from p_number_format then
      raise exception using errcode = '40001',
        message = 'Organization runtime settings are already initialized differently';
    end if;
    return query select existing.organization_id, existing.language, existing.time_zone,
      existing.currency, existing.date_format, existing.number_format, existing.revision;
    return;
  end if;

  insert into vortex_identity.organization_runtime_settings (
    organization_id, language, time_zone, currency, date_format, number_format,
    initialized_at, changed_at, revision
  ) values (
    p_organization_id, p_language, p_time_zone, p_currency, p_date_format,
    p_number_format, operation_at, operation_at, 1
  ) returning * into existing;

  return query select existing.organization_id, existing.language, existing.time_zone,
    existing.currency, existing.date_format, existing.number_format, existing.revision;
end
$function$;


ALTER FUNCTION vortex_identity.initialize_organization_runtime_settings(p_organization_id uuid, p_language text, p_time_zone text, p_currency text, p_date_format text, p_number_format text) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION initialize_organization_runtime_settings(p_organization_id uuid, p_language text, p_time_zone text, p_currency text, p_date_format text, p_number_format text); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.initialize_organization_runtime_settings(p_organization_id uuid, p_language text, p_time_zone text, p_currency text, p_date_format text, p_number_format text) IS 'Trusted explicit Identity setup for one organisation runtime-settings row; identical retries return the current existing row and conflicting retries refuse.';


--
-- Name: is_active_organization_account_reference_internal(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.is_active_organization_account_reference_internal(
  p_tenant_id uuid,
  p_organization_id uuid,
  p_organization_account_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select exists (
    select 1
    from vortex_identity.organization_accounts as account
    join vortex_identity.identity_projections as projection
      on projection.identity_id = account.identity_id
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where tenant.tenant_id = p_tenant_id
      and organization.organization_id = p_organization_id
      and account.organization_account_id = p_organization_account_id
      and projection.state = 'active'
      and account.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
  )
$function$;


ALTER FUNCTION vortex_identity.is_active_organization_account_reference_internal(p_tenant_id uuid, p_organization_id uuid, p_organization_account_id uuid) OWNER TO vortex_identity_owner;

--
-- Name: list_organization_account_choices_internal(uuid, uuid, text, integer, text, uuid); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.list_organization_account_choices_internal(
  p_tenant_id uuid,
  p_organization_id uuid,
  p_search text,
  p_page_size integer,
  p_after_sort_key text,
  p_after_organization_account_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  search_value text;
  result_value jsonb;
begin
  if p_tenant_id is null
    or p_organization_id is null
    or p_page_size is null
    or p_page_size not between 1 and 100
    or (p_search is not null and pg_catalog.char_length(p_search) not between 1 and 100)
    or (p_after_sort_key is null) <> (p_after_organization_account_id is null)
    or pg_catalog.char_length(p_after_sort_key) > 1000 then
    raise exception using errcode = '22023',
      message = 'Organisation account choice page input is invalid';
  end if;
  search_value := pg_catalog.lower(p_search);

  with candidates as (
    select account.organization_account_id,
      account.display_name,
      (coalesce(pg_catalog.lower(account.display_name), '') collate "C") as sort_key
    from vortex_identity.organization_accounts as account
    join vortex_identity.identity_projections as projection
      on projection.identity_id = account.identity_id
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where tenant.tenant_id = p_tenant_id
      and organization.organization_id = p_organization_id
      and account.state = 'active'
      and projection.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
      and (
        search_value is null
        or pg_catalog.strpos(pg_catalog.lower(account.display_name), search_value) > 0
      )
  ),
  page as (
    select candidate.organization_account_id, candidate.display_name, candidate.sort_key,
      pg_catalog.row_number() over (
        order by candidate.sort_key, candidate.organization_account_id
      ) as ordinal
    from candidates as candidate
    where p_after_sort_key is null
      or (candidate.sort_key, candidate.organization_account_id)
        > ((p_after_sort_key collate "C"), p_after_organization_account_id)
    order by candidate.sort_key, candidate.organization_account_id
    limit p_page_size + 1
  )
  select pg_catalog.jsonb_build_object(
    'accounts', coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'organizationAccountId', entry.organization_account_id,
          'displayName', entry.display_name
        )) order by entry.ordinal
      ) filter (where entry.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    'next', case
      when pg_catalog.count(*) > p_page_size then
        (pg_catalog.array_agg(
          pg_catalog.jsonb_build_object(
            'sortKey', entry.sort_key,
            'organizationAccountId', entry.organization_account_id
          ) order by entry.ordinal
        ) filter (where entry.ordinal <= p_page_size))[p_page_size]
      else null
    end
  )
  into result_value
  from page as entry;

  return result_value;
end
$function$;


ALTER FUNCTION vortex_identity.list_organization_account_choices_internal(p_tenant_id uuid, p_organization_id uuid, p_search text, p_page_size integer, p_after_sort_key text, p_after_organization_account_id uuid) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION list_organization_account_choices_internal(p_tenant_id uuid, p_organization_id uuid, p_search text, p_page_size integer, p_after_sort_key text, p_after_organization_account_id uuid); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.list_organization_account_choices_internal(p_tenant_id uuid, p_organization_id uuid, p_search text, p_page_size integer, p_after_sort_key text, p_after_organization_account_id uuid) IS 'Identity-owned bounded picker projection of active accounts in one active organisation: account id and display name only, keyset-paged, no counts.';


--
-- Name: list_organization_accounts(uuid); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.list_organization_accounts(p_identity_id uuid)
returns table (
  organization_account_id uuid,
  organization_id uuid,
  identity_id uuid,
  display_name text,
  state text,
  language text,
  time_zone text,
  invitation_id uuid,
  activated_at timestamptz,
  suspended_at timestamptz,
  closed_at timestamptz,
  changed_at timestamptz,
  state_changed_at timestamptz,
  state_changed_by uuid,
  state_change_correlation_id uuid,
  revision bigint
)
language sql
stable
security definer
set search_path = ''
as $function$
  select account.organization_account_id, account.organization_id, account.identity_id,
    account.display_name, account.state, account.language, account.time_zone,
    account.originating_invitation_id, account.activated_at, account.suspended_at,
    account.closed_at, account.changed_at, account.state_changed_at,
    account.state_changed_by, account.state_change_correlation_id, account.revision
  from vortex_identity.organization_accounts as account
  join vortex_identity.identity_projections as projection
    on projection.identity_id = account.identity_id
  join vortex_identity.organizations as organization
    on organization.organization_id = account.organization_id
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  where account.identity_id = p_identity_id
    and projection.state = 'active'
    and account.state = 'active'
    and organization.state = 'active'
    and tenant.state = 'active'
  order by account.organization_id, account.organization_account_id
$function$;


ALTER FUNCTION vortex_identity.list_organization_accounts(p_identity_id uuid) OWNER TO vortex_identity_owner;

--
-- Name: list_organization_accounts_for_administration_internal(uuid, uuid, integer); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.list_organization_accounts_for_administration_internal(
  p_organization_id uuid,
  p_after_organization_account_id uuid,
  p_page_size integer
)
returns table (
  accounts jsonb,
  next_after_organization_account_id uuid
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  account_items jsonb;
  page_account_ids uuid[];
  candidate_count integer;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_page_size is null
    or p_page_size not between 1 and 100
    or p_after_organization_account_id =
      '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Organization account administration page input is invalid';
  end if;

  with candidates as (
    select account.organization_account_id, account.display_name,
      account.state, account.language, account.time_zone, account.revision,
      pg_catalog.row_number() over (
        order by account.organization_account_id
      ) as ordinal
    from vortex_identity.organization_accounts as account
    where account.organization_id = p_organization_id
      and (
        p_after_organization_account_id is null
        or account.organization_account_id > p_after_organization_account_id
      )
    order by account.organization_account_id
    limit p_page_size + 1
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'organizationAccountId', candidate.organization_account_id,
          'displayName', candidate.display_name,
          'state', candidate.state,
          'language', candidate.language,
          'timeZone', candidate.time_zone,
          'revision', candidate.revision
        )) order by candidate.organization_account_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.organization_account_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into account_items, page_account_ids, candidate_count
  from candidates as candidate;

  return query select account_items,
    case when candidate_count > p_page_size
      then page_account_ids[p_page_size] else null end;
end
$function$;


ALTER FUNCTION vortex_identity.list_organization_accounts_for_administration_internal(p_organization_id uuid, p_after_organization_account_id uuid, p_page_size integer) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION list_organization_accounts_for_administration_internal(p_organization_id uuid, p_after_organization_account_id uuid, p_page_size integer); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.list_organization_accounts_for_administration_internal(p_organization_id uuid, p_after_organization_account_id uuid, p_page_size integer) IS 'Identity-owned bounded organisation-scoped safe account administration projection.';


--
-- Name: list_organization_accounts_projection_internal(uuid, boolean); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.list_organization_accounts_projection_internal(
  p_organization_id uuid,
  p_active_members_only boolean
)
returns table (
  organization_account_id uuid,
  display_name text,
  account_state text,
  language text,
  time_zone text,
  revision bigint
)
language sql
stable
security definer
set search_path = ''
as $function$
  -- Two fixed visibility modes, chosen only by the Access-owned reader. The
  -- administration mode returns every account of the organisation. The member
  -- mode applies today's account-choice rule: only active accounts whose
  -- identity, organisation and tenant are active, and only the display name and
  -- state, exactly the facts any active member may already list.
  select account.organization_account_id, account.display_name, account.state,
    case when p_active_members_only then null else account.language end,
    case when p_active_members_only then null else account.time_zone end,
    account.revision
  from vortex_identity.organization_accounts as account
  join vortex_identity.identity_projections as projection
    on projection.identity_id = account.identity_id
  join vortex_identity.organizations as organization
    on organization.organization_id = account.organization_id
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  where account.organization_id = p_organization_id
    and p_organization_id is not null
    and p_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid
    and p_active_members_only is not null
    and (
      not p_active_members_only
      or (
        account.state = 'active'
        and projection.state = 'active'
        and organization.state = 'active'
        and tenant.state = 'active'
      )
    )
  order by account.organization_account_id
$function$;


ALTER FUNCTION vortex_identity.list_organization_accounts_projection_internal(p_organization_id uuid, p_active_members_only boolean) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION list_organization_accounts_projection_internal(p_organization_id uuid, p_active_members_only boolean); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.list_organization_accounts_projection_internal(p_organization_id uuid, p_active_members_only boolean) IS 'Identity-owned set-returning safe organisation-account projection bounded to the given organisation: every account in administration mode, or only active accounts with their display name and state in member mode; identity, originating invitation and state-change evidence are never exposed, and the already-decided request scope is the only visibility.';


