COMMENT ON FUNCTION vortex_identity.list_organization_invitations_for_administration_internal(p_organization_id uuid, p_after_invitation_id uuid, p_page_size integer) IS 'Identity-owned bounded organisation-scoped safe invitation projection without secret or fingerprint.';


--
-- Name: list_organization_invitations_projection_internal(uuid); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.list_organization_invitations_projection_internal(
  p_organization_id uuid
)
returns table (
  invitation_id uuid,
  invited_email text,
  invitation_state text,
  invited_at timestamptz,
  expires_at timestamptz,
  revision bigint
)
language sql
stable
security definer
set search_path = ''
as $function$
  select invitation.invitation_id, invitation.invited_email,
    case
      when invitation.accepted_at is not null then 'accepted'
      when invitation.revoked_at is not null then 'revoked'
      when invitation.expires_at <= pg_catalog.statement_timestamp() then 'expired'
      else 'pending'
    end,
    invitation.invited_at, invitation.expires_at, invitation.revision
  from vortex_identity.organization_invitations as invitation
  where invitation.organization_id = p_organization_id
    and p_organization_id is not null
    and p_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid
  order by invitation.invitation_id
$function$;


ALTER FUNCTION vortex_identity.list_organization_invitations_projection_internal(p_organization_id uuid) OWNER TO vortex_identity_owner;

