-- Name: FUNCTION provision_tenant(p_cluster_id uuid, p_operator_actor_id uuid, p_duplicate_key uuid, p_command_fingerprint text, p_tenant_short_name text, p_tenant_display_name text, p_organization_short_name text, p_organization_display_name text, p_tenant_steward_identity_id uuid, p_organization_steward_identity_id uuid, p_account_display_name text, p_account_language text, p_account_time_zone text, p_runtime_language text, p_runtime_time_zone text, p_runtime_currency text, p_runtime_date_format text, p_runtime_number_format text); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.provision_tenant(p_cluster_id uuid, p_operator_actor_id uuid, p_duplicate_key uuid, p_command_fingerprint text, p_tenant_short_name text, p_tenant_display_name text, p_organization_short_name text, p_organization_display_name text, p_tenant_steward_identity_id uuid, p_organization_steward_identity_id uuid, p_account_display_name text, p_account_language text, p_account_time_zone text, p_runtime_language text, p_runtime_time_zone text, p_runtime_currency text, p_runtime_date_format text, p_runtime_number_format text) IS 'Configured-system-only atomic tenant/root-organisation provisioning with separate explicit tenant and organisation steward nominations and an initial current owner Group membership for the organisation steward.';


--
-- Name: publish_identity_disablement(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.publish_identity_disablement(
  p_subject_identity_id uuid,
  p_actor_identity_id uuid,
  p_correlation_id uuid,
  p_published_at timestamptz
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_identity.projection:' || p_subject_identity_id::text, 0
    )
  );

  perform 1
  from vortex_identity.identity_projections as projection
  where projection.identity_id = p_subject_identity_id
  for update;

  update vortex_identity.identity_projections as projection
  set state = 'suspended',
    state_changed_at = greatest(p_published_at, projection.state_changed_at),
    state_changed_by = p_actor_identity_id,
    state_change_correlation_id = p_correlation_id,
    revision = projection.revision + 1
  where projection.identity_id = p_subject_identity_id
    and projection.state = 'active';
end
$function$;


ALTER FUNCTION vortex_identity.publish_identity_disablement(p_subject_identity_id uuid, p_actor_identity_id uuid, p_correlation_id uuid, p_published_at timestamp with time zone) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION publish_identity_disablement(p_subject_identity_id uuid, p_actor_identity_id uuid, p_correlation_id uuid, p_published_at timestamp with time zone); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.publish_identity_disablement(p_subject_identity_id uuid, p_actor_identity_id uuid, p_correlation_id uuid, p_published_at timestamp with time zone) IS 'Private step of complete_identity_disablement: suspends the subject''s existing cluster-local identity projection.';


