-- Name: FUNCTION require_current_tenant_capability(p_identity_id uuid, p_tenant_id uuid, p_capability_key text, p_evaluated_at timestamp with time zone); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.require_current_tenant_capability(p_identity_id uuid, p_tenant_id uuid, p_capability_key text, p_evaluated_at timestamp with time zone) IS 'Requires one current tenant capability, the default capability-limits read permission for an active tenant administrator, or the independent active Vortex super-administrator assignment.';


--
-- Name: require_identity_not_disabled(uuid); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

CREATE FUNCTION vortex_identity.require_identity_not_disabled(p_identity_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_identity_id is null
    or not vortex_context.is_non_nil_uuid(p_identity_id::text)
    or vortex_identity.identity_is_disabled(p_identity_id)
  then
    raise exception using errcode = '42501', message = 'Identity is unavailable';
  end if;
end
$$;


ALTER FUNCTION vortex_identity.require_identity_not_disabled(p_identity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION require_identity_not_disabled(p_identity_id uuid); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.require_identity_not_disabled(p_identity_id uuid) IS 'Runtime live check at named sensitive operations: refuses (42501) an identity whose disablement completed.';


--
-- Name: require_request_identity_not_disabled(); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

CREATE FUNCTION vortex_identity.require_request_identity_not_disabled() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  checked jsonb;
begin
  checked := vortex_context.current_context();
  if checked ->> 'callerKind' is null
    or checked ->> 'callerKind' not in ('human', 'federated')
    or not vortex_context.is_non_nil_uuid(checked ->> 'identityId')
  then
    raise exception using errcode = '42501', message = 'Identity is unavailable';
  end if;

  perform vortex_identity.require_identity_not_disabled(
    (checked ->> 'identityId')::uuid
  );
end
$$;


ALTER FUNCTION vortex_identity.require_request_identity_not_disabled() OWNER TO postgres;

--
-- Name: FUNCTION require_request_identity_not_disabled(); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.require_request_identity_not_disabled() IS 'Request live check: refuses (42501) unless the current context names a human or federated person whose disablement has not completed.';


--
-- Name: resolve_active_organization_account(uuid, uuid); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

create or replace function vortex_identity.resolve_active_organization_account(
  p_identity_id uuid,
  p_organization_id uuid
)
returns table (
  tenant_id uuid,
  organization_id uuid,
  organization_account_id uuid
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  resolved_tenant_id uuid;
  resolved_assignment_id uuid;
  resolved_account_id uuid;
  account_state text;
  evaluated_at timestamptz := pg_catalog.clock_timestamp();
  new_correlation_id uuid := pg_catalog.gen_random_uuid();
  inserted_account_id uuid;
begin
  if p_identity_id is null
    or not vortex_context.is_non_nil_uuid(p_identity_id::text)
    or p_organization_id is null
    or not vortex_context.is_non_nil_uuid(p_organization_id::text) then
    raise exception using errcode = '22023',
      message = 'Organisation selection is invalid';
  end if;

  select organization.tenant_id
  into resolved_tenant_id
  from vortex_identity.identity_projections as identity
  join vortex_identity.organizations as organization
    on organization.organization_id = p_organization_id
  join vortex_identity.tenants as tenant
    on tenant.tenant_id = organization.tenant_id
  where identity.identity_id = p_identity_id
    and identity.state = 'active'
    and organization.state = 'active'
    and tenant.state = 'active'
  for share of identity, organization, tenant;
  if not found then
    raise exception using errcode = '42501',
      message = 'Organisation selection is unavailable';
  end if;

  select account.organization_account_id, account.state
  into resolved_account_id, account_state
  from vortex_identity.organization_accounts as account
  where account.identity_id = p_identity_id
    and account.organization_id = p_organization_id
  for share;
  if found then
    if account_state = 'active' then
      return query select resolved_tenant_id, p_organization_id,
        resolved_account_id;
      return;
    end if;
    if account_state = 'suspended'
      and vortex_identity.resolve_active_vortex_super_administrator_assignment_internal(
        p_identity_id, evaluated_at
      ) is not null then
      raise exception using errcode = 'V3140',
        message = 'This super-administrator organisation account is suspended';
    end if;
    raise exception using errcode = '42501',
      message = 'Organisation selection is unavailable';
  end if;

  select assignment.assignment_id
  into resolved_assignment_id
  from vortex_identity.vortex_super_administrator_assignments as assignment
  where assignment.identity_id = p_identity_id
    and assignment.revoked_at is null
    and assignment.granted_at <= evaluated_at
  for share of assignment;
  if not found then
    raise exception using errcode = '42501',
      message = 'Organisation selection is unavailable';
  end if;

  insert into vortex_identity.organization_accounts (
    organization_account_id, organization_id, identity_id, display_name,
    state, language, time_zone, activated_at, changed_at, state_changed_at,
    state_changed_by, state_change_correlation_id, revision,
    provisioning_kind, provisioning_assignment_id, provisioned_by_identity_id
  ) values (
    pg_catalog.gen_random_uuid(), p_organization_id, p_identity_id, null,
    'active', null, null, evaluated_at, evaluated_at, evaluated_at,
    p_identity_id, new_correlation_id, 1, 'vortex_super_administrator',
    resolved_assignment_id, p_identity_id
  )
  on conflict (organization_id, identity_id) do nothing
  returning organization_account_id into inserted_account_id;

  if inserted_account_id is null then
    select account.organization_account_id, account.state
    into resolved_account_id, account_state
    from vortex_identity.organization_accounts as account
    where account.identity_id = p_identity_id
      and account.organization_id = p_organization_id
    for share;
    if account_state = 'active' then
      return query select resolved_tenant_id, p_organization_id,
        resolved_account_id;
      return;
    end if;
    if account_state = 'suspended' then
      raise exception using errcode = 'V3140',
        message = 'This super-administrator organisation account is suspended';
    end if;
    raise exception using errcode = '42501',
      message = 'Organisation selection is unavailable';
  end if;

  perform vortex_activity.append_organization_activity_entry(
    p_organization_id, pg_catalog.gen_random_uuid(), evaluated_at,
    'identity', p_identity_id, 'super_administrator_account_provisioned',
    array(
      select subject_id
      from pg_catalog.unnest(array[
        p_organization_id, inserted_account_id, resolved_assignment_id
      ]) as subject(subject_id)
      order by subject_id
    ), '{}'::uuid[], 'web', new_correlation_id, 'completed'
  );

  return query select resolved_tenant_id, p_organization_id,
    inserted_account_id;
end
$function$;


ALTER FUNCTION vortex_identity.resolve_active_organization_account(p_identity_id uuid, p_organization_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION resolve_active_organization_account(p_identity_id uuid, p_organization_id uuid); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.resolve_active_organization_account(p_identity_id uuid, p_organization_id uuid) IS 'Returns an active local account or transactionally provisions one for an assigned Vortex super administrator with immutable provenance and Activity evidence.';


--
-- Name: resolve_active_vortex_super_administrator_assignment_internal(uuid, timestamp with time zone); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

create or replace function vortex_identity.resolve_active_vortex_super_administrator_assignment_internal(
  p_identity_id uuid,
  p_checked_at timestamptz
)
returns uuid
language sql
stable
security definer
set search_path = ''
as $function$
  select assignment.assignment_id
  from vortex_identity.vortex_super_administrator_assignments as assignment
  join vortex_identity.identity_projections as identity
    on identity.identity_id = assignment.identity_id
    and identity.state = 'active'
  where assignment.identity_id = p_identity_id
    and (assignment.revoked_at is null or assignment.revoked_at > p_checked_at)
    and assignment.granted_at <= p_checked_at
  limit 1
$function$;


ALTER FUNCTION vortex_identity.resolve_active_vortex_super_administrator_assignment_internal(p_identity_id uuid, p_checked_at timestamp with time zone) OWNER TO postgres;

--
