--
-- Name: revoke_organization_invitation(uuid, bigint); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.revoke_organization_invitation(
  p_invitation_id uuid,
  p_expected_revision bigint
)
returns table (
  invitation_id uuid,
  organization_id uuid,
  invited_email text,
  invited_by uuid,
  created_at timestamptz,
  invited_at timestamptz,
  expires_at timestamptz,
  revoked_at timestamptz,
  revoked_by uuid,
  accepted_at timestamptz,
  accepted_organization_account_id uuid,
  changed_at timestamptz,
  revision bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked jsonb;
  operation_at timestamptz := pg_catalog.statement_timestamp();
begin
  checked := vortex_identity.validated_human_account_context();

  return query
  update vortex_identity.organization_invitations as invitation
  set revoked_at = operation_at,
      revoked_by_organization_account_id = (checked ->> 'organizationAccountId')::uuid,
      changed_at = operation_at,
      revision = invitation.revision + 1
  where invitation.invitation_id = p_invitation_id
    and invitation.organization_id = (checked ->> 'organizationId')::uuid
    and invitation.revision = p_expected_revision
    and invitation.accepted_at is null
    and invitation.revoked_at is null
  returning invitation.invitation_id, invitation.organization_id, invitation.invited_email,
    invitation.invited_by_organization_account_id, invitation.created_at,
    invitation.invited_at, invitation.expires_at, invitation.revoked_at,
    invitation.revoked_by_organization_account_id, invitation.accepted_at,
    invitation.accepted_organization_account_id, invitation.changed_at,
    invitation.revision;

  if not found then
    raise exception using errcode = '40001', message = 'Invitation is stale or unavailable';
  end if;
end
$function$;


ALTER FUNCTION vortex_identity.revoke_organization_invitation(p_invitation_id uuid, p_expected_revision bigint) OWNER TO vortex_identity_owner;

--
-- Name: revoke_tenant_administrator(uuid, text, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

create or replace function vortex_identity.revoke_tenant_administrator(
  p_duplicate_key uuid,
  p_command_fingerprint text,
  p_tenant_id uuid,
  p_assignment_id uuid,
  p_expected_revision bigint
)
returns table (outcome text, operation text, assignment_id uuid, revision bigint, correlation_id uuid, accepted_at timestamptz)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz;
  actor_identity_id uuid;
  target_identity_id uuid;
  current_revision bigint;
  current_revoked_at timestamptz;
  receipt vortex_identity.accepted_administration_receipts%rowtype;
  new_correlation_id uuid := pg_catalog.gen_random_uuid();
  resulting_revision bigint;
begin
  if p_duplicate_key is null or not vortex_context.is_non_nil_uuid(p_duplicate_key::text)
    or p_tenant_id is null or not vortex_context.is_non_nil_uuid(p_tenant_id::text)
    or p_assignment_id is null or not vortex_context.is_non_nil_uuid(p_assignment_id::text)
    or p_expected_revision is null or p_expected_revision not between 1 and 9007199254740991
    or p_command_fingerprint is null or p_command_fingerprint !~ '^sha256:[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Tenant assignment command is invalid';
  end if;
  actor_identity_id := vortex_identity.tenant_request_actor_id();
  perform 1 from vortex_identity.tenants tenant
    where tenant.tenant_id = p_tenant_id for update;
  if not found then
    raise exception using errcode = 'V3101', message = 'Tenant operation is unavailable';
  end if;
  select a.identity_id into target_identity_id
  from vortex_identity.tenant_administrator_assignments a
  where a.assignment_id = p_assignment_id and a.tenant_id = p_tenant_id;
  perform 1 from vortex_identity.identity_projections p
    where p.identity_id in (actor_identity_id, target_identity_id)
    order by p.identity_id for share;
  perform 1 from vortex_identity.tenant_administrator_assignments a
    where a.tenant_id = p_tenant_id
      and (a.identity_id = actor_identity_id or a.assignment_id = p_assignment_id)
    order by a.assignment_id for update;
  evaluated_at := pg_catalog.clock_timestamp();
  perform vortex_identity.require_current_tenant_capability(
    actor_identity_id, p_tenant_id,
    'platform.tenant.administrators.manage', evaluated_at
  );
  select a.revision, a.revoked_at into current_revision, current_revoked_at
  from vortex_identity.tenant_administrator_assignments a
  where a.assignment_id = p_assignment_id and a.tenant_id = p_tenant_id;
  select stored.* into receipt
  from vortex_identity.accepted_administration_receipts stored
  where stored.actor_id = actor_identity_id and stored.tenant_id = p_tenant_id
    and stored.operation_key = 'revoke_tenant_administrator'
    and stored.duplicate_key = p_duplicate_key for update;
  if found then
    if receipt.command_fingerprint <> p_command_fingerprint then
      raise exception using errcode = 'V3001', message = 'Administration duplicate conflicts';
    end if;
    return query select 'replayed'::text, 'revoke_tenant_administrator'::text,
      p_assignment_id, receipt.subject_revisions[1], receipt.receipt_id,
      receipt.accepted_at;
    return;
  end if;
  if current_revision is null or current_revoked_at is not null then
    raise exception using errcode = 'V3101', message = 'Tenant operation is unavailable';
  end if;
  if current_revision <> p_expected_revision then
    raise exception using errcode = 'V3102', message = 'Tenant assignment revision is stale';
  end if;
  if not vortex_identity.tenant_has_permanent_manager(
    p_tenant_id, evaluated_at, p_assignment_id
  ) then
    raise exception using errcode = 'V3103', message = 'Permanent tenant manager is required';
  end if;
  resulting_revision := current_revision + 1;
  update vortex_identity.tenant_administrator_assignments
  set revision = resulting_revision, changed_at = evaluated_at,
    changed_by_actor_id = actor_identity_id,
    change_correlation_id = new_correlation_id, revoked_at = evaluated_at,
    revoked_by_actor_id = actor_identity_id,
    revocation_correlation_id = new_correlation_id
  where tenant_administrator_assignments.assignment_id = p_assignment_id;
  insert into vortex_identity.accepted_administration_receipts(
    receipt_id, actor_id, tenant_id, operation_key, duplicate_key,
    command_fingerprint, subject_ids, subject_revisions, accepted_at
  ) values (
    new_correlation_id, actor_identity_id, p_tenant_id,
    'revoke_tenant_administrator', p_duplicate_key, p_command_fingerprint,
    array[p_assignment_id], array[resulting_revision], evaluated_at
  );
  return query select 'accepted'::text, 'revoke_tenant_administrator'::text,
    p_assignment_id, resulting_revision, new_correlation_id, evaluated_at;
end
$function$;


ALTER FUNCTION vortex_identity.revoke_tenant_administrator(p_duplicate_key uuid, p_command_fingerprint text, p_tenant_id uuid, p_assignment_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION revoke_tenant_administrator(p_duplicate_key uuid, p_command_fingerprint text, p_tenant_id uuid, p_assignment_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.revoke_tenant_administrator(p_duplicate_key uuid, p_command_fingerprint text, p_tenant_id uuid, p_assignment_id uuid, p_expected_revision bigint) IS 'Protected same-tenant tenant-administrator revocation under the bound request context person''s current structural authority, with permanent-manager preservation, exact revision and accepted replay.';


--
-- Name: revoke_vortex_super_administrator(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

create or replace function vortex_identity.revoke_vortex_super_administrator(
  p_duplicate_key uuid,
  p_assignment_id uuid,
  p_expected_revision bigint
)
returns table (
  outcome text,
  assignment_id uuid,
  identity_id uuid,
  revision bigint,
  correlation_id uuid,
  accepted_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  actor_identity_id uuid;
  target_identity_id uuid;
  existing_receipt vortex_identity.vortex_super_administrator_assignment_receipts%rowtype;
  assignment_fact vortex_identity.vortex_super_administrator_assignments%rowtype;
  evaluated_at timestamptz;
  revoked_at_value timestamptz;
  resulting_revision bigint;
  computed_fingerprint text;
  new_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_duplicate_key is null
    or not vortex_context.is_non_nil_uuid(p_duplicate_key::text)
    or p_assignment_id is null
    or not vortex_context.is_non_nil_uuid(p_assignment_id::text)
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Super-administrator revocation command is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  actor_identity_id := (context_value ->> 'identityId')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('vortex.super_administrator.assignments', 0)
  );
  perform 1
  from vortex_identity.identity_projections as identity
  where identity.identity_id = actor_identity_id
    and identity.state = 'active'
  for share;
  if not found then
    raise exception using errcode = '42501',
      message = 'Super-administrator authority is unavailable';
  end if;

  perform 1
  from vortex_identity.vortex_super_administrator_assignments as assignment
  where assignment.identity_id = actor_identity_id
    and assignment.revoked_at is null
  for share;
  if not found then
    raise exception using errcode = '42501',
      message = 'Super-administrator authority is unavailable';
  end if;

  select assignment.* into assignment_fact
  from vortex_identity.vortex_super_administrator_assignments as assignment
  where assignment.assignment_id = p_assignment_id
  for update;
  if not found then
    raise exception using errcode = 'V3141',
      message = 'Super-administrator assignment is unavailable';
  end if;
  target_identity_id := assignment_fact.identity_id;

  evaluated_at := pg_catalog.clock_timestamp();
  if vortex_access.recent_authentication_deadline_internal(
    context_value, evaluated_at,
    '{"kind":"primary","maximumAgeSeconds":900}'::jsonb
  ) is null then
    raise exception using errcode = 'V3142',
      message = 'A recent sign-in is required for super-administrator changes';
  end if;

  computed_fingerprint := 'sha256:' || pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.concat_ws(E'\x1f', 'revoke',
      p_assignment_id::text, p_expected_revision::text), 'UTF8'), 'sha256'
  ), 'hex');

  select receipt.* into existing_receipt
  from vortex_identity.vortex_super_administrator_assignment_receipts as receipt
  where receipt.actor_kind = 'identity'
    and receipt.actor_id = actor_identity_id
    and receipt.operation_key = 'revoke'
    and receipt.duplicate_key = p_duplicate_key;
  if found then
    if existing_receipt.command_fingerprint <> computed_fingerprint then
      raise exception using errcode = 'V3143',
        message = 'Super-administrator revocation duplicate conflicts';
    end if;
    return query select 'replayed'::text, existing_receipt.assignment_id,
      target_identity_id, existing_receipt.revision,
      existing_receipt.correlation_id, existing_receipt.accepted_at;
    return;
  end if;

  if assignment_fact.revoked_at is not null then
    raise exception using errcode = 'V3141',
      message = 'Super-administrator assignment is already revoked';
  end if;
  if assignment_fact.revision <> p_expected_revision
    or assignment_fact.revision = 9007199254740991 then
    raise exception using errcode = 'V3102',
      message = 'Super-administrator assignment revision is stale';
  end if;

  revoked_at_value := evaluated_at;
  resulting_revision := assignment_fact.revision + 1;

  perform vortex_activity.append_organization_activity_entry(
    (context_value ->> 'organizationId')::uuid, pg_catalog.gen_random_uuid(),
    evaluated_at, 'organization_account',
    (context_value ->> 'organizationAccountId')::uuid,
    'super_administrator_assignment_revoked',
    array(
      select subject_id
      from pg_catalog.unnest(array[target_identity_id, p_assignment_id]) as subject(subject_id)
      order by subject_id
    ), '{}'::uuid[], coalesce(context_value ->> 'channel', 'web'),
    new_correlation_id, 'completed'
  );

  update vortex_identity.vortex_super_administrator_assignments as assignment
  set revision = resulting_revision,
    changed_at = revoked_at_value,
    changed_by_kind = 'identity',
    changed_by_id = actor_identity_id,
    change_correlation_id = new_correlation_id,
    revoked_at = revoked_at_value,
    revoked_by_kind = 'identity',
    revoked_by_id = actor_identity_id,
    revocation_correlation_id = new_correlation_id
  where assignment.assignment_id = p_assignment_id;

  insert into vortex_identity.vortex_super_administrator_assignment_receipts (
    actor_kind, actor_id, operation_key, duplicate_key, command_fingerprint,
    assignment_id, revision, correlation_id, accepted_at
  ) values (
    'identity', actor_identity_id, 'revoke', p_duplicate_key,
    computed_fingerprint, p_assignment_id, resulting_revision,
    new_correlation_id, revoked_at_value
  );

  return query select 'accepted'::text, p_assignment_id, target_identity_id,
    resulting_revision, new_correlation_id, revoked_at_value;
end
$function$;


ALTER FUNCTION vortex_identity.revoke_vortex_super_administrator(p_duplicate_key uuid, p_assignment_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION revoke_vortex_super_administrator(p_duplicate_key uuid, p_assignment_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.revoke_vortex_super_administrator(p_duplicate_key uuid, p_assignment_id uuid, p_expected_revision bigint) IS 'Revokes a named super-administrator assignment through the live account-bound super-administrator context, with recent sign-in and exact revision evidence.';


--
-- Name: save_organization_runtime_settings_record_internal(uuid, bigint, jsonb, jsonb); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.save_organization_runtime_settings_record_internal(
  p_organization_id uuid,
  p_expected_revision bigint,
  p_core_values jsonb,
  p_extension_values jsonb
)
returns table (
  organization_id uuid,
  language text,
  time_zone text,
  currency text,
  date_format text,
  number_format text,
  default_application_root_id uuid,
  extension_values jsonb,
  revision bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  existing vortex_identity.organization_runtime_settings%rowtype;
  language_value text;
  time_zone_value text;
  currency_value text;
  date_format_value text;
  number_format_value text;
  default_application_root_id_value uuid;
  extension_values_value jsonb;
  extension_item record;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740990
    or pg_catalog.jsonb_typeof(p_core_values) is distinct from 'object'
    or p_core_values - array[
      'language', 'time_zone', 'currency', 'date_format', 'number_format',
      'default_application_root_id'
    ] <> '{}'::jsonb
    or pg_catalog.jsonb_typeof(p_extension_values) is distinct from 'object'
    or p_extension_values ?| array[
      'organization_id', 'revision', 'language', 'time_zone', 'currency',
      'date_format', 'number_format', 'default_application_root_id'
    ] then
    raise exception using errcode = '22023',
      message = 'Organization settings record update is invalid';
  end if;

  select settings.* into existing
  from vortex_identity.organization_runtime_settings as settings
  where settings.organization_id = p_organization_id
  for update;
  if not found or existing.revision <> p_expected_revision then
    raise exception using errcode = '40001',
      message = 'Organization settings record is stale or unavailable';
  end if;

  language_value := existing.language;
  time_zone_value := existing.time_zone;
  currency_value := existing.currency;
  date_format_value := existing.date_format;
  number_format_value := existing.number_format;
  default_application_root_id_value := existing.default_application_root_id;

  if p_core_values ? 'language' then
    if pg_catalog.jsonb_typeof(p_core_values -> 'language') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
    language_value := p_core_values ->> 'language';
  end if;
  if p_core_values ? 'time_zone' then
    if pg_catalog.jsonb_typeof(p_core_values -> 'time_zone') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
    time_zone_value := p_core_values ->> 'time_zone';
  end if;
  if p_core_values ? 'currency' then
    if pg_catalog.jsonb_typeof(p_core_values -> 'currency') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
    currency_value := p_core_values ->> 'currency';
  end if;
  if p_core_values ? 'date_format' then
    if pg_catalog.jsonb_typeof(p_core_values -> 'date_format') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
    date_format_value := p_core_values ->> 'date_format';
  end if;
  if p_core_values ? 'number_format' then
    if pg_catalog.jsonb_typeof(p_core_values -> 'number_format') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
    number_format_value := p_core_values ->> 'number_format';
  end if;
  if p_core_values ? 'default_application_root_id' then
    if pg_catalog.jsonb_typeof(p_core_values -> 'default_application_root_id') = 'null' then
      default_application_root_id_value := null;
    elsif pg_catalog.jsonb_typeof(p_core_values -> 'default_application_root_id') = 'string'
      and pg_catalog.pg_input_is_valid(
        p_core_values ->> 'default_application_root_id', 'uuid'
      ) then
      default_application_root_id_value :=
        (p_core_values ->> 'default_application_root_id')::uuid;
    else
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
    if default_application_root_id_value = '00000000-0000-0000-0000-000000000000'::uuid then
      raise exception using errcode = '22023',
        message = 'Organization settings record update is invalid';
    end if;
  end if;

  perform vortex_identity.assert_organization_runtime_settings_values(
    language_value, time_zone_value, currency_value, date_format_value, number_format_value
  );

  extension_values_value := existing.extension_values;
  for extension_item in
    select item.key, item.value
    from pg_catalog.jsonb_each(p_extension_values) as item(key, value)
    order by item.key collate "C"
  loop
    if pg_catalog.jsonb_typeof(extension_item.value) = 'null' then
      extension_values_value := extension_values_value - extension_item.key;
    else
      extension_values_value := extension_values_value || pg_catalog.jsonb_build_object(
        extension_item.key, extension_item.value
      );
    end if;
  end loop;

  update vortex_identity.organization_runtime_settings as settings
  set language = language_value,
      time_zone = time_zone_value,
      currency = currency_value,
      date_format = date_format_value,
      number_format = number_format_value,
      default_application_root_id = default_application_root_id_value,
      extension_values = extension_values_value,
      changed_at = pg_catalog.statement_timestamp(),
      revision = settings.revision + 1
  where settings.organization_id = p_organization_id
  returning * into existing;

  return query select existing.organization_id, existing.language, existing.time_zone,
    existing.currency, existing.date_format, existing.number_format,
    existing.default_application_root_id, existing.extension_values, existing.revision;
end
$function$;


ALTER FUNCTION vortex_identity.save_organization_runtime_settings_record_internal(p_organization_id uuid, p_expected_revision bigint, p_core_values jsonb, p_extension_values jsonb) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION save_organization_runtime_settings_record_internal(p_organization_id uuid, p_expected_revision bigint, p_core_values jsonb, p_extension_values jsonb); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.save_organization_runtime_settings_record_internal(p_organization_id uuid, p_expected_revision bigint, p_core_values jsonb, p_extension_values jsonb) IS 'Private revision-checked Identity writer for one organisation settings record, merging invariant field patches and declared extension values in the same settings row.';


--
-- Name: start_disabled_identity_projection_suspended(); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

CREATE FUNCTION vortex_identity.start_disabled_identity_projection_suspended() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_identity.projection:' || new.identity_id::text, 0
    )
  );

  if new.state = 'active' and vortex_identity.identity_is_disabled(new.identity_id) then
    new.state := 'suspended';
  end if;

  return new;
end
$$;


ALTER FUNCTION vortex_identity.start_disabled_identity_projection_suspended() OWNER TO postgres;

--
-- Name: FUNCTION start_disabled_identity_projection_suspended(); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.start_disabled_identity_projection_suspended() IS 'Private insert trigger: a new cluster-local projection of a disabled identity starts suspended.';


--
-- Name: subject_revisions_are_valid(uuid[], bigint[]); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

CREATE FUNCTION vortex_identity.subject_revisions_are_valid(p_subject_ids uuid[], p_subject_revisions bigint[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
declare
  subject_revision bigint;
begin
  if pg_catalog.array_ndims(p_subject_revisions) <> 1
    or pg_catalog.array_lower(p_subject_revisions, 1) <> 1
    or pg_catalog.cardinality(p_subject_revisions) <> pg_catalog.cardinality(p_subject_ids) then
    return false;
  end if;

  foreach subject_revision in array p_subject_revisions loop
    if subject_revision is null or subject_revision not between 1 and 9007199254740991 then
      return false;
    end if;
  end loop;
  return true;
end
$$;


ALTER FUNCTION vortex_identity.subject_revisions_are_valid(p_subject_ids uuid[], p_subject_revisions bigint[]) OWNER TO postgres;

--
-- Name: suspend_cluster_identity(uuid, uuid, uuid, text, uuid, bigint); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.suspend_cluster_identity(
  p_cluster_id uuid, p_operator_actor_id uuid, p_duplicate_key uuid,
  p_command_fingerprint text, p_identity_id uuid, p_expected_revision bigint
)
returns table (outcome text, operation text, identity_id uuid, revision bigint,
  correlation_id uuid, accepted_at timestamptz)
language sql volatile security definer set search_path = ''
as $function$
  select * from vortex_identity.apply_configured_cluster_identity_lifecycle(
