-- Name: FUNCTION tenant_structural_capability_set_is_canonical(p_capability_keys text[]); Type: COMMENT; Schema: vortex_identity; Owner: postgres
--

COMMENT ON FUNCTION vortex_identity.tenant_structural_capability_set_is_canonical(p_capability_keys text[]) IS 'Validates a canonical nonempty set of tenant capability permissions against the single closed permission set.';


--
-- Name: update_organization_account_profile_internal(uuid, uuid, bigint, text, text, text); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.update_organization_account_profile_internal(
  p_organization_id uuid,
  p_organization_account_id uuid,
  p_expected_revision bigint,
  p_display_name text,
  p_language text,
  p_time_zone text
)
returns table (
  organization_id uuid,
  organization_account_id uuid,
  display_name text,
  state text,
  language text,
  time_zone text,
  changed_at timestamptz,
  revision bigint
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  existing vortex_identity.organization_accounts%rowtype;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_organization_account_id is null
    or p_organization_account_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991
    or p_display_name is null
    or p_display_name <> pg_catalog.btrim(p_display_name)
    or pg_catalog.char_length(p_display_name) not between 1 and 120
    or (p_language is not null
      and (p_language <> pg_catalog.btrim(p_language)
        or pg_catalog.char_length(p_language) not between 2 and 35))
    or (p_time_zone is not null
      and (p_time_zone <> pg_catalog.btrim(p_time_zone)
        or pg_catalog.char_length(p_time_zone) not between 1 and 100)) then
    raise exception using errcode = '22023',
      message = 'Organization account profile update is invalid';
  end if;

  select account.* into existing
  from vortex_identity.organization_accounts as account
  where account.organization_id = p_organization_id
    and account.organization_account_id = p_organization_account_id
  for update;
  if not found
    or existing.state <> 'active'
    or existing.revision <> p_expected_revision
    or p_expected_revision = 9007199254740991 then
    raise exception using errcode = '40001',
      message = 'Organization account profile update is stale or unavailable';
  end if;
  if existing.display_name is not distinct from p_display_name
    and existing.language is not distinct from p_language
    and existing.time_zone is not distinct from p_time_zone then
    raise exception using errcode = '40001',
      message = 'Organization account profile is unchanged';
  end if;

  update vortex_identity.organization_accounts as account
  set display_name = p_display_name,
      language = p_language,
      time_zone = p_time_zone,
      changed_at = pg_catalog.statement_timestamp(),
      revision = account.revision + 1
  where account.organization_id = p_organization_id
    and account.organization_account_id = p_organization_account_id
  returning * into existing;

  return query select existing.organization_id, existing.organization_account_id,
    existing.display_name, existing.state, existing.language, existing.time_zone,
    existing.changed_at, existing.revision;
end
$function$;


ALTER FUNCTION vortex_identity.update_organization_account_profile_internal(p_organization_id uuid, p_organization_account_id uuid, p_expected_revision bigint, p_display_name text, p_language text, p_time_zone text) OWNER TO vortex_identity_owner;

--
-- Name: FUNCTION update_organization_account_profile_internal(p_organization_id uuid, p_organization_account_id uuid, p_expected_revision bigint, p_display_name text, p_language text, p_time_zone text); Type: COMMENT; Schema: vortex_identity; Owner: vortex_identity_owner
--

COMMENT ON FUNCTION vortex_identity.update_organization_account_profile_internal(p_organization_id uuid, p_organization_account_id uuid, p_expected_revision bigint, p_display_name text, p_language text, p_time_zone text) IS 'Owner-only Identity writer for one active organisation account profile under an exact current revision; changes display name, language and time zone only and advances the account revision.';


--
-- Name: validate_organization_lifecycle(); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.validate_organization_lifecycle()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  current_parent_id uuid;
  current_state text;
  tenant_state text;
  parent_state text;
begin
  select organization.parent_organization_id, organization.state
  into current_parent_id, current_state
  from vortex_identity.organizations as organization
  where organization.organization_id = new.organization_id;

  if not found then
    return null;
  end if;

  select tenant.state
  into tenant_state
  from vortex_identity.tenants as tenant
  where tenant.tenant_id = new.tenant_id;

  if current_state in ('active', 'suspended')
    and tenant_state in ('archived', 'removal_pending') then
    raise exception using
      errcode = '23514',
      message = 'An unresolved organisation requires a live tenant';
  end if;

  if current_parent_id is not null then
    select parent.state
    into parent_state
    from vortex_identity.organizations as parent
    where parent.tenant_id = new.tenant_id
      and parent.organization_id = current_parent_id;

    if current_state in ('active', 'suspended')
      and parent_state in ('archived', 'removal_pending') then
      raise exception using
        errcode = '23514',
        message = 'An unresolved organisation requires a live parent';
    end if;
  end if;

  if current_state in ('archived', 'removal_pending')
    and exists (
      select 1
      from vortex_identity.organizations as child
      where child.tenant_id = new.tenant_id
        and child.parent_organization_id = new.organization_id
        and child.state in ('active', 'suspended')
    ) then
    raise exception using
      errcode = '23514',
      message = 'An archived or removal-pending organisation cannot retain unresolved children';
  end if;

  return null;
end
$function$;


ALTER FUNCTION vortex_identity.validate_organization_lifecycle() OWNER TO vortex_identity_owner;

--
-- Name: validate_tenant_lifecycle(); Type: FUNCTION; Schema: vortex_identity; Owner: vortex_identity_owner
--

create or replace function vortex_identity.validate_tenant_lifecycle()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  current_state text;
begin
  select tenant.state
  into current_state
  from vortex_identity.tenants as tenant
  where tenant.tenant_id = new.tenant_id;

  if not found then
    return null;
  end if;

  if current_state in ('archived', 'removal_pending')
    and exists (
      select 1
      from vortex_identity.organizations as organization
      where organization.tenant_id = new.tenant_id
        and organization.state in ('active', 'suspended')
    ) then
    raise exception using
      errcode = '23514',
      message = 'An archived or removal-pending tenant cannot retain unresolved organisations';
  end if;

  return null;
end
$function$;


ALTER FUNCTION vortex_identity.validate_tenant_lifecycle() OWNER TO vortex_identity_owner;

--
-- Name: validated_human_account_context(); Type: FUNCTION; Schema: vortex_identity; Owner: postgres
--

CREATE FUNCTION vortex_identity.validated_human_account_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  checked jsonb;
begin
  checked := vortex_context.current_context();
  if checked ->> 'callerKind' is distinct from 'human'
    or not checked ?& array['identityId', 'organizationAccountId'] then
    raise exception using errcode = '42501', message = 'Organisation-account operation requires human context';
  end if;

  if not exists (
    select 1
    from vortex_identity.organization_accounts as account
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    join vortex_identity.identity_projections as identity
      on identity.identity_id = account.identity_id
    where account.organization_account_id = (checked ->> 'organizationAccountId')::uuid
      and account.organization_id = (checked ->> 'organizationId')::uuid
      and account.identity_id = (checked ->> 'identityId')::uuid
      and organization.tenant_id = (checked ->> 'tenantId')::uuid
      and account.state = 'active'
      and identity.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
  ) then
    raise exception using errcode = '42501', message = 'Organisation-account context is inactive or unavailable';
  end if;

  return checked;
end
$$;


ALTER FUNCTION vortex_identity.validated_human_account_context() OWNER TO postgres;

--
-- Name: application_is_installed(uuid, uuid); Type: FUNCTION; Schema: vortex_invalidation; Owner: vortex_invalidation_owner
--

create or replace function vortex_invalidation.application_is_installed(
  p_organization_id uuid,
  p_application_root_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select p_organization_id is not null
    and p_application_root_id is not null
    and exists (
      select 1
      from vortex_access.read_application_permission_snapshot(
        p_organization_id, p_application_root_id
      ) as registration
      where vortex_definition.application_root_exists_for_organization_internal(
          p_organization_id, p_application_root_id
        )
        and vortex_module.has_active_application_release_binding_internal(
          p_organization_id, p_application_root_id, registration.release_revision
        )
    )
$function$;


ALTER FUNCTION vortex_invalidation.application_is_installed(p_organization_id uuid, p_application_root_id uuid) OWNER TO vortex_invalidation_owner;

--
-- Name: FUNCTION application_is_installed(p_organization_id uuid, p_application_root_id uuid); Type: COMMENT; Schema: vortex_invalidation; Owner: vortex_invalidation_owner
--

COMMENT ON FUNCTION vortex_invalidation.application_is_installed(p_organization_id uuid, p_application_root_id uuid) IS 'Private check that an application has an active registration and an active installation binding for its registered release in one organisation.';


--
-- Name: change_topic(uuid, uuid); Type: FUNCTION; Schema: vortex_invalidation; Owner: postgres
--

create or replace function vortex_invalidation.change_topic(
  p_organization_id uuid,
  p_application_root_id uuid
)
returns text
language sql
stable
security invoker
set search_path = ''
as $function$
  select case
    when p_organization_id is null or p_application_root_id is null then null
    else (
      vortex_access.validation_reference_list('private_invalidation_topic_prefix')
    )[1]
      || ':' || p_organization_id::text || ':' || p_application_root_id::text
  end
$function$;


ALTER FUNCTION vortex_invalidation.change_topic(p_organization_id uuid, p_application_root_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION change_topic(p_organization_id uuid, p_application_root_id uuid); Type: COMMENT; Schema: vortex_invalidation; Owner: postgres
--

COMMENT ON FUNCTION vortex_invalidation.change_topic(p_organization_id uuid, p_application_root_id uuid) IS 'Returns the deterministic private Broadcast topic for one organisation and application.';


--
-- Name: may_receive_topic(text); Type: FUNCTION; Schema: vortex_invalidation; Owner: postgres
--

create or replace function vortex_invalidation.may_receive_topic(p_topic text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select exists (
    select 1
    from vortex_identity.identity_projections as projection
    join vortex_identity.organization_accounts as account
      on account.identity_id = projection.identity_id
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where projection.identity_id = auth.uid()
      and projection.state = 'active'
      and account.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
      and organization.organization_id = vortex_invalidation.topic_organization_id(p_topic)
      and vortex_invalidation.application_is_installed(
        organization.organization_id,
        vortex_invalidation.topic_application_root_id(p_topic)
      )
  )
$function$;


ALTER FUNCTION vortex_invalidation.may_receive_topic(p_topic text) OWNER TO postgres;

--
-- Name: FUNCTION may_receive_topic(p_topic text); Type: COMMENT; Schema: vortex_invalidation; Owner: postgres
--

COMMENT ON FUNCTION vortex_invalidation.may_receive_topic(p_topic text) IS 'Authorises one authenticated identity to read a private topic only for an active organisation account it holds and an application currently installed there.';


--
-- Name: publish_change_notice(uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, uuid); Type: FUNCTION; Schema: vortex_invalidation; Owner: postgres
--

create or replace function vortex_invalidation.publish_change_notice(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_record_type_id uuid,
  p_record_id uuid,
  p_record_version bigint,
  p_change_kind text,
  p_data_version bigint,
  p_sequence bigint,
  p_correlation_id uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  operation_at timestamptz := pg_catalog.clock_timestamp();
  selected_topic text;
  selected_payload jsonb;
  stored_context text;
begin
  if p_organization_id is null
    or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null
    or not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_record_type_id is null
    or not vortex_context.is_non_nil_uuid(p_record_type_id::text)
    or (p_record_id is not null and not vortex_context.is_non_nil_uuid(p_record_id::text))
    or (p_record_version is not null
      and p_record_version not between 1 and 9007199254740991)
    or p_change_kind is null
    or not (
      p_change_kind = any (
        vortex_access.validation_reference_list('private_invalidation_change_kind')
      )
    )
    or p_data_version is null
    or p_data_version not between 1 and 9007199254740991
    or p_sequence is null
    or p_sequence not between 1 and 9007199254740991
    or p_correlation_id is null
    or not vortex_context.is_non_nil_uuid(p_correlation_id::text) then
    raise exception using errcode = '22023',
      message = 'Invalidation notice command is invalid';
  end if;

  stored_context := pg_catalog.current_setting('vortex.request_context', true);
  if stored_context is not null and stored_context <> ''
    and (vortex_context.current_context() ->> 'organizationId')::uuid
      is distinct from p_organization_id then
    raise exception using errcode = '42501',
      message = 'Invalidation notice scope is unavailable';
  end if;

  if not exists (
    select 1
    from vortex_identity.organizations as organization
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where organization.organization_id = p_organization_id
      and organization.state = 'active'
      and tenant.state = 'active'
  ) or not vortex_invalidation.application_is_installed(
    p_organization_id, p_application_root_id
  ) then
    raise exception using errcode = 'P0002',
      message = 'Invalidation notice scope is unavailable';
  end if;

  selected_topic := vortex_invalidation.change_topic(p_organization_id, p_application_root_id);

  selected_payload := pg_catalog.jsonb_build_object(
    'contractVersion', '1.0.0',
    'organizationId', p_organization_id,
    'applicationRootId', p_application_root_id,
    'recordTypeId', p_record_type_id,
    'changeKind', p_change_kind,
    'dataVersion', p_data_version,
    'sequence', p_sequence,
    'occurredAt', vortex_context.format_timestamp_utc(operation_at),
    'correlationId', p_correlation_id
  )
  || case when p_record_id is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('recordId', p_record_id) end
  || case when p_record_version is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('recordVersion', p_record_version) end;

  perform realtime.send(selected_payload, 'invalidation', selected_topic, true);

  return selected_topic;
end
$function$;


ALTER FUNCTION vortex_invalidation.publish_change_notice(p_organization_id uuid, p_application_root_id uuid, p_record_type_id uuid, p_record_id uuid, p_record_version bigint, p_change_kind text, p_data_version bigint, p_sequence bigint, p_correlation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION publish_change_notice(p_organization_id uuid, p_application_root_id uuid, p_record_type_id uuid, p_record_id uuid, p_record_version bigint, p_change_kind text, p_data_version bigint, p_sequence bigint, p_correlation_id uuid); Type: COMMENT; Schema: vortex_invalidation; Owner: postgres
--

COMMENT ON FUNCTION vortex_invalidation.publish_change_notice(p_organization_id uuid, p_application_root_id uuid, p_record_type_id uuid, p_record_id uuid, p_record_version bigint, p_change_kind text, p_data_version bigint, p_sequence bigint, p_correlation_id uuid) IS 'Protected post-commit broadcast of the bounded content-free invalidation envelope on the private topic for one organisation and application.';


--
-- Name: topic_application_root_id(text); Type: FUNCTION; Schema: vortex_invalidation; Owner: postgres
--

create or replace function vortex_invalidation.topic_application_root_id(p_topic text)
returns uuid
language sql
stable
security invoker
set search_path = ''
as $function$
  select case
    when p_topic ~ (
      '^'
      || (
        vortex_access.validation_reference_list('private_invalidation_topic_prefix')
      )[1]
      || ':[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
      || ':[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
      then pg_catalog.split_part(p_topic, ':', 4)::uuid
    else null
  end
$function$;


ALTER FUNCTION vortex_invalidation.topic_application_root_id(p_topic text) OWNER TO postgres;

