--
-- Name: activate_application_installation(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.activate_application_installation(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  application_release vortex_definition.releases%rowtype;
  permission_snapshot record;
  pin record;
  locked_binding vortex_module.installation_bindings%rowtype;
  storage_provision record;
  expected_count integer;
  pin_count integer;
  all_provisioned boolean;
  all_active boolean;
  changed_value boolean;
  binding_evidence jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId')::uuid =
          '00000000-0000-0000-0000-000000000000'::uuid
        or (item.value ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Application installation activation command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where root.root_id = p_application_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application'
    and release.release_revision = p_application_release_revision
    and release.validation_contract_version = any (vortex_definition.accepted_contract_version('application'))
    and release.compilation_output #>> '{kind}' = 'application'
    and release.compilation_output #>> '{canonical,envelope,rootId}' = p_application_root_id::text
    and release.compilation_output #>> '{validationContractVersion}' = any (vortex_definition.accepted_contract_version('application'));

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if pin_count = 0 or expected_count <> pin_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Application installation binding set is incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_module.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
    perform 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Application installation authority changed';
  end if;

  select pg_catalog.bool_and(coalesce(
      binding.state = 'provisioned'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'active'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    ))
  into all_provisioned, all_active
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  left join vortex_module.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id
  left join lateral (
    select (expected.value ->> 'bindingRevision')::bigint as binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
  ) as expected on true
  ;
  if all_provisioned is null or (not all_provisioned and not all_active)
    or exists (
      select 1 from vortex_module.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.state <> 'detached'
        and not exists (
          select 1 from vortex_definition.reachable_module_dependency_edges(
            p_application_root_id, p_application_release_revision
          ) as required
          where required.target_root_id = binding.module_root_id
        )
    ) then
    raise exception using errcode = '40001',
      message = 'Application installation bindings changed or are incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    select binding.* into strict locked_binding
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id;

    select provision.* into strict storage_provision
    from vortex_record.read_exact_module_storage_provision(
      pin.target_root_id, pin.target_release_revision
    ) as provision;

    if locked_binding.storage_contract_ids <> storage_provision.storage_contract_ids then
      raise exception using errcode = '40001',
        message = 'Application installation storage evidence changed or is incomplete';
    end if;
  end loop;

  select snapshot.* into permission_snapshot
  from vortex_access.read_application_permission_snapshot(
    initial_authority.organization_id, p_application_root_id
  ) as snapshot;
  if not found
    or permission_snapshot.release_revision <> p_application_release_revision
    or permission_snapshot.definition_key <> (
      select root.key from vortex_definition.roots as root
      where root.root_id = p_application_root_id
    )
    or permission_snapshot.release_version <> application_release.release_version
    or permission_snapshot.validation_contract_version <> application_release.validation_contract_version
    or permission_snapshot.content_fingerprint <> application_release.content_fingerprint
    or permission_snapshot.resolution_fingerprint <> application_release.resolution_fingerprint then
    raise exception using errcode = '40001',
      message = 'Application permission registration is stale or unavailable';
  end if;

  changed_value := all_provisioned;
  if changed_value then
    if exists (
      select 1 from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      join vortex_module.installation_bindings as binding
        on binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.module_root_id = required.target_root_id
      where binding.binding_revision = 9007199254740991
    ) then
      raise exception using errcode = '22003',
        message = 'Application installation binding revision is exhausted';
    end if;
    update vortex_module.installation_bindings as binding
    set state = 'active', binding_revision = binding.binding_revision + 1,
      changed_at = pg_catalog.statement_timestamp()
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = required.target_root_id
      and binding.state = 'provisioned';
    if not found then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed';
    end if;
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'organizationId', binding.organization_id,
    'applicationRootId', binding.application_root_id,
    'moduleRootId', binding.module_root_id,
    'bindingRevision', binding.binding_revision,
    'applicationReleaseRevision', binding.application_release_revision,
    'moduleReleaseRevision', binding.module_release_revision,
    'state', binding.state
  ) order by binding.module_root_id) into binding_evidence
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  join vortex_module.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'state', 'active', 'changed', changed_value,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application installation evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Application installation activation command is invalid';
end
$function$;


ALTER FUNCTION vortex_module.activate_application_installation(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION activate_application_installation(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.activate_application_installation(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Revision-checked atomic activation of the complete exact Module pin set for one Application release.';


--
-- Name: append_application_installation_activity_internal(uuid, uuid, text); Type: FUNCTION; Schema: vortex_module; Owner: postgres
--

create or replace function vortex_module.append_application_installation_activity_internal(
  p_activity_id uuid,
  p_application_root_id uuid,
  p_action text
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  append_result text;
begin
  if p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_action is null
    or p_action not in (
      'activate_application_installation', 'withdraw_application_installation',
      'drain_application_installation'
    ) then
    raise exception using errcode = '22023',
      message = 'Application installation Activity input is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  append_result := vortex_activity.append_organization_activity_entry(
    (context_value ->> 'organizationId')::uuid,
    p_activity_id,
    pg_catalog.statement_timestamp(),
    'organization_account',
    (context_value ->> 'organizationAccountId')::uuid,
    p_action,
    array[p_application_root_id]::uuid[],
    array[]::uuid[],
    vortex_context.channel(),
    (context_value ->> 'correlationId')::uuid,
    'completed'
  );
  if append_result is distinct from 'inserted' then
    raise exception using errcode = '40001',
      message = 'Application installation Activity is stale';
  end if;
end
$function$;


ALTER FUNCTION vortex_module.append_application_installation_activity_internal(p_activity_id uuid, p_application_root_id uuid, p_action text) OWNER TO postgres;

--
-- Name: FUNCTION append_application_installation_activity_internal(p_activity_id uuid, p_application_root_id uuid, p_action text); Type: COMMENT; Schema: vortex_module; Owner: postgres
--

COMMENT ON FUNCTION vortex_module.append_application_installation_activity_internal(p_activity_id uuid, p_application_root_id uuid, p_action text) IS 'Private content-free Activity composer for one protected Application installation lifecycle change.';


--
-- Name: assert_prepared_installation_runtime_bundle(uuid, bigint, jsonb, text); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.assert_prepared_installation_runtime_bundle(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb,
  p_pin_fingerprint text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expected_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  checked_context jsonb;
  selected_organization_id uuid;
  prepared_source jsonb;
  source_manifest jsonb;
  application_content jsonb;
  expected_access_plan jsonb;
  access_plan_text text;
  access_plan_value jsonb;
  stored_bundle vortex_module.installation_runtime_bundles%rowtype;
  part_item record;
  metadata_item jsonb;
  metadata_count integer;
  stored_part_count integer;
  section_value text;
  ordinal_value bigint;
  byte_size_value bigint;
  total_size_value bigint := 0;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_pin_fingerprint is null
    or p_pin_fingerprint !~ '^sha256:[a-f0-9]{64}$'
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) < 1 then
    raise exception using errcode = '22023',
      message = 'Prepared runtime bundle assertion is invalid';
  end if;
  checked_context := vortex_access.validated_human_request_context();
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  if selected_organization_id is null then
    raise exception using errcode = '42501',
      message = 'Prepared runtime bundle authority is unavailable';
  end if;
  prepared_source := vortex_module.read_prepared_installation_runtime_source(
    p_application_root_id,
    p_application_release_revision,
    p_expected_module_bindings
  );
  if prepared_source is null
    or (prepared_source ->> 'organizationId')::uuid is distinct from selected_organization_id
    or prepared_source ->> 'pinFingerprint' is distinct from p_pin_fingerprint then
    raise exception using errcode = '40001',
      message = 'Prepared runtime bundle source changed';
  end if;
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', prepared_source #> '{application,rootId}',
      'definitionKey', prepared_source #> '{application,key}',
      'releaseRevision', prepared_source #> '{application,releaseRevision}',
      'releaseVersion', prepared_source #> '{application,releaseVersion}',
      'validationContractVersion', prepared_source #> '{application,validationContractVersion}',
      'contentFingerprint', prepared_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', prepared_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', prepared_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', prepared_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', prepared_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );
  select stored.* into strict stored_bundle
  from vortex_module.installation_runtime_bundles as stored
  where stored.organization_id = selected_organization_id
    and stored.application_root_id = p_application_root_id
    and stored.application_release_revision = p_application_release_revision
    and stored.bundle_format_version = 2;
  if stored_bundle.pin_fingerprint is distinct from p_pin_fingerprint
    or stored_bundle.source_manifest is distinct from source_manifest then
    raise exception using errcode = '23505',
      message = 'Prepared runtime bundle identity differs';
  end if;

  if pg_catalog.jsonb_typeof(stored_bundle.parts) is distinct from 'array'
    or pg_catalog.jsonb_array_length(stored_bundle.parts) < pg_catalog.cardinality(expected_sections)
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1 from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle parts are incomplete';
  end if;
  select pg_catalog.count(*)::integer into metadata_count
  from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value);
  select pg_catalog.count(*)::integer into stored_part_count
  from vortex_module.installation_runtime_bundle_parts as part
  where part.organization_id = selected_organization_id
    and part.application_root_id = p_application_root_id
    and part.application_release_revision = p_application_release_revision
    and part.bundle_format_version = 2;
  if metadata_count is distinct from stored_part_count then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle part count differs';
  end if;
  for metadata_item in
    select item.value from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
  loop
    if pg_catalog.jsonb_typeof(metadata_item) is distinct from 'object'
      or not metadata_item ?& array['section','ordinal','byteSize','sha256']
      or metadata_item - array['section','ordinal','byteSize','sha256'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(metadata_item -> 'section') is distinct from 'string'
      or pg_catalog.jsonb_typeof(metadata_item -> 'ordinal') is distinct from 'number'
      or pg_catalog.jsonb_typeof(metadata_item -> 'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(metadata_item -> 'sha256') is distinct from 'string'
      or not (metadata_item ->> 'section' = any (expected_sections))
      or (metadata_item ->> 'ordinal') !~ '^(0|[1-9][0-9]*)$'
      or pg_catalog.length(metadata_item ->> 'ordinal') > 10
      or (metadata_item ->> 'byteSize') !~ '^[1-9][0-9]*$'
      or pg_catalog.length(metadata_item ->> 'byteSize') > 7
      or (metadata_item ->> 'sha256') !~ '^sha256:[a-f0-9]{64}$' then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle part metadata is invalid';
    end if;
    section_value := metadata_item ->> 'section';
    ordinal_value := (metadata_item ->> 'ordinal')::bigint;
    byte_size_value := (metadata_item ->> 'byteSize')::bigint;
    if ordinal_value > 2147483647 or byte_size_value > 1048575 then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle part metadata exceeds its limit';
    end if;
    total_size_value := total_size_value + byte_size_value;
    if total_size_value > 9007199254740991 then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle total size exceeds its limit';
    end if;
    select part.* into strict part_item
    from vortex_module.installation_runtime_bundle_parts as part
    where part.organization_id = selected_organization_id
      and part.application_root_id = p_application_root_id
      and part.application_release_revision = p_application_release_revision
      and part.bundle_format_version = 2
      and part.section = section_value
      and part.ordinal = ordinal_value::integer;
    if pg_catalog.octet_length(part_item.content_bytes) is distinct from byte_size_value
      or ('sha256:' || pg_catalog.encode(
        extensions.digest(part_item.content_bytes, 'sha256'), 'hex'
      )) is distinct from metadata_item ->> 'sha256' then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle bytes do not match their manifest';
    end if;
  end loop;
  if total_size_value is distinct from stored_bundle.total_size_bytes
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
      group by item.value ->> 'section', (item.value ->> 'ordinal')::integer
      having pg_catalog.count(*) > 1
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
      group by item.value ->> 'section'
      having pg_catalog.min((item.value ->> 'ordinal')::integer) <> 0
        or pg_catalog.max((item.value ->> 'ordinal')::integer) <>
          pg_catalog.count(*) - 1
    )
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle metadata is incomplete';
  end if;

  application_content := prepared_source #> '{application,compilationOutput,canonical,content}';
  select pg_catalog.jsonb_build_object(
    'preparedRecordAccessPlan', prepared_source -> 'preparedRecordAccessPlan',
    'declaredPermissions', pg_catalog.jsonb_build_object(
      'application', application_content -> 'permissions',
      'modules', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'rootId', module.value -> 'rootId',
            'permissions', module.value #> '{compilationOutput,canonical,content,permissions}'
          ) order by (module.value ->> 'rootId') collate "C")
        from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
      ), '[]'::jsonb)
    )
  ) into expected_access_plan;
  select pg_catalog.string_agg(pg_catalog.convert_from(part.content_bytes, 'UTF8'), ''
    order by part.ordinal)
  into access_plan_text
  from vortex_module.installation_runtime_bundle_parts as part
  where part.organization_id = selected_organization_id
    and part.application_root_id = p_application_root_id
    and part.application_release_revision = p_application_release_revision
    and part.bundle_format_version = 2
    and part.section = 'access_plan';
  begin
    access_plan_value := access_plan_text::jsonb;
  exception when others then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle access plan is invalid';
  end;
  if access_plan_value is distinct from expected_access_plan then
    raise exception using errcode = '23505',
      message = 'Prepared runtime bundle Record plan differs from current source';
  end if;
  return pg_catalog.jsonb_build_object(
    'outcome', 'verified',
    'organizationId', selected_organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'bundleFormatVersion', 2,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Prepared runtime bundle is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.assert_prepared_installation_runtime_bundle(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb, p_pin_fingerprint text) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION assert_prepared_installation_runtime_bundle(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb, p_pin_fingerprint text); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.assert_prepared_installation_runtime_bundle(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb, p_pin_fingerprint text) IS 'Re-derives first-install source and plan identity, then verifies the complete immutable format-2 bundle and its stored bytes before activation.';


--
-- Name: assert_preview_installation_authority_internal(); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.assert_preview_installation_authority_internal()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  permission_decision record;
  checked_context jsonb;
begin
  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.definition_drafts.manage',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '0548c061-b1a9-48e5-a04a-eb1d0dae0644'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  checked_context := vortex_access.validated_human_request_context();
  if permission_decision.outcome is distinct from 'eligible'
    or checked_context is null
    or (checked_context ->> 'organizationId')::uuid
      is distinct from permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid
      is distinct from permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint
      is distinct from permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid
      is distinct from permission_decision.correlation_id then
    raise exception using errcode = '42501', message = 'Preview installation authority is unavailable';
  end if;
  return checked_context;
end
$function$;


ALTER FUNCTION vortex_module.assert_preview_installation_authority_internal() OWNER TO vortex_module_owner;

--
-- Name: FUNCTION assert_preview_installation_authority_internal(); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.assert_preview_installation_authority_internal() IS 'Validates the current human request context and definition-draft management permission for private preview installation operations.';


--
-- Name: claim_organization_setup_source_manifest(uuid, uuid, uuid, uuid, text, uuid, text, integer, text, text); Type: FUNCTION; Schema: vortex_module; Owner: postgres
--

create or replace function vortex_module.claim_organization_setup_source_manifest(
  p_tenant_id uuid,
  p_organization_id uuid,
  p_organization_account_id uuid,
  p_identity_id uuid,
  p_operation text,
  p_receipt_id uuid,
  p_command_fingerprint text,
  p_expected_setup_revision integer,
  p_manifest_canonical_text text,
  p_manifest_fingerprint text
)
returns table (result_kind text, checkpoint jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  attested record;
  stored vortex_module.organization_setup_source_manifests%rowtype;
  expected_receipt jsonb;
  candidate_payload jsonb;
  candidate_entry jsonb;
  candidate_key text;
  candidate_version text;
  candidate_identity text;
  previous_identity text;
  has_default_application boolean := false;
  key_count bigint;
  unknown_key_count bigint;
  namespace_pattern constant text :=
    '^[a-z][a-z0-9]*(_[a-z0-9]+)*([.][a-z][a-z0-9]*(_[a-z0-9]+)*)+$';
  version_pattern constant text :=
    '^(0|[1-9][0-9]*)[.](0|[1-9][0-9]*)[.](0|[1-9][0-9]*)(-((0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)([.](0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?([+]([0-9A-Za-z-]+([.][0-9A-Za-z-]+)*))?$';
begin
  if p_expected_setup_revision is distinct from 0
    or pg_catalog.array_position(array[
      p_tenant_id, p_organization_id, p_organization_account_id, p_identity_id, p_receipt_id
    ], null::uuid) is not null
    or '00000000-0000-0000-0000-000000000000'::uuid = any(array[
      p_tenant_id, p_organization_id, p_organization_account_id, p_identity_id, p_receipt_id
    ])
    or p_operation is null
    or p_operation not in ('provision_tenant', 'create_tenant_organization')
    or p_command_fingerprint is null
    or p_command_fingerprint !~ '^sha256:[a-f0-9]{64}$'
    or (p_manifest_canonical_text is null) <> (p_manifest_fingerprint is null) then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;

  -- Reject oversized or inconsistent candidates before taking a lock, even for a stored replay.
  if p_manifest_canonical_text is not null then
    if pg_catalog.octet_length(pg_catalog.convert_to(p_manifest_canonical_text, 'UTF8'))
        not between 1 and 16777216
      or p_manifest_fingerprint !~ '^sha256:[a-f0-9]{64}$' then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
    if p_manifest_fingerprint is distinct from (
      'sha256:' || pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(p_manifest_canonical_text, 'UTF8')
      ), 'hex')
    ) then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
  end if;

  -- Original facts are re-attested here; neither runtime input nor the checkpoint is authority.
  select evidence.* into strict attested
  from vortex_identity.read_organization_setup_receipt(
    p_receipt_id, p_operation, p_organization_id
  ) as evidence;
  if attested.tenant_id is distinct from p_tenant_id
    or attested.organization_id is distinct from p_organization_id
    or attested.organization_account_id is distinct from p_organization_account_id
    or attested.identity_id is distinct from p_identity_id
    or attested.operation_key is distinct from p_operation
    or attested.receipt_id is distinct from p_receipt_id
    or attested.command_fingerprint is distinct from p_command_fingerprint then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;
  expected_receipt := pg_catalog.jsonb_build_object(
    'tenantId', p_tenant_id::text,
    'organizationId', p_organization_id::text,
    'organizationAccountId', p_organization_account_id::text,
    'identityId', p_identity_id::text,
    'operation', p_operation,
    'receiptId', p_receipt_id::text,
    'commandFingerprint', p_command_fingerprint
  );

  -- The original organisation row serialises the first claim, including the read-before-select call.
  perform 1 from vortex_identity.organizations as organization
  where organization.organization_id = p_organization_id
    and organization.tenant_id = p_tenant_id
  for update;
  if not found then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;

  select saved.* into stored
  from vortex_module.organization_setup_source_manifests as saved
  where saved.organization_id = p_organization_id;
  if found then
    if stored.tenant_id is distinct from p_tenant_id
      or stored.organization_account_id is distinct from p_organization_account_id
      or stored.identity_id is distinct from p_identity_id
      or stored.operation_key is distinct from p_operation
      or stored.receipt_id is distinct from p_receipt_id
      or stored.command_fingerprint is distinct from p_command_fingerprint
      or stored.setup_revision is distinct from 1
      or stored.phase is distinct from 'source_manifest_frozen'
      or stored.source_manifest_payload -> 'receipt' is distinct from expected_receipt
      or (p_manifest_canonical_text is not null and (
        stored.source_manifest_canonical_text is distinct from p_manifest_canonical_text
        or stored.manifest_fingerprint is distinct from p_manifest_fingerprint
      )) then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
    return query select 'pending'::text,
      stored.source_manifest_payload || pg_catalog.jsonb_build_object(
        'checkpointId', stored.checkpoint_id::text,
        'manifestFingerprint', stored.manifest_fingerprint,
        'setupRevision', stored.setup_revision,
        'phase', stored.phase
      );
    return;
  end if;

  if p_manifest_canonical_text is null then
    return query select 'missing'::text, null::jsonb;
    return;
  end if;
  candidate_payload := p_manifest_canonical_text::jsonb;
  if pg_catalog.jsonb_typeof(candidate_payload) is distinct from 'object' then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;
  select pg_catalog.count(*), pg_catalog.count(*) filter (where key not in (
    'receipt', 'sourceManifestIdentity', 'sourceManifestVersion',
    'sources', 'intendedDefaultDefinitionKey'
  )) into key_count, unknown_key_count
  from pg_catalog.jsonb_object_keys(candidate_payload) as keys(key);
  if key_count <> 5 or unknown_key_count <> 0
    or candidate_payload -> 'receipt' is distinct from expected_receipt
    or pg_catalog.jsonb_typeof(candidate_payload -> 'sourceManifestIdentity')
      is distinct from 'string'
    or pg_catalog.jsonb_typeof(candidate_payload -> 'sourceManifestVersion')
      is distinct from 'string'
    or pg_catalog.jsonb_typeof(candidate_payload -> 'intendedDefaultDefinitionKey')
      is distinct from 'string'
    or pg_catalog.jsonb_typeof(candidate_payload -> 'sources') is distinct from 'array' then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;
  foreach candidate_key in array array[
    candidate_payload ->> 'sourceManifestIdentity',
    candidate_payload ->> 'intendedDefaultDefinitionKey'
  ] loop
    if pg_catalog.char_length(candidate_key) not between 3 and 120
      or candidate_key !~ namespace_pattern
      or exists (select 1 from pg_catalog.unnest(pg_catalog.string_to_array(candidate_key, '.'))
        as segments(segment) where pg_catalog.char_length(segment) > 40) then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
  end loop;
  candidate_version := candidate_payload ->> 'sourceManifestVersion';
  if pg_catalog.char_length(candidate_version) not between 1 and 120
    or candidate_version !~ version_pattern
    or pg_catalog.jsonb_array_length(candidate_payload -> 'sources') not between 1 and 64 then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;

  -- This bounded data envelope does not duplicate the current Module/Application compiler.
  for candidate_entry in
    select value from pg_catalog.jsonb_array_elements(candidate_payload -> 'sources') as sources(value)
  loop
    if pg_catalog.jsonb_typeof(candidate_entry) is distinct from 'object' then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
    select pg_catalog.count(*), pg_catalog.count(*) filter (where key not in (
      'kind', 'key', 'sourceContractVersion', 'source', 'sourceFingerprint'
    )) into key_count, unknown_key_count
    from pg_catalog.jsonb_object_keys(candidate_entry) as keys(key);
    if key_count <> 5 or unknown_key_count <> 0
      or pg_catalog.jsonb_typeof(candidate_entry -> 'kind') is distinct from 'string'
      or candidate_entry ->> 'kind' not in ('module', 'application')
      or pg_catalog.jsonb_typeof(candidate_entry -> 'key') is distinct from 'string'
      or pg_catalog.jsonb_typeof(candidate_entry -> 'sourceContractVersion') is distinct from 'string'
      or pg_catalog.jsonb_typeof(candidate_entry -> 'sourceFingerprint') is distinct from 'string'
      or candidate_entry ->> 'sourceFingerprint' !~ '^sha256:[a-f0-9]{64}$'
      or pg_catalog.jsonb_typeof(candidate_entry -> 'source') is distinct from 'object'
      or candidate_entry ->> 'kind' is distinct from candidate_entry -> 'source' ->> 'kind'
      or candidate_entry ->> 'key' is distinct from candidate_entry -> 'source' ->> 'key'
      or candidate_entry ->> 'sourceContractVersion'
        is distinct from candidate_entry -> 'source' ->> 'source_contract_version'
      or pg_catalog.jsonb_typeof(candidate_entry -> 'source' -> 'body') is distinct from 'object' then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
    candidate_key := candidate_entry ->> 'key';
    candidate_version := candidate_entry ->> 'sourceContractVersion';
    if pg_catalog.char_length(candidate_key) not between 3 and 120
      or candidate_key !~ namespace_pattern
      or exists (select 1 from pg_catalog.unnest(pg_catalog.string_to_array(candidate_key, '.'))
        as segments(segment) where pg_catalog.char_length(segment) > 40)
      or pg_catalog.char_length(candidate_version) not between 1 and 120
      or candidate_version !~ version_pattern then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
    candidate_identity := (candidate_entry ->> 'kind') || ':' || candidate_key;
    if previous_identity is not null
      and candidate_identity collate pg_catalog."C" <= previous_identity collate pg_catalog."C" then
      raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
    end if;
    previous_identity := candidate_identity;
    if candidate_entry ->> 'kind' = 'application'
      and candidate_key = candidate_payload ->> 'intendedDefaultDefinitionKey' then
      has_default_application := true;
    end if;
  end loop;
  if not has_default_application then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
  end if;

  insert into vortex_module.organization_setup_source_manifests (
    tenant_id, organization_id, organization_account_id, identity_id, operation_key,
    receipt_id, command_fingerprint, source_manifest_canonical_text,
    source_manifest_payload, manifest_fingerprint
  ) values (
    p_tenant_id, p_organization_id, p_organization_account_id, p_identity_id, p_operation,
    p_receipt_id, p_command_fingerprint, p_manifest_canonical_text,
    candidate_payload, p_manifest_fingerprint
  ) returning * into stored;
  return query select 'pending'::text,
    stored.source_manifest_payload || pg_catalog.jsonb_build_object(
      'checkpointId', stored.checkpoint_id::text,
      'manifestFingerprint', stored.manifest_fingerprint,
      'setupRevision', stored.setup_revision,
      'phase', stored.phase
    );
exception
  when others then
    raise exception using errcode = 'V3101', message = 'Organisation setup is unavailable';
end
$function$;


ALTER FUNCTION vortex_module.claim_organization_setup_source_manifest(p_tenant_id uuid, p_organization_id uuid, p_organization_account_id uuid, p_identity_id uuid, p_operation text, p_receipt_id uuid, p_command_fingerprint text, p_expected_setup_revision integer, p_manifest_canonical_text text, p_manifest_fingerprint text) OWNER TO postgres;

--
-- Name: FUNCTION claim_organization_setup_source_manifest(p_tenant_id uuid, p_organization_id uuid, p_organization_account_id uuid, p_identity_id uuid, p_operation text, p_receipt_id uuid, p_command_fingerprint text, p_expected_setup_revision integer, p_manifest_canonical_text text, p_manifest_fingerprint text); Type: COMMENT; Schema: vortex_module; Owner: postgres
--

COMMENT ON FUNCTION vortex_module.claim_organization_setup_source_manifest(p_tenant_id uuid, p_organization_id uuid, p_organization_account_id uuid, p_identity_id uuid, p_operation text, p_receipt_id uuid, p_command_fingerprint text, p_expected_setup_revision integer, p_manifest_canonical_text text, p_manifest_fingerprint text) IS 'Claims or reads one immutable original-receipt-bound pending source checkpoint; grants no setup, publication, installation, rights, default or completion authority.';


--
-- Name: count_storage_adoption_dependents_internal(uuid, uuid, bigint[]); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  dependent_count bigint;
begin
  if p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_dependent_release_revisions is null
    or pg_catalog.array_position(p_dependent_release_revisions, null) is not null then
    raise exception using errcode = '22023',
      message = 'Storage adoption dependent count command is invalid';
  end if;

  -- Every organisation's binding counts: the mappings are shared by every
  -- installation of the Module. A provisioned binding is counted with an active
  -- one because activation does not recheck storage, so it could otherwise
  -- activate over a retired field; only a detached binding stops depending on
  -- the source field. The caller holds the storage-lineage lock, which every
  -- provision of these releases takes before it writes a binding, so no new
  -- dependent can appear unseen.
  select pg_catalog.count(*) into dependent_count
  from vortex_module.installation_bindings as binding
  where binding.module_root_id = p_module_root_id
    and binding.state in ('provisioned', 'active')
    and p_storage_contract_id = any (binding.storage_contract_ids)
    and binding.module_release_revision = any (p_dependent_release_revisions);
  return dependent_count;
end
$$;


ALTER FUNCTION vortex_module.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) IS 'Private storage adoption fact: counts every organisation''s provisioned and active bindings of the Module that install one of the named releases needing the source storage.';


--
-- Name: create_preview_installation(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.create_preview_installation(
  p_application_root_id uuid,
  p_expected_draft_revision bigint,
  p_candidate jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  preview_lifetime constant interval := interval '24 hours';
  checked_context jsonb;
  organization_id_value uuid;
  organization_account_id_value uuid;
  identity_id_value uuid;
  preview_installation_id_value uuid;
  draft_revision_value bigint;
  created_at_value timestamptz;
  expires_at_value timestamptz;
  compilation_value jsonb;
  module_dependency jsonb;
  module_release_revision bigint;
  module_root_id_value uuid;
  module_closure jsonb := '[]'::jsonb;
  resolved_modules_value jsonb := '[]'::jsonb;
  storage_identities_value jsonb := '[]'::jsonb;
  binding_count bigint;
  resolution_count bigint;
begin
  if not vortex_context.is_non_nil_uuid(p_application_root_id::text)
    or p_expected_draft_revision is null
    or p_expected_draft_revision not between 1 and 9007199254740991
    or p_candidate is null
    or pg_catalog.jsonb_typeof(p_candidate) <> 'object'
    or pg_catalog.jsonb_typeof(p_candidate -> 'compilation') is distinct from 'object'
    or not (p_candidate ? 'currentReleaseRevision')
    or pg_catalog.jsonb_typeof(p_candidate -> 'currentReleaseRevision')
      not in ('number', 'null') then
    raise exception using errcode = '22023', message = 'Preview installation command is invalid';
  end if;
  checked_context := vortex_module.assert_preview_installation_authority_internal();
  organization_id_value := (checked_context ->> 'organizationId')::uuid;
  organization_account_id_value := (checked_context ->> 'organizationAccountId')::uuid;
  identity_id_value := (checked_context ->> 'identityId')::uuid;
  if checked_context ->> 'applicationRootId' is distinct from p_application_root_id::text then
    raise exception using errcode = '42501', message = 'Preview installation context is unavailable';
  end if;

  compilation_value := p_candidate -> 'compilation';
  if compilation_value ->> 'kind' is distinct from 'application'
    or compilation_value #>> '{canonical,envelope,rootId}'
      is distinct from p_application_root_id::text then
    raise exception using errcode = '23514', message = 'Compiled Application candidate identity is invalid';
  end if;
  if pg_catalog.jsonb_typeof(
      compilation_value #> '{canonical,envelope,draftRevision}'
    ) is distinct from 'number' then
    raise exception using errcode = '23514', message = 'Compiled Application candidate revision is invalid';
  end if;
  begin
    draft_revision_value := (compilation_value #>> '{canonical,envelope,draftRevision}')::bigint;
  exception when invalid_text_representation then
    raise exception using errcode = '23514', message = 'Compiled Application candidate revision is invalid';
  end;
  if draft_revision_value <> p_expected_draft_revision
    or draft_revision_value not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(compilation_value #> '{resolvedDependencies}') <> 'array'
    or pg_catalog.jsonb_typeof(compilation_value #> '{canonical,content,moduleBindings}') <> 'array' then
    raise exception using errcode = '23514', message = 'Compiled Application candidate does not match its request';
  end if;

  select draft.draft_revision into draft_revision_value
  from vortex_definition.roots as root
  join vortex_definition.drafts as draft on draft.root_id = root.root_id
  where root.root_id = p_application_root_id
    and root.organization_id = organization_id_value
    and root.kind = 'application'
  for share of draft;
  if not found or draft_revision_value <> p_expected_draft_revision then
    raise exception using errcode = '40001', message = 'Application draft revision changed';
  end if;

  select pg_catalog.count(*) into binding_count
  from pg_catalog.jsonb_array_elements(
    compilation_value #> '{canonical,content,moduleBindings}'
  ) as item(value);
  select pg_catalog.count(*) into resolution_count
  from pg_catalog.jsonb_array_elements(compilation_value -> 'resolvedDependencies') as item(value)
  where item.value ->> 'kind' = 'module';
  if binding_count <> resolution_count or exists (
    select 1
    from pg_catalog.jsonb_array_elements(
      compilation_value #> '{canonical,content,moduleBindings}'
    ) as binding(value)
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements(compilation_value -> 'resolvedDependencies') as resolved(value)
      where resolved.value ->> 'kind' = 'module'
        and resolved.value ->> 'rootId' = binding.value ->> 'moduleRootId'
        and resolved.value ->> 'exactVersion' = binding.value ->> 'resolvedVersion'
    )
  ) or (
    select pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'moduleRootId')
    from pg_catalog.jsonb_array_elements(
      compilation_value #> '{canonical,content,moduleBindings}'
    ) as item(value)
  ) or (
    select pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'rootId')
    from pg_catalog.jsonb_array_elements(compilation_value -> 'resolvedDependencies') as item(value)
    where item.value ->> 'kind' = 'module'
  ) then
    raise exception using errcode = '23514', message = 'Compiled Application Module evidence is inconsistent';
  end if;

  perform vortex_module.expire_preview_installations(100);
  preview_installation_id_value := pg_catalog.gen_random_uuid();
  created_at_value := pg_catalog.statement_timestamp();
  expires_at_value := created_at_value + preview_lifetime;
  insert into vortex_module.preview_installations (
    preview_installation_id, organization_id, application_root_id,
    draft_revision, previewer_identity_id, previewer_organization_account_id, candidate,
    resolved_modules, storage_identities, created_at, expires_at
  ) values (
    preview_installation_id_value, organization_id_value, p_application_root_id,
    p_expected_draft_revision, identity_id_value, organization_account_id_value, p_candidate,
    '[]'::jsonb, '[]'::jsonb, created_at_value, expires_at_value
  );

  with recursive module_closure(module_root_id, release_version) as (
    select (binding.value ->> 'moduleRootId')::uuid, binding.value ->> 'resolvedVersion'
    from pg_catalog.jsonb_array_elements(
      compilation_value #> '{canonical,content,moduleBindings}'
    ) as binding(value)
    union
    select (dependency.value ->> 'moduleRootId')::uuid,
      dependency.value ->> 'resolvedVersion'
    from module_closure as parent
    join vortex_definition.releases as release
      on release.root_id = parent.module_root_id
      and release.release_version = parent.release_version
    cross join lateral pg_catalog.jsonb_array_elements(
      release.compilation_output #> '{canonical,content,dependencies}'
    ) as dependency(value)
  )
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'moduleRootId', closure.module_root_id,
        'releaseVersion', closure.release_version
      ) order by closure.module_root_id, closure.release_version
    ),
    '[]'::jsonb
  ) into module_closure
  from module_closure as closure;

  for module_dependency in
    select item.value
    from pg_catalog.jsonb_array_elements(module_closure) as item(value)
    order by item.value ->> 'moduleRootId', item.value ->> 'releaseVersion'
  loop
    begin
      module_root_id_value := (module_dependency ->> 'moduleRootId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '23514', message = 'Compiled Module identity is invalid';
    end;
    if not vortex_context.is_non_nil_uuid(module_root_id_value::text)
      or module_dependency ->> 'releaseVersion' is null then
      raise exception using errcode = '23514', message = 'Compiled Module release is invalid';
    end if;
    select release.release_revision into strict module_release_revision
    from vortex_definition.releases as release
    join vortex_definition.roots as root on root.root_id = release.root_id
    where release.root_id = module_root_id_value
      and release.release_version = module_dependency ->> 'releaseVersion'
      and root.kind = 'module';
    resolved_modules_value := resolved_modules_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'moduleRootId', module_root_id_value,
        'moduleReleaseRevision', module_release_revision,
        'releaseVersion', module_dependency ->> 'releaseVersion'
      )
    );
    storage_identities_value := storage_identities_value || vortex_record.provision_preview_module_storage(
      preview_installation_id_value, module_root_id_value, module_release_revision
    );
  end loop;

  update vortex_module.preview_installations as preview
  set resolved_modules = resolved_modules_value,
      storage_identities = storage_identities_value
  where preview.preview_installation_id = preview_installation_id_value;

  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_installation_id_value,
    'organizationId', organization_id_value,
    'applicationRootId', p_application_root_id,
    'draftRevision', p_expected_draft_revision,
    'previewerIdentityId', identity_id_value,
    'previewerOrganizationAccountId', organization_account_id_value,
    'candidate', p_candidate,
    'resolvedModules', resolved_modules_value,
    'storageIdentities', storage_identities_value,
    'createdAt', created_at_value,
    'expiresAt', expires_at_value
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Exact Application or Module evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Exact Application or Module evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.create_preview_installation(p_application_root_id uuid, p_expected_draft_revision bigint, p_candidate jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION create_preview_installation(p_application_root_id uuid, p_expected_draft_revision bigint, p_candidate jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.create_preview_installation(p_application_root_id uuid, p_expected_draft_revision bigint, p_candidate jsonb) IS 'Creates a 24-hour preview of one current Application draft, with fresh isolated storage for its exact published Module dependencies and no live installation registrations.';


--
-- Name: detach_application_installation(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.detach_application_installation(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  pin record;
  expected_count integer;
  pin_count integer;
  all_active boolean;
  all_provisioned boolean;
  all_detached boolean;
  changed_value boolean;
  binding_evidence jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId')::uuid =
          '00000000-0000-0000-0000-000000000000'::uuid
        or (item.value ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Application installation detach command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release on release.root_id = root.root_id
    where root.root_id = p_application_root_id
      and root.organization_id = initial_authority.organization_id
      and root.kind = 'application'
      and release.release_revision = p_application_release_revision
      and release.validation_contract_version = any (vortex_definition.accepted_contract_version('application'))
      and release.compilation_output #>> '{kind}' = 'application'
      and release.compilation_output #>> '{canonical,envelope,rootId}' = p_application_root_id::text
      and release.compilation_output #>> '{validationContractVersion}' = any (vortex_definition.accepted_contract_version('application'))
  ) then
    raise exception using errcode = 'P0002',
      message = 'Exact Application release is unavailable';
  end if;

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if pin_count = 0 or expected_count <> pin_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Application installation binding set is incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_module.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
    perform 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Application installation authority changed';
  end if;

  -- Each accepted state must hold for the complete exact set; mixed states are refused.
  select pg_catalog.bool_and(coalesce(
      binding.state = 'active'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'provisioned'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'detached'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    ))
  into all_active, all_provisioned, all_detached
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  left join vortex_module.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id
  left join lateral (
    select (expected.value ->> 'bindingRevision')::bigint as binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
  ) as expected on true
  ;
  if all_active is null or (not all_active and not all_provisioned and not all_detached)
    or exists (
      select 1 from vortex_module.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.state <> 'detached'
        and not exists (
          select 1 from vortex_definition.reachable_module_dependency_edges(
            p_application_root_id, p_application_release_revision
          ) as required
          where required.target_root_id = binding.module_root_id
        )
    ) then
    raise exception using errcode = '40001',
      message = 'Application installation bindings changed or are incomplete';
  end if;

  changed_value := all_active or all_provisioned;
  if changed_value then
    if exists (
      select 1 from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      join vortex_module.installation_bindings as binding
        on binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.module_root_id = required.target_root_id
      where binding.binding_revision = 9007199254740991
    ) then
      raise exception using errcode = '22003',
        message = 'Application installation binding revision is exhausted';
    end if;
    update vortex_module.installation_bindings as binding
    set state = 'detached', binding_revision = binding.binding_revision + 1,
      changed_at = pg_catalog.statement_timestamp()
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = required.target_root_id
      and binding.state in ('active', 'provisioned');
    if not found then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed';
    end if;
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'organizationId', binding.organization_id,
    'applicationRootId', binding.application_root_id,
    'moduleRootId', binding.module_root_id,
    'bindingRevision', binding.binding_revision,
    'applicationReleaseRevision', binding.application_release_revision,
    'moduleReleaseRevision', binding.module_release_revision,
    'state', binding.state
  ) order by binding.module_root_id) into binding_evidence
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  join vortex_module.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'state', 'detached', 'changed', changed_value,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application installation evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Application installation detach command is invalid';
end
$function$;


ALTER FUNCTION vortex_module.detach_application_installation(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION detach_application_installation(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.detach_application_installation(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Revision-checked atomic detach of one complete Application Module binding set while retaining storage and records.';


--
-- Name: discard_preview_installation(uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.discard_preview_installation(
  p_preview_installation_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  preview_row vortex_module.preview_installations%rowtype;
begin
  if not vortex_context.is_non_nil_uuid(p_preview_installation_id::text) then
    raise exception using errcode = '22023', message = 'Preview installation identity is invalid';
  end if;
  checked_context := vortex_module.assert_preview_installation_authority_internal();
  select preview.* into preview_row
  from vortex_module.preview_installations as preview
  where preview.preview_installation_id = p_preview_installation_id
    and preview.organization_id = (checked_context ->> 'organizationId')::uuid
    and preview.previewer_identity_id = (checked_context ->> 'identityId')::uuid
    and preview.previewer_organization_account_id =
      (checked_context ->> 'organizationAccountId')::uuid
    and preview.application_root_id = (checked_context ->> 'applicationRootId')::uuid
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Preview installation is unavailable';
  end if;
  perform vortex_record.drop_preview_installation_storage(
    preview_row.preview_installation_id
  );
  delete from vortex_module.preview_installations as preview
  where preview.preview_installation_id = preview_row.preview_installation_id;
  return pg_catalog.jsonb_build_object(
    'discarded', true,
    'previewInstallationId', preview_row.preview_installation_id
  );
end
$function$;


ALTER FUNCTION vortex_module.discard_preview_installation(p_preview_installation_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION discard_preview_installation(p_preview_installation_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.discard_preview_installation(p_preview_installation_id uuid) IS 'Immediately drops a preview installation and its isolated Record storage, only for the creating organisation account.';


--
-- Name: drain_installation(uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.drain_installation(
  p_activity_id uuid,
  p_root_id uuid,
  p_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  target_kind text;
  application_release vortex_definition.releases%rowtype;
  pin record;
  expected_count integer;
  pin_count integer;
  all_active boolean;
  all_draining boolean;
  changed_value boolean;
  binding_evidence jsonb;
begin
  if p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_root_id is null
    or p_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId')::uuid =
          '00000000-0000-0000-0000-000000000000'::uuid
        or (item.value ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Installation drain command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  select root.kind into target_kind
  from vortex_definition.roots as root
  where root.root_id = p_root_id
    and root.organization_id = initial_authority.organization_id;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Installation is unavailable';
  end if;

  -- A Module is never installed on its own; its storage and records exist because an
  -- installed Application binds that exact release. Uninstalling a Module an installed
  -- Application still depends on is refused.
  if target_kind = 'module' then
    if exists (
      select 1 from vortex_module.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.module_root_id = p_root_id
        and binding.state in ('provisioned', 'active', 'draining')
    ) then
      raise exception using errcode = '42501',
        message = 'Installation is required by an installed application';
    end if;
    raise exception using errcode = 'P0002',
      message = 'Installation is unavailable';
  end if;

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where root.root_id = p_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application'
    and release.release_revision = p_release_revision
    and release.validation_contract_version = any (vortex_definition.accepted_contract_version('application'))
    and release.compilation_output #>> '{kind}' = 'application'
    and release.compilation_output #>> '{canonical,envelope,rootId}' = p_root_id::text
    and release.compilation_output #>> '{validationContractVersion}' = any (vortex_definition.accepted_contract_version('application'));

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision);
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if pin_count = 0 or expected_count <> pin_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
      where not exists (
        select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Installation binding set is incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_module.binding:' || initial_authority.organization_id::text || ':' ||
          p_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
    perform 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_root_id
      and binding.module_root_id = pin.target_root_id
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Installation authority changed';
  end if;

  select pg_catalog.bool_and(coalesce(
      binding.state = 'active'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'draining'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    ))
  into all_active, all_draining
  from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
  left join vortex_module.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_root_id
    and binding.module_root_id = required.target_root_id
  left join lateral (
    select (expected.value ->> 'bindingRevision')::bigint as binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
  ) as expected on true;
  if all_active is null or (not all_active and not all_draining)
    or exists (
      select 1 from vortex_module.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_root_id
        and binding.state <> 'detached'
        and not exists (
          select 1
          from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
          where required.target_root_id = binding.module_root_id
        )
    ) then
    raise exception using errcode = '40001',
      message = 'Installation bindings changed or are incomplete';
  end if;

  changed_value := all_active;
  if changed_value then
    if exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
      join vortex_module.installation_bindings as binding
        on binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_root_id
        and binding.module_root_id = required.target_root_id
      where binding.binding_revision = 9007199254740991
    ) then
      raise exception using errcode = '22003',
        message = 'Installation binding revision is exhausted';
    end if;
    update vortex_module.installation_bindings as binding
    set state = 'draining', binding_revision = binding.binding_revision + 1,
      changed_at = pg_catalog.statement_timestamp()
    from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_root_id
      and binding.module_root_id = required.target_root_id
      and binding.state = 'active';
    if not found then
      raise exception using errcode = '40001',
        message = 'Installation bindings changed';
    end if;
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'organizationId', binding.organization_id,
    'applicationRootId', binding.application_root_id,
    'moduleRootId', binding.module_root_id,
    'bindingRevision', binding.binding_revision,
    'applicationReleaseRevision', binding.application_release_revision,
    'moduleReleaseRevision', binding.module_release_revision,
    'state', binding.state
  ) order by binding.module_root_id) into binding_evidence
  from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
  join vortex_module.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_root_id
    and binding.module_root_id = required.target_root_id;

  if changed_value then
    perform vortex_module.append_application_installation_activity_internal(
      p_activity_id, p_root_id, 'drain_application_installation'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_root_id,
    'applicationReleaseRevision', p_release_revision,
    'state', 'draining', 'changed', changed_value,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installation evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Installation drain command is invalid';
end
$function$;


ALTER FUNCTION vortex_module.drain_installation(p_activity_id uuid, p_root_id uuid, p_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION drain_installation(p_activity_id uuid, p_root_id uuid, p_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.drain_installation(p_activity_id uuid, p_root_id uuid, p_release_revision bigint, p_expected_module_bindings jsonb) IS 'Protected first uninstall step: moves one exact active Application installation to draining, or refuses a Module an installed Application depends on, recording Activity from the trusted channel.';


--
-- Name: expire_preview_installations(integer); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.expire_preview_installations(
  p_limit integer
)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  preview_row record;
  expired_count integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'Preview expiry batch size is invalid';
  end if;
  checked_context := vortex_module.assert_preview_installation_authority_internal();
  for preview_row in
    select preview.preview_installation_id
    from vortex_module.preview_installations as preview
    where preview.organization_id = (checked_context ->> 'organizationId')::uuid
      and preview.expires_at <= pg_catalog.statement_timestamp()
    order by preview.expires_at, preview.preview_installation_id
    limit p_limit
    for update skip locked
  loop
    perform vortex_record.drop_preview_installation_storage(
      preview_row.preview_installation_id
    );
    delete from vortex_module.preview_installations as preview
    where preview.preview_installation_id = preview_row.preview_installation_id;
    expired_count := expired_count + 1;
  end loop;
  return expired_count;
end
$function$;


ALTER FUNCTION vortex_module.expire_preview_installations(p_limit integer) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION expire_preview_installations(p_limit integer); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.expire_preview_installations(p_limit integer) IS 'Purges a bounded batch of expired preview installations in the current human organisation, including their isolated Record storage.';


--
-- Name: has_active_application_release_binding_internal(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.has_active_application_release_binding_internal(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_application_release_revision bigint
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select exists (
    select 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = p_organization_id
      and binding.application_root_id = p_application_root_id
      and binding.application_release_revision = p_application_release_revision
      and binding.state = 'active'
  );
$function$;


ALTER FUNCTION vortex_module.has_active_application_release_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION has_active_application_release_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.has_active_application_release_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint) IS 'Private exact active Application release binding existence predicate for owner-controlled installation decisions; returns no binding rows or authority.';


--
-- Name: is_current_application_address_release(bigint); Type: FUNCTION; Schema: vortex_module; Owner: postgres
--

create or replace function vortex_module.is_current_application_address_release(
  p_release_revision bigint
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  installation_value jsonb;
begin
  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId'
    or p_release_revision not between 1 and 9007199254740991 then
    return false;
  end if;
  installation_value := vortex_module.read_current_active_installation();
  return (installation_value ->> 'applicationReleaseRevision')::bigint = p_release_revision
    and exists (
    select 1
    from vortex_access.permission_registrations as registration
    where registration.organization_id = (context_value ->> 'organizationId')::uuid
      and registration.registration_kind = 'application'
      and registration.registration_owner_id =
        (context_value ->> 'applicationRootId')::uuid
      and registration.state = 'active'
      and registration.source_revision = p_release_revision
  );
exception
  when sqlstate 'P0002' or sqlstate '55000' or sqlstate '23514' then
    return false;
end
$function$;


ALTER FUNCTION vortex_module.is_current_application_address_release(p_release_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION is_current_application_address_release(p_release_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: postgres
--

COMMENT ON FUNCTION vortex_module.is_current_application_address_release(p_release_revision bigint) IS 'Checks an internal candidate release against the exact active registration and binding in the validated human application context.';


--
-- Name: lock_active_installation_runtime_mapping_internal(jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity jsonb)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare
  checked_context jsonb;
  selected_org uuid;
  selected_app uuid;
  selected_revision bigint;
  active_count integer;
  registered_app record;
  registered_identity jsonb;
  bindings jsonb;
  pin_facts jsonb;
  pin_hash text;
  identity_value jsonb;
  before_identity jsonb;
  item jsonb;
  installation jsonb;
  application_evidence jsonb;
  module_evidence jsonb;
  release_identity jsonb;
begin
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_module.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_module.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  if p_expected_identity is distinct from identity_value then
    raise exception using errcode='40001', message='Active Application identity changed';
  end if;
  before_identity:=identity_value;
  for item in select pin.value from pg_catalog.jsonb_array_elements(bindings) as pin(value)
    order by (pin.value ->> 'moduleRootId')::uuid
  loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'vortex_module.binding:' || selected_org::text || ':' || selected_app::text || ':' ||
        (item ->> 'moduleRootId'),0));
    perform 1 from vortex_module.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.module_root_id=(item ->> 'moduleRootId')::uuid for update;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_module.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_module.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
    if identity_value is distinct from before_identity then
      raise exception using errcode='40001', message='Active Application identity changed while waiting';
    end if;
  end loop;
  installation:=vortex_module.read_active_installation_for_scope_internal(selected_org,selected_app);
  if (installation ->> 'applicationReleaseRevision')::bigint is distinct from selected_revision
    or exists(select 1 from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as current(value)
      where not exists(select 1 from pg_catalog.jsonb_array_elements(bindings) as expected(value)
        where current.value -> 'moduleRootId'=expected.value -> 'moduleRootId'
          and current.value -> 'moduleReleaseRevision'=expected.value -> 'moduleReleaseRevision'
          and current.value -> 'bindingRevision'=expected.value -> 'bindingRevision'
          and current.value ->> 'state'='active'))
    or pg_catalog.jsonb_array_length(installation -> 'moduleBindings')<>active_count then
    raise exception using errcode='40001', message='Active Application pin closure changed';
  end if;
  application_evidence:=vortex_definition.project_consumer_release_evidence('application',selected_app,selected_revision);
  release_identity:=pg_catalog.jsonb_build_object(
    'rootId',application_evidence -> 'rootId','definitionKey',application_evidence -> 'key',
    'releaseRevision',application_evidence -> 'releaseRevision','releaseVersion',application_evidence -> 'releaseVersion',
    'validationContractVersion',application_evidence -> 'validationContractVersion',
    'contentFingerprint',application_evidence -> 'contentFingerprint',
    'resolutionFingerprint',application_evidence -> 'resolutionFingerprint');
  if application_evidence ->> 'kind' is distinct from 'application'
    or (application_evidence ->> 'organizationId')::uuid is distinct from selected_org
    or release_identity is distinct from registered_identity then
    raise exception using errcode='23514', message='Active Application publication differs';
  end if;
  select pg_catalog.jsonb_agg(vortex_definition.project_consumer_release_evidence(
    'module',(pin.value ->> 'moduleRootId')::uuid,(pin.value ->> 'moduleReleaseRevision')::bigint)
    order by (pin.value ->> 'moduleRootId')::uuid)
  into module_evidence from pg_catalog.jsonb_array_elements(bindings) as pin(value);
  if pg_catalog.jsonb_array_length(module_evidence)<>active_count or exists(
    select 1 from pg_catalog.jsonb_array_elements(module_evidence) as module(value)
    where module.value ->> 'kind' is distinct from 'module'
      or (module.value ->> 'organizationId')::uuid is distinct from selected_org
      or not exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
        where pin.value -> 'moduleRootId'=module.value -> 'rootId'
          and pin.value -> 'moduleReleaseRevision'=module.value -> 'releaseRevision'
          and pin.value -> 'contentFingerprint'=module.value -> 'contentFingerprint'
          and pin.value -> 'resolutionFingerprint'=module.value -> 'resolutionFingerprint')) then
    raise exception using errcode='23514', message='Active Module publication differs';
  end if;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_module.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_module.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  if identity_value is distinct from before_identity then
    raise exception using errcode='40001', message='Active Application mapping changed';
  end if;
  return pg_catalog.jsonb_build_object('identity',identity_value,'installation',installation,
    'application',application_evidence,'modules',module_evidence);
exception when no_data_found or too_many_rows then
  raise exception using errcode='P0002', message='Active Application mapping is unavailable';
end
$function$;


ALTER FUNCTION vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION lock_active_installation_runtime_mapping_internal(p_expected_identity jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity jsonb) IS 'Locks and proves exact active publication mapping under the current HUMAN request; expected identity is only a guard.';


--
-- Name: lock_prepared_installation_runtime_mapping_internal(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.lock_prepared_installation_runtime_mapping_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  none_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  initial_authority record;
  current_authority record;
  registration_revision bigint;
  required_count integer;
  expected_count integer;
  binding_item jsonb;
  pin_facts jsonb;
  binding_facts jsonb;
  pin_fingerprint text;
begin
  if p_application_root_id is null or p_application_root_id = none_uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) < 1
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) is distinct from 'object'
        or not item.value ?& array[
          'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state'
        ]
        or item.value - array[
          'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state'
        ] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId') !~* '^[0-9a-f-]{36}$'
        or (item.value ->> 'moduleReleaseRevision') !~ '^[1-9][0-9]*$'
        or (item.value ->> 'bindingRevision') !~ '^[1-9][0-9]*$'
        or item.value ->> 'state' is distinct from 'provisioned'
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Prepared installation mapping command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  select snapshot.release_revision into registration_revision
  from vortex_access.read_application_permission_snapshot(
    initial_authority.organization_id, p_application_root_id
  ) as snapshot;
  if registration_revision is distinct from p_application_release_revision then
    raise exception using errcode = '42501',
      message = 'Prepared installation registration is unavailable';
  end if;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = p_application_release_revision
    where root.root_id = p_application_root_id
      and root.organization_id = initial_authority.organization_id
      and root.kind = 'application'
      and release.validation_contract_version = any (
        vortex_definition.accepted_contract_version('application')
      )
      and release.compilation_output #>> '{kind}' = 'application'
      and release.compilation_output #>> '{canonical,envelope,rootId}' = p_application_root_id::text
      and release.compilation_output #>> '{validationContractVersion}' = any (
        vortex_definition.accepted_contract_version('application')
      )
  ) then
    raise exception using errcode = 'P0002',
      message = 'Prepared installation Application release is unavailable';
  end if;

  select pg_catalog.count(*)::integer into required_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if required_count = 0 or expected_count <> required_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
          and (expected.value ->> 'moduleReleaseRevision')::bigint = required.target_release_revision
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Prepared installation pin set is incomplete';
  end if;

  for binding_item in
    select item.value
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    order by (item.value ->> 'moduleRootId')::uuid
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_module.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || (binding_item ->> 'moduleRootId'),
        0
      )
    );
    perform 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = (binding_item ->> 'moduleRootId')::uuid
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Prepared installation authority changed';
  end if;

  if exists (
    select 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.state <> 'detached'
      and not exists (
        select 1
        from vortex_definition.reachable_module_dependency_edges(
          p_application_root_id, p_application_release_revision
        ) as required
        where required.target_root_id = binding.module_root_id
      )
  ) or exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    left join vortex_module.installation_bindings as binding
      on binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = required.target_root_id
    left join lateral (
      select (expected.value ->> 'bindingRevision')::bigint as binding_revision
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
      where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
        and (expected.value ->> 'moduleReleaseRevision')::bigint = required.target_release_revision
    ) as expected on true
    where binding.state is distinct from 'provisioned'
      or binding.application_release_revision is distinct from p_application_release_revision
      or binding.module_release_revision is distinct from required.target_release_revision
      or binding.binding_revision is distinct from expected.binding_revision
  ) then
    raise exception using errcode = '40001',
      message = 'Prepared installation binding set changed';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId', pin.target_root_id,
      'moduleReleaseRevision', pin.target_release_revision,
      'contentFingerprint', release.content_fingerprint,
      'resolutionFingerprint', release.resolution_fingerprint
    ) order by pin.target_root_id)
  into pin_facts
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as pin
  join vortex_definition.releases as release
    on release.root_id = pin.target_root_id
    and release.release_revision = pin.target_release_revision;
  if pin_facts is null or pg_catalog.jsonb_array_length(pin_facts) <> required_count then
    raise exception using errcode = '55000',
      message = 'Prepared installation source pins are unavailable';
  end if;
  pin_fingerprint := 'sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text, 'UTF8')),
    'hex'
  );

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId', binding.module_root_id,
      'moduleReleaseRevision', binding.module_release_revision,
      'bindingRevision', binding.binding_revision,
      'state', binding.state
    ) order by binding.module_root_id)
  into binding_facts
  from vortex_module.installation_bindings as binding
  where binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'provisioned';
  if binding_facts is distinct from p_expected_module_bindings then
    raise exception using errcode = '40001',
      message = 'Prepared installation expected bindings changed';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'organizationAccountId', initial_authority.organization_account_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'accessVersion', initial_authority.access_version,
    'correlationId', initial_authority.correlation_id,
    'registeredReleaseRevision', registration_revision,
    'pinFingerprint', pin_fingerprint,
    'pinFacts', pin_facts,
    'moduleBindings', binding_facts
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Prepared installation mapping evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared installation mapping evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.lock_prepared_installation_runtime_mapping_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION lock_prepared_installation_runtime_mapping_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.lock_prepared_installation_runtime_mapping_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Locks the current human installation authority and exact complete provisioned Module pin mapping for first-install runtime preparation.';


--
-- Name: lock_storage_adoption_binding_internal(uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  own_binding vortex_module.installation_bindings%rowtype;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_source_release_revision is null
    or p_source_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Storage adoption binding command is invalid';
  end if;

  -- The same identity and order every binding writer uses, so this never
  -- interleaves with a provision, activation or detach of the same binding.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_module.binding:' || p_organization_id::text || ':' ||
        p_application_root_id::text || ':' || p_module_root_id::text,
      0
    )
  );

  select binding.* into own_binding
  from vortex_module.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = p_module_root_id
  for update;
  if not found
    or own_binding.module_release_revision <> p_source_release_revision
    or not (p_storage_contract_id = any (own_binding.storage_contract_ids)) then
    raise exception using errcode = '55000',
      message = 'Storage adoption installation does not install the source release';
  end if;
  -- An installation still using the source field cannot lose it.
  if own_binding.state <> 'detached' then
    raise exception using errcode = '55006',
      message = 'Storage adoption installation is still using the source storage';
  end if;
end
$$;


ALTER FUNCTION vortex_module.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) IS 'Private storage adoption fact: locks the caller''s own binding in canonical order and requires it detached at the exact source release.';


--
-- Name: provision_module_contribution_storage(uuid, bigint, uuid, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.provision_module_contribution_storage(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_module_root_id uuid,
  p_module_release_revision bigint,
  p_expected_binding_revision bigint,
  p_contribution_mode text,
  p_contributions jsonb
)
returns table (
  state text,
  changed boolean,
  binding_revision bigint,
  application_root_id uuid,
  application_release_revision bigint,
  module_root_id uuid,
  module_release_revision bigint,
  contribution_ids uuid[]
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  permission_decision record;
  delegation_decision record;
  checked_context jsonb;
  application_release vortex_definition.releases%rowtype;
  stored_binding vortex_module.installation_bindings%rowtype;
  provision record;
  retire_contributions boolean;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision not between 1 and 9007199254740991
    or (p_expected_binding_revision is not null
      and p_expected_binding_revision not between 1 and 9007199254740991)
    or p_contribution_mode is null
    or p_contribution_mode not in ('attach', 'detach')
    or pg_catalog.jsonb_typeof(p_contributions) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_contributions) < 1
    or pg_catalog.jsonb_array_length(p_contributions) > 100 then
    raise exception using errcode = '22023',
      message = 'Module contribution storage command is invalid';
  end if;

  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible' then
    raise exception using errcode = '42501', message = 'Module installation authority is unavailable';
  end if;

  select evaluated.* into strict delegation_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  if delegation_decision.outcome is distinct from 'eligible'
    or delegation_decision.organization_id <> permission_decision.organization_id
    or delegation_decision.organization_account_id <> permission_decision.organization_account_id
    or delegation_decision.access_version <> permission_decision.access_version
    or delegation_decision.correlation_id <> permission_decision.correlation_id then
    raise exception using errcode = '42501', message = 'Module installation delegation is unavailable';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '40001', message = 'Module installation context changed';
  end if;

  -- The binding identity is locked before its stored lineage can change, exactly
  -- as the installation storage provisioner does.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_module.binding:' || permission_decision.organization_id::text || ':' ||
        p_application_root_id::text || ':' || p_module_root_id::text,
      0
    )
  );

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_application_root_id
    and release.release_revision = p_application_release_revision
    and root.kind = 'application'
    and root.organization_id = permission_decision.organization_id;
  if application_release.validation_contract_version
      <> all (vortex_definition.accepted_contract_version('application'))
    or application_release.compilation_output #>> '{kind}' <> 'application'
    or application_release.compilation_output #>> '{canonical,envelope,rootId}'
      <> p_application_root_id::text
    or application_release.compilation_output #>> '{validationContractVersion}'
      <> all (vortex_definition.accepted_contract_version('application')) then
    raise exception using errcode = '23514', message = 'Exact Application release is unavailable';
  end if;
  if not exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as edge
    where edge.target_root_id = p_module_root_id
      and edge.target_release_revision = p_module_release_revision
  ) then
    raise exception using errcode = '23514',
      message = 'Exact application Module binding is unavailable';
  end if;

  select binding.* into stored_binding
  from vortex_module.installation_bindings as binding
  where binding.organization_id = permission_decision.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = p_module_root_id
  for update;
  if not found
    or stored_binding.application_release_revision <> p_application_release_revision
    or stored_binding.module_release_revision <> p_module_release_revision
    or (p_expected_binding_revision is not null
      and stored_binding.binding_revision <> p_expected_binding_revision)
    or (p_contribution_mode = 'attach' and stored_binding.state = 'detached') then
    raise exception using errcode = '40001',
      message = 'Module installation binding changed';
  end if;

  -- Every target is the exact dependency release this Application release
  -- pins; an attach also needs the target's own storage installed here.
  if exists (
    with edges as (
      select edge.target_root_id, edge.target_release_revision
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as edge
    )
    select 1
    from pg_catalog.jsonb_array_elements(p_contributions) as item(value)
    where not exists (
      select 1
      from edges
      join vortex_definition.releases as release
        on release.root_id = edges.target_root_id
        and release.release_revision = edges.target_release_revision
      where edges.target_root_id::text = pg_catalog.lower(item.value ->> 'targetModuleRootId')
        and edges.target_root_id <> p_module_root_id
        and release.release_version = item.value ->> 'targetModuleReleaseVersion'
        and (
          p_contribution_mode = 'detach'
          or exists (
            select 1
            from vortex_module.installation_bindings as target_binding
            where target_binding.organization_id = permission_decision.organization_id
              and target_binding.application_root_id = p_application_root_id
              and target_binding.module_root_id = edges.target_root_id
              and target_binding.module_release_revision = edges.target_release_revision
              and target_binding.state <> 'detached'
          )
        )
    )
  ) then
    raise exception using errcode = '23514',
      message = 'Exact application target Module binding is unavailable';
  end if;

  -- Contributed field mappings live on shared target storage. One lock per
  -- contributor serialises attach and detach across organisations, so a
  -- detach sees every committed installation that still uses the mappings.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('vortex_module.contribution:' || p_module_root_id::text, 0)
  );

  if p_contribution_mode = 'attach' then
    select storage.* into strict provision
    from vortex_record.provision_exact_module_contributions(
      p_module_root_id, p_module_release_revision, p_contributions
    ) as storage;
    return query select 'attached'::text, provision.changed,
      stored_binding.binding_revision, stored_binding.application_root_id,
      stored_binding.application_release_revision, stored_binding.module_root_id,
      stored_binding.module_release_revision, provision.contribution_ids;
    return;
  end if;

  -- Another live installation of the contributor keeps its mappings active;
  -- the last one retires them. Columns and values are retained either way.
  retire_contributions := not exists (
    select 1
    from vortex_module.installation_bindings as other_binding
    where other_binding.module_root_id = p_module_root_id
      and other_binding.state <> 'detached'
      and (other_binding.organization_id, other_binding.application_root_id)
        <> (permission_decision.organization_id, p_application_root_id)
  );
  select storage.* into strict provision
  from vortex_record.detach_exact_module_contributions(
    p_module_root_id, p_module_release_revision, p_contributions, retire_contributions
  ) as storage;
  return query select 'detached'::text, provision.changed,
    stored_binding.binding_revision, stored_binding.application_root_id,
    stored_binding.application_release_revision, stored_binding.module_root_id,
    stored_binding.module_release_revision, provision.contribution_ids;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Module contribution evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Module contribution evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.provision_module_contribution_storage(p_application_root_id uuid, p_application_release_revision bigint, p_module_root_id uuid, p_module_release_revision bigint, p_expected_binding_revision bigint, p_contribution_mode text, p_contributions jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION provision_module_contribution_storage(p_application_root_id uuid, p_application_release_revision bigint, p_module_root_id uuid, p_module_release_revision bigint, p_expected_binding_revision bigint, p_contribution_mode text, p_contributions jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.provision_module_contribution_storage(p_application_root_id uuid, p_application_release_revision bigint, p_module_root_id uuid, p_module_release_revision bigint, p_expected_binding_revision bigint, p_contribution_mode text, p_contributions jsonb) IS 'Protected exact-release contributor storage attach or detach; attaches the resolved additive bindings to their target storage, or retires them while retaining every column and value.';


--
-- Name: provision_module_installation_storage(uuid, bigint, uuid, bigint, bigint); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.provision_module_installation_storage(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_module_root_id uuid,
  p_module_release_revision bigint,
  p_expected_binding_revision bigint
)
returns table (
  state text,
  changed boolean,
  binding_revision bigint,
  application_root_id uuid,
  application_release_revision bigint,
  module_root_id uuid,
  module_release_revision bigint,
  storage_contract_ids uuid[]
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  permission_decision record;
  delegation_decision record;
  checked_context jsonb;
  application_release vortex_definition.releases%rowtype;
  stored_binding vortex_module.installation_bindings%rowtype;
  provision record;
  next_binding_revision bigint;
  binding_exists boolean;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision not between 1 and 9007199254740991
    or (p_expected_binding_revision is not null
      and p_expected_binding_revision not between 1 and 9007199254740991) then
    raise exception using errcode = '22023', message = 'Module installation storage command is invalid';
  end if;

  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible' then
    raise exception using errcode = '42501', message = 'Module installation authority is unavailable';
  end if;

  select evaluated.* into strict delegation_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  if delegation_decision.outcome is distinct from 'eligible'
    or delegation_decision.organization_id <> permission_decision.organization_id
    or delegation_decision.organization_account_id <> permission_decision.organization_account_id
    or delegation_decision.access_version <> permission_decision.access_version
    or delegation_decision.correlation_id <> permission_decision.correlation_id then
    raise exception using errcode = '42501', message = 'Module installation delegation is unavailable';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '40001', message = 'Module installation context changed';
  end if;

  -- The binding identity is locked before its row can exist. Storage lineage
  -- locks are acquired later by the Record helper in canonical UUID order.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_module.binding:' || permission_decision.organization_id::text || ':' ||
        p_application_root_id::text || ':' || p_module_root_id::text,
      0
    )
  );

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_application_root_id
    and release.release_revision = p_application_release_revision
    and root.kind = 'application'
    and root.organization_id = permission_decision.organization_id;
  if application_release.validation_contract_version <> all (vortex_definition.accepted_contract_version('application'))
    or application_release.compilation_output #>> '{kind}' <> 'application'
    or application_release.compilation_output #>> '{canonical,envelope,rootId}'
      <> p_application_root_id::text
    or application_release.compilation_output #>> '{validationContractVersion}' <> all (vortex_definition.accepted_contract_version('application')) then
    raise exception using errcode = '23514', message = 'Exact Application release is unavailable';
  end if;
  if not exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as edge
    where edge.target_root_id = p_module_root_id
      and edge.target_release_revision = p_module_release_revision
  ) then
    raise exception using errcode = '23514', message = 'Exact application Module binding is unavailable';
  end if;

  select binding.* into stored_binding
  from vortex_module.installation_bindings as binding
  where binding.organization_id = permission_decision.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = p_module_root_id
  for update;
  binding_exists := found;

  if binding_exists then
    if stored_binding.state in ('active', 'draining')
      or (
        p_expected_binding_revision is null
        and (
          stored_binding.application_release_revision <> p_application_release_revision
          or stored_binding.module_release_revision <> p_module_release_revision
          or stored_binding.state <> 'provisioned'
        )
      )
      or (
        p_expected_binding_revision is not null
        and stored_binding.binding_revision <> p_expected_binding_revision
      ) then
      raise exception using errcode = '40001', message = 'Module installation binding changed';
    end if;
  end if;
  if not binding_exists and p_expected_binding_revision is not null then
    raise exception using errcode = '40001', message = 'Module installation binding is unavailable';
  end if;

  select storage.* into strict provision
  from vortex_record.provision_exact_module_storage(
    p_module_root_id, p_module_release_revision
  ) as storage;

  if binding_exists
    and stored_binding.application_release_revision = p_application_release_revision
    and stored_binding.module_release_revision = p_module_release_revision
    and stored_binding.state = 'provisioned' then
    if stored_binding.storage_contract_ids <> provision.storage_contract_ids then
      raise exception using errcode = '55000', message = 'Stored Module installation evidence is incompatible';
    end if;
    return query select stored_binding.state, false, stored_binding.binding_revision,
      stored_binding.application_root_id, stored_binding.application_release_revision,
      stored_binding.module_root_id, stored_binding.module_release_revision,
      stored_binding.storage_contract_ids;
    return;
  end if;

  if binding_exists then
    if stored_binding.binding_revision = 9007199254740991 then
      raise exception using errcode = '22003', message = 'Module installation binding revision is exhausted';
    end if;
    next_binding_revision := stored_binding.binding_revision + 1;
    update vortex_module.installation_bindings as binding
    set binding_revision = next_binding_revision,
        application_release_revision = p_application_release_revision,
        module_release_revision = p_module_release_revision,
        state = 'provisioned',
        storage_contract_ids = provision.storage_contract_ids,
        changed_at = pg_catalog.statement_timestamp()
    where binding.organization_id = permission_decision.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = p_module_root_id
      and binding.binding_revision = p_expected_binding_revision;
    if not found then
      raise exception using errcode = '40001', message = 'Module installation binding changed';
    end if;
  else
    next_binding_revision := 1;
    insert into vortex_module.installation_bindings (
      organization_id, application_root_id, module_root_id, binding_revision,
      application_release_revision, module_release_revision, state,
      storage_contract_ids
    ) values (
      permission_decision.organization_id, p_application_root_id, p_module_root_id, 1,
      p_application_release_revision, p_module_release_revision, 'provisioned',
      provision.storage_contract_ids
    );
  end if;

  return query select 'provisioned'::text, true, next_binding_revision,
    p_application_root_id, p_application_release_revision, p_module_root_id,
    p_module_release_revision, provision.storage_contract_ids;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Module installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Module installation evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.provision_module_installation_storage(p_application_root_id uuid, p_application_release_revision bigint, p_module_root_id uuid, p_module_release_revision bigint, p_expected_binding_revision bigint) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION provision_module_installation_storage(p_application_root_id uuid, p_application_release_revision bigint, p_module_root_id uuid, p_module_release_revision bigint, p_expected_binding_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.provision_module_installation_storage(p_application_root_id uuid, p_application_release_revision bigint, p_module_root_id uuid, p_module_release_revision bigint, p_expected_binding_revision bigint) IS 'Protected exact-release storage provisioning; commits only an inactive Module binding.';


--
-- Name: read_active_installation_bundle_identity(); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_active_installation_bundle_identity()
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare
  checked_context jsonb;
  selected_org uuid;
  selected_app uuid;
  selected_revision bigint;
  active_count integer;
  registered_app record;
  registered_identity jsonb;
  bindings jsonb;
  pin_facts jsonb;
  pin_hash text;
  identity_value jsonb;
  before_identity jsonb;
  stored_bundle vortex_module.installation_runtime_bundles%rowtype;
  bundle_index jsonb;
  current_manifest jsonb;
  manifest_pins jsonb;
  mapping jsonb;
  stable_plan jsonb;
  active_source jsonb;
  source_manifest jsonb;
begin
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_module.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_module.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  before_identity:=identity_value;
  select stored.* into stored_bundle from vortex_module.installation_runtime_bundles as stored
  where stored.organization_id=selected_org and stored.application_root_id=selected_app
    and stored.application_release_revision=selected_revision and stored.bundle_format_version=2;
  if found then
    current_manifest:=stored_bundle.source_manifest;
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',module.value -> 'rootId','moduleReleaseRevision',module.value -> 'releaseRevision',
      'contentFingerprint',module.value -> 'contentFingerprint',
      'resolutionFingerprint',module.value -> 'resolutionFingerprint')
      order by (module.value ->> 'rootId')::uuid)
    into manifest_pins from pg_catalog.jsonb_array_elements(current_manifest -> 'modules') as module(value);
    if current_manifest ->> 'bundleFormatVersion' is distinct from '2'
      or current_manifest -> 'application' is distinct from registered_identity
      or current_manifest ->> 'pinFingerprint' is distinct from pin_hash
      or stored_bundle.pin_fingerprint is distinct from pin_hash
      or manifest_pins is distinct from pin_facts
      or pg_catalog.jsonb_typeof(current_manifest -> 'preparedRecordAccessPlan') is distinct from 'object'
      or current_manifest #>> '{preparedRecordAccessPlan,planKey}' is distinct from (
        'sha256:' || pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
          'vortex.installation-runtime-bundle.prepared-record-access-plan.v2|' ||
            selected_org::text || '|' || selected_app::text || '|' ||
            selected_revision::text || '|2|' || pin_hash,'UTF8')),'hex'))
      or current_manifest #>> '{preparedRecordAccessPlan,mappingFingerprint}' is null
      or (current_manifest #>> '{preparedRecordAccessPlan,planKey}') !~ '^sha256:[a-f0-9]{64}$'
      or (current_manifest #>> '{preparedRecordAccessPlan,mappingFingerprint}') !~ '^sha256:[a-f0-9]{64}$' then
      raise exception using errcode='23514', message='Active runtime bundle manifest differs';
    end if;
    bundle_index:=vortex_module.read_installation_runtime_bundle_index(selected_app,selected_revision,2);
  else
    -- Missing format2 takes a genuine locked active-only cold source path.
    -- The mapping locker derives identity inline and cannot recurse into this reader.
    mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(before_identity);
    stable_plan:=vortex_record.resolve_active_bundle_record_access_plan_internal(before_identity);
    active_source:=pg_catalog.jsonb_build_object(
      'organizationId',mapping #> '{identity,organizationId}',
      'applicationRootId',mapping #> '{identity,applicationRootId}',
      'applicationReleaseRevision',mapping #> '{identity,applicationReleaseRevision}',
      'accessVersion',mapping #> '{identity,accessVersion}',
      'correlationId',mapping #> '{identity,correlationId}',
      'pinFingerprint',mapping #> '{identity,pinFingerprint}',
      'mappingFingerprint',stable_plan -> 'mappingFingerprint',
      'moduleBindings',mapping #> '{identity,moduleBindings}',
      'application',mapping -> 'application','modules',mapping -> 'modules',
      'preparedRecordAccessPlan',stable_plan);
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', active_source #> '{application,rootId}',
      'definitionKey', active_source #> '{application,key}',
      'releaseRevision', active_source #> '{application,releaseRevision}',
      'releaseVersion', active_source #> '{application,releaseVersion}',
      'validationContractVersion', active_source #> '{application,validationContractVersion}',
      'contentFingerprint', active_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', active_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', active_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', active_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', active_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );

    active_source:=active_source || pg_catalog.jsonb_build_object('sourceManifest',source_manifest);
  end if;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_module.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_module.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  if identity_value is distinct from before_identity then
    raise exception using errcode='40001', message='Active runtime bundle identity changed';
  end if;
  return pg_catalog.jsonb_build_object('identity',identity_value,
    'bundleIndex',bundle_index,'repairNeeded',bundle_index is null,'coldSource',active_source);
exception when no_data_found or too_many_rows then
  raise exception using errcode='P0002', message='Active runtime bundle identity is unavailable';
end
$function$;


ALTER FUNCTION vortex_module.read_active_installation_bundle_identity() OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_active_installation_bundle_identity(); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_active_installation_bundle_identity() IS 'Returns fresh active format2 identity and index, or a private exact locked active cold source for the same HUMAN request; carries no viewer permission decision.';


--
-- Name: read_active_installation_for_scope_internal(uuid, uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_active_installation_for_scope_internal(
  p_organization_id uuid,
  p_application_root_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  selected_organization_id uuid;
  selected_application_root_id uuid;
  selected_application_release_revision bigint;
  selected_bindings jsonb;
begin
  if p_organization_id is null or p_application_root_id is null then
    raise exception using errcode = '22023', message = 'Active Application context is required';
  end if;
  selected_organization_id := p_organization_id;
  selected_application_root_id := p_application_root_id;

  select pg_catalog.min(binding.application_release_revision)
  into selected_application_release_revision
  from vortex_module.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.state = 'active';
  if selected_application_release_revision is null then
    raise exception using errcode = 'P0002', message = 'Active Application installation is unavailable';
  end if;
  if exists (
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'active'
      and binding.application_release_revision <> selected_application_release_revision
  ) then
    raise exception using errcode = '55000', message = 'Active Application installation is mixed';
  end if;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = selected_application_release_revision
    where root.root_id = selected_application_root_id
      and root.kind = 'application'
      and root.organization_id = selected_organization_id
      and release.compilation_output #>> '{kind}' = 'application'
  ) then
    raise exception using errcode = '23514', message = 'Active Application release evidence is invalid';
  end if;

  if not exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      selected_application_root_id, selected_application_release_revision
    )
  ) or exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      selected_application_root_id, selected_application_release_revision
    ) as node
    left join vortex_module.installation_bindings as binding
      on binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.module_root_id = node.target_root_id
    where binding.state is distinct from 'active'
      or binding.application_release_revision is distinct from selected_application_release_revision
      or binding.module_release_revision is distinct from node.target_release_revision
  ) or exists (
    select 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'active'
      and not exists (
        select 1
        from vortex_definition.reachable_module_dependency_edges(
          selected_application_root_id, selected_application_release_revision
        ) as node
        where node.target_root_id = binding.module_root_id
          and node.target_release_revision = binding.module_release_revision
      )
  ) then
    raise exception using errcode = '55000', message = 'Active Application Module bindings are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'organizationId', binding.organization_id,
      'applicationRootId', binding.application_root_id,
      'moduleRootId', binding.module_root_id,
      'bindingRevision', binding.binding_revision,
      'applicationReleaseRevision', binding.application_release_revision,
      'moduleReleaseRevision', binding.module_release_revision,
      'state', binding.state
    ) order by binding.module_root_id
  ) into selected_bindings
  from vortex_module.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.application_release_revision = selected_application_release_revision
    and binding.state = 'active';

  return pg_catalog.jsonb_build_object(
    'organizationId', selected_organization_id,
    'applicationRootId', selected_application_root_id,
    'applicationReleaseRevision', selected_application_release_revision,
    'moduleBindings', selected_bindings
  );
end
$function$;


ALTER FUNCTION vortex_module.read_active_installation_for_scope_internal(p_organization_id uuid, p_application_root_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_active_installation_for_scope_internal(p_organization_id uuid, p_application_root_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_active_installation_for_scope_internal(p_organization_id uuid, p_application_root_id uuid) IS 'Resolves the complete exact active Module binding set for one already-validated organisation/Application scope.';


--
-- Name: read_active_shared_record_consumers_internal(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_active_shared_record_consumers_internal(
  p_module_root_id uuid,
  p_record_type_id uuid,
  p_storage_contract_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  selected_organization_id uuid;
  selected_application_root_id uuid;
  selected_access_version bigint;
  candidate_application_root_id uuid;
  application_installation jsonb;
  application_root vortex_definition.roots%rowtype;
  application_release vortex_definition.releases%rowtype;
  permission_snapshot record;
  module_binding_fact jsonb;
  module_binding vortex_module.installation_bindings%rowtype;
  module_root vortex_definition.roots%rowtype;
  module_release vortex_definition.releases%rowtype;
  storage_provision record;
  module_bindings jsonb;
  targets jsonb := '[]'::jsonb;
  target jsonb;
  target_record_types jsonb;
  target_record_type_count integer;
  own_module_binding_count integer;
  binding_count integer;
begin
  if p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_type_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Shared record consumer selection is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  if pg_catalog.jsonb_typeof(context_value) is distinct from 'object'
    or not (context_value ?& array[
      'callerKind', 'tenantId', 'organizationId', 'organizationAccountId',
      'applicationRootId', 'accessVersion', 'correlationId'
    ])
    or context_value ->> 'callerKind' is distinct from 'human'
    or not vortex_context.is_non_nil_uuid(context_value ->> 'tenantId')
    or not vortex_context.is_non_nil_uuid(context_value ->> 'organizationId')
    or not vortex_context.is_non_nil_uuid(context_value ->> 'organizationAccountId')
    or not vortex_context.is_non_nil_uuid(context_value ->> 'applicationRootId')
    or not vortex_context.is_non_nil_uuid(context_value ->> 'correlationId')
    or not pg_catalog.pg_input_is_valid(context_value ->> 'accessVersion', 'bigint')
    or (context_value ->> 'accessVersion')::bigint not between 1 and 9007199254740991 then
    raise exception using errcode = '42501',
      message = 'Shared record consumer request context is unavailable';
  end if;
  selected_organization_id := (context_value ->> 'organizationId')::uuid;
  selected_application_root_id := (context_value ->> 'applicationRootId')::uuid;
  selected_access_version := (context_value ->> 'accessVersion')::bigint;

  <<application_loop>>
  for candidate_application_root_id in
    select distinct binding.application_root_id
    from vortex_module.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.module_root_id = p_module_root_id
      and binding.state = 'active'
    order by binding.application_root_id
  loop
    select snapshot.* into permission_snapshot
    from vortex_access.read_application_permission_snapshot(
      selected_organization_id, candidate_application_root_id
    ) as snapshot;
    if not found then
      continue application_loop;
    end if;

    select root.* into application_root
    from vortex_definition.roots as root
    where root.root_id = candidate_application_root_id;
    if not found
      or application_root.kind is distinct from 'application'
      or application_root.organization_id is distinct from selected_organization_id
      or application_root.key is null or application_root.key = '' then
      continue application_loop;
    end if;

    if not pg_catalog.pg_input_is_valid(permission_snapshot.release_revision::text, 'bigint')
      or permission_snapshot.release_revision not between 1 and 9007199254740991 then
      continue application_loop;
    end if;
    select release.* into application_release
    from vortex_definition.releases as release
    where release.root_id = candidate_application_root_id
      and release.release_revision = permission_snapshot.release_revision;
    if not found
      or application_release.validation_contract_version is null
      or not (application_release.validation_contract_version = any (
        vortex_definition.accepted_contract_version('application')
      ))
      or application_release.release_version is null
      or application_release.release_version = ''
      or application_release.content_fingerprint is null
      or application_release.content_fingerprint !~ '^sha256:[a-f0-9]{64}$'
      or application_release.resolution_fingerprint is null
      or application_release.resolution_fingerprint !~ '^sha256:[a-f0-9]{64}$'
      or pg_catalog.jsonb_typeof(application_release.compilation_output) is distinct from 'object'
      or application_release.compilation_output ->> 'kind' is distinct from 'application'
      or application_release.compilation_output ->> 'validationContractVersion'
        is distinct from application_release.validation_contract_version
      or application_release.compilation_output #>> '{canonical,envelope,rootId}'
        is distinct from candidate_application_root_id::text
      or application_release.compilation_output #>> '{canonical,envelope,kind}'
        is distinct from 'application'
      or application_release.compilation_output #>> '{canonical,envelope,validationContractVersion}'
        is distinct from application_release.validation_contract_version then
      continue application_loop;
    end if;

    if permission_snapshot.organization_id is distinct from selected_organization_id
      or permission_snapshot.application_root_id is distinct from candidate_application_root_id
      or permission_snapshot.registration_revision is null
      or permission_snapshot.registration_revision not between 1 and 9007199254740991
      or permission_snapshot.release_revision is distinct from application_release.release_revision
      or permission_snapshot.definition_key is distinct from application_root.key
      or permission_snapshot.release_version is distinct from application_release.release_version
      or permission_snapshot.validation_contract_version
        is distinct from application_release.validation_contract_version
      or permission_snapshot.content_fingerprint is distinct from application_release.content_fingerprint
      or permission_snapshot.resolution_fingerprint is distinct from application_release.resolution_fingerprint
      or permission_snapshot.catalogue_fingerprint is null
      or permission_snapshot.catalogue_fingerprint !~ '^sha256:[a-f0-9]{64}$' then
      continue application_loop;
    end if;

    begin
      application_installation := vortex_module.read_active_installation_for_scope_internal(
        selected_organization_id, candidate_application_root_id
      );
    exception
      when sqlstate 'P0002' or sqlstate '55000' or sqlstate '23514' then
        continue application_loop;
    end;

    if pg_catalog.jsonb_typeof(application_installation) is distinct from 'object'
      or not (application_installation ?& array[
        'organizationId', 'applicationRootId', 'applicationReleaseRevision', 'moduleBindings'
      ])
      or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(application_installation)) <> 4
      or application_installation ->> 'organizationId' is distinct from selected_organization_id::text
      or application_installation ->> 'applicationRootId' is distinct from candidate_application_root_id::text
      or application_installation ->> 'applicationReleaseRevision'
        is distinct from application_release.release_revision::text
      or pg_catalog.jsonb_typeof(application_installation -> 'moduleBindings') is distinct from 'array'
      or pg_catalog.jsonb_array_length(application_installation -> 'moduleBindings') = 0 then
      raise exception using errcode = '55000',
        message = 'Active shared record consumer evidence is malformed';
    end if;

    select pg_catalog.count(*)::integer into binding_count
    from pg_catalog.jsonb_array_elements(application_installation -> 'moduleBindings') as item(value);
    module_bindings := '[]'::jsonb;
    own_module_binding_count := 0;

    for module_binding_fact in
      select item.value
      from pg_catalog.jsonb_array_elements(application_installation -> 'moduleBindings') as item(value)
      order by (item.value ->> 'moduleRootId')::uuid
    loop
      if pg_catalog.jsonb_typeof(module_binding_fact) is distinct from 'object'
        or not (module_binding_fact ?& array[
          'organizationId', 'applicationRootId', 'moduleRootId', 'bindingRevision',
          'applicationReleaseRevision', 'moduleReleaseRevision', 'state'
        ])
        or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(module_binding_fact)) <> 7
        or not vortex_context.is_non_nil_uuid(module_binding_fact ->> 'moduleRootId')
        or not pg_catalog.pg_input_is_valid(module_binding_fact ->> 'bindingRevision', 'bigint')
        or (module_binding_fact ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
        or not pg_catalog.pg_input_is_valid(module_binding_fact ->> 'moduleReleaseRevision', 'bigint')
        or (module_binding_fact ->> 'moduleReleaseRevision')::bigint not between 1 and 9007199254740991
        or module_binding_fact ->> 'organizationId' is distinct from selected_organization_id::text
        or module_binding_fact ->> 'applicationRootId' is distinct from candidate_application_root_id::text
        or module_binding_fact ->> 'applicationReleaseRevision'
          is distinct from application_release.release_revision::text
        or module_binding_fact ->> 'state' is distinct from 'active' then
        raise exception using errcode = '55000',
          message = 'Active shared record consumer binding evidence is malformed';
      end if;

      select binding.* into module_binding
      from vortex_module.installation_bindings as binding
      where binding.organization_id = selected_organization_id
        and binding.application_root_id = candidate_application_root_id
        and binding.module_root_id = (module_binding_fact ->> 'moduleRootId')::uuid;
      if not found
        or module_binding.state is distinct from 'active'
        or module_binding.binding_revision is distinct from (module_binding_fact ->> 'bindingRevision')::bigint
        or module_binding.application_release_revision is distinct from application_release.release_revision
        or module_binding.module_release_revision is distinct from (module_binding_fact ->> 'moduleReleaseRevision')::bigint then
        raise exception using errcode = '40001',
          message = 'Active shared record consumer binding changed during selection';
      end if;

      select root.* into module_root
      from vortex_definition.roots as root
      where root.root_id = module_binding.module_root_id;
      if not found or module_root.kind is distinct from 'module'
        or module_root.key is null or module_root.key = '' then
        continue application_loop;
      end if;
      select release.* into module_release
      from vortex_definition.releases as release
      where release.root_id = module_binding.module_root_id
        and release.release_revision = module_binding.module_release_revision;
      if not found
        or module_release.validation_contract_version is null
        or not (module_release.validation_contract_version = any (
          vortex_definition.accepted_contract_version('module')
        ))
        or module_release.release_version is null
        or module_release.release_version = ''
        or module_release.content_fingerprint is null
        or module_release.content_fingerprint !~ '^sha256:[a-f0-9]{64}$'
        or module_release.resolution_fingerprint is null
        or module_release.resolution_fingerprint !~ '^sha256:[a-f0-9]{64}$'
        or pg_catalog.jsonb_typeof(module_release.compilation_output) is distinct from 'object'
        or module_release.compilation_output ->> 'kind' is distinct from 'module'
        or module_release.compilation_output ->> 'validationContractVersion'
          is distinct from module_release.validation_contract_version
        or module_release.compilation_output #>> '{canonical,envelope,rootId}'
          is distinct from module_binding.module_root_id::text
        or module_release.compilation_output #>> '{canonical,envelope,kind}'
          is distinct from 'module'
        or module_release.compilation_output #>> '{canonical,envelope,validationContractVersion}'
          is distinct from module_release.validation_contract_version then
        continue application_loop;
      end if;

      begin
        select provision.* into strict storage_provision
        from vortex_record.read_exact_module_storage_provision(
          module_binding.module_root_id, module_binding.module_release_revision
        ) as provision;
      exception
        when no_data_found then
          continue application_loop;
      end;
      if storage_provision.module_root_id is distinct from module_binding.module_root_id
        or storage_provision.release_revision is distinct from module_binding.module_release_revision
        or storage_provision.storage_contract_ids is null
        or pg_catalog.cardinality(storage_provision.storage_contract_ids) = 0
        or module_binding.storage_contract_ids is distinct from storage_provision.storage_contract_ids
        or exists (
          select 1
          from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
          where stored.contract_id is null
            or stored.contract_id = '00000000-0000-0000-0000-000000000000'::uuid
        )
        or exists (
          select 1
          from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
          group by stored.contract_id having pg_catalog.count(*) <> 1
        )
        or storage_provision.storage_contract_ids is distinct from (
          select pg_catalog.array_agg(stored.contract_id order by stored.contract_id)
          from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
        ) then
        continue application_loop;
      end if;

      if module_binding.module_root_id = p_module_root_id then
        own_module_binding_count := own_module_binding_count + 1;
        target_record_types := module_release.compilation_output #> '{canonical,content,recordTypes}';
        if pg_catalog.jsonb_typeof(target_record_types) is distinct from 'array' then
          raise exception using errcode = '55000',
            message = 'Shared record type release evidence is malformed';
        end if;
        select pg_catalog.count(*)::integer into target_record_type_count
        from pg_catalog.jsonb_array_elements(target_record_types) as item(value)
        where item.value ->> 'recordTypeId' = p_record_type_id::text;
        if target_record_type_count <> 1 or not exists (
          select 1
          from pg_catalog.jsonb_array_elements(target_record_types) as item(value)
          where item.value ->> 'recordTypeId' = p_record_type_id::text
            and item.value ->> 'storageContractId' = p_storage_contract_id::text
            and item.value ->> 'storageScope' = 'organization_shared'
        ) then
          continue application_loop;
        end if;
        if not (p_storage_contract_id = any (storage_provision.storage_contract_ids)) then
          continue application_loop;
        end if;
      end if;

      module_bindings := module_bindings || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'moduleRootId', module_binding.module_root_id,
          'bindingRevision', module_binding.binding_revision,
          'applicationReleaseRevision', module_binding.application_release_revision,
          'moduleReleaseRevision', module_binding.module_release_revision,
          'state', module_binding.state,
          'contentFingerprint', module_release.content_fingerprint,
          'resolutionFingerprint', module_release.resolution_fingerprint,
          'generatorContractVersion', '1.0.0',
          'storageContractIds', pg_catalog.to_jsonb(storage_provision.storage_contract_ids)
        )
      );
    end loop;

    if own_module_binding_count <> 1
      or pg_catalog.jsonb_array_length(module_bindings) <> binding_count then
      continue application_loop;
    end if;

    target := pg_catalog.jsonb_build_object(
      'applicationRootId', candidate_application_root_id,
      'applicationReleaseRevision', application_release.release_revision,
      'moduleRootId', p_module_root_id,
      'moduleReleaseRevision', (
        select binding.module_release_revision
        from vortex_module.installation_bindings as binding
        where binding.organization_id = selected_organization_id
          and binding.application_root_id = candidate_application_root_id
          and binding.module_root_id = p_module_root_id
          and binding.state = 'active'
      ),
      'bindingRevision', (
        select binding.binding_revision
        from vortex_module.installation_bindings as binding
        where binding.organization_id = selected_organization_id
          and binding.application_root_id = candidate_application_root_id
          and binding.module_root_id = p_module_root_id
          and binding.state = 'active'
      ),
      'recordTypeId', p_record_type_id,
      'storageContractId', p_storage_contract_id,
      'registrationRevision', permission_snapshot.registration_revision,
      'definitionKey', application_root.key,
      'releaseVersion', application_release.release_version,
      'validationContractVersion', application_release.validation_contract_version,
      'contentFingerprint', application_release.content_fingerprint,
      'resolutionFingerprint', application_release.resolution_fingerprint,
      'catalogueFingerprint', permission_snapshot.catalogue_fingerprint,
      'moduleBindings', module_bindings
    );
    targets := targets || pg_catalog.jsonb_build_array(target);
  end loop;

  if pg_catalog.jsonb_array_length(targets) = 0 then
    raise exception using errcode = '42501',
      message = 'No active shared record consumer is available';
  end if;
  if not exists (
    select 1
    from pg_catalog.jsonb_array_elements(targets) as item(value)
    where item.value ->> 'applicationRootId' = selected_application_root_id::text
  ) then
    raise exception using errcode = '42501',
      message = 'Origin Application is not a proved shared record consumer';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', selected_organization_id,
    'accessVersion', selected_access_version,
    'targets', targets
  );
end
$function$;


ALTER FUNCTION vortex_module.read_active_shared_record_consumers_internal(p_module_root_id uuid, p_record_type_id uuid, p_storage_contract_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_active_shared_record_consumers_internal(p_module_root_id uuid, p_record_type_id uuid, p_storage_contract_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_active_shared_record_consumers_internal(p_module_root_id uuid, p_record_type_id uuid, p_storage_contract_id uuid) IS 'Selects every exact active App consumer of one organization-shared record from the complete installed Module lineage and active exact release registration.';


--
-- Name: read_application_installation_bindings(uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.read_application_installation_bindings(p_application_root_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority record;
  binding_evidence jsonb;
  registered_release_revision bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Application installation read command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_application_installation_authority() as locked;

  if not exists (
    select 1
    from vortex_definition.roots as root
    where root.root_id = p_application_root_id
      and root.organization_id = authority.organization_id
      and root.kind = 'application'
  ) then
    raise exception using errcode = 'P0002',
      message = 'Application installation is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'organizationId', binding.organization_id,
      'applicationRootId', binding.application_root_id,
      'moduleRootId', binding.module_root_id,
      'bindingRevision', binding.binding_revision,
      'applicationReleaseRevision', binding.application_release_revision,
      'moduleReleaseRevision', binding.module_release_revision,
      'state', binding.state
    ) order by binding.module_root_id), '[]'::jsonb)
  into binding_evidence
  from vortex_module.installation_bindings as binding
  where binding.organization_id = authority.organization_id
    and binding.application_root_id = p_application_root_id;

  -- The exact release the active permission registration was prepared from,
  -- or null when it is absent or withdrawn. The fixed activation requires it
  -- to name the release being activated.
  select snapshot.release_revision into registered_release_revision
  from vortex_access.read_application_permission_snapshot(
    authority.organization_id, p_application_root_id
  ) as snapshot;

  return pg_catalog.jsonb_build_object(
    'organizationId', authority.organization_id,
    'applicationRootId', p_application_root_id,
    'registeredReleaseRevision', registered_release_revision,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application installation evidence is ambiguous';
end
$$;


ALTER FUNCTION vortex_module.read_application_installation_bindings(p_application_root_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_application_installation_bindings(p_application_root_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_application_installation_bindings(p_application_root_id uuid) IS 'Installer-only read of one Application''s current Module binding revisions and registered release under application-management authority.';


--
-- Name: read_current_active_installation(); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.read_current_active_installation() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  checked_context jsonb;
begin
  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId' then
    raise exception using errcode = '22023', message = 'Active Application context is required';
  end if;
  return vortex_module.read_active_installation_for_scope_internal(
    (checked_context ->> 'organizationId')::uuid,
    (checked_context ->> 'applicationRootId')::uuid
  );
end
$$;


ALTER FUNCTION vortex_module.read_current_active_installation() OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_current_active_installation(); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_current_active_installation() IS 'Returns the complete exact active Module binding set selected from validated human Application context.';


--
-- Name: read_current_detached_installation_for_transfer_internal(); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_current_detached_installation_for_transfer_internal()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  selected_organization_id uuid;
  selected_application_root_id uuid;
  selected_application_release_revision bigint;
  selected_bindings jsonb;
  binding_row vortex_module.installation_bindings%rowtype;
begin
  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId' then
    raise exception using errcode = '22023', message = 'Detached Application context is required';
  end if;
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  selected_application_root_id := (checked_context ->> 'applicationRootId')::uuid;

  -- The retained/disabled entry must observe one stable binding set.  Use the
  -- same lifecycle key as installation transitions, then hold every matching
  -- binding through the transfer transaction.
  for binding_row in
    select binding.*
    from vortex_module.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
    order by binding.module_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'vortex_module.binding:' || binding_row.organization_id::text || ':' ||
        binding_row.application_root_id::text || ':' || binding_row.module_root_id::text,
      0
    ));
  end loop;
  perform 1
  from vortex_module.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
  for share;

  select pg_catalog.min(binding.application_release_revision)
  into selected_application_release_revision
  from vortex_module.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.state = 'detached';
  if selected_application_release_revision is null then
    raise exception using errcode = 'P0002', message = 'Detached Application installation is unavailable';
  end if;
  if exists (
    select 1 from vortex_module.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'detached'
      and binding.application_release_revision <> selected_application_release_revision
  ) then
    raise exception using errcode = '55000', message = 'Detached Application installation is mixed';
  end if;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = selected_application_release_revision
    where root.root_id = selected_application_root_id
      and root.kind = 'application'
      and root.organization_id = selected_organization_id
      and release.compilation_output #>> '{kind}' = 'application'
  ) then
    raise exception using errcode = '23514', message = 'Detached Application release evidence is invalid';
  end if;

  if not exists (
    select 1 from vortex_definition.release_dependencies as dependency
    where dependency.root_id = selected_application_root_id
      and dependency.release_revision = selected_application_release_revision
      and dependency.dependency_kind = 'module'
  ) or exists (
    with recursive module_edges as (
      select dependency.target_root_id, dependency.target_release_revision,
        dependency.dependency_reference, dependency.dependency_version,
        dependency.dependency_content_fingerprint, dependency.evidence_fingerprint
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = selected_application_root_id
        and dependency.release_revision = selected_application_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision,
        dependency.dependency_reference, dependency.dependency_version,
        dependency.dependency_content_fingerprint, dependency.evidence_fingerprint
      from module_edges as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select 1
    from module_edges as edge
    left join vortex_definition.releases as module_release
      on module_release.root_id = edge.target_root_id
      and module_release.release_revision = edge.target_release_revision
    left join vortex_definition.roots as module_root
      on module_root.root_id = edge.target_root_id
    where module_root.kind is distinct from 'module'
      or module_root.key is distinct from edge.dependency_reference
      or module_release.release_version is distinct from edge.dependency_version
      or module_release.content_fingerprint is distinct from edge.dependency_content_fingerprint
      or module_release.resolution_fingerprint is distinct from edge.evidence_fingerprint
  ) or exists (
    with recursive module_nodes as (
      select dependency.target_root_id, dependency.target_release_revision
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = selected_application_root_id
        and dependency.release_revision = selected_application_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision
      from module_nodes as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select 1 from module_nodes group by target_root_id
    having pg_catalog.count(distinct target_release_revision) <> 1
  ) or exists (
    with recursive module_nodes as (
      select dependency.target_root_id, dependency.target_release_revision
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = selected_application_root_id
        and dependency.release_revision = selected_application_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision
      from module_nodes as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select 1
    from module_nodes as node
    left join vortex_module.installation_bindings as binding
      on binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.module_root_id = node.target_root_id
    where binding.state is distinct from 'detached'
      or binding.application_release_revision is distinct from selected_application_release_revision
      or binding.module_release_revision is distinct from node.target_release_revision
  ) or exists (
    select 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'detached'
      and not exists (
        with recursive module_nodes as (
          select dependency.target_root_id, dependency.target_release_revision
          from vortex_definition.release_dependencies as dependency
          where dependency.root_id = selected_application_root_id
            and dependency.release_revision = selected_application_release_revision
            and dependency.dependency_kind = 'module'
          union
          select dependency.target_root_id, dependency.target_release_revision
          from module_nodes as parent
          join vortex_definition.release_dependencies as dependency
            on dependency.root_id = parent.target_root_id
            and dependency.release_revision = parent.target_release_revision
            and dependency.dependency_kind = 'module'
        )
        select 1 from module_nodes as node
        where node.target_root_id = binding.module_root_id
          and node.target_release_revision = binding.module_release_revision
      )
  ) then
    raise exception using errcode = '55000', message = 'Detached Application Module bindings are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'organizationId', binding.organization_id,
      'applicationRootId', binding.application_root_id,
      'moduleRootId', binding.module_root_id,
      'bindingRevision', binding.binding_revision,
      'applicationReleaseRevision', binding.application_release_revision,
      'moduleReleaseRevision', binding.module_release_revision,
      'state', binding.state
    ) order by binding.module_root_id
  ) into selected_bindings
  from vortex_module.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.application_release_revision = selected_application_release_revision
    and binding.state = 'detached';

  return pg_catalog.jsonb_build_object(
    'organizationId', selected_organization_id,
    'applicationRootId', selected_application_root_id,
    'applicationReleaseRevision', selected_application_release_revision,
    'moduleBindings', selected_bindings
  );
end
$function$;


ALTER FUNCTION vortex_module.read_current_detached_installation_for_transfer_internal() OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_current_detached_installation_for_transfer_internal(); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_current_detached_installation_for_transfer_internal() IS 'Private exact detached installation reader for the fixed retained/disabled ownership-transfer operation.';


--
-- Name: read_current_offboarding_inventory_installation_internal(); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.read_current_offboarding_inventory_installation_internal() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  installation jsonb;
  installation_state text;
  context_value jsonb;
  storage_contract_ids jsonb;
begin
  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId' then
    raise exception using errcode = '22023',
      message = 'Offboarding inventory requires an application context';
  end if;

  begin
    installation := vortex_module.read_current_active_installation();
    installation_state := 'active';
  exception
    when no_data_found then
      installation := vortex_module.read_current_detached_installation_for_transfer_internal();
      installation_state := 'detached';
  end;

  select coalesce(pg_catalog.jsonb_agg(contract_id order by contract_id), '[]'::jsonb)
  into storage_contract_ids
  from (
    select distinct unnest(binding.storage_contract_ids) as contract_id
    from vortex_module.installation_bindings as binding
    where binding.organization_id = (context_value ->> 'organizationId')::uuid
      and binding.application_root_id = (context_value ->> 'applicationRootId')::uuid
      and binding.state = installation_state
      and binding.application_release_revision =
        (installation ->> 'applicationReleaseRevision')::bigint
  ) as contracts;

  if storage_contract_ids = '[]'::jsonb then
    raise exception using errcode = '55000',
      message = 'Offboarding inventory installation bindings are unavailable';
  end if;

  return installation || pg_catalog.jsonb_build_object(
    'installationState', installation_state,
    'storageContractIds', storage_contract_ids
  );
end
$$;


ALTER FUNCTION vortex_module.read_current_offboarding_inventory_installation_internal() OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_current_offboarding_inventory_installation_internal(); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_current_offboarding_inventory_installation_internal() IS 'Private exact active-or-detached installation reader with the bound storage contracts for account-offboarding inventory.';


--
-- Name: read_installation_runtime_bundle_index(uuid, bigint, integer); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_installation_runtime_bundle_index(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_bundle_format_version integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  selected_organization_id uuid;
  stored_bundle vortex_module.installation_runtime_bundles%rowtype;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_bundle_format_version is distinct from 2 then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle key is invalid';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  if selected_organization_id is null then
    raise exception using errcode = '42501',
      message = 'Installation runtime bundle organisation is unavailable';
  end if;

  select stored.* into stored_bundle
  from vortex_module.installation_runtime_bundles as stored
  where stored.organization_id = selected_organization_id
    and stored.application_root_id = p_application_root_id
    and stored.application_release_revision = p_application_release_revision
    and stored.bundle_format_version = p_bundle_format_version;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle is unavailable';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', stored_bundle.organization_id,
    'applicationRootId', stored_bundle.application_root_id,
    'applicationReleaseRevision', stored_bundle.application_release_revision,
    'bundleFormatVersion', stored_bundle.bundle_format_version,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest,
    'parts', stored_bundle.parts,
    'totalSizeBytes', stored_bundle.total_size_bytes,
    'builtAt', stored_bundle.built_at
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle is unavailable';
end
$function$;


ALTER FUNCTION vortex_module.read_installation_runtime_bundle_index(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_installation_runtime_bundle_index(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_installation_runtime_bundle_index(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer) IS 'Reads one exact immutable runtime bundle index inside the verified organisation context.';


--
-- Name: read_installation_runtime_bundle_parts(uuid, bigint, integer, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_installation_runtime_bundle_parts(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_bundle_format_version integer,
  p_sections jsonb
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  allowed_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  checked_context jsonb;
  selected_organization_id uuid;
  requested_sections text[];
  parts_value jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_bundle_format_version is null or p_bundle_format_version < 1
    or p_sections is null or pg_catalog.jsonb_typeof(p_sections) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle read command is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_sections) not between 1 and
    pg_catalog.cardinality(allowed_sections) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle read command is invalid';
  end if;
  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_sections) as requested(value)
      where pg_catalog.jsonb_typeof(requested.value) is distinct from 'string'
        or not ((requested.value #>> '{}') = any (allowed_sections))
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_sections) as requested(value)
      group by requested.value
      having pg_catalog.count(*) > 1
    ) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle read command is invalid';
  end if;
  select pg_catalog.array_agg(requested.value #>> '{}' order by requested.ordinality)
  into requested_sections
  from pg_catalog.jsonb_array_elements(p_sections) with ordinality as requested(value, ordinality);

  checked_context := vortex_access.validated_human_request_context();
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  if selected_organization_id is null then
    raise exception using errcode = '42501',
      message = 'Installation runtime bundle organisation is unavailable';
  end if;

  if not exists (
    select 1 from vortex_module.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version
  ) then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'section', part.section,
      'ordinal', part.ordinal,
      'byteSize', pg_catalog.octet_length(part.content_bytes),
      'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(part.content_bytes, 'sha256'), 'hex'
      ),
      'content', pg_catalog.convert_from(part.content_bytes, 'UTF8')
    ) order by pg_catalog.array_position(requested_sections, part.section), part.ordinal
  ), '[]'::jsonb)
  into parts_value
  from vortex_module.installation_runtime_bundle_parts as part
  where part.organization_id = selected_organization_id
    and part.application_root_id = p_application_root_id
    and part.application_release_revision = p_application_release_revision
    and part.bundle_format_version = p_bundle_format_version
    and part.section = any (requested_sections);

  return parts_value;
end
$function$;


ALTER FUNCTION vortex_module.read_installation_runtime_bundle_parts(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer, p_sections jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_installation_runtime_bundle_parts(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer, p_sections jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_installation_runtime_bundle_parts(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer, p_sections jsonb) IS 'Reads selected immutable runtime bundle parts by exact key inside the verified organisation context.';


--
-- Name: read_lifecycle_activation_targets_internal(uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) RETURNS TABLE(storage_contract_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  context_value jsonb;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
    ) then
    raise exception using errcode = '22023',
      message = 'Lifecycle activation target command is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  if (context_value ->> 'organizationId')::uuid is distinct from p_organization_id then
    raise exception using errcode = '42501',
      message = 'Lifecycle activation targets are unavailable';
  end if;

  return query
  select storage_id.value
  from vortex_module.installation_bindings as binding
  join pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    on expected.value ->> 'moduleRootId' = binding.module_root_id::text
    and expected.value ->> 'bindingRevision' = binding.binding_revision::text
  join pg_catalog.unnest(binding.storage_contract_ids) as storage_id(value) on true
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.application_release_revision = p_application_release_revision
    -- Activation has already flipped this exact binding set to 'active' under
    -- its own advisory and row locks earlier in this transaction.
    and binding.state = 'active'
  for share of binding;
end
$$;


ALTER FUNCTION vortex_module.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Private activation-time installation fact: the exact storage contracts of one already-activated Application binding set, shared for the transaction.';


--
-- Name: read_offboarding_inventory_contract_applications_internal(uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  context_value jsonb;
  affected_applications jsonb;
begin
  if p_storage_contract_id is null or p_storage_contract_id = nil_uuid then
    raise exception using errcode = '22023',
      message = 'Offboarding inventory selector is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();

  -- Provisioned bindings are not installed and are excluded; detached bindings
  -- are a disabled installation of a real application and stay visible, exactly
  -- as the inventory's installation reader treats them.
  select coalesce(
    pg_catalog.jsonb_agg(
      distinct binding.application_root_id order by binding.application_root_id
    ),
    '[]'::jsonb
  )
  into affected_applications
  from vortex_module.installation_bindings as binding
  where binding.organization_id = (context_value ->> 'organizationId')::uuid
    and binding.state in ('active', 'detached')
    and p_storage_contract_id = any (binding.storage_contract_ids);

  return affected_applications;
end
$$;


ALTER FUNCTION vortex_module.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) IS 'Private adapter-only bridge returning the installed application root IDs one storage contract is bound into, for account-offboarding shared impact.';


--
-- Name: read_prepared_installation_runtime_source(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_prepared_installation_runtime_source(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  mapping jsonb;
  prepared_record_plan jsonb;
  application_evidence jsonb;
  module_evidence jsonb;
begin
  mapping := vortex_module.lock_prepared_installation_runtime_mapping_internal(
    p_application_root_id,
    p_application_release_revision,
    p_expected_module_bindings
  );
  select vortex_definition.project_consumer_release_evidence(
    'application', p_application_root_id, p_application_release_revision
  ) into application_evidence;
  if application_evidence is null
    or (application_evidence ->> 'organizationId')::uuid
      is distinct from (mapping ->> 'organizationId')::uuid then
    raise exception using errcode = 'P0002',
      message = 'Prepared Application source is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
      vortex_definition.project_consumer_release_evidence(
        'module', (pin.value ->> 'moduleRootId')::uuid,
        (pin.value ->> 'moduleReleaseRevision')::bigint
      ) order by (pin.value ->> 'moduleRootId')::uuid
    ), '[]'::jsonb)
  into module_evidence
  from pg_catalog.jsonb_array_elements(mapping -> 'moduleBindings') as pin(value);

  prepared_record_plan := vortex_record.resolve_prepared_record_access_plan_internal(
    p_application_root_id,
    p_application_release_revision,
    mapping -> 'moduleBindings'
  );
  if prepared_record_plan is null
    or pg_catalog.jsonb_typeof(prepared_record_plan) is distinct from 'object'
    or not prepared_record_plan ?& array['planKey', 'mappingFingerprint', 'plan'] then
    raise exception using errcode = '55000',
      message = 'Prepared Record access plan is unavailable';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', mapping -> 'organizationId',
    'applicationRootId', mapping -> 'applicationRootId',
    'applicationReleaseRevision', mapping -> 'applicationReleaseRevision',
    'accessVersion', mapping -> 'accessVersion',
    'correlationId', mapping -> 'correlationId',
    'pinFingerprint', mapping -> 'pinFingerprint',
    'mappingFingerprint', prepared_record_plan -> 'mappingFingerprint',
    'moduleBindings', mapping -> 'moduleBindings',
    'application', application_evidence,
    'modules', module_evidence,
    'preparedRecordAccessPlan', prepared_record_plan
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Prepared runtime source evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared runtime source evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.read_prepared_installation_runtime_source(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_prepared_installation_runtime_source(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_prepared_installation_runtime_source(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Reads exact immutable Application and complete Module source plus the current prepared Record plan inside the verified human installation transaction.';


--
-- Name: read_preview_installation(uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_preview_installation(
  p_preview_installation_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  preview_row vortex_module.preview_installations%rowtype;
begin
  if not vortex_context.is_non_nil_uuid(p_preview_installation_id::text) then
    raise exception using errcode = '22023', message = 'Preview installation identity is invalid';
  end if;
  checked_context := vortex_module.assert_preview_installation_authority_internal();
  select preview.* into preview_row
  from vortex_module.preview_installations as preview
  where preview.preview_installation_id = p_preview_installation_id
    and preview.organization_id = (checked_context ->> 'organizationId')::uuid
    and preview.previewer_identity_id = (checked_context ->> 'identityId')::uuid
    and preview.previewer_organization_account_id =
      (checked_context ->> 'organizationAccountId')::uuid
    and preview.application_root_id = (checked_context ->> 'applicationRootId')::uuid
    and preview.expires_at > pg_catalog.statement_timestamp();
  if not found then
    return null;
  end if;
  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_row.preview_installation_id,
    'organizationId', preview_row.organization_id,
    'applicationRootId', preview_row.application_root_id,
    'draftRevision', preview_row.draft_revision,
    'previewerIdentityId', preview_row.previewer_identity_id,
    'previewerOrganizationAccountId', preview_row.previewer_organization_account_id,
    'candidate', preview_row.candidate,
    'resolvedModules', preview_row.resolved_modules,
    'storageIdentities', preview_row.storage_identities,
    'createdAt', preview_row.created_at,
    'expiresAt', preview_row.expires_at
  );
end
$function$;


ALTER FUNCTION vortex_module.read_preview_installation(p_preview_installation_id uuid) OWNER TO vortex_module_owner;

