COMMENT ON FUNCTION vortex_module.read_preview_installation(p_preview_installation_id uuid) IS 'Reads a non-expired preview installation only for its creating organisation account in the validated human request.';


--
-- Name: read_preview_record_installation_internal(uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_preview_record_installation_internal(
  p_preview_installation_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  preview_row vortex_module.preview_installations%rowtype;
  module_bindings_value jsonb;
begin
  if not vortex_context.is_non_nil_uuid(p_preview_installation_id::text) then
    return null;
  end if;

  begin
    context_value := vortex_module.assert_preview_installation_authority_internal();
  exception when insufficient_privilege then
    return null;
  end;
  select preview.* into preview_row
  from vortex_module.preview_installations as preview
  where preview.preview_installation_id = p_preview_installation_id
    and preview.organization_id = (context_value ->> 'organizationId')::uuid
    and preview.application_root_id = (context_value ->> 'applicationRootId')::uuid
    and preview.previewer_identity_id = (context_value ->> 'identityId')::uuid
    and preview.previewer_organization_account_id =
      (context_value ->> 'organizationAccountId')::uuid
    and preview.expires_at > pg_catalog.statement_timestamp()
  for key share;
  if not found then
    return null;
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'moduleRootId', item.value -> 'moduleRootId',
      'moduleReleaseRevision', item.value -> 'moduleReleaseRevision',
      'bindingRevision', 1,
      'state', 'active'
    ) order by item.value ->> 'moduleRootId' collate "C"
  ), '[]'::jsonb)
  into module_bindings_value
  from pg_catalog.jsonb_array_elements(preview_row.resolved_modules) as item(value);

  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_row.preview_installation_id,
    'organizationId', preview_row.organization_id,
    'applicationRootId', preview_row.application_root_id,
    'applicationReleaseRevision', preview_row.draft_revision,
    'moduleBindings', module_bindings_value,
    'candidate', preview_row.candidate,
    'resolvedModules', preview_row.resolved_modules,
    'storageIdentities', preview_row.storage_identities
  );
end
$function$;


ALTER FUNCTION vortex_module.read_preview_record_installation_internal(p_preview_installation_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_preview_record_installation_internal(p_preview_installation_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_preview_record_installation_internal(p_preview_installation_id uuid) IS 'Private owner-only preview installation reader for the protected Record port, restricted to the exact human identity, organisation account and Application context until expiry.';


--
-- Name: read_provisioned_lifecycle_setup_targets_internal(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.read_provisioned_lifecycle_setup_targets_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  install_decision record;
  install_scope_decision record;
  initial_context jsonb;
  current_context jsonb;
  completion_time timestamptz;
  context_expires_at timestamptz;
  delegated_expires_at timestamptz;
  application_definition_key text;
  application_release vortex_definition.releases%rowtype;
  permission_snapshot record;
  pin record;
  locked_binding vortex_module.installation_bindings%rowtype;
  module_release vortex_definition.releases%rowtype;
  storage_provision record;
  expected_module_root_id uuid;
  expected_binding_revision bigint;
  previous_module_root_id uuid;
  module_root_text text;
  binding_revision_text text;
  closure_count bigint;
  expected_count integer;
  module_bindings jsonb := '[]'::jsonb;
  normalized_pins jsonb;
  all_storage_contract_ids uuid[] := array[]::uuid[];
  union_storage_contract_ids uuid[];
  storage_contract_id_count bigint;
  distinct_storage_contract_id_count bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup command is invalid';
  end if;

  if p_expected_module_bindings is null
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup binding pins are invalid';
  end if;
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if expected_count < 1 or expected_count > 10000 then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup binding pins are invalid';
  end if;

  previous_module_root_id := null;
  for pin in
    select item.value
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
  loop
    if pg_catalog.jsonb_typeof(pin.value) is distinct from 'object' then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    if not (pin.value ?& array['moduleRootId', 'bindingRevision'])
      or pin.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
      or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(pin.value)) <> 2 then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    if pg_catalog.jsonb_typeof(pin.value -> 'moduleRootId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(pin.value -> 'bindingRevision') is distinct from 'number' then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;

    module_root_text := pin.value ->> 'moduleRootId';
    if module_root_text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or not pg_catalog.pg_input_is_valid(module_root_text, 'uuid') then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    expected_module_root_id := module_root_text::uuid;
    if expected_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
      or module_root_text is distinct from expected_module_root_id::text then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;

    binding_revision_text := pin.value ->> 'bindingRevision';
    if binding_revision_text !~ '^[1-9][0-9]*$'
      or not pg_catalog.pg_input_is_valid(binding_revision_text, 'bigint') then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    expected_binding_revision := binding_revision_text::bigint;
    if expected_binding_revision not between 1 and 9007199254740991
      or (previous_module_root_id is not null
        and previous_module_root_id >= expected_module_root_id) then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    previous_module_root_id := expected_module_root_id;
  end loop;

  select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'moduleRootId', (item.value ->> 'moduleRootId')::uuid,
        'bindingRevision', (item.value ->> 'bindingRevision')::bigint
      )
      order by (item.value ->> 'moduleRootId')::uuid
    )
  into strict normalized_pins
  from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value);
  if p_expected_module_bindings is distinct from normalized_pins then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup binding pins are invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;
  initial_context := vortex_access.validated_human_request_context();
  if initial_context ->> 'callerKind' is distinct from 'human'
    or (initial_context ->> 'organizationId')::uuid is distinct from initial_authority.organization_id
    or (initial_context ->> 'organizationAccountId')::uuid is distinct from initial_authority.organization_account_id
    or (initial_context ->> 'accessVersion')::bigint is distinct from initial_authority.access_version
    or (initial_context ->> 'correlationId')::uuid is distinct from initial_authority.correlation_id
    or (initial_context ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    raise exception using errcode = '42501',
      message = 'Provisioned Application lifecycle setup authority is unavailable';
  end if;

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where root.root_id = p_application_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application'
    and release.release_revision = p_application_release_revision;

  select root.key into strict application_definition_key
  from vortex_definition.roots as root
  where root.root_id = p_application_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application';

  if not application_release.validation_contract_version = any (
      vortex_definition.accepted_contract_version('application')
    )
    or application_release.compilation_output #>> '{kind}' is distinct from 'application'
    or application_release.compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from p_application_root_id::text
    or application_release.compilation_output #>> '{validationContractVersion}'
      is distinct from application_release.validation_contract_version then
    raise exception using errcode = '23514',
      message = 'Exact Application release is unavailable';
  end if;

  select snapshot.* into strict permission_snapshot
  from vortex_access.read_application_permission_snapshot(
    initial_authority.organization_id, p_application_root_id
  ) as snapshot;
  if permission_snapshot.organization_id is distinct from initial_authority.organization_id
    or permission_snapshot.application_root_id is distinct from p_application_root_id
    or permission_snapshot.registration_revision not between 1 and 9007199254740991
    or permission_snapshot.release_revision is distinct from p_application_release_revision
    or permission_snapshot.definition_key is distinct from application_definition_key
    or permission_snapshot.release_version is distinct from application_release.release_version
    or permission_snapshot.validation_contract_version is distinct from application_release.validation_contract_version
    or permission_snapshot.content_fingerprint is distinct from application_release.content_fingerprint
    or permission_snapshot.resolution_fingerprint is distinct from application_release.resolution_fingerprint then
    raise exception using errcode = '40001',
      message = 'Application permission registration is stale or unavailable';
  end if;

  select pg_catalog.count(*) into closure_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  if closure_count < 1
    or closure_count > 10000
    or closure_count <> expected_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Application installation binding set is incomplete';
  end if;

  for pin in
    select required.target_root_id
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_module.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
  end loop;

  for pin in
    select required.target_root_id
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id
    for share;
  end loop;

  for locked_binding in
    select binding.*
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.state <> 'detached'
    order by binding.module_root_id
    for share
  loop
    if locked_binding.state <> 'detached'
      and not exists (
        select 1
        from vortex_definition.reachable_module_dependency_edges(
          p_application_root_id, p_application_release_revision
        ) as required
        where required.target_root_id = locked_binding.module_root_id
      ) then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed or are incomplete';
    end if;
  end loop;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    select (expected.value ->> 'bindingRevision')::bigint
    into strict expected_binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = pin.target_root_id;

    select binding.* into strict locked_binding
    from vortex_module.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id;

    select release.* into strict module_release
    from vortex_definition.releases as release
    where release.root_id = locked_binding.module_root_id
      and release.release_revision = locked_binding.module_release_revision;

    if locked_binding.binding_revision is distinct from expected_binding_revision
      or locked_binding.application_release_revision is distinct from p_application_release_revision
      or locked_binding.module_release_revision is distinct from pin.target_release_revision
      or locked_binding.state is distinct from 'provisioned'
      or module_release.content_fingerprint is distinct from pin.dependency_content_fingerprint
      or module_release.resolution_fingerprint is distinct from pin.evidence_fingerprint then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed or are incomplete';
    end if;

    select provision.* into strict storage_provision
    from vortex_record.read_exact_module_storage_provision(
      pin.target_root_id, pin.target_release_revision
    ) as provision;
    if storage_provision.module_root_id is distinct from pin.target_root_id
      or storage_provision.release_revision is distinct from pin.target_release_revision
      or storage_provision.storage_contract_ids is null
      or (
        pg_catalog.cardinality(storage_provision.storage_contract_ids) > 0
        and (
          pg_catalog.array_ndims(storage_provision.storage_contract_ids) is distinct from 1
          or pg_catalog.array_lower(storage_provision.storage_contract_ids, 1) is distinct from 1
        )
      )
      or locked_binding.storage_contract_ids is distinct from storage_provision.storage_contract_ids
      or exists (
        select 1
        from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
        where stored.contract_id is null
          or stored.contract_id = '00000000-0000-0000-0000-000000000000'::uuid
      ) then
      raise exception using errcode = '40001',
        message = 'Application installation storage evidence changed or is incomplete';
    end if;

    select pg_catalog.count(*),
      pg_catalog.count(distinct stored.contract_id)
    into storage_contract_id_count, distinct_storage_contract_id_count
    from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id);
    if storage_contract_id_count <> distinct_storage_contract_id_count then
      raise exception using errcode = '40001',
        message = 'Application installation storage evidence is invalid';
    end if;

    all_storage_contract_ids := all_storage_contract_ids || storage_provision.storage_contract_ids;
    module_bindings := module_bindings || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'moduleRootId', pin.target_root_id,
        'moduleReleaseRevision', pin.target_release_revision,
        'bindingRevision', locked_binding.binding_revision,
        'state', 'provisioned',
        'storageContractIds', pg_catalog.to_jsonb(storage_provision.storage_contract_ids)
      )
    );
  end loop;

  select coalesce(
      pg_catalog.array_agg(distinct stored.contract_id order by stored.contract_id),
      array[]::uuid[]
    )
  into union_storage_contract_ids
  from pg_catalog.unnest(all_storage_contract_ids) as stored(contract_id);

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  select evaluated.* into strict install_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  select evaluated.* into strict install_scope_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  current_context := vortex_access.validated_human_request_context();
  if current_authority.organization_id is distinct from initial_authority.organization_id
    or current_authority.organization_account_id is distinct from initial_authority.organization_account_id
    or current_authority.access_version is distinct from initial_authority.access_version
    or current_authority.correlation_id is distinct from initial_authority.correlation_id
    or current_context is distinct from initial_context
    or current_context ->> 'callerKind' is distinct from 'human'
    or (current_context ->> 'organizationId')::uuid is distinct from current_authority.organization_id
    or (current_context ->> 'organizationAccountId')::uuid is distinct from current_authority.organization_account_id
    or (current_context ->> 'accessVersion')::bigint is distinct from current_authority.access_version
    or (current_context ->> 'correlationId')::uuid is distinct from current_authority.correlation_id
    or (current_context ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    raise exception using errcode = '40001',
      message = 'Application installation authority changed';
  end if;

  if install_decision.outcome is distinct from 'eligible'
    or install_decision.operation_key is distinct from
      'platform.organization.applications.install'
    or install_decision.target_kind is distinct from 'organization'
    or install_decision.target_application_root_id is not null
    or install_decision.organization_id is distinct from current_authority.organization_id
    or install_decision.organization_account_id is distinct from current_authority.organization_account_id
    or install_decision.access_version is distinct from current_authority.access_version
    or install_decision.correlation_id is distinct from current_authority.correlation_id
    or install_decision.reason_code is not null
    or install_scope_decision.outcome is distinct from 'eligible'
    or install_scope_decision.operation_key is distinct from
      'platform.organization.applications.install_scope'
    or install_scope_decision.target_kind is distinct from 'organization'
    or install_scope_decision.target_application_root_id is not null
    or install_scope_decision.organization_id is distinct from current_authority.organization_id
    or install_scope_decision.organization_account_id is distinct from
      current_authority.organization_account_id
    or install_scope_decision.access_version is distinct from current_authority.access_version
    or install_scope_decision.correlation_id is distinct from current_authority.correlation_id
    or install_scope_decision.reason_code is not null then
    raise exception using errcode = '42501',
      message = 'Application installation authority is unavailable';
  end if;

  completion_time := pg_catalog.clock_timestamp();
  context_expires_at := (current_context ->> 'expiresAt')::timestamptz;
  if install_decision.checked_at is null
    or install_decision.checked_at > completion_time
    or install_decision.valid_until is null
    or install_decision.valid_until <= completion_time
    or install_scope_decision.checked_at is null
    or install_scope_decision.checked_at > completion_time
    or install_scope_decision.valid_until is null
    or install_scope_decision.valid_until <= completion_time
    or not pg_catalog.isfinite(context_expires_at)
    or context_expires_at <= completion_time then
    raise exception using errcode = '42501',
      message = 'Application installation context expired';
  end if;
  if current_context ? 'delegatedContext' then
    delegated_expires_at := (current_context #>> '{delegatedContext,expiresAt}')::timestamptz;
    if not pg_catalog.isfinite(delegated_expires_at)
      or delegated_expires_at <= completion_time then
      raise exception using errcode = '42501',
        message = 'Application installation delegation expired';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'registrationRevision', permission_snapshot.registration_revision,
    'moduleBindings', module_bindings,
    'storageContractIds', pg_catalog.to_jsonb(union_storage_contract_ids)
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application lifecycle setup evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application lifecycle setup evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup command is invalid';
end
$function$;


ALTER FUNCTION vortex_module.read_provisioned_lifecycle_setup_targets_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION read_provisioned_lifecycle_setup_targets_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.read_provisioned_lifecycle_setup_targets_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Module-owned complete exact provisioned lifecycle setup targets for the authorized Record setup reader.';


--
-- Name: record_application_installation_outcome(uuid, uuid, bigint, text); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority record;
  pin_count integer;
  changed_count integer;
begin
  if p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or p_state is null
    or p_state not in ('active', 'detached') then
    raise exception using errcode = '22023',
      message = 'Application installation outcome command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_application_installation_authority() as locked;

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );

  -- Activity records only a change this transaction made: every pinned binding
  -- must be in the reported state for this exact release and changed since this
  -- transaction began. The fixed activate/detach operations stamp changed_at
  -- with their statement time and keep the rows locked until commit, so a
  -- binding they changed here satisfies this and an untouched one does not.
  select pg_catalog.count(*)::integer into changed_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  join vortex_module.installation_bindings as binding
    on binding.organization_id = authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id
  where binding.state = p_state
    and binding.application_release_revision = p_application_release_revision
    and binding.module_release_revision = required.target_release_revision
    and binding.changed_at >= pg_catalog.transaction_timestamp();

  if pin_count = 0 or changed_count <> pin_count then
    raise exception using errcode = '40001',
      message = 'Application installation outcome is not a change of this transaction';
  end if;

  perform vortex_module.append_application_installation_activity_internal(
    p_activity_id,
    p_application_root_id,
    case p_state
      when 'active' then 'activate_application_installation'
      else 'withdraw_application_installation'
    end
  );
end
$$;


ALTER FUNCTION vortex_module.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) IS 'Appends content-free Activity for an Application activation or withdrawal made earlier in the same protected transaction.';


--
-- Name: record_lifecycle_provisioned_setup_target_internal(uuid, uuid, bigint, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  provisioned_release_revision bigint;
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_binding_revision is null
    or p_expected_binding_revision not between 1 and 9007199254740991
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    -- A workflow reference is either completely absent or completely present.
    or (p_workflow_id is null) <> (p_expected_workflow_revision is null)
    or (p_workflow_id is not null
      and p_workflow_id = '00000000-0000-0000-0000-000000000000'::uuid)
    or (p_expected_workflow_revision is not null
      and p_expected_workflow_revision not between 1 and 9007199254740991) then
    return false;
  end if;

  select binding.application_release_revision into provisioned_release_revision
  from vortex_module.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'provisioned'
    and binding.binding_revision = p_expected_binding_revision
    and p_storage_contract_id = any (binding.storage_contract_ids)
  order by binding.module_root_id
  limit 1
  for share;
  if not found then
    return false;
  end if;

  if p_workflow_id is null then
    return true;
  end if;

  -- There is no free-standing workflow revision in a compiled definition: the
  -- Application release revision is the workflow revision runtime pins.
  if provisioned_release_revision <> p_expected_workflow_revision then
    return false;
  end if;

  select true into matched
  from vortex_definition.releases as application_release
  join vortex_definition.roots as application_root
    on application_root.root_id = application_release.root_id
  where application_release.root_id = p_application_root_id
    and application_release.release_revision = provisioned_release_revision
    and application_root.organization_id = p_organization_id
    and application_root.kind = 'application'
    and application_release.compilation_output #>> '{kind}' = 'application'
    and application_release.compilation_output #>> '{canonical,envelope,rootId}'
      = p_application_root_id::text
    and application_release.compilation_output #>> '{validationContractVersion}'
      = application_release.validation_contract_version
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(
            application_release.compilation_output #> '{canonical,content,workflows}'
          ) = 'array'
            then application_release.compilation_output #> '{canonical,content,workflows}'
          else '[]'::jsonb
        end
      ) as workflow(value)
      where pg_catalog.jsonb_typeof(workflow.value) = 'object'
        and workflow.value ->> 'workflowId' = p_workflow_id::text
    )
  for share of application_release, application_root;

  return coalesce(matched, false);
end
$$;


ALTER FUNCTION vortex_module.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) IS 'Private provisioned-setup installation fact for one exact Application binding revision and, optionally, one workflow of that exact immutable release; never used by the #566 administration save.';


--
-- Name: record_lifecycle_target_is_installed_internal(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (p_application_root_id is not null
      and p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid) then
    return false;
  end if;
  select true into matched
  from vortex_module.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.state = 'active'
    and p_storage_contract_id = any (binding.storage_contract_ids)
    and (
      p_application_root_id is null
      or binding.application_root_id = p_application_root_id
    )
  limit 1
  for share;
  return coalesce(matched, false);
end
$$;


ALTER FUNCTION vortex_module.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) IS 'Private installation fact for record lifecycle policy administration; shares the matching active installation binding for the transaction.';


--
-- Name: record_lifecycle_workflow_is_installed_internal(uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  active_release_revision bigint;
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_workflow_id is null
    or p_workflow_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_workflow_revision is null
    or p_expected_workflow_revision not between 1 and 9007199254740991 then
    return false;
  end if;

  select binding.application_release_revision into active_release_revision
  from vortex_module.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'active'
    and p_storage_contract_id = any (binding.storage_contract_ids)
  order by binding.module_root_id
  limit 1
  for share;
  if not found or active_release_revision <> p_expected_workflow_revision then
    return false;
  end if;

  select true into matched
  from vortex_definition.releases as application_release
  join vortex_definition.roots as application_root
    on application_root.root_id = application_release.root_id
  where application_release.root_id = p_application_root_id
    and application_release.release_revision = active_release_revision
    and application_root.organization_id = p_organization_id
    and application_root.kind = 'application'
    and application_release.compilation_output #>> '{kind}' = 'application'
    and application_release.compilation_output #>> '{canonical,envelope,rootId}'
      = p_application_root_id::text
    and application_release.compilation_output #>> '{validationContractVersion}'
      = application_release.validation_contract_version
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(
            application_release.compilation_output #> '{canonical,content,workflows}'
          ) = 'array'
            then application_release.compilation_output #> '{canonical,content,workflows}'
          else '[]'::jsonb
        end
      ) as workflow(value)
      where pg_catalog.jsonb_typeof(workflow.value) = 'object'
        and workflow.value ->> 'workflowId' = p_workflow_id::text
    )
  for share of application_release, application_root;

  return coalesce(matched, false);
end
$$;


ALTER FUNCTION vortex_module.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) IS 'Private exact-active-Application workflow fact for record lifecycle policy administration; locks the matching installation and immutable Application release.';


--
-- Name: remove_abandoned_runtime_bundles_internal(integer); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.remove_abandoned_runtime_bundles_internal(
  p_limit integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  abandoned_bundle_ttl constant interval := interval '7 days';
  maximum_batch_size constant integer := 100;
  candidate_key record;
  bundle_row vortex_module.installation_runtime_bundles%rowtype;
  removed_bundle_keys jsonb := '[]'::jsonb;
  bundles_removed bigint := 0;
  bundle_parts_removed bigint := 0;
  access_plans_removed bigint := 0;
  orphaned_access_plans_removed bigint := 0;
  changed_rows bigint;
begin
  if p_limit is null or p_limit < 1 or p_limit > maximum_batch_size then
    raise exception using errcode = '22023',
      message = 'Runtime bundle cleanup batch is invalid';
  end if;

  for candidate_key in
    select bundle.organization_id, bundle.application_root_id,
      bundle.application_release_revision, bundle.bundle_format_version
    from vortex_module.installation_runtime_bundles as bundle
    where not exists (
      select 1
      from vortex_module.installation_bindings as binding
      where binding.organization_id = bundle.organization_id
        and binding.application_root_id = bundle.application_root_id
        and binding.application_release_revision = bundle.application_release_revision
        and binding.state in ('active', 'draining')
    )
      and (
        exists (
          select 1
          from vortex_module.installation_bindings as later_binding
          where later_binding.organization_id = bundle.organization_id
            and later_binding.application_root_id = bundle.application_root_id
            and later_binding.application_release_revision > bundle.application_release_revision
            and later_binding.state in ('active', 'draining')
        )
        or (
          bundle.built_at <= pg_catalog.statement_timestamp() - abandoned_bundle_ttl
          and not exists (
            select 1
            from vortex_module.installation_bindings as previous_binding
            where previous_binding.organization_id = bundle.organization_id
              and previous_binding.application_root_id = bundle.application_root_id
              and previous_binding.application_release_revision = bundle.application_release_revision
              and previous_binding.state = 'detached'
          )
        )
      )
    order by bundle.built_at, bundle.organization_id, bundle.application_root_id,
      bundle.application_release_revision, bundle.bundle_format_version
    limit p_limit
  loop
    perform 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = candidate_key.organization_id
      and binding.application_root_id = candidate_key.application_root_id
    order by binding.module_root_id
    for update;

    select bundle.* into bundle_row
    from vortex_module.installation_runtime_bundles as bundle
    where bundle.organization_id = candidate_key.organization_id
      and bundle.application_root_id = candidate_key.application_root_id
      and bundle.application_release_revision = candidate_key.application_release_revision
      and bundle.bundle_format_version = candidate_key.bundle_format_version
    for update of bundle skip locked;
    if not found then
      continue;
    end if;

    if exists (
      select 1
      from vortex_module.installation_bindings as binding
      where binding.organization_id = bundle_row.organization_id
        and binding.application_root_id = bundle_row.application_root_id
        and binding.application_release_revision = bundle_row.application_release_revision
        and binding.state in ('active', 'draining')
    ) then
      continue;
    end if;

    if not exists (
        select 1
        from vortex_module.installation_bindings as later_binding
        where later_binding.organization_id = bundle_row.organization_id
          and later_binding.application_root_id = bundle_row.application_root_id
          and later_binding.application_release_revision > bundle_row.application_release_revision
          and later_binding.state in ('active', 'draining')
      ) and (
        bundle_row.built_at > pg_catalog.statement_timestamp() - abandoned_bundle_ttl
        or exists (
          select 1
          from vortex_module.installation_bindings as previous_binding
          where previous_binding.organization_id = bundle_row.organization_id
            and previous_binding.application_root_id = bundle_row.application_root_id
            and previous_binding.application_release_revision = bundle_row.application_release_revision
            and previous_binding.state = 'detached'
        )
      ) then
      continue;
    end if;

    delete from vortex_module.installation_runtime_bundle_parts as part
    where part.organization_id = bundle_row.organization_id
      and part.application_root_id = bundle_row.application_root_id
      and part.application_release_revision = bundle_row.application_release_revision
      and part.bundle_format_version = bundle_row.bundle_format_version;
    get diagnostics changed_rows = row_count;
    bundle_parts_removed := bundle_parts_removed + changed_rows;

    delete from vortex_module.installation_runtime_bundles as bundle
    where bundle.organization_id = bundle_row.organization_id
      and bundle.application_root_id = bundle_row.application_root_id
      and bundle.application_release_revision = bundle_row.application_release_revision
      and bundle.bundle_format_version = bundle_row.bundle_format_version;
    get diagnostics changed_rows = row_count;
    if changed_rows = 1 then
      bundles_removed := bundles_removed + 1;
      removed_bundle_keys := removed_bundle_keys || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'organizationId', bundle_row.organization_id,
          'applicationRootId', bundle_row.application_root_id,
          'applicationReleaseRevision', bundle_row.application_release_revision
        )
      );
    end if;
  end loop;

  delete from vortex_record.installation_access_plans as plan
  where plan.plan_key in (
    select candidate.plan_key
    from vortex_record.installation_access_plans as candidate
    where exists (
      select 1
      from pg_catalog.jsonb_array_elements(removed_bundle_keys) as removed(bundle_key)
      where (removed.bundle_key ->> 'organizationId')::uuid = candidate.organization_id
        and (removed.bundle_key ->> 'applicationRootId')::uuid = candidate.application_root_id
        and (removed.bundle_key ->> 'applicationReleaseRevision')::bigint =
          candidate.application_release_revision
    )
      and not exists (
        select 1
        from vortex_module.installation_runtime_bundles as remaining
        where remaining.organization_id = candidate.organization_id
          and remaining.application_root_id = candidate.application_root_id
          and remaining.application_release_revision = candidate.application_release_revision
      )
      and not exists (
        select 1
        from vortex_module.installation_bindings as binding
        where binding.organization_id = candidate.organization_id
          and binding.application_root_id = candidate.application_root_id
          and binding.application_release_revision = candidate.application_release_revision
          and binding.state in ('active', 'draining')
      )
    order by candidate.plan_key
    limit p_limit
  );
  get diagnostics changed_rows = row_count;
  access_plans_removed := access_plans_removed + changed_rows;

  delete from vortex_record.installation_access_plans as plan
  where plan.plan_key in (
    select candidate.plan_key
    from vortex_record.installation_access_plans as candidate
    where candidate.created_at <= pg_catalog.statement_timestamp() - abandoned_bundle_ttl
      and not exists (
        select 1
        from vortex_module.installation_runtime_bundles as bundle
        where bundle.organization_id = candidate.organization_id
          and bundle.application_root_id = candidate.application_root_id
          and bundle.application_release_revision = candidate.application_release_revision
      )
      and not exists (
        select 1
        from vortex_module.installation_bindings as binding
        where binding.organization_id = candidate.organization_id
          and binding.application_root_id = candidate.application_root_id
          and binding.application_release_revision = candidate.application_release_revision
          and binding.state in ('active', 'draining')
      )
    order by candidate.plan_key
    limit p_limit
  );
  get diagnostics changed_rows = row_count;
  orphaned_access_plans_removed := changed_rows;

  return pg_catalog.jsonb_build_object(
    'bundlesRemoved', bundles_removed,
    'bundlePartsRemoved', bundle_parts_removed,
    'accessPlansRemoved', access_plans_removed,
    'orphanedAccessPlansRemoved', orphaned_access_plans_removed
  );
end
$function$;


ALTER FUNCTION vortex_module.remove_abandoned_runtime_bundles_internal(p_limit integer) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION remove_abandoned_runtime_bundles_internal(p_limit integer); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.remove_abandoned_runtime_bundles_internal(p_limit integer) IS 'Removes one bounded batch of expired never-activated or superseded runtime bundles and orphaned access plans.';


--
-- Name: remove_installation_runtime_bundles_internal(uuid); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.remove_installation_runtime_bundles_internal(
  p_application_root_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  authority record;
  bundle_list jsonb;
  bundles_removed bigint;
  bundle_parts_removed bigint;
  access_plans_removed bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Runtime bundle uninstall command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_application_installation_authority() as locked;

  if not exists (
    select 1
    from vortex_definition.roots as root
    where root.root_id = p_application_root_id
      and root.organization_id = authority.organization_id
      and root.kind = 'application'
  ) then
    raise exception using errcode = 'P0002',
      message = 'Application installation is unavailable';
  end if;

  perform 1
  from vortex_module.installation_bindings as binding
  where binding.organization_id = authority.organization_id
    and binding.application_root_id = p_application_root_id
  order by binding.module_root_id
  for update;

  if exists (
    select 1
    from vortex_module.installation_bindings as binding
    where binding.organization_id = authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.state in ('active', 'draining')
  ) then
    raise exception using errcode = '40001',
      message = 'Runtime bundles cannot be removed before installation drain completes';
  end if;

  delete from vortex_module.installation_runtime_bundle_parts as part
  where part.organization_id = authority.organization_id
    and part.application_root_id = p_application_root_id;
  get diagnostics bundle_parts_removed = row_count;

  with removed_bundles as (
    delete from vortex_module.installation_runtime_bundles as bundle
    where bundle.organization_id = authority.organization_id
      and bundle.application_root_id = p_application_root_id
    returning bundle.application_release_revision, bundle.bundle_format_version
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'applicationReleaseRevision', removed.application_release_revision,
          'bundleFormatVersion', removed.bundle_format_version
        ) order by removed.application_release_revision, removed.bundle_format_version
      ),
      '[]'::jsonb
    ),
    pg_catalog.count(*)
  into bundle_list, bundles_removed
  from removed_bundles as removed;

  delete from vortex_record.installation_access_plans as plan
  where plan.organization_id = authority.organization_id
    and plan.application_root_id = p_application_root_id;
  get diagnostics access_plans_removed = row_count;

  return pg_catalog.jsonb_build_object(
    'bundles', bundle_list,
    'bundlePartsRemoved', bundle_parts_removed,
    'accessPlansRemoved', access_plans_removed
  );
end
$function$;


ALTER FUNCTION vortex_module.remove_installation_runtime_bundles_internal(p_application_root_id uuid) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION remove_installation_runtime_bundles_internal(p_application_root_id uuid); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.remove_installation_runtime_bundles_internal(p_application_root_id uuid) IS 'Lists and removes all runtime bundle registrations and access plans for one authorised installation after its bindings are detached.';


--
-- Name: repair_active_installation_runtime_bundle_internal(jsonb, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.repair_active_installation_runtime_bundle_internal(
  p_expected_identity jsonb,
  p_parts jsonb
)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare

  expected_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  checked_context jsonb;
  selected_organization_id uuid;
  part_item jsonb;
  section_value text;
  ordinal_value bigint;
  byte_size_value bigint;
  content_text text;
  content_bytes bytea;
  sha256_value text;
  total_size_value bigint := 0;
  parts_manifest jsonb;
  inserted_rows bigint;
  stored_bundle vortex_module.installation_runtime_bundles%rowtype;
  source_manifest jsonb;
  section_payloads jsonb := '{}'::jsonb;
  section_text text;
  application_content jsonb;
  expected_modules jsonb;
  expected_trigger_index jsonb;
  expected_access_plan jsonb;
  p_application_root_id uuid;
  p_application_release_revision bigint;
  p_bundle_format_version integer:=2;
  p_pin_fingerprint text;
  active_source jsonb;
  mapping jsonb;
  final_mapping jsonb;
  stable_plan jsonb;
begin
  if pg_catalog.jsonb_typeof(p_expected_identity) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_parts) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_parts)<pg_catalog.cardinality(expected_sections) then
    raise exception using errcode='22023', message='Active runtime repair command is invalid';
  end if;
  -- This current HUMAN viewer path deliberately has no installation/manage
  -- decision, delegated installer scope or provisioned-binding authority.
  mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  stable_plan:=vortex_record.resolve_active_bundle_record_access_plan_internal(p_expected_identity);
  p_application_root_id:=(mapping #>> '{identity,applicationRootId}')::uuid;
  p_application_release_revision:=(mapping #>> '{identity,applicationReleaseRevision}')::bigint;
  p_pin_fingerprint:=mapping #>> '{identity,pinFingerprint}';
  selected_organization_id:=(mapping #>> '{identity,organizationId}')::uuid;
  active_source:=pg_catalog.jsonb_build_object(
    'organizationId',mapping #> '{identity,organizationId}',
    'applicationRootId',mapping #> '{identity,applicationRootId}',
    'applicationReleaseRevision',mapping #> '{identity,applicationReleaseRevision}',
    'pinFingerprint',mapping #> '{identity,pinFingerprint}',
    'application',mapping -> 'application','modules',mapping -> 'modules',
    'preparedRecordAccessPlan',stable_plan);
  -- Exclusive bundle lock follows already-held binding and storage locks.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'vortex_module.runtime_bundle:' || selected_organization_id::text || ':' ||
      p_application_root_id::text || ':' || p_application_release_revision::text || ':2',0));
  final_mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  if final_mapping is distinct from mapping then
    raise exception using errcode='40001', message='Active runtime repair changed while waiting';
  end if;
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', active_source #> '{application,rootId}',
      'definitionKey', active_source #> '{application,key}',
      'releaseRevision', active_source #> '{application,releaseRevision}',
      'releaseVersion', active_source #> '{application,releaseVersion}',
      'validationContractVersion', active_source #> '{application,validationContractVersion}',
      'contentFingerprint', active_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', active_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', active_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', active_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', active_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );
  for section_value in
    select required.section
    from pg_catalog.unnest(expected_sections) as required(section)
  loop
    select pg_catalog.string_agg(item.value ->> 'content', '' order by
      (item.value ->> 'ordinal')::integer)
    into section_text
    from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    where item.value ->> 'section' = section_value;
    if section_text is null then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is unavailable';
    end if;
    begin
      section_payloads := section_payloads || pg_catalog.jsonb_build_object(
        section_value, section_text::jsonb
      );
    exception when others then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is invalid';
    end;
  end loop;
  application_content := active_source #> '{application,compilationOutput,canonical,content}';
  if application_content is null then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle Application content is unavailable';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'identity', pg_catalog.jsonb_build_object(
        'kind', module.value -> 'kind',
        'organizationId', module.value -> 'organizationId',
        'rootId', module.value -> 'rootId',
        'definitionKey', module.value -> 'key',
        'releaseRevision', module.value -> 'releaseRevision',
        'releaseVersion', module.value -> 'releaseVersion',
        'validationContractVersion', module.value -> 'validationContractVersion',
        'contentFingerprint', module.value -> 'contentFingerprint',
        'resolutionFingerprint', module.value -> 'resolutionFingerprint',
        'dependencyManifest', module.value -> 'dependencyManifest'
      ),
      'content', module.value #> '{compilationOutput,canonical,content}'
    ) order by (module.value ->> 'rootId') collate "C"), '[]'::jsonb)
  into expected_modules
  from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value);
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'flowId', flow.value -> 'id', 'trigger', trigger.value
    ) order by (flow.value ->> 'id') collate "C", (trigger.value ->> 'id') collate "C"), '[]'::jsonb)
  into expected_trigger_index
  from pg_catalog.jsonb_array_elements(application_content -> 'flows') as flow(value)
  cross join lateral pg_catalog.jsonb_array_elements(flow.value -> 'triggers') as trigger(value);
  select pg_catalog.jsonb_build_object(
    'preparedRecordAccessPlan', active_source -> 'preparedRecordAccessPlan',
    'declaredPermissions', pg_catalog.jsonb_build_object(
      'application', application_content -> 'permissions',
      'modules', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'rootId', module.value -> 'rootId',
            'permissions', module.value #> '{compilationOutput,canonical,content,permissions}'
          ) order by (module.value ->> 'rootId') collate "C")
        from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value)
      ), '[]'::jsonb)
    )
  ) into expected_access_plan;
  if section_payloads -> 'navigation' is distinct from application_content -> 'navigation'
    or section_payloads -> 'flows' is distinct from pg_catalog.jsonb_build_object(
      'flows', application_content -> 'flows',
      'flowBindings', application_content -> 'flowBindings'
    )
    or section_payloads -> 'trigger_index' is distinct from expected_trigger_index
    or section_payloads -> 'theme' is distinct from application_content -> 'theme'
    or section_payloads -> 'component_registry' is distinct from application_content -> 'platformBlockDependencies'
    or section_payloads -> 'tool_bundle' is distinct from active_source #> '{application,compilationOutput,toolBundle}'
    or section_payloads -> 'access_plan' is distinct from expected_access_plan
    or section_payloads #> '{pages,application,identity}' is distinct from (
      pg_catalog.jsonb_build_object(
        'kind', active_source #> '{application,kind}',
        'organizationId', active_source #> '{application,organizationId}',
        'rootId', active_source #> '{application,rootId}',
        'definitionKey', active_source #> '{application,key}',
        'releaseRevision', active_source #> '{application,releaseRevision}',
        'releaseVersion', active_source #> '{application,releaseVersion}',
        'validationContractVersion', active_source #> '{application,validationContractVersion}',
        'contentFingerprint', active_source #> '{application,contentFingerprint}',
        'resolutionFingerprint', active_source #> '{application,resolutionFingerprint}',
        'dependencyManifest', active_source #> '{application,dependencyManifest}'
      )
      || case
        when active_source #> '{application,compilationOutput,platformCompatibilityVersion}' is null
          then '{}'::jsonb
        else pg_catalog.jsonb_build_object(
          'platformCompatibilityVersion',
          active_source #> '{application,compilationOutput,platformCompatibilityVersion}'
        )
      end
    )
    or section_payloads #> '{pages,application,content}' is distinct from
      application_content - array[
        'navigation', 'flows', 'flowBindings', 'theme',
        'platformBlockDependencies', 'shells', 'pages'
      ]::text[]
    or section_payloads #> '{pages,application,shells}' is distinct from application_content -> 'shells'
    or section_payloads #> '{pages,application,pages}' is distinct from application_content -> 'pages'
    or section_payloads #> '{pages,modules}' is distinct from expected_modules
    or pg_catalog.jsonb_typeof(section_payloads #> '{pages,resolvedCompositions}') is distinct from 'array'
    or pg_catalog.jsonb_array_length(section_payloads #> '{pages,resolvedCompositions}') <>
      pg_catalog.jsonb_array_length(application_content -> 'pages') then
    raise exception using errcode = '23514',
      message = 'Installation runtime bundle sections do not match current immutable source';
  end if;
  for part_item in
    select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
  loop
    if pg_catalog.jsonb_typeof(part_item) is distinct from 'object' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    if not (part_item ?& array['section', 'ordinal', 'byteSize', 'sha256', 'content'])
      or part_item - array['section', 'ordinal', 'byteSize', 'sha256', 'content'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(part_item -> 'section') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'ordinal') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'sha256') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'content') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;

    section_value := part_item ->> 'section';
    if not (section_value = any (expected_sections))
      or (part_item ->> 'ordinal') !~ '^(0|[1-9][0-9]*)$'
      or pg_catalog.length(part_item ->> 'ordinal') > 10
      or (part_item ->> 'byteSize') !~ '^[1-9][0-9]*$'
      or pg_catalog.length(part_item ->> 'byteSize') > 7 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    ordinal_value := (part_item ->> 'ordinal')::bigint;
    byte_size_value := (part_item ->> 'byteSize')::bigint;
    content_text := part_item ->> 'content';
    if ordinal_value > 2147483647 or byte_size_value > 1048575 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part exceeds its limit';
    end if;

    content_bytes := pg_catalog.convert_to(content_text, 'UTF8');
    if pg_catalog.octet_length(content_bytes) <> byte_size_value then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part size is invalid';
    end if;
    sha256_value := 'sha256:' || pg_catalog.encode(
      extensions.digest(content_bytes, 'sha256'), 'hex'
    );
    if (part_item ->> 'sha256') !~ '^sha256:[a-f0-9]{64}$'
      or sha256_value <> (part_item ->> 'sha256') then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part fingerprint is invalid';
    end if;
    total_size_value := total_size_value + byte_size_value;
    if total_size_value > 9007199254740991 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle is too large';
    end if;
  end loop;

  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section', (item.value ->> 'ordinal')::integer
      having pg_catalog.count(*) > 1
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section'
      having pg_catalog.min((item.value ->> 'ordinal')::integer) <> 0
        or pg_catalog.max((item.value ->> 'ordinal')::integer) <>
          pg_catalog.count(*) - 1
    )
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle sections are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'section', item.value ->> 'section',
      'ordinal', (item.value ->> 'ordinal')::integer,
      'byteSize', (item.value ->> 'byteSize')::bigint,
      'sha256', item.value ->> 'sha256'
    ) order by pg_catalog.array_position(
      expected_sections, item.value ->> 'section'
    ), (item.value ->> 'ordinal')::integer
  )
  into parts_manifest
  from pg_catalog.jsonb_array_elements(p_parts) as item(value);

  insert into vortex_module.installation_runtime_bundles (
    organization_id, application_root_id, application_release_revision,
    bundle_format_version, pin_fingerprint, source_manifest, parts, total_size_bytes
  ) values (
    selected_organization_id, p_application_root_id, p_application_release_revision,
    p_bundle_format_version, p_pin_fingerprint, source_manifest, parts_manifest, total_size_value
  ) on conflict (
    organization_id, application_root_id, application_release_revision, bundle_format_version
  ) do nothing;
  get diagnostics inserted_rows = row_count;

  if inserted_rows = 0 then
    select stored.* into stored_bundle
    from vortex_module.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
    if not found then
      raise exception using errcode = '40001',
        message = 'Installation runtime bundle changed concurrently';
    end if;
    if stored_bundle.pin_fingerprint <> p_pin_fingerprint
      or stored_bundle.source_manifest is distinct from source_manifest
      or stored_bundle.parts is distinct from parts_manifest
      or stored_bundle.total_size_bytes is distinct from total_size_value
      or (select pg_catalog.count(*) from vortex_module.installation_runtime_bundle_parts as part
        where part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version)
        <> pg_catalog.jsonb_array_length(p_parts)
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        left join vortex_module.installation_runtime_bundle_parts as part
          on part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version
          and part.section = item.value ->> 'section'
          and part.ordinal = (item.value ->> 'ordinal')::integer
        where part.content_bytes is distinct from pg_catalog.convert_to(item.value ->> 'content', 'UTF8')
      ) then
      raise exception using errcode = '23505',
        message = 'Installation runtime bundle pin fingerprint differs';
    end if;
  else
    for part_item in
      select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    loop
      insert into vortex_module.installation_runtime_bundle_parts (
        organization_id, application_root_id, application_release_revision,
        bundle_format_version, section, ordinal, content_bytes
      ) values (
        selected_organization_id, p_application_root_id, p_application_release_revision,
        p_bundle_format_version, part_item ->> 'section',
        (part_item ->> 'ordinal')::integer,
        pg_catalog.convert_to(part_item ->> 'content', 'UTF8')
      );
    end loop;

    select stored.* into strict stored_bundle
    from vortex_module.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
  end if;

  final_mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  if final_mapping is distinct from mapping then
    raise exception using errcode='40001', message='Active runtime repair identity changed';
  end if;
  return pg_catalog.jsonb_build_object(
    'organizationId', stored_bundle.organization_id,
    'applicationRootId', stored_bundle.application_root_id,
    'applicationReleaseRevision', stored_bundle.application_release_revision,
    'bundleFormatVersion', stored_bundle.bundle_format_version,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest,
    'parts', stored_bundle.parts,
    'totalSizeBytes', stored_bundle.total_size_bytes,
    'builtAt', stored_bundle.built_at
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.repair_active_installation_runtime_bundle_internal(p_expected_identity jsonb, p_parts jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION repair_active_installation_runtime_bundle_internal(p_expected_identity jsonb, p_parts jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.repair_active_installation_runtime_bundle_internal(p_expected_identity jsonb, p_parts jsonb) IS 'Atomically repairs only the current active immutable format2 bundle under a current HUMAN viewer transaction, with complete source and byte replay equality and no installation authority.';


--
-- Name: resolve_addressed_active_application_identity(text); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.resolve_addressed_active_application_identity(p_application_key text)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare
  checked_context jsonb;
  final_context jsonb;
  selected_root uuid;
  installation jsonb;
  registered_app record;
begin
  if p_application_key is null or pg_catalog.length(p_application_key) not between 3 and 120
    or p_application_key !~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*(\.[a-z][a-z0-9]*(_[a-z0-9]+)*)+$' or exists(select 1 from pg_catalog.unnest(pg_catalog.string_to_array(p_application_key,'.')) as segment(value) where pg_catalog.length(segment.value)>40) then
    raise exception using errcode='22023', message='Application address is invalid';
  end if;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Application address is unavailable';
  end if;
  select root.root_id into strict selected_root from vortex_definition.roots as root
  where root.organization_id=(checked_context ->> 'organizationId')::uuid
    and root.kind='application' and root.key=p_application_key;
  installation:=vortex_module.read_active_installation_for_scope_internal(
    (checked_context ->> 'organizationId')::uuid,selected_root);
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(
    (checked_context ->> 'organizationId')::uuid,selected_root) as snapshot;
  if registered_app.release_revision is distinct from (installation ->> 'applicationReleaseRevision')::bigint
    or registered_app.definition_key is distinct from p_application_key
    or exists(select 1 from vortex_module.installation_bindings as binding
      where binding.organization_id=(checked_context ->> 'organizationId')::uuid
        and binding.application_root_id=selected_root and binding.state not in ('active','detached')) then
    raise exception using errcode='40001', message='Application address changed';
  end if;
  final_context:=vortex_access.validated_human_request_context();
  if final_context is distinct from checked_context
    or pg_catalog.clock_timestamp()>=(final_context ->> 'expiresAt')::timestamptz
    or (final_context ? 'delegatedContext' and pg_catalog.clock_timestamp()>=(final_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (final_context ? 'supportContext' and pg_catalog.clock_timestamp()>=(final_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='40001', message='Application address context changed';
  end if;
  return pg_catalog.jsonb_build_object(
    'organizationId',checked_context -> 'organizationId','applicationRootId',selected_root,
    'definitionKey',p_application_key,'applicationReleaseRevision',installation -> 'applicationReleaseRevision');
exception when no_data_found or too_many_rows then
  raise exception using errcode='P0002', message='Application address is unavailable';
end
$function$;


ALTER FUNCTION vortex_module.resolve_addressed_active_application_identity(p_application_key text) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION resolve_addressed_active_application_identity(p_application_key text); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.resolve_addressed_active_application_identity(p_application_key text) IS 'Returns one exact active Application address under the current HUMAN organization request, without a Page grant.';


--
-- Name: storage_conversion_is_installed_internal(uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

CREATE FUNCTION vortex_module.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision is null
    or p_module_release_revision not between 1 and 9007199254740991
    or (p_application_root_id is not null
      and p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid) then
    return false;
  end if;
  select true into matched
  from vortex_module.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.state = 'active'
    and binding.module_root_id = p_module_root_id
    and binding.module_release_revision = p_module_release_revision
    and p_storage_contract_id = any (binding.storage_contract_ids)
    and (
      p_application_root_id is null
      or binding.application_root_id = p_application_root_id
    )
  order by binding.application_root_id
  limit 1
  for share;
  return coalesce(matched, false);
end
$$;


ALTER FUNCTION vortex_module.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) IS 'Private installation fact for storage conversion: shares the active installation of the exact Module release that installs the storage contract in this organisation scope.';


--
-- Name: write_installation_runtime_bundle_internal(uuid, bigint, integer, text, jsonb); Type: FUNCTION; Schema: vortex_module; Owner: vortex_module_owner
--

create or replace function vortex_module.write_installation_runtime_bundle_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_bundle_format_version integer,
  p_pin_fingerprint text,
  p_parts jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expected_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  permission_decision record;
  delegation_decision record;
  checked_context jsonb;
  selected_organization_id uuid;
  part_item jsonb;
  section_value text;
  ordinal_value bigint;
  byte_size_value bigint;
  content_text text;
  content_bytes bytea;
  sha256_value text;
  total_size_value bigint := 0;
  parts_manifest jsonb;
  inserted_rows bigint;
  stored_bundle vortex_module.installation_runtime_bundles%rowtype;
  expected_module_bindings jsonb;
  prepared_source jsonb;
  source_manifest jsonb;
  section_payloads jsonb := '{}'::jsonb;
  section_text text;
  application_content jsonb;
  expected_modules jsonb;
  expected_trigger_index jsonb;
  expected_access_plan jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_bundle_format_version is distinct from 2
    or p_pin_fingerprint is null or p_pin_fingerprint !~ '^sha256:[a-f0-9]{64}$'
    or p_parts is null or pg_catalog.jsonb_typeof(p_parts) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle command is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_parts) < pg_catalog.cardinality(expected_sections) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle command is invalid';
  end if;

  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible' then
    raise exception using errcode = '42501',
      message = 'Module installation authority is unavailable';
  end if;

  select evaluated.* into strict delegation_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  if delegation_decision.outcome is distinct from 'eligible'
    or delegation_decision.organization_id <> permission_decision.organization_id
    or delegation_decision.organization_account_id <> permission_decision.organization_account_id
    or delegation_decision.access_version <> permission_decision.access_version
    or delegation_decision.correlation_id <> permission_decision.correlation_id then
    raise exception using errcode = '42501',
      message = 'Module installation delegation is unavailable';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '40001',
      message = 'Module installation context changed';
  end if;
  selected_organization_id := permission_decision.organization_id;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = p_application_release_revision
    where root.root_id = p_application_root_id
      and root.organization_id = selected_organization_id
      and root.kind = 'application'
      and release.validation_contract_version = any (
        vortex_definition.accepted_contract_version('application')
      )
      and release.compilation_output #>> '{kind}' = 'application'
      and release.compilation_output #>> '{canonical,envelope,rootId}' =
        p_application_root_id::text
      and release.compilation_output #>> '{validationContractVersion}' = any (
        vortex_definition.accepted_contract_version('application')
      )
  ) then
    raise exception using errcode = 'P0002',
      message = 'Installation Application release is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId', binding.module_root_id,
      'moduleReleaseRevision', binding.module_release_revision,
      'bindingRevision', binding.binding_revision,
      'state', binding.state
    ) order by binding.module_root_id), '[]'::jsonb)
  into expected_module_bindings
  from vortex_module.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'provisioned';
  prepared_source := vortex_module.read_prepared_installation_runtime_source(
    p_application_root_id,
    p_application_release_revision,
    expected_module_bindings
  );
  if prepared_source is null
    or (prepared_source ->> 'organizationId')::uuid is distinct from selected_organization_id
    or (prepared_source ->> 'applicationRootId')::uuid is distinct from p_application_root_id
    or (prepared_source ->> 'applicationReleaseRevision')::bigint is distinct from p_application_release_revision
    or prepared_source ->> 'pinFingerprint' is distinct from p_pin_fingerprint then
    raise exception using errcode = '40001',
      message = 'Installation runtime bundle source changed';
  end if;
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', prepared_source #> '{application,rootId}',
      'definitionKey', prepared_source #> '{application,key}',
      'releaseRevision', prepared_source #> '{application,releaseRevision}',
      'releaseVersion', prepared_source #> '{application,releaseVersion}',
      'validationContractVersion', prepared_source #> '{application,validationContractVersion}',
      'contentFingerprint', prepared_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', prepared_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', prepared_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', prepared_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', prepared_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );
  for section_value in
    select required.section
    from pg_catalog.unnest(expected_sections) as required(section)
  loop
    select pg_catalog.string_agg(item.value ->> 'content', '' order by
      (item.value ->> 'ordinal')::integer)
    into section_text
    from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    where item.value ->> 'section' = section_value;
    if section_text is null then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is unavailable';
    end if;
    begin
      section_payloads := section_payloads || pg_catalog.jsonb_build_object(
        section_value, section_text::jsonb
      );
    exception when others then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is invalid';
    end;
  end loop;
  application_content := prepared_source #> '{application,compilationOutput,canonical,content}';
  if application_content is null then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle Application content is unavailable';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'identity', pg_catalog.jsonb_build_object(
        'kind', module.value -> 'kind',
        'organizationId', module.value -> 'organizationId',
        'rootId', module.value -> 'rootId',
        'definitionKey', module.value -> 'key',
        'releaseRevision', module.value -> 'releaseRevision',
        'releaseVersion', module.value -> 'releaseVersion',
        'validationContractVersion', module.value -> 'validationContractVersion',
        'contentFingerprint', module.value -> 'contentFingerprint',
        'resolutionFingerprint', module.value -> 'resolutionFingerprint',
        'dependencyManifest', module.value -> 'dependencyManifest'
      ),
      'content', module.value #> '{compilationOutput,canonical,content}'
    ) order by (module.value ->> 'rootId') collate "C"), '[]'::jsonb)
  into expected_modules
  from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value);
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'flowId', flow.value -> 'id', 'trigger', trigger.value
    ) order by (flow.value ->> 'id') collate "C", (trigger.value ->> 'id') collate "C"), '[]'::jsonb)
  into expected_trigger_index
  from pg_catalog.jsonb_array_elements(application_content -> 'flows') as flow(value)
  cross join lateral pg_catalog.jsonb_array_elements(flow.value -> 'triggers') as trigger(value);
  select pg_catalog.jsonb_build_object(
    'preparedRecordAccessPlan', prepared_source -> 'preparedRecordAccessPlan',
    'declaredPermissions', pg_catalog.jsonb_build_object(
      'application', application_content -> 'permissions',
      'modules', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'rootId', module.value -> 'rootId',
            'permissions', module.value #> '{compilationOutput,canonical,content,permissions}'
          ) order by (module.value ->> 'rootId') collate "C")
        from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
      ), '[]'::jsonb)
    )
  ) into expected_access_plan;
  if section_payloads -> 'navigation' is distinct from application_content -> 'navigation'
    or section_payloads -> 'flows' is distinct from pg_catalog.jsonb_build_object(
      'flows', application_content -> 'flows',
      'flowBindings', application_content -> 'flowBindings'
    )
    or section_payloads -> 'trigger_index' is distinct from expected_trigger_index
    or section_payloads -> 'theme' is distinct from application_content -> 'theme'
    or section_payloads -> 'component_registry' is distinct from application_content -> 'platformBlockDependencies'
    or section_payloads -> 'tool_bundle' is distinct from prepared_source #> '{application,compilationOutput,toolBundle}'
    or section_payloads -> 'access_plan' is distinct from expected_access_plan
    or section_payloads #> '{pages,application,identity}' is distinct from (
      pg_catalog.jsonb_build_object(
        'kind', prepared_source #> '{application,kind}',
        'organizationId', prepared_source #> '{application,organizationId}',
        'rootId', prepared_source #> '{application,rootId}',
        'definitionKey', prepared_source #> '{application,key}',
        'releaseRevision', prepared_source #> '{application,releaseRevision}',
        'releaseVersion', prepared_source #> '{application,releaseVersion}',
        'validationContractVersion', prepared_source #> '{application,validationContractVersion}',
        'contentFingerprint', prepared_source #> '{application,contentFingerprint}',
        'resolutionFingerprint', prepared_source #> '{application,resolutionFingerprint}',
        'dependencyManifest', prepared_source #> '{application,dependencyManifest}'
      )
      || case
        when prepared_source #> '{application,compilationOutput,platformCompatibilityVersion}' is null
          then '{}'::jsonb
        else pg_catalog.jsonb_build_object(
          'platformCompatibilityVersion',
          prepared_source #> '{application,compilationOutput,platformCompatibilityVersion}'
        )
      end
    )
    or section_payloads #> '{pages,application,content}' is distinct from
      application_content - array[
        'navigation', 'flows', 'flowBindings', 'theme',
        'platformBlockDependencies', 'shells', 'pages'
      ]::text[]
    or section_payloads #> '{pages,application,shells}' is distinct from application_content -> 'shells'
    or section_payloads #> '{pages,application,pages}' is distinct from application_content -> 'pages'
    or section_payloads #> '{pages,modules}' is distinct from expected_modules
    or pg_catalog.jsonb_typeof(section_payloads #> '{pages,resolvedCompositions}') is distinct from 'array'
    or pg_catalog.jsonb_array_length(section_payloads #> '{pages,resolvedCompositions}') <>
      pg_catalog.jsonb_array_length(application_content -> 'pages') then
    raise exception using errcode = '23514',
      message = 'Installation runtime bundle sections do not match current immutable source';
  end if;
  for part_item in
    select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
  loop
    if pg_catalog.jsonb_typeof(part_item) is distinct from 'object' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    if not (part_item ?& array['section', 'ordinal', 'byteSize', 'sha256', 'content'])
      or part_item - array['section', 'ordinal', 'byteSize', 'sha256', 'content'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(part_item -> 'section') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'ordinal') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'sha256') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'content') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;

    section_value := part_item ->> 'section';
    if not (section_value = any (expected_sections))
      or (part_item ->> 'ordinal') !~ '^(0|[1-9][0-9]*)$'
      or pg_catalog.length(part_item ->> 'ordinal') > 10
      or (part_item ->> 'byteSize') !~ '^[1-9][0-9]*$'
      or pg_catalog.length(part_item ->> 'byteSize') > 7 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    ordinal_value := (part_item ->> 'ordinal')::bigint;
    byte_size_value := (part_item ->> 'byteSize')::bigint;
    content_text := part_item ->> 'content';
    if ordinal_value > 2147483647 or byte_size_value > 1048575 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part exceeds its limit';
    end if;

    content_bytes := pg_catalog.convert_to(content_text, 'UTF8');
    if pg_catalog.octet_length(content_bytes) <> byte_size_value then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part size is invalid';
    end if;
    sha256_value := 'sha256:' || pg_catalog.encode(
      extensions.digest(content_bytes, 'sha256'), 'hex'
    );
    if (part_item ->> 'sha256') !~ '^sha256:[a-f0-9]{64}$'
      or sha256_value <> (part_item ->> 'sha256') then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part fingerprint is invalid';
    end if;
    total_size_value := total_size_value + byte_size_value;
    if total_size_value > 9007199254740991 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle is too large';
    end if;
  end loop;

  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section', (item.value ->> 'ordinal')::integer
      having pg_catalog.count(*) > 1
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section'
      having pg_catalog.min((item.value ->> 'ordinal')::integer) <> 0
        or pg_catalog.max((item.value ->> 'ordinal')::integer) <>
          pg_catalog.count(*) - 1
    )
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle sections are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'section', item.value ->> 'section',
      'ordinal', (item.value ->> 'ordinal')::integer,
      'byteSize', (item.value ->> 'byteSize')::bigint,
      'sha256', item.value ->> 'sha256'
    ) order by pg_catalog.array_position(
      expected_sections, item.value ->> 'section'
    ), (item.value ->> 'ordinal')::integer
  )
  into parts_manifest
  from pg_catalog.jsonb_array_elements(p_parts) as item(value);

  insert into vortex_module.installation_runtime_bundles (
    organization_id, application_root_id, application_release_revision,
    bundle_format_version, pin_fingerprint, source_manifest, parts, total_size_bytes
  ) values (
    selected_organization_id, p_application_root_id, p_application_release_revision,
    p_bundle_format_version, p_pin_fingerprint, source_manifest, parts_manifest, total_size_value
  ) on conflict (
    organization_id, application_root_id, application_release_revision, bundle_format_version
  ) do nothing;
  get diagnostics inserted_rows = row_count;

  if inserted_rows = 0 then
    select stored.* into stored_bundle
    from vortex_module.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
    if not found then
      raise exception using errcode = '40001',
        message = 'Installation runtime bundle changed concurrently';
    end if;
    if stored_bundle.pin_fingerprint <> p_pin_fingerprint
      or stored_bundle.source_manifest is distinct from source_manifest
      or stored_bundle.parts is distinct from parts_manifest
      or stored_bundle.total_size_bytes is distinct from total_size_value
      or (select pg_catalog.count(*) from vortex_module.installation_runtime_bundle_parts as part
        where part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version)
        <> pg_catalog.jsonb_array_length(p_parts)
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        left join vortex_module.installation_runtime_bundle_parts as part
          on part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version
          and part.section = item.value ->> 'section'
          and part.ordinal = (item.value ->> 'ordinal')::integer
        where part.content_bytes is distinct from pg_catalog.convert_to(item.value ->> 'content', 'UTF8')
      ) then
      raise exception using errcode = '23505',
        message = 'Installation runtime bundle pin fingerprint differs';
    end if;
  else
    for part_item in
      select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    loop
      insert into vortex_module.installation_runtime_bundle_parts (
        organization_id, application_root_id, application_release_revision,
        bundle_format_version, section, ordinal, content_bytes
      ) values (
        selected_organization_id, p_application_root_id, p_application_release_revision,
        p_bundle_format_version, part_item ->> 'section',
        (part_item ->> 'ordinal')::integer,
        pg_catalog.convert_to(part_item ->> 'content', 'UTF8')
      );
    end loop;

    select stored.* into strict stored_bundle
    from vortex_module.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', stored_bundle.organization_id,
    'applicationRootId', stored_bundle.application_root_id,
    'applicationReleaseRevision', stored_bundle.application_release_revision,
    'bundleFormatVersion', stored_bundle.bundle_format_version,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest,
    'parts', stored_bundle.parts,
    'totalSizeBytes', stored_bundle.total_size_bytes,
    'builtAt', stored_bundle.built_at
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_module.write_installation_runtime_bundle_internal(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer, p_pin_fingerprint text, p_parts jsonb) OWNER TO vortex_module_owner;

--
-- Name: FUNCTION write_installation_runtime_bundle_internal(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer, p_pin_fingerprint text, p_parts jsonb); Type: COMMENT; Schema: vortex_module; Owner: vortex_module_owner
--

COMMENT ON FUNCTION vortex_module.write_installation_runtime_bundle_internal(p_application_root_id uuid, p_application_release_revision bigint, p_bundle_format_version integer, p_pin_fingerprint text, p_parts jsonb) IS 'Atomically stores one immutable runtime bundle for an authorised exact Application release and pin fingerprint.';


--
-- Name: alert_signal_builder_key_is_valid(text); Type: FUNCTION; Schema: vortex_operations; Owner: postgres
--

create or replace function vortex_operations.alert_signal_builder_key_is_valid(p_key text)
returns boolean
language sql
immutable
security invoker
set search_path = ''
as $function$
  select p_key is not null
    and pg_catalog.length(p_key) between 1 and 40
    and p_key ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'
$function$;


ALTER FUNCTION vortex_operations.alert_signal_builder_key_is_valid(p_key text) OWNER TO postgres;

--
-- Name: FUNCTION alert_signal_builder_key_is_valid(p_key text); Type: COMMENT; Schema: vortex_operations; Owner: postgres
--

COMMENT ON FUNCTION vortex_operations.alert_signal_builder_key_is_valid(p_key text) IS 'Private check for the contract builder-key shape used by alert service and owning-role fields.';


--
-- Name: alert_signal_namespaced_key_is_valid(text); Type: FUNCTION; Schema: vortex_operations; Owner: postgres
--

create or replace function vortex_operations.alert_signal_namespaced_key_is_valid(p_key text)
returns boolean
language sql
immutable
security invoker
set search_path = ''
as $function$
  select p_key is not null
    and pg_catalog.length(p_key) between 3 and 120
    and p_key ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*(\.[a-z][a-z0-9]*(_[a-z0-9]+)*)+$'
    and not exists (
      select 1
      from pg_catalog.unnest(pg_catalog.string_to_array(p_key, '.')) as part(value)
      where pg_catalog.length(part.value) > 40
    )
$function$;


ALTER FUNCTION vortex_operations.alert_signal_namespaced_key_is_valid(p_key text) OWNER TO postgres;

--
-- Name: FUNCTION alert_signal_namespaced_key_is_valid(p_key text); Type: COMMENT; Schema: vortex_operations; Owner: postgres
--

COMMENT ON FUNCTION vortex_operations.alert_signal_namespaced_key_is_valid(p_key text) IS 'Private check for the contract namespaced-key shape used by alert code and runbook-reference fields.';


--
-- Name: read_open_alert_signals(integer); Type: FUNCTION; Schema: vortex_operations; Owner: vortex_operations_owner
--

create or replace function vortex_operations.read_open_alert_signals(
  p_limit integer default 100
)
returns table (
  signal_id uuid,
  code text,
  severity text,
  affected_service text,
  deduplication_key text,
  owning_role text,
  runbook_reference text,
  occurrence_count bigint,
  first_seen_at timestamptz,
  last_seen_at timestamptz,
  state text
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if p_limit is null or p_limit not between 1 and 500 then
    raise exception using errcode = '22023',
      message = 'Operations alert signal read is invalid';
  end if;

  return query
    select signal.signal_id, signal.code, signal.severity, signal.affected_service,
      signal.deduplication_key, signal.owning_role, signal.runbook_reference,
      signal.occurrence_count, signal.first_seen_at, signal.last_seen_at, signal.state
    from vortex_operations.alert_signals as signal
    where signal.state = 'open'
    order by signal.last_seen_at desc, signal.signal_id
    limit p_limit;
end
$function$;


ALTER FUNCTION vortex_operations.read_open_alert_signals(p_limit integer) OWNER TO vortex_operations_owner;

--
-- Name: FUNCTION read_open_alert_signals(p_limit integer); Type: COMMENT; Schema: vortex_operations; Owner: vortex_operations_owner
--

COMMENT ON FUNCTION vortex_operations.read_open_alert_signals(p_limit integer) IS 'Returns one bounded page of open Operations alert signals, most recently seen first.';


--
-- Name: record_alert_signal(text, text, text, text, text, text); Type: FUNCTION; Schema: vortex_operations; Owner: vortex_operations_owner
--

create or replace function vortex_operations.record_alert_signal(
  p_code text,
  p_severity text,
  p_affected_service text,
  p_deduplication_key text,
  p_owning_role text,
  p_runbook_reference text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  observed_at timestamptz := pg_catalog.clock_timestamp();
  stored vortex_operations.alert_signals%rowtype;
begin
  if p_code is null or not vortex_operations.alert_signal_namespaced_key_is_valid(p_code)
    or p_severity is null
    or p_severity not in ('warning', 'error', 'critical')
    or p_affected_service is null
    or not vortex_operations.alert_signal_builder_key_is_valid(p_affected_service)
    or p_deduplication_key is null
    or pg_catalog.length(p_deduplication_key) not between 16 and 200
    or p_deduplication_key !~ '^[a-z0-9][a-z0-9._:-]*$'
    or p_owning_role is null
    or not vortex_operations.alert_signal_builder_key_is_valid(p_owning_role)
    or p_runbook_reference is null
    or not vortex_operations.alert_signal_namespaced_key_is_valid(p_runbook_reference) then
    raise exception using errcode = '22023',
      message = 'Operations alert signal is invalid';
  end if;

  insert into vortex_operations.alert_signals (
    signal_id, code, severity, affected_service, deduplication_key,
    owning_role, runbook_reference, occurrence_count, first_seen_at, last_seen_at, state
  ) values (
    pg_catalog.gen_random_uuid(), p_code, p_severity, p_affected_service,
    p_deduplication_key, p_owning_role, p_runbook_reference, 1, observed_at, observed_at,
    'open'
  )
  on conflict (deduplication_key) do update set
    code = excluded.code,
    severity = excluded.severity,
    affected_service = excluded.affected_service,
    owning_role = excluded.owning_role,
    runbook_reference = excluded.runbook_reference,
    occurrence_count = least(
      vortex_operations.alert_signals.occurrence_count + 1, 9007199254740991
    ),
    last_seen_at = greatest(
      vortex_operations.alert_signals.last_seen_at, excluded.last_seen_at
    ),
    state = 'open'
  returning * into stored;

  return pg_catalog.jsonb_build_object(
    'signalId', stored.signal_id,
    'code', stored.code,
    'severity', stored.severity,
    'affectedService', stored.affected_service,
    'deduplicationKey', stored.deduplication_key,
    'owningRole', stored.owning_role,
    'runbookReference', stored.runbook_reference,
    'occurrenceCount', stored.occurrence_count,
    'firstSeenAt', pg_catalog.to_char(stored.first_seen_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'lastSeenAt', pg_catalog.to_char(stored.last_seen_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'state', stored.state
  );
end
$function$;


ALTER FUNCTION vortex_operations.record_alert_signal(p_code text, p_severity text, p_affected_service text, p_deduplication_key text, p_owning_role text, p_runbook_reference text) OWNER TO vortex_operations_owner;

--
-- Name: FUNCTION record_alert_signal(p_code text, p_severity text, p_affected_service text, p_deduplication_key text, p_owning_role text, p_runbook_reference text); Type: COMMENT; Schema: vortex_operations; Owner: vortex_operations_owner
--

COMMENT ON FUNCTION vortex_operations.record_alert_signal(p_code text, p_severity text, p_affected_service text, p_deduplication_key text, p_owning_role text, p_runbook_reference text) IS 'Validates one contract alert record and upserts it by deduplication key, incrementing the occurrence count, refreshing last-seen and reopening a resolved signal.';


--
-- Name: abandon_private_form_draft(uuid, bigint); Type: FUNCTION; Schema: vortex_page; Owner: vortex_page_owner
--

create or replace function vortex_page.abandon_private_form_draft(
  p_draft_id uuid,
  p_expected_revision bigint
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  stored vortex_page.form_drafts%rowtype;
begin
  if p_draft_id is null or not vortex_context.is_non_nil_uuid(p_draft_id::text)
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Private form draft abandon command is invalid';
  end if;

  select context.* into strict scope
  from vortex_page.private_form_draft_context_internal() as context;

  select draft.* into stored
  from vortex_page.form_drafts as draft
  where draft.draft_id = p_draft_id
    and draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
  for update;
  if not found or stored.expires_at <= pg_catalog.clock_timestamp() then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  if stored.revision <> p_expected_revision then
    return query select 'stale_revision'::text, null::jsonb;
    return;
  end if;

  delete from vortex_page.form_drafts as draft
  where draft.draft_id = p_draft_id;

  stored.revision := stored.revision + 1;
  stored.updated_at := pg_catalog.clock_timestamp();
  stored.field_values := '{}'::jsonb;
  stored.validation_state := '{}'::jsonb;

  return query select 'abandoned'::text,
    vortex_page.private_form_draft_to_json_internal(stored, 'abandoned');
end
$function$;


ALTER FUNCTION vortex_page.abandon_private_form_draft(p_draft_id uuid, p_expected_revision bigint) OWNER TO vortex_page_owner;

--
-- Name: FUNCTION abandon_private_form_draft(p_draft_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: vortex_page; Owner: vortex_page_owner
--

COMMENT ON FUNCTION vortex_page.abandon_private_form_draft(p_draft_id uuid, p_expected_revision bigint) IS 'Abandons and deletes one exact owned live private form draft at its expected revision.';


--
-- Name: create_private_form_draft(uuid, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_page; Owner: vortex_page_owner
--

create or replace function vortex_page.create_private_form_draft(
  p_form_id uuid,
  p_flow_id uuid,
  p_node_id uuid,
  p_subject_record_id uuid,
  p_field_values jsonb,
  p_validation_state jsonb
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  created_at timestamptz;
  new_draft_id uuid;
  stored vortex_page.form_drafts%rowtype;
begin
  if p_form_id is null or not vortex_context.is_non_nil_uuid(p_form_id::text)
    or (p_flow_id is not null and not vortex_context.is_non_nil_uuid(p_flow_id::text))
    or (p_node_id is not null and not vortex_context.is_non_nil_uuid(p_node_id::text))
    or (p_subject_record_id is not null
      and not vortex_context.is_non_nil_uuid(p_subject_record_id::text))
    or not vortex_page.private_form_draft_values_are_valid(p_field_values)
    or not vortex_page.private_form_draft_validation_is_valid(p_validation_state) then
    raise exception using errcode = '22023',
      message = 'Private form draft create command is invalid';
  end if;

  select context.* into strict scope
  from vortex_page.private_form_draft_context_internal() as context;

  -- An untouched draft that has reached its expiry no longer holds the scope.
  delete from vortex_page.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.application_root_id = scope.application_root_id
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
    and draft.expires_at <= pg_catalog.clock_timestamp();

  perform vortex_page.private_form_draft_purge_internal(scope.organization_id, 100);

  perform 1
  from vortex_page.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.application_root_id = scope.application_root_id
    and draft.installation_release_revision = scope.release_revision
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
  for update;
  if found then
    return query select 'exists'::text, null::jsonb;
    return;
  end if;

  created_at := pg_catalog.clock_timestamp();
  new_draft_id := pg_catalog.gen_random_uuid();
  begin
    insert into vortex_page.form_drafts (
      draft_id, organization_id, organization_account_id, identity_id,
      application_root_id, installation_release_revision,
      form_id, flow_id, node_id, subject_record_id,
      revision, field_values, validation_state,
      created_at, updated_at, expires_at, correlation_id
    ) values (
      new_draft_id, scope.organization_id, scope.organization_account_id, scope.identity_id,
      scope.application_root_id, scope.release_revision,
      p_form_id, p_flow_id, p_node_id, p_subject_record_id,
      1, p_field_values, p_validation_state,
      created_at, created_at,
      vortex_page.private_form_draft_expiry_internal(created_at), scope.correlation_id
    )
    returning * into stored;
  exception
    when unique_violation then
      return query select 'exists'::text, null::jsonb;
      return;
  end;

  return query select 'created'::text,
    vortex_page.private_form_draft_to_json_internal(stored, 'active');
end
$function$;


ALTER FUNCTION vortex_page.create_private_form_draft(p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid, p_field_values jsonb, p_validation_state jsonb) OWNER TO vortex_page_owner;

--
-- Name: FUNCTION create_private_form_draft(p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid, p_field_values jsonb, p_validation_state jsonb); Type: COMMENT; Schema: vortex_page; Owner: vortex_page_owner
--

COMMENT ON FUNCTION vortex_page.create_private_form_draft(p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid, p_field_values jsonb, p_validation_state jsonb) IS 'Creates revision 1 of a private form draft for the current person and exact active installation, or reports the scope is already held.';


--
-- Name: expire_private_form_drafts(integer); Type: FUNCTION; Schema: vortex_page; Owner: vortex_page_owner
--

create or replace function vortex_page.expire_private_form_drafts(p_limit integer default 500)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked jsonb;
begin
  if p_limit is null or p_limit not between 1 and 10000 then
    raise exception using errcode = '22023',
      message = 'Private form draft expiry command is invalid';
  end if;

  checked := vortex_access.validated_human_request_context();
  if not vortex_context.is_non_nil_uuid(checked ->> 'organizationId') then
    raise exception using errcode = '42501',
      message = 'Private form draft scope is unavailable';
  end if;

  return vortex_page.private_form_draft_purge_internal(
    (checked ->> 'organizationId')::uuid,
    p_limit
  );
end
$function$;


ALTER FUNCTION vortex_page.expire_private_form_drafts(p_limit integer) OWNER TO vortex_page_owner;

--
-- Name: FUNCTION expire_private_form_drafts(p_limit integer); Type: COMMENT; Schema: vortex_page; Owner: vortex_page_owner
--

COMMENT ON FUNCTION vortex_page.expire_private_form_drafts(p_limit integer) IS 'Deletes a bounded batch of the current organisation''s private form drafts untouched for thirty days.';


--
-- Name: private_form_draft_context_internal(); Type: FUNCTION; Schema: vortex_page; Owner: vortex_page_owner
--

create or replace function vortex_page.private_form_draft_context_internal()
returns table (
  organization_id uuid,
  organization_account_id uuid,
  identity_id uuid,
  application_root_id uuid,
  release_revision bigint,
  correlation_id uuid
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked jsonb;
  installation jsonb;
  selected_application_root_id uuid;
begin
  checked := vortex_access.validated_human_request_context();
  if not (checked ?& array['organizationAccountId', 'identityId', 'applicationRootId'])
    or not vortex_context.is_non_nil_uuid(checked ->> 'applicationRootId')
    or not vortex_context.is_non_nil_uuid(checked ->> 'organizationAccountId')
    or not vortex_context.is_non_nil_uuid(checked ->> 'identityId') then
    raise exception using errcode = '42501',
      message = 'Private form draft scope is unavailable';
  end if;
  selected_application_root_id := (checked ->> 'applicationRootId')::uuid;

  installation := vortex_module.read_current_active_installation();
  if installation is null
    or pg_catalog.jsonb_typeof(installation) <> 'object'
    or (installation ->> 'organizationId')::uuid
      is distinct from (checked ->> 'organizationId')::uuid
    or (installation ->> 'applicationRootId')::uuid is distinct from selected_application_root_id
    or pg_catalog.jsonb_typeof(installation -> 'applicationReleaseRevision')
      is distinct from 'number'
    or not vortex_context.is_non_nil_uuid(checked ->> 'correlationId') then
    raise exception using errcode = '42501',
      message = 'Private form draft scope is unavailable';
  end if;

  return query select
    (checked ->> 'organizationId')::uuid,
    (checked ->> 'organizationAccountId')::uuid,
    (checked ->> 'identityId')::uuid,
    selected_application_root_id,
    (installation ->> 'applicationReleaseRevision')::bigint,
    (checked ->> 'correlationId')::uuid;
end
$function$;


