--
-- Name: private_form_draft_key_is_valid(text); Type: FUNCTION; Schema: vortex_page; Owner: postgres
--

create or replace function vortex_page.private_form_draft_key_is_valid(p_key text)
returns boolean
language sql
immutable
security invoker
set search_path = ''
as $function$
  select p_key is not null
    and (
      p_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or (
        pg_catalog.length(p_key) <= 40
        and p_key ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'
      )
    )
$function$;


ALTER FUNCTION vortex_page.private_form_draft_key_is_valid(p_key text) OWNER TO postgres;

--
-- Name: FUNCTION private_form_draft_key_is_valid(p_key text); Type: COMMENT; Schema: vortex_page; Owner: postgres
--

COMMENT ON FUNCTION vortex_page.private_form_draft_key_is_valid(p_key text) IS 'Checks whether a private form draft field key uses an accepted key format.';


--
-- Name: private_form_draft_purge_internal(uuid, integer); Type: FUNCTION; Schema: vortex_page; Owner: postgres
--

create or replace function vortex_page.private_form_draft_purge_internal(
  p_organization_id uuid,
  p_limit integer
)
returns integer
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  affected integer;
begin
  with expired as (
    select draft.draft_id
    from vortex_page.form_drafts as draft
    where draft.organization_id = p_organization_id
      and draft.expires_at <= pg_catalog.clock_timestamp()
    order by draft.expires_at
    limit p_limit
    for update skip locked
  )
  delete from vortex_page.form_drafts as draft
  using expired
  where draft.draft_id = expired.draft_id;

  get diagnostics affected = row_count;
  return affected;
end
$function$;


ALTER FUNCTION vortex_page.private_form_draft_purge_internal(p_organization_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION private_form_draft_purge_internal(p_organization_id uuid, p_limit integer); Type: COMMENT; Schema: vortex_page; Owner: postgres
--

COMMENT ON FUNCTION vortex_page.private_form_draft_purge_internal(p_organization_id uuid, p_limit integer) IS 'Deletes a bounded batch of expired private form drafts for one organization.';


--
-- Name: private_form_draft_validation_is_valid(jsonb); Type: FUNCTION; Schema: vortex_page; Owner: postgres
--

create or replace function vortex_page.private_form_draft_validation_is_valid(p_validation jsonb)
returns boolean
language sql
immutable
security invoker
set search_path = ''
as $function$
  select case
    when p_validation is null or pg_catalog.jsonb_typeof(p_validation) <> 'object' then false
    else (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(p_validation)) <= 500
      and not exists (
        select 1
        from pg_catalog.jsonb_each(p_validation) as supplied(key, value)
        where not vortex_page.private_form_draft_key_is_valid(supplied.key)
          or case
            when pg_catalog.jsonb_typeof(supplied.value) <> 'object' then true
            else supplied.value ->> 'state' is null
              or supplied.value ->> 'state' not in ('valid', 'invalid', 'incomplete')
              or (supplied.value - array['state', 'reasonCode']) <> '{}'::jsonb
              or (
                supplied.value ? 'reasonCode'
                and case
                  when pg_catalog.jsonb_typeof(supplied.value -> 'reasonCode') <> 'string'
                    then true
                  else pg_catalog.length(supplied.value ->> 'reasonCode') > 120
                    or supplied.value ->> 'reasonCode' !~ '^[a-z][a-z0-9_]*$'
                end
              )
          end
      )
  end
$function$;


ALTER FUNCTION vortex_page.private_form_draft_validation_is_valid(p_validation jsonb) OWNER TO postgres;

--
-- Name: FUNCTION private_form_draft_validation_is_valid(p_validation jsonb); Type: COMMENT; Schema: vortex_page; Owner: postgres
--

COMMENT ON FUNCTION vortex_page.private_form_draft_validation_is_valid(p_validation jsonb) IS 'Validates bounded private form draft validation state.';


--
-- Name: private_form_draft_values_are_valid(jsonb); Type: FUNCTION; Schema: vortex_page; Owner: postgres
--

create or replace function vortex_page.private_form_draft_values_are_valid(p_values jsonb)
returns boolean
language sql
immutable
security invoker
set search_path = ''
as $function$
  select case
    when p_values is null or pg_catalog.jsonb_typeof(p_values) <> 'object' then false
    else pg_catalog.octet_length(p_values::text) <= 524288
      and (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(p_values)) <= 500
      and not exists (
        select 1
        from pg_catalog.jsonb_object_keys(p_values) as supplied(key)
        where not vortex_page.private_form_draft_key_is_valid(supplied.key)
      )
  end
$function$;


ALTER FUNCTION vortex_page.private_form_draft_values_are_valid(p_values jsonb) OWNER TO postgres;

--
-- Name: FUNCTION private_form_draft_values_are_valid(p_values jsonb); Type: COMMENT; Schema: vortex_page; Owner: postgres
--

COMMENT ON FUNCTION vortex_page.private_form_draft_values_are_valid(p_values jsonb) IS 'Validates bounded private form draft field values.';


--
-- Name: form_drafts; Type: TABLE; Schema: vortex_page; Owner: postgres
--

CREATE TABLE vortex_page.form_drafts (
    draft_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    organization_account_id uuid NOT NULL,
    identity_id uuid NOT NULL,
    application_root_id uuid NOT NULL,
    installation_release_revision bigint NOT NULL,
    form_id uuid NOT NULL,
    flow_id uuid,
    node_id uuid,
    subject_record_id uuid,
    revision bigint NOT NULL,
    field_values jsonb NOT NULL,
    validation_state jsonb NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    correlation_id uuid NOT NULL,
    CONSTRAINT form_drafts_ids_non_nil CHECK ((vortex_context.is_non_nil_uuid((draft_id)::text) AND vortex_context.is_non_nil_uuid((organization_id)::text) AND vortex_context.is_non_nil_uuid((organization_account_id)::text) AND vortex_context.is_non_nil_uuid((identity_id)::text) AND vortex_context.is_non_nil_uuid((application_root_id)::text) AND vortex_context.is_non_nil_uuid((form_id)::text) AND ((flow_id IS NULL) OR vortex_context.is_non_nil_uuid((flow_id)::text)) AND ((node_id IS NULL) OR vortex_context.is_non_nil_uuid((node_id)::text)) AND ((subject_record_id IS NULL) OR vortex_context.is_non_nil_uuid((subject_record_id)::text)) AND vortex_context.is_non_nil_uuid((correlation_id)::text))),
    CONSTRAINT form_drafts_revisions_valid CHECK ((((installation_release_revision >= 1) AND (installation_release_revision <= '9007199254740991'::bigint)) AND ((revision >= 1) AND (revision <= '9007199254740991'::bigint)))),
    CONSTRAINT form_drafts_times_valid CHECK (((created_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (updated_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (updated_at >= created_at) AND (expires_at > updated_at))),
    CONSTRAINT form_drafts_validation_valid CHECK (vortex_page.private_form_draft_validation_is_valid(validation_state)),
    CONSTRAINT form_drafts_values_valid CHECK (vortex_page.private_form_draft_values_are_valid(field_values))
);

ALTER TABLE ONLY vortex_page.form_drafts FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_page.form_drafts OWNER TO postgres;

--
-- Name: TABLE form_drafts; Type: COMMENT; Schema: vortex_page; Owner: postgres
--

COMMENT ON TABLE vortex_page.form_drafts IS 'Private revisioned form drafts. Rows are keyed by person, organisation, exact installed Application release and exact form/flow/node, exist only while the draft is live, are written only by the protected Page operations, and are never business records.';


--
-- Name: private_form_draft_to_json_internal(vortex_page.form_drafts, text); Type: FUNCTION; Schema: vortex_page; Owner: postgres
--

create or replace function vortex_page.private_form_draft_to_json_internal(
  d vortex_page.form_drafts,
  p_state text
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $function$
  select pg_catalog.jsonb_build_object(
    'draftId', d.draft_id,
    'organizationId', d.organization_id,
    'organizationAccountId', d.organization_account_id,
    'identityId', d.identity_id,
    'applicationRootId', d.application_root_id,
    'installationReleaseRevision', d.installation_release_revision,
    'formId', d.form_id,
    'revision', d.revision,
    'values', d.field_values,
    'validation', d.validation_state,
    'state', p_state,
    'createdAt', pg_catalog.to_char(d.created_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'updatedAt', pg_catalog.to_char(d.updated_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'expiresAt', pg_catalog.to_char(d.expires_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  )
  || case when d.flow_id is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('flowId', d.flow_id) end
  || case when d.node_id is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('nodeId', d.node_id) end
  || case when d.subject_record_id is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('subjectRecordId', d.subject_record_id) end
$function$;


ALTER FUNCTION vortex_page.private_form_draft_to_json_internal(d vortex_page.form_drafts, p_state text) OWNER TO postgres;

--
-- Name: FUNCTION private_form_draft_to_json_internal(d vortex_page.form_drafts, p_state text); Type: COMMENT; Schema: vortex_page; Owner: postgres
--

COMMENT ON FUNCTION vortex_page.private_form_draft_to_json_internal(d vortex_page.form_drafts, p_state text) IS 'Converts one private form draft row to its canonical JSON result.';


--
-- Name: read_private_form_draft(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_page; Owner: vortex_page_owner
--

create or replace function vortex_page.read_private_form_draft(
  p_form_id uuid,
  p_flow_id uuid,
  p_node_id uuid,
  p_subject_record_id uuid
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  stored vortex_page.form_drafts%rowtype;
begin
  if p_form_id is null or not vortex_context.is_non_nil_uuid(p_form_id::text)
    or (p_flow_id is not null and not vortex_context.is_non_nil_uuid(p_flow_id::text))
    or (p_node_id is not null and not vortex_context.is_non_nil_uuid(p_node_id::text))
    or (p_subject_record_id is not null
      and not vortex_context.is_non_nil_uuid(p_subject_record_id::text)) then
    raise exception using errcode = '22023',
      message = 'Private form draft read command is invalid';
  end if;

  select context.* into strict scope
  from vortex_page.private_form_draft_context_internal() as context;

  -- Only the draft bound to the exact current installed release is resumable.
  select draft.* into stored
  from vortex_page.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
    and draft.installation_release_revision = scope.release_revision
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
    and draft.expires_at > pg_catalog.clock_timestamp();
  if found then
    return query select 'available'::text,
      vortex_page.private_form_draft_to_json_internal(stored, 'active');
    return;
  end if;

  -- A live draft for this scope bound to a replaced installation is stale, not
  -- silently combined with the changed form.
  perform 1
  from vortex_page.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
    and draft.installation_release_revision <> scope.release_revision
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
    and draft.expires_at > pg_catalog.clock_timestamp();
  if found then
    return query select 'stale_installation'::text, null::jsonb;
    return;
  end if;

  return query select 'unavailable'::text, null::jsonb;
end
$function$;


ALTER FUNCTION vortex_page.read_private_form_draft(p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid) OWNER TO vortex_page_owner;

--
-- Name: FUNCTION read_private_form_draft(p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid); Type: COMMENT; Schema: vortex_page; Owner: vortex_page_owner
--

COMMENT ON FUNCTION vortex_page.read_private_form_draft(p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid) IS 'Reads one exact live private form draft of the current person, rechecking the exact active installation before returning any value.';


--
-- Name: update_private_form_draft(uuid, bigint, uuid, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_page; Owner: vortex_page_owner
--

create or replace function vortex_page.update_private_form_draft(
  p_draft_id uuid,
  p_expected_revision bigint,
  p_form_id uuid,
  p_flow_id uuid,
  p_node_id uuid,
  p_subject_record_id uuid,
  p_field_values jsonb,
  p_validation_state jsonb
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  stored vortex_page.form_drafts%rowtype;
  touched_at timestamptz;
begin
  if p_draft_id is null or not vortex_context.is_non_nil_uuid(p_draft_id::text)
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991
    or p_form_id is null or not vortex_context.is_non_nil_uuid(p_form_id::text)
    or (p_flow_id is not null and not vortex_context.is_non_nil_uuid(p_flow_id::text))
    or (p_node_id is not null and not vortex_context.is_non_nil_uuid(p_node_id::text))
    or (p_subject_record_id is not null
      and not vortex_context.is_non_nil_uuid(p_subject_record_id::text))
    or not vortex_page.private_form_draft_values_are_valid(p_field_values)
    or not vortex_page.private_form_draft_validation_is_valid(p_validation_state) then
    raise exception using errcode = '22023',
      message = 'Private form draft update command is invalid';
  end if;

  select context.* into strict scope
  from vortex_page.private_form_draft_context_internal() as context;

  -- Another person's draft is never locked and is indistinguishable from a
  -- missing one.
  select draft.* into stored
  from vortex_page.form_drafts as draft
  where draft.draft_id = p_draft_id
    and draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
  for update;
  if not found
    or stored.expires_at <= pg_catalog.clock_timestamp()
    or stored.form_id <> p_form_id
    or stored.flow_id is distinct from p_flow_id
    or stored.node_id is distinct from p_node_id
    or stored.subject_record_id is distinct from p_subject_record_id then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  if stored.installation_release_revision <> scope.release_revision then
    return query select 'stale_installation'::text, null::jsonb;
    return;
  end if;

  if stored.revision <> p_expected_revision then
    return query select 'stale_revision'::text, null::jsonb;
    return;
  end if;

  touched_at := pg_catalog.clock_timestamp();
  update vortex_page.form_drafts as draft
  set field_values = p_field_values,
      validation_state = p_validation_state,
      revision = draft.revision + 1,
      updated_at = touched_at,
      expires_at = vortex_page.private_form_draft_expiry_internal(touched_at)
  where draft.draft_id = p_draft_id
  returning * into stored;

  perform vortex_page.private_form_draft_purge_internal(scope.organization_id, 100);

  return query select 'updated'::text,
    vortex_page.private_form_draft_to_json_internal(stored, 'active');
end
$function$;


ALTER FUNCTION vortex_page.update_private_form_draft(p_draft_id uuid, p_expected_revision bigint, p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid, p_field_values jsonb, p_validation_state jsonb) OWNER TO vortex_page_owner;

