-- Name: FUNCTION update_private_form_draft(p_draft_id uuid, p_expected_revision bigint, p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid, p_field_values jsonb, p_validation_state jsonb); Type: COMMENT; Schema: vortex_page; Owner: vortex_page_owner
--

COMMENT ON FUNCTION vortex_page.update_private_form_draft(p_draft_id uuid, p_expected_revision bigint, p_form_id uuid, p_flow_id uuid, p_node_id uuid, p_subject_record_id uuid, p_field_values jsonb, p_validation_state jsonb) IS 'Compare-and-updates one exact owned live private form draft at its current revision, refusing a stale revision or replaced installation.';


--
-- Name: account_retains_owned_records_internal(uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_inventory
--

CREATE FUNCTION vortex_record.account_retains_owned_records_internal(p_organization_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  organization_id_value uuid;
  physical record;
  found_any boolean;
begin
  if p_organization_account_id is null
    or p_organization_account_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Account deletion inventory selector is invalid';
  end if;

  organization_id_value := vortex_context.organization_id();
  if organization_id_value is null then
    raise exception using errcode = '55000',
      message = 'Account deletion inventory completeness cannot be proved';
  end if;

  for physical in
    select relation.oid as relation_id, relation.relname, relation.relkind,
      relation.relrowsecurity
    from pg_catalog.pg_class as relation
    join pg_catalog.pg_namespace as namespace on namespace.oid = relation.relnamespace
    where namespace.nspname = 'record_data'
      and relation.relname ~ '^rt_[a-f0-9]{32}$'
    order by relation.relname
  loop
    if physical.relkind <> 'r'
      or (physical.relrowsecurity and not exists (
        select 1 from pg_catalog.pg_policy as policy
        where policy.polrelid = physical.relation_id
          and policy.polname = 'record_account_deletion_inventory'
      )) then
      raise exception using errcode = '55000',
        message = 'Account deletion inventory completeness cannot be proved';
    end if;

    execute pg_catalog.format(
      'select exists (
         select 1 from record_data.%I as stored
         where stored.organisation_id = $1
           and stored.owner_organisation_account_id = $2
       )',
      physical.relname
    ) into found_any using organization_id_value, p_organization_account_id;

    if found_any then
      return true;
    end if;
  end loop;

  return false;
end
$_$;


ALTER FUNCTION vortex_record.account_retains_owned_records_internal(p_organization_account_id uuid) OWNER TO vortex_record_inventory;

--
-- Name: FUNCTION account_retains_owned_records_internal(p_organization_account_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_inventory
--

COMMENT ON FUNCTION vortex_record.account_retains_owned_records_internal(p_organization_account_id uuid) IS 'Private all-scope account-deletion inventory over every physical Record table in the organisation; returns only whether any owned row remains.';


--
-- Name: acquire_relationship_edge_locks_internal(text[]); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.acquire_relationship_edge_locks_internal(p_identities text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  transaction_key text := pg_catalog.pg_current_xact_id()::text;
  stored_value text;
  high_water text;
  identity_value text;
begin
  if p_identities is null
    or pg_catalog.array_position(p_identities, null::text) is not null then
    raise exception using errcode = '22023',
      message = 'Relationship edge lock set is invalid';
  end if;
  stored_value := pg_catalog.current_setting(
    'vortex_record.relationship_edge_lock_high_water', true
  );
  if stored_value is not null
    and pg_catalog.split_part(stored_value, '|', 1) = transaction_key then
    high_water := pg_catalog.substr(
      stored_value, pg_catalog.length(transaction_key) + 2
    );
  end if;
  for identity_value in
    select distinct item.value collate "C"
    from pg_catalog.unnest(p_identities) as item(value)
    order by 1
  loop
    if high_water is null or identity_value collate "C" > high_water collate "C" then
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(identity_value, 0)
      );
      high_water := identity_value;
      perform pg_catalog.set_config(
        'vortex_record.relationship_edge_lock_high_water',
        transaction_key || '|' || high_water, true
      );
    elsif not pg_catalog.pg_try_advisory_xact_lock(
      pg_catalog.hashtextextended(identity_value, 0)
    ) then
      raise exception using errcode = '40001',
        message = 'Relationship edge lock order conflict';
    end if;
  end loop;
end
$$;


ALTER FUNCTION vortex_record.acquire_relationship_edge_locks_internal(p_identities text[]) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION acquire_relationship_edge_locks_internal(p_identities text[]); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.acquire_relationship_edge_locks_internal(p_identities text[]) IS 'Acquires relationship edge participant identities as transaction advisory locks in one ascending collate "C" order per transaction; an out-of-order identity that is held elsewhere is a bounded 40001 conflict, never a wait.';


--
-- Name: adopt_storage_conversion(uuid, bigint, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.adopt_storage_conversion(p_conversion_contract_id uuid, p_expected_plan_revision bigint, p_application_root_id uuid, p_module_root_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  authority jsonb;
  organisation_id_value uuid;
  scope_application_root_id uuid;
  conversion vortex_record.storage_conversion_catalogue%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  plan_row vortex_record.storage_conversion_plans%rowtype;
  target_mapping vortex_record.field_storage_mappings%rowtype;
  target_required boolean;
  lock_sql text;
  check_sql text;
  unfinished_count bigint;
  switched jsonb;
begin
  if p_conversion_contract_id is null
    or p_conversion_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_plan_revision is null
    or p_expected_plan_revision not between 1 and 9007199254740991
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Storage adoption command is invalid';
  end if;

  select entry.* into conversion
  from vortex_record.storage_conversion_catalogue as entry
  where entry.conversion_contract_id = p_conversion_contract_id;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Storage conversion plan is unavailable';
  end if;

  -- The installation is already detached by this transaction, so authority is
  -- proved without requiring an active installation.
  authority := vortex_record.authorize_storage_conversion_internal(
    conversion.source_storage_contract_id, null
  );
  organisation_id_value := (authority ->> 'organizationId')::uuid;
  scope_application_root_id := (authority ->> 'applicationRootId')::uuid;
  if scope_application_root_id is not null
    and scope_application_root_id <> p_application_root_id then
    raise exception using errcode = '42501',
      message = 'Storage adoption Application is outside the request context';
  end if;

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = conversion.source_storage_contract_id;
  if not found or catalogue_row.state <> 'active' then
    raise exception using errcode = '55000',
      message = 'Storage adoption contract is unavailable';
  end if;
  -- The caller names the converted Module so it can adopt at that Module's
  -- place in the canonical provisioning order; the catalogue decides it.
  if catalogue_row.module_root_id <> p_module_root_id then
    raise exception using errcode = '55000',
      message = 'Storage adoption Module is incompatible';
  end if;

  -- Binding identity first, then the storage lineages: the provisioner's order.
  perform vortex_record.lock_storage_adoption_internal(
    p_conversion_contract_id, organisation_id_value, p_application_root_id
  );

  select plan.* into plan_row
  from vortex_record.storage_conversion_plans as plan
  where plan.conversion_contract_id = p_conversion_contract_id
    and plan.organisation_id = organisation_id_value
    and plan.application_root_id is not distinct from scope_application_root_id
  for update;
  if not found then
    raise exception using errcode = '55000',
      message = 'Storage conversion plan is not allocated';
  end if;
  if plan_row.plan_revision <> p_expected_plan_revision then
    raise exception using errcode = '40001',
      message = 'Storage conversion plan changed';
  end if;
  if plan_row.state <> 'converted' then
    raise exception using errcode = '55000',
      message = 'Storage conversion plan is incomplete';
  end if;

  select mapping.* into target_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.target_field_id;
  if not found then
    raise exception using errcode = '55000',
      message = 'Storage adoption target mapping is not allocated';
  end if;
  target_required := coalesce(
    (conversion.target_field_definition ->> 'required')::boolean, false
  );

  -- Hold every in-scope record still while it is judged. A writer of this scope
  -- locks its row before it takes the binding lock this transaction already
  -- holds, so waiting for it here could deadlock: a row still locked by a writer
  -- in flight refuses the adoption as a retryable conflict instead. The next
  -- statement then reads the committed state.
  lock_sql := pg_catalog.format(
    'select 1 from record_data.%I as stored'
      || ' where stored.organisation_id = $1::uuid'
      || ' and stored.application_root_id is not distinct from $2::uuid'
      || ' order by stored.record_id'
      || ' for share of stored nowait',
    catalogue_row.physical_table_token
  );
  begin
    execute lock_sql using organisation_id_value, scope_application_root_id;
  exception
    when lock_not_available then
      raise exception using errcode = '40001',
        message = 'Storage adoption records are being changed';
  end;

  -- The exact candidate predicate of `convert_record_storage_batch`: a record
  -- never converted, or converted under an older concurrency revision, is
  -- unfinished. A required target field must also hold a value.
  check_sql := pg_catalog.format(
    'select pg_catalog.count(*)'
      || ' from record_data.%I as stored'
      || ' left join vortex_record.storage_conversion_progress as progress'
      || ' on progress.conversion_contract_id = $1::uuid'
      || ' and progress.organisation_id = stored.organisation_id'
      || ' and progress.application_root_id is not distinct from stored.application_root_id'
      || ' and progress.record_id = stored.record_id'
      || ' where stored.organisation_id = $2::uuid'
      || ' and stored.application_root_id is not distinct from $3::uuid'
      || ' and (progress.record_id is null'
      || ' or progress.source_concurrency_number <> stored.concurrency_number'
      || ' or ($4::boolean and stored.%I is null))',
    catalogue_row.physical_table_token, target_mapping.physical_column_token
  );
  execute check_sql into unfinished_count
    using p_conversion_contract_id, organisation_id_value,
      scope_application_root_id, target_required;
  if unfinished_count > 0 then
    raise exception using errcode = '55000',
      message = 'Storage conversion has records changed or missed since conversion';
  end if;

  switched := vortex_record.switch_storage_conversion_mappings_internal(
    p_conversion_contract_id, (authority ->> 'ownsModule')::boolean
  );

  return pg_catalog.jsonb_build_object(
    'conversionContractId', conversion.conversion_contract_id,
    'storageContractId', conversion.source_storage_contract_id,
    'moduleRootId', catalogue_row.module_root_id,
    'sourceFieldId', conversion.source_field_id,
    'targetFieldId', conversion.target_field_id,
    'organisationId', organisation_id_value,
    'applicationRootId', p_application_root_id,
    'sourceReleaseRevision', conversion.source_release_revision,
    'targetReleaseRevision', conversion.target_release_revision,
    'planRevision', plan_row.plan_revision,
    'dependentCount', (switched ->> 'dependentCount')::bigint,
    'changed', (switched ->> 'changed')::boolean
  );
exception
  when no_data_found or too_many_rows then
    raise exception using errcode = '55000',
      message = 'Storage adoption evidence is unavailable';
end
$_$;


ALTER FUNCTION vortex_record.adopt_storage_conversion(p_conversion_contract_id uuid, p_expected_plan_revision bigint, p_application_root_id uuid, p_module_root_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION adopt_storage_conversion(p_conversion_contract_id uuid, p_expected_plan_revision bigint, p_application_root_id uuid, p_module_root_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.adopt_storage_conversion(p_conversion_contract_id uuid, p_expected_plan_revision bigint, p_application_root_id uuid, p_module_root_id uuid) IS 'Atomic storage adoption for one detached installation: refuses stale or incomplete plans and any remaining installation of a release carrying the source field, then switches the target mapping to active and the source mapping to retired together; never drops a column.';


--
-- Name: allocate_preview_reference_number_internal(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.allocate_preview_reference_number_internal(
  p_preview_installation_id uuid,
  p_storage_contract_id uuid,
  p_field_id uuid,
  p_settings jsonb
)
returns text
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  preview_value jsonb;
  start_number numeric(78,0);
  allocated numeric(78,0);
  digit_width integer;
  prefix_value text;
  suffix_value text;
begin
  if not vortex_context.is_non_nil_uuid(p_preview_installation_id::text)
    or not vortex_context.is_non_nil_uuid(p_storage_contract_id::text)
    or not vortex_context.is_non_nil_uuid(p_field_id::text)
    or pg_catalog.jsonb_typeof(p_settings) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_settings -> 'digits') is distinct from 'number'
    or (p_settings ->> 'digits')::integer not between 1 and 20
    or (p_settings ? 'startingNumber' and (
      pg_catalog.jsonb_typeof(p_settings -> 'startingNumber') <> 'number'
      or (p_settings ->> 'startingNumber')::numeric < 1
      or pg_catalog.trunc((p_settings ->> 'startingNumber')::numeric)
        <> (p_settings ->> 'startingNumber')::numeric
    )) then
    raise exception using errcode = '22023', message = 'Preview reference-number settings are invalid';
  end if;

  preview_value := vortex_record.read_current_preview_installation_internal();
  if preview_value is null
    or preview_value ->> 'outcome' = 'refused'
    or (preview_value ->> 'previewInstallationId')::uuid
      is distinct from p_preview_installation_id
    or not exists (
      select 1
      from pg_catalog.jsonb_array_elements(preview_value -> 'storageIdentities')
        as binding(value)
      where (binding.value ->> 'previewStorageContractId')::uuid = p_storage_contract_id
    )
    or not exists (
      select 1
      from vortex_record.field_storage_mappings as mapping
      where mapping.storage_contract_id = p_storage_contract_id
        and mapping.field_id = p_field_id
        and mapping.state = 'active'
    ) then
    raise exception using errcode = '42501', message = 'Preview reference-number storage is unavailable';
  end if;

  digit_width := (p_settings ->> 'digits')::integer;
  start_number := coalesce((p_settings ->> 'startingNumber')::numeric, 1);
  prefix_value := coalesce(p_settings ->> 'prefix', '');
  suffix_value := coalesce(p_settings ->> 'suffix', '');

  insert into vortex_record.preview_reference_counters (
    preview_installation_id, storage_contract_id, field_id, next_number
  ) values (
    p_preview_installation_id, p_storage_contract_id, p_field_id, start_number + 1
  )
  on conflict (preview_installation_id, storage_contract_id, field_id)
    do update set next_number =
      vortex_record.preview_reference_counters.next_number + 1
  returning next_number - 1 into allocated;

  return prefix_value
    || pg_catalog.lpad(
      allocated::text,
      case when pg_catalog.length(allocated::text) > digit_width
        then pg_catalog.length(allocated::text) else digit_width end,
      '0'
    )
    || suffix_value;
end
$function$;


ALTER FUNCTION vortex_record.allocate_preview_reference_number_internal(p_preview_installation_id uuid, p_storage_contract_id uuid, p_field_id uuid, p_settings jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION allocate_preview_reference_number_internal(p_preview_installation_id uuid, p_storage_contract_id uuid, p_field_id uuid, p_settings jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.allocate_preview_reference_number_internal(p_preview_installation_id uuid, p_storage_contract_id uuid, p_field_id uuid, p_settings jsonb) IS 'Allocates a reference number from the exact preview installation''s private counter, after revalidating its owner, expiry and storage identity.';


--
-- Name: allocate_reference_number_internal(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.allocate_reference_number_internal(p_organization_id uuid, p_storage_contract_id uuid, p_field_id uuid, p_application_root_id uuid, p_settings jsonb) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  start_number numeric(78,0);
  allocated numeric(78,0);
  digit_width integer;
  prefix_value text;
  suffix_value text;
begin
  if pg_catalog.jsonb_typeof(p_settings) <> 'object'
    or pg_catalog.jsonb_typeof(p_settings -> 'digits') <> 'number'
    or (p_settings ->> 'digits')::integer not between 1 and 20
    or (p_settings ? 'startingNumber' and (
      pg_catalog.jsonb_typeof(p_settings -> 'startingNumber') <> 'number'
      or (p_settings ->> 'startingNumber')::numeric < 1
      or pg_catalog.trunc((p_settings ->> 'startingNumber')::numeric)
        <> (p_settings ->> 'startingNumber')::numeric
    )) then
    raise exception using errcode = '22023', message = 'Reference-number settings are invalid';
  end if;
  digit_width := (p_settings ->> 'digits')::integer;
  start_number := coalesce((p_settings ->> 'startingNumber')::numeric, 1);
  prefix_value := coalesce(p_settings ->> 'prefix', '');
  suffix_value := coalesce(p_settings ->> 'suffix', '');

  insert into vortex_record.record_reference_counters (
    organization_id, storage_contract_id, field_id, application_root_id, next_number
  ) values (
    p_organization_id, p_storage_contract_id, p_field_id, p_application_root_id,
    start_number + 1
  )
  on conflict (organization_id, storage_contract_id, field_id, application_root_id)
    do update set next_number = vortex_record.record_reference_counters.next_number + 1,
      changed_at = pg_catalog.statement_timestamp()
  returning next_number - 1 into allocated;

  return prefix_value
    || pg_catalog.lpad(
      allocated::text,
      case when pg_catalog.length(allocated::text) > digit_width
        then pg_catalog.length(allocated::text) else digit_width end,
      '0'
    )
    || suffix_value;
end
$$;


ALTER FUNCTION vortex_record.allocate_reference_number_internal(p_organization_id uuid, p_storage_contract_id uuid, p_field_id uuid, p_application_root_id uuid, p_settings jsonb) OWNER TO vortex_record_adapter;

--
-- Name: allocate_storage_conversion_plan(uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.allocate_storage_conversion_plan(p_conversion_contract_id uuid, p_expected_plan_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority jsonb;
  organisation_id_value uuid;
  scope_application_root_id uuid;
  conversion vortex_record.storage_conversion_catalogue%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  source_mapping vortex_record.field_storage_mappings%rowtype;
  target_mapping vortex_record.field_storage_mappings%rowtype;
  plan_row vortex_record.storage_conversion_plans%rowtype;
  mapping_lock record;
  target_column_token text;
  changed_value boolean := false;
begin
  if p_conversion_contract_id is null
    or p_conversion_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (
      p_expected_plan_revision is not null
      and p_expected_plan_revision not between 1 and 9007199254740991
    ) then
    raise exception using errcode = '22023',
      message = 'Storage conversion allocation command is invalid';
  end if;

  select entry.* into conversion
  from vortex_record.storage_conversion_catalogue as entry
  where entry.conversion_contract_id = p_conversion_contract_id;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Storage conversion plan is unavailable';
  end if;

  authority := vortex_record.authorize_storage_conversion_internal(
    conversion.source_storage_contract_id, conversion.source_release_revision
  );
  organisation_id_value := (authority ->> 'organizationId')::uuid;
  scope_application_root_id := (authority ->> 'applicationRootId')::uuid;

  -- The same storage-lineage lock the provisioner takes, so staging a mapping
  -- and column never interleaves with a provision or a running batch.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_record.storage:' || conversion.source_storage_contract_id::text, 0
    )
  );

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = conversion.source_storage_contract_id;
  if not found or catalogue_row.state <> 'active' then
    raise exception using errcode = '55000',
      message = 'Storage conversion contract is unavailable';
  end if;

  -- Lock both mappings in canonical field-id order, the same order the
  -- provisioner uses.
  for mapping_lock in
    select mapping.field_id
    from vortex_record.field_storage_mappings as mapping
    where mapping.storage_contract_id = conversion.source_storage_contract_id
      and mapping.field_id in (conversion.source_field_id, conversion.target_field_id)
    order by mapping.field_id
    for update
  loop
    null;
  end loop;

  select mapping.* into source_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.source_field_id;
  if not found or source_mapping.state <> 'active'
    or source_mapping.database_value_type <> conversion.source_database_value_type then
    raise exception using errcode = '55000',
      message = 'Storage conversion source mapping is incompatible';
  end if;

  target_column_token := 'f_' || pg_catalog.replace(
    pg_catalog.lower(conversion.target_field_id::text), '-', ''
  );

  select mapping.* into target_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.target_field_id;
  if found then
    if target_mapping.physical_column_token <> target_column_token
      or target_mapping.database_value_type <> conversion.target_database_value_type
      or target_mapping.state <> 'planned'
      or target_mapping.introduced_at_release_revision <> conversion.target_release_revision
      or vortex_record.field_storage_meaning(target_mapping.field_definition)
        is distinct from vortex_record.field_storage_meaning(
          conversion.target_field_definition
        ) then
      raise exception using errcode = '55000',
        message = 'Existing storage conversion target mapping is incompatible';
    end if;
  else
    -- Staging changes the Module's shared storage for every installation, so
    -- only the organisation that owns the Module may do it.
    if not (authority ->> 'ownsModule')::boolean then
      raise exception using errcode = '42501',
        message = 'Storage conversion staging requires the Module owner';
    end if;
    insert into vortex_record.field_storage_mappings (
      storage_contract_id, field_id, physical_column_token, database_value_type,
      field_definition, introduced_by_module_root_id, introduced_at_release_revision, state
    ) values (
      conversion.source_storage_contract_id, conversion.target_field_id,
      target_column_token, conversion.target_database_value_type,
      conversion.target_field_definition, catalogue_row.module_root_id,
      conversion.target_release_revision, 'planned'
    );
    changed_value := true;
  end if;

  -- Physical `add`. The column is nullable; no active reader or writer selects
  -- it because its mapping is `planned`.
  perform vortex_record.ensure_storage_conversion_column_internal(
    catalogue_row.physical_table_token, target_column_token,
    conversion.target_database_value_type
  );

  select plan.* into plan_row
  from vortex_record.storage_conversion_plans as plan
  where plan.conversion_contract_id = p_conversion_contract_id
    and plan.organisation_id = organisation_id_value
    and plan.application_root_id is not distinct from scope_application_root_id
  for update;

  if found then
    if p_expected_plan_revision is not null
      and plan_row.plan_revision <> p_expected_plan_revision then
      raise exception using errcode = '40001',
        message = 'Storage conversion plan changed';
    end if;
  else
    if p_expected_plan_revision is not null then
      raise exception using errcode = '40001',
        message = 'Storage conversion plan is unavailable';
    end if;
    insert into vortex_record.storage_conversion_plans (
      conversion_contract_id, organisation_id, application_root_id, state,
      plan_revision, converted_count, last_record_id
    ) values (
      p_conversion_contract_id, organisation_id_value, scope_application_root_id,
      'planned', 1, 0, null
    )
    returning * into plan_row;
    changed_value := true;
  end if;

  return pg_catalog.jsonb_build_object(
    'conversionContractId', conversion.conversion_contract_id,
    'storageContractId', conversion.source_storage_contract_id,
    'sourceFieldId', conversion.source_field_id,
    'targetFieldId', conversion.target_field_id,
    'conversionSemantic', conversion.conversion_semantic,
    'sourceDatabaseValueType', conversion.source_database_value_type,
    'targetDatabaseValueType', conversion.target_database_value_type,
    'organisationId', organisation_id_value,
    'applicationRootId', scope_application_root_id,
    'state', plan_row.state,
    'planRevision', plan_row.plan_revision,
    'convertedCount', plan_row.converted_count,
    'changed', changed_value
  );
exception
  when no_data_found or too_many_rows then
    raise exception using errcode = '55000',
      message = 'Storage conversion plan evidence is unavailable';
end
$$;


ALTER FUNCTION vortex_record.allocate_storage_conversion_plan(p_conversion_contract_id uuid, p_expected_plan_revision bigint) OWNER TO vortex_record_owner;

