-- Name: FUNCTION ensure_field_index_internal(p_storage_contract_id uuid, p_field_id uuid, p_purpose text, p_storage_scope text, p_table_token text, p_scope_index_columns text, p_column_token text); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.ensure_field_index_internal(p_storage_contract_id uuid, p_field_id uuid, p_purpose text, p_storage_scope text, p_table_token text, p_scope_index_columns text, p_column_token text) IS 'Private provisioner helper: creates one exact field index and records its desired definition and observed readiness for one storage contract and field.';


--
-- Name: ensure_offboarding_owner_index_internal(text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.ensure_offboarding_owner_index_internal(p_physical_table_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  index_name text;
begin
  if p_physical_table_token is null
    or p_physical_table_token !~ '^rt_[a-f0-9]{32}$'
    or pg_catalog.to_regclass(pg_catalog.format('record_data.%I', p_physical_table_token)) is null then
    raise exception using errcode = '55000',
      message = 'Account-owner record storage is unavailable';
  end if;

  index_name := 'ix_' || p_physical_table_token || '_owner';
  execute pg_catalog.format(
    'create index if not exists %I on record_data.%I
       (organisation_id, owner_organisation_account_id)
       where owner_organisation_account_id is not null',
    index_name, p_physical_table_token
  );
end
$_$;


ALTER FUNCTION vortex_record.ensure_offboarding_owner_index_internal(p_physical_table_token text) OWNER TO vortex_record_owner;

