--
-- Name: filter_calculated_readable_field_ids(jsonb, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.filter_calculated_readable_field_ids(p_record_types jsonb, p_record_type_id uuid, p_readable_field_ids jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  record_type_value jsonb;
  field_value jsonb;
  field_id text;
  dependency_id text;
  readable_ids text[] := array[]::text[];
  allowed_ids text[] := array[]::text[];
  changed boolean := true;
  dependencies_allowed boolean;
begin
  if p_record_type_id is null
    or pg_catalog.jsonb_typeof(p_record_types) <> 'array'
    or pg_catalog.jsonb_typeof(p_readable_field_ids) <> 'array' then
    return '[]'::jsonb;
  end if;

  select item.value into record_type_value
  from pg_catalog.jsonb_array_elements(p_record_types) as item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') =
    pg_catalog.lower(p_record_type_id::text);
  if record_type_value is null
    or pg_catalog.jsonb_typeof(record_type_value -> 'fields') <> 'array' then
    return '[]'::jsonb;
  end if;

  select coalesce(pg_catalog.array_agg(pg_catalog.lower(item.value #>> '{}')),
    array[]::text[])
  into readable_ids
  from pg_catalog.jsonb_array_elements(p_readable_field_ids) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'string';

  -- Ordinary fields keep their already-authorized visibility. Calculated fields
  -- are added only after every declared source is already visible.
  for field_value in
    select item.value
    from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as item(value)
  loop
    field_id := pg_catalog.lower(field_value ->> 'fieldId');
    if field_value ->> 'type' <> 'calculation'
      and field_id = any (readable_ids) then
      allowed_ids := pg_catalog.array_append(allowed_ids, field_id);
    end if;
  end loop;

  while changed loop
    changed := false;
    for field_value in
      select item.value
      from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as item(value)
      where item.value ->> 'type' = 'calculation'
    loop
      field_id := pg_catalog.lower(field_value ->> 'fieldId');
      if field_id <> all (readable_ids) or field_id = any (allowed_ids) then
        continue;
      end if;
      dependencies_allowed := true;
      for dependency_id in
        select pg_catalog.lower(item.value #>> '{}')
        from pg_catalog.jsonb_array_elements(
          coalesce(field_value -> 'settings' -> 'dependencyFieldIds', '[]'::jsonb)
        ) as item(value)
      loop
        if dependency_id <> all (allowed_ids) then
          dependencies_allowed := false;
          exit;
        end if;
      end loop;
      if dependencies_allowed then
        allowed_ids := pg_catalog.array_append(allowed_ids, field_id);
        changed := true;
      end if;
    end loop;
  end loop;

  return coalesce((
    select pg_catalog.jsonb_agg(item.value order by item.ordinality)
    from pg_catalog.jsonb_array_elements(p_readable_field_ids)
      with ordinality as item(value, ordinality)
    where pg_catalog.jsonb_typeof(item.value) = 'string'
      and pg_catalog.lower(item.value #>> '{}') = any (allowed_ids)
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION vortex_record.filter_calculated_readable_field_ids(p_record_types jsonb, p_record_type_id uuid, p_readable_field_ids jsonb) OWNER TO vortex_record_adapter;

--
-- Name: finalize_account_deletion_fence(uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.finalize_account_deletion_fence(p_organization_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scope record;
  target record;
  changed record;
  resulting_revision bigint;
begin
  if p_organization_account_id is null
    or p_organization_account_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023', message = 'Account deletion command is invalid';
  end if;

  select authorized.* into strict scope
  from vortex_access.organization_accounts_offboarding_inventory_scope_internal() as authorized;

  -- After the lock wait, each later statement must read the rows committed
  -- by the writers it waited for; an older transaction snapshot cannot.
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '55000',
      message = 'Account deletion inventory completeness cannot be proved';
  end if;

  select locked.state, locked.revision into target
  from vortex_identity.lock_organization_account_for_deletion_internal(
    p_organization_account_id
  ) as locked;

  if not found then
    return pg_catalog.jsonb_build_object(
      'outcome', 'not_closing',
      'accessVersion', scope.access_version
    );
  end if;

  if target.state not in ('closing', 'deleted') then
    return pg_catalog.jsonb_build_object(
      'outcome', 'not_closing',
      'organizationAccountId', p_organization_account_id,
      'state', target.state,
      'revision', target.revision,
      'accessVersion', scope.access_version
    );
  end if;

  resulting_revision := target.revision;
  if target.state = 'closing' then
    if vortex_record.account_retains_owned_records_internal(p_organization_account_id) then
      return pg_catalog.jsonb_build_object(
        'outcome', 'records_remain',
        'accessVersion', scope.access_version
      );
    end if;

    select result.* into strict changed
    from vortex_identity.finalize_organization_account_deletion(
      p_organization_account_id, target.revision
    ) as result;

    if changed.organization_id <> scope.organization_id
      or changed.organization_account_id <> p_organization_account_id
      or changed.state <> 'deleted'
      or changed.revision <> target.revision + 1 then
      raise exception using errcode = '42501', message = 'Account deletion result is unavailable';
    end if;
    resulting_revision := changed.revision;
  end if;

  return pg_catalog.jsonb_build_object(
    'outcome', 'deleted',
    'organizationAccountId', p_organization_account_id,
    'state', 'deleted',
    'revision', resulting_revision,
    'accessVersion', scope.access_version
  );
end
$$;


ALTER FUNCTION vortex_record.finalize_account_deletion_fence(p_organization_account_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION finalize_account_deletion_fence(p_organization_account_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.finalize_account_deletion_fence(p_organization_account_id uuid) IS 'Protected final account-deletion fence: accounts.manage, exclusive account lock, private all-scope inventory, then closing-to-deleted only when nothing is owned.';


--
-- Name: index_build_statements_internal(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.index_build_statements_internal(p_storage_contract_id uuid, p_field_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  catalogue_row vortex_record.index_catalogue%rowtype;
  storage_row vortex_record.storage_catalogue%rowtype;
  mapping_row vortex_record.field_storage_mappings%rowtype;
  mapping_purpose text;
  scope_columns text;
  expected_fingerprint text;
  observed text;
  table_relation oid;
  physical_relation oid;
  physical_owner_relation oid;
  physical_valid boolean;
  physical_unique boolean;
  statements jsonb := '[]'::jsonb;
begin
  select catalogue.* into catalogue_row
  from vortex_record.index_catalogue as catalogue
  where catalogue.storage_contract_id = p_storage_contract_id
    and catalogue.field_id = p_field_id;
  if catalogue_row.index_contract_id is null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'index_unknown'
    );
  end if;

  select storage.* into storage_row
  from vortex_record.storage_catalogue as storage
  where storage.storage_contract_id = p_storage_contract_id;
  if storage_row.storage_contract_id is null
    or storage_row.state <> 'active'
    or storage_row.physical_schema_token <> 'record_data' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'storage_contract_unavailable'
    );
  end if;

  select stored.* into mapping_row
  from vortex_record.field_storage_mappings as stored
  where stored.storage_contract_id = p_storage_contract_id
    and stored.field_id = p_field_id;
  if mapping_row.storage_contract_id is null or mapping_row.state <> 'active' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'field_unavailable'
    );
  end if;

  scope_columns := vortex_record.index_scope_columns(storage_row.storage_scope);
  table_relation := pg_catalog.to_regclass(
    pg_catalog.format('record_data.%I', storage_row.physical_table_token)
  );
  if scope_columns is null or table_relation is null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'storage_contract_unavailable'
    );
  end if;

  -- The same purpose `read_index_readiness` derives, so the runner builds
  -- exactly the index activation will require.
  mapping_purpose := case
    when coalesce((mapping_row.field_definition ->> 'unique')::boolean, false)
      then 'uniqueness'
    when coalesce((mapping_row.field_definition ->> 'filterable')::boolean, false)
      or coalesce((mapping_row.field_definition ->> 'sortable')::boolean, false)
      then 'performance'
    else null
  end;
  expected_fingerprint := vortex_record.index_definition_fingerprint(
    catalogue_row.purpose, storage_row.physical_table_token, scope_columns,
    mapping_row.physical_column_token
  );
  -- The recorded identity must still describe exactly this physical index; a
  -- drifted row is never built against a definition it does not name.
  if mapping_purpose is distinct from catalogue_row.purpose
    or expected_fingerprint is distinct from catalogue_row.desired_definition_fingerprint
    or catalogue_row.physical_index_token is distinct from
      (case catalogue_row.purpose when 'uniqueness' then 'ux_' else 'ix_' end
        || pg_catalog.substr(mapping_row.physical_column_token, 3)) then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'index_definition_drifted'
    );
  end if;

  observed := vortex_record.observe_field_index_internal(
    catalogue_row.purpose, storage_row.physical_table_token, scope_columns,
    mapping_row.physical_column_token
  );
  if observed = 'present' then
    return pg_catalog.jsonb_build_object('outcome', 'settled');
  end if;

  -- A concurrent index build or cleanup holds SHARE UPDATE EXCLUSIVE on the
  -- table for its whole duration, including one orphaned by a worker that
  -- died or whose lease expired mid-build. While any other session holds or
  -- awaits that lock the row is left alone, so a cleanup can never drop an
  -- index another session is about to complete. Autovacuum takes the same
  -- lock; the row is simply offered again by a later run.
  if exists (
    select 1
    from pg_catalog.pg_locks as held
    where held.locktype = 'relation'
      and held.database = (
        select database_value.oid
        from pg_catalog.pg_database as database_value
        where database_value.datname = pg_catalog.current_database()
      )
      and held.relation = table_relation
      and held.mode = 'ShareUpdateExclusiveLock'
      and held.pid <> pg_catalog.pg_backend_pid()
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'busy');
  end if;

  physical_relation := pg_catalog.to_regclass(
    pg_catalog.format('record_data.%I', catalogue_row.physical_index_token)
  );
  if physical_relation is not null then
    select index_value.indrelid, index_value.indisvalid, index_value.indisunique
      into physical_owner_relation, physical_valid, physical_unique
    from pg_catalog.pg_index as index_value
    where index_value.indexrelid = physical_relation;
    -- The name is held by something other than an index of this table (the
    -- index namespace is shared across every record table). It is never
    -- dropped from here.
    if not found or physical_owner_relation is distinct from table_relation then
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'index_name_conflict'
      );
    end if;
    -- A valid unique index is still enforcing whatever uniqueness it provides,
    -- whatever its purpose or definition. Dropping it would remove that
    -- enforcement, so the row is refused rather than replaced; only an index
    -- that enforces nothing (invalid, or valid but not unique) is recreated.
    if physical_valid and physical_unique then
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'uniqueness_enforcement_present'
      );
    end if;
    statements := statements || pg_catalog.jsonb_build_array(
      pg_catalog.format(
        'drop index concurrently if exists record_data.%I',
        catalogue_row.physical_index_token
      )
    );
  end if;

  statements := statements || pg_catalog.jsonb_build_array(
    case catalogue_row.purpose
      when 'uniqueness' then pg_catalog.format(
        'create unique index concurrently %I on record_data.%I (%s, %I) where lifecycle_state in (''active'', ''soft_deleted'', ''removal_pending'')',
        catalogue_row.physical_index_token, storage_row.physical_table_token,
        scope_columns, mapping_row.physical_column_token
      )
      else pg_catalog.format(
        'create index concurrently %I on record_data.%I (%s, %I)',
        catalogue_row.physical_index_token, storage_row.physical_table_token,
        scope_columns, mapping_row.physical_column_token
      )
    end
  );

  return pg_catalog.jsonb_build_object(
    'outcome', 'claimed',
    'indexContractId', catalogue_row.index_contract_id,
    'storageContractId', catalogue_row.storage_contract_id,
    'fieldId', catalogue_row.field_id,
    'purpose', catalogue_row.purpose,
    'desiredDefinitionFingerprint', expected_fingerprint,
    'statements', statements
  );
end
$$;


ALTER FUNCTION vortex_record.index_build_statements_internal(p_storage_contract_id uuid, p_field_id uuid) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION index_build_statements_internal(p_storage_contract_id uuid, p_field_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.index_build_statements_internal(p_storage_contract_id uuid, p_field_id uuid) IS 'Private derivation of the ordered drop/create statements one catalogue row needs; never granted above vortex_record_owner.';


--
-- Name: index_contract_identity(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.index_contract_identity(p_storage_contract_id uuid, p_field_id uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (
    pg_catalog.substr(source.digest_hex, 1, 12)
    || '8'
    || pg_catalog.substr(source.digest_hex, 14, 3)
    || pg_catalog.substr(
      '89ab',
      (pg_catalog.strpos(
        '0123456789abcdef', pg_catalog.substr(source.digest_hex, 17, 1)
      ) - 1) % 4 + 1,
      1
    )
    || pg_catalog.substr(source.digest_hex, 18, 15)
  )::uuid
  from (
    select pg_catalog.md5(
      pg_catalog.lower(p_storage_contract_id::text) || ':'
        || pg_catalog.lower(p_field_id::text)
    ) as digest_hex
  ) as source
$$;


ALTER FUNCTION vortex_record.index_contract_identity(p_storage_contract_id uuid, p_field_id uuid) OWNER TO vortex_record_owner;

--
-- Name: index_definition(text, text, text, text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.index_definition(p_purpose text, p_table_token text, p_scope_index_columns text, p_column_token text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'schemaToken', 'record_data',
    'tableToken', p_table_token,
    'columns', pg_catalog.string_to_array(p_scope_index_columns, ', ') || p_column_token,
    'unique', p_purpose = 'uniqueness',
    'predicate', case when p_purpose = 'uniqueness'
      then 'lifecycle_state in (active, soft_deleted, removal_pending)' else null end
  )
$$;


ALTER FUNCTION vortex_record.index_definition(p_purpose text, p_table_token text, p_scope_index_columns text, p_column_token text) OWNER TO vortex_record_owner;

--
-- Name: index_definition_fingerprint(text, text, text, text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.index_definition_fingerprint(p_purpose text, p_table_token text, p_scope_index_columns text, p_column_token text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'sha256:' || pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        vortex_record.index_definition(
          p_purpose, p_table_token, p_scope_index_columns, p_column_token
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
$$;


ALTER FUNCTION vortex_record.index_definition_fingerprint(p_purpose text, p_table_token text, p_scope_index_columns text, p_column_token text) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION index_definition_fingerprint(p_purpose text, p_table_token text, p_scope_index_columns text, p_column_token text); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.index_definition_fingerprint(p_purpose text, p_table_token text, p_scope_index_columns text, p_column_token text) IS 'Canonical sha256 fingerprint of one exact desired field-index definition, using the same convention as record storage content fingerprints.';


--
-- Name: index_scope_columns(text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.index_scope_columns(p_storage_scope text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_storage_scope
    when 'organization_shared' then 'organisation_id'
    when 'application_contained' then 'organisation_id, application_root_id'
    else null
  end
$$;


