-- Name: FUNCTION preview_scoped_command_id_internal(p_command_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.preview_scoped_command_id_internal(p_command_id uuid) IS 'Derives a deterministic receipt identity inside one validated preview installation so retries stay isolated from live and other preview record commands.';


--
-- Name: project_derived_readable_field_ids_internal(jsonb, uuid, uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.project_derived_readable_field_ids_internal(p_loaded jsonb, p_record_type_id uuid, p_record_id uuid, p_readable_field_ids jsonb, p_required_field_ids jsonb, p_seen_derived_field_keys jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  field_value jsonb;
  candidate_readable_field_ids jsonb := p_readable_field_ids;
  required_field_ids text[] := array[]::text[];
  total_field_id text;
  derived_field_key text;
  inputs_readable boolean;
begin
  if p_record_type_id is null or p_record_id is null
    or pg_catalog.jsonb_typeof(p_loaded -> 'facts' -> 'recordTypes') <> 'array'
    or pg_catalog.jsonb_typeof(p_readable_field_ids) <> 'array'
    or pg_catalog.jsonb_typeof(p_required_field_ids) <> 'array'
    or pg_catalog.jsonb_typeof(p_seen_derived_field_keys) <> 'array' then
    return null;
  end if;
  -- Only totals named by the source aggregate/filter fields, or by a declared
  -- calculation dependency of those fields, are traversed.  This avoids an
  -- unrelated total turning a finite self relationship into a false cycle.
  select coalesce(pg_catalog.array_agg(distinct needed.field_id), array[]::text[])
  into required_field_ids
  from (
    with recursive needed(field_id) as (
      select pg_catalog.lower(item.value)
      from pg_catalog.jsonb_array_elements_text(p_required_field_ids) as item(value)
      union
      select pg_catalog.lower(dependency.value)
      from needed
      join pg_catalog.jsonb_array_elements(p_loaded -> 'facts' -> 'recordTypes') as record_type(value)
        on pg_catalog.lower(record_type.value ->> 'recordTypeId') = pg_catalog.lower(p_record_type_id::text)
      cross join lateral pg_catalog.jsonb_array_elements(record_type.value -> 'fields') as field(value)
      cross join lateral pg_catalog.jsonb_array_elements_text(
        coalesce(field.value -> 'settings' -> 'dependencyFieldIds', '[]'::jsonb)
      ) as dependency(value)
      where field.value ->> 'type' = 'calculation'
        and pg_catalog.lower(field.value ->> 'fieldId') = needed.field_id
    ) select field_id from needed
  ) as needed;
  for field_value in
    select field.value
    from pg_catalog.jsonb_array_elements(p_loaded -> 'facts' -> 'recordTypes') as record_type(value)
    cross join lateral pg_catalog.jsonb_array_elements(record_type.value -> 'fields') as field(value)
    where pg_catalog.lower(record_type.value ->> 'recordTypeId') = pg_catalog.lower(p_record_type_id::text)
      and field.value ->> 'type' = 'total'
  loop
    total_field_id := pg_catalog.lower(field_value ->> 'fieldId');
    if total_field_id <> all(required_field_ids)
      or not exists (
        select 1 from pg_catalog.jsonb_array_elements_text(p_readable_field_ids) as item(value)
        where pg_catalog.lower(item.value) = total_field_id
      ) then
      continue;
    end if;
    derived_field_key := pg_catalog.lower(p_record_type_id::text) || ':'
      || pg_catalog.lower(p_record_id::text) || ':' || total_field_id;
    inputs_readable := not exists (
      select 1 from pg_catalog.jsonb_array_elements_text(p_seen_derived_field_keys) as key(value)
      where key.value = derived_field_key
    ) and vortex_record.total_inputs_readable_internal(
      p_loaded, p_record_type_id, p_record_id, field_value,
      p_seen_derived_field_keys || pg_catalog.jsonb_build_array(derived_field_key)
    );
    if not inputs_readable then
      candidate_readable_field_ids := coalesce((
        select pg_catalog.jsonb_agg(item.value order by item.ordinality)
        from pg_catalog.jsonb_array_elements(candidate_readable_field_ids)
          with ordinality as item(value, ordinality)
        where pg_catalog.lower(item.value #>> '{}') <> total_field_id
      ), '[]'::jsonb);
    end if;
  end loop;
  -- Existing calculation disclosure is the sole fixed-point evaluator.  A
  -- failed total is removed before it becomes one of that evaluator's seeds.
  return vortex_record.filter_calculated_readable_field_ids(
    p_loaded -> 'facts' -> 'recordTypes', p_record_type_id,
    candidate_readable_field_ids
  );
end
$$;


ALTER FUNCTION vortex_record.project_derived_readable_field_ids_internal(p_loaded jsonb, p_record_type_id uuid, p_record_id uuid, p_readable_field_ids jsonb, p_required_field_ids jsonb, p_seen_derived_field_keys jsonb) OWNER TO vortex_record_adapter;

--
-- Name: project_named_action_record_internal(text, uuid, bigint, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.project_named_action_record_internal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid, p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  loaded jsonb;
  decision jsonb;
  bounds jsonb;
  values_value jsonb := '{}'::jsonb;
  field_id text;
begin
  loaded := vortex_record.load_named_action_facts_internal(
    p_action_owner_kind, p_action_owner_id, p_action_release_revision,
    p_action_id, p_record_type_id, p_record_id, null
  );
  if loaded ->> 'outcome' <> 'loaded' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  decision := vortex_access.evaluate_organization_record_access_internal(
    loaded -> 'declaration', p_record_id, loaded -> 'facts'
  );
  if decision ->> 'outcome' <> 'allowed' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  bounds := vortex_access.resolve_record_field_bounds_internal(decision);
  bounds := bounds || pg_catalog.jsonb_build_object(
    'readableFieldIds', vortex_record.filter_calculated_readable_field_ids(
      loaded -> 'facts' -> 'recordTypes', p_record_type_id,
      bounds -> 'readableFieldIds'
    )
  );
  for field_id in
    select item.value #>> '{}'
    from pg_catalog.jsonb_array_elements(bounds -> 'readableFieldIds') item(value)
  loop
    if loaded -> 'columns' ? field_id and loaded -> 'fieldValues' ? field_id then
      values_value := values_value || pg_catalog.jsonb_build_object(
        field_id, loaded -> 'fieldValues' -> field_id
      );
    end if;
  end loop;
  return pg_catalog.jsonb_build_object(
    'outcome', 'completed', 'recordId', p_record_id,
    'concurrencyNumber', loaded -> 'concurrencyNumber',
    'values', values_value,
    'correlationId', loaded -> 'context' -> 'correlationId',
    'backgroundDelivery', 'pending', 'replayed', true
  );
exception
  when no_data_found or too_many_rows or insufficient_privilege
    or object_not_in_prerequisite_state or check_violation then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
end
$$;


ALTER FUNCTION vortex_record.project_named_action_record_internal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid, p_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: provision_account_deletion_fence_internal(); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.provision_account_deletion_fence_internal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.physical_schema_token = 'record_data' then
    perform vortex_record.ensure_account_deletion_fence_internal(new.physical_table_token);
  end if;
  return new;
end
$$;


ALTER FUNCTION vortex_record.provision_account_deletion_fence_internal() OWNER TO vortex_record_owner;

--
-- Name: provision_exact_module_contributions(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.provision_exact_module_contributions(
  p_module_root_id uuid,
  p_module_release_revision bigint,
  p_contributions jsonb
)
returns table (
  module_root_id uuid,
  release_revision bigint,
  contribution_ids uuid[],
  changed boolean
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  release_row vortex_definition.releases%rowtype;
  contribution jsonb;
  contribution_id uuid;
  contribution_kind text;
  contributor_root_id uuid;
  target_module_root_id uuid;
  target_module_version text;
  target_extension_point_id uuid;
  target_record_type_id uuid;
  source_record_type_id uuid;
  field_id_value uuid;
  source_field jsonb;
  storage_id uuid;
  storage_ids uuid[] := array[]::uuid[];
  target_release vortex_definition.releases%rowtype;
  target_content jsonb;
  target_record_type jsonb;
  target_point jsonb;
  stored_catalogue vortex_record.storage_catalogue%rowtype;
  stored_field vortex_record.field_storage_mappings%rowtype;
  table_token text;
  column_token text;
  storage_scope_value text;
  scope_index_columns text;
  database_type text;
  sql_type text;
  is_projection boolean;
  protected_view_key text;
  reader_schema_value text;
  reader_function_value text;
  view_oid oid;
  reader_function_oid oid;
  contribution_ids uuid[] := array[]::uuid[];
  any_change boolean := false;
begin
  if not vortex_context.is_non_nil_uuid(p_module_root_id::text)
    or p_module_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_contributions) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_contributions) < 1
    or pg_catalog.jsonb_array_length(p_contributions) > 100 then
    raise exception using errcode = '22023',
      message = 'Module contribution storage command is invalid';
  end if;

  select release.* into strict release_row
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_module_root_id
    and release.release_revision = p_module_release_revision
    and root.kind = 'module';
  if release_row.validation_contract_version
      <> all (vortex_definition.accepted_contract_version('module'))
    or release_row.source_contract_version
      is distinct from release_row.validation_contract_version
    or release_row.compilation_output #>> '{kind}' is distinct from 'module'
    or release_row.compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from p_module_root_id::text
    or release_row.compilation_output #>> '{validationContractVersion}'
      is distinct from release_row.validation_contract_version then
    raise exception using errcode = '23514',
      message = 'Exact contributor Module release is incompatible';
  end if;

  -- Resolve every target record table first, then take its storage lineage lock
  -- in canonical storage-identity order, so a concurrent provisioner and this
  -- helper acquire the same locks in the same order.
  for contribution in
    select item.value
    from pg_catalog.jsonb_array_elements(p_contributions) as item(value)
    order by pg_catalog.lower(item.value ->> 'targetModuleRootId'),
      pg_catalog.lower(item.value ->> 'targetRecordTypeId'),
      pg_catalog.lower(item.value ->> 'contributionId')
  loop
    if pg_catalog.jsonb_typeof(contribution) is distinct from 'object'
      or pg_catalog.jsonb_typeof(contribution -> 'contributorModuleRootId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(contribution -> 'targetModuleRootId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(contribution -> 'targetRecordTypeId') is distinct from 'string' then
      raise exception using errcode = '22023', message = 'Module contribution identity is invalid';
    end if;
    begin
      contributor_root_id := (contribution ->> 'contributorModuleRootId')::uuid;
      target_module_root_id := (contribution ->> 'targetModuleRootId')::uuid;
      target_record_type_id := (contribution ->> 'targetRecordTypeId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '22023', message = 'Module contribution identity is invalid';
    end;
    if not vortex_context.is_non_nil_uuid(contributor_root_id::text)
      or not vortex_context.is_non_nil_uuid(target_module_root_id::text)
      or not vortex_context.is_non_nil_uuid(target_record_type_id::text)
      or contributor_root_id <> p_module_root_id
      or target_module_root_id = p_module_root_id then
      raise exception using errcode = '22023', message = 'Module contribution binding is invalid';
    end if;
    select catalogue.storage_contract_id into storage_id
    from vortex_record.storage_catalogue as catalogue
    where catalogue.module_root_id = target_module_root_id
      and catalogue.record_type_id = target_record_type_id
      and catalogue.state = 'active';
    if storage_id is null then
      raise exception using errcode = '55000',
        message = 'Target record storage is unavailable';
    end if;
    storage_ids := storage_ids || storage_id;
  end loop;

  for storage_id in
    select distinct item.value
    from pg_catalog.unnest(storage_ids) as item(value)
    order by item.value
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('vortex_record.storage:' || storage_id::text, 0)
    );
  end loop;

  -- Preflight every projection field in the complete contribution array before
  -- the first generated-table or companion-storage DDL. A later unsupported
  -- projection field therefore cannot follow an earlier physical change.
  for contribution in
    select item.value
    from pg_catalog.jsonb_array_elements(p_contributions) as item(value)
    order by pg_catalog.lower(item.value ->> 'targetModuleRootId'),
      pg_catalog.lower(item.value ->> 'targetRecordTypeId'),
      pg_catalog.lower(item.value ->> 'contributionId')
  loop
    if contribution ->> 'kind' is distinct from 'field' then
      continue;
    end if;
    begin
      target_module_root_id := (contribution ->> 'targetModuleRootId')::uuid;
      target_extension_point_id := (contribution ->> 'targetExtensionPointId')::uuid;
      target_record_type_id := (contribution ->> 'targetRecordTypeId')::uuid;
      source_record_type_id := (contribution ->> 'recordTypeId')::uuid;
      field_id_value := (contribution ->> 'fieldId')::uuid;
      contribution_id := (contribution ->> 'contributionId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '22023', message = 'Contributed field identity is invalid';
    end;
    target_module_version := contribution ->> 'targetModuleReleaseVersion';
    if target_module_version is null
      or not vortex_context.is_non_nil_uuid(target_module_root_id::text)
      or not vortex_context.is_non_nil_uuid(target_extension_point_id::text)
      or not vortex_context.is_non_nil_uuid(target_record_type_id::text)
      or not vortex_context.is_non_nil_uuid(source_record_type_id::text)
      or not vortex_context.is_non_nil_uuid(field_id_value::text)
      or not vortex_context.is_non_nil_uuid(contribution_id::text)
      or field_id_value <> contribution_id then
      raise exception using errcode = '22023', message = 'Contributed field identity is invalid';
    end if;

    select release.* into strict target_release
    from vortex_definition.releases as release
    join vortex_definition.roots as root on root.root_id = release.root_id
    where release.root_id = target_module_root_id
      and release.release_version = target_module_version
      and root.kind = 'module';
    if target_release.validation_contract_version
      <> all (vortex_definition.accepted_contract_version('module')) then
      raise exception using errcode = '23514',
        message = 'Exact target Module release is incompatible';
    end if;
    target_content := target_release.compilation_output #> '{canonical,content}';
    select item.value into target_record_type
    from pg_catalog.jsonb_array_elements(target_content -> 'recordTypes') as item(value)
    where pg_catalog.lower(item.value ->> 'recordTypeId')
      = pg_catalog.lower(target_record_type_id::text);
    if target_record_type is null then
      raise exception using errcode = '23514', message = 'Target record type is unavailable';
    end if;
    is_projection := target_record_type ? 'systemProjection';
    if not is_projection then
      continue;
    end if;

    -- Projection fields are optional and unindexed by contract. Use JSONB
    -- identity comparisons so a missing or non-boolean flag cannot pass.
    select item.value into target_point
    from pg_catalog.jsonb_array_elements(target_content -> 'extensionPoints') as item(value)
    where pg_catalog.lower(item.value ->> 'extensionPointId')
      = pg_catalog.lower(target_extension_point_id::text);
    if target_point is null
      or pg_catalog.lower(target_point ->> 'recordTypeId')
        <> pg_catalog.lower(target_record_type_id::text)
      or not coalesce((target_point -> 'accepts') ? 'field', false) then
      raise exception using errcode = '23514', message = 'Target extension point is unavailable';
    end if;
    if not exists (
      select 1
      from pg_catalog.jsonb_array_elements(
          coalesce(release_row.compilation_output #> '{canonical,content,contributions}', '[]'::jsonb)
        ) as item(value)
      where pg_catalog.lower(item.value ->> 'contributionId')
          = pg_catalog.lower(contribution ->> 'contributionId')
        and item.value ->> 'kind' = 'field'
        and pg_catalog.lower(item.value #>> '{targetModule,moduleRootId}')
          = pg_catalog.lower(target_module_root_id::text)
        and pg_catalog.lower(item.value ->> 'targetExtensionPointId')
          = pg_catalog.lower(target_extension_point_id::text)
        and pg_catalog.lower(item.value ->> 'recordTypeId')
          = pg_catalog.lower(source_record_type_id::text)
    ) then
      raise exception using errcode = '23514',
        message = 'Module contribution declaration is unavailable';
    end if;
    source_field := null;
    select item.value into source_field
    from pg_catalog.jsonb_array_elements(
        release_row.compilation_output #> '{canonical,content,recordTypes}'
      ) as record_item(value)
    cross join lateral pg_catalog.jsonb_array_elements(
      record_item.value -> 'fields'
    ) as item(value)
    where pg_catalog.lower(record_item.value ->> 'recordTypeId')
        = pg_catalog.lower(source_record_type_id::text)
      and pg_catalog.lower(item.value ->> 'fieldId')
        = pg_catalog.lower(field_id_value::text);
    if source_field is null then
      raise exception using errcode = '23514',
        message = 'Contributed field definition is unavailable';
    end if;
    if source_field -> 'required' is distinct from 'false'::jsonb
      or source_field -> 'unique' is distinct from 'false'::jsonb
      or source_field -> 'filterable' is distinct from 'false'::jsonb
      or source_field -> 'sortable' is distinct from 'false'::jsonb then
      raise exception using errcode = '23514',
        message = 'A system projection contribution must be optional and unindexed';
    end if;
    database_type := vortex_record.database_value_type(source_field);
    sql_type := vortex_record.sql_value_type(database_type);
    if database_type is null or sql_type is null then
      raise exception using errcode = '23514',
        message = 'Contributed field type is unsupported';
    end if;
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(target_record_type -> 'fields') as item(value)
      where pg_catalog.lower(item.value ->> 'fieldId')
        = pg_catalog.lower(field_id_value::text)
    ) or exists (
      select 1
      from pg_catalog.jsonb_array_elements(target_content -> 'actions') as item(value)
      where pg_catalog.lower(item.value ->> 'actionId')
        = pg_catalog.lower(field_id_value::text)
    ) then
      raise exception using errcode = '55000',
        message = 'Contributed field collides with target storage';
    end if;

    begin
      storage_id := (target_record_type ->> 'storageContractId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '55000',
        message = 'Target record storage lineage is incompatible';
    end;
    protected_view_key := target_record_type #>> '{systemProjection,protectedView}';
    select catalogue.* into strict stored_catalogue
    from vortex_record.storage_catalogue as catalogue
    where catalogue.module_root_id = target_module_root_id
      and catalogue.record_type_id = target_record_type_id
      and catalogue.state = 'active';
    if not vortex_context.is_non_nil_uuid(storage_id::text)
      or not (storage_id = any (storage_ids))
      or storage_id <> stored_catalogue.storage_contract_id
      or not exists (
        select 1
        from vortex_record.release_provisions as provision
        where provision.module_root_id = target_release.root_id
          and provision.release_revision = target_release.release_revision
          and storage_id = any (provision.storage_contract_ids)
      )
      or target_record_type ->> 'storageScope' is distinct from 'organization_shared'
      or stored_catalogue.storage_scope is distinct from 'organization_shared'
      or stored_catalogue.physical_schema_token is distinct from 'system_projection'
      or stored_catalogue.physical_table_token is distinct from
        ('rt_' || pg_catalog.replace(pg_catalog.lower(storage_id::text), '-', ''))
      or stored_catalogue.protected_read_model_key is distinct from protected_view_key
      or protected_view_key is null then
      raise exception using errcode = '55000',
        message = 'Target record storage lineage is incompatible';
    end if;
    select registered.reader_schema, registered.reader_function
    into reader_schema_value, reader_function_value
    from vortex_record.protected_read_model_views as registered
    where registered.protected_read_model_key = protected_view_key;
    if not found then
      raise exception using errcode = '55000',
        message = 'Protected projection view is unavailable';
    end if;
    view_oid := pg_catalog.to_regclass(pg_catalog.format(
      '%I.%I', 'record_data', stored_catalogue.physical_table_token
    ))::oid;
    reader_function_oid := pg_catalog.to_regprocedure(pg_catalog.format(
      '%I.%I(uuid,integer)', reader_schema_value, reader_function_value
    ))::oid;
    if view_oid is null
      or reader_function_oid is null
      or not exists (
        select 1
        from pg_catalog.pg_class as relation
        where relation.oid = view_oid
          and relation.relkind = 'v'
          and relation.relowner = 'vortex_record_owner'::regrole
      )
      or exists (
        select 1 from pg_catalog.pg_trigger as trigger
        where trigger.tgrelid = view_oid and not trigger.tgisinternal
      )
      or exists (
        select 1 from pg_catalog.pg_rewrite as rule
        where rule.ev_class = view_oid and rule.rulename <> '_RETURN'
      )
      or not exists (
        select 1
        from pg_catalog.pg_rewrite as rule
        join pg_catalog.pg_depend as dependency
          on dependency.classid = 'pg_rewrite'::regclass
          and dependency.objid = rule.oid
          and dependency.refclassid = 'pg_proc'::regclass
          and dependency.refobjid = reader_function_oid
        where rule.ev_class = view_oid and rule.rulename = '_RETURN'
      )
      or not exists (
        select 1 from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = view_oid
          and attribute.attname = 'record_id'
          and attribute.attnum > 0 and not attribute.attisdropped
      )
      or not exists (
        select 1 from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = view_oid
          and attribute.attname = 'organisation_id'
          and attribute.attnum > 0 and not attribute.attisdropped
      )
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(target_record_type -> 'fields') as field_item(value)
        where not exists (
          select 1 from pg_catalog.pg_attribute as attribute
          where attribute.attrelid = view_oid
            and attribute.attname = 'f_' || pg_catalog.replace(
              pg_catalog.lower(field_item.value ->> 'fieldId'), '-', ''
            )
            and attribute.attnum > 0 and not attribute.attisdropped
        )
      )
      or (
        select pg_catalog.count(*)
        from pg_catalog.pg_class as relation
        cross join lateral pg_catalog.aclexplode(coalesce(
          relation.relacl, pg_catalog.acldefault('r', relation.relowner)
        )) as privilege
        where relation.oid = view_oid
          and privilege.grantee = 'vortex_record_adapter'::regrole::oid
          and privilege.privilege_type = 'SELECT'
          and not privilege.is_grantable
      ) <> 1
      or exists (
        select 1
        from pg_catalog.pg_class as relation
        cross join lateral pg_catalog.aclexplode(coalesce(
          relation.relacl, pg_catalog.acldefault('r', relation.relowner)
        )) as privilege
        where relation.oid = view_oid
          and (privilege.grantee not in (
              'vortex_record_owner'::regrole::oid,
              'vortex_record_adapter'::regrole::oid
            )
            or (privilege.grantee = 'vortex_record_adapter'::regrole::oid
              and privilege.privilege_type <> 'SELECT')
            or (privilege.grantee = 'vortex_record_adapter'::regrole::oid
              and privilege.is_grantable))
      )
      or exists (
        select 1 from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = view_oid and attribute.attacl is not null
      ) then
      raise exception using errcode = '55000',
        message = 'Protected projection view lineage is incompatible';
    end if;

    perform vortex_record.create_system_projection_companion_storage_internal(
      storage_id, target_module_root_id, target_record_type_id,
      p_module_root_id, source_field, true
    );
  end loop;

  for contribution in
    select item.value
    from pg_catalog.jsonb_array_elements(p_contributions) as item(value)
    order by pg_catalog.lower(item.value ->> 'targetModuleRootId'),
      pg_catalog.lower(item.value ->> 'targetRecordTypeId'),
      pg_catalog.lower(item.value ->> 'contributionId')
  loop
    begin
      contribution_id := (contribution ->> 'contributionId')::uuid;
      target_module_root_id := (contribution ->> 'targetModuleRootId')::uuid;
      target_extension_point_id := (contribution ->> 'targetExtensionPointId')::uuid;
      target_record_type_id := (contribution ->> 'targetRecordTypeId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '22023', message = 'Module contribution identity is invalid';
    end;
    contribution_kind := contribution ->> 'kind';
    target_module_version := contribution ->> 'targetModuleReleaseVersion';
    if contribution_id is null
      or contribution_kind is null
      or target_module_version is null
      or not vortex_context.is_non_nil_uuid(contribution_id::text)
      or not vortex_context.is_non_nil_uuid(target_extension_point_id::text)
      or contribution_kind not in ('field', 'action') then
      raise exception using errcode = '22023', message = 'Module contribution binding is invalid';
    end if;

    -- The target is the exact dependency release the resolver bound; it must
    -- still declare the accepting extension point on the named record type.
    select release.* into strict target_release
    from vortex_definition.releases as release
    join vortex_definition.roots as root on root.root_id = release.root_id
    where release.root_id = target_module_root_id
      and release.release_version = target_module_version
      and root.kind = 'module';
    if target_release.validation_contract_version
      <> all (vortex_definition.accepted_contract_version('module')) then
      raise exception using errcode = '23514',
        message = 'Exact target Module release is incompatible';
    end if;
    target_content := target_release.compilation_output #> '{canonical,content}';
    select item.value into target_record_type
    from pg_catalog.jsonb_array_elements(target_content -> 'recordTypes') as item(value)
    where pg_catalog.lower(item.value ->> 'recordTypeId')
      = pg_catalog.lower(target_record_type_id::text);
    if target_record_type is null then
      raise exception using errcode = '23514', message = 'Target record type is unavailable';
    end if;
    select item.value into target_point
    from pg_catalog.jsonb_array_elements(target_content -> 'extensionPoints') as item(value)
    where pg_catalog.lower(item.value ->> 'extensionPointId')
      = pg_catalog.lower(target_extension_point_id::text);
    if target_point is null
      or pg_catalog.lower(target_point ->> 'recordTypeId')
        <> pg_catalog.lower(target_record_type_id::text)
      or not coalesce((target_point -> 'accepts') ? contribution_kind, false) then
      raise exception using errcode = '23514',
        message = 'Target extension point is unavailable';
    end if;

    -- The contributor's own exact release must declare this contribution to this
    -- target Module's extension point; a caller cannot attach an undeclared field
    -- or action.
    if not exists (
      select 1
      from pg_catalog.jsonb_array_elements(
          coalesce(release_row.compilation_output #> '{canonical,content,contributions}', '[]'::jsonb)
        ) as item(value)
      where pg_catalog.lower(item.value ->> 'contributionId')
          = pg_catalog.lower(contribution_id::text)
        and item.value ->> 'kind' = contribution_kind
        and pg_catalog.lower(item.value #>> '{targetModule,moduleRootId}')
          = pg_catalog.lower(target_module_root_id::text)
        and pg_catalog.lower(item.value ->> 'targetExtensionPointId')
          = pg_catalog.lower(target_extension_point_id::text)
        and (contribution_kind <> 'field'
          or pg_catalog.lower(item.value ->> 'recordTypeId')
            = pg_catalog.lower(contribution ->> 'recordTypeId'))
    ) then
      raise exception using errcode = '23514',
        message = 'Module contribution declaration is unavailable';
    end if;

    if contribution_kind = 'action' then
      -- An action contribution has no physical storage; the exact resolved
      -- binding already carries the capability, so only its identity is echoed.
      if not exists (
        select 1
        from pg_catalog.jsonb_array_elements(release_row.compilation_output #> '{canonical,content,actions}') as item(value)
        where pg_catalog.lower(item.value ->> 'actionId') = pg_catalog.lower(contribution_id::text)
      ) then
        raise exception using errcode = '23514',
          message = 'Contributed action definition is unavailable';
      end if;
      contribution_ids := contribution_ids || contribution_id;
      continue;
    end if;

    -- A field contribution reuses the contributor's exact field definition and
    -- adds its permanent value storage to the target's generated table or projection companion.
    begin
      source_record_type_id := (contribution ->> 'recordTypeId')::uuid;
      field_id_value := (contribution ->> 'fieldId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '22023', message = 'Contributed field identity is invalid';
    end;
    if not vortex_context.is_non_nil_uuid(source_record_type_id::text)
      or not vortex_context.is_non_nil_uuid(field_id_value::text)
      or field_id_value <> contribution_id then
      raise exception using errcode = '22023', message = 'Contributed field identity is invalid';
    end if;
    source_field := null;
    select item.value into source_field
    from pg_catalog.jsonb_array_elements(
        release_row.compilation_output #> '{canonical,content,recordTypes}'
      ) as record_item(value)
    cross join lateral pg_catalog.jsonb_array_elements(
      record_item.value -> 'fields'
    ) as item(value)
    where pg_catalog.lower(record_item.value ->> 'recordTypeId')
        = pg_catalog.lower(source_record_type_id::text)
      and pg_catalog.lower(item.value ->> 'fieldId')
        = pg_catalog.lower(field_id_value::text);
    if source_field is null then
      raise exception using errcode = '23514',
        message = 'Contributed field definition is unavailable';
    end if;

    -- The contributed identity may not collide with the target's own component.
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(target_record_type -> 'fields') as item(value)
      where pg_catalog.lower(item.value ->> 'fieldId')
        = pg_catalog.lower(field_id_value::text)
    ) or exists (
      select 1
      from pg_catalog.jsonb_array_elements(target_content -> 'actions') as item(value)
      where pg_catalog.lower(item.value ->> 'actionId')
        = pg_catalog.lower(field_id_value::text)
    ) then
      raise exception using errcode = '55000',
        message = 'Contributed field collides with target storage';
    end if;

    select catalogue.* into strict stored_catalogue
    from vortex_record.storage_catalogue as catalogue
    where catalogue.module_root_id = target_module_root_id
      and catalogue.record_type_id = target_record_type_id
      and catalogue.state = 'active';
    table_token := stored_catalogue.physical_table_token;
    storage_scope_value := stored_catalogue.storage_scope;
    scope_index_columns := vortex_record.index_scope_columns(storage_scope_value);
    is_projection := target_record_type ? 'systemProjection';
    column_token := 'f_' || pg_catalog.replace(pg_catalog.lower(field_id_value::text), '-', '');
    database_type := vortex_record.database_value_type(source_field);
    sql_type := vortex_record.sql_value_type(database_type);
    if database_type is null or sql_type is null then
      raise exception using errcode = '23514', message = 'Contributed field type is unsupported';
    end if;

    if is_projection then
      begin
        storage_id := (target_record_type ->> 'storageContractId')::uuid;
      exception when invalid_text_representation then
        raise exception using errcode = '55000',
          message = 'Target record storage lineage is incompatible';
      end;
      if storage_id is distinct from stored_catalogue.storage_contract_id
        or stored_catalogue.storage_scope is distinct from 'organization_shared'
        or stored_catalogue.physical_schema_token is distinct from 'system_projection'
        or stored_catalogue.physical_table_token is distinct from
          ('rt_' || pg_catalog.replace(pg_catalog.lower(storage_id::text), '-', ''))
        or stored_catalogue.protected_read_model_key is distinct from
          (target_record_type #>> '{systemProjection,protectedView}') then
        raise exception using errcode = '55000',
          message = 'Target record storage lineage is incompatible';
      end if;
      perform vortex_record.create_system_projection_companion_storage_internal(
        stored_catalogue.storage_contract_id, target_module_root_id,
        target_record_type_id, p_module_root_id, source_field, false
      );
      select mapping.* into stored_field
      from vortex_record.field_storage_mappings as mapping
      where mapping.storage_contract_id = stored_catalogue.storage_contract_id
        and mapping.field_id = field_id_value
      for update;
      if found then
        if stored_field.physical_column_token <> column_token
          or stored_field.database_value_type <> database_type
          or stored_field.introduced_by_module_root_id <> p_module_root_id
          or vortex_record.field_storage_meaning(stored_field.field_definition)
            is distinct from vortex_record.field_storage_meaning(source_field)
          or stored_field.state not in ('active', 'retired') then
          raise exception using errcode = '55000',
            message = 'Existing contributed field storage is incompatible';
        end if;
        if stored_field.state = 'retired' then
          update vortex_record.field_storage_mappings as mapping
          set state = 'active',
              retired_by_module_root_id = null,
              retired_at_release_revision = null
          where mapping.storage_contract_id = stored_catalogue.storage_contract_id
            and mapping.field_id = field_id_value;
          any_change := true;
        end if;
      else
        insert into vortex_record.field_storage_mappings (
          storage_contract_id, field_id, physical_column_token, database_value_type,
          field_definition, introduced_by_module_root_id, introduced_at_release_revision, state
        ) values (
          stored_catalogue.storage_contract_id, field_id_value, column_token, database_type,
          source_field, p_module_root_id, p_module_release_revision, 'active'
        );
        any_change := true;
      end if;
    else
      if stored_catalogue.physical_schema_token <> 'record_data'
        or scope_index_columns is null then
        raise exception using errcode = '55000', message = 'Target record storage is incompatible';
      end if;

      select mapping.* into stored_field
      from vortex_record.field_storage_mappings as mapping
      where mapping.storage_contract_id = stored_catalogue.storage_contract_id
        and mapping.field_id = field_id_value
      for update;
      if found then
        if stored_field.physical_column_token <> column_token
          or stored_field.database_value_type <> database_type
          or stored_field.introduced_by_module_root_id <> p_module_root_id
          or vortex_record.field_storage_meaning(stored_field.field_definition)
            is distinct from vortex_record.field_storage_meaning(source_field)
          or not exists (
            select 1
            from pg_catalog.pg_attribute as attribute
            where attribute.attrelid = pg_catalog.to_regclass(
                pg_catalog.format('%I.%I', 'record_data', table_token)
              )
              and attribute.attname = column_token
              and attribute.attnum > 0
              and not attribute.attisdropped
          ) then
          raise exception using errcode = '55000',
            message = 'Existing contributed field storage is incompatible';
        end if;
        if stored_field.state = 'retired' then
          update vortex_record.field_storage_mappings as mapping
          set state = 'active',
              retired_by_module_root_id = null,
              retired_at_release_revision = null
          where mapping.storage_contract_id = stored_catalogue.storage_contract_id
            and mapping.field_id = field_id_value;
          any_change := true;
        elsif stored_field.state <> 'active' then
          raise exception using errcode = '55000',
            message = 'Existing contributed field storage is incompatible';
        end if;
      else
        if (source_field ->> 'required')::boolean then
          raise exception using errcode = '55000',
            message = 'A new contributed field must be optional on shared storage';
        end if;
        -- A column without a mapping has unknown meaning and values, so it is
        -- never adopted.
        if exists (
          select 1
          from pg_catalog.pg_attribute as attribute
          where attribute.attrelid = pg_catalog.to_regclass(
              pg_catalog.format('%I.%I', 'record_data', table_token)
            )
            and attribute.attname = column_token
            and attribute.attnum > 0
            and not attribute.attisdropped
        ) then
          raise exception using errcode = '55000',
            message = 'Existing contributed field storage is incompatible';
        end if;
        execute pg_catalog.format(
          'alter table record_data.%I add column %I %s',
          table_token, column_token, sql_type
        );
        insert into vortex_record.field_storage_mappings (
          storage_contract_id, field_id, physical_column_token, database_value_type,
          field_definition, introduced_by_module_root_id, introduced_at_release_revision, state
        ) values (
          stored_catalogue.storage_contract_id, field_id_value, column_token, database_type,
          source_field, p_module_root_id, p_module_release_revision, 'active'
        );
        if (source_field ->> 'unique')::boolean then
          perform vortex_record.ensure_field_index_internal(
            stored_catalogue.storage_contract_id, field_id_value, 'uniqueness',
            storage_scope_value, table_token, scope_index_columns, column_token
          );
        elsif (source_field ->> 'filterable')::boolean
          or (source_field ->> 'sortable')::boolean then
          perform vortex_record.ensure_field_index_internal(
            stored_catalogue.storage_contract_id, field_id_value, 'performance',
            storage_scope_value, table_token, scope_index_columns, column_token
          );
        end if;
        any_change := true;
      end if;
    end if;

    contribution_ids := contribution_ids || contribution_id;
  end loop;

  return query select p_module_root_id, p_module_release_revision, contribution_ids, any_change;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Exact Module contribution evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Module contribution evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.provision_exact_module_contributions(p_module_root_id uuid, p_module_release_revision bigint, p_contributions jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION provision_exact_module_contributions(p_module_root_id uuid, p_module_release_revision bigint, p_contributions jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.provision_exact_module_contributions(p_module_root_id uuid, p_module_release_revision bigint, p_contributions jsonb) IS 'Private exact-release contributor storage provisioner: adds generated-table fields or optional unindexed system-projection companion fields and records their retained lineage. It never drops a column, changes projection identity, or overwrites a value.';


--
-- Name: provision_exact_module_storage(uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.provision_exact_module_storage(
  p_module_root_id uuid,
  p_module_release_revision bigint
)
returns table (
  module_root_id uuid,
  release_revision bigint,
  storage_contract_ids uuid[],
  changed boolean
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  release_row vortex_definition.releases%rowtype;
  record_types jsonb;
  record_type jsonb;
  stored_catalogue vortex_record.storage_catalogue%rowtype;
  stored_field vortex_record.field_storage_mappings%rowtype;
  projection_expression_pair record;
  field_value jsonb;
  relationship_value jsonb;
  target_value jsonb;
  target_ids uuid[];
  storage_id uuid;
  record_type_id_value uuid;
  field_id_value uuid;
  relationship_id_value uuid;
  table_token text;
  column_token text;
  storage_scope_value text;
  ownership_mode_value text;
  database_type text;
  sql_type text;
  stored_projection_role text;
  requested_projection_role text;
  stored_database_type text;
  requested_database_type text;
  stored_sql_type text;
  requested_sql_type text;
  stored_expression jsonb;
  requested_expression jsonb;
  shape_fingerprint text;
  scope_index_columns text;
  result_storage_ids uuid[] := array[]::uuid[];
  any_change boolean := false;
  is_projection boolean;
  protected_view_key text;
  reader_schema_value text;
  reader_function_value text;
  field_columns_sql text;
  projection_view_sql text;
  existing_columns text[];
  expected_columns text[];
begin
  if not vortex_context.is_non_nil_uuid(p_module_root_id::text)
    or p_module_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023', message = 'Record storage release selector is invalid';
  end if;

  select release.* into strict release_row
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_module_root_id
    and release.release_revision = p_module_release_revision
    and root.kind = 'module';
  -- Module V3 reuses the Module V2 record-type content, so both validation
  -- contracts allocate identical storage. The source contract must agree with
  -- the validation contract, and the embedded identity is compared with
  -- IS DISTINCT FROM so an absent JSON member cannot evade the gate.
  if release_row.validation_contract_version <> all (vortex_definition.accepted_contract_version('module'))
    or release_row.source_contract_version
      is distinct from release_row.validation_contract_version
    or release_row.compilation_output #>> '{kind}' is distinct from 'module'
    or release_row.compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from p_module_root_id::text
    or release_row.compilation_output #>> '{validationContractVersion}'
      is distinct from release_row.validation_contract_version then
    raise exception using errcode = '23514', message = 'Exact Module release is incompatible';
  end if;

  record_types := release_row.compilation_output #> '{canonical,content,recordTypes}';
  if pg_catalog.jsonb_typeof(record_types) <> 'array'
    or pg_catalog.jsonb_array_length(record_types) < 1 then
    raise exception using errcode = '23514', message = 'Module record storage definition is incompatible';
  end if;

  perform 1 from vortex_record.release_provisions as provision
  where provision.module_root_id = p_module_root_id
    and provision.release_revision = p_module_release_revision
  for update;
  if found then
    select provision.storage_contract_ids into result_storage_ids
    from vortex_record.release_provisions as provision
    where provision.module_root_id = p_module_root_id
      and provision.release_revision = p_module_release_revision;
    if result_storage_ids is distinct from (
      select pg_catalog.array_agg((item.value ->> 'storageContractId')::uuid order by item.value ->> 'storageContractId')
      from pg_catalog.jsonb_array_elements(record_types) as item(value)
    ) then
      raise exception using errcode = '55000', message = 'Stored release provision identities are incompatible';
    end if;
    result_storage_ids := array[]::uuid[];
  end if;

  if (
    select pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'storageContractId')
      or pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'recordTypeId')
    from pg_catalog.jsonb_array_elements(record_types) as item(value)
  ) then
    raise exception using errcode = '23514', message = 'Module record storage identities are duplicated';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(record_types) as record_item(value)
    where (
      select pg_catalog.count(*) <> pg_catalog.count(distinct field_item.value ->> 'fieldId')
      from pg_catalog.jsonb_array_elements(record_item.value -> 'fields') as field_item(value)
    )
  ) or (
    select pg_catalog.count(*) <> pg_catalog.count(distinct relationship_item.value ->> 'relationshipId')
    from pg_catalog.jsonb_array_elements(record_types) as record_item(value)
    cross join lateral pg_catalog.jsonb_array_elements(
      record_item.value -> 'relationships'
    ) as relationship_item(value)
  ) then
    raise exception using errcode = '23514', message = 'Module field or relationship identities are duplicated';
  end if;

  for record_type in
    select item.value
    from pg_catalog.jsonb_array_elements(record_types) as item(value)
    order by item.value ->> 'storageContractId'
  loop
    begin
      storage_id := (record_type ->> 'storageContractId')::uuid;
      record_type_id_value := (record_type ->> 'recordTypeId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '42501', message = 'Module record storage identity is invalid';
    end;
    storage_scope_value := record_type ->> 'storageScope';
    ownership_mode_value := record_type ->> 'ownershipMode';
    if not vortex_context.is_non_nil_uuid(storage_id::text)
      or not vortex_context.is_non_nil_uuid(record_type_id_value::text)
      or storage_scope_value not in ('organization_shared', 'application_contained')
      or ownership_mode_value not in ('none', 'organization_account', 'group', 'inherited')
      or pg_catalog.jsonb_typeof(record_type -> 'fields') <> 'array'
      or pg_catalog.jsonb_array_length(record_type -> 'fields') < 1
      or pg_catalog.jsonb_typeof(record_type -> 'relationships') <> 'array' then
      raise exception using errcode = '42501', message = 'Module record storage definition is invalid';
    end if;
    -- The record-type loop is ordered by storage identity, so overlapping
    -- provisions acquire absent and existing lineage locks deterministically.
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('vortex_record.storage:' || storage_id::text, 0)
    );
    table_token := 'rt_' || pg_catalog.replace(pg_catalog.lower(storage_id::text), '-', '');
    shape_fingerprint := vortex_record.storage_meaning_fingerprint(record_type);
    result_storage_ids := result_storage_ids || storage_id;
    scope_index_columns := case storage_scope_value
      when 'organization_shared' then 'organisation_id'
      else 'organisation_id, application_root_id'
    end;

    -- A system projection record type has no generated storage. It is read
    -- through one registered protected view, created here as an ordinary
    -- record_data relation so the fixed read adapters resolve it unchanged,
    -- while the projection itself keeps every row-visibility rule inside the
    -- registered function. The view exposes exactly the record type's declared
    -- fields as record-data columns, plus the protected row identity and
    -- revision, and is read-only: the projection has no ordinary write path.
    -- Every projection value is reset per record type, so a generated record
    -- type provisioned after a projection never inherits its protected key.
    is_projection := record_type ? 'systemProjection';
    protected_view_key := null;
    reader_schema_value := null;
    reader_function_value := null;
    projection_view_sql := null;
    if is_projection then
      protected_view_key := record_type #>> '{systemProjection,protectedView}';
      select registered.reader_schema, registered.reader_function
      into reader_schema_value, reader_function_value
      from vortex_record.protected_read_model_views as registered
      where registered.protected_read_model_key = protected_view_key;
      if not found then
        raise exception using errcode = '42501',
          message = 'Protected projection view is unavailable';
      end if;
      if storage_scope_value <> 'organization_shared' then
        raise exception using errcode = '42501',
          message = 'Protected projection storage must be organisation shared';
      end if;
      field_columns_sql := '';
      expected_columns := array[]::text[];
      for field_value in
        select item.value
        from pg_catalog.jsonb_array_elements(record_type -> 'fields') as item(value)
        order by item.value ->> 'fieldId'
      loop
        begin
          field_id_value := (field_value ->> 'fieldId')::uuid;
        exception when invalid_text_representation then
          raise exception using errcode = '42501',
            message = 'Record field storage identity is invalid';
        end;
        column_token := 'f_' || pg_catalog.replace(pg_catalog.lower(field_id_value::text), '-', '');
        database_type := vortex_record.database_value_type(field_value);
        if database_type is null then
          raise exception using errcode = '23514',
            message = 'Record field storage type is unsupported';
        end if;
        sql_type := vortex_record.sql_value_type(database_type);
        expected_columns := expected_columns || column_token;
        if field_value ->> 'fieldId' = record_type #>> '{systemProjection,organizationFieldId}' then
          field_columns_sql := field_columns_sql
            || pg_catalog.format('projection.organization_id::text as %I, ', column_token);
        elsif field_value ->> 'fieldId' = record_type #>> '{systemProjection,revisionFieldId}' then
          field_columns_sql := field_columns_sql
            || pg_catalog.format('projection.revision::%s as %I, ', sql_type, column_token);
        elsif database_type = 'json' then
          field_columns_sql := field_columns_sql
            || pg_catalog.format(
              '(projection.attribute_values -> %L) as %I, ', field_value ->> 'key', column_token
            );
        else
          field_columns_sql := field_columns_sql
            || pg_catalog.format(
              '(projection.attribute_values ->> %L)::%s as %I, ',
              field_value ->> 'key', sql_type, column_token
            );
        end if;
      end loop;
      select pg_catalog.array_agg(item.column_name order by item.column_name)
      into expected_columns
      from pg_catalog.unnest(expected_columns) as item(column_name);
      field_columns_sql := pg_catalog.left(
        field_columns_sql, pg_catalog.length(field_columns_sql) - 2
      );
      projection_view_sql := pg_catalog.format(
        'create view record_data.%I as select
           projection.organization_id as organisation_id,
           %L::uuid as module_root_id,
           %L::uuid as record_type_id,
           %L::uuid as storage_contract_id,
           projection.record_id,
           null::uuid as application_root_id,
           %L::bigint as definition_revision,
           null::uuid as owner_organisation_account_id,
           null::uuid as owner_group_id,
           ''active''::text as lifecycle_state,
           projection.revision as concurrency_number,
           null::timestamptz as created_at,
           null::uuid as created_by,
           null::timestamptz as updated_at,
           null::uuid as updated_by,
           null::timestamptz as deleted_at,
           null::uuid as deleted_by,
           null::timestamptz as removal_due_at,
           %s
         from %I.%I(null::uuid, null::integer) as projection',
        table_token, p_module_root_id, record_type_id_value, storage_id,
        p_module_release_revision, field_columns_sql,
        reader_schema_value, reader_function_value
      );
    end if;

    select catalogue.* into stored_catalogue
    from vortex_record.storage_catalogue as catalogue
    where catalogue.storage_contract_id = storage_id
    for update;

    if not found then
      if is_projection then
        execute projection_view_sql;
        execute pg_catalog.format(
          'grant select on record_data.%I to vortex_record_adapter', table_token
        );
      else
        perform vortex_record.create_record_storage_table_internal(
          storage_id, p_module_root_id, record_type_id_value,
          storage_scope_value, ownership_mode_value
        );
      end if;

      insert into vortex_record.storage_catalogue (
        storage_contract_id, physical_schema_token, physical_table_token,
        module_root_id, record_type_id, storage_scope,
        first_compatible_release_revision, last_compatible_release_revision,
        state, content_fingerprint, record_type_definition, protected_read_model_key
      ) values (
        storage_id,
        case when is_projection then 'system_projection' else 'record_data' end,
        table_token, p_module_root_id, record_type_id_value, storage_scope_value,
        p_module_release_revision, p_module_release_revision, 'active',
        shape_fingerprint, record_type, protected_view_key
      );
      any_change := true;
    else
      if is_projection then
        if stored_catalogue.module_root_id <> p_module_root_id
          or stored_catalogue.record_type_id <> record_type_id_value
          or stored_catalogue.storage_scope <> storage_scope_value
          or stored_catalogue.state <> 'active'
          or stored_catalogue.physical_schema_token <> 'system_projection'
          or stored_catalogue.protected_read_model_key is distinct from protected_view_key
          or stored_catalogue.physical_table_token <> table_token
          or pg_catalog.to_regclass(pg_catalog.format('%I.%I', 'record_data', table_token)) is null then
          raise exception using errcode = '55000', message = 'Record storage lineage is incompatible';
        end if;
        if pg_catalog.jsonb_typeof(stored_catalogue.record_type_definition) is distinct from 'object'
          or pg_catalog.jsonb_typeof(stored_catalogue.record_type_definition -> 'fields') is distinct from 'array'
          or pg_catalog.jsonb_typeof(stored_catalogue.record_type_definition -> 'systemProjection') is distinct from 'object'
          or pg_catalog.jsonb_typeof(record_type -> 'systemProjection') is distinct from 'object' then
          raise exception using errcode = '55000', message = 'Existing record field storage is incompatible';
        end if;

        -- The catalogue keeps the newest compatible exact definition. Compare
        -- only shared field identities so an older subset and newer additions
        -- retain their existing release-order behavior. These descriptors
        -- mirror the source expressions assembled above, including the
        -- protected attribute key, JSON/text extraction, and cast.
        for projection_expression_pair in
          select requested_item.value as requested_field,
            stored_item.value as stored_field
          from pg_catalog.jsonb_array_elements(record_type -> 'fields') as requested_item(value)
          join pg_catalog.jsonb_array_elements(
            stored_catalogue.record_type_definition -> 'fields'
          ) as stored_item(value)
            on stored_item.value ->> 'fieldId' = requested_item.value ->> 'fieldId'
          order by requested_item.value ->> 'fieldId'
        loop
          stored_projection_role := case
            when projection_expression_pair.stored_field ->> 'fieldId'
              = stored_catalogue.record_type_definition #>> '{systemProjection,organizationFieldId}'
              then 'organization'
            when projection_expression_pair.stored_field ->> 'fieldId'
              = stored_catalogue.record_type_definition #>> '{systemProjection,revisionFieldId}'
              then 'revision'
            else 'attribute'
          end;
          requested_projection_role := case
            when projection_expression_pair.requested_field ->> 'fieldId'
              = record_type #>> '{systemProjection,organizationFieldId}'
              then 'organization'
            when projection_expression_pair.requested_field ->> 'fieldId'
              = record_type #>> '{systemProjection,revisionFieldId}'
              then 'revision'
            else 'attribute'
          end;
          stored_database_type := vortex_record.database_value_type(
            projection_expression_pair.stored_field
          );
          requested_database_type := vortex_record.database_value_type(
            projection_expression_pair.requested_field
          );
          if stored_projection_role is distinct from requested_projection_role
            or stored_database_type is null
            or requested_database_type is null then
            raise exception using errcode = '55000', message = 'Existing record field storage is incompatible';
          end if;
          stored_sql_type := vortex_record.sql_value_type(stored_database_type);
          requested_sql_type := vortex_record.sql_value_type(requested_database_type);
          stored_expression := case stored_projection_role
            when 'organization' then pg_catalog.jsonb_build_object(
              'role', stored_projection_role,
              'source', 'projection.organization_id',
              'cast', 'text'
            )
            when 'revision' then pg_catalog.jsonb_build_object(
              'role', stored_projection_role,
              'source', 'projection.revision',
              'cast', stored_sql_type
            )
            else pg_catalog.jsonb_build_object(
              'role', stored_projection_role,
              'source', 'projection.attribute_values',
              'key', projection_expression_pair.stored_field ->> 'key',
              'extraction', case when stored_database_type = 'json' then '->' else '->>' end,
              'cast', case when stored_database_type = 'json' then null else stored_sql_type end
            )
          end;
          requested_expression := case requested_projection_role
            when 'organization' then pg_catalog.jsonb_build_object(
              'role', requested_projection_role,
              'source', 'projection.organization_id',
              'cast', 'text'
            )
            when 'revision' then pg_catalog.jsonb_build_object(
              'role', requested_projection_role,
              'source', 'projection.revision',
              'cast', requested_sql_type
            )
            else pg_catalog.jsonb_build_object(
              'role', requested_projection_role,
              'source', 'projection.attribute_values',
              'key', projection_expression_pair.requested_field ->> 'key',
              'extraction', case when requested_database_type = 'json' then '->' else '->>' end,
              'cast', case when requested_database_type = 'json' then null else requested_sql_type end
            )
          end;
          if stored_expression is distinct from requested_expression then
            raise exception using errcode = '55000', message = 'Existing record field storage is incompatible';
          end if;
        end loop;

        select coalesce(
            pg_catalog.array_agg(attribute.attname order by attribute.attname),
            array[]::text[]
          )
        into existing_columns
        from pg_catalog.pg_attribute as attribute
        where attribute.attrelid = pg_catalog.to_regclass(
            pg_catalog.format('%I.%I', 'record_data', table_token)
          )
          and attribute.attnum > 0
          and not attribute.attisdropped
          and attribute.attname like 'f\_%';
        -- The view always carries the newest compatible release's shape, as a
        -- generated table keeps every column a newer release added. A newer
        -- release, or the newest one with a different field set, recreates it
        -- exactly; an older release, which the field checks below prove is a
        -- compatible subset, leaves the newer view alone. The projection has no
        -- indexes or dependent objects.
        if p_module_release_revision > stored_catalogue.last_compatible_release_revision
          or (p_module_release_revision = stored_catalogue.last_compatible_release_revision
            and existing_columns is distinct from expected_columns) then
          execute pg_catalog.format('drop view record_data.%I', table_token);
          execute projection_view_sql;
          execute pg_catalog.format(
            'grant select on record_data.%I to vortex_record_adapter', table_token
          );
          any_change := true;
        end if;
      else
        if stored_catalogue.module_root_id <> p_module_root_id
          or stored_catalogue.record_type_id <> record_type_id_value
          or stored_catalogue.storage_scope <> storage_scope_value
          or stored_catalogue.state <> 'active'
          or stored_catalogue.physical_schema_token <> 'record_data'
          or stored_catalogue.physical_table_token <> table_token
          or pg_catalog.to_regclass(pg_catalog.format('%I.%I', 'record_data', table_token)) is null then
          raise exception using errcode = '55000', message = 'Record storage lineage is incompatible';
        end if;
      end if;
    end if;

    for field_value in
      select item.value from pg_catalog.jsonb_array_elements(record_type -> 'fields') as item(value)
      order by item.value ->> 'fieldId'
    loop
      begin
        field_id_value := (field_value ->> 'fieldId')::uuid;
      exception when invalid_text_representation then
        raise exception using errcode = '42501', message = 'Record field storage identity is invalid';
      end;
      if not vortex_context.is_non_nil_uuid(field_id_value::text)
        or field_value ->> 'type' is null
        or pg_catalog.jsonb_typeof(field_value -> 'required') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'unique') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'filterable') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'sortable') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'settings') <> 'object' then
        raise exception using errcode = '42501', message = 'Record field storage definition is invalid';
      end if;
      column_token := 'f_' || pg_catalog.replace(pg_catalog.lower(field_id_value::text), '-', '');
      database_type := vortex_record.database_value_type(field_value);
      if database_type is null then
        raise exception using errcode = '23514', message = 'Record field storage type is unsupported';
      end if;
      sql_type := vortex_record.sql_value_type(database_type);

      select mapping.* into stored_field
      from vortex_record.field_storage_mappings as mapping
      where mapping.storage_contract_id = storage_id and mapping.field_id = field_id_value
      for update;
      if found then
        if stored_field.physical_column_token <> column_token
          or stored_field.database_value_type <> database_type
          or stored_field.state <> 'active'
          or vortex_record.field_storage_meaning(stored_field.field_definition)
            is distinct from vortex_record.field_storage_meaning(field_value)
          or not exists (
            select 1
            from pg_catalog.pg_attribute as attribute
            where attribute.attrelid = pg_catalog.to_regclass(
                pg_catalog.format('%I.%I', 'record_data', table_token)
              )
              and attribute.attname = column_token
              and attribute.attnum > 0
              and not attribute.attisdropped
          ) then
          raise exception using errcode = '55000', message = 'Existing record field storage is incompatible';
        end if;
      else
        if not is_projection then
          if stored_catalogue.storage_contract_id is not null
            and (field_value ->> 'required')::boolean then
            raise exception using errcode = '55000', message = 'Compatible storage upgrades may add only nullable fields';
          end if;
          execute pg_catalog.format(
            'alter table record_data.%I add column %I %s%s',
            table_token, column_token, sql_type,
            case when (field_value ->> 'required')::boolean then ' not null' else '' end
          );
        end if;
        insert into vortex_record.field_storage_mappings (
          storage_contract_id, field_id, physical_column_token, database_value_type,
          field_definition, introduced_by_module_root_id, introduced_at_release_revision, state
        ) values (
          storage_id, field_id_value, column_token, database_type, field_value,
          p_module_root_id, p_module_release_revision, 'active'
        );
        -- A projection field lives in the protected view, which carries no
        -- indexes; the projection's own protected function applies visibility,
        -- ordering and filtering, so no generated index is provisioned.
        if is_projection then
          null;
        elsif (field_value ->> 'unique')::boolean then
          perform vortex_record.ensure_field_index_internal(
            storage_id, field_id_value, 'uniqueness', storage_scope_value,
            table_token, scope_index_columns, column_token
          );
        elsif (field_value ->> 'filterable')::boolean or (field_value ->> 'sortable')::boolean then
          perform vortex_record.ensure_field_index_internal(
            storage_id, field_id_value, 'performance', storage_scope_value,
            table_token, scope_index_columns, column_token
          );
        end if;
        any_change := true;
      end if;
    end loop;

    -- Only a field this Module itself introduced can prove a removed field. A
    -- field another Module contributed keeps its retained lineage and never
    -- refuses this Module's own storage.
    if exists (
      select 1 from vortex_record.field_storage_mappings as mapping
      where mapping.storage_contract_id = storage_id and mapping.state = 'active'
        and mapping.introduced_by_module_root_id = p_module_root_id
        and mapping.introduced_at_release_revision <= p_module_release_revision
        and not exists (
          select 1 from pg_catalog.jsonb_array_elements(record_type -> 'fields') as item(value)
          where item.value ->> 'fieldId' = mapping.field_id::text
        )
    ) then
      raise exception using errcode = '55000', message = 'Compatible storage upgrades cannot remove fields';
    end if;

    if stored_catalogue.storage_contract_id is not null
      and stored_catalogue.last_compatible_release_revision < p_module_release_revision then
      update vortex_record.storage_catalogue
      set last_compatible_release_revision = greatest(
            last_compatible_release_revision, p_module_release_revision
          ),
          content_fingerprint = shape_fingerprint,
          record_type_definition = record_type,
          changed_at = pg_catalog.statement_timestamp()
      where storage_contract_id = storage_id;
      any_change := true;
    elsif stored_catalogue.storage_contract_id is not null
      and stored_catalogue.first_compatible_release_revision > p_module_release_revision then
      -- A newer release may have created the shared table first. The loops above
      -- prove the older release is a compatible subset; retain the newer shape.
      update vortex_record.storage_catalogue
      set first_compatible_release_revision = p_module_release_revision,
          changed_at = pg_catalog.statement_timestamp()
      where storage_contract_id = storage_id;
    elsif stored_catalogue.storage_contract_id is not null
      and stored_catalogue.last_compatible_release_revision = p_module_release_revision
      and stored_catalogue.content_fingerprint <> shape_fingerprint then
      raise exception using errcode = '55000', message = 'Stored record storage meaning is incompatible';
    end if;
  end loop;

  if exists (
    select 1
    from vortex_record.relationship_storage_mappings as mapping
    where mapping.module_root_id = p_module_root_id
      and mapping.release_revision <= p_module_release_revision
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(record_types) as record_item(value)
        cross join lateral pg_catalog.jsonb_array_elements(
          record_item.value -> 'relationships'
        ) as relationship_item(value)
        where relationship_item.value ->> 'relationshipId' = mapping.relationship_id::text
      )
  ) then
    raise exception using errcode = '55000', message = 'Compatible storage upgrades cannot remove relationships';
  end if;

  for record_type in select item.value from pg_catalog.jsonb_array_elements(record_types) as item(value)
  loop
    storage_id := (record_type ->> 'storageContractId')::uuid;
    for relationship_value in
      select item.value from pg_catalog.jsonb_array_elements(record_type -> 'relationships') as item(value)
    loop
      relationship_id_value := (relationship_value ->> 'relationshipId')::uuid;
      field_id_value := (relationship_value ->> 'fromFieldId')::uuid;
      target_ids := array[]::uuid[];
      if relationship_value ? 'toRecordType' then
        target_ids := array[(relationship_value #>> '{toRecordType,recordTypeId}')::uuid];
      else
        for target_value in select item.value
          from pg_catalog.jsonb_array_elements(relationship_value -> 'toRecordTypes') as item(value)
        loop
          target_ids := target_ids || (target_value ->> 'recordTypeId')::uuid;
        end loop;
      end if;
      if pg_catalog.cardinality(target_ids) < 1 or array_position(target_ids, null) is not null then
        raise exception using errcode = '42501', message = 'Relationship target evidence is unresolved';
      end if;
      insert into vortex_record.relationship_storage_mappings (
        relationship_id, module_root_id, release_revision, source_storage_contract_id,
        source_field_id, target_record_type_ids, cardinality, on_parent_delete, definition
      ) values (
        relationship_id_value, p_module_root_id, p_module_release_revision, storage_id,
        field_id_value, target_ids, relationship_value ->> 'cardinality',
        relationship_value ->> 'onParentDelete', relationship_value
      )
      on conflict (relationship_id) do update
      set release_revision = greatest(
            vortex_record.relationship_storage_mappings.release_revision,
            excluded.release_revision
          )
      where vortex_record.relationship_storage_mappings.module_root_id = excluded.module_root_id
        and vortex_record.relationship_storage_mappings.source_storage_contract_id = excluded.source_storage_contract_id
        and vortex_record.relationship_storage_mappings.source_field_id = excluded.source_field_id
        and vortex_record.relationship_storage_mappings.target_record_type_ids = excluded.target_record_type_ids
        and vortex_record.relationship_storage_mappings.cardinality = excluded.cardinality
        and vortex_record.relationship_storage_mappings.on_parent_delete = excluded.on_parent_delete
        and vortex_record.relationship_storage_mappings.definition = excluded.definition;
      if not found then
        raise exception using errcode = '55000', message = 'Existing relationship storage is incompatible';
      end if;
    end loop;
  end loop;

  select pg_catalog.array_agg(value order by value) into result_storage_ids
  from pg_catalog.unnest(result_storage_ids) as item(value);
  insert into vortex_record.release_provisions (
    module_root_id, release_revision, storage_contract_ids
  ) values (
    p_module_root_id, p_module_release_revision, result_storage_ids
  ) on conflict on constraint release_provisions_pkey do nothing;

  return query select p_module_root_id, p_module_release_revision,
    result_storage_ids, any_change;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Exact Module release is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Module storage evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.provision_exact_module_storage(p_module_root_id uuid, p_module_release_revision bigint) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION provision_exact_module_storage(p_module_root_id uuid, p_module_release_revision bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.provision_exact_module_storage(p_module_root_id uuid, p_module_release_revision bigint) IS 'Private exact-release Module storage provisioner: creates or evolves the generated record_data storage, or the read-only record_data view over one registered protected projection reader for a system projection record type, for one published Module release and records its immutable provision evidence.';


--
-- Name: provision_offboarding_owner_index_internal(); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.provision_offboarding_owner_index_internal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.state = 'active'
    and new.physical_schema_token = 'record_data'
    and new.record_type_definition ->> 'ownershipMode' = 'organization_account' then
    perform vortex_record.ensure_offboarding_owner_index_internal(new.physical_table_token);
  end if;
  return new;
end
$$;


ALTER FUNCTION vortex_record.provision_offboarding_owner_index_internal() OWNER TO vortex_record_owner;

--
-- Name: provision_preview_module_storage(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.provision_preview_module_storage(
  p_preview_installation_id uuid,
  p_module_root_id uuid,
  p_module_release_revision bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  release_row vortex_definition.releases%rowtype;
  record_types jsonb;
  record_type jsonb;
  preview_record_type jsonb;
  field_value jsonb;
  storage_id uuid;
  preview_storage_id uuid;
  record_type_id_value uuid;
  field_id_value uuid;
  table_token text;
  column_token text;
  storage_scope_value text;
  ownership_mode_value text;
  database_type text;
  sql_type text;
  shape_fingerprint text;
  scope_index_columns text;
  index_token text;
  storage_identities jsonb := '[]'::jsonb;
begin
  if not vortex_context.is_non_nil_uuid(p_preview_installation_id::text)
    or not vortex_context.is_non_nil_uuid(p_module_root_id::text)
    or p_module_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023', message = 'Preview storage selector is invalid';
  end if;
  select release.* into strict release_row
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_module_root_id
    and release.release_revision = p_module_release_revision
    and root.kind = 'module';
  if release_row.validation_contract_version <> all (vortex_definition.accepted_contract_version('module'))
    or release_row.source_contract_version
      is distinct from release_row.validation_contract_version
    or release_row.compilation_output #>> '{kind}' is distinct from 'module'
    or release_row.compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from p_module_root_id::text
    or release_row.compilation_output #>> '{validationContractVersion}'
      is distinct from release_row.validation_contract_version then
    raise exception using errcode = '23514', message = 'Exact Module release is incompatible';
  end if;
  record_types := release_row.compilation_output #> '{canonical,content,recordTypes}';
  if pg_catalog.jsonb_typeof(record_types) <> 'array' then
    raise exception using errcode = '23514', message = 'Module record storage definition is incompatible';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(record_types) as item(value)
    where item.value ->> 'storageContractId' is null
      or item.value ->> 'recordTypeId' is null
  ) or (
    select pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'storageContractId')
      or pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'recordTypeId')
    from pg_catalog.jsonb_array_elements(record_types) as item(value)
  ) then
    raise exception using errcode = '23514', message = 'Module record storage identities are duplicated';
  end if;

  for record_type in
    select item.value
    from pg_catalog.jsonb_array_elements(record_types) as item(value)
    order by item.value ->> 'storageContractId'
  loop
    begin
      storage_id := (record_type ->> 'storageContractId')::uuid;
      record_type_id_value := (record_type ->> 'recordTypeId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '42501', message = 'Module record storage identity is invalid';
    end;
    storage_scope_value := record_type ->> 'storageScope';
    ownership_mode_value := record_type ->> 'ownershipMode';
    if not vortex_context.is_non_nil_uuid(storage_id::text)
      or not vortex_context.is_non_nil_uuid(record_type_id_value::text)
      or storage_scope_value not in ('organization_shared', 'application_contained')
      or ownership_mode_value not in ('none', 'organization_account', 'group', 'inherited')
      or pg_catalog.jsonb_typeof(record_type -> 'fields') <> 'array'
      or pg_catalog.jsonb_array_length(record_type -> 'fields') < 1
      or pg_catalog.jsonb_typeof(record_type -> 'relationships') <> 'array' then
      raise exception using errcode = '42501', message = 'Module record storage definition is invalid';
    end if;

    preview_storage_id := pg_catalog.gen_random_uuid();
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('vortex_record.storage:' || preview_storage_id::text, 0)
    );
    table_token := 'rt_' || pg_catalog.replace(pg_catalog.lower(preview_storage_id::text), '-', '');
    preview_record_type := pg_catalog.jsonb_set(
      record_type,
      '{storageContractId}',
      pg_catalog.to_jsonb(preview_storage_id::text),
      true
    );
    shape_fingerprint := vortex_record.storage_meaning_fingerprint(preview_record_type);

    perform vortex_record.create_record_storage_table_internal(
      preview_storage_id, p_module_root_id, record_type_id_value,
      storage_scope_value, ownership_mode_value
    );
    insert into vortex_record.storage_catalogue (
      storage_contract_id, physical_schema_token, physical_table_token,
      module_root_id, record_type_id, storage_scope,
      first_compatible_release_revision, last_compatible_release_revision,
      state, content_fingerprint, record_type_definition, protected_read_model_key
    ) values (
      preview_storage_id, 'record_data', table_token,
      p_module_root_id, record_type_id_value, storage_scope_value,
      p_module_release_revision, p_module_release_revision,
      'active', shape_fingerprint, preview_record_type, null
    );

    for field_value in
      select item.value
      from pg_catalog.jsonb_array_elements(record_type -> 'fields') as item(value)
      order by item.value ->> 'fieldId'
    loop
      begin
        field_id_value := (field_value ->> 'fieldId')::uuid;
      exception when invalid_text_representation then
        raise exception using errcode = '42501', message = 'Record field storage identity is invalid';
      end;
      if not vortex_context.is_non_nil_uuid(field_id_value::text)
        or field_value ->> 'type' is null
        or pg_catalog.jsonb_typeof(field_value -> 'required') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'unique') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'filterable') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'sortable') <> 'boolean'
        or pg_catalog.jsonb_typeof(field_value -> 'settings') <> 'object' then
        raise exception using errcode = '42501', message = 'Record field storage definition is invalid';
      end if;
      column_token := 'f_' || pg_catalog.replace(pg_catalog.lower(field_id_value::text), '-', '');
      database_type := vortex_record.database_value_type(field_value);
      if database_type is null then
        raise exception using errcode = '23514', message = 'Record field storage type is unsupported';
      end if;
      sql_type := vortex_record.sql_value_type(database_type);
      execute pg_catalog.format(
        'alter table record_data.%I add column %I %s%s',
        table_token, column_token, sql_type,
        case when (field_value ->> 'required')::boolean then ' not null' else '' end
      );
      insert into vortex_record.field_storage_mappings (
        storage_contract_id, field_id, physical_column_token, database_value_type,
        field_definition, introduced_by_module_root_id, introduced_at_release_revision, state
      ) values (
        preview_storage_id, field_id_value, column_token, database_type, field_value,
        p_module_root_id, p_module_release_revision, 'active'
      );
      if not (record_type ? 'systemProjection')
        and (field_value ->> 'unique')::boolean then
        scope_index_columns := case storage_scope_value
          when 'organization_shared' then 'organisation_id'
          else 'organisation_id, application_root_id'
        end;
        index_token := 'pux_' || pg_catalog.md5(
          preview_storage_id::text || ':' || field_id_value::text
        );
        execute pg_catalog.format(
          'create unique index %I on record_data.%I (%s, %I) where lifecycle_state in (''active'', ''soft_deleted'', ''removal_pending'')',
          index_token, table_token, scope_index_columns, column_token
        );
      end if;
    end loop;

    insert into vortex_record.preview_storage_bindings (
      preview_installation_id, storage_contract_id, module_root_id,
      module_release_revision, record_type_id, release_storage_contract_id
    ) values (
      p_preview_installation_id, preview_storage_id, p_module_root_id,
      p_module_release_revision, record_type_id_value, storage_id
    );
    storage_identities := storage_identities || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'moduleRootId', p_module_root_id,
        'moduleReleaseRevision', p_module_release_revision,
        'recordTypeId', record_type_id_value,
        'releaseStorageContractId', storage_id,
        'previewStorageContractId', preview_storage_id
      )
    );
  end loop;
  return storage_identities;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Exact Module release is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Exact Module release is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.provision_preview_module_storage(p_preview_installation_id uuid, p_module_root_id uuid, p_module_release_revision bigint) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION provision_preview_module_storage(p_preview_installation_id uuid, p_module_root_id uuid, p_module_release_revision bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.provision_preview_module_storage(p_preview_installation_id uuid, p_module_root_id uuid, p_module_release_revision bigint) IS 'Creates fresh empty Record storage for every record type in one exact published Module release, without provisioning its live release identities.';


--
-- Name: read_application_index_status(uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.read_application_index_status(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  authority jsonb;
  target_storage_contract_ids uuid[];
  target record;
  mapping record;
  purpose text;
  scope_columns text;
  index_token text;
  definition_fingerprint text;
  observed text;
  catalogue_row vortex_record.index_catalogue%rowtype;
  index_state text;
  ready boolean;
  lease_active boolean;
  conflict_outcome jsonb;
  conflict_value jsonb;
  target_count integer := 0;
  index_count integer := 0;
  ready_count integer := 0;
  pending_count integer := 0;
  running_count integer := 0;
  interrupted_count integer := 0;
  conflicting_count integer := 0;
  indexes jsonb := '[]'::jsonb;
  uniqueness_ready boolean := true;
begin
  if p_organization_id is null
    or p_organization_id = nil_uuid
    or p_application_root_id is null
    or p_application_root_id = nil_uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Index status command is invalid';
  end if;

  authority := vortex_record.authorize_index_status_internal(
    p_organization_id, p_application_root_id
  );

  -- The same protected active-installation target fact `read_index_readiness`
  -- uses; the organisation is re-derived from the validated request context
  -- inside it and the supplied value must match it.
  select pg_catalog.array_agg(distinct targets.storage_contract_id)
    into target_storage_contract_ids
  from vortex_module.read_lifecycle_activation_targets_internal(
    p_organization_id, p_application_root_id, p_application_release_revision,
    p_expected_module_bindings
  ) as targets;

  if target_storage_contract_ids is null
    or pg_catalog.cardinality(target_storage_contract_ids) = 0 then
    raise exception using errcode = '23514',
      message = 'Index status activation targets are incomplete';
  end if;

  for target in
    select catalogue.storage_contract_id, catalogue.storage_scope,
      catalogue.physical_table_token, catalogue.record_type_id
    from vortex_record.storage_catalogue as catalogue
    where catalogue.storage_contract_id = any (target_storage_contract_ids)
      and catalogue.state = 'active'
    order by catalogue.storage_contract_id
  loop
    target_count := target_count + 1;

    for mapping in
      select stored.field_id, stored.physical_column_token, stored.field_definition
      from vortex_record.field_storage_mappings as stored
      where stored.storage_contract_id = target.storage_contract_id
        and stored.state = 'active'
        and (
          coalesce((stored.field_definition ->> 'unique')::boolean, false)
          or coalesce((stored.field_definition ->> 'filterable')::boolean, false)
          or coalesce((stored.field_definition ->> 'sortable')::boolean, false)
        )
      order by stored.field_id
    loop
      index_count := index_count + 1;

      purpose := case
        when coalesce((mapping.field_definition ->> 'unique')::boolean, false)
          then 'uniqueness'
        else 'performance'
      end;
      scope_columns := vortex_record.index_scope_columns(target.storage_scope);
      index_token := case purpose when 'uniqueness' then 'ux_' else 'ix_' end
        || pg_catalog.substr(mapping.physical_column_token, 3);
      definition_fingerprint := vortex_record.index_definition_fingerprint(
        purpose, target.physical_table_token, scope_columns, mapping.physical_column_token
      );
      observed := vortex_record.observe_field_index_internal(
        purpose, target.physical_table_token, scope_columns, mapping.physical_column_token
      );

      select stored_index.* into catalogue_row
      from vortex_record.index_catalogue as stored_index
      where stored_index.storage_contract_id = target.storage_contract_id
        and stored_index.field_id = mapping.field_id
      for share;

      ready := observed = 'present'
        and catalogue_row.index_contract_id is not null
        and catalogue_row.purpose = purpose
        and catalogue_row.physical_index_token = index_token
        and catalogue_row.desired_definition_fingerprint = definition_fingerprint;

      -- A lease that has not expired is an active build. An expired lease or
      -- an invalid physical index is an interrupted build awaiting a later
      -- claim. Neither is ever projected as ready.
      lease_active := catalogue_row.index_contract_id is not null
        and catalogue_row.claim_id is not null
        and catalogue_row.lease_expires_at > pg_catalog.statement_timestamp();

      -- Only a uniqueness index that is neither ready nor actively building
      -- can be blocked by its own data. The conflict search is only attempted
      -- then, and its exact outcome decides the state.
      conflict_outcome := null;
      conflict_value := null;
      if not ready and not lease_active and purpose = 'uniqueness' then
        conflict_outcome := vortex_record.read_index_conflict_references_internal(
          target.record_type_id, target.physical_table_token, scope_columns,
          mapping.physical_column_token
        );
      end if;

      if ready then
        index_state := 'ready';
        ready_count := ready_count + 1;
      elsif lease_active then
        index_state := 'running';
        running_count := running_count + 1;
      elsif conflict_outcome is not null and conflict_outcome ->> 'outcome' <> 'none' then
        index_state := 'conflicting';
        conflicting_count := conflicting_count + 1;
        conflict_value := case conflict_outcome ->> 'outcome'
          when 'unreadable' then pg_catalog.jsonb_build_object('state', 'unreadable')
          else pg_catalog.jsonb_build_object(
            'state', 'readable',
            'records', coalesce(conflict_outcome -> 'records', '[]'::jsonb)
          )
        end;
      elsif observed = 'invalid' or catalogue_row.claim_id is not null then
        index_state := 'interrupted';
        interrupted_count := interrupted_count + 1;
      else
        index_state := 'pending';
        pending_count := pending_count + 1;
      end if;

      if purpose = 'uniqueness' and not ready then
        uniqueness_ready := false;
      end if;

      indexes := indexes || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'indexContractId', coalesce(
          catalogue_row.index_contract_id,
          vortex_record.index_contract_identity(
            target.storage_contract_id, mapping.field_id
          )
        ),
        'storageContractId', target.storage_contract_id,
        'fieldId', mapping.field_id,
        'purpose', purpose,
        'desiredDefinitionFingerprint', definition_fingerprint,
        'state', index_state,
        'observedState', observed,
        'recordedObservedState', catalogue_row.observed_state,
        'observedRevision', catalogue_row.observed_revision,
        'ready', ready,
        'failureCode', case index_state
          when 'interrupted' then 'build_interrupted'
          when 'conflicting' then 'uniqueness_conflict'
          else null
        end,
        'conflict', conflict_value
      ));
    end loop;
  end loop;

  -- Every installation storage contract must be an active catalogue entry; a
  -- target this read cannot account for is an incomplete installation, never
  -- an implicitly unindexed record type.
  if target_count <> pg_catalog.cardinality(target_storage_contract_ids) then
    raise exception using errcode = '23514',
      message = 'Index status activation targets are incomplete';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', authority ->> 'organizationId',
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'indexes', indexes,
    'progress', pg_catalog.jsonb_build_object(
      'total', index_count,
      'ready', ready_count,
      'pending', pending_count,
      'running', running_count,
      'interrupted', interrupted_count,
      'conflicting', conflicting_count
    ),
    'uniquenessReady', uniqueness_ready,
    'performanceAdvisory', true
  );
end
$$;


ALTER FUNCTION vortex_record.read_application_index_status(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION read_application_index_status(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.read_application_index_status(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Protected live status of every exact field index one active Application installation owns: pending, running, ready, interrupted or conflicting, with bounded progress and no physical detail.';


--
-- Name: read_application_lifecycle_policy_readiness(uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.read_application_lifecycle_policy_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target record;
  policy_row vortex_record.record_type_lifecycle_policies%rowtype;
  limits_row vortex_record.organization_lifecycle_limits%rowtype;
  target_storage_contract_ids uuid[];
  target_count integer := 0;
  policies jsonb := '[]'::jsonb;
  workflows jsonb := '[]'::jsonb;
  connections jsonb := '[]'::jsonb;
  connection_readiness jsonb;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Lifecycle activation readiness command is invalid';
  end if;

  -- One read of the installation targets, de-duplicated once, so the
  -- completeness check below cannot disagree with the policies collected.
  select pg_catalog.array_agg(distinct targets.storage_contract_id)
    into target_storage_contract_ids
  from vortex_module.read_lifecycle_activation_targets_internal(
    p_organization_id, p_application_root_id, p_application_release_revision,
    p_expected_module_bindings
  ) as targets;

  if target_storage_contract_ids is null
    or pg_catalog.cardinality(target_storage_contract_ids) = 0 then
    raise exception using errcode = '23514',
      message = 'Lifecycle activation targets are incomplete';
  end if;

  for target in
    select catalogue.storage_contract_id, catalogue.storage_scope
    from vortex_record.storage_catalogue as catalogue
    where catalogue.storage_contract_id = any (target_storage_contract_ids)
      and catalogue.state = 'active'
    order by catalogue.storage_contract_id
  loop
    target_count := target_count + 1;

    select stored.* into policy_row
    from vortex_record.record_type_lifecycle_policies as stored
    where stored.organization_id = p_organization_id
      and stored.storage_contract_id = target.storage_contract_id
      and stored.application_root_id is not distinct from case
        when target.storage_scope = 'application_contained' then p_application_root_id
        else null
      end
    for share;
    if not found then
      raise exception using errcode = '23514',
        message = 'Record-type lifecycle policy is unavailable';
    end if;
    policies := policies || pg_catalog.jsonb_build_array(policy_row.policy_body);

    if policy_row.action = 'archive_workflow' then
      -- An archive policy always carries a permanent Application scope; #566
      -- refuses to store an organisation-shared one.
      if policy_row.application_root_id is distinct from p_application_root_id then
        raise exception using errcode = '23514',
          message = 'Record-type lifecycle archive policy scope is unavailable';
      end if;

      if not vortex_module.record_lifecycle_workflow_is_installed_internal(
        p_organization_id,
        p_application_root_id,
        target.storage_contract_id,
        (policy_row.policy_body ->> 'archiveWorkflowId')::uuid,
        (policy_row.policy_body #>> '{expectedWorkflowRevision}')::bigint
      ) then
        raise exception using errcode = '23514',
          message = 'Record-type lifecycle archive workflow is unavailable';
      end if;

      connection_readiness := vortex_connection.resolve_connection_instance_readiness(
        p_organization_id,
        p_application_root_id,
        (policy_row.policy_body ->> 'archiveConnectionInstanceId')::uuid,
        policy_row.policy_body ->> 'archiveDestination',
        (policy_row.policy_body #>> '{expectedConnectionRevision}')::bigint,
        policy_row.policy_body ->> 'expectedDestinationFingerprint'
      );
      -- Every returned fact is checked against the stored policy, exactly as
      -- the #566 save does: a 'ready' outcome alone is not evidence that the
      -- readiness answers the policy this activation is gating on.
      if connection_readiness ->> 'outcome' is distinct from 'ready'
        or pg_catalog.lower(connection_readiness ->> 'connectionInstanceId')
          is distinct from pg_catalog.lower(
            policy_row.policy_body ->> 'archiveConnectionInstanceId')
        or connection_readiness ->> 'organizationId' is distinct from p_organization_id::text
        or connection_readiness ->> 'applicationRootId'
          is distinct from p_application_root_id::text
        or connection_readiness ->> 'destinationKey'
          is distinct from policy_row.policy_body ->> 'archiveDestination'
        or connection_readiness ->> 'destinationFingerprint'
          is distinct from policy_row.policy_body ->> 'expectedDestinationFingerprint'
        or connection_readiness ->> 'revision'
          is distinct from policy_row.policy_body #>> '{expectedConnectionRevision}'
        or connection_readiness ->> 'healthOutcome' is distinct from 'healthy'
        or connection_readiness ->> 'state' is distinct from 'active' then
        raise exception using errcode = '23514',
          message = 'Record-type lifecycle archive connection is unavailable';
      end if;

      workflows := workflows || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'workflowId', policy_row.policy_body ->> 'archiveWorkflowId',
        'workflowRevision',
          (policy_row.policy_body #>> '{expectedWorkflowRevision}')::bigint,
        'organizationId', p_organization_id,
        'authorizedApplicationIds', pg_catalog.jsonb_build_array(p_application_root_id),
        'state', 'active'
      ));
      connections := connections || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'connectionInstanceId', connection_readiness ->> 'connectionInstanceId',
        'destinationKey', connection_readiness ->> 'destinationKey',
        'destinationFingerprint', connection_readiness ->> 'destinationFingerprint',
        'organizationId', p_organization_id,
        'authorizedApplicationIds', pg_catalog.jsonb_build_array(p_application_root_id),
        'state', connection_readiness ->> 'state',
        'revision', (connection_readiness ->> 'revision')::bigint,
        'lastHealthOutcome', connection_readiness ->> 'healthOutcome',
        'verifiedAt', connection_readiness -> 'verifiedAt'
      ));
    end if;
  end loop;

  -- Every installed storage contract must be an active catalogue entry with a
  -- policy. A target this read cannot account for is an incomplete
  -- installation, never an implicitly unmanaged record type.
  if target_count <> pg_catalog.cardinality(target_storage_contract_ids) then
    raise exception using errcode = '23514',
      message = 'Lifecycle activation targets are incomplete';
  end if;

  select limits.* into limits_row
  from vortex_record.organization_lifecycle_limits as limits
  where limits.organization_id = p_organization_id
  for share;
  if not found then
    raise exception using errcode = '23514',
      message = 'Organisation lifecycle limits are unavailable';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', p_organization_id,
    'applicationRootId', p_application_root_id,
    'policies', policies,
    'organizationLimits', pg_catalog.jsonb_build_object(
      'organizationId', limits_row.organization_id,
      'settingsRevision', limits_row.settings_revision,
      'maxRetentionDays', limits_row.max_retention_days,
      'maxRecordCount', limits_row.max_record_count,
      'allowUnlimitedRetentionDays', limits_row.allow_unlimited_retention_days,
      'allowUnlimitedRecordCount', limits_row.allow_unlimited_record_count,
      'allowedActions', pg_catalog.to_jsonb(limits_row.allowed_actions),
      'allowedArchiveDestinations', pg_catalog.to_jsonb(limits_row.allowed_archive_destinations)
    ),
    'readinessEvidence', pg_catalog.jsonb_build_object(
      'organizationId', p_organization_id,
      'registeredWorkflows', workflows,
      'activeConnections', connections
    )
  );
end
$$;


ALTER FUNCTION vortex_record.read_application_lifecycle_policy_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION read_application_lifecycle_policy_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.read_application_lifecycle_policy_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Complete executable-policy snapshot for one activating Application installation: every owned record type''s current policy, the organisation ceilings and the live archive readiness those policies name.';


--
-- Name: read_current_legal_holds(jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.read_current_legal_holds(p_candidate jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  context_tenant_id uuid;
  context_organization_id uuid;
  context_application_root_id uuid;
  candidate_kind text;
  candidate_tenant_id uuid;
  candidate_organization_id uuid;
  candidate_application_root_id uuid;
  candidate_application_known boolean := false;
  candidate_record_type_id uuid;
  candidate_record_id uuid;
  candidate_file_id uuid;
  candidate_owner_record_type_id uuid;
  candidate_owner_record_id uuid;
  allowed_keys text[];
  required_keys text[];
  hold_values jsonb;
begin
  begin
    context_value := vortex_context.validated_service_context();
  exception
    when insufficient_privilege
      or foreign_key_violation
      or object_not_in_prerequisite_state
      or invalid_text_representation then
      return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end;

  if context_value is null
    or pg_catalog.jsonb_typeof(context_value) is distinct from 'object'
    or context_value ->> 'callerKind' is null
    or context_value ->> 'callerKind' not in ('human', 'system')
    or not vortex_context.is_non_nil_uuid(context_value ->> 'tenantId')
    or not vortex_context.is_non_nil_uuid(context_value ->> 'organizationId') then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  context_tenant_id := (context_value ->> 'tenantId')::uuid;
  context_organization_id := (context_value ->> 'organizationId')::uuid;

  if p_candidate is null
    or pg_catalog.jsonb_typeof(p_candidate) is distinct from 'object'
    or not (p_candidate ?& array['kind', 'tenantId', 'organizationId']) then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  candidate_kind := p_candidate ->> 'kind';
  if candidate_kind = 'record' then
    allowed_keys := array[
      'kind', 'tenantId', 'organizationId', 'applicationRootId', 'recordTypeId', 'recordId'
    ];
    required_keys := array['kind', 'tenantId', 'organizationId', 'recordTypeId', 'recordId'];
  elsif candidate_kind = 'file' then
    allowed_keys := array[
      'kind', 'tenantId', 'organizationId', 'applicationRootId', 'fileId',
      'ownerRecordTypeId', 'ownerRecordId'
    ];
    required_keys := array['kind', 'tenantId', 'organizationId', 'fileId'];
  else
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  if not (p_candidate ?& required_keys)
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(p_candidate) as candidate_key(key)
      where not (candidate_key.key = any (allowed_keys))
    )
    or not vortex_context.is_non_nil_uuid(p_candidate ->> 'tenantId')
    or not vortex_context.is_non_nil_uuid(p_candidate ->> 'organizationId') then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  candidate_tenant_id := (p_candidate ->> 'tenantId')::uuid;
  candidate_organization_id := (p_candidate ->> 'organizationId')::uuid;
  if candidate_tenant_id <> context_tenant_id
    or candidate_organization_id <> context_organization_id then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  if p_candidate ? 'applicationRootId' then
    if pg_catalog.jsonb_typeof(p_candidate -> 'applicationRootId') = 'null'
      and candidate_kind = 'record' then
      candidate_application_known := true;
    elsif vortex_context.is_non_nil_uuid(p_candidate ->> 'applicationRootId') then
      candidate_application_root_id := (p_candidate ->> 'applicationRootId')::uuid;
      candidate_application_known := true;
      if not vortex_context.is_non_nil_uuid(context_value ->> 'applicationRootId') then
        return pg_catalog.jsonb_build_object('outcome', 'unavailable');
      end if;
      context_application_root_id := (context_value ->> 'applicationRootId')::uuid;
      if candidate_application_root_id <> context_application_root_id then
        return pg_catalog.jsonb_build_object('outcome', 'unavailable');
      end if;
    else
      return pg_catalog.jsonb_build_object('outcome', 'unavailable');
    end if;
  end if;

  if candidate_kind = 'record' then
    if not vortex_context.is_non_nil_uuid(p_candidate ->> 'recordTypeId')
      or not vortex_context.is_non_nil_uuid(p_candidate ->> 'recordId') then
      return pg_catalog.jsonb_build_object('outcome', 'unavailable');
    end if;
    candidate_record_type_id := (p_candidate ->> 'recordTypeId')::uuid;
    candidate_record_id := (p_candidate ->> 'recordId')::uuid;
  else
    if not vortex_context.is_non_nil_uuid(p_candidate ->> 'fileId') then
      return pg_catalog.jsonb_build_object('outcome', 'unavailable');
    end if;
    candidate_file_id := (p_candidate ->> 'fileId')::uuid;

    if p_candidate ? 'ownerRecordTypeId' or p_candidate ? 'ownerRecordId' then
      if not (p_candidate ?& array['ownerRecordTypeId', 'ownerRecordId'])
        or not vortex_context.is_non_nil_uuid(p_candidate ->> 'ownerRecordTypeId')
        or not vortex_context.is_non_nil_uuid(p_candidate ->> 'ownerRecordId') then
        return pg_catalog.jsonb_build_object('outcome', 'unavailable');
      end if;
      candidate_owner_record_type_id := (p_candidate ->> 'ownerRecordTypeId')::uuid;
      candidate_owner_record_id := (p_candidate ->> 'ownerRecordId')::uuid;
      candidate_record_type_id := candidate_owner_record_type_id;
      candidate_record_id := candidate_owner_record_id;
    end if;
  end if;

  if exists (
    select 1
    from (
      select
        hold_id,
        pg_catalog.count(*)::bigint as version_count,
        pg_catalog.min(hold_revision) as first_revision,
        pg_catalog.max(hold_revision) as current_revision
      from vortex_record.legal_hold_versions
      where tenant_id = context_tenant_id
        and organization_id = context_organization_id
      group by hold_id
    ) as history
    where history.first_revision <> 1
      or history.version_count <> history.current_revision
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  if exists (
    select 1
    from (
      select
        version.*,
        pg_catalog.lag(hold_revision) over hold_history as previous_hold_revision,
        pg_catalog.lag(scope_revision) over hold_history as previous_scope_revision,
        pg_catalog.lag(scope_kind) over hold_history as previous_scope_kind,
        pg_catalog.lag(application_root_id) over hold_history as previous_application_root_id,
        pg_catalog.lag(record_type_id) over hold_history as previous_record_type_id,
        pg_catalog.lag(record_id) over hold_history as previous_record_id,
        pg_catalog.lag(file_id) over hold_history as previous_file_id,
        pg_catalog.lag(status) over hold_history as previous_status,
        pg_catalog.lag(release_decision_id) over hold_history as previous_release_decision_id,
        pg_catalog.lag(release_reason) over hold_history as previous_release_reason,
        pg_catalog.lag(released_by_kind) over hold_history as previous_released_by_kind,
        pg_catalog.lag(released_by_id) over hold_history as previous_released_by_id,
        pg_catalog.lag(released_at) over hold_history as previous_released_at
      from vortex_record.legal_hold_versions as version
      where tenant_id = context_tenant_id
        and organization_id = context_organization_id
      window hold_history as (partition by hold_id order by hold_revision)
    ) as lineage
    where lineage.previous_hold_revision is not null
      and (
        lineage.hold_revision <> lineage.previous_hold_revision + 1
        or (
          (
            lineage.scope_kind is distinct from lineage.previous_scope_kind
            or lineage.application_root_id is distinct from lineage.previous_application_root_id
            or lineage.record_type_id is distinct from lineage.previous_record_type_id
            or lineage.record_id is distinct from lineage.previous_record_id
            or lineage.file_id is distinct from lineage.previous_file_id
          )
          and lineage.scope_revision <> lineage.previous_scope_revision + 1
        )
        or (
          lineage.scope_kind is not distinct from lineage.previous_scope_kind
          and lineage.application_root_id is not distinct from lineage.previous_application_root_id
          and lineage.record_type_id is not distinct from lineage.previous_record_type_id
          and lineage.record_id is not distinct from lineage.previous_record_id
          and lineage.file_id is not distinct from lineage.previous_file_id
          and lineage.scope_revision <> lineage.previous_scope_revision
        )
        or (
          lineage.previous_status = 'released'
          and (
            lineage.status is distinct from 'released'
            or lineage.release_decision_id is distinct from lineage.previous_release_decision_id
            or lineage.release_reason is distinct from lineage.previous_release_reason
            or lineage.released_by_kind is distinct from lineage.previous_released_by_kind
            or lineage.released_by_id is distinct from lineage.previous_released_by_id
            or lineage.released_at is distinct from lineage.previous_released_at
          )
        )
      )
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  if (
    not candidate_application_known
    or (
      candidate_kind = 'file'
      and candidate_record_type_id is null
    )
  ) and exists (
    with current_revision as (
      select hold_id, pg_catalog.max(hold_revision) as hold_revision
      from vortex_record.legal_hold_versions
      where tenant_id = context_tenant_id
        and organization_id = context_organization_id
      group by hold_id
    )
    select 1
    from vortex_record.legal_hold_versions as current
    join current_revision
      on current_revision.hold_id = current.hold_id
      and current_revision.hold_revision = current.hold_revision
    where current.tenant_id = context_tenant_id
      and current.organization_id = context_organization_id
      and (
        (not candidate_application_known and current.scope_kind = 'application')
        or (
          candidate_kind = 'file'
          and candidate_record_type_id is null
          and current.scope_kind in ('record_type', 'record')
        )
      )
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
  end if;

  with current_revision as (
    select hold_id, pg_catalog.max(hold_revision) as hold_revision
    from vortex_record.legal_hold_versions
    where tenant_id = context_tenant_id
      and organization_id = context_organization_id
    group by hold_id
  ),
  current_version as (
    select version.*
    from vortex_record.legal_hold_versions as version
    join current_revision as current
      on current.hold_id = version.hold_id
      and current.hold_revision = version.hold_revision
    where version.tenant_id = context_tenant_id
      and version.organization_id = context_organization_id
  )
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'tenantId', current.tenant_id,
        'holdId', current.hold_id,
        'organizationId', current.organization_id,
        'scope',
          case current.scope_kind
            when 'all_organization_data' then
              pg_catalog.jsonb_build_object('kind', current.scope_kind)
            when 'application' then
              pg_catalog.jsonb_build_object(
                'kind', current.scope_kind,
                'applicationRootId', current.application_root_id
              )
            when 'record_type' then
              pg_catalog.jsonb_build_object(
                'kind', current.scope_kind,
                'recordTypeId', current.record_type_id
              )
            when 'record' then
              pg_catalog.jsonb_build_object(
                'kind', current.scope_kind,
                'recordTypeId', current.record_type_id,
                'recordId', current.record_id
              )
            when 'file' then
              pg_catalog.jsonb_build_object(
                'kind', current.scope_kind,
                'fileId', current.file_id
              )
          end,
        'status', current.status,
        'holdRevision', current.hold_revision,
        'scopeRevision', current.scope_revision
      )
      order by current.hold_id
    ),
    '[]'::jsonb
  )
  into hold_values
  from current_version as current
  where current.scope_kind = 'all_organization_data'
    or (
      current.scope_kind = 'application'
      and candidate_application_known
      and candidate_application_root_id is not null
      and current.application_root_id = candidate_application_root_id
    )
    or (
      current.scope_kind = 'record_type'
      and candidate_record_type_id is not null
      and current.record_type_id = candidate_record_type_id
    )
    or (
      current.scope_kind = 'record'
      and candidate_record_type_id is not null
      and candidate_record_id is not null
      and current.record_type_id = candidate_record_type_id
      and current.record_id = candidate_record_id
    )
    or (
      current.scope_kind = 'file'
      and candidate_kind = 'file'
      and current.file_id = candidate_file_id
    );

  return pg_catalog.jsonb_build_object(
    'outcome', 'complete',
    'holds', hold_values
  );
exception
  when others then
    return pg_catalog.jsonb_build_object('outcome', 'unavailable');
end
$function$;


ALTER FUNCTION vortex_record.read_current_legal_holds(p_candidate jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION read_current_legal_holds(p_candidate jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.read_current_legal_holds(p_candidate jsonb) IS 'Returns only current versioned legal-hold references relevant to one candidate in validated protected scope.';


--
-- Name: read_current_preview_installation_internal(); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_current_preview_installation_internal()
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  address_value text;
  preview_value jsonb;
begin
  address_value := nullif(
    pg_catalog.current_setting('vortex_record.preview_installation_id', true), ''
  );
  if address_value is null then
    return null;
  end if;
  if not pg_catalog.pg_input_is_valid(address_value, 'uuid') then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  preview_value := vortex_module.read_preview_record_installation_internal(
    address_value::uuid
  );
  if preview_value is null then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  return preview_value;
end
$function$;


ALTER FUNCTION vortex_record.read_current_preview_installation_internal() OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_current_preview_installation_internal(); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_current_preview_installation_internal() IS 'Resolves the transaction-local preview address only after the module ledger validates the same human identity, organisation account and Application context and confirms the preview is unexpired.';


--
-- Name: read_derived_field_ids_for_exact_record_internal(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.read_derived_field_ids_for_exact_record_internal(p_record_type_id uuid, p_record_id uuid, p_required_field_ids jsonb, p_seen_derived_field_keys jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  loaded jsonb;
  decision jsonb;
  bounds jsonb;
begin
  if p_record_type_id is null or p_record_id is null
    or pg_catalog.jsonb_typeof(p_required_field_ids) <> 'array'
    or pg_catalog.jsonb_typeof(p_seen_derived_field_keys) <> 'array' then
    return null;
  end if;
  loaded := vortex_record.load_record_access_facts_internal(p_record_type_id, 'read', p_record_id, null);
  if loaded ->> 'outcome' <> 'loaded' or pg_catalog.jsonb_typeof(loaded -> 'declaration') <> 'object' then
    return null;
  end if;
  decision := vortex_access.evaluate_organization_record_access_internal(
    loaded -> 'declaration', p_record_id, loaded -> 'facts'
  );
  if decision ->> 'outcome' <> 'allowed' then
    return null;
  end if;
  bounds := vortex_access.resolve_record_field_bounds_internal(decision);
  return vortex_record.project_derived_readable_field_ids_internal(
    loaded, p_record_type_id, p_record_id, bounds -> 'readableFieldIds',
    p_required_field_ids, p_seen_derived_field_keys
  );
end
$$;


ALTER FUNCTION vortex_record.read_derived_field_ids_for_exact_record_internal(p_record_type_id uuid, p_record_id uuid, p_required_field_ids jsonb, p_seen_derived_field_keys jsonb) OWNER TO vortex_record_adapter;

--
-- Name: read_exact_module_storage_provision(uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.read_exact_module_storage_provision(
  p_module_root_id uuid,
  p_module_release_revision bigint
)
returns table (
  module_root_id uuid,
  release_revision bigint,
  storage_contract_ids uuid[]
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Exact Module storage provision input is invalid';
  end if;

  return query
  select provision.module_root_id, provision.release_revision,
    provision.storage_contract_ids
  from vortex_record.release_provisions as provision
  where provision.module_root_id = p_module_root_id
    and provision.release_revision = p_module_release_revision;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Exact Module storage provision evidence is unavailable';
  end if;
end
$function$;


ALTER FUNCTION vortex_record.read_exact_module_storage_provision(p_module_root_id uuid, p_module_release_revision bigint) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION read_exact_module_storage_provision(p_module_root_id uuid, p_module_release_revision bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.read_exact_module_storage_provision(p_module_root_id uuid, p_module_release_revision bigint) IS 'Record-owned read of one exact immutable Module release provision for installation activation.';


--
-- Name: read_import_update_targets(uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_import_update_targets(
  p_record_type_id uuid,
  p_mapped_field_ids jsonb,
  p_targets jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  uuid_pattern constant text := '^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|ffffffff-ffff-ffff-ffff-ffffffffffff)$';
  context_initial jsonb;
  context_final jsonb;
  installation_initial jsonb;
  installation_final jsonb;
  meta_initial jsonb;
  meta_final jsonb;
  record_type_value jsonb;
  mapped_ids uuid[] := array[]::uuid[];
  mapped_ids_value jsonb := '[]'::jsonb;
  target_results jsonb := '[]'::jsonb;
  target_item record;
  target_value jsonb;
  row_number_value bigint;
  row_number_values bigint[] := array[]::bigint[];
  record_id_candidate text;
  target_record_id uuid;
  initial_read jsonb;
  initial_capabilities jsonb;
  final_read jsonb;
  final_capabilities jsonb;
  row_values jsonb;
  field_id_value uuid;
  field_type_value text;
  field_matches integer;
  binding_matches integer;
  key_count integer;
  action_value text;
  action_values text[];
  capability_field_value text;
  capability_field_id uuid;
  capability_field_ids uuid[];
  projection_field_value text;
  projection_field_id uuid;
  projection_field_ids uuid[];
  mapped_field_id uuid;
  mapped_fields_available boolean;
  row_result jsonb;
  result_value jsonb;
  issued_at_value timestamptz;
  valid_until_value timestamptz;
  now_value timestamptz;
begin
  if p_record_type_id is null or p_record_type_id = nil_uuid
    or pg_catalog.jsonb_typeof(p_mapped_field_ids) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_mapped_field_ids) < 1
    or pg_catalog.jsonb_array_length(p_mapped_field_ids) > 500
    or pg_catalog.jsonb_typeof(p_targets) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_targets) < 1
    or pg_catalog.jsonb_array_length(p_targets) > 50 then
    raise exception using errcode = '22023', message = 'Import update target request is invalid';
  end if;

  for target_item in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(p_mapped_field_ids) with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    if pg_catalog.jsonb_typeof(target_item.value) is distinct from 'string'
      or (target_item.value #>> '{}') !~* uuid_pattern then
      raise exception using errcode = '22023', message = 'Import update target mapping is invalid';
    end if;
    begin
      field_id_value := (target_item.value #>> '{}')::uuid;
    exception when others then
      raise exception using errcode = '22023', message = 'Import update target mapping is invalid';
    end;
    if field_id_value = nil_uuid or field_id_value = any(mapped_ids) then
      raise exception using errcode = '22023', message = 'Import update target mapping is invalid';
    end if;
    mapped_ids := pg_catalog.array_append(mapped_ids, field_id_value);
    mapped_ids_value := mapped_ids_value || pg_catalog.jsonb_build_array(
      pg_catalog.to_jsonb(field_id_value::text)
    );
  end loop;

  context_initial := vortex_access.validated_human_request_context();
  if pg_catalog.jsonb_typeof(context_initial) is distinct from 'object'
    or context_initial ->> 'callerKind' is distinct from 'human'
    or not (context_initial ? 'applicationRootId')
    or context_initial ->> 'identityId' is null
    or context_initial ->> 'organizationAccountId' is null
    or context_initial ->> 'issuedAt' is null
    or context_initial ->> 'expiresAt' is null then
    raise exception using errcode = '42501', message = 'Import update targets require a human Application request';
  end if;

  issued_at_value := (context_initial ->> 'issuedAt')::timestamptz;
  valid_until_value := least(
    (context_initial ->> 'expiresAt')::timestamptz,
    issued_at_value + interval '30 seconds'
  );
  now_value := pg_catalog.clock_timestamp();
  if not pg_catalog.isfinite(issued_at_value)
    or not pg_catalog.isfinite(valid_until_value)
    or now_value >= valid_until_value then
    raise exception using errcode = '22023', message = 'Import update target request has expired';
  end if;

  installation_initial := vortex_module.read_current_active_installation();
  if pg_catalog.jsonb_typeof(installation_initial) is distinct from 'object'
    or (installation_initial ->> 'organizationId')::uuid
      is distinct from (context_initial ->> 'organizationId')::uuid
    or (installation_initial ->> 'applicationRootId')::uuid
      is distinct from (context_initial ->> 'applicationRootId')::uuid
    or pg_catalog.jsonb_typeof(installation_initial -> 'moduleBindings') is distinct from 'array' then
    raise exception using errcode = '55000', message = 'Active installation evidence is invalid';
  end if;

  meta_initial := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'read');
  if pg_catalog.jsonb_typeof(meta_initial) is distinct from 'object'
    or meta_initial ? 'previewInstallationId'
    or pg_catalog.jsonb_typeof(meta_initial -> 'recordType') is distinct from 'object'
    or pg_catalog.jsonb_typeof(meta_initial -> 'context') is distinct from 'object'
    or meta_initial -> 'context' is distinct from context_initial
    or pg_catalog.jsonb_typeof(meta_initial -> 'recordType' -> 'fields') is distinct from 'array'
    or meta_initial -> 'recordType' ? 'systemProjection' then
    raise exception using errcode = '55000', message = 'Installed Record metadata is unavailable';
  end if;

  record_type_value := meta_initial -> 'recordType';
  if (record_type_value ->> 'recordTypeId')::uuid is distinct from p_record_type_id
    or (record_type_value ->> 'storageContractId')::uuid
      is distinct from (meta_initial ->> 'storageContractId')::uuid
    or record_type_value ->> 'storageScope' is distinct from meta_initial ->> 'storageScope'
    or pg_catalog.jsonb_array_length(record_type_value -> 'fields') > 500
    or pg_catalog.octet_length(pg_catalog.convert_to(record_type_value::text, 'UTF8')) > 262144 then
    raise exception using errcode = '55000', message = 'Installed Record definition is invalid';
  end if;

  select pg_catalog.count(*) into binding_matches
  from pg_catalog.jsonb_array_elements(installation_initial -> 'moduleBindings') as binding(value)
  where (binding.value ->> 'organizationId')::uuid = (context_initial ->> 'organizationId')::uuid
    and (binding.value ->> 'applicationRootId')::uuid = (context_initial ->> 'applicationRootId')::uuid
    and (binding.value ->> 'applicationReleaseRevision')::bigint =
      (installation_initial ->> 'applicationReleaseRevision')::bigint
    and binding.value ->> 'state' = 'active'
    and (binding.value ->> 'moduleRootId')::uuid = (meta_initial ->> 'moduleRootId')::uuid
    and (binding.value ->> 'moduleReleaseRevision')::bigint =
      (meta_initial ->> 'moduleReleaseRevision')::bigint;
  if binding_matches <> 1 then
    raise exception using errcode = '55000', message = 'Installed Record Module binding is unavailable';
  end if;

  for target_item in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(p_mapped_field_ids) with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    field_id_value := (target_item.value #>> '{}')::uuid;
    select pg_catalog.count(*), pg_catalog.min(field.value ->> 'type')
    into field_matches, field_type_value
    from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as field(value)
    where (field.value ->> 'fieldId')::uuid = field_id_value;
    if field_matches <> 1
      or field_type_value in ('reference_number', 'calculation', 'total') then
      raise exception using errcode = '22023', message = 'Import update target mapping is unsupported';
    end if;
  end loop;

  -- Validate the complete target batch before any target UUID cast or Record lookup.
  for target_item in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(p_targets) with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    target_value := target_item.value;
    if pg_catalog.jsonb_typeof(target_value) is distinct from 'object' then
      raise exception using errcode = '22023', message = 'Import update target row is invalid';
    end if;
    select pg_catalog.count(*) into key_count
    from pg_catalog.jsonb_object_keys(target_value) as supplied(key);
    if key_count <> 2
      or not (target_value ?& array['rowNumber', 'recordIdCandidate'])
      or pg_catalog.jsonb_typeof(target_value -> 'rowNumber') is distinct from 'number'
      or (target_value ->> 'rowNumber') !~ '^[1-9][0-9]*$'
      or (target_value ->> 'rowNumber')::numeric > 9007199254740991
      or pg_catalog.jsonb_typeof(target_value -> 'recordIdCandidate') is distinct from 'string' then
      raise exception using errcode = '22023', message = 'Import update target row is invalid';
    end if;
    row_number_value := (target_value ->> 'rowNumber')::bigint;
    if row_number_value = any(row_number_values) then
      raise exception using errcode = '22023', message = 'Import update target rows are duplicated';
    end if;
    row_number_values := pg_catalog.array_append(row_number_values, row_number_value);
    record_id_candidate := target_value ->> 'recordIdCandidate';
    if pg_catalog.octet_length(pg_catalog.convert_to(record_id_candidate, 'UTF8')) > 256 then
      raise exception using errcode = '22023', message = 'Import update target identifier is too large';
    end if;
  end loop;
  row_number_values := array[]::bigint[];

  for target_item in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(p_targets) with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    target_value := target_item.value;
    if pg_catalog.jsonb_typeof(target_value) is distinct from 'object'
      or not (target_value ?& array['rowNumber', 'recordIdCandidate']) then
      raise exception using errcode = '22023', message = 'Import update target row is invalid';
    end if;
    select pg_catalog.count(*) into key_count
    from pg_catalog.jsonb_object_keys(target_value) as supplied(key);
    if key_count <> 2
      or pg_catalog.jsonb_typeof(target_value -> 'rowNumber') is distinct from 'number'
      or (target_value ->> 'rowNumber') !~ '^[1-9][0-9]*$'
      or (target_value ->> 'rowNumber')::numeric > 9007199254740991
      or pg_catalog.jsonb_typeof(target_value -> 'recordIdCandidate') is distinct from 'string' then
      raise exception using errcode = '22023', message = 'Import update target row is invalid';
    end if;
    row_number_value := (target_value ->> 'rowNumber')::bigint;
    if row_number_value = any(row_number_values) then
      raise exception using errcode = '22023', message = 'Import update target rows are duplicated';
    end if;
    row_number_values := pg_catalog.array_append(row_number_values, row_number_value);
    record_id_candidate := target_value ->> 'recordIdCandidate';
    if pg_catalog.octet_length(pg_catalog.convert_to(record_id_candidate, 'UTF8')) > 256 then
      raise exception using errcode = '22023', message = 'Import update target identifier is too large';
    end if;

    if record_id_candidate !~* uuid_pattern then
      row_result := pg_catalog.jsonb_build_object(
        'rowNumber', row_number_value, 'status', 'refused', 'code', 'invalid_record_id'
      );
      target_results := target_results || pg_catalog.jsonb_build_array(row_result);
      continue;
    end if;
    begin
      target_record_id := record_id_candidate::uuid;
    exception when others then
      row_result := pg_catalog.jsonb_build_object(
        'rowNumber', row_number_value, 'status', 'refused', 'code', 'invalid_record_id'
      );
      target_results := target_results || pg_catalog.jsonb_build_array(row_result);
      continue;
    end;
    if target_record_id = nil_uuid then
      row_result := pg_catalog.jsonb_build_object(
        'rowNumber', row_number_value, 'status', 'refused', 'code', 'invalid_record_id'
      );
      target_results := target_results || pg_catalog.jsonb_build_array(row_result);
      continue;
    end if;

    initial_read := vortex_record.read_record(p_record_type_id, target_record_id);
    initial_capabilities := vortex_record.read_record_capabilities(p_record_type_id, target_record_id);
    if pg_catalog.jsonb_typeof(initial_read) is distinct from 'object' then
      raise exception using errcode = '55000', message = 'Record reader returned malformed facts';
    end if;
    -- A neutral row must not conceal malformed facts from either reader.
    if initial_capabilities is not null then
      if pg_catalog.jsonb_typeof(initial_capabilities) is distinct from 'object'
        or not (initial_capabilities ?& array['actions', 'changeableFieldIds'])
        or pg_catalog.jsonb_typeof(initial_capabilities -> 'actions') is distinct from 'array'
        or pg_catalog.jsonb_typeof(initial_capabilities -> 'changeableFieldIds') is distinct from 'array' then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
      end if;
      select pg_catalog.count(*) into key_count
      from pg_catalog.jsonb_object_keys(initial_capabilities) as supplied(key);
      if key_count <> 2 then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
      end if;
    end if;
    select pg_catalog.count(*) into key_count
    from pg_catalog.jsonb_object_keys(initial_read) as supplied(key);
    if initial_read ->> 'outcome' = 'refused' then
      if key_count <> 1 then
        raise exception using errcode = '55000', message = 'Record reader returned malformed facts';
      end if;
    else
      if initial_read ->> 'outcome' is distinct from 'allowed'
        or pg_catalog.jsonb_typeof(initial_read -> 'values') is distinct from 'object' then
        raise exception using errcode = '55000', message = 'Record reader returned malformed facts';
      end if;
      if key_count <> 4 or not (initial_read ?& array['outcome', 'recordId', 'concurrencyNumber', 'values']) then
        raise exception using errcode = '55000', message = 'Record reader returned malformed facts';
      end if;
      if (initial_read ->> 'recordId') !~* uuid_pattern
        or (initial_read ->> 'recordId')::uuid is distinct from target_record_id
        or pg_catalog.jsonb_typeof(initial_read -> 'concurrencyNumber') is distinct from 'number'
        or (initial_read ->> 'concurrencyNumber') !~ '^[1-9][0-9]*$'
        or (initial_read ->> 'concurrencyNumber')::numeric > 9007199254740991
        or pg_catalog.octet_length(pg_catalog.convert_to((initial_read -> 'values')::text, 'UTF8')) > 65536 then
        raise exception using errcode = '55000', message = 'Record reader returned malformed facts';
      end if;

      projection_field_ids := array[]::uuid[];
      for projection_field_value in
        select key from pg_catalog.jsonb_object_keys(initial_read -> 'values') as projected(key)
      loop
        if projection_field_value !~* uuid_pattern then
          raise exception using errcode = '55000', message = 'Record projection returned malformed fields';
        end if;
        begin
          projection_field_id := projection_field_value::uuid;
        exception when others then
          raise exception using errcode = '55000', message = 'Record projection returned malformed fields';
        end;
        if projection_field_id = nil_uuid
          or projection_field_id = any(projection_field_ids)
          or not exists (
          select 1
          from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as field(value)
          where (field.value ->> 'fieldId')::uuid = projection_field_id
        ) then
          raise exception using errcode = '55000', message = 'Record projection returned malformed fields';
        end if;
        projection_field_ids := pg_catalog.array_append(projection_field_ids, projection_field_id);
      end loop;
    end if;

    if initial_capabilities is not null then
      action_values := array[]::text[];
      for target_item in
        select item.value from pg_catalog.jsonb_array_elements(initial_capabilities -> 'actions') as item(value)
      loop
        if pg_catalog.jsonb_typeof(target_item.value) is distinct from 'string' then
          raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
        end if;
        action_value := target_item.value #>> '{}';
        if action_value not in ('update', 'delete', 'restore') or action_value = any(action_values) then
          raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
        end if;
        action_values := pg_catalog.array_append(action_values, action_value);
      end loop;

      capability_field_ids := array[]::uuid[];
      for capability_field_value in
        select item.value #>> '{}'
        from pg_catalog.jsonb_array_elements(initial_capabilities -> 'changeableFieldIds') as item(value)
      loop
        if capability_field_value !~* uuid_pattern then
          raise exception using errcode = '55000', message = 'Record capability reader returned malformed fields';
        end if;
        begin
          capability_field_id := capability_field_value::uuid;
        exception when others then
          raise exception using errcode = '55000', message = 'Record capability reader returned malformed fields';
        end;
        if capability_field_id = nil_uuid
          or capability_field_id = any(capability_field_ids)
          or not exists (
            select 1
            from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as field(value)
            where (field.value ->> 'fieldId')::uuid = capability_field_id
          ) then
          raise exception using errcode = '55000', message = 'Record capability reader returned malformed fields';
        end if;
        capability_field_ids := pg_catalog.array_append(capability_field_ids, capability_field_id);
      end loop;
    end if;

    if initial_read ->> 'outcome' = 'refused' or initial_capabilities is null then
      row_result := pg_catalog.jsonb_build_object(
        'rowNumber', row_number_value, 'status', 'refused', 'code', 'target_unavailable'
      );
      target_results := target_results || pg_catalog.jsonb_build_array(row_result);
      continue;
    end if;

    mapped_fields_available := 'update' = any(action_values);
    if mapped_fields_available then
      foreach mapped_field_id in array mapped_ids loop
        if not exists (
          select 1
          from pg_catalog.jsonb_object_keys(initial_read -> 'values') as projected(key)
          where pg_catalog.lower(projected.key) = mapped_field_id::text
        ) or not (mapped_field_id = any(capability_field_ids)) then
          mapped_fields_available := false;
          exit;
        end if;
      end loop;
    end if;
    if not mapped_fields_available then
      row_result := pg_catalog.jsonb_build_object(
        'rowNumber', row_number_value, 'status', 'refused', 'code', 'target_unavailable'
      );
      target_results := target_results || pg_catalog.jsonb_build_array(row_result);
      continue;
    end if;

    final_read := vortex_record.read_record(p_record_type_id, target_record_id);
    final_capabilities := vortex_record.read_record_capabilities(p_record_type_id, target_record_id);
    if pg_catalog.jsonb_typeof(final_read) is distinct from 'object'
      or final_read ->> 'outcome' is distinct from 'allowed'
      or pg_catalog.jsonb_typeof(final_read -> 'values') is distinct from 'object'
      or final_capabilities is null
      or pg_catalog.jsonb_typeof(final_capabilities) is distinct from 'object'
      or not (final_capabilities ?& array['actions', 'changeableFieldIds'])
      or pg_catalog.jsonb_typeof(final_capabilities -> 'actions') is distinct from 'array'
      or pg_catalog.jsonb_typeof(final_capabilities -> 'changeableFieldIds') is distinct from 'array' then
      raise exception using errcode = '55000', message = 'Record facts changed during import preview';
    end if;
    if (final_read ->> 'recordId') !~* uuid_pattern
      or (final_read ->> 'recordId')::uuid is distinct from target_record_id
      or final_read -> 'concurrencyNumber' is distinct from initial_read -> 'concurrencyNumber'
      or final_read -> 'values' is distinct from initial_read -> 'values' then
      raise exception using errcode = '55000', message = 'Record facts changed during import preview';
    end if;
    select pg_catalog.count(*) into key_count
    from pg_catalog.jsonb_object_keys(final_read) as supplied(key);
    if key_count <> 4
      or not (final_read ?& array['outcome', 'recordId', 'concurrencyNumber', 'values'])
      or pg_catalog.jsonb_typeof(final_read -> 'concurrencyNumber') is distinct from 'number'
      or (final_read ->> 'concurrencyNumber') !~ '^[1-9][0-9]*$'
      or (final_read ->> 'concurrencyNumber')::numeric > 9007199254740991
      or pg_catalog.octet_length(pg_catalog.convert_to((final_read -> 'values')::text, 'UTF8')) > 65536 then
      raise exception using errcode = '55000', message = 'Record reader returned malformed facts';
    end if;
    select pg_catalog.count(*) into key_count
    from pg_catalog.jsonb_object_keys(final_capabilities) as supplied(key);
    if key_count <> 2 then
      raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
    end if;

    -- The update action and every mapped field must remain available.
    -- Changes to unrelated delete or restore actions are not update evidence.
    action_values := array[]::text[];
    for target_item in
      select item.value from pg_catalog.jsonb_array_elements(final_capabilities -> 'actions') as item(value)
    loop
      if pg_catalog.jsonb_typeof(target_item.value) is distinct from 'string' then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
      end if;
      action_value := target_item.value #>> '{}';
      if action_value not in ('update', 'delete', 'restore') or action_value = any(action_values) then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed facts';
      end if;
      action_values := pg_catalog.array_append(action_values, action_value);
    end loop;
    capability_field_ids := array[]::uuid[];
    for capability_field_value in
      select item.value #>> '{}'
      from pg_catalog.jsonb_array_elements(final_capabilities -> 'changeableFieldIds') as item(value)
    loop
      if capability_field_value !~* uuid_pattern then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed fields';
      end if;
      begin
        capability_field_id := capability_field_value::uuid;
      exception when others then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed fields';
      end;
      if capability_field_id = nil_uuid
        or capability_field_id = any(capability_field_ids)
        or not exists (
          select 1
          from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as field(value)
          where (field.value ->> 'fieldId')::uuid = capability_field_id
        ) then
        raise exception using errcode = '55000', message = 'Record capability reader returned malformed fields';
      end if;
      capability_field_ids := pg_catalog.array_append(capability_field_ids, capability_field_id);
    end loop;
    if not ('update' = any(action_values)) then
      raise exception using errcode = '55000', message = 'Record update capability changed during import preview';
    end if;
    foreach mapped_field_id in array mapped_ids loop
      if not (mapped_field_id = any(capability_field_ids)) then
        raise exception using errcode = '55000', message = 'Record update capability changed during import preview';
      end if;
    end loop;

    row_values := initial_read -> 'values';
    row_result := pg_catalog.jsonb_build_object(
      'rowNumber', row_number_value,
      'status', 'matched',
      'recordId', target_record_id,
      'expectedConcurrencyNumber', (initial_read ->> 'concurrencyNumber')::numeric,
      'existingValues', row_values,
      'changeableFieldIds', mapped_ids_value,
      'access', pg_catalog.jsonb_build_object(
        'state', 'allowed', 'operation', 'update', 'targetRecordId', target_record_id
      ),
      'match', pg_catalog.jsonb_build_object(
        'method', 'record_id', 'state', 'matched', 'recordId', target_record_id,
        'existingValues', row_values
      )
    );
    target_results := target_results || pg_catalog.jsonb_build_array(row_result);
  end loop;

  context_final := vortex_access.validated_human_request_context();
  installation_final := vortex_module.read_current_active_installation();
  meta_final := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'read');
  if context_final is distinct from context_initial
    or installation_final is distinct from installation_initial
    or meta_final is distinct from meta_initial then
    raise exception using errcode = '55000', message = 'Import update target context changed';
  end if;
  now_value := pg_catalog.clock_timestamp();
  if now_value >= valid_until_value then
    raise exception using errcode = '22023', message = 'Import update target request expired during resolution';
  end if;

  result_value := pg_catalog.jsonb_build_object(
    'outcome', 'available',
    'kind', 'partial_update_target_facts',
    'validationComplete', false,
    'organizationId', (context_initial ->> 'organizationId')::uuid,
    'applicationRootId', (context_initial ->> 'applicationRootId')::uuid,
    'identityId', (context_initial ->> 'identityId')::uuid,
    'organizationAccountId', (context_initial ->> 'organizationAccountId')::uuid,
    'accessVersion', (context_initial ->> 'accessVersion')::numeric,
    'correlationId', (context_initial ->> 'correlationId')::uuid,
    'issuedAt', context_initial -> 'issuedAt',
    'validUntil', pg_catalog.to_jsonb(valid_until_value),
    'activeInstallation', installation_initial,
    'moduleRootId', (meta_initial ->> 'moduleRootId')::uuid,
    'moduleReleaseRevision', (meta_initial ->> 'moduleReleaseRevision')::numeric,
    'storageContractId', (meta_initial ->> 'storageContractId')::uuid,
    'storageScope', meta_initial -> 'storageScope',
    'recordType', record_type_value,
    'mappedFieldIds', mapped_ids_value,
    'rows', target_results
  );
  if pg_catalog.octet_length(pg_catalog.convert_to(result_value::text, 'UTF8')) > 5242880 then
    raise exception using errcode = '54000', message = 'Import update target result is too large';
  end if;
  if pg_catalog.clock_timestamp() >= valid_until_value then
    raise exception using errcode = '22023', message = 'Import update target request expired before return';
  end if;
  return result_value;
end
$function$;


ALTER FUNCTION vortex_record.read_import_update_targets(p_record_type_id uuid, p_mapped_field_ids jsonb, p_targets jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_import_update_targets(p_record_type_id uuid, p_mapped_field_ids jsonb, p_targets jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_import_update_targets(p_record_type_id uuid, p_mapped_field_ids jsonb, p_targets jsonb) IS 'Returns bounded partial update-target facts for a verified human Application request by composing the current installed Record definition and paired protected Record readers; never writes business records or authorizes execution.';


--
-- Name: read_index_conflict_references_internal(uuid, text, text, text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.read_index_conflict_references_internal(p_record_type_id uuid, p_table_token text, p_scope_columns text, p_column_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  max_groups constant integer := 100;
  max_records constant integer := 1000;
  conflict_sql text;
  group_row record;
  record_id_value uuid;
  loaded jsonb;
  decision jsonb;
  readable_references jsonb := '[]'::jsonb;
  group_count integer := 0;
  record_count integer := 0;
begin
  if p_record_type_id is null
    or p_record_type_id = nil_uuid
    or p_table_token is null
    or p_table_token !~ '^rt_[a-f0-9]{32}$'
    or p_column_token is null
    or p_column_token !~ '^f_[a-f0-9]{32}$'
    or p_scope_columns is null
    or p_scope_columns not in ('organisation_id', 'organisation_id, application_root_id') then
    raise exception using errcode = '55000',
      message = 'Index conflict selector is invalid';
  end if;

  -- Only the participating record identities are selected; the conflicting
  -- field value is grouped on but never projected, so no raw value can leave.
  -- The search mirrors the unique index exactly: its lifecycle predicate, and
  -- no null value, because the index treats every null as distinct. The
  -- forced `record_data` policies keep it to the caller's organisation and
  -- Application.
  conflict_sql := pg_catalog.format(
    'select pg_catalog.array_agg(stored.record_id order by stored.record_id) as record_ids
     from record_data.%I as stored
     where stored.lifecycle_state in (''active'', ''soft_deleted'', ''removal_pending'')
       and stored.%I is not null
     group by %s, stored.%I
     having pg_catalog.count(*) > 1
     order by 1
     limit %s',
    p_table_token, p_column_token, p_scope_columns, p_column_token, max_groups + 1
  );

  for group_row in execute conflict_sql
  loop
    group_count := group_count + 1;
    if group_count > max_groups then
      return pg_catalog.jsonb_build_object('outcome', 'unreadable');
    end if;

    for record_id_value in
      select id.value from pg_catalog.unnest(group_row.record_ids) as id(value)
    loop
      record_count := record_count + 1;
      if record_count > max_records then
        return pg_catalog.jsonb_build_object('outcome', 'unreadable');
      end if;

      begin
        loaded := vortex_record.load_record_access_facts_internal(
          p_record_type_id, 'read', record_id_value, null
        );
        if loaded ->> 'outcome' <> 'loaded'
          or pg_catalog.jsonb_typeof(loaded -> 'declaration') <> 'object'
          or pg_catalog.jsonb_typeof(loaded -> 'facts') <> 'object' then
          return pg_catalog.jsonb_build_object('outcome', 'unreadable');
        end if;

        decision := vortex_access.evaluate_organization_record_access_internal(
          loaded -> 'declaration', record_id_value, loaded -> 'facts'
        );
        -- Any unreadable participant collapses the whole conflict; a partial
        -- listing would be an existence oracle for the hidden rows.
        if decision ->> 'outcome' <> 'allowed' then
          return pg_catalog.jsonb_build_object('outcome', 'unreadable');
        end if;
      exception
        when others then
          -- Candidate-specific failures carry record detail; they collapse
          -- exactly like a refused decision.
          return pg_catalog.jsonb_build_object('outcome', 'unreadable');
      end;

      readable_references := readable_references || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'recordTypeId', p_record_type_id,
          'recordId', record_id_value
        )
      );
    end loop;
  end loop;

  if group_count = 0 then
    return pg_catalog.jsonb_build_object('outcome', 'none');
  end if;
  return pg_catalog.jsonb_build_object('outcome', 'readable', 'records', readable_references);
end
$_$;


ALTER FUNCTION vortex_record.read_index_conflict_references_internal(p_record_type_id uuid, p_table_token text, p_scope_columns text, p_column_token text) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_index_conflict_references_internal(p_record_type_id uuid, p_table_token text, p_scope_columns text, p_column_token text); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_index_conflict_references_internal(p_record_type_id uuid, p_table_token text, p_scope_columns text, p_column_token text) IS 'Adapter-owned resolution of one uniqueness index conflict: duplicate record identities only, each behind the exact read decision, collapsing wholly to one generic refusal when any participant is unreadable.';


--
-- Name: read_index_readiness(uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.read_index_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_storage_contract_ids uuid[];
  target record;
  mapping record;
  purpose text;
  scope_columns text;
  index_token text;
  definition_fingerprint text;
  observed text;
  catalogue_id uuid;
  catalogue_purpose text;
  catalogue_token text;
  catalogue_fingerprint text;
  catalogue_observed text;
  catalogue_revision bigint;
  ready boolean;
  target_count integer := 0;
  indexes jsonb := '[]'::jsonb;
  uniqueness_ready boolean := true;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Index readiness command is invalid';
  end if;

  -- The same protected activation target fact the lifecycle-policy readiness
  -- read uses; the organisation is re-derived from the validated human request
  -- context inside it and is never taken from the caller.
  select pg_catalog.array_agg(distinct targets.storage_contract_id)
    into target_storage_contract_ids
  from vortex_module.read_lifecycle_activation_targets_internal(
    p_organization_id, p_application_root_id, p_application_release_revision,
    p_expected_module_bindings
  ) as targets;

  if target_storage_contract_ids is null
    or pg_catalog.cardinality(target_storage_contract_ids) = 0 then
    raise exception using errcode = '23514',
      message = 'Index activation targets are incomplete';
  end if;

  for target in
    select catalogue.storage_contract_id, catalogue.storage_scope,
      catalogue.physical_table_token
    from vortex_record.storage_catalogue as catalogue
    where catalogue.storage_contract_id = any (target_storage_contract_ids)
      and catalogue.state = 'active'
    order by catalogue.storage_contract_id
  loop
    target_count := target_count + 1;

    for mapping in
      select stored.field_id, stored.physical_column_token, stored.field_definition
      from vortex_record.field_storage_mappings as stored
      where stored.storage_contract_id = target.storage_contract_id
        and stored.state = 'active'
        and (
          coalesce((stored.field_definition ->> 'unique')::boolean, false)
          or coalesce((stored.field_definition ->> 'filterable')::boolean, false)
          or coalesce((stored.field_definition ->> 'sortable')::boolean, false)
        )
      order by stored.field_id
    loop
      purpose := case
        when coalesce((mapping.field_definition ->> 'unique')::boolean, false)
          then 'uniqueness'
        else 'performance'
      end;
      scope_columns := vortex_record.index_scope_columns(target.storage_scope);
      index_token := case purpose when 'uniqueness' then 'ux_' else 'ix_' end
        || pg_catalog.substr(mapping.physical_column_token, 3);
      definition_fingerprint := vortex_record.index_definition_fingerprint(
        purpose, target.physical_table_token, scope_columns, mapping.physical_column_token
      );
      observed := vortex_record.observe_field_index_internal(
        purpose, target.physical_table_token, scope_columns, mapping.physical_column_token
      );

      select stored_index.index_contract_id, stored_index.purpose,
        stored_index.physical_index_token, stored_index.desired_definition_fingerprint,
        stored_index.observed_state, stored_index.observed_revision
      into catalogue_id, catalogue_purpose, catalogue_token, catalogue_fingerprint,
        catalogue_observed, catalogue_revision
      from vortex_record.index_catalogue as stored_index
      where stored_index.storage_contract_id = target.storage_contract_id
        and stored_index.field_id = mapping.field_id
      for share;

      ready := observed = 'present'
        and catalogue_id is not null
        and catalogue_purpose = purpose
        and catalogue_token = index_token
        and catalogue_fingerprint = definition_fingerprint;

      if purpose = 'uniqueness' and not ready then
        uniqueness_ready := false;
      end if;

      indexes := indexes || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'indexContractId', coalesce(
          catalogue_id,
          vortex_record.index_contract_identity(
            target.storage_contract_id, mapping.field_id
          )
        ),
        'storageContractId', target.storage_contract_id,
        'fieldId', mapping.field_id,
        'purpose', purpose,
        'desiredDefinitionFingerprint', definition_fingerprint,
        'observedState', observed,
        'recordedObservedState', catalogue_observed,
        'observedRevision', catalogue_revision,
        'ready', ready
      ));
    end loop;
  end loop;

  -- Every installation storage contract must be an active catalogue entry; a
  -- target this read cannot account for is an incomplete installation, never an
  -- implicitly unindexed record type.
  if target_count <> pg_catalog.cardinality(target_storage_contract_ids) then
    raise exception using errcode = '23514',
      message = 'Index activation targets are incomplete';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', p_organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'indexes', indexes,
    'uniquenessReady', uniqueness_ready,
    'performanceAdvisory', true
  );
end
$$;


ALTER FUNCTION vortex_record.read_index_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION read_index_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.read_index_readiness(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Live readiness of every exact field index an activating Application installation owns: uniqueness indexes are activation requirements, performance indexes are advisory.';


--
-- Name: read_module_query_inputs(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_module_query_inputs(
  p_module_root_id uuid,
  p_query_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  preview_address text;
  preview_context jsonb;
  resolved jsonb;
begin
  preview_address := nullif(
    pg_catalog.current_setting('vortex_record.preview_installation_id', true), ''
  );
  if preview_address is not null then
    begin
      preview_context := vortex_record.read_current_preview_installation_internal();
      if preview_context is null
        or pg_catalog.jsonb_typeof(preview_context) is distinct from 'object'
        or preview_context ? 'outcome' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'query_unavailable');
      end if;
      resolved := vortex_record.resolve_preview_module_query_internal(p_module_root_id, p_query_id);
    exception when others then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'query_unavailable');
    end;
  else
    resolved := vortex_record.resolve_installed_module_query_internal(p_module_root_id, p_query_id);
  end if;
  if resolved is null then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'query_unavailable');
  end if;
  return pg_catalog.jsonb_build_object(
    'outcome', 'resolved',
    'moduleReleaseRevision', resolved -> 'moduleReleaseRevision',
    'moduleReleaseVersion', resolved -> 'moduleReleaseVersion',
    'inputs', coalesce(resolved #> '{query,inputs}', '[]'::jsonb)
  );
end
$function$;


ALTER FUNCTION vortex_record.read_module_query_inputs(p_module_root_id uuid, p_query_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_module_query_inputs(p_module_root_id uuid, p_query_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_module_query_inputs(p_module_root_id uuid, p_query_id uuid) IS 'The typed input contract of one installed or exact current human-owned preview Module query, or one refusal.';


--
-- Name: read_provisioned_lifecycle_policy_setup(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.read_provisioned_lifecycle_policy_setup(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expected_item jsonb;
  expected_root uuid;
  expected_revision bigint;
  previous_expected_root text;
  projection jsonb;
  projection_item jsonb;
  projection_storage_item jsonb;
  previous_projection_root text;
  previous_projection_storage text;
  previous_union_storage text;
  storage_ids uuid[] := array[]::uuid[];
  storage_id uuid;
  authority record;
  policy_row vortex_record.record_type_lifecycle_policies%rowtype;
  limits_row vortex_record.organization_lifecycle_limits%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  context_after_lock jsonb;
  context_at_completion jsonb;
  install_decision record;
  install_scope_decision record;
  final_decision record;
  completed_at timestamptz;
  expected_binding_count integer := 0;
  target_ordinal integer := 0;
  source_bindings jsonb;
  target_application_root_id uuid;
  target_policy jsonb;
  limits_value jsonb;
  targets_value jsonb := '[]'::jsonb;
  target_value jsonb;
  policy_found boolean;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_expected_module_bindings is null
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) <> 'array' then
    raise exception using errcode = '22023',
      message = 'Provisioned lifecycle setup request is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_expected_module_bindings) not between 1 and 10000 then
    raise exception using errcode = '22023',
      message = 'Provisioned lifecycle setup request is invalid';
  end if;

  for expected_item in
    select item.value
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings)
      with ordinality as item(value, ordinal)
    order by item.ordinal
  loop
    expected_binding_count := expected_binding_count + 1;
    if pg_catalog.jsonb_typeof(expected_item) <> 'object'
      or not expected_item ?& array['moduleRootId', 'bindingRevision']
      or expected_item - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(expected_item -> 'moduleRootId') <> 'string'
      or not vortex_record.is_lifecycle_uuid_text(expected_item ->> 'moduleRootId')
      or (expected_item ->> 'moduleRootId') <> pg_catalog.lower(expected_item ->> 'moduleRootId')
      or not vortex_record.is_lifecycle_revision_value(expected_item -> 'bindingRevision') then
      raise exception using errcode = '22023',
        message = 'Provisioned lifecycle setup request is invalid';
    end if;
    if previous_expected_root is not null
      and previous_expected_root collate "C"
        >= (expected_item ->> 'moduleRootId') collate "C" then
      raise exception using errcode = '22023',
        message = 'Provisioned lifecycle setup request is not canonical';
    end if;
    previous_expected_root := expected_item ->> 'moduleRootId';
  end loop;

  select locked.* into strict authority
  from vortex_access.lock_record_lifecycle_policy_authority() as locked;
  if authority.application_root_id is distinct from p_application_root_id then
    raise exception using errcode = '42501',
      message = 'Provisioned lifecycle setup authority is unavailable';
  end if;
  context_after_lock := vortex_access.validated_human_request_context();
  if context_after_lock is null
    or pg_catalog.jsonb_typeof(context_after_lock) <> 'object'
    or not context_after_lock ?& array[
      'callerKind', 'tenantId', 'organizationId', 'organizationAccountId',
      'applicationRootId', 'identityId', 'sessionId', 'authenticationStrength',
      'issuedAt', 'expiresAt', 'accessVersion', 'correlationId'
    ]
    or context_after_lock ->> 'callerKind' is distinct from 'human'
    or context_after_lock ->> 'applicationRootId' is distinct from p_application_root_id::text
    or context_after_lock ->> 'organizationId' is distinct from authority.organization_id::text
    or context_after_lock ->> 'organizationAccountId' is distinct from
      authority.organization_account_id::text
    or context_after_lock ->> 'accessVersion' is distinct from authority.access_version::text
    or context_after_lock ->> 'correlationId' is distinct from authority.correlation_id::text then
    raise exception using errcode = '42501',
      message = 'Provisioned lifecycle setup authority is unavailable';
  end if;

  projection := vortex_module.read_provisioned_lifecycle_setup_targets_internal(
    p_application_root_id,
    p_application_release_revision,
    p_expected_module_bindings
  );
  if projection is null
    or pg_catalog.jsonb_typeof(projection) <> 'object'
    or not projection ?& array[
      'organizationId', 'applicationRootId', 'applicationReleaseRevision',
      'registrationRevision', 'moduleBindings', 'storageContractIds'
    ]
    or projection - array[
      'organizationId', 'applicationRootId', 'applicationReleaseRevision',
      'registrationRevision', 'moduleBindings', 'storageContractIds'
    ] <> '{}'::jsonb
    or not vortex_record.is_lifecycle_uuid_text(projection ->> 'organizationId')
    or not vortex_record.is_lifecycle_uuid_text(projection ->> 'applicationRootId')
    or pg_catalog.lower(projection ->> 'organizationId') <> authority.organization_id::text
    or pg_catalog.lower(projection ->> 'applicationRootId') <> p_application_root_id::text
    or not vortex_record.is_lifecycle_revision_value(projection -> 'applicationReleaseRevision')
    or (projection ->> 'applicationReleaseRevision')::bigint <> p_application_release_revision
    or not vortex_record.is_lifecycle_revision_value(projection -> 'registrationRevision')
    or pg_catalog.jsonb_typeof(projection -> 'moduleBindings') <> 'array'
    or pg_catalog.jsonb_typeof(projection -> 'storageContractIds') <> 'array' then
    raise exception using errcode = '40001',
      message = 'Provisioned lifecycle setup source changed';
  end if;
  if pg_catalog.jsonb_array_length(projection -> 'moduleBindings') <> expected_binding_count then
    raise exception using errcode = '40001',
      message = 'Provisioned lifecycle setup source changed';
  end if;

  for projection_item in
    select item.value
    from pg_catalog.jsonb_array_elements(projection -> 'moduleBindings')
      with ordinality as item(value, ordinal)
    order by item.ordinal
  loop
    if pg_catalog.jsonb_typeof(projection_item) <> 'object'
      or not projection_item ?& array[
        'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state', 'storageContractIds'
      ]
      or projection_item - array[
        'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state', 'storageContractIds'
      ] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(projection_item -> 'moduleRootId') <> 'string'
      or not vortex_record.is_lifecycle_uuid_text(projection_item ->> 'moduleRootId')
      or (projection_item ->> 'moduleRootId') <> pg_catalog.lower(projection_item ->> 'moduleRootId')
      or not vortex_record.is_lifecycle_revision_value(projection_item -> 'moduleReleaseRevision')
      or not vortex_record.is_lifecycle_revision_value(projection_item -> 'bindingRevision')
      or projection_item ->> 'state' is distinct from 'provisioned'
      or pg_catalog.jsonb_typeof(projection_item -> 'storageContractIds') <> 'array' then
      raise exception using errcode = '40001',
        message = 'Provisioned lifecycle setup source is incomplete';
    end if;
    if previous_projection_root is not null
      and previous_projection_root collate "C"
        >= (projection_item ->> 'moduleRootId') collate "C" then
      raise exception using errcode = '40001',
        message = 'Provisioned lifecycle setup source is not canonical';
    end if;
    previous_projection_root := projection_item ->> 'moduleRootId';
    expected_root := (projection_item ->> 'moduleRootId')::uuid;
    expected_revision := (projection_item ->> 'bindingRevision')::bigint;
    if not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
      where (expected.value ->> 'moduleRootId')::uuid = expected_root
        and (expected.value ->> 'bindingRevision')::bigint = expected_revision
    ) then
      raise exception using errcode = '40001',
        message = 'Provisioned lifecycle setup source changed';
    end if;

    previous_projection_storage := null;
    for projection_storage_item in
      select storage_item.value
      from pg_catalog.jsonb_array_elements(projection_item -> 'storageContractIds')
        with ordinality as storage_item(value, ordinal)
      order by storage_item.ordinal
    loop
      if pg_catalog.jsonb_typeof(projection_storage_item) <> 'string'
        or not vortex_record.is_lifecycle_uuid_text(projection_storage_item #>> '{}')
        or (projection_storage_item #>> '{}') <> pg_catalog.lower(projection_storage_item #>> '{}') then
        raise exception using errcode = '40001',
          message = 'Provisioned lifecycle setup source is incomplete';
      end if;
      if previous_projection_storage is not null
        and previous_projection_storage collate "C"
          >= (projection_storage_item #>> '{}') collate "C" then
        raise exception using errcode = '40001',
          message = 'Provisioned lifecycle setup source is not canonical';
      end if;
      previous_projection_storage := projection_storage_item #>> '{}';
      storage_id := (projection_storage_item #>> '{}')::uuid;
      if not storage_id = any (storage_ids) then
        storage_ids := pg_catalog.array_append(storage_ids, storage_id);
      end if;
    end loop;
  end loop;

  if pg_catalog.cardinality(storage_ids) = 0 then
    raise exception using errcode = '23514',
      message = 'Provisioned lifecycle setup has no policy targets';
  end if;
  storage_ids := array(select distinct item.value from pg_catalog.unnest(storage_ids) item(value)
    order by item.value);
  if pg_catalog.jsonb_array_length(projection -> 'storageContractIds') <>
    pg_catalog.cardinality(storage_ids) then
    raise exception using errcode = '40001',
      message = 'Provisioned lifecycle setup source is incomplete';
  end if;
  target_ordinal := 0;
  for projection_storage_item in
    select item.value
    from pg_catalog.jsonb_array_elements(projection -> 'storageContractIds')
      with ordinality as item(value, ordinal)
    order by item.ordinal
  loop
    target_ordinal := target_ordinal + 1;
    if pg_catalog.jsonb_typeof(projection_storage_item) <> 'string'
      or not vortex_record.is_lifecycle_uuid_text(projection_storage_item #>> '{}')
      or (projection_storage_item #>> '{}') <> pg_catalog.lower(projection_storage_item #>> '{}')
      or (projection_storage_item #>> '{}') <> storage_ids[target_ordinal]::text
      or (previous_union_storage is not null
        and previous_union_storage collate "C"
          >= (projection_storage_item #>> '{}') collate "C") then
      raise exception using errcode = '40001',
        message = 'Provisioned lifecycle setup source is not canonical';
    end if;
    previous_union_storage := projection_storage_item #>> '{}';
  end loop;

  select stored.* into limits_row
  from vortex_record.organization_lifecycle_limits as stored
  where stored.organization_id = authority.organization_id
  for share;
  if not found
    or limits_row.settings_revision not between 1 and 9007199254740991
    or not vortex_record.is_lifecycle_action_list(limits_row.allowed_actions)
    or not vortex_record.is_lifecycle_destination_list(limits_row.allowed_archive_destinations)
    or limits_row.allow_unlimited_retention_days is distinct from
      (limits_row.max_retention_days is null)
    or limits_row.allow_unlimited_record_count is distinct from
      (limits_row.max_record_count is null) then
    raise exception using errcode = '23514',
      message = 'Provisioned lifecycle settings are incomplete';
  end if;
  limits_value := pg_catalog.jsonb_build_object(
    'organizationId', limits_row.organization_id,
    'settingsRevision', limits_row.settings_revision,
    'maxRetentionDays', limits_row.max_retention_days,
    'maxRecordCount', limits_row.max_record_count,
    'allowUnlimitedRetentionDays', limits_row.allow_unlimited_retention_days,
    'allowUnlimitedRecordCount', limits_row.allow_unlimited_record_count,
    'allowedActions', pg_catalog.to_jsonb(limits_row.allowed_actions),
    'allowedArchiveDestinations', pg_catalog.to_jsonb(limits_row.allowed_archive_destinations)
  );

  for storage_id in select item.value from pg_catalog.unnest(storage_ids) item(value)
    order by item.value
  loop
    select stored.* into catalogue_row
    from vortex_record.storage_catalogue as stored
    where stored.storage_contract_id = storage_id
      and stored.state = 'active'
    for share;
    if not found then
      raise exception using errcode = '40001',
        message = 'Provisioned lifecycle target is incomplete';
    end if;

    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'moduleRootId', binding.value ->> 'moduleRootId',
        'moduleReleaseRevision', (binding.value ->> 'moduleReleaseRevision')::bigint,
        'bindingRevision', (binding.value ->> 'bindingRevision')::bigint
      ) order by (binding.value ->> 'moduleRootId') collate "C"
    ) into source_bindings
    from pg_catalog.jsonb_array_elements(projection -> 'moduleBindings') as binding(value)
    where exists (
      select 1
      from pg_catalog.jsonb_array_elements(binding.value -> 'storageContractIds') as source(value)
      where (source.value #>> '{}')::uuid = storage_id
    );
    if source_bindings is null or not exists (
      select 1
      from pg_catalog.jsonb_array_elements(source_bindings) as source(value)
      where (source.value ->> 'moduleRootId')::uuid = catalogue_row.module_root_id
    ) then
      raise exception using errcode = '40001',
        message = 'Provisioned lifecycle target source is incomplete';
    end if;

    target_application_root_id := case
      when catalogue_row.storage_scope = 'organization_shared' then null
      when catalogue_row.storage_scope = 'application_contained' then p_application_root_id
      else null
    end;
    if catalogue_row.storage_scope not in ('organization_shared', 'application_contained') then
      raise exception using errcode = '23514',
        message = 'Provisioned lifecycle target scope is invalid';
    end if;

    select stored.* into policy_row
    from vortex_record.record_type_lifecycle_policies as stored
    where stored.organization_id = authority.organization_id
      and stored.storage_contract_id = storage_id
      and stored.application_root_id is not distinct from target_application_root_id
    for share;
    policy_found := found;
    if not policy_found then
      target_policy := pg_catalog.jsonb_build_object('state', 'absent');
    else
      if not vortex_record.is_record_type_lifecycle_policy(policy_row.policy_body)
        or pg_catalog.lower(policy_row.policy_body ->> 'policyId') is distinct from
          policy_row.policy_id::text
        or pg_catalog.lower(policy_row.policy_body ->> 'organizationId') is distinct from
          authority.organization_id::text
        or pg_catalog.lower(policy_row.policy_body ->> 'storageContractId') is distinct from
          storage_id::text
        or pg_catalog.lower(policy_row.policy_body ->> 'applicationRootId') is distinct from
          target_application_root_id::text
        or policy_row.policy_body ->> 'policyRevision' is distinct from
          policy_row.policy_revision::text
        or policy_row.policy_body ->> 'action' is distinct from policy_row.action then
        raise exception using errcode = '23514',
          message = 'Provisioned lifecycle policy is inconsistent';
      end if;
      target_policy := pg_catalog.jsonb_build_object(
        'state', 'configured',
        'policyId', policy_row.policy_id,
        'policyRevision', policy_row.policy_revision,
        'policyBody', policy_row.policy_body
      );
    end if;

    target_value := pg_catalog.jsonb_build_object(
      'storageContractId', storage_id,
      'storageScope', catalogue_row.storage_scope,
      'applicationRootId', target_application_root_id,
      'sourceBindings', source_bindings,
      'policy', target_policy
    );
    targets_value := targets_value || pg_catalog.jsonb_build_array(target_value);
  end loop;

  -- Re-evaluate all authority after every Module and Record lock wait. The
  -- installation delegation can expire without an Access-version change, so
  -- the request context alone is not sufficient completion evidence. The
  -- request-role caller repeats all three decisions after validating the DTO.
  select evaluated.* into strict install_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  select evaluated.* into strict install_scope_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  select evaluated.* into strict final_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.record_lifecycle.manage_policy',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  context_at_completion := vortex_access.validated_human_request_context();
  completed_at := pg_catalog.clock_timestamp();
  if context_at_completion is null
    or pg_catalog.jsonb_typeof(context_at_completion) <> 'object'
    or not context_at_completion ?& array[
      'callerKind', 'tenantId', 'organizationId', 'organizationAccountId',
      'applicationRootId', 'identityId', 'sessionId', 'authenticationStrength',
      'issuedAt', 'expiresAt', 'accessVersion', 'correlationId'
    ]
    or final_decision.outcome is distinct from 'eligible'
    or final_decision.operation_key is distinct from
      'platform.organization.record_lifecycle.manage_policy'
    or final_decision.organization_id is distinct from authority.organization_id
    or final_decision.organization_account_id is distinct from authority.organization_account_id
    or final_decision.access_version is distinct from authority.access_version
    or final_decision.correlation_id is distinct from authority.correlation_id
    or final_decision.target_kind is distinct from 'organization'
    or final_decision.target_application_root_id is not null
    or final_decision.reason_code is not null
    or final_decision.valid_until is null
    or final_decision.checked_at is null
    or final_decision.checked_at > completed_at
    or final_decision.valid_until <= completed_at
    or install_decision.outcome is distinct from 'eligible'
    or install_decision.operation_key is distinct from
      'platform.organization.applications.install'
    or install_decision.organization_id is distinct from authority.organization_id
    or install_decision.organization_account_id is distinct from authority.organization_account_id
    or install_decision.access_version is distinct from authority.access_version
    or install_decision.correlation_id is distinct from authority.correlation_id
    or install_decision.target_kind is distinct from 'organization'
    or install_decision.target_application_root_id is not null
    or install_decision.reason_code is not null
    or install_decision.valid_until is null
    or install_decision.checked_at is null
    or install_decision.checked_at > completed_at
    or install_decision.valid_until <= completed_at
    or install_scope_decision.outcome is distinct from 'eligible'
    or install_scope_decision.operation_key is distinct from
      'platform.organization.applications.install_scope'
    or install_scope_decision.organization_id is distinct from authority.organization_id
    or install_scope_decision.organization_account_id is distinct from
      authority.organization_account_id
    or install_scope_decision.access_version is distinct from authority.access_version
    or install_scope_decision.correlation_id is distinct from authority.correlation_id
    or install_scope_decision.target_kind is distinct from 'organization'
    or install_scope_decision.target_application_root_id is not null
    or install_scope_decision.reason_code is not null
    or install_scope_decision.valid_until is null
    or install_scope_decision.checked_at is null
    or install_scope_decision.checked_at > completed_at
    or install_scope_decision.valid_until <= completed_at
    or context_at_completion ->> 'callerKind' is distinct from 'human'
    or context_at_completion ->> 'tenantId' is distinct from context_after_lock ->> 'tenantId'
    or context_at_completion ->> 'organizationId' is distinct from authority.organization_id::text
    or context_at_completion ->> 'organizationAccountId' is distinct from
      authority.organization_account_id::text
    or context_at_completion ->> 'applicationRootId' is distinct from p_application_root_id::text
    or context_at_completion ->> 'accessVersion' is distinct from authority.access_version::text
    or context_at_completion ->> 'correlationId' is distinct from authority.correlation_id::text
    or context_at_completion ->> 'identityId' is distinct from context_after_lock ->> 'identityId'
    or context_at_completion ->> 'sessionId' is distinct from context_after_lock ->> 'sessionId'
    or context_at_completion ->> 'authenticationStrength' is distinct from
      context_after_lock ->> 'authenticationStrength'
    or context_at_completion ->> 'accessTokenIssuedAt' is distinct from
      context_after_lock ->> 'accessTokenIssuedAt'
    or context_at_completion ->> 'primaryAuthenticatedAt' is distinct from
      context_after_lock ->> 'primaryAuthenticatedAt'
    or context_at_completion ->> 'multiFactorAuthenticatedAt' is distinct from
      context_after_lock ->> 'multiFactorAuthenticatedAt'
    or context_at_completion ->> 'issuedAt' is distinct from context_after_lock ->> 'issuedAt'
    or context_at_completion ->> 'expiresAt' is distinct from context_after_lock ->> 'expiresAt'
    or (context_at_completion ->> 'issuedAt')::timestamptz > completed_at
    or (context_at_completion ->> 'expiresAt')::timestamptz <= completed_at then
    raise exception using errcode = '42501',
      message = 'Provisioned lifecycle setup authority expired';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'registrationRevision', (projection ->> 'registrationRevision')::bigint,
    'organizationLimits', limits_value,
    'targets', targets_value
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Provisioned lifecycle setup evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Provisioned lifecycle setup evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Provisioned lifecycle setup request is invalid';
end
$function$;


ALTER FUNCTION vortex_record.read_provisioned_lifecycle_policy_setup(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION read_provisioned_lifecycle_policy_setup(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.read_provisioned_lifecycle_policy_setup(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Read-only first-install projection of lifecycle limits and exact provisioned storage policies; binds a complete Module projection to current HUMAN policy-management authority.';


--
-- Name: read_record(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_record(
  p_record_type_id uuid,
  p_record_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  loaded jsonb;
  decision jsonb;
  bounds jsonb;
  columns_value jsonb;
  values_value jsonb := '{}'::jsonb;
  field_id text;
  read_time_fields jsonb;
  read_time_clock jsonb;
  read_time_expression jsonb;
  read_time_value jsonb;
  preview_meta jsonb;
  preview_bounds jsonb;
  due_key text;
  status_key text;
  due_value jsonb;
  status_value jsonb;
begin
  if p_record_type_id is null or p_record_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  loaded := vortex_record.load_record_access_facts_internal(p_record_type_id, 'read', p_record_id, null);
  if loaded ->> 'outcome' <> 'loaded'
    or pg_catalog.jsonb_typeof(loaded -> 'declaration') <> 'object' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  if loaded ? 'previewInstallationId' then
    preview_meta := vortex_record.resolve_record_action_context_internal(
      p_record_type_id, 'read'
    );
    preview_bounds := vortex_record.preview_record_field_bounds_internal(
      p_record_type_id, (preview_meta ->> 'storageContractId')::uuid,
      preview_meta -> 'recordType'
    );
    if preview_bounds is null then
      return pg_catalog.jsonb_build_object('outcome', 'refused');
    end if;
    bounds := preview_bounds;
  else
    decision := vortex_access.evaluate_organization_record_access_internal(
      loaded -> 'declaration', p_record_id, loaded -> 'facts'
    );
    if decision ->> 'outcome' <> 'allowed' then
      return pg_catalog.jsonb_build_object('outcome', 'refused');
    end if;
    bounds := vortex_access.resolve_record_field_bounds_internal(decision);
  end if;
  bounds := bounds || pg_catalog.jsonb_build_object('readableFieldIds',
    vortex_record.project_derived_readable_field_ids_internal(
      loaded, p_record_type_id, p_record_id, bounds -> 'readableFieldIds',
      bounds -> 'readableFieldIds', '[]'::jsonb
    )
  );
  columns_value := loaded -> 'columns';
  -- Read-time calculations are worked out here, at one statement timestamp in
  -- the organisation's time zone, from the record's stored values. They are
  -- never read from storage.
  select coalesce(pg_catalog.jsonb_object_agg(pg_catalog.lower(field.value ->> 'fieldId'), field.value), '{}'::jsonb)
  into read_time_fields
  from pg_catalog.jsonb_array_elements(loaded -> 'facts' -> 'recordTypes') as record_type(value)
  cross join lateral pg_catalog.jsonb_array_elements(record_type.value -> 'fields') as field(value)
  where pg_catalog.lower(record_type.value ->> 'recordTypeId') = pg_catalog.lower(p_record_type_id::text)
    and field.value ->> 'type' = 'calculation'
    and (field.value #>> '{settings,evaluation}' = 'read_time'
      or field.value #>> '{settings,expression,kind}' = 'deadline_passed');
  if read_time_fields <> '{}'::jsonb then
    read_time_clock := vortex_record.read_time_clock_internal();
  end if;
  for field_id in
    select item.value #>> '{}' from pg_catalog.jsonb_array_elements(bounds -> 'readableFieldIds') as item(value)
  loop
    if not (columns_value ? field_id) then
      continue;
    end if;
    if read_time_fields ? pg_catalog.lower(field_id) then
      read_time_expression := read_time_fields -> pg_catalog.lower(field_id) #> '{settings,expression}';
      -- Only the deadline-passed form is defined; another read-time form is
      -- withheld rather than disclosed from a stored column.
      if read_time_expression ->> 'kind' is distinct from 'deadline_passed' then
        continue;
      end if;
      due_key := pg_catalog.lower(read_time_expression ->> 'dueFieldId');
      status_key := pg_catalog.lower(read_time_expression ->> 'statusFieldId');
      due_value := loaded -> 'fieldValues' -> due_key;
      status_value := case when status_key is null then null else loaded -> 'fieldValues' -> status_key end;
      if status_value is not null and status_value <> 'null'::jsonb and exists (
        select 1
        from pg_catalog.jsonb_array_elements(coalesce(read_time_expression -> 'terminalStatusValues', '[]'::jsonb))
          as terminal(value)
        where terminal.value = status_value
      ) then
        read_time_value := 'false'::jsonb;
      elsif pg_catalog.jsonb_typeof(due_value) = 'string'
        and loaded -> 'columns' -> due_key ->> 'databaseValueType' = 'date' then
        -- Without the organisation's time zone the local date is unknown.
        if read_time_clock ->> 'organizationLocalDate' is null then
          continue;
        end if;
        read_time_value := pg_catalog.to_jsonb((read_time_clock ->> 'organizationLocalDate') > (due_value #>> '{}'));
      elsif pg_catalog.jsonb_typeof(due_value) = 'string'
        and loaded -> 'columns' -> due_key ->> 'databaseValueType' = 'timestamp_with_time_zone' then
        read_time_value := pg_catalog.to_jsonb(
          (read_time_clock ->> 'instant')::timestamp with time zone
            >= (due_value #>> '{}')::timestamp with time zone
        );
      else
        read_time_value := 'null'::jsonb;
      end if;
      values_value := values_value || pg_catalog.jsonb_build_object(field_id, read_time_value);
    else
      values_value := values_value || pg_catalog.jsonb_build_object(field_id, loaded -> 'fieldValues' -> field_id);
    end if;
  end loop;
  return pg_catalog.jsonb_build_object('outcome', 'allowed', 'recordId', p_record_id,
    'concurrencyNumber', loaded -> 'concurrencyNumber', 'values', values_value);
end
$function$;


ALTER FUNCTION vortex_record.read_record(p_record_type_id uuid, p_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_record(p_record_type_id uuid, p_record_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_record(p_record_type_id uuid, p_record_id uuid) IS 'Fixed record read adapter: returns the readable field projection of one live record under the caller''s current authority or one preview record for its validated preview owner, or an identical refusal for a missing, foreign or unreachable record.';


--
-- Name: read_record_capabilities(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_record_capabilities(
  p_record_type_id uuid,
  p_record_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  read_loaded jsonb;
  read_decision jsonb;
  read_bounds jsonb;
  preview_bounds jsonb;
  readable_field_ids jsonb;
  meta jsonb;
  changeable_field_ids jsonb := '[]'::jsonb;
  actions text[] := array[]::text[];
  action_kind text;
  action_loaded jsonb;
  action_decision jsonb;
begin
  if p_record_type_id is null or p_record_type_id = nil_uuid
    or p_record_id is null or p_record_id = nil_uuid then
    return null;
  end if;

  -- The row must be readable under the exact decision read_record applies, over
  -- the same fact loader; an unreadable row has no capabilities to report.
  read_loaded := vortex_record.load_record_access_facts_internal(
    p_record_type_id, 'read', p_record_id, null
  );
  if read_loaded ->> 'outcome' <> 'loaded'
    or (not (read_loaded ? 'previewInstallationId')
      and pg_catalog.jsonb_typeof(read_loaded -> 'declaration') <> 'object') then
    return null;
  end if;
  if read_loaded ? 'previewInstallationId' then
    meta := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'read');
    preview_bounds := vortex_record.preview_record_field_bounds_internal(
      p_record_type_id, (meta ->> 'storageContractId')::uuid,
      meta -> 'recordType'
    );
    if preview_bounds is null then
      return null;
    end if;
    read_bounds := preview_bounds;
  else
    read_decision := vortex_access.evaluate_organization_record_access_internal(
      read_loaded -> 'declaration', p_record_id, read_loaded -> 'facts'
    );
    if read_decision ->> 'outcome' <> 'allowed' then
      return null;
    end if;
    read_bounds := vortex_access.resolve_record_field_bounds_internal(read_decision);
  end if;
  readable_field_ids := vortex_record.project_derived_readable_field_ids_internal(
    read_loaded, p_record_type_id, p_record_id,
    read_bounds -> 'readableFieldIds', read_bounds -> 'readableFieldIds', '[]'::jsonb
  );

  if read_loaded ? 'previewInstallationId' then
    select coalesce(
      pg_catalog.jsonb_agg(projected.value order by projected.value), '[]'::jsonb
    )
    into changeable_field_ids
    from pg_catalog.jsonb_array_elements_text(readable_field_ids) as projected(value)
    where exists (
      select 1
      from pg_catalog.jsonb_array_elements_text(
        preview_bounds -> 'changeableFieldIds'
      ) as changeable(value)
      where pg_catalog.lower(changeable.value) = pg_catalog.lower(projected.value)
    );
    if pg_catalog.jsonb_array_length(changeable_field_ids) > 0 then
      actions := array['update'];
    end if;
    return pg_catalog.jsonb_build_object(
      'changeableFieldIds', changeable_field_ids,
      'actions', pg_catalog.to_jsonb(actions)
    );
  end if;

  meta := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'read');
  if meta #>> '{recordType,key}' = 'organization_settings'
    and meta #>> '{recordType,systemProjection,protectedView}' =
      'organization_runtime_settings'
    and coalesce((meta #> '{recordType,standardActions}') ? 'update', false)
    and exists (
      select 1
      from vortex_definition.roots as root
      where root.root_id = (meta ->> 'moduleRootId')::uuid
        and root.kind = 'module'
        and root.key = 'vortex.organisation_administration'
    ) then
    if vortex_access.organization_runtime_settings_manage_is_current() then
      select coalesce(
        pg_catalog.jsonb_agg(projected.value order by projected.value), '[]'::jsonb
      )
      into changeable_field_ids
      from pg_catalog.jsonb_array_elements_text(readable_field_ids) as projected(value)
      join pg_catalog.jsonb_array_elements(meta #> '{recordType,fields}') as field(value)
        on pg_catalog.lower(field.value ->> 'fieldId') = pg_catalog.lower(projected.value)
      where field.value ->> 'key' not in ('organization_id', 'revision')
        and field.value ->> 'type' not in (
          'reference_number', 'table', 'link', 'link_to_one_of_several', 'total',
          'attachment', 'calculation'
        );
      if pg_catalog.jsonb_array_length(changeable_field_ids) > 0 then
        actions := array['update'];
      end if;
    end if;
    return pg_catalog.jsonb_build_object(
      'changeableFieldIds', changeable_field_ids,
      'actions', pg_catalog.to_jsonb(actions)
    );
  end if;

  -- Each record action kind is decided exactly as its own writer decides it: the
  -- same fact loader for that action kind and the same complete exact-record
  -- evaluation. An action is reported only when its own decision allows this
  -- exact record; a missing declaration contributes no action.
  foreach action_kind in array array['update', 'delete', 'restore'] loop
    action_loaded := vortex_record.load_record_access_facts_internal(
      p_record_type_id, action_kind, p_record_id, null
    );
    if action_loaded ->> 'outcome' = 'loaded'
      and pg_catalog.jsonb_typeof(action_loaded -> 'declaration') = 'object' then
      action_decision := vortex_access.evaluate_organization_record_access_internal(
        action_loaded -> 'declaration', p_record_id, action_loaded -> 'facts'
      );
      if action_decision ->> 'outcome' = 'allowed' then
        actions := pg_catalog.array_append(actions, action_kind);
        -- The changeable fields are the update decision's own field bounds, the
        -- set the record save enforces, narrowed to the fields read_record
        -- projects for this row, so no hidden field is ever reported.
        if action_kind = 'update' then
          changeable_field_ids := coalesce((
            select pg_catalog.jsonb_agg(projected.value order by projected.value)
            from pg_catalog.jsonb_array_elements_text(readable_field_ids) as projected(value)
            where exists (
              select 1
              from pg_catalog.jsonb_array_elements_text(
                vortex_access.resolve_record_field_bounds_internal(action_decision)
                  -> 'changeableFieldIds'
              ) as changeable(value)
              where pg_catalog.lower(changeable.value) = pg_catalog.lower(projected.value)
            )
          ), '[]'::jsonb);
        end if;
      end if;
    end if;
  end loop;

  -- Changing a row needs at least one field it may change, so update is never
  -- reported without one.
  if pg_catalog.jsonb_array_length(changeable_field_ids) = 0 then
    actions := pg_catalog.array_remove(actions, 'update');
  end if;

  return pg_catalog.jsonb_build_object(
    'changeableFieldIds', changeable_field_ids,
    'actions', pg_catalog.to_jsonb(actions)
  );
end
$function$;


ALTER FUNCTION vortex_record.read_record_capabilities(p_record_type_id uuid, p_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_record_capabilities(p_record_type_id uuid, p_record_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_record_capabilities(p_record_type_id uuid, p_record_id uuid) IS 'Fixed record capabilities adapter: for one live record readable under the caller''s current authority or one owner-readable preview record, returns only permitted update, delete and restore actions and changeable fields; preview capabilities are limited to supported updates, and missing, foreign or unreadable records return null.';


--
-- Name: read_record_lifecycle_preview_candidates_internal(text, uuid, uuid, uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.read_record_lifecycle_preview_candidates_internal(p_physical_table_token text, p_organization_id uuid, p_storage_contract_id uuid, p_application_root_id uuid, p_after_created_at timestamp with time zone, p_after_record_id uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  result_value jsonb;
begin
  if p_physical_table_token is null
    or p_physical_table_token !~ '^rt_[a-f0-9]{32}$'
    or p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (p_application_root_id is not null
      and p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid)
    or p_limit is null
    or p_limit not between 1 and 500
    or ((p_after_created_at is null) <> (p_after_record_id is null))
    or (p_after_record_id is not null
      and p_after_record_id = '00000000-0000-0000-0000-000000000000'::uuid)
    or p_organization_id <> vortex_context.organization_id()
    or p_application_root_id is distinct from vortex_context.application_root_id(false) then
    raise exception using errcode = '42501',
      message = 'Record lifecycle preview candidates are unavailable';
  end if;

  execute pg_catalog.format(
    'with ranked as materialized (
       select stored.record_id,
              stored.concurrency_number,
              stored.created_at,
              stored.lifecycle_state,
              stored.deleted_at,
              pg_catalog.row_number() over (
                order by stored.created_at asc, stored.record_id asc
              )::bigint as record_position,
              pg_catalog.count(*) over ()::bigint as total_retained_count
       from record_data.%I as stored
       where stored.organisation_id = $1
         and stored.storage_contract_id = $2
         and stored.application_root_id is not distinct from $3
         and stored.lifecycle_state in (''active'', ''soft_deleted'', ''removal_pending'')
     ), page as materialized (
       select ranked.*
       from ranked
       where $5::timestamptz is null
          or ranked.created_at > $5
          or (ranked.created_at = $5 and ranked.record_id > $6)
       order by ranked.created_at asc, ranked.record_id asc
       limit $4 + 1
     ), selected as materialized (
       select page.*
       from page
       order by page.created_at asc, page.record_id asc
       limit $4
     )
     select pg_catalog.jsonb_build_object(
       ''totalRetainedCount'', coalesce(
         (select ranked.total_retained_count from ranked limit 1), 0
       ),
       ''records'', coalesce((
         select pg_catalog.jsonb_agg(
           pg_catalog.jsonb_build_object(
             ''recordId'', selected.record_id,
             ''expectedRecordRevision'', selected.concurrency_number,
             ''createdAt'', pg_catalog.to_jsonb(selected.created_at),
             ''lifecycleState'', selected.lifecycle_state,
             ''deletedAt'', pg_catalog.to_jsonb(selected.deleted_at),
             ''recordPosition'', selected.record_position
           ) order by selected.created_at asc, selected.record_id asc
         )
         from selected
       ), ''[]''::jsonb),
       ''hasMore'', (select pg_catalog.count(*) > $4 from page)
     )',
    p_physical_table_token
  ) into strict result_value using
    p_organization_id, p_storage_contract_id, p_application_root_id,
    p_limit, p_after_created_at, p_after_record_id;

  return result_value;
end
$_$;


ALTER FUNCTION vortex_record.read_record_lifecycle_preview_candidates_internal(p_physical_table_token text, p_organization_id uuid, p_storage_contract_id uuid, p_application_root_id uuid, p_after_created_at timestamp with time zone, p_after_record_id uuid, p_limit integer) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_record_lifecycle_preview_candidates_internal(p_physical_table_token text, p_organization_id uuid, p_storage_contract_id uuid, p_application_root_id uuid, p_after_created_at timestamp with time zone, p_after_record_id uuid, p_limit integer); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_record_lifecycle_preview_candidates_internal(p_physical_table_token text, p_organization_id uuid, p_storage_contract_id uuid, p_application_root_id uuid, p_after_created_at timestamp with time zone, p_after_record_id uuid, p_limit integer) IS 'Private adapter-owned, forced-RLS lifecycle candidate page and global-position projection for Record owner.';


--
-- Name: read_storage_conversion_corrections(uuid, integer); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.read_storage_conversion_corrections(p_conversion_contract_id uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  authority jsonb;
  organisation_id_value uuid;
  scope_application_root_id uuid;
  conversion vortex_record.storage_conversion_catalogue%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  count_sql text;
  list_sql text;
  correction_row record;
  changed_count bigint := 0;
  corrections jsonb := '[]'::jsonb;
begin
  if p_conversion_contract_id is null
    or p_conversion_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_limit is null or p_limit not between 1 and 1000 then
    raise exception using errcode = '22023',
      message = 'Storage conversion correction command is invalid';
  end if;

  select entry.* into conversion
  from vortex_record.storage_conversion_catalogue as entry
  where entry.conversion_contract_id = p_conversion_contract_id;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Storage conversion plan is unavailable';
  end if;

  authority := vortex_record.authorize_storage_conversion_internal(
    conversion.source_storage_contract_id, conversion.source_release_revision
  );
  organisation_id_value := (authority ->> 'organizationId')::uuid;
  scope_application_root_id := (authority ->> 'applicationRootId')::uuid;

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = conversion.source_storage_contract_id;
  if not found or catalogue_row.state <> 'active' then
    raise exception using errcode = '55000',
      message = 'Storage conversion contract is unavailable';
  end if;

  count_sql := pg_catalog.format(
    'select pg_catalog.count(*)'
      || ' from record_data.%I as stored'
      || ' join vortex_record.storage_conversion_progress as progress'
      || ' on progress.conversion_contract_id = $1::uuid'
      || ' and progress.organisation_id = stored.organisation_id'
      || ' and progress.application_root_id is not distinct from stored.application_root_id'
      || ' and progress.record_id = stored.record_id'
      || ' where stored.organisation_id = $2::uuid'
      || ' and stored.application_root_id is not distinct from $3::uuid'
      || ' and progress.source_concurrency_number <> stored.concurrency_number',
    catalogue_row.physical_table_token
  );
  execute count_sql into changed_count
    using p_conversion_contract_id, organisation_id_value, scope_application_root_id;

  list_sql := pg_catalog.format(
    'select stored.record_id, progress.source_concurrency_number,'
      || ' stored.concurrency_number'
      || ' from record_data.%I as stored'
      || ' join vortex_record.storage_conversion_progress as progress'
      || ' on progress.conversion_contract_id = $1::uuid'
      || ' and progress.organisation_id = stored.organisation_id'
      || ' and progress.application_root_id is not distinct from stored.application_root_id'
      || ' and progress.record_id = stored.record_id'
      || ' where stored.organisation_id = $2::uuid'
      || ' and stored.application_root_id is not distinct from $3::uuid'
      || ' and progress.source_concurrency_number <> stored.concurrency_number'
      || ' order by stored.record_id'
      || ' limit $4::integer',
    catalogue_row.physical_table_token
  );
  for correction_row in execute list_sql
    using p_conversion_contract_id, organisation_id_value,
      scope_application_root_id, p_limit
  loop
    corrections := corrections || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'recordId', correction_row.record_id,
        'sourceConcurrencyNumber', correction_row.source_concurrency_number,
        'currentConcurrencyNumber', correction_row.concurrency_number
      )
    );
  end loop;

  return pg_catalog.jsonb_build_object(
    'conversionContractId', conversion.conversion_contract_id,
    'organisationId', organisation_id_value,
    'applicationRootId', scope_application_root_id,
    'conversionSemantic', conversion.conversion_semantic,
    'changedCount', changed_count,
    'corrections', corrections
  );
exception
  when no_data_found or too_many_rows then
    raise exception using errcode = '55000',
      message = 'Storage conversion correction evidence is unavailable';
end
$_$;


ALTER FUNCTION vortex_record.read_storage_conversion_corrections(p_conversion_contract_id uuid, p_limit integer) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_storage_conversion_corrections(p_conversion_contract_id uuid, p_limit integer); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_storage_conversion_corrections(p_conversion_contract_id uuid, p_limit integer) IS 'Authorised correction facts for the caller''s scope: converted record ids whose live concurrency revision differs from the recorded source revision, with no field values or physical names.';


--
-- Name: read_time_clock_internal(); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_time_clock_internal()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  zone_value text;
  instant_value timestamp with time zone := pg_catalog.statement_timestamp();
begin
  context_value := vortex_access.validated_human_request_context();
  -- No time zone is ever assumed: without the organisation's own settings the
  -- local date is unknown, so a date deadline is withheld or refused rather
  -- than worked out in the wrong zone. Exact-instant deadlines need no zone.
  zone_value := vortex_identity.read_organization_time_zone_internal(
    (context_value ->> 'organizationId')::uuid
  );
  return pg_catalog.jsonb_build_object(
    'instant', vortex_context.format_timestamp_utc(instant_value),
    'organizationLocalDate', case when zone_value is null then null else pg_catalog.to_char(
      pg_catalog.timezone(zone_value, instant_value), 'YYYY-MM-DD'
    ) end,
    'timeZone', zone_value
  );
end
$function$;


ALTER FUNCTION vortex_record.read_time_clock_internal() OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_time_clock_internal(); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_time_clock_internal() IS 'The one statement timestamp and the current date in the organisation time zone of the validated request context (null when the organisation has no time zone), which every read-time calculation in a statement uses; owner-only.';


--
-- Name: read_time_deadline_expression_internal(uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.read_time_deadline_expression_internal(
  p_storage_contract_id uuid,
  p_expression jsonb,
  p_clock jsonb
)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  due_mapping vortex_record.field_storage_mappings%rowtype;
  status_mapping vortex_record.field_storage_mappings%rowtype;
  terminal_values jsonb;
  terminal_sql text := 'false';
  comparison_sql text;
begin
  if p_storage_contract_id is null or p_clock is null
    or pg_catalog.jsonb_typeof(p_expression) is distinct from 'object'
    or p_expression ->> 'kind' is distinct from 'deadline_passed'
    or pg_catalog.jsonb_typeof(p_expression -> 'dueFieldId') is distinct from 'string'
    or pg_catalog.jsonb_typeof(p_clock -> 'instant') is distinct from 'string' then
    return null;
  end if;
  select mapping.* into due_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = p_storage_contract_id
    and mapping.field_id = (pg_catalog.lower(p_expression ->> 'dueFieldId'))::uuid;
  if not found or due_mapping.state <> 'active' then
    raise exception using errcode = '55000',
      message = 'Record storage disagrees with the installed definition';
  end if;
  if due_mapping.database_value_type not in ('date', 'timestamp_with_time_zone')
    or (due_mapping.database_value_type = 'date'
      and pg_catalog.jsonb_typeof(p_clock -> 'organizationLocalDate') is distinct from 'string') then
    return null;
  end if;
  if pg_catalog.jsonb_typeof(p_expression -> 'statusFieldId') = 'string' then
    terminal_values := coalesce(p_expression -> 'terminalStatusValues', '[]'::jsonb);
    if pg_catalog.jsonb_typeof(terminal_values) <> 'array' then
      return null;
    end if;
    select mapping.* into status_mapping
    from vortex_record.field_storage_mappings as mapping
    where mapping.storage_contract_id = p_storage_contract_id
      and mapping.field_id = (pg_catalog.lower(p_expression ->> 'statusFieldId'))::uuid;
    if not found or status_mapping.state <> 'active' then
      raise exception using errcode = '55000',
        message = 'Record storage disagrees with the installed definition';
    end if;
    if status_mapping.database_value_type not in ('text', 'integer', 'boolean', 'uuid') then
      return null;
    end if;
    if pg_catalog.jsonb_array_length(terminal_values) > 0 then
      terminal_sql := pg_catalog.format(
        '(stored.%I is not null and pg_catalog.to_jsonb(stored.%I) in (%s))',
        status_mapping.physical_column_token, status_mapping.physical_column_token,
        (select pg_catalog.string_agg(pg_catalog.format('%L::jsonb', terminal.value::text), ', ')
         from pg_catalog.jsonb_array_elements(terminal_values) as terminal(value))
      );
    end if;
  end if;
  comparison_sql := case due_mapping.database_value_type
    when 'date' then pg_catalog.format(
      '%L::date > stored.%I', p_clock ->> 'organizationLocalDate', due_mapping.physical_column_token)
    else pg_catalog.format(
      '%L::timestamp with time zone >= stored.%I', p_clock ->> 'instant', due_mapping.physical_column_token)
  end;
  return pg_catalog.format(
    '(case when %s then false when stored.%I is null then null else %s end)',
    terminal_sql, due_mapping.physical_column_token, comparison_sql
  );
end
$function$;


ALTER FUNCTION vortex_record.read_time_deadline_expression_internal(p_storage_contract_id uuid, p_expression jsonb, p_clock jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION read_time_deadline_expression_internal(p_storage_contract_id uuid, p_expression jsonb, p_clock jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.read_time_deadline_expression_internal(p_storage_contract_id uuid, p_expression jsonb, p_clock jsonb) IS 'Compiles one deadline-passed calculation to a boolean SQL expression over the stored due and status columns of the record alias, using the supplied statement clock, or returns null when the calculation cannot be compiled; owner-only.';


--
-- Name: record_index_build_result(uuid, uuid, uuid, text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.record_index_build_result(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_expected_definition_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  catalogue_row vortex_record.index_catalogue%rowtype;
  storage_row vortex_record.storage_catalogue%rowtype;
  mapping_row vortex_record.field_storage_mappings%rowtype;
  mapping_purpose text;
  scope_columns text;
  derived_fingerprint text;
  observed text;
  refusal_reason text;
begin
  if p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_field_id is null
    or p_field_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_claim_id is null
    or p_expected_definition_fingerprint is null
    or p_expected_definition_fingerprint !~ '^sha256:[a-f0-9]{64}$' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'command_invalid'
    );
  end if;

  select catalogue.* into catalogue_row
  from vortex_record.index_catalogue as catalogue
  where catalogue.storage_contract_id = p_storage_contract_id
    and catalogue.field_id = p_field_id
  for update;
  if catalogue_row.index_contract_id is null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'index_unknown'
    );
  end if;
  if catalogue_row.claim_id is distinct from p_claim_id then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'lease_not_owned'
    );
  end if;

  -- A newer or different desired definition superseded this build.
  if catalogue_row.desired_definition_fingerprint
      is distinct from p_expected_definition_fingerprint then
    refusal_reason := 'desired_definition_changed';
  end if;

  if refusal_reason is null then
    select storage.* into storage_row
    from vortex_record.storage_catalogue as storage
    where storage.storage_contract_id = p_storage_contract_id;
    select stored.* into mapping_row
    from vortex_record.field_storage_mappings as stored
    where stored.storage_contract_id = p_storage_contract_id
      and stored.field_id = p_field_id;
    scope_columns := vortex_record.index_scope_columns(storage_row.storage_scope);
    if storage_row.storage_contract_id is null
      or storage_row.state <> 'active'
      or storage_row.physical_schema_token <> 'record_data'
      or mapping_row.storage_contract_id is null
      or mapping_row.state <> 'active'
      or scope_columns is null then
      refusal_reason := 'storage_contract_unavailable';
    end if;
  end if;

  if refusal_reason is null then
    mapping_purpose := case
      when coalesce((mapping_row.field_definition ->> 'unique')::boolean, false)
        then 'uniqueness'
      when coalesce((mapping_row.field_definition ->> 'filterable')::boolean, false)
        or coalesce((mapping_row.field_definition ->> 'sortable')::boolean, false)
        then 'performance'
      else null
    end;
    derived_fingerprint := vortex_record.index_definition_fingerprint(
      catalogue_row.purpose, storage_row.physical_table_token, scope_columns,
      mapping_row.physical_column_token
    );
    if mapping_purpose is distinct from catalogue_row.purpose
      or derived_fingerprint is distinct from p_expected_definition_fingerprint
      or catalogue_row.physical_index_token is distinct from
        (case catalogue_row.purpose when 'uniqueness' then 'ux_' else 'ix_' end
          || pg_catalog.substr(mapping_row.physical_column_token, 3)) then
      refusal_reason := 'definition_mismatch';
    end if;
  end if;

  if refusal_reason is not null then
    update vortex_record.index_catalogue as catalogue
    set claim_id = null, claimed_by = null, claimed_at = null, lease_expires_at = null
    where catalogue.storage_contract_id = p_storage_contract_id
      and catalogue.field_id = p_field_id;
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', refusal_reason
    );
  end if;

  observed := vortex_record.observe_field_index_internal(
    catalogue_row.purpose, storage_row.physical_table_token, scope_columns,
    mapping_row.physical_column_token
  );

  update vortex_record.index_catalogue as catalogue
  set observed_state = observed,
    observed_revision = case when observed is distinct from catalogue_row.observed_state
      then catalogue_row.observed_revision + 1
      else catalogue_row.observed_revision end,
    claim_id = null,
    claimed_by = null,
    claimed_at = null,
    lease_expires_at = null,
    changed_at = pg_catalog.statement_timestamp()
  where catalogue.storage_contract_id = p_storage_contract_id
    and catalogue.field_id = p_field_id;

  return pg_catalog.jsonb_build_object(
    'outcome', observed,
    'indexContractId', catalogue_row.index_contract_id,
    'storageContractId', catalogue_row.storage_contract_id,
    'fieldId', catalogue_row.field_id,
    'purpose', catalogue_row.purpose,
    'desiredDefinitionFingerprint', derived_fingerprint,
    'observedState', observed
  );
end
$_$;


ALTER FUNCTION vortex_record.record_index_build_result(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_expected_definition_fingerprint text) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION record_index_build_result(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_expected_definition_fingerprint text); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.record_index_build_result(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_expected_definition_fingerprint text) IS 'Records the observed physical state of a leased index build, marking present only when the live definition matches the claimed fingerprint.';


--
-- Name: record_lifecycle_command_fingerprint_internal(uuid, text, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.record_lifecycle_command_fingerprint_internal(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'contractVersion', '1.0.0',
        'commandId', p_command_id,
        'operation', p_operation,
        'recordTypeId', p_record_type_id,
        'recordId', p_record_id,
        'expectedConcurrencyNumber', p_expected_concurrency_number
      )::text, 'UTF8'
    )), 'hex'
  )
$$;


ALTER FUNCTION vortex_record.record_lifecycle_command_fingerprint_internal(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) OWNER TO vortex_record_adapter;

--
-- Name: record_lifecycle_current_revision_internal(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.record_lifecycle_current_revision_internal(p_record_type_id uuid, p_record_id uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  loaded jsonb;
  decision jsonb;
begin
  begin
    loaded := vortex_record.load_record_access_facts_internal(
      p_record_type_id, 'delete', p_record_id, null
    );
    if loaded ->> 'outcome' is distinct from 'loaded'
      or pg_catalog.jsonb_typeof(loaded -> 'declaration') is distinct from 'object' then
      return null;
    end if;
    decision := vortex_access.evaluate_organization_record_access_internal(
      loaded -> 'declaration', p_record_id, loaded -> 'facts'
    );
    if decision ->> 'outcome' is distinct from 'allowed' then
      return null;
    end if;
    return (loaded ->> 'concurrencyNumber')::bigint;
  exception
    when others then
      return null;
  end;
end
$$;


ALTER FUNCTION vortex_record.record_lifecycle_current_revision_internal(p_record_type_id uuid, p_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: record_lifecycle_total_closure_internal(jsonb, text, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.record_lifecycle_total_closure_internal(
  p_catalogue jsonb,
  p_operation text,
  p_record_type_id uuid,
  p_record_id uuid,
  p_command_id uuid
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  context_value jsonb;
  context_organization_id uuid;
  context_application_id uuid;
  context_actor_id uuid;
  seed record;
  seed_key text;
  closure_value jsonb;
  closure_record jsonb;
  record_key text;
  records jsonb := '[]'::jsonb;
  record_keys text[] := array[]::text[];
  signatures jsonb := '[]'::jsonb;
begin
  if p_operation = 'restore' then
    return vortex_record.discover_relationship_total_closure_internal(
      p_catalogue, 'update', p_record_type_id, p_record_id, '{}'::jsonb
    );
  end if;
  if p_operation is distinct from 'delete' or p_command_id is null
    or pg_catalog.jsonb_typeof(p_catalogue -> 'recordTypes') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_catalogue -> 'relationships') is distinct from 'array' then
    return null;
  end if;
  context_value := vortex_access.validated_human_request_context();
  context_organization_id := (context_value ->> 'organizationId')::uuid;
  context_application_id := (context_value ->> 'applicationRootId')::uuid;
  context_actor_id := (context_value ->> 'organizationAccountId')::uuid;

  for seed in
    select distinct
      (target_type.value ->> 'recordTypeId')::uuid as record_type_id,
      edge.to_storage_contract_id as storage_contract_id,
      edge.to_record_id as record_id
    from vortex_record.record_lifecycle_command_effects as effect
    join vortex_record.relationship_edges as edge
      on edge.from_organisation_id = effect.organization_id
     and edge.from_storage_contract_id = effect.storage_contract_id
     and edge.from_record_id = effect.record_id
    cross join lateral (
      select item.value
      from pg_catalog.jsonb_array_elements(p_catalogue -> 'relationships') as item(value)
      where pg_catalog.lower(item.value ->> 'relationshipId') =
          pg_catalog.lower(edge.relationship_id::text)
        and item.value ->> 'cardinality' in ('one_to_one', 'many_to_one')
    ) as relationship
    cross join lateral (
      select item.value
      from pg_catalog.jsonb_array_elements(p_catalogue -> 'recordTypes') as item(value)
      where (item.value ->> 'storageContractId')::uuid = edge.to_storage_contract_id
        and vortex_record.relationship_declares_target_internal(
          relationship.value, (item.value ->> 'recordTypeId')::uuid
        )
    ) as target_type
    where effect.organization_id = context_organization_id
      and effect.application_root_id = context_application_id
      and effect.actor_organization_account_id = context_actor_id
      and effect.command_id = p_command_id
      and effect.effect_kind = 'soft_deleted'
      and edge.to_organisation_id = context_organization_id
      and edge.to_application_root_id is not distinct from case
        when target_type.value ->> 'storageScope' = 'application_contained'
          then context_application_id else null end
      and exists (
        select 1
        from pg_catalog.jsonb_array_elements(target_type.value -> 'fields') as field(value)
        where field.value ->> 'type' = 'total'
          and pg_catalog.lower(field.value #>> '{settings,relationshipId}') =
            pg_catalog.lower(relationship.value ->> 'relationshipId')
      )
      and not exists (
        select 1 from vortex_record.record_lifecycle_command_effects as deleted
        where deleted.organization_id = effect.organization_id
          and deleted.application_root_id = effect.application_root_id
          and deleted.actor_organization_account_id = effect.actor_organization_account_id
          and deleted.command_id = effect.command_id
          and deleted.effect_kind = 'soft_deleted'
          and deleted.storage_contract_id = edge.to_storage_contract_id
          and deleted.record_id = edge.to_record_id
      )
    order by 2, 3
  loop
    seed_key := pg_catalog.lower(seed.record_type_id::text) || ':'
      || pg_catalog.lower(seed.record_id::text);
    -- A parent already reached is complete: discovery follows every
    -- transitive total parent of each member it adds.
    if seed_key = any (record_keys) then
      continue;
    end if;
    closure_value := vortex_record.discover_relationship_total_closure_internal(
      p_catalogue, 'update', seed.record_type_id, seed.record_id, '{}'::jsonb
    );
    if closure_value is null then
      return null;
    end if;
    for closure_record in
      select item.value
      from pg_catalog.jsonb_array_elements(closure_value -> 'records') as item(value)
    loop
      record_key := case when closure_record ->> 'recordKey' = 'root'
        then seed_key else closure_record ->> 'recordKey' end;
      if record_key = any (record_keys) then
        continue;
      end if;
      records := records || pg_catalog.jsonb_build_array(
        closure_record || pg_catalog.jsonb_build_object('recordKey', record_key)
      );
      record_keys := pg_catalog.array_append(record_keys, record_key);
    end loop;
    signatures := signatures || coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'from', case when item.value ->> 'from' = 'root'
          then seed_key else item.value ->> 'from' end,
        'relationshipId', item.value -> 'relationshipId',
        'to', case when item.value ->> 'to' = 'root'
          then seed_key else item.value ->> 'to' end
      ))
      from pg_catalog.jsonb_array_elements(closure_value -> 'signatures') as item(value)
    ), '[]'::jsonb);
  end loop;

  return pg_catalog.jsonb_build_object(
    'records', records,
    'signatures', coalesce((
      select pg_catalog.jsonb_agg(distinct item.value order by item.value)
      from pg_catalog.jsonb_array_elements(signatures) as item(value)
    ), '[]'::jsonb)
  );
end
$function$;


ALTER FUNCTION vortex_record.record_lifecycle_total_closure_internal(p_catalogue jsonb, p_operation text, p_record_type_id uuid, p_record_id uuid, p_command_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: record_named_action_precondition_refusal(text, uuid, bigint, uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.record_named_action_precondition_refusal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_activity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  loaded jsonb;
  decision jsonb;
  context_value jsonb;
begin
  context_value := vortex_access.validated_human_request_context();
  loaded := vortex_record.load_named_action_facts_internal(
    p_action_owner_kind, p_action_owner_id, p_action_release_revision,
    p_action_id, p_record_type_id, p_record_id, p_expected_concurrency_number
  );
  if loaded ->> 'outcome' <> 'loaded' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  decision := vortex_access.evaluate_organization_record_access_internal(
    loaded -> 'declaration', p_record_id, loaded -> 'facts'
  );
  if decision ->> 'outcome' <> 'allowed' then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;
  perform vortex_record.append_named_action_activity_internal(
    p_activity_id, p_record_id, array[]::uuid[], 'refused'
  );
  return pg_catalog.jsonb_build_object(
    'outcome', 'refused_recorded', 'correlationId', context_value -> 'correlationId'
  );
end
$$;


ALTER FUNCTION vortex_record.record_named_action_precondition_refusal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_activity_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: register_storage_conversion_plan(uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

create or replace function vortex_record.register_storage_conversion_plan(
  p_source_storage_contract_id uuid,
  p_source_field_id uuid,
  p_target_field_id uuid,
  p_source_release_revision bigint,
  p_target_release_revision bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  authority jsonb;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  source_mapping vortex_record.field_storage_mappings%rowtype;
  target_mapping vortex_record.field_storage_mappings%rowtype;
  source_release vortex_definition.releases%rowtype;
  target_release vortex_definition.releases%rowtype;
  source_record_types jsonb;
  target_record_types jsonb;
  source_field jsonb;
  target_field jsonb;
  semantic text;
  conversion_id uuid;
  inserted_count integer;
  stored vortex_record.storage_conversion_catalogue%rowtype;
begin
  if p_source_storage_contract_id is null
    or p_source_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_source_field_id is null
    or p_source_field_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_target_field_id is null
    or p_target_field_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_source_field_id = p_target_field_id
    or p_source_release_revision is null
    or p_source_release_revision not between 1 and 9007199254740991
    or p_target_release_revision is null
    or p_target_release_revision not between 1 and 9007199254740991
    or p_target_release_revision <= p_source_release_revision then
    raise exception using errcode = '22023',
      message = 'Storage conversion registration command is invalid';
  end if;

  authority := vortex_record.authorize_storage_conversion_internal(
    p_source_storage_contract_id, null
  );
  if not (authority ->> 'ownsModule')::boolean then
    raise exception using errcode = '42501',
      message = 'Storage conversion registration requires the Module owner';
  end if;

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = p_source_storage_contract_id;
  if not found or catalogue_row.state <> 'active'
    or p_source_release_revision < catalogue_row.first_compatible_release_revision
    or (
      catalogue_row.last_compatible_release_revision is not null
      and p_source_release_revision > catalogue_row.last_compatible_release_revision
    ) then
    raise exception using errcode = '55000',
      message = 'Storage conversion source contract is unavailable';
  end if;

  select mapping.* into source_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = p_source_storage_contract_id
    and mapping.field_id = p_source_field_id;
  if not found or source_mapping.state <> 'active' then
    raise exception using errcode = '55000',
      message = 'Storage conversion source field is not active';
  end if;

  -- A target field that is already stored (active or retired) is not a
  -- conversion target; only an absent or already-planned target qualifies.
  select mapping.* into target_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = p_source_storage_contract_id
    and mapping.field_id = p_target_field_id;
  if found and target_mapping.state <> 'planned' then
    raise exception using errcode = '55000',
      message = 'Storage conversion target field is already stored';
  end if;

  select release.* into source_release
  from vortex_definition.releases as release
  where release.root_id = catalogue_row.module_root_id
    and release.release_revision = p_source_release_revision;
  if not found
    or source_release.validation_contract_version <> all (vortex_definition.accepted_contract_version('module_storage_conversion'))
    or source_release.compilation_output #>> '{kind}' <> 'module'
    or source_release.compilation_output #>> '{canonical,envelope,rootId}'
      <> catalogue_row.module_root_id::text
    or source_release.compilation_output #>> '{validationContractVersion}' <> all (vortex_definition.accepted_contract_version('module_storage_conversion')) then
    raise exception using errcode = '23514',
      message = 'Exact storage conversion source release is incompatible';
  end if;

  select release.* into target_release
  from vortex_definition.releases as release
  where release.root_id = catalogue_row.module_root_id
    and release.release_revision = p_target_release_revision;
  if not found
    or target_release.validation_contract_version <> all (vortex_definition.accepted_contract_version('module_storage_conversion'))
    or target_release.compilation_output #>> '{kind}' <> 'module'
    or target_release.compilation_output #>> '{canonical,envelope,rootId}'
      <> catalogue_row.module_root_id::text
    or target_release.compilation_output #>> '{validationContractVersion}' <> all (vortex_definition.accepted_contract_version('module_storage_conversion')) then
    raise exception using errcode = '23514',
      message = 'Exact storage conversion target release is incompatible';
  end if;

  source_record_types := source_release.compilation_output
    #> '{canonical,content,recordTypes}';
  target_record_types := target_release.compilation_output
    #> '{canonical,content,recordTypes}';
  if pg_catalog.jsonb_typeof(source_record_types) is distinct from 'array'
    or pg_catalog.jsonb_typeof(target_record_types) is distinct from 'array' then
    raise exception using errcode = '23514',
      message = 'Storage conversion release content is incompatible';
  end if;

  select field_item.value into source_field
  from pg_catalog.jsonb_array_elements(source_record_types) as record_item(value)
  cross join lateral pg_catalog.jsonb_array_elements(
    record_item.value -> 'fields'
  ) as field_item(value)
  where (record_item.value ->> 'storageContractId')::uuid = p_source_storage_contract_id
    and (field_item.value ->> 'fieldId')::uuid = p_source_field_id;
  if source_field is null
    or vortex_record.database_value_type(source_field)
      is distinct from source_mapping.database_value_type then
    raise exception using errcode = '55000',
      message = 'Storage conversion source field evidence is incompatible';
  end if;

  select field_item.value into target_field
  from pg_catalog.jsonb_array_elements(target_record_types) as record_item(value)
  cross join lateral pg_catalog.jsonb_array_elements(
    record_item.value -> 'fields'
  ) as field_item(value)
  where (record_item.value ->> 'storageContractId')::uuid = p_source_storage_contract_id
    and (field_item.value ->> 'fieldId')::uuid = p_target_field_id;
  if target_field is null then
    raise exception using errcode = '55000',
      message = 'Storage conversion target field is not published';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(source_record_types) as record_item(value)
    cross join lateral pg_catalog.jsonb_array_elements(
      record_item.value -> 'fields'
    ) as field_item(value)
    where (record_item.value ->> 'storageContractId')::uuid = p_source_storage_contract_id
      and (field_item.value ->> 'fieldId')::uuid = p_target_field_id
  ) then
    raise exception using errcode = '23514',
      message = 'Storage conversion target field already exists in the source release';
  end if;

  semantic := vortex_record.conversion_semantic_for_fields(source_field, target_field);
  if semantic is null then
    raise exception using errcode = '23514',
      message = 'Storage conversion pair is unsupported';
  end if;

  conversion_id := vortex_record.storage_conversion_contract_identity(
    p_source_storage_contract_id, p_source_field_id, p_target_field_id
  );

  insert into vortex_record.storage_conversion_catalogue (
    conversion_contract_id, source_storage_contract_id, target_storage_contract_id,
    source_field_id, target_field_id, source_database_value_type,
    target_database_value_type, conversion_semantic, source_release_revision,
    target_release_revision, source_field_definition, target_field_definition
  ) values (
    conversion_id, p_source_storage_contract_id, p_source_storage_contract_id,
    p_source_field_id, p_target_field_id, source_mapping.database_value_type,
    vortex_record.database_value_type(target_field), semantic,
    p_source_release_revision, p_target_release_revision, source_field, target_field
  )
  on conflict (conversion_contract_id) do nothing;
  get diagnostics inserted_count = row_count;

  select stored_entry.* into stored
  from vortex_record.storage_conversion_catalogue as stored_entry
  where stored_entry.conversion_contract_id = conversion_id;
  if not found then
    raise exception using errcode = '55000',
      message = 'Storage conversion catalogue write failed';
  end if;

  -- An entry is immutable once registered: a plan, its staged mapping and its
  -- progress all depend on exactly this evidence.
  if inserted_count = 0 and (
    stored.source_database_value_type is distinct from source_mapping.database_value_type
    or stored.target_database_value_type
      is distinct from vortex_record.database_value_type(target_field)
    or stored.conversion_semantic is distinct from semantic
    or stored.source_release_revision is distinct from p_source_release_revision
    or stored.target_release_revision is distinct from p_target_release_revision
    or stored.source_field_definition is distinct from source_field
    or stored.target_field_definition is distinct from target_field
  ) then
    raise exception using errcode = '55000',
      message = 'Storage conversion is already registered with different evidence';
  end if;

  return pg_catalog.jsonb_build_object(
    'conversionContractId', stored.conversion_contract_id,
    'storageContractId', stored.source_storage_contract_id,
    'sourceFieldId', stored.source_field_id,
    'targetFieldId', stored.target_field_id,
    'conversionSemantic', stored.conversion_semantic,
    'sourceDatabaseValueType', stored.source_database_value_type,
    'targetDatabaseValueType', stored.target_database_value_type,
    'sourceReleaseRevision', stored.source_release_revision,
    'targetReleaseRevision', stored.target_release_revision,
    'changed', inserted_count > 0
  );
exception
  when no_data_found or too_many_rows then
    raise exception using errcode = '55000',
      message = 'Storage conversion release evidence is unavailable';
end
$function$;


ALTER FUNCTION vortex_record.register_storage_conversion_plan(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid, p_source_release_revision bigint, p_target_release_revision bigint) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION register_storage_conversion_plan(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid, p_source_release_revision bigint, p_target_release_revision bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.register_storage_conversion_plan(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid, p_source_release_revision bigint, p_target_release_revision bigint) IS 'Records one immutable conversion catalogue entry from the caller-owned Module''s exact published source mapping and target release evidence; refuses any caller-authored type or unsupported pair.';


--
-- Name: relationship_declares_target_internal(jsonb, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.relationship_declares_target_internal(p_relationship jsonb, p_record_type_id uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_record_type_id is not null and exists (
    select 1
    from pg_catalog.jsonb_array_elements(
      case
        when pg_catalog.jsonb_typeof(p_relationship -> 'toRecordType') = 'object'
          then pg_catalog.jsonb_build_array(p_relationship -> 'toRecordType')
        when pg_catalog.jsonb_typeof(p_relationship -> 'toRecordTypes') = 'array'
          then p_relationship -> 'toRecordTypes'
        else '[]'::jsonb
      end
    ) as target(value)
    where pg_catalog.lower(target.value ->> 'recordTypeId') =
      pg_catalog.lower(p_record_type_id::text)
  )
$$;


ALTER FUNCTION vortex_record.relationship_declares_target_internal(p_relationship jsonb, p_record_type_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION relationship_declares_target_internal(p_relationship jsonb, p_record_type_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.relationship_declares_target_internal(p_relationship jsonb, p_record_type_id uuid) IS 'True only when a concrete record type is one of a relationship''s declared targets: its single toRecordType or a member of its toRecordTypes list.';


--
-- Name: relationship_edge_lock_identities_internal(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.relationship_edge_lock_identities_internal(p_relationship_id uuid, p_from_storage_contract_id uuid, p_from_record_id uuid, p_to_storage_contract_id uuid, p_to_record_id uuid) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  source_identity text;
  target_identity text;
begin
  if (p_to_storage_contract_id is null) <> (p_to_record_id is null) then
    raise exception using errcode = '22023',
      message = 'Relationship edge target identity is incomplete';
  end if;
  source_identity := vortex_record.relationship_edge_record_identity_internal(
    p_relationship_id, p_from_storage_contract_id, p_from_record_id
  );
  if p_to_storage_contract_id is null then
    return array[source_identity];
  end if;
  target_identity := vortex_record.relationship_edge_record_identity_internal(
    p_relationship_id, p_to_storage_contract_id, p_to_record_id
  );
  if source_identity = target_identity then
    return array[source_identity];
  end if;
  return case when source_identity collate "C" < target_identity collate "C"
    then array[source_identity, target_identity]
    else array[target_identity, source_identity] end;
end
$$;


ALTER FUNCTION vortex_record.relationship_edge_lock_identities_internal(p_relationship_id uuid, p_from_storage_contract_id uuid, p_from_record_id uuid, p_to_storage_contract_id uuid, p_to_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION relationship_edge_lock_identities_internal(p_relationship_id uuid, p_from_storage_contract_id uuid, p_from_record_id uuid, p_to_storage_contract_id uuid, p_to_record_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.relationship_edge_lock_identities_internal(p_relationship_id uuid, p_from_storage_contract_id uuid, p_from_record_id uuid, p_to_storage_contract_id uuid, p_to_record_id uuid) IS 'Sorted participant identities one relationship edge mutation locks: the source always, and the new target when an edge is installed.';


--
-- Name: relationship_edge_record_identity_internal(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.relationship_edge_record_identity_internal(p_relationship_id uuid, p_storage_contract_id uuid, p_record_id uuid) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_relationship_id is null or p_storage_contract_id is null or p_record_id is null
    or p_relationship_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Relationship edge participant identity is invalid';
  end if;
  return pg_catalog.concat_ws(
    ':',
    'vortex_record.relationship_edge',
    pg_catalog.lower(p_relationship_id::text),
    pg_catalog.lower(p_storage_contract_id::text),
    pg_catalog.lower(p_record_id::text)
  );
end
$$;


ALTER FUNCTION vortex_record.relationship_edge_record_identity_internal(p_relationship_id uuid, p_storage_contract_id uuid, p_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION relationship_edge_record_identity_internal(p_relationship_id uuid, p_storage_contract_id uuid, p_record_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.relationship_edge_record_identity_internal(p_relationship_id uuid, p_storage_contract_id uuid, p_record_id uuid) IS 'Permanent identity of one participant of one relationship edge: relationship, storage contract and record. Malformed or sentinel identities raise.';


--
-- Name: relationship_total_catalogue_internal(); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.relationship_total_catalogue_internal()
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  installation jsonb;
  binding jsonb;
  content jsonb;
  record_types jsonb := '[]'::jsonb;
  relationships jsonb := '[]'::jsonb;
  has_installed_rules boolean := false;
  rule_subject_record_type_ids jsonb := '[]'::jsonb;
  record_type jsonb;
begin
  installation := vortex_module.read_current_active_installation();
  for binding in
    select item.value
    from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') item(value)
    order by item.value ->> 'moduleRootId'
  loop
    select release.compilation_output #> '{canonical,content}' into strict content
    from vortex_definition.releases release
    where release.root_id = (binding ->> 'moduleRootId')::uuid
      and release.release_revision = (binding ->> 'moduleReleaseRevision')::bigint;
    if pg_catalog.jsonb_typeof(content -> 'recordTypes') <> 'array' then
      raise exception using errcode = '55000', message = 'Installed Record definitions are unavailable';
    end if;
    has_installed_rules := has_installed_rules or
      pg_catalog.jsonb_array_length(coalesce(content -> 'rules', '[]'::jsonb)) > 0;
    rule_subject_record_type_ids := rule_subject_record_type_ids || coalesce((
      select pg_catalog.jsonb_agg(distinct rule.value -> 'subjectRecordTypeId')
      from pg_catalog.jsonb_array_elements(coalesce(content -> 'rules', '[]'::jsonb)) rule(value)
      where rule.value ->> 'profile' = 'before_save'
    ), '[]'::jsonb);
    record_types := record_types || coalesce((
      select pg_catalog.jsonb_agg(
        item.value || pg_catalog.jsonb_build_object(
          'moduleReleaseRevision', binding -> 'moduleReleaseRevision'
        )
        order by item.value ->> 'recordTypeId'
      )
      from pg_catalog.jsonb_array_elements(content -> 'recordTypes') item(value)
    ), '[]'::jsonb);
    for record_type in
      select item.value from pg_catalog.jsonb_array_elements(content -> 'recordTypes') item(value)
    loop
      relationships := relationships || coalesce(record_type -> 'relationships', '[]'::jsonb);
    end loop;
  end loop;
  select release.compilation_output #> '{canonical,content}' into strict content
  from vortex_definition.releases release
  where release.root_id = (installation ->> 'applicationRootId')::uuid
    and release.release_revision = (installation ->> 'applicationReleaseRevision')::bigint;
  has_installed_rules := has_installed_rules or
    pg_catalog.jsonb_array_length(coalesce(content -> 'rules', '[]'::jsonb)) > 0;
  rule_subject_record_type_ids := rule_subject_record_type_ids || coalesce((
    select pg_catalog.jsonb_agg(distinct rule.value -> 'subjectRecordTypeId')
    from pg_catalog.jsonb_array_elements(coalesce(content -> 'rules', '[]'::jsonb)) rule(value)
    where rule.value ->> 'profile' = 'before_save'
  ), '[]'::jsonb);
  return pg_catalog.jsonb_build_object(
    'recordTypes', record_types,
    'relationships', relationships,
    'hasInstalledRules', has_installed_rules,
    'ruleSubjectRecordTypeIds', rule_subject_record_type_ids
  );
end
$function$;


ALTER FUNCTION vortex_record.relationship_total_catalogue_internal() OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION relationship_total_catalogue_internal(); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.relationship_total_catalogue_internal() IS 'Private relationship-total catalogue for the validated human Application request context.';


--
-- Name: relationship_total_record_snapshot_internal(jsonb, uuid, uuid, boolean); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.relationship_total_record_snapshot_internal(
  p_catalogue jsonb,
  p_record_type_id uuid,
  p_record_id uuid,
  p_lock boolean
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  context_value jsonb;
  record_type jsonb;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  columns_value jsonb;
  value_expression text;
  load_sql text;
  result_value jsonb;
begin
  if p_record_type_id is null or p_record_id is null or p_lock is null
    or pg_catalog.jsonb_typeof(p_catalogue -> 'recordTypes') <> 'array' then
    return null;
  end if;
  context_value := vortex_access.validated_human_request_context();
  select item.value into record_type
  from pg_catalog.jsonb_array_elements(p_catalogue -> 'recordTypes') item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') = pg_catalog.lower(p_record_type_id::text);
  if record_type is null then return null; end if;

  select stored.* into catalogue_row
  from vortex_record.storage_catalogue stored
  where stored.storage_contract_id = (record_type ->> 'storageContractId')::uuid
    and stored.record_type_id = p_record_type_id
    and stored.state = 'active';
  if not found then return null; end if;

  select pg_catalog.jsonb_object_agg(
    pg_catalog.lower(field.value ->> 'fieldId'),
    pg_catalog.jsonb_build_object(
      'token', mapping.physical_column_token,
      'databaseValueType', mapping.database_value_type,
      'type', field.value ->> 'type'
    )
  ) into columns_value
  from pg_catalog.jsonb_array_elements(record_type -> 'fields') field(value)
  join vortex_record.field_storage_mappings mapping
    on mapping.storage_contract_id = (record_type ->> 'storageContractId')::uuid
   and mapping.field_id = (field.value ->> 'fieldId')::uuid
   and mapping.state = 'active';
  if (select pg_catalog.count(*)
      from pg_catalog.jsonb_object_keys(coalesce(columns_value, '{}'::jsonb))) <>
      pg_catalog.jsonb_array_length(record_type -> 'fields') then
    return null;
  end if;

  select pg_catalog.string_agg(
    field_chunk.pairs_text,
    ') || pg_catalog.jsonb_build_object(' order by field_chunk.chunk_index
  )
  into value_expression
  from (
    select (ordered_fields.field_number - 1) / 50 as chunk_index,
      pg_catalog.string_agg(
        pg_catalog.format(
          '%L, %s', ordered_fields.key,
          case ordered_fields.value ->> 'databaseValueType'
            when 'decimal' then pg_catalog.format('pg_catalog.to_jsonb(stored.%I::text)', ordered_fields.value ->> 'token')
            when 'timestamp_with_time_zone' then pg_catalog.format(
              'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(stored.%I))',
              ordered_fields.value ->> 'token'
            )
            when 'date' then pg_catalog.format(
              'pg_catalog.to_jsonb(pg_catalog.to_char(stored.%I, ''YYYY-MM-DD''))',
              ordered_fields.value ->> 'token'
            )
            else pg_catalog.format('pg_catalog.to_jsonb(stored.%I)', ordered_fields.value ->> 'token')
          end
        ), ', ' order by ordered_fields.key collate "C"
      ) as pairs_text
    from (
      select entry.key, entry.value,
        pg_catalog.row_number() over (
          order by entry.key collate "C"
        ) as field_number
      from pg_catalog.jsonb_each(columns_value) entry(key, value)
    ) as ordered_fields
    group by (ordered_fields.field_number - 1) / 50
  ) as field_chunk;

  load_sql := pg_catalog.format(
    'select pg_catalog.jsonb_build_object(
       ''recordType'', $3 - ''moduleReleaseRevision'',
       ''recordTypeId'', %L::uuid,
       ''storageContractId'', %L::uuid,
       ''recordId'', stored.record_id,
       ''concurrencyNumber'', stored.concurrency_number,
       ''definitionRevision'', %L::bigint,
       ''existingValues'', pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(%s))
     )
     from record_data.%I stored
     where stored.organisation_id = $1 and stored.record_id = $2
       and stored.lifecycle_state = ''active''
       and stored.application_root_id is not distinct from %s%s',
    p_record_type_id,
    (record_type ->> 'storageContractId')::uuid,
    (record_type ->> 'moduleReleaseRevision')::bigint,
    value_expression,
    catalogue_row.physical_table_token,
    case when record_type ->> 'storageScope' = 'application_contained'
      then '$4::uuid' else 'null::uuid' end,
    case when p_lock then ' for update' else '' end
  );
  execute load_sql into result_value using
    (context_value ->> 'organizationId')::uuid,
    p_record_id,
    record_type,
    (context_value ->> 'applicationRootId')::uuid;
  return result_value;
end
$function$;


ALTER FUNCTION vortex_record.relationship_total_record_snapshot_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid, p_lock boolean) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION relationship_total_record_snapshot_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid, p_lock boolean); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.relationship_total_record_snapshot_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid, p_lock boolean) IS 'Private locked-or-read snapshot of one record for the validated human Application request context.';


--
-- Name: relationship_total_source_is_retained_internal(jsonb, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.relationship_total_source_is_retained_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid, p_organization_id uuid, p_application_root_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  record_type jsonb;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  lifecycle_state_value text;
begin
  if p_record_type_id is null or p_record_id is null or p_organization_id is null
    or pg_catalog.jsonb_typeof(p_catalogue -> 'recordTypes') is distinct from 'array' then
    return false;
  end if;
  select item.value into record_type
  from pg_catalog.jsonb_array_elements(p_catalogue -> 'recordTypes') as item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') = pg_catalog.lower(p_record_type_id::text);
  if record_type is null then
    return false;
  end if;
  select stored.* into catalogue_row
  from vortex_record.storage_catalogue as stored
  where stored.storage_contract_id = (record_type ->> 'storageContractId')::uuid
    and stored.record_type_id = p_record_type_id
    and stored.state = 'active';
  if not found then
    return false;
  end if;
  execute pg_catalog.format(
    'select stored.lifecycle_state from record_data.%I as stored
     where stored.organisation_id = $1 and stored.record_id = $2
       and stored.application_root_id is not distinct from $3',
    catalogue_row.physical_table_token
  ) into lifecycle_state_value using
    p_organization_id, p_record_id,
    case when record_type ->> 'storageScope' = 'application_contained'
      then p_application_root_id else null end;
  return lifecycle_state_value is not null and lifecycle_state_value <> 'active';
end
$_$;


ALTER FUNCTION vortex_record.relationship_total_source_is_retained_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid, p_organization_id uuid, p_application_root_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: release_command_receipt_internal(text, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.release_command_receipt_internal(
  p_command_kind text,
  p_command_id uuid
)
returns void
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  context_value jsonb;
  preview_value jsonb;
begin
  context_value := vortex_access.validated_human_request_context();
  preview_value := vortex_record.read_current_preview_installation_internal();
  if preview_value is not null then
    if preview_value ->> 'outcome' = 'refused' then
      raise exception using errcode = '42501',
        message = 'Preview Record command is unavailable';
    end if;
    delete from vortex_record.preview_command_receipts as stored
    where stored.preview_installation_id =
        (preview_value ->> 'previewInstallationId')::uuid
      and stored.organization_id = (context_value ->> 'organizationId')::uuid
      and stored.application_root_id = (context_value ->> 'applicationRootId')::uuid
      and stored.actor_organization_account_id =
        (context_value ->> 'organizationAccountId')::uuid
      and stored.command_kind = p_command_kind
      and stored.command_id = p_command_id
      and stored.state = 'pending';
    return;
  end if;
  delete from vortex_record.command_receipts as stored
  where stored.organization_id = (context_value ->> 'organizationId')::uuid
      and stored.application_root_id = (context_value ->> 'applicationRootId')::uuid
      and stored.actor_organization_account_id =
        (context_value ->> 'organizationAccountId')::uuid
      and stored.command_kind = p_command_kind
      and stored.command_id = p_command_id
    and stored.state = 'pending';
end
$function$;


ALTER FUNCTION vortex_record.release_command_receipt_internal(p_command_kind text, p_command_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION release_command_receipt_internal(p_command_kind text, p_command_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.release_command_receipt_internal(p_command_kind text, p_command_id uuid) IS 'Releases the request actor''s pending live or preview-local command receipt when its command is refused before any change, so the identity can be used again.';


--
-- Name: renew_record_index_build_lease(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.renew_record_index_build_lease(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_storage_contract_id is null
    or p_field_id is null
    or p_claim_id is null
    or p_lease_seconds is null
    or p_lease_seconds not between 1 and 86400 then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'command_invalid'
    );
  end if;

  update vortex_record.index_catalogue as catalogue
  set lease_expires_at = pg_catalog.statement_timestamp()
    + pg_catalog.make_interval(secs => p_lease_seconds)
  where catalogue.storage_contract_id = p_storage_contract_id
    and catalogue.field_id = p_field_id
    and catalogue.claim_id = p_claim_id;
  if not found then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'lease_not_owned'
    );
  end if;
  return pg_catalog.jsonb_build_object('outcome', 'renewed');
end
$$;


ALTER FUNCTION vortex_record.renew_record_index_build_lease(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_lease_seconds integer) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION renew_record_index_build_lease(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_lease_seconds integer); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.renew_record_index_build_lease(p_storage_contract_id uuid, p_field_id uuid, p_claim_id uuid, p_lease_seconds integer) IS 'Confirms the caller still holds one index build claim and extends its lease before the next statement.';


--
-- Name: reserve_named_action_creation_locks_internal(uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.reserve_named_action_creation_locks_internal(
  p_record_type_id uuid,
  p_creations jsonb
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  organization_id_value uuid;
  application_root_id_value uuid;
  counters jsonb := '[]'::jsonb;
  creation jsonb;
  record_meta jsonb;
  record_type_value jsonb;
  storage_contract_id_value uuid;
  storage_scope_value text;
  field_item jsonb;
  field_settings jsonb;
  counter_row record;
begin
  if p_record_type_id is null
    or pg_catalog.jsonb_typeof(p_creations) is distinct from 'array' then
    raise exception using errcode = '22023', message = 'Named action creation is invalid';
  end if;
  context_value := vortex_access.validated_human_request_context();
  organization_id_value := (context_value ->> 'organizationId')::uuid;
  application_root_id_value := (context_value ->> 'applicationRootId')::uuid;

  for creation in
    select item.value
    from pg_catalog.jsonb_array_elements(p_creations) with ordinality item(value, ordinality)
    order by item.ordinality
  loop
    record_meta := vortex_record.resolve_record_action_context_internal(
      (creation ->> 'recordTypeId')::uuid, 'create'
    );
    if pg_catalog.jsonb_typeof(record_meta -> 'recordType') is distinct from 'object' then
      raise exception using errcode = '55000',
        message = 'Named action creation target is unavailable';
    end if;
    record_type_value := record_meta -> 'recordType';
    storage_contract_id_value := (record_meta ->> 'storageContractId')::uuid;
    storage_scope_value := record_meta ->> 'storageScope';
    for field_item in
      select item.value
      from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as item(value)
      order by item.value ->> 'fieldId'
    loop
      if field_item ->> 'type' <> 'reference_number' then continue; end if;
      field_settings := coalesce(field_item -> 'settings', '{}'::jsonb);
      -- A malformed setting is left for `allocate_reference_number_internal` to
      -- reject; this pass only reserves a valid counter.
      if pg_catalog.jsonb_typeof(field_settings -> 'digits') <> 'number'
        or (field_settings ->> 'digits')::integer not between 1 and 20
        or (field_settings ? 'startingNumber' and (
          pg_catalog.jsonb_typeof(field_settings -> 'startingNumber') <> 'number'
          or (field_settings ->> 'startingNumber')::numeric < 1
          or pg_catalog.trunc((field_settings ->> 'startingNumber')::numeric)
            <> (field_settings ->> 'startingNumber')::numeric
        )) then
        continue;
      end if;
      counters := counters || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'storageContractId', storage_contract_id_value,
        'fieldId', (field_item ->> 'fieldId')::uuid,
        'applicationRootId', case when storage_scope_value = 'application_contained'
          then application_root_id_value else null end,
        'startNumber', coalesce((field_settings ->> 'startingNumber')::numeric, 1)
      ));
    end loop;
  end loop;

  -- L4: every created record's reference-number counter, in one canonical
  -- order, before the subject writer writes the subject's relationship edges
  -- (L6), matching ordinary create's counter-then-edge order. A row is created
  -- at `startingNumber` or left unchanged, and `allocate_reference_number_internal`
  -- then increments the held row, so an abandoned reservation consumes no number.
  for counter_row in
    select distinct
      (item.value ->> 'storageContractId')::uuid as storage_contract_id,
      (item.value ->> 'fieldId')::uuid as field_id,
      (item.value ->> 'applicationRootId')::uuid as application_root_id,
      (item.value ->> 'startNumber')::numeric as start_number
    from pg_catalog.jsonb_array_elements(counters) as item(value)
    order by 1, 2, 3
  loop
    insert into vortex_record.record_reference_counters (
      organization_id, storage_contract_id, field_id, application_root_id, next_number
    ) values (
      organization_id_value, counter_row.storage_contract_id, counter_row.field_id,
      counter_row.application_root_id, counter_row.start_number
    )
    on conflict (organization_id, storage_contract_id, field_id, application_root_id)
      do update set next_number = vortex_record.record_reference_counters.next_number;
  end loop;
end
$function$;


ALTER FUNCTION vortex_record.reserve_named_action_creation_locks_internal(p_record_type_id uuid, p_creations jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION reserve_named_action_creation_locks_internal(p_record_type_id uuid, p_creations jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.reserve_named_action_creation_locks_internal(p_record_type_id uuid, p_creations jsonb) IS 'Private named-action step: takes every created record''s reference-number counter (L4) before the subject writer writes any relationship edge (L6), so a combined create and subject-link command keeps edge identities as the last lock class, as ordinary create does. Changes no counter value except the creation reservation itself.';


--
-- Name: resolve_active_bundle_record_access_plan_internal(jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.resolve_active_bundle_record_access_plan_internal(p_expected_identity jsonb)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare

  plan_key_value text;
  organization_id_value uuid;
  application_root_id_value uuid;
  application_release_revision_value bigint;
  binding_item jsonb;
  release_content jsonb;
  release_revision_value bigint;
  release_validation_contract_version text;
  record_type_item jsonb;
  field_item jsonb;
  relationship_item jsonb;
  condition_item jsonb;
  permission_item jsonb;
  module_root_value uuid;
  record_type_id_value uuid;
  release_storage_contract_value uuid;
  storage_contract_value uuid;
  type_meta jsonb := '{}'::jsonb;
  relationship_by_id jsonb := '{}'::jsonb;
  condition_list jsonb := '[]'::jsonb;
  permission_by_id jsonb := '{}'::jsonb;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  mapping_row vortex_record.field_storage_mappings%rowtype;
  columns_value jsonb;
  value_expression text;
  plan jsonb;
  p_installation jsonb;
  active_mapping jsonb;
  final_mapping jsonb;
  storage_item record;
  stable_plan jsonb;
  stored_plan_row vortex_record.installation_access_plans%rowtype;
  inserted_rows bigint;
  mapping_fingerprint_value text;
  pin_fingerprint_value text;
begin
  active_mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  p_installation:=active_mapping -> 'installation';
  organization_id_value:=(p_installation ->> 'organizationId')::uuid;
  application_root_id_value:=(p_installation ->> 'applicationRootId')::uuid;
  application_release_revision_value:=(p_installation ->> 'applicationReleaseRevision')::bigint;
  -- This fixed active-only composer exposes no preview or binding-state override.
  pin_fingerprint_value:=active_mapping #>> '{identity,pinFingerprint}';
  -- Reuse the storage mutators' existing advisory key, without requesting
  -- row-lock UPDATE authority on SELECT-only storage catalogue tables.
  for storage_item in
    select distinct (record_type.value ->> 'storageContractId')::uuid as storage_id
    from pg_catalog.jsonb_array_elements(active_mapping -> 'modules') as module(value)
    cross join lateral pg_catalog.jsonb_array_elements(
      module.value #> '{compilationOutput,canonical,content,recordTypes}') as record_type(value)
    order by storage_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'vortex_record.storage:' || storage_item.storage_id::text,0));
    final_mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity);
    if final_mapping is distinct from active_mapping then
      raise exception using errcode='40001', message='Active Record mapping changed while waiting';
    end if;
  end loop;
  -- Step 1: the pinned definitions. Record types, relationships and saved
  -- conditions of every bound Module, plus the declared permissions of the
  -- Application release and of each Module release. Physical tokens are
  -- resolved here too, and every disagreement refuses.
  for binding_item in
    select item.value
    from pg_catalog.jsonb_array_elements(p_installation -> 'moduleBindings') as item(value)
    -- Canonical binding order, so the plan content never depends on the order
    -- a caller happened to supply and always matches the plan key's order.
    order by (item.value ->> 'moduleRootId') collate "C"
  loop
    module_root_value := (binding_item ->> 'moduleRootId')::uuid;
    release_revision_value := (binding_item ->> 'moduleReleaseRevision')::bigint;

    select release.compilation_output #> '{canonical,content}',
      release.validation_contract_version
    into strict release_content, release_validation_contract_version
    from vortex_definition.releases as release
    where release.root_id = module_root_value
      and release.release_revision = release_revision_value;

    if pg_catalog.jsonb_typeof(release_content -> 'recordTypes') <> 'array' then
      raise exception using errcode = '55000',
        message = 'Installed Module definition is unavailable';
    end if;

    for record_type_item in
      select item.value
      from pg_catalog.jsonb_array_elements(release_content -> 'recordTypes') as item(value)
    loop
      record_type_id_value := (record_type_item ->> 'recordTypeId')::uuid;
      release_storage_contract_value := (record_type_item ->> 'storageContractId')::uuid;
      storage_contract_value := release_storage_contract_value;

      select catalogue.* into catalogue_row
      from vortex_record.storage_catalogue as catalogue
      where catalogue.storage_contract_id = storage_contract_value;
      if not found
        or catalogue_row.state <> 'active'
        or catalogue_row.module_root_id <> module_root_value
        or catalogue_row.record_type_id <> record_type_id_value
        or catalogue_row.storage_scope is distinct from (record_type_item ->> 'storageScope')
        or catalogue_row.physical_schema_token not in ('record_data', 'system_projection')
        -- A system projection is read only through the protected reader
        -- registered for exactly the key its installed definition declares (the
        -- catalogue key references the closed registry); a generated record
        -- type is never read through a projection, and a disagreeing key
        -- refuses.
        or (catalogue_row.physical_schema_token = 'system_projection')
          is distinct from (record_type_item ? 'systemProjection')
        or (catalogue_row.physical_schema_token = 'system_projection'
          and catalogue_row.protected_read_model_key
            is distinct from (record_type_item #>> '{systemProjection,protectedView}'))
        or not exists (
          select 1
          from vortex_record.release_provisions as provision
          where provision.module_root_id = module_root_value
            and provision.release_revision = release_revision_value
            and release_storage_contract_value = any (provision.storage_contract_ids)
        ) then
        raise exception using errcode = '55000',
          message = 'Record storage disagrees with the installed definition';
      end if;

      -- The column map and the one value expression that reads this record
      -- type's row, built once here and reused by every load below.
      columns_value := '{}'::jsonb;
      for field_item in
        select item.value
        from pg_catalog.jsonb_array_elements(record_type_item -> 'fields') as item(value)
      loop
        select mapping.* into mapping_row
        from vortex_record.field_storage_mappings as mapping
        where mapping.storage_contract_id = storage_contract_value
          and mapping.field_id = (field_item ->> 'fieldId')::uuid;
        if not found or mapping_row.state <> 'active' then
          raise exception using errcode = '55000',
            message = 'Record storage disagrees with the installed definition';
        end if;
        columns_value := columns_value || pg_catalog.jsonb_build_object(
          pg_catalog.lower(field_item ->> 'fieldId'), pg_catalog.jsonb_build_object(
            'token', mapping_row.physical_column_token,
            'databaseValueType', mapping_row.database_value_type,
            'type', field_item ->> 'type'
          )
        );
      end loop;

      select pg_catalog.string_agg(
        field_chunk.pairs_text,
        ') || pg_catalog.jsonb_build_object(' order by field_chunk.chunk_index
      )
      into value_expression
      from (
        select (ordered_fields.field_number - 1) / 50 as chunk_index,
          pg_catalog.string_agg(
            pg_catalog.format(
              '%L, %s',
              ordered_fields.key,
              case ordered_fields.value ->> 'databaseValueType'
                when 'decimal' then
                  pg_catalog.format('pg_catalog.to_jsonb(%I::text)', ordered_fields.value ->> 'token')
                when 'timestamp_with_time_zone' then
                  pg_catalog.format(
                    'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(%I))',
                    ordered_fields.value ->> 'token'
                  )
                when 'date' then
                  pg_catalog.format(
                    'pg_catalog.to_jsonb(pg_catalog.to_char(%I, ''YYYY-MM-DD''))',
                    ordered_fields.value ->> 'token'
                  )
                else pg_catalog.format('pg_catalog.to_jsonb(%I)', ordered_fields.value ->> 'token')
              end
            ),
            ', ' order by ordered_fields.key collate "C"
          ) as pairs_text
        from (
          select column_entry.key, column_entry.value,
            pg_catalog.row_number() over (
              order by column_entry.key collate "C"
            ) as field_number
          from pg_catalog.jsonb_each(columns_value) as column_entry(key, value)
        ) as ordered_fields
        group by (ordered_fields.field_number - 1) / 50
      ) as field_chunk;

      type_meta := type_meta || pg_catalog.jsonb_build_object(
        pg_catalog.lower(record_type_id_value::text),
        pg_catalog.jsonb_build_object(
          'moduleRootId', module_root_value,
          'recordTypeId', record_type_id_value,
          'storageContractId', storage_contract_value,
          'storageScope', record_type_item ->> 'storageScope',
          'ownershipMode', record_type_item ->> 'ownershipMode',
          'releaseRevision', release_revision_value,
          'validationContractVersion', release_validation_contract_version,
          'table', catalogue_row.physical_table_token,
          'columns', columns_value,
          'valueExpression', value_expression,
          'fields', coalesce((
            select pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'fieldId', declared.value -> 'fieldId',
                'type', declared.value -> 'type'
              ) || case
                when pg_catalog.jsonb_typeof(declared.value -> 'settings') = 'object'
                  then pg_catalog.jsonb_build_object('settings', declared.value -> 'settings')
                else '{}'::jsonb
              end
              order by declared.ordinality
            )
            from pg_catalog.jsonb_array_elements(record_type_item -> 'fields')
              with ordinality as declared(value, ordinality)
          ), '[]'::jsonb)
        ) || case
          when record_type_item ? 'ownershipRelationshipId'
            then pg_catalog.jsonb_build_object(
              'ownershipRelationshipId', record_type_item -> 'ownershipRelationshipId'
            )
          else '{}'::jsonb
        end
      );

      for relationship_item in
        select item.value
        from pg_catalog.jsonb_array_elements(record_type_item -> 'relationships') as item(value)
      loop
        -- Every declared target, single or polymorphic, as one uniform list;
        -- Access proves a concrete edge target a member of it.
        relationship_by_id := relationship_by_id || pg_catalog.jsonb_build_object(
          pg_catalog.lower(relationship_item ->> 'relationshipId'),
          pg_catalog.jsonb_build_object(
            'relationshipId', relationship_item -> 'relationshipId',
            'fromModuleRootId', module_root_value,
            'fromRecordTypeId', record_type_item -> 'recordTypeId',
            'toRecordTypes', coalesce((
              select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'moduleRootId', target.value -> 'moduleRootId',
                'recordTypeId', target.value -> 'recordTypeId'
              ) order by target.ordinality)
              from pg_catalog.jsonb_array_elements(
                case when relationship_item ? 'toRecordType'
                  then pg_catalog.jsonb_build_array(relationship_item -> 'toRecordType')
                  else relationship_item -> 'toRecordTypes'
                end
              ) with ordinality as target(value, ordinality)
            ), '[]'::jsonb)
          )
        );
      end loop;
    end loop;

    for condition_item in
      select item.value
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(release_content -> 'sharingConditions') = 'array'
            then release_content -> 'sharingConditions'
          else '[]'::jsonb
        end
      ) as item(value)
    loop
      condition_list := condition_list || pg_catalog.jsonb_build_array(condition_item);
    end loop;

    for permission_item in
      select item.value
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(release_content -> 'permissions') = 'array'
            then release_content -> 'permissions'
          else '[]'::jsonb
        end
      ) as item(value)
    loop
      if pg_catalog.jsonb_typeof(permission_item -> 'recordScope') = 'object' then
        permission_by_id := permission_by_id || pg_catalog.jsonb_build_object(
          pg_catalog.lower(permission_item ->> 'permissionId'),
          pg_catalog.jsonb_build_object(
            'ownerKind', 'module',
            'ownerId', module_root_value,
            'recordTypeId', permission_item -> 'recordTypeId',
            'actionKind', permission_item -> 'actionKind',
            'namedAction', permission_item -> 'namedAction',
            'recordScope', permission_item -> 'recordScope'
          )
        );
      end if;
    end loop;
  end loop;

  select release.compilation_output #> '{canonical,content}'
  into strict release_content from vortex_definition.releases as release
  where release.root_id=application_root_id_value
    and release.release_revision=application_release_revision_value;

  for permission_item in
    select item.value
    from pg_catalog.jsonb_array_elements(
      case
        when pg_catalog.jsonb_typeof(release_content -> 'permissions') = 'array'
          then release_content -> 'permissions'
        else '[]'::jsonb
      end
    ) as item(value)
  loop
    if pg_catalog.jsonb_typeof(permission_item -> 'recordScope') = 'object' then
      permission_by_id := permission_by_id || pg_catalog.jsonb_build_object(
        pg_catalog.lower(permission_item ->> 'permissionId'),
        pg_catalog.jsonb_build_object(
          'ownerKind', 'application',
          'ownerId', application_root_id_value,
          'recordTypeId', permission_item -> 'recordTypeId',
          'actionKind', permission_item -> 'actionKind',
          'namedAction', permission_item -> 'namedAction',
          'recordScope', permission_item -> 'recordScope'
        )
      );
    end if;
  end loop;

  plan := pg_catalog.jsonb_build_object(
    'organizationId', organization_id_value,
    'applicationRootId', application_root_id_value,
    'applicationReleaseRevision', application_release_revision_value,
    'recordTypes', type_meta,
    'relationships', relationship_by_id,
    'sharingConditions', condition_list,
    'permissions', permission_by_id
  );


  mapping_fingerprint_value:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'recordTypes',plan -> 'recordTypes','relationships',plan -> 'relationships',
      'sharingConditions',plan -> 'sharingConditions','permissions',plan -> 'permissions')::text,'UTF8')),'hex');
  plan_key_value:='sha256:' || pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
    'vortex.installation-runtime-bundle.prepared-record-access-plan.v2|' ||
      organization_id_value::text || '|' || application_root_id_value::text || '|' ||
      application_release_revision_value::text || '|2|' || pin_fingerprint_value,'UTF8')),'hex');
  stable_plan:=pg_catalog.jsonb_build_object('planKey',plan_key_value,
    'mappingFingerprint',mapping_fingerprint_value,'plan',plan);
  insert into vortex_record.installation_access_plans(
    plan_key,organization_id,application_root_id,application_release_revision,plan)
  values(plan_key_value,organization_id_value,application_root_id_value,
    application_release_revision_value,stable_plan)
  on conflict(plan_key) do nothing;
  get diagnostics inserted_rows=row_count;
  if inserted_rows=0 then
    select stored.* into strict stored_plan_row
    from vortex_record.installation_access_plans as stored where stored.plan_key=plan_key_value for update;
    if stored_plan_row.organization_id is distinct from organization_id_value
      or stored_plan_row.application_root_id is distinct from application_root_id_value
      or stored_plan_row.application_release_revision is distinct from application_release_revision_value
      or stored_plan_row.plan is distinct from stable_plan then
      raise exception using errcode='23505', message='Active Record plan immutable identity differs';
    end if;
  end if;
  final_mapping:=vortex_module.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  if final_mapping is distinct from active_mapping then
    raise exception using errcode='40001', message='Active Record mapping changed';
  end if;
  return stable_plan;
exception when no_data_found or too_many_rows then
  raise exception using errcode='55000', message='Active Record plan evidence is unavailable';
end
$function$;


ALTER FUNCTION vortex_record.resolve_active_bundle_record_access_plan_internal(p_expected_identity jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_active_bundle_record_access_plan_internal(p_expected_identity jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_active_bundle_record_access_plan_internal(p_expected_identity jsonb) IS 'Derives the full active declared Record plan under current binding and storage locks, using the same immutable format2 plan identity as first preparation.';


--
-- Name: resolve_installation_access_plan_internal(jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.resolve_installation_access_plan_internal(
  p_installation jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  none_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  plan_key_value text;
  cached_plan jsonb;
  organization_id_value uuid;
  application_root_id_value uuid;
  application_release_revision_value bigint;
  preview_installation_id_value uuid;
  binding_item jsonb;
  release_content jsonb;
  release_revision_value bigint;
  release_validation_contract_version text;
  record_type_item jsonb;
  field_item jsonb;
  relationship_item jsonb;
  condition_item jsonb;
  permission_item jsonb;
  module_root_value uuid;
  record_type_id_value uuid;
  release_storage_contract_value uuid;
  storage_contract_value uuid;
  type_meta jsonb := '{}'::jsonb;
  relationship_by_id jsonb := '{}'::jsonb;
  condition_list jsonb := '[]'::jsonb;
  permission_by_id jsonb := '{}'::jsonb;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  mapping_row vortex_record.field_storage_mappings%rowtype;
  columns_value jsonb;
  value_expression text;
  plan jsonb;
  cacheable boolean;
begin
  -- The plan is keyed by the exact installation pins. A binding revision is
  -- advanced by every installation lifecycle transition, and a release revision
  -- is immutable, so any change to definitions, bindings, permissions or saved
  -- conditions yields a different key and therefore a different plan. A plan
  -- that no longer matches the live pins can never be selected. The plan holds
  -- declared requirements only: role grants and every other decision input are
  -- read live by Access, never from the plan.
  if p_installation is null
    or pg_catalog.jsonb_typeof(p_installation) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_installation -> 'moduleBindings') is distinct from 'array'
    or (p_installation ->> 'organizationId') is null
    or (p_installation ->> 'applicationRootId') is null
    or (p_installation ->> 'applicationReleaseRevision') is null
    or (p_installation ? 'previewInstallationId'
      and pg_catalog.jsonb_typeof(p_installation -> 'storageIdentities') is distinct from 'array')
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_installation -> 'moduleBindings') as item(value)
      where pg_catalog.jsonb_typeof(item.value) is distinct from 'object'
        or not item.value ?& array[
          'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state'
        ]
    ) then
    raise exception using errcode = '42501',
      message = 'Record installation is unavailable';
  end if;

  organization_id_value := (p_installation ->> 'organizationId')::uuid;
  application_root_id_value := (p_installation ->> 'applicationRootId')::uuid;
  application_release_revision_value :=
    (p_installation ->> 'applicationReleaseRevision')::bigint;
  preview_installation_id_value := case
    when p_installation ? 'previewInstallationId'
      then (p_installation ->> 'previewInstallationId')::uuid
    else null
  end;
  if organization_id_value = none_uuid
    or application_root_id_value = none_uuid
    or application_release_revision_value not between 1 and 9007199254740991 then
    raise exception using errcode = '42501',
      message = 'Record installation is unavailable';
  end if;

  plan_key_value := 'sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      organization_id_value::text || '|' || application_root_id_value::text || '|'
        || application_release_revision_value::text || '|'
        || case when preview_installation_id_value is null then ''
          else preview_installation_id_value::text || '|' end || coalesce((
          select pg_catalog.string_agg(
            (item.value ->> 'moduleRootId') || ':'
              || (item.value ->> 'moduleReleaseRevision') || ':'
              || (item.value ->> 'bindingRevision') || ':'
              || (item.value ->> 'state'),
            ',' order by (item.value ->> 'moduleRootId') collate "C"
          )
          from pg_catalog.jsonb_array_elements(p_installation -> 'moduleBindings') as item(value)
        ), ''),
      'UTF8'
    )),
    'hex'
  );

  -- Only an all-active pin set is cached. The storage catalogue and field
  -- mappings the plan resolves are not part of the key; storage adoption can
  -- retire a field mapping only while no provisioned or active binding pins a
  -- release that declares the field, so an active plan's mappings cannot
  -- change under it. A detached binding is not counted there, so a detached
  -- pin set is resolved afresh on every call and still refuses a retired
  -- mapping exactly as before.
  cacheable := preview_installation_id_value is null and not exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_installation -> 'moduleBindings') as item(value)
    where (item.value ->> 'state') is distinct from 'active'
  );

  if cacheable then
    select stored.plan into cached_plan
    from vortex_record.installation_access_plans as stored
    where stored.plan_key = plan_key_value;
    if cached_plan is not null then
      return cached_plan;
    end if;
  end if;

  -- Step 1: the pinned definitions. Record types, relationships and saved
  -- conditions of every bound Module, plus the declared permissions of the
  -- Application release and of each Module release. Physical tokens are
  -- resolved here too, and every disagreement refuses.
  for binding_item in
    select item.value
    from pg_catalog.jsonb_array_elements(p_installation -> 'moduleBindings') as item(value)
    -- Canonical binding order, so the plan content never depends on the order
    -- a caller happened to supply and always matches the plan key's order.
    order by (item.value ->> 'moduleRootId') collate "C"
  loop
    module_root_value := (binding_item ->> 'moduleRootId')::uuid;
    release_revision_value := (binding_item ->> 'moduleReleaseRevision')::bigint;

    select release.compilation_output #> '{canonical,content}',
      release.validation_contract_version
    into strict release_content, release_validation_contract_version
    from vortex_definition.releases as release
    where release.root_id = module_root_value
      and release.release_revision = release_revision_value;

    if pg_catalog.jsonb_typeof(release_content -> 'recordTypes') <> 'array' then
      raise exception using errcode = '55000',
        message = 'Installed Module definition is unavailable';
    end if;

    for record_type_item in
      select item.value
      from pg_catalog.jsonb_array_elements(release_content -> 'recordTypes') as item(value)
    loop
      record_type_id_value := (record_type_item ->> 'recordTypeId')::uuid;
      release_storage_contract_value := (record_type_item ->> 'storageContractId')::uuid;
      if preview_installation_id_value is null then
        storage_contract_value := release_storage_contract_value;
      else
        select (binding.value ->> 'previewStorageContractId')::uuid
        into strict storage_contract_value
        from pg_catalog.jsonb_array_elements(p_installation -> 'storageIdentities')
          as binding(value)
        where (binding.value ->> 'moduleRootId')::uuid = module_root_value
          and (binding.value ->> 'moduleReleaseRevision')::bigint = release_revision_value
          and (binding.value ->> 'recordTypeId')::uuid = record_type_id_value
          and (binding.value ->> 'releaseStorageContractId')::uuid = release_storage_contract_value;
        if not found then
          raise exception using errcode = '55000',
            message = 'Preview Record storage disagrees with its exact Module release';
        end if;
      end if;

      select catalogue.* into catalogue_row
      from vortex_record.storage_catalogue as catalogue
      where catalogue.storage_contract_id = storage_contract_value;
      if not found
        or catalogue_row.state <> 'active'
        or catalogue_row.module_root_id <> module_root_value
        or catalogue_row.record_type_id <> record_type_id_value
        or catalogue_row.storage_scope is distinct from (record_type_item ->> 'storageScope')
        or catalogue_row.physical_schema_token not in ('record_data', 'system_projection')
        -- A system projection is read only through the protected reader
        -- registered for exactly the key its installed definition declares (the
        -- catalogue key references the closed registry); a generated record
        -- type is never read through a projection, and a disagreeing key
        -- refuses.
        or (catalogue_row.physical_schema_token = 'system_projection')
          is distinct from (record_type_item ? 'systemProjection')
        or (catalogue_row.physical_schema_token = 'system_projection'
          and catalogue_row.protected_read_model_key
            is distinct from (record_type_item #>> '{systemProjection,protectedView}'))
        or (preview_installation_id_value is null and not exists (
          select 1
          from vortex_record.release_provisions as provision
          where provision.module_root_id = module_root_value
            and provision.release_revision = release_revision_value
            and release_storage_contract_value = any (provision.storage_contract_ids)
        )) then
        raise exception using errcode = '55000',
          message = 'Record storage disagrees with the installed definition';
      end if;

      -- The column map and the one value expression that reads this record
      -- type's row, built once here and reused by every load below.
      columns_value := '{}'::jsonb;
      for field_item in
        select item.value
        from pg_catalog.jsonb_array_elements(record_type_item -> 'fields') as item(value)
      loop
        select mapping.* into mapping_row
        from vortex_record.field_storage_mappings as mapping
        where mapping.storage_contract_id = storage_contract_value
          and mapping.field_id = (field_item ->> 'fieldId')::uuid;
        if not found or mapping_row.state <> 'active' then
          raise exception using errcode = '55000',
            message = 'Record storage disagrees with the installed definition';
        end if;
        columns_value := columns_value || pg_catalog.jsonb_build_object(
          pg_catalog.lower(field_item ->> 'fieldId'), pg_catalog.jsonb_build_object(
            'token', mapping_row.physical_column_token,
            'databaseValueType', mapping_row.database_value_type,
            'type', field_item ->> 'type'
          )
        );
      end loop;

      select pg_catalog.string_agg(
        field_chunk.pairs_text,
        ') || pg_catalog.jsonb_build_object(' order by field_chunk.chunk_index
      )
      into value_expression
      from (
        select (ordered_fields.field_number - 1) / 50 as chunk_index,
          pg_catalog.string_agg(
            pg_catalog.format(
              '%L, %s',
              ordered_fields.key,
              case ordered_fields.value ->> 'databaseValueType'
                when 'decimal' then
                  pg_catalog.format('pg_catalog.to_jsonb(%I::text)', ordered_fields.value ->> 'token')
                when 'timestamp_with_time_zone' then
                  pg_catalog.format(
                    'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(%I))',
                    ordered_fields.value ->> 'token'
                  )
                when 'date' then
                  pg_catalog.format(
                    'pg_catalog.to_jsonb(pg_catalog.to_char(%I, ''YYYY-MM-DD''))',
                    ordered_fields.value ->> 'token'
                  )
                else pg_catalog.format('pg_catalog.to_jsonb(%I)', ordered_fields.value ->> 'token')
              end
            ),
            ', ' order by ordered_fields.key collate "C"
          ) as pairs_text
        from (
          select column_entry.key, column_entry.value,
            pg_catalog.row_number() over (
              order by column_entry.key collate "C"
            ) as field_number
          from pg_catalog.jsonb_each(columns_value) as column_entry(key, value)
        ) as ordered_fields
        group by (ordered_fields.field_number - 1) / 50
      ) as field_chunk;

      type_meta := type_meta || pg_catalog.jsonb_build_object(
        pg_catalog.lower(record_type_id_value::text),
        pg_catalog.jsonb_build_object(
          'moduleRootId', module_root_value,
          'recordTypeId', record_type_id_value,
          'storageContractId', storage_contract_value,
          'storageScope', record_type_item ->> 'storageScope',
          'ownershipMode', record_type_item ->> 'ownershipMode',
          'releaseRevision', release_revision_value,
          'validationContractVersion', release_validation_contract_version,
          'table', catalogue_row.physical_table_token,
          'columns', columns_value,
          'valueExpression', value_expression,
          'fields', coalesce((
            select pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'fieldId', declared.value -> 'fieldId',
                'type', declared.value -> 'type'
              ) || case
                when pg_catalog.jsonb_typeof(declared.value -> 'settings') = 'object'
                  then pg_catalog.jsonb_build_object('settings', declared.value -> 'settings')
                else '{}'::jsonb
              end
              order by declared.ordinality
            )
            from pg_catalog.jsonb_array_elements(record_type_item -> 'fields')
              with ordinality as declared(value, ordinality)
          ), '[]'::jsonb)
        ) || case
          when record_type_item ? 'ownershipRelationshipId'
            then pg_catalog.jsonb_build_object(
              'ownershipRelationshipId', record_type_item -> 'ownershipRelationshipId'
            )
          else '{}'::jsonb
        end
      );

      for relationship_item in
        select item.value
        from pg_catalog.jsonb_array_elements(record_type_item -> 'relationships') as item(value)
      loop
        -- Every declared target, single or polymorphic, as one uniform list;
        -- Access proves a concrete edge target a member of it.
        relationship_by_id := relationship_by_id || pg_catalog.jsonb_build_object(
          pg_catalog.lower(relationship_item ->> 'relationshipId'),
          pg_catalog.jsonb_build_object(
            'relationshipId', relationship_item -> 'relationshipId',
            'fromModuleRootId', module_root_value,
            'fromRecordTypeId', record_type_item -> 'recordTypeId',
            'toRecordTypes', coalesce((
              select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'moduleRootId', target.value -> 'moduleRootId',
                'recordTypeId', target.value -> 'recordTypeId'
              ) order by target.ordinality)
              from pg_catalog.jsonb_array_elements(
                case when relationship_item ? 'toRecordType'
                  then pg_catalog.jsonb_build_array(relationship_item -> 'toRecordType')
                  else relationship_item -> 'toRecordTypes'
                end
              ) with ordinality as target(value, ordinality)
            ), '[]'::jsonb)
          )
        );
      end loop;
    end loop;

    for condition_item in
      select item.value
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(release_content -> 'sharingConditions') = 'array'
            then release_content -> 'sharingConditions'
          else '[]'::jsonb
        end
      ) as item(value)
    loop
      condition_list := condition_list || pg_catalog.jsonb_build_array(condition_item);
    end loop;

    for permission_item in
      select item.value
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(release_content -> 'permissions') = 'array'
            then release_content -> 'permissions'
          else '[]'::jsonb
        end
      ) as item(value)
    loop
      if pg_catalog.jsonb_typeof(permission_item -> 'recordScope') = 'object' then
        permission_by_id := permission_by_id || pg_catalog.jsonb_build_object(
          pg_catalog.lower(permission_item ->> 'permissionId'),
          pg_catalog.jsonb_build_object(
            'ownerKind', 'module',
            'ownerId', module_root_value,
            'recordTypeId', permission_item -> 'recordTypeId',
            'actionKind', permission_item -> 'actionKind',
            'namedAction', permission_item -> 'namedAction',
            'recordScope', permission_item -> 'recordScope'
          )
        );
      end if;
    end loop;
  end loop;

  if preview_installation_id_value is null then
    select release.compilation_output #> '{canonical,content}'
    into strict release_content
    from vortex_definition.releases as release
    where release.root_id = application_root_id_value
      and release.release_revision = application_release_revision_value;
  else
    release_content := p_installation #> '{candidate,compilation,canonical,content}';
    if pg_catalog.jsonb_typeof(release_content) is distinct from 'object' then
      raise exception using errcode = '55000',
        message = 'Preview Application candidate is unavailable';
    end if;
  end if;

  for permission_item in
    select item.value
    from pg_catalog.jsonb_array_elements(
      case
        when pg_catalog.jsonb_typeof(release_content -> 'permissions') = 'array'
          then release_content -> 'permissions'
        else '[]'::jsonb
      end
    ) as item(value)
  loop
    if pg_catalog.jsonb_typeof(permission_item -> 'recordScope') = 'object' then
      permission_by_id := permission_by_id || pg_catalog.jsonb_build_object(
        pg_catalog.lower(permission_item ->> 'permissionId'),
        pg_catalog.jsonb_build_object(
          'ownerKind', 'application',
          'ownerId', application_root_id_value,
          'recordTypeId', permission_item -> 'recordTypeId',
          'actionKind', permission_item -> 'actionKind',
          'namedAction', permission_item -> 'namedAction',
          'recordScope', permission_item -> 'recordScope'
        )
      );
    end if;
  end loop;

  plan := pg_catalog.jsonb_build_object(
    'organizationId', organization_id_value,
    'applicationRootId', application_root_id_value,
    'applicationReleaseRevision', application_release_revision_value,
    'recordTypes', type_meta,
    'relationships', relationship_by_id,
    'sharingConditions', condition_list,
    'permissions', permission_by_id
  ) || case when preview_installation_id_value is not null
    then pg_catalog.jsonb_build_object(
      'previewInstallationId', preview_installation_id_value
    )
    else '{}'::jsonb end;

  if not cacheable then
    return plan;
  end if;

  -- A concurrent builder may have stored the same plan first. Both were built
  -- from the same immutable pins, so either row is the same plan; this call's
  -- own plan is returned when that row is not yet visible to its snapshot.
  insert into vortex_record.installation_access_plans (
    plan_key, organization_id, application_root_id,
    application_release_revision, plan
  ) values (
    plan_key_value, organization_id_value, application_root_id_value,
    application_release_revision_value, plan
  )
  on conflict (plan_key) do nothing;

  select stored.plan into cached_plan
  from vortex_record.installation_access_plans as stored
  where stored.plan_key = plan_key_value;
  return coalesce(cached_plan, plan);
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'Installed Module definition is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installed Module definition is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.resolve_installation_access_plan_internal(p_installation jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_installation_access_plan_internal(p_installation jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_installation_access_plan_internal(p_installation jsonb) IS 'Private installation access plan builder and cache: resolves definitions, column maps, permission alternatives and saved conditions once per all-active installation binding revision; a detached pin set is resolved afresh.';


--
-- Name: resolve_installed_module_query_internal(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.resolve_installed_module_query_internal(p_module_root_id uuid, p_query_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  installation jsonb;
  query_release_revision bigint;
  query_release_version text;
  query_contract_version text;
  query_content jsonb;
  query_item jsonb;
  type_module_root_id uuid;
  type_record_type_id uuid;
  type_release_revision bigint;
  type_content jsonb;
  record_type_item jsonb;
begin
  if p_module_root_id is null or p_module_root_id = nil_uuid
    or p_query_id is null or p_query_id = nil_uuid then
    return null;
  end if;

  installation := vortex_module.read_current_active_installation();

  select (item.value ->> 'moduleReleaseRevision')::bigint
  into query_release_revision
  from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as item(value)
  where (item.value ->> 'moduleRootId')::uuid = p_module_root_id;
  if query_release_revision is null then
    return null;
  end if;

  select release.compilation_output #> '{canonical,content}',
    release.release_version, release.validation_contract_version
  into query_content, query_release_version, query_contract_version
  from vortex_definition.releases as release
  where release.root_id = p_module_root_id
    and release.release_revision = query_release_revision;
  if not found
    or query_contract_version is distinct from '3.0.0'
    or pg_catalog.jsonb_typeof(query_content -> 'queries') is distinct from 'array' then
    return null;
  end if;

  select item.value into query_item
  from pg_catalog.jsonb_array_elements(query_content -> 'queries') as item(value)
  where pg_catalog.lower(item.value ->> 'queryId') = pg_catalog.lower(p_query_id::text)
  limit 1;
  if query_item is null
    or query_item #>> '{recordType,state}' is distinct from 'resolved'
    or not coalesce(pg_catalog.pg_input_is_valid(query_item #>> '{recordType,moduleRootId}', 'uuid'), false)
    or not coalesce(pg_catalog.pg_input_is_valid(query_item #>> '{recordType,recordTypeId}', 'uuid'), false) then
    return null;
  end if;
  type_module_root_id := (query_item #>> '{recordType,moduleRootId}')::uuid;
  type_record_type_id := (query_item #>> '{recordType,recordTypeId}')::uuid;

  -- The record type may belong to a declared dependency; it must be bound to
  -- this same installation at its own pinned release.
  select (item.value ->> 'moduleReleaseRevision')::bigint
  into type_release_revision
  from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as item(value)
  where (item.value ->> 'moduleRootId')::uuid = type_module_root_id;
  if type_release_revision is null then
    return null;
  end if;

  if type_module_root_id = p_module_root_id then
    type_content := query_content;
  else
    select release.compilation_output #> '{canonical,content}'
    into type_content
    from vortex_definition.releases as release
    where release.root_id = type_module_root_id
      and release.release_revision = type_release_revision;
  end if;
  if pg_catalog.jsonb_typeof(type_content -> 'recordTypes') is distinct from 'array' then
    return null;
  end if;

  select item.value into record_type_item
  from pg_catalog.jsonb_array_elements(type_content -> 'recordTypes') as item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') = pg_catalog.lower(type_record_type_id::text)
  limit 1;
  if record_type_item is null
    or pg_catalog.jsonb_typeof(record_type_item -> 'fields') is distinct from 'array'
    or not coalesce(pg_catalog.pg_input_is_valid(record_type_item ->> 'storageContractId', 'uuid'), false) then
    return null;
  end if;

  return pg_catalog.jsonb_build_object(
    'moduleReleaseRevision', query_release_revision,
    'moduleReleaseVersion', query_release_version,
    'query', query_item,
    'recordTypeId', type_record_type_id,
    'recordTypeModuleRootId', type_module_root_id,
    'recordType', record_type_item
  );
end
$$;


ALTER FUNCTION vortex_record.resolve_installed_module_query_internal(p_module_root_id uuid, p_query_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_installed_module_query_internal(p_module_root_id uuid, p_query_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_installed_module_query_internal(p_module_root_id uuid, p_query_id uuid) IS 'Private: the exact installed Module query and its record type, or null when either is unavailable to the current installation.';


--
-- Name: resolve_named_action_context_internal(text, uuid, bigint, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.resolve_named_action_context_internal(
  p_action_owner_kind text,
  p_action_owner_id uuid,
  p_action_release_revision bigint,
  p_action_id uuid,
  p_record_type_id uuid
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  base_context jsonb;
  context_value jsonb;
  installation jsonb;
  binding_value jsonb;
  release_content jsonb;
  release_validation_version text;
  application_content jsonb;
  action_content jsonb;
  action_owner_content jsonb;
  permission_value jsonb;
  permission_candidates jsonb := '[]'::jsonb;
  permission_keys jsonb;
  permission_key text;
  matched_permission jsonb;
  required_permissions jsonb := '[]'::jsonb;
  named_action_value text;
  event_value jsonb;
  event_descriptor jsonb;
  event_descriptors jsonb := '[]'::jsonb;
  task_value jsonb;
  rules_unsupported boolean := false;
  matched_count integer;
begin
  if p_action_owner_kind is null
    or p_action_owner_kind not in ('application', 'module')
    or p_action_owner_id is null or p_action_owner_id = nil_uuid
    or p_action_release_revision is null
    or p_action_release_revision not between 1 and 9007199254740991
    or p_action_id is null or p_action_id = nil_uuid
    or p_record_type_id is null or p_record_type_id = nil_uuid then
    raise exception using errcode = '22023', message = 'Named action selector is invalid';
  end if;

  -- This existing fixed resolver owns active installation, target Module,
  -- storage/provision and field-map agreement. It decides no update authority.
  base_context := vortex_record.resolve_record_action_context_internal(
    p_record_type_id, 'update'
  );
  context_value := base_context -> 'context';
  installation := vortex_module.read_current_active_installation();

  if p_action_owner_kind = 'application' then
    if p_action_owner_id <> (context_value ->> 'applicationRootId')::uuid
      or p_action_release_revision <>
        (installation ->> 'applicationReleaseRevision')::bigint then
      raise exception using errcode = '55000', message = 'Named action owner is not installed';
    end if;
    select release.compilation_output #> '{canonical,content}',
      release.validation_contract_version
    into strict action_owner_content, release_validation_version
    from vortex_definition.releases as release
    where release.root_id = p_action_owner_id
      and release.release_revision = p_action_release_revision;
  else
    select item.value into strict binding_value
    from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as item(value)
    where (item.value ->> 'moduleRootId')::uuid = p_action_owner_id
      and (item.value ->> 'moduleReleaseRevision')::bigint = p_action_release_revision;
    select release.compilation_output #> '{canonical,content}',
      release.validation_contract_version
    into strict action_owner_content, release_validation_version
    from vortex_definition.releases as release
    where release.root_id = p_action_owner_id
      and release.release_revision = p_action_release_revision;
  end if;

  select item.value into strict action_content
  from pg_catalog.jsonb_array_elements(
    coalesce(action_owner_content -> 'actions', '[]'::jsonb)
  ) as item(value)
  where (item.value ->> 'actionId')::uuid = p_action_id
    and (item.value ->> 'subjectRecordTypeId')::uuid = p_record_type_id;

  permission_keys := case when action_content ? 'permissionKeys'
    then action_content -> 'permissionKeys'
    else pg_catalog.jsonb_build_array(action_content -> 'permissionKey') end;
  if pg_catalog.jsonb_typeof(permission_keys) <> 'array'
    or pg_catalog.jsonb_array_length(permission_keys) = 0 then
    raise exception using errcode = '55000', message = 'Named action permission is unavailable';
  end if;

  -- Collect the exact permission declarations of the active pin set. Access
  -- remains authoritative for current registrations, assignments and scopes.
  for binding_value in
    select item.value
    from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as item(value)
  loop
    select release.compilation_output #> '{canonical,content}' into strict release_content
    from vortex_definition.releases as release
    where release.root_id = (binding_value ->> 'moduleRootId')::uuid
      and release.release_revision = (binding_value ->> 'moduleReleaseRevision')::bigint;
    for permission_value in
      select item.value from pg_catalog.jsonb_array_elements(
        coalesce(release_content -> 'permissions', '[]'::jsonb)
      ) as item(value)
      where pg_catalog.jsonb_typeof(item.value -> 'recordScope') = 'object'
    loop
      permission_candidates := permission_candidates || pg_catalog.jsonb_build_array(
        permission_value || pg_catalog.jsonb_build_object(
          'ownerKind', 'module',
          'ownerId', (binding_value ->> 'moduleRootId')::uuid
        )
      );
    end loop;
    -- #578: the owning Module release's rules are evaluated by Record
    -- (`beforeSaveRules`); a rule for the subject in any other release is not.
    if (binding_value ->> 'moduleRootId')::uuid <>
        (base_context ->> 'moduleRootId')::uuid
      and exists (
        select 1 from pg_catalog.jsonb_array_elements(
          coalesce(release_content -> 'rules', '[]'::jsonb)
        ) as item(value)
        where pg_catalog.lower(item.value ->> 'subjectRecordTypeId') =
          pg_catalog.lower(p_record_type_id::text)
      ) then
      rules_unsupported := true;
    end if;
  end loop;

  select release.compilation_output #> '{canonical,content}' into strict application_content
  from vortex_definition.releases as release
  where release.root_id = (context_value ->> 'applicationRootId')::uuid
    and release.release_revision = (installation ->> 'applicationReleaseRevision')::bigint;
  for permission_value in
    select item.value from pg_catalog.jsonb_array_elements(
      coalesce(application_content -> 'permissions', '[]'::jsonb)
    ) as item(value)
    where pg_catalog.jsonb_typeof(item.value -> 'recordScope') = 'object'
  loop
    permission_candidates := permission_candidates || pg_catalog.jsonb_build_array(
      permission_value || pg_catalog.jsonb_build_object(
        'ownerKind', 'application',
        'ownerId', (context_value ->> 'applicationRootId')::uuid
      )
    );
  end loop;
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(
      coalesce(application_content -> 'rules', '[]'::jsonb)
    ) as item(value)
    where pg_catalog.lower(item.value ->> 'subjectRecordTypeId') =
      pg_catalog.lower(p_record_type_id::text)
  ) then
    rules_unsupported := true;
  end if;

  for permission_key in
    select item.value #>> '{}'
    from pg_catalog.jsonb_array_elements(permission_keys) as item(value)
  loop
    select pg_catalog.count(*), pg_catalog.min(item.value::text)::jsonb
    into matched_count, matched_permission
    from pg_catalog.jsonb_array_elements(permission_candidates) as item(value)
    where item.value ->> 'key' = permission_key;
    if matched_count <> 1
      or matched_permission ->> 'actionKind' <> 'named'
      or (matched_permission ->> 'recordTypeId')::uuid <> p_record_type_id
      or (matched_permission ->> 'namedAction') is null then
      raise exception using errcode = '55000', message = 'Named action permission is ambiguous';
    end if;
    if named_action_value is null then
      named_action_value := matched_permission ->> 'namedAction';
    elsif named_action_value is distinct from matched_permission ->> 'namedAction' then
      raise exception using errcode = '55000', message = 'Named action permission alternatives disagree';
    end if;
    required_permissions := required_permissions || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'applicationRootId', (context_value ->> 'applicationRootId')::uuid,
        'ownerKind', matched_permission ->> 'ownerKind',
        'ownerId', (matched_permission ->> 'ownerId')::uuid,
        'permissionId', (matched_permission ->> 'permissionId')::uuid
      )
    );
  end loop;
  select pg_catalog.jsonb_agg(item.value order by
    item.value ->> 'ownerKind' collate "C",
    item.value ->> 'ownerId' collate "C",
    item.value ->> 'permissionId' collate "C")
  into required_permissions
  from pg_catalog.jsonb_array_elements(required_permissions) as item(value);

  for task_value in
    select item.value from pg_catalog.jsonb_array_elements(action_content -> 'tasks')
      with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    if task_value ->> 'type' <> 'event.announce' then continue; end if;
    select item.value into strict event_value
    from pg_catalog.jsonb_array_elements(
      coalesce(action_owner_content -> 'events', '[]'::jsonb)
    ) as item(value)
    where item.value ->> 'key' = task_value #>> '{properties,eventKey}'
      and (item.value ->> 'recordTypeId')::uuid = p_record_type_id;
    event_descriptor := pg_catalog.jsonb_build_object(
      'kind', 'declared',
      'owner', case when p_action_owner_kind = 'application'
        then pg_catalog.jsonb_build_object(
          'kind', 'application', 'applicationRootId', p_action_owner_id
        )
        else pg_catalog.jsonb_build_object(
          'kind', 'module', 'moduleRootId', p_action_owner_id
        ) end,
      'declarationId', event_value -> 'eventId',
      'key', event_value -> 'key',
      'recordTypeId', event_value -> 'recordTypeId',
      'carriedFieldIds', event_value -> 'carriedFieldIds'
    );
    event_descriptors := event_descriptors || pg_catalog.jsonb_build_array(event_descriptor);
  end loop;

  return base_context || pg_catalog.jsonb_build_object(
    'actionOwner', pg_catalog.jsonb_build_object(
      'ownerKind', p_action_owner_kind,
      'ownerId', p_action_owner_id,
      'releaseRevision', p_action_release_revision
    ),
    'action', action_content,
    -- Action values follow the subject Record's owning Module contract. An
    -- Application version cannot reinterpret exact Module field values.
    'validationContractVersion', (
      select release.validation_contract_version
      from vortex_definition.releases as release
      where release.root_id = (base_context ->> 'moduleRootId')::uuid
        and release.release_revision = (base_context ->> 'moduleReleaseRevision')::bigint
    ),
    'eventDescriptors', event_descriptors,
    'rulesUnsupported', rules_unsupported,
    'declaration', pg_catalog.jsonb_build_object(
      'operationKey', action_content -> 'key',
      'action', pg_catalog.jsonb_build_object(
        'actionKind', 'named', 'namedAction', named_action_value
      ),
      'target', pg_catalog.jsonb_build_object(
        'kind', 'application',
        'applicationRootId', (context_value ->> 'applicationRootId')::uuid
      ),
      'requiredPermissions', required_permissions,
      'recordBinding', pg_catalog.jsonb_build_object(
        'moduleRootId', (base_context ->> 'moduleRootId')::uuid,
        'recordTypeId', p_record_type_id,
        'storageContractId', (base_context ->> 'storageContractId')::uuid,
        'storageScope', base_context ->> 'storageScope'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  );
exception
  when no_data_found then
    raise exception using errcode = '55000', message = 'Installed named action is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Installed named action is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.resolve_named_action_context_internal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_named_action_context_internal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_named_action_context_internal(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid) IS 'Private exact active installed action, permission-alternative and declared-Event resolver for protected named actions.';


--
-- Name: resolve_prepared_record_access_plan_internal(uuid, bigint, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.resolve_prepared_record_access_plan_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  organization_id_value uuid;
  application_root_id_value uuid;
  application_release_revision_value bigint;
  pin_fingerprint_value text;
  current_mapping jsonb;
  current_bindings jsonb;
  resolved_plan jsonb;
  mapping_fingerprint_value text;
  plan_key_value text;
  prepared_plan jsonb;
  stored_plan vortex_record.installation_access_plans%rowtype;
  inserted_rows bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) < 1 then
    raise exception using errcode = '22023',
      message = 'Prepared Record access plan command is invalid';
  end if;

  select locked.* into current_mapping
  from vortex_module.lock_prepared_installation_runtime_mapping_internal(
    p_application_root_id,
    p_application_release_revision,
    p_expected_module_bindings
  ) as locked;
  organization_id_value := (current_mapping ->> 'organizationId')::uuid;
  application_root_id_value := (current_mapping ->> 'applicationRootId')::uuid;
  application_release_revision_value :=
    (current_mapping ->> 'applicationReleaseRevision')::bigint;
  pin_fingerprint_value := current_mapping ->> 'pinFingerprint';
  if current_mapping is null
    or application_root_id_value is distinct from p_application_root_id
    or application_release_revision_value is distinct from p_application_release_revision
    or pin_fingerprint_value is null
    or pin_fingerprint_value !~ '^sha256:[a-f0-9]{64}$' then
    raise exception using errcode = '40001',
      message = 'Prepared Record access plan mapping changed';
  end if;
  current_bindings := current_mapping -> 'moduleBindings';
  resolved_plan := vortex_record.resolve_installation_access_plan_internal(
    pg_catalog.jsonb_build_object(
      'organizationId', organization_id_value,
      'applicationRootId', application_root_id_value,
      'applicationReleaseRevision', application_release_revision_value,
      'moduleBindings', current_bindings
    )
  );
  if resolved_plan is null
    or (resolved_plan ->> 'organizationId')::uuid is distinct from organization_id_value
    or (resolved_plan ->> 'applicationRootId')::uuid is distinct from application_root_id_value
    or (resolved_plan ->> 'applicationReleaseRevision')::bigint
      is distinct from application_release_revision_value then
    raise exception using errcode = '55000',
      message = 'Prepared Record access plan is unavailable';
  end if;

  mapping_fingerprint_value := 'sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      (pg_catalog.jsonb_build_object(
        'recordTypes', resolved_plan -> 'recordTypes',
        'relationships', resolved_plan -> 'relationships',
        'sharingConditions', resolved_plan -> 'sharingConditions',
        'permissions', resolved_plan -> 'permissions'
      ))::text,
      'UTF8'
    )),
    'hex'
  );
  plan_key_value := 'sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      'vortex.installation-runtime-bundle.prepared-record-access-plan.v2|' ||
        organization_id_value::text || '|' || application_root_id_value::text || '|' ||
        application_release_revision_value::text || '|2|' || pin_fingerprint_value,
      'UTF8'
    )),
    'hex'
  );
  prepared_plan := pg_catalog.jsonb_build_object(
    'planKey', plan_key_value,
    'mappingFingerprint', mapping_fingerprint_value,
    'plan', resolved_plan
  );

  insert into vortex_record.installation_access_plans (
    plan_key, organization_id, application_root_id, application_release_revision, plan
  ) values (
    plan_key_value, organization_id_value, application_root_id_value,
    application_release_revision_value, prepared_plan
  ) on conflict (plan_key) do nothing;
  get diagnostics inserted_rows = row_count;
  if inserted_rows = 0 then
    select stored.* into strict stored_plan
    from vortex_record.installation_access_plans as stored
    where stored.plan_key = plan_key_value
    for update;
    if stored_plan.organization_id is distinct from organization_id_value
      or stored_plan.application_root_id is distinct from application_root_id_value
      or stored_plan.application_release_revision is distinct from application_release_revision_value
      or stored_plan.plan is distinct from prepared_plan then
      raise exception using errcode = '23505',
        message = 'Prepared Record access plan immutable identity differs';
    end if;
    prepared_plan := stored_plan.plan;
  end if;
  return prepared_plan;
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'Prepared Record access plan evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared Record access plan evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.resolve_prepared_record_access_plan_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_prepared_record_access_plan_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_prepared_record_access_plan_internal(p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Resolves and immutably stores the exact prepared Record access plan for a first-install provisioned Module mapping.';


--
-- Name: resolve_preview_module_query_internal(uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.resolve_preview_module_query_internal(
  p_module_root_id uuid,
  p_query_id uuid
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  installation jsonb;
  module_bindings jsonb;
  storage_identities jsonb;
  preview_installation_id uuid;
  query_binding jsonb;
  query_binding_count bigint;
  query_release_revision_text text;
  query_release_revision bigint;
  query_compilation_output jsonb;
  query_content jsonb;
  query_release_version text;
  query_validation_contract_version text;
  query_source_contract_version text;
  query_item jsonb;
  query_match_count bigint := 0;
  record_type_module_root_id_text text;
  record_type_module_root_id uuid;
  record_type_id_text text;
  record_type_id uuid;
  record_type_binding jsonb;
  record_type_binding_count bigint;
  record_type_release_revision_text text;
  record_type_release_revision bigint;
  record_type_compilation_output jsonb;
  record_type_content jsonb;
  record_type_validation_contract_version text;
  record_type_source_contract_version text;
  record_type_item jsonb;
  record_type_match_count bigint := 0;
  release_storage_contract_id_text text;
  release_storage_contract_id uuid;
  storage_identity jsonb;
  storage_identity_count bigint := 0;
  preview_storage_contract_id_text text;
  preview_storage_contract_id uuid;
  preview_storage_identity_count bigint;
  catalogue_row vortex_record.storage_catalogue%rowtype;
begin
  if p_module_root_id is null or p_module_root_id = nil_uuid
    or p_query_id is null or p_query_id = nil_uuid then
    return null;
  end if;

  -- The address is transaction-local. This helper validates the human actor,
  -- organisation account, Application, ownership and expiry before returning
  -- the pinned preview; a missing or refused address never selects live state.
  installation := vortex_record.read_current_preview_installation_internal();
  if installation is null
    or pg_catalog.jsonb_typeof(installation) is distinct from 'object'
    or installation ? 'outcome'
    or not coalesce(pg_catalog.pg_input_is_valid(
      installation ->> 'previewInstallationId', 'uuid'
    ), false) then
    return null;
  end if;
  preview_installation_id := (installation ->> 'previewInstallationId')::uuid;
  if preview_installation_id = nil_uuid then
    return null;
  end if;

  module_bindings := installation -> 'moduleBindings';
  storage_identities := installation -> 'storageIdentities';
  if pg_catalog.jsonb_typeof(module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_typeof(storage_identities) is distinct from 'array' then
    return null;
  end if;

  -- Resolve the query only through one exact Module pin in this preview.
  select pg_catalog.count(*)
  into query_binding_count
  from pg_catalog.jsonb_array_elements(module_bindings) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'object'
    and pg_catalog.lower(item.value ->> 'moduleRootId') = p_module_root_id::text;
  if query_binding_count <> 1 then
    return null;
  end if;
  select item.value into query_binding
  from pg_catalog.jsonb_array_elements(module_bindings) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'object'
    and pg_catalog.lower(item.value ->> 'moduleRootId') = p_module_root_id::text;
  if query_binding ->> 'state' is distinct from 'active' then
    return null;
  end if;
  query_release_revision_text := query_binding ->> 'moduleReleaseRevision';
  if not coalesce(pg_catalog.pg_input_is_valid(query_release_revision_text, 'bigint'), false) then
    return null;
  end if;
  query_release_revision := query_release_revision_text::bigint;
  if query_release_revision not between 1 and 9007199254740991 then
    return null;
  end if;

  select release.compilation_output, release.compilation_output #> '{canonical,content}',
    release.release_version, release.validation_contract_version,
    release.source_contract_version
  into query_compilation_output, query_content, query_release_version, query_validation_contract_version,
    query_source_contract_version
  from vortex_definition.releases as release
  where release.root_id = p_module_root_id
    and release.release_revision = query_release_revision;
  if not found
    or query_validation_contract_version is distinct from '3.0.0'
    or query_source_contract_version is distinct from query_validation_contract_version
    or query_compilation_output #>> '{kind}' is distinct from 'module'
    or query_compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from p_module_root_id::text
    or query_compilation_output #>> '{validationContractVersion}'
      is distinct from query_validation_contract_version
    or pg_catalog.jsonb_typeof(query_content -> 'queries') is distinct from 'array' then
    return null;
  end if;

  for query_item in
    select item.value
    from pg_catalog.jsonb_array_elements(query_content -> 'queries') as item(value)
    where pg_catalog.lower(item.value ->> 'queryId') = p_query_id::text
  loop
    query_match_count := query_match_count + 1;
  end loop;
  if query_match_count <> 1 then
    return null;
  end if;
  select item.value into query_item
  from pg_catalog.jsonb_array_elements(query_content -> 'queries') as item(value)
  where pg_catalog.lower(item.value ->> 'queryId') = p_query_id::text;
  if pg_catalog.jsonb_typeof(query_item) is distinct from 'object'
    or query_item #>> '{recordType,state}' is distinct from 'resolved' then
    return null;
  end if;

  record_type_module_root_id_text := query_item #>> '{recordType,moduleRootId}';
  record_type_id_text := query_item #>> '{recordType,recordTypeId}';
  if not coalesce(pg_catalog.pg_input_is_valid(record_type_module_root_id_text, 'uuid'), false)
    or not coalesce(pg_catalog.pg_input_is_valid(record_type_id_text, 'uuid'), false) then
    return null;
  end if;
  record_type_module_root_id := record_type_module_root_id_text::uuid;
  record_type_id := record_type_id_text::uuid;
  if record_type_module_root_id = nil_uuid or record_type_id = nil_uuid then
    return null;
  end if;

  -- The referenced record type may be in a dependency, but that dependency
  -- must also have one active pin in this same preview installation.
  select pg_catalog.count(*)
  into record_type_binding_count
  from pg_catalog.jsonb_array_elements(module_bindings) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'object'
    and pg_catalog.lower(item.value ->> 'moduleRootId') = record_type_module_root_id::text;
  if record_type_binding_count <> 1 then
    return null;
  end if;
  select item.value into record_type_binding
  from pg_catalog.jsonb_array_elements(module_bindings) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'object'
    and pg_catalog.lower(item.value ->> 'moduleRootId') = record_type_module_root_id::text;
  if record_type_binding ->> 'state' is distinct from 'active' then
    return null;
  end if;
  record_type_release_revision_text := record_type_binding ->> 'moduleReleaseRevision';
  if not coalesce(pg_catalog.pg_input_is_valid(record_type_release_revision_text, 'bigint'), false) then
    return null;
  end if;
  record_type_release_revision := record_type_release_revision_text::bigint;
  if record_type_release_revision not between 1 and 9007199254740991 then
    return null;
  end if;

  if record_type_module_root_id = p_module_root_id then
    if record_type_release_revision <> query_release_revision then
      return null;
    end if;
    record_type_compilation_output := query_compilation_output;
    record_type_content := query_content;
    record_type_validation_contract_version := query_validation_contract_version;
    record_type_source_contract_version := query_source_contract_version;
  else
    select release.compilation_output, release.compilation_output #> '{canonical,content}',
      release.validation_contract_version, release.source_contract_version
    into record_type_compilation_output, record_type_content, record_type_validation_contract_version,
      record_type_source_contract_version
    from vortex_definition.releases as release
    where release.root_id = record_type_module_root_id
      and release.release_revision = record_type_release_revision;
    if not found then
      return null;
    end if;
  end if;
  if record_type_validation_contract_version not in ('2.0.0', '3.0.0')
    or record_type_source_contract_version is distinct from record_type_validation_contract_version
    or record_type_compilation_output #>> '{kind}' is distinct from 'module'
    or record_type_compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from record_type_module_root_id::text
    or record_type_compilation_output #>> '{validationContractVersion}'
      is distinct from record_type_validation_contract_version
    or pg_catalog.jsonb_typeof(record_type_content -> 'recordTypes') is distinct from 'array' then
    return null;
  end if;

  for record_type_item in
    select item.value
    from pg_catalog.jsonb_array_elements(record_type_content -> 'recordTypes') as item(value)
    where pg_catalog.lower(item.value ->> 'recordTypeId') = record_type_id::text
  loop
    record_type_match_count := record_type_match_count + 1;
  end loop;
  if record_type_match_count <> 1 then
    return null;
  end if;
  select item.value into record_type_item
  from pg_catalog.jsonb_array_elements(record_type_content -> 'recordTypes') as item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') = record_type_id::text;
  if pg_catalog.jsonb_typeof(record_type_item) is distinct from 'object'
    or pg_catalog.jsonb_typeof(record_type_item -> 'fields') is distinct from 'array'
    or not coalesce(pg_catalog.pg_input_is_valid(
      record_type_item ->> 'storageContractId', 'uuid'
    ), false) then
    return null;
  end if;
  release_storage_contract_id_text := record_type_item ->> 'storageContractId';
  release_storage_contract_id := release_storage_contract_id_text::uuid;
  if release_storage_contract_id = nil_uuid then
    return null;
  end if;

  -- Match one storage identity against both exact release pins and the
  -- declaration's release storage contract; duplicates or malformed mappings
  -- never choose an arbitrary preview table.
  for storage_identity in
    select item.value
    from pg_catalog.jsonb_array_elements(storage_identities) as item(value)
    where pg_catalog.jsonb_typeof(item.value) = 'object'
      and pg_catalog.lower(item.value ->> 'moduleRootId') = record_type_module_root_id::text
      and item.value ->> 'moduleReleaseRevision' = record_type_release_revision::text
      and pg_catalog.lower(item.value ->> 'recordTypeId') = record_type_id::text
      and pg_catalog.lower(item.value ->> 'releaseStorageContractId') = release_storage_contract_id::text
  loop
    storage_identity_count := storage_identity_count + 1;
  end loop;
  if storage_identity_count <> 1 then
    return null;
  end if;
  select item.value into storage_identity
  from pg_catalog.jsonb_array_elements(storage_identities) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'object'
    and pg_catalog.lower(item.value ->> 'moduleRootId') = record_type_module_root_id::text
    and item.value ->> 'moduleReleaseRevision' = record_type_release_revision::text
    and pg_catalog.lower(item.value ->> 'recordTypeId') = record_type_id::text
    and pg_catalog.lower(item.value ->> 'releaseStorageContractId') = release_storage_contract_id::text;
  preview_storage_contract_id_text := storage_identity ->> 'previewStorageContractId';
  if not coalesce(pg_catalog.pg_input_is_valid(preview_storage_contract_id_text, 'uuid'), false) then
    return null;
  end if;
  preview_storage_contract_id := preview_storage_contract_id_text::uuid;
  if preview_storage_contract_id = nil_uuid then
    return null;
  end if;
  select pg_catalog.count(*)
  into preview_storage_identity_count
  from pg_catalog.jsonb_array_elements(storage_identities) as item(value)
  where pg_catalog.jsonb_typeof(item.value) = 'object'
    and pg_catalog.lower(item.value ->> 'previewStorageContractId')
      = preview_storage_contract_id::text;
  if preview_storage_identity_count <> 1 then
    return null;
  end if;

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = preview_storage_contract_id;
  if not found
    or catalogue_row.state is distinct from 'active'
    or catalogue_row.physical_schema_token is distinct from 'record_data'
    or catalogue_row.module_root_id is distinct from record_type_module_root_id
    or catalogue_row.record_type_id is distinct from record_type_id
    or catalogue_row.storage_scope is distinct from (record_type_item ->> 'storageScope')
    or catalogue_row.first_compatible_release_revision is distinct from record_type_release_revision
    or catalogue_row.last_compatible_release_revision is distinct from record_type_release_revision
    or catalogue_row.record_type_definition ->> 'storageContractId'
      is distinct from preview_storage_contract_id::text
    or pg_catalog.lower(catalogue_row.record_type_definition ->> 'recordTypeId')
      is distinct from record_type_id::text
    or catalogue_row.record_type_definition ->> 'storageScope'
      is distinct from (record_type_item ->> 'storageScope') then
    return null;
  end if;

  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_installation_id,
    'moduleRootId', p_module_root_id,
    'moduleReleaseRevision', query_release_revision,
    'moduleReleaseVersion', query_release_version,
    'query', query_item,
    'recordTypeId', record_type_id,
    'recordTypeModuleRootId', record_type_module_root_id,
    'recordTypeModuleReleaseRevision', record_type_release_revision,
    'releaseStorageContractId', release_storage_contract_id,
    'previewStorageContractId', preview_storage_contract_id,
    'storageScope', record_type_item ->> 'storageScope',
    'recordType', record_type_item
  );
end
$function$;


ALTER FUNCTION vortex_record.resolve_preview_module_query_internal(p_module_root_id uuid, p_query_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_preview_module_query_internal(p_module_root_id uuid, p_query_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_preview_module_query_internal(p_module_root_id uuid, p_query_id uuid) IS 'Private preview-only resolver for one query and its exact pinned record type and active preview storage identity; it validates the current human-owned unexpired preview and never falls back to an active installation.';


--
-- Name: resolve_record_action_context_internal(uuid, text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.resolve_record_action_context_internal(
  p_record_type_id uuid,
  p_action_kind text
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  context_value jsonb;
  application_root_id_value uuid;
  installation jsonb;
  preview_installation jsonb;
  preview_installation_id_value uuid;
  binding_item jsonb;
  module_content jsonb;
  application_content jsonb;
  module_root_id_value uuid;
  module_release_revision_value bigint;
  record_type_value jsonb;
  candidate_record_type_value jsonb;
  release_storage_contract_id uuid;
  target_module_root_id uuid;
  target_release_revision bigint;
  target_storage_contract_id uuid;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  field_item jsonb;
  field_mapping vortex_record.field_storage_mappings%rowtype;
  columns_value jsonb := '{}'::jsonb;
  required_permissions jsonb := '[]'::jsonb;
  permission_item jsonb;
begin
  if p_record_type_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_action_kind is null
    or p_action_kind not in ('create', 'read', 'update', 'delete', 'restore') then
    raise exception using errcode = '22023', message = 'Record action selector is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId' then
    raise exception using errcode = '42501',
      message = 'Record action requires an application context';
  end if;
  application_root_id_value := (context_value ->> 'applicationRootId')::uuid;
  preview_installation :=
    vortex_record.read_current_preview_installation_internal();
  if preview_installation is not null then
    if preview_installation ->> 'outcome' = 'refused'
      or p_action_kind not in ('create', 'read', 'update') then
      return pg_catalog.jsonb_build_object('outcome', 'refused');
    end if;
    installation := preview_installation;
    preview_installation_id_value :=
      (preview_installation ->> 'previewInstallationId')::uuid;
  else
    installation := vortex_module.read_current_active_installation();
  end if;

  for binding_item in
    select item.value
    from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as item(value)
  loop
    module_root_id_value := (binding_item ->> 'moduleRootId')::uuid;
    module_release_revision_value := (binding_item ->> 'moduleReleaseRevision')::bigint;
    select release.compilation_output #> '{canonical,content}' into strict module_content
    from vortex_definition.releases as release
    where release.root_id = module_root_id_value
      and release.release_revision = module_release_revision_value;

    select item.value into candidate_record_type_value
    from pg_catalog.jsonb_array_elements(module_content -> 'recordTypes') as item(value)
    where (item.value ->> 'recordTypeId')::uuid = p_record_type_id;
    if found then
      if target_module_root_id is not null then
        raise exception using errcode = '55000',
          message = 'Installed record type identity is ambiguous';
      end if;
      target_module_root_id := module_root_id_value;
      target_release_revision := module_release_revision_value;
      record_type_value := candidate_record_type_value;
      release_storage_contract_id := (record_type_value ->> 'storageContractId')::uuid;
      target_storage_contract_id := release_storage_contract_id;
      if preview_installation_id_value is not null then
        select (binding.value ->> 'previewStorageContractId')::uuid
        into strict target_storage_contract_id
        from pg_catalog.jsonb_array_elements(installation -> 'storageIdentities')
          as binding(value)
        where (binding.value ->> 'moduleRootId')::uuid = target_module_root_id
          and (binding.value ->> 'moduleReleaseRevision')::bigint = target_release_revision
          and (binding.value ->> 'recordTypeId')::uuid = p_record_type_id
          and (binding.value ->> 'releaseStorageContractId')::uuid = release_storage_contract_id;
        if not found then
          return pg_catalog.jsonb_build_object('outcome', 'refused');
        end if;
      end if;
      for permission_item in
        select item.value
        from pg_catalog.jsonb_array_elements(
          coalesce(module_content -> 'permissions', '[]'::jsonb)
        ) as item(value)
        where (item.value ->> 'recordTypeId')::uuid = p_record_type_id
          and item.value ->> 'actionKind' = p_action_kind
          and (item.value ->> 'namedAction') is null
      loop
        required_permissions := required_permissions || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'applicationRootId', application_root_id_value,
            'ownerKind', 'module', 'ownerId', target_module_root_id,
            'permissionId', (permission_item ->> 'permissionId')::uuid
          )
        );
      end loop;
    end if;
  end loop;

  if target_module_root_id is null then
    raise exception using errcode = '55000',
      message = 'Record type is not part of the active installation';
  end if;

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = target_storage_contract_id;
  if not found or catalogue_row.state <> 'active'
    or catalogue_row.module_root_id <> target_module_root_id
    or catalogue_row.record_type_id <> p_record_type_id
    or catalogue_row.storage_scope is distinct from (record_type_value ->> 'storageScope')
    or (preview_installation_id_value is null
      and catalogue_row.physical_schema_token not in ('record_data', 'system_projection'))
    or (preview_installation_id_value is not null
      and catalogue_row.physical_schema_token <> 'record_data')
    or (catalogue_row.physical_schema_token = 'system_projection')
      is distinct from (record_type_value ? 'systemProjection')
    or (catalogue_row.physical_schema_token = 'system_projection'
      and catalogue_row.protected_read_model_key
        is distinct from (record_type_value #>> '{systemProjection,protectedView}'))
    or (catalogue_row.physical_schema_token = 'system_projection'
      and not coalesce(
        (record_type_value #> '{standardActions}') ? p_action_kind,
        false
      ))
    or (preview_installation_id_value is null and not exists (
      select 1 from vortex_record.release_provisions as provision
      where provision.module_root_id = target_module_root_id
        and provision.release_revision = target_release_revision
        and release_storage_contract_id = any (provision.storage_contract_ids)
    )) then
    raise exception using errcode = '55000',
      message = 'Record storage disagrees with the active installation';
  end if;

  for field_item in
    select item.value from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as item(value)
  loop
    select mapping.* into field_mapping
    from vortex_record.field_storage_mappings as mapping
    where mapping.storage_contract_id = target_storage_contract_id
      and mapping.field_id = (field_item ->> 'fieldId')::uuid;
    if not found or field_mapping.state <> 'active' then
      raise exception using errcode = '55000',
        message = 'Record field storage disagrees with the active installation';
    end if;
    columns_value := columns_value || pg_catalog.jsonb_build_object(
      pg_catalog.lower(field_item ->> 'fieldId'),
      pg_catalog.jsonb_build_object(
        'token', field_mapping.physical_column_token,
        'databaseValueType', field_mapping.database_value_type,
        'type', field_item ->> 'type',
        'required', field_item -> 'required',
        'settings', field_item -> 'settings'
      )
    );
  end loop;

  if preview_installation_id_value is null then
    select release.compilation_output #> '{canonical,content}' into strict application_content
    from vortex_definition.releases as release
    where release.root_id = application_root_id_value
      and release.release_revision = (installation ->> 'applicationReleaseRevision')::bigint;
  else
    application_content :=
      installation #> '{candidate,compilation,canonical,content}';
    if pg_catalog.jsonb_typeof(application_content) is distinct from 'object' then
      return pg_catalog.jsonb_build_object('outcome', 'refused');
    end if;
  end if;
  for permission_item in
    select item.value
    from pg_catalog.jsonb_array_elements(
      coalesce(application_content -> 'permissions', '[]'::jsonb)
    ) as item(value)
    where (item.value ->> 'recordTypeId')::uuid = p_record_type_id
      and item.value ->> 'actionKind' = p_action_kind
      and (item.value ->> 'namedAction') is null
  loop
    required_permissions := required_permissions || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'applicationRootId', application_root_id_value,
        'ownerKind', 'application', 'ownerId', application_root_id_value,
        'permissionId', (permission_item ->> 'permissionId')::uuid
      )
    );
  end loop;

  required_permissions := coalesce((
    select pg_catalog.jsonb_agg(item.value order by
      item.value ->> 'ownerKind' collate "C", item.value ->> 'permissionId' collate "C")
    from pg_catalog.jsonb_array_elements(required_permissions) as item(value)
  ), '[]'::jsonb);

  return pg_catalog.jsonb_build_object(
    'context', context_value,
    'recordType', record_type_value,
    'moduleRootId', target_module_root_id,
    'moduleReleaseRevision', target_release_revision,
    'storageContractId', target_storage_contract_id,
    'storageScope', record_type_value ->> 'storageScope',
    'table', catalogue_row.physical_table_token,
    'columns', columns_value,
    'declaration', case when preview_installation_id_value is not null
      then pg_catalog.jsonb_build_object(
        'operationKey', 'record.' || p_action_kind,
        'action', pg_catalog.jsonb_build_object('actionKind', p_action_kind),
        'target', pg_catalog.jsonb_build_object(
          'kind', 'application', 'applicationRootId', application_root_id_value
        ),
        'requiredPermissions', required_permissions,
        'recordBinding', pg_catalog.jsonb_build_object(
          'moduleRootId', target_module_root_id,
          'recordTypeId', p_record_type_id,
          'storageContractId', target_storage_contract_id,
          'storageScope', record_type_value ->> 'storageScope'
        ),
        'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
        'authority', pg_catalog.jsonb_build_object('kind', 'preview_owner')
      )
      when pg_catalog.jsonb_array_length(required_permissions) = 0 then null
      else pg_catalog.jsonb_build_object(
        'operationKey', 'record.' || p_action_kind,
        'action', pg_catalog.jsonb_build_object('actionKind', p_action_kind),
        'target', pg_catalog.jsonb_build_object(
          'kind', 'application', 'applicationRootId', application_root_id_value
        ),
        'requiredPermissions', required_permissions,
        'recordBinding', pg_catalog.jsonb_build_object(
          'moduleRootId', target_module_root_id,
          'recordTypeId', p_record_type_id,
          'storageContractId', target_storage_contract_id,
          'storageScope', record_type_value ->> 'storageScope'
        ),
        'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
        'authority', pg_catalog.jsonb_build_object('kind', 'permission')
      ) end
  ) || case when preview_installation_id_value is not null
    then pg_catalog.jsonb_build_object(
      'previewInstallationId', preview_installation_id_value
    )
    else '{}'::jsonb end;
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'Installed definition evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installed definition evidence is ambiguous';
end
$function$;


ALTER FUNCTION vortex_record.resolve_record_action_context_internal(p_record_type_id uuid, p_action_kind text) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION resolve_record_action_context_internal(p_record_type_id uuid, p_action_kind text); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.resolve_record_action_context_internal(p_record_type_id uuid, p_action_kind text) IS 'Private Record metadata resolver over one exact live installation or an owner-validated, unexpired preview storage binding; preview contexts support only reads and base record changes.';


--
-- Name: restore_record_internal(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.restore_record_internal(
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  meta jsonb;
  context_value jsonb;
  loaded jsonb;
  facts jsonb;
  record_fact jsonb;
  decision jsonb;
  field_item jsonb;
  relationship_value jsonb;
  edge_row vortex_record.relationship_edges%rowtype;
  target_catalogue vortex_record.storage_catalogue%rowtype;
  retained_value jsonb;
  retained_target_type_id uuid;
  retained_target_record_id uuid;
  target_loaded jsonb;
  target_decision jsonb;
  target_record jsonb;
  target_scope jsonb;
  field_required boolean;
  application_root_required boolean;
  changed_rows integer;
  app_scope uuid;
  saved_record_id uuid;
  saved_concurrency_number bigint;
  preview_installation jsonb;
  notice_sequence bigint;
begin
  if p_record_type_id is null or p_record_id is null
    or p_expected_concurrency_number not between 1 and 9007199254740990 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'command_invalid');
  end if;
  begin
    meta := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'restore');
    context_value := meta -> 'context';
    loaded := vortex_record.load_record_access_facts_internal(
      p_record_type_id, 'restore', p_record_id, p_expected_concurrency_number
    );
    if loaded ->> 'outcome' = 'conflict' then
      return pg_catalog.jsonb_build_object(
        'outcome', 'conflict', 'concurrencyNumber', loaded -> 'concurrencyNumber'
      );
    end if;
    if loaded ->> 'outcome' <> 'loaded'
      or pg_catalog.jsonb_typeof(meta -> 'declaration') <> 'object' then
      raise exception using errcode = 'P0002', message = 'Record is unavailable';
    end if;
    select item.value into record_fact
    from pg_catalog.jsonb_array_elements(loaded -> 'facts' -> 'records') as item(value)
    where (item.value -> 'recordScope' ->> 'recordId')::uuid = p_record_id;
    if record_fact ->> 'lifecycleState' <> 'soft_deleted' then
      raise exception using errcode = 'P0002', message = 'Record is unavailable';
    end if;

    -- Restore access is decided over the retained row projected as the active
    -- candidate it would become.  The retained values/owner are unchanged.
    facts := (loaded -> 'facts') || pg_catalog.jsonb_build_object(
      'binding', meta -> 'declaration' -> 'recordBinding',
      'records', (
        select pg_catalog.jsonb_agg(
          case when (item.value -> 'recordScope' ->> 'recordId')::uuid = p_record_id
            then item.value || pg_catalog.jsonb_build_object('lifecycleState', 'active')
            else item.value end order by item.ordinality
        )
        from pg_catalog.jsonb_array_elements(loaded -> 'facts' -> 'records')
          with ordinality as item(value, ordinality)
      )
    );
    decision := vortex_access.evaluate_organization_record_access_internal(
      meta -> 'declaration', p_record_id, facts
    );
    if decision ->> 'outcome' <> 'allowed' then
      raise exception using errcode = 'P0002', message = 'Record is unavailable';
    end if;

    -- A restore keeps the retained values. Validate the narrow invariants this
    -- primitive owns: every currently required non-link value is present,
    -- non-null and has its canonical storage shape; every required link agrees
    -- with exactly one retained edge to a locked, active, currently readable
    -- target. Full final-value settings validation remains owned by #47.
    for field_item in
      select item.value from pg_catalog.jsonb_array_elements(meta -> 'recordType' -> 'fields') as item(value)
      where coalesce((item.value ->> 'required')::boolean, false)
        or (item.value ->> 'type' in ('link', 'link_to_one_of_several')
          and coalesce((item.value #>> '{settings,applicationRootIdRequired}')::boolean, false))
    loop
      field_required := coalesce((field_item ->> 'required')::boolean, false);
      application_root_required := coalesce(
        (field_item #>> '{settings,applicationRootIdRequired}')::boolean, false
      );
      retained_value := record_fact -> 'fieldValues'
        -> pg_catalog.lower(field_item ->> 'fieldId');
      if not ((record_fact -> 'fieldValues') ? pg_catalog.lower(field_item ->> 'fieldId'))
        or pg_catalog.jsonb_typeof(retained_value) = 'null' then
        if field_required then
          raise exception using errcode = '23514', message = 'Required retained value is unavailable';
        end if;
        continue;
      end if;

      if field_item ->> 'type' not in ('link', 'link_to_one_of_several') then
        if not vortex_record.canonical_record_value_matches(
          retained_value,
          field_item ->> 'type',
          meta -> 'columns' -> pg_catalog.lower(field_item ->> 'fieldId')
            ->> 'databaseValueType'
        ) then
          raise exception using errcode = '23514', message = 'Required retained value is invalid';
        end if;
        continue;
      end if;

      select item.value into strict relationship_value
      from pg_catalog.jsonb_array_elements(meta -> 'recordType' -> 'relationships') as item(value)
      where (item.value ->> 'fromFieldId')::uuid = (field_item ->> 'fieldId')::uuid;

      -- The retained value names its concrete target type; it must be one of
      -- the relationship's declared targets and the retained edge's target.
      if pg_catalog.jsonb_typeof(retained_value) <> 'object'
        or not (retained_value ?& array['recordTypeId', 'recordId'])
        or retained_value - array['recordTypeId', 'recordId'] <> '{}'::jsonb then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
      begin
        retained_target_type_id := (retained_value ->> 'recordTypeId')::uuid;
        retained_target_record_id := (retained_value ->> 'recordId')::uuid;
      exception when invalid_text_representation then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end;
      if retained_target_record_id = '00000000-0000-0000-0000-000000000000'::uuid then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
      if not vortex_record.relationship_declares_target_internal(
        relationship_value, retained_target_type_id
      ) then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;

      select edge.* into strict edge_row
      from vortex_record.relationship_edges as edge
      where edge.relationship_id = (relationship_value ->> 'relationshipId')::uuid
        and edge.from_organisation_id = (context_value ->> 'organizationId')::uuid
        and edge.from_storage_contract_id = (meta ->> 'storageContractId')::uuid
        and edge.from_record_id = p_record_id;
      if edge_row.to_organisation_id <> (context_value ->> 'organizationId')::uuid
        or edge_row.to_record_id <> retained_target_record_id then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
      select catalogue.* into strict target_catalogue
      from vortex_record.storage_catalogue as catalogue
      where catalogue.storage_contract_id = edge_row.to_storage_contract_id
        and catalogue.record_type_id = retained_target_type_id
        and catalogue.physical_schema_token in ('record_data', 'system_projection')
        and catalogue.state = 'active';
      if application_root_required
        and (target_catalogue.physical_schema_token is distinct from 'system_projection'
          or target_catalogue.protected_read_model_key is distinct from 'organization_accounts') then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;

      perform vortex_record.lock_relationship_target_row_internal(
        retained_target_type_id, retained_target_record_id,
        (context_value ->> 'organizationId')::uuid
      );

      target_loaded := vortex_record.load_record_access_facts_internal(
        retained_target_type_id, 'read', retained_target_record_id, null
      );
      if target_loaded ->> 'outcome' <> 'loaded'
        or pg_catalog.jsonb_typeof(target_loaded -> 'declaration') <> 'object' then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
      target_decision := vortex_access.evaluate_organization_record_access_internal(
        target_loaded -> 'declaration', retained_target_record_id, target_loaded -> 'facts'
      );
      if target_decision ->> 'outcome' <> 'allowed' then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
      select item.value into target_record
      from pg_catalog.jsonb_array_elements(target_loaded -> 'facts' -> 'records') as item(value)
      where (item.value -> 'recordScope' ->> 'recordId')::uuid = retained_target_record_id;
      target_scope := target_record -> 'recordScope';
      if target_record is null or target_record ->> 'lifecycleState' <> 'active'
        or (target_scope ->> 'organizationId')::uuid <>
          (context_value ->> 'organizationId')::uuid
        or edge_row.to_application_root_id is distinct from (
          case when target_scope ->> 'storageScope' = 'application_contained'
            then (target_scope ->> 'applicationRootId')::uuid else null end
        ) then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
      if application_root_required
        and not vortex_access.organization_account_has_current_application_access_internal(
          (context_value ->> 'organizationId')::uuid,
          retained_target_record_id,
          (context_value ->> 'applicationRootId')::uuid
        ) then
        raise exception using errcode = '23514', message = 'Required relationship is unavailable';
      end if;
    end loop;

    execute pg_catalog.format(
      'update record_data.%I as stored
       set lifecycle_state = ''active'', concurrency_number = concurrency_number + 1,
         updated_at = pg_catalog.statement_timestamp(), updated_by = $3,
         deleted_at = null, deleted_by = null, removal_due_at = null,
         definition_revision = $4
       where organisation_id = $1 and record_id = $2
         and lifecycle_state = ''soft_deleted'' and concurrency_number = $5
       returning stored.record_id, stored.concurrency_number',
      meta ->> 'table'
    ) into saved_record_id, saved_concurrency_number
      using (context_value ->> 'organizationId')::uuid, p_record_id,
      (context_value ->> 'organizationAccountId')::uuid,
      (meta ->> 'moduleReleaseRevision')::bigint, p_expected_concurrency_number;
    get diagnostics changed_rows = row_count;
    if changed_rows <> 1 then
      raise exception using errcode = '40001', message = 'Record restore revision changed';
    end if;
    app_scope := case when meta ->> 'storageScope' = 'application_contained'
      then (context_value ->> 'applicationRootId')::uuid else null end;
    preview_installation :=
      vortex_record.read_current_preview_installation_internal();
    if preview_installation is null
      and meta ->> 'storageScope' = 'application_contained' then
      begin
        notice_sequence := pg_catalog.nextval(
          'vortex_record.record_invalidation_sequence'::pg_catalog.regclass
        );
        perform vortex_invalidation.publish_change_notice(
          (context_value ->> 'organizationId')::uuid,
          (context_value ->> 'applicationRootId')::uuid,
          p_record_type_id,
          saved_record_id,
          saved_concurrency_number,
          'changed',
          notice_sequence,
          notice_sequence,
          (context_value ->> 'correlationId')::uuid
        );
      exception when others then
        -- Allocation and publication are advisory; the guarded write is not.
        null;
      end;
    else
      perform vortex_record.bump_record_data_version_internal(
        (context_value ->> 'organizationId')::uuid,
        (meta ->> 'storageContractId')::uuid, app_scope
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'outcome', 'completed', 'recordId', saved_record_id,
      'concurrencyNumber', saved_concurrency_number
    );
  exception
    when serialization_failure or deadlock_detected then
      return pg_catalog.jsonb_build_object('outcome', 'conflict');
    when no_data_found or too_many_rows or insufficient_privilege or check_violation
      or object_not_in_prerequisite_state then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'record_unavailable');
  end;
end
$function$;


ALTER FUNCTION vortex_record.restore_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION restore_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.restore_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) IS 'Private revision-checked restore primitive over retained facts, current Access, current definition, required relationships and every non-null Person link with required application access; it locks record or protected projection targets through the canonical relationship lock and enforces no recovery window.';


--
-- Name: run_module_query(uuid, uuid, bigint, jsonb, jsonb, integer, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.run_module_query(
  p_module_root_id uuid,
  p_query_id uuid,
  p_expected_release_revision bigint,
  p_input_values jsonb,
  p_requested_field_ids jsonb,
  p_page_size integer,
  p_after jsonb,
  p_requested_system_field_keys jsonb,
  p_user_inputs jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  -- The most candidate rows one request examines. A page that the budget ends
  -- early still returns a position, so a later request resumes exactly there.
  scan_limit constant integer := 500;
  uuid_pattern constant text :=
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  prepared_plan jsonb;
  storage_plan jsonb;
  context_organization_id uuid;
  context_application_root_id uuid;
  resolved jsonb;
  query_item jsonb;
  record_type_item jsonb;
  record_type_id_value uuid;
  v_storage_contract_id uuid;
  mapping_row vortex_record.field_storage_mappings%rowtype;
  field_item jsonb;
  fields_by_id jsonb := '{}'::jsonb;
  field_key text;
  selected_ids text[];
  requested_ids text[] := array[]::text[];
  sort_item jsonb;
  sort_ids text[] := array[]::text[];
  declared_sort_ids text[] := array[]::text[];
  sort_directions text[] := array[]::text[];
  sort_value_sql text[] := array[]::text[];
  sort_sql_types text[] := array[]::text[];
  filter_condition jsonb;
  filter_ids text[] := array[]::text[];
  filter_types jsonb := '{}'::jsonb;
  filter_nulls jsonb := '{}'::jsonb;
  filter_expressions text[] := array[]::text[];
  filter_predicate text;
  filter_parameters jsonb := '[]'::jsonb;
  parameter_types jsonb := '{}'::jsonb;
  parameter_values jsonb := '{}'::jsonb;
  after_sort_key text[];
  after_record_id uuid;
  sort_index integer;
  column_sql text;
  value_sql text;
  pushed boolean;
  after_terms text[] := array[]::text[];
  equal_prefix text := '';
  keyset_sql text := '';
  order_terms text[] := array[]::text[];
  sort_key_terms text[] := array[]::text[];
  order_by_sql text;
  scan_sql text;
  readable_field_ids text[] := array[]::text[];
  access_sql text;
  access_parameters jsonb := '[]'::jsonb;
  access_owner_account_id uuid;
  access_owner_group_ids uuid[] := array[]::uuid[];
  access_shared_record_ids uuid[] := array[]::uuid[];
  physical_table_token text;
  storage_scope text;
  scan_record record;
  examined integer := 0;
  budget_exhausted boolean := false;
  more_rows boolean := false;
  passes boolean;
  needs_refusal_check boolean;
  projection jsonb;
  readable_values jsonb;
  row_capabilities jsonb;
  rows_value jsonb := '[]'::jsonb;
  row_count integer := 0;
  last_examined_sort_key text[];
  last_examined_record_id uuid;
  last_returned_sort_key text[];
  last_returned_record_id uuid;
  next_value jsonb := null;
  system_field_keys text[] := array[]::text[];
  system_key text;
  system_expressions text[] := array[]::text[];
  system_columns_sql text;
  read_time_field boolean;
  read_time_clock jsonb;
  read_time_sql text;
  list_key text;
  declared_list jsonb;
  parsed_ids text[];
  declared_lists jsonb := '{}'::jsonb;
  declared_sortable_ids text[] := array[]::text[];
  declared_searchable_ids text[] := array[]::text[];
  user_sort jsonb;
  user_search text;
  user_search_folded text;
  effective_sort jsonb;
  effective_sort_is_user boolean := false;
  search_candidate_ids text[] := array[]::text[];
  search_field_ids text[] := array[]::text[];
  search_matches boolean;
  board_member_mode boolean := false;
  group_member_mode boolean := false;
  board_member jsonb;
  board_choice_field_id text;
  board_column_kind text;
  board_column_value text;
  board_options jsonb;
  board_option_values text[] := array[]::text[];
  board_option jsonb;
  board_member_matches boolean;
  group_member jsonb;
  group_selector jsonb;
  group_selector_item jsonb;
  group_selector_value jsonb;
  group_selector_values jsonb := '{}'::jsonb;
  group_selector_types jsonb := '{}'::jsonb;
  group_candidate_values jsonb;
  group_by_ids text[] := array[]::text[];
  group_key text;
  group_field_type text;
  group_value_valid boolean;
  group_member_matches boolean;
  preview_mode boolean := false;
begin
  -- Request shape. Nothing here is authority; it only bounds the work.
  if p_requested_field_ids is null
    or pg_catalog.jsonb_typeof(p_requested_field_ids) <> 'array'
    or pg_catalog.jsonb_array_length(p_requested_field_ids) not between 1 and 200
    or p_page_size is null or p_page_size not between 1 and 200 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  for field_item in select item.value from pg_catalog.jsonb_array_elements(p_requested_field_ids) as item(value) loop
    if pg_catalog.jsonb_typeof(field_item) <> 'string'
      or pg_catalog.lower(field_item #>> '{}') !~ uuid_pattern
      or pg_catalog.lower(field_item #>> '{}') = any (requested_ids) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    requested_ids := pg_catalog.array_append(requested_ids, pg_catalog.lower(field_item #>> '{}'));
  end loop;

  -- Declared system values: a closed set, each named at most once.
  if p_requested_system_field_keys is null then
    p_requested_system_field_keys := '[]'::jsonb;
  end if;
  if pg_catalog.jsonb_typeof(p_requested_system_field_keys) <> 'array'
    or pg_catalog.jsonb_array_length(p_requested_system_field_keys) > 5 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  for field_item in
    select item.value from pg_catalog.jsonb_array_elements(p_requested_system_field_keys) as item(value)
  loop
    if pg_catalog.jsonb_typeof(field_item) <> 'string'
      or (field_item #>> '{}') not in ('created_at', 'created_by', 'updated_at', 'updated_by', 'owner')
      or (field_item #>> '{}') = any (system_field_keys) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    system_field_keys := pg_catalog.array_append(system_field_keys, field_item #>> '{}');
  end loop;

  -- User-facing sort and search, plus the user filter passed to shared
  -- preparation. The component's declared field sets only narrow user input;
  -- they never supply authority or replace the published query contract.
  if p_user_inputs is null then
    p_user_inputs := '{}'::jsonb;
  end if;
  if pg_catalog.jsonb_typeof(p_user_inputs) <> 'object' then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  board_member_mode := p_user_inputs ? 'boardMember';
  group_member_mode := p_user_inputs ? 'groupMember';
  if board_member_mode and group_member_mode then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(p_user_inputs) as supplied(key)
    where supplied.key not in (
      'sort', 'filter', 'search', 'sortableFieldIds', 'filterableFieldIds', 'searchableFieldIds',
      'boardMember', 'groupMember'
    )
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  if group_member_mode then
    group_member := p_user_inputs -> 'groupMember';
    if pg_catalog.jsonb_typeof(group_member) is distinct from 'object' then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    if group_member - array['values']::text[] <> '{}'::jsonb
      or not (group_member ? 'values')
      or pg_catalog.jsonb_typeof(group_member -> 'values') is distinct from 'array' then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    if pg_catalog.jsonb_array_length(group_member -> 'values') not between 1 and 10 then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    group_selector := group_member -> 'values';
    for group_selector_item in
      select item.value from pg_catalog.jsonb_array_elements(group_selector) as item(value)
    loop
      if pg_catalog.jsonb_typeof(group_selector_item) is distinct from 'object' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
      end if;
      if group_selector_item - array['fieldId', 'fieldType', 'value']::text[] <> '{}'::jsonb
        or not (group_selector_item ? 'fieldId')
        or not (group_selector_item ? 'fieldType')
        or not (group_selector_item ? 'value')
        or pg_catalog.jsonb_typeof(group_selector_item -> 'fieldId') is distinct from 'string'
        or pg_catalog.lower(group_selector_item ->> 'fieldId') !~ uuid_pattern
        or pg_catalog.lower(group_selector_item ->> 'fieldId') = '00000000-0000-0000-0000-000000000000'
        or pg_catalog.jsonb_typeof(group_selector_item -> 'fieldType') is distinct from 'string'
        or group_selector_item ->> 'fieldType' not in (
          'text', 'whole_number', 'decimal_number', 'yes_no', 'date', 'date_time',
          'choice', 'reference_number', 'email_address', 'phone_number', 'web_address',
          'link', 'link_to_one_of_several', 'link_to_person'
        ) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
      end if;
      group_key := pg_catalog.lower(group_selector_item ->> 'fieldId');
      if group_selector_types ? group_key then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
      end if;
      group_field_type := group_selector_item ->> 'fieldType';
      group_selector_value := group_selector_item -> 'value';
      group_value_valid := group_selector_value = 'null'::jsonb;
      if not group_value_valid then
        case group_field_type
          when 'text', 'reference_number', 'email_address', 'phone_number', 'web_address' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'string';
          when 'choice' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'string'
              and pg_catalog.length(group_selector_value #>> '{}') between 1 and 120;
          when 'whole_number' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'number'
              and case when pg_catalog.pg_input_is_valid(group_selector_value #>> '{}', 'numeric') then
                (group_selector_value #>> '{}')::numeric = pg_catalog.trunc((group_selector_value #>> '{}')::numeric)
                and pg_catalog.abs((group_selector_value #>> '{}')::numeric) <= 9007199254740991
              else false end;
          when 'decimal_number' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'string'
              and group_selector_value #>> '{}' ~ '^-?(0|[1-9][0-9]*)(\.[0-9]+)?$';
          when 'yes_no' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'boolean';
          when 'date' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'string'
              and group_selector_value #>> '{}' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_catalog.pg_input_is_valid(group_selector_value #>> '{}', 'date');
          when 'date_time' then
            group_value_valid := pg_catalog.jsonb_typeof(group_selector_value) = 'string'
              and group_selector_value #>> '{}' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?(Z|[+-][0-9]{2}:[0-9]{2})$'
              and pg_catalog.substr(group_selector_value #>> '{}', 12, 2) between '00' and '23'
              and pg_catalog.substr(group_selector_value #>> '{}', 15, 2) between '00' and '59'
              and (pg_catalog.substr(group_selector_value #>> '{}', 17, 1) <> ':'
                or pg_catalog.substr(group_selector_value #>> '{}', 18, 2) between '00' and '59')
              and pg_catalog.pg_input_is_valid(group_selector_value #>> '{}', 'timestamp with time zone');
          when 'link', 'link_to_one_of_several' then
            group_value_valid := case when pg_catalog.jsonb_typeof(group_selector_value) = 'object' then
              group_selector_value - array['recordTypeId', 'recordId']::text[] = '{}'::jsonb
              and group_selector_value ? 'recordTypeId' and group_selector_value ? 'recordId'
              and pg_catalog.jsonb_typeof(group_selector_value -> 'recordTypeId') = 'string'
              and pg_catalog.lower(group_selector_value ->> 'recordTypeId') ~ uuid_pattern
              and pg_catalog.lower(group_selector_value ->> 'recordTypeId') <> '00000000-0000-0000-0000-000000000000'
              and pg_catalog.jsonb_typeof(group_selector_value -> 'recordId') = 'string'
              and pg_catalog.lower(group_selector_value ->> 'recordId') ~ uuid_pattern
              and pg_catalog.lower(group_selector_value ->> 'recordId') <> '00000000-0000-0000-0000-000000000000'
            else false end;
          when 'link_to_person' then
            group_value_valid := case when pg_catalog.jsonb_typeof(group_selector_value) = 'object' then
              group_selector_value - array['organizationAccountId']::text[] = '{}'::jsonb
              and group_selector_value ? 'organizationAccountId'
              and pg_catalog.jsonb_typeof(group_selector_value -> 'organizationAccountId') = 'string'
              and pg_catalog.lower(group_selector_value ->> 'organizationAccountId') ~ uuid_pattern
              and pg_catalog.lower(group_selector_value ->> 'organizationAccountId') <> '00000000-0000-0000-0000-000000000000'
            else false end;
          else
            group_value_valid := false;
        end case;
      end if;
      if not group_value_valid then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
      end if;
      group_selector_types := group_selector_types || pg_catalog.jsonb_build_object(group_key, group_field_type);
      group_selector_values := group_selector_values || pg_catalog.jsonb_build_object(group_key, group_selector_value);
    end loop;
  end if;
  if board_member_mode then
    board_member := p_user_inputs -> 'boardMember';
    if pg_catalog.jsonb_typeof(board_member) is distinct from 'object'
      or board_member - array['choiceFieldId', 'column']::text[] <> '{}'::jsonb
      or not (board_member ? 'choiceFieldId') or not (board_member ? 'column')
      or pg_catalog.jsonb_typeof(board_member -> 'choiceFieldId') is distinct from 'string'
      or pg_catalog.lower(board_member ->> 'choiceFieldId') !~ uuid_pattern then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    board_choice_field_id := pg_catalog.lower(board_member ->> 'choiceFieldId');
    if pg_catalog.jsonb_typeof(board_member -> 'column') is distinct from 'object'
      or pg_catalog.jsonb_typeof(board_member #> '{column,kind}') is distinct from 'string' then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    board_column_kind := board_member #>> '{column,kind}';
    if board_column_kind = 'option' then
      if (board_member #> '{column}') - array['kind', 'value']::text[] <> '{}'::jsonb
        or not ((board_member #> '{column}') ? 'value')
        or pg_catalog.jsonb_typeof(board_member #> '{column,value}') is distinct from 'string'
        or coalesce(pg_catalog.length(board_member #>> '{column,value}'), 0) not between 1 and 120 then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      board_column_value := board_member #>> '{column,value}';
    elsif board_column_kind = 'unassigned' then
      if (board_member #> '{column}') - array['kind']::text[] <> '{}'::jsonb then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      board_column_value := null;
    else
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
  end if;

  -- The list-only sortable and searchable allow-lists contain distinct field
  -- identities. Query preparation validates the filterable allow-list.
  for list_key in
    select pg_catalog.unnest(array['sortableFieldIds', 'searchableFieldIds'])
  loop
    declared_list := coalesce(p_user_inputs -> list_key, '[]'::jsonb);
    if pg_catalog.jsonb_typeof(declared_list) <> 'array' then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    if pg_catalog.jsonb_array_length(declared_list) > 200 then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
    end if;
    parsed_ids := array[]::text[];
    for field_item in
      select item.value from pg_catalog.jsonb_array_elements(declared_list) as item(value)
    loop
      if pg_catalog.jsonb_typeof(field_item) <> 'string'
        or pg_catalog.lower(field_item #>> '{}') !~ uuid_pattern
        or pg_catalog.lower(field_item #>> '{}') = any (parsed_ids) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
      end if;
      parsed_ids := pg_catalog.array_append(parsed_ids, pg_catalog.lower(field_item #>> '{}'));
    end loop;
    declared_lists := declared_lists || pg_catalog.jsonb_build_object(list_key, pg_catalog.to_jsonb(parsed_ids));
  end loop;
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[]) into declared_sortable_ids
  from pg_catalog.jsonb_array_elements_text(declared_lists -> 'sortableFieldIds') as item(value);
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[]) into declared_searchable_ids
  from pg_catalog.jsonb_array_elements_text(declared_lists -> 'searchableFieldIds') as item(value);

  -- The user's sort: the same pair shape as the published sort, bounded and each
  -- direction valid. It replaces the published order only when it is non-empty.
  user_sort := coalesce(p_user_inputs -> 'sort', '[]'::jsonb);
  if pg_catalog.jsonb_typeof(user_sort) <> 'array' then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  if pg_catalog.jsonb_array_length(user_sort) > 20 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;

  -- The user's search: one bounded, non-blank text term; a blank term is absent.
  if p_user_inputs ? 'search'
    and pg_catalog.jsonb_typeof(p_user_inputs -> 'search') not in ('string', 'null') then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  user_search := pg_catalog.btrim(p_user_inputs ->> 'search');
  if user_search = '' then
    user_search := null;
  end if;
  if user_search is not null and pg_catalog.length(user_search) > 200 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  user_search_folded := pg_catalog.lower(user_search);
  if (board_member_mode or group_member_mode) and (
    pg_catalog.jsonb_array_length(user_sort) <> 0
    or user_search is not null
    or pg_catalog.cardinality(declared_sortable_ids) <> 0
    or pg_catalog.cardinality(declared_searchable_ids) <> 0
    or (group_member_mode and p_user_inputs ? 'search'
      and pg_catalog.jsonb_typeof(p_user_inputs -> 'search') is distinct from 'null')
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;

  foreach system_key in array system_field_keys loop
    system_expressions := pg_catalog.array_append(system_expressions, pg_catalog.format('%L, %s', system_key,
      case system_key
        when 'created_at' then
          'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(stored.created_at))'
        when 'updated_at' then
          'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(stored.updated_at))'
        when 'created_by' then 'pg_catalog.to_jsonb(stored.created_by)'
        when 'updated_by' then 'pg_catalog.to_jsonb(stored.updated_by)'
        else
          'case when stored.owner_organisation_account_id is not null then pg_catalog.jsonb_build_object(''kind'', ''organization_account'', ''organizationAccountId'', stored.owner_organisation_account_id) when stored.owner_group_id is not null then pg_catalog.jsonb_build_object(''kind'', ''group'', ''groupId'', stored.owner_group_id) else ''null''::jsonb end'
      end));
  end loop;
  system_columns_sql := pg_catalog.array_to_string(system_expressions, ', ');

  prepared_plan := vortex_record.prepare_module_query_internal(
    p_module_root_id, p_query_id, p_expected_release_revision, p_input_values,
    p_user_inputs -> 'filter', coalesce(p_user_inputs -> 'filterableFieldIds', '[]'::jsonb),
    'resolution', null
  );
  if prepared_plan ->> 'outcome' is distinct from 'prepared' then
    return prepared_plan;
  end if;

  resolved := prepared_plan -> 'resolved';
  query_item := prepared_plan -> 'query';
  record_type_item := prepared_plan -> 'recordType';
  record_type_id_value := (prepared_plan ->> 'recordTypeId')::uuid;
  context_organization_id := (prepared_plan #>> '{scope,organizationId}')::uuid;
  context_application_root_id := (prepared_plan #>> '{scope,applicationRootId}')::uuid;
  preview_mode := prepared_plan ? 'preview';
  if preview_mode and (
    board_member_mode or group_member_mode or pg_catalog.cardinality(system_field_keys) > 0
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
  end if;

  for field_item in
    select item.value from pg_catalog.jsonb_array_elements(record_type_item -> 'fields') as item(value)
  loop
    fields_by_id := fields_by_id || pg_catalog.jsonb_build_object(
      pg_catalog.lower(field_item ->> 'fieldId'), field_item
    );
  end loop;

  -- Grouped and totalled shapes are not plain rows. Only separately validated
  -- board and generic group member modes may read members from those Queries.
  if pg_catalog.jsonb_typeof(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) is distinct from 'array'
    or pg_catalog.jsonb_typeof(coalesce(query_item -> 'aggregates', '[]'::jsonb)) is distinct from 'array' then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
  end if;
  if pg_catalog.jsonb_array_length(coalesce(query_item -> 'aggregates', '[]'::jsonb)) > 20 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
  end if;
  if group_member_mode then
    if pg_catalog.jsonb_array_length(query_item -> 'groupByFieldIds') not between 1 and 10 then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    for field_item in
      select item.value from pg_catalog.jsonb_array_elements(query_item -> 'groupByFieldIds') as item(value)
    loop
      if pg_catalog.jsonb_typeof(field_item) is distinct from 'string'
        or pg_catalog.lower(field_item #>> '{}') !~ uuid_pattern
        or pg_catalog.lower(field_item #>> '{}') = '00000000-0000-0000-0000-000000000000' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      group_key := pg_catalog.lower(field_item #>> '{}');
      group_field_type := coalesce(fields_by_id -> group_key ->> 'type', '');
      if group_key = any (group_by_ids)
        or group_field_type not in (
          'text', 'whole_number', 'decimal_number', 'yes_no', 'date', 'date_time',
          'choice', 'reference_number', 'email_address', 'phone_number', 'web_address',
          'link', 'link_to_one_of_several', 'link_to_person'
        ) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      group_by_ids := pg_catalog.array_append(group_by_ids, group_key);
    end loop;
    if pg_catalog.jsonb_array_length(group_selector) <> pg_catalog.cardinality(group_by_ids)
      or exists (
        select 1 from pg_catalog.jsonb_object_keys(group_selector_types) as supplied(key)
        where supplied.key <> all (group_by_ids)
      ) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    foreach group_key in array group_by_ids loop
      if group_selector_types ->> group_key is distinct from fields_by_id -> group_key ->> 'type' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
    end loop;
  elsif board_member_mode then
    if pg_catalog.jsonb_array_length(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) <> 1 then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
  elsif pg_catalog.jsonb_array_length(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) > 0
    or pg_catalog.jsonb_array_length(coalesce(query_item -> 'aggregates', '[]'::jsonb)) > 0 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
  end if;
  if coalesce((query_item ->> 'relationshipHops')::integer, 0) <> 0 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'relationship_invalid');
  end if;
  if p_page_size > coalesce((query_item ->> 'pageSize')::integer, 0) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'page_size_invalid');
  end if;

  prepared_plan := vortex_record.prepare_module_query_internal(
    p_module_root_id, p_query_id, p_expected_release_revision, p_input_values,
    p_user_inputs -> 'filter', coalesce(p_user_inputs -> 'filterableFieldIds', '[]'::jsonb),
    'storage', prepared_plan
  );
  if prepared_plan ->> 'outcome' is distinct from 'prepared' then
    return prepared_plan;
  end if;
  storage_plan := prepared_plan;
  v_storage_contract_id := (prepared_plan #>> '{storage,storageContractId}')::uuid;
  preview_mode := prepared_plan ? 'preview';
  physical_table_token := prepared_plan #>> '{storage,physicalTableToken}';
  storage_scope := prepared_plan #>> '{storage,storageScope}';
  access_sql := coalesce(prepared_plan #>> '{access,predicate}', 'true');
  access_parameters := coalesce(prepared_plan #> '{access,parameters}', '[]'::jsonb);
  access_owner_account_id := nullif(prepared_plan #>> '{access,ownerAccountId}', '')::uuid;
  select coalesce(pg_catalog.array_agg(item.value::uuid), array[]::uuid[])
  into access_owner_group_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan #> '{access,ownerGroupIds}') as item(value);
  select coalesce(pg_catalog.array_agg(item.value::uuid), array[]::uuid[])
  into access_shared_record_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan #> '{access,sharedRecordIds}') as item(value);
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[])
  into readable_field_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan -> 'readableFieldIds') as item(value);

  -- Search authority: the record type's own declared search priority. A component
  -- with only a search box declares no per-field list, so an empty declared set
  -- searches every field the record type marks searchable; a declared set narrows
  -- it. A row matches only through a field the reader can see on that row, so a
  -- hidden searchable value never decides a match.
  if pg_catalog.cardinality(declared_searchable_ids) > 0 then
    search_candidate_ids := declared_searchable_ids;
  else
    select coalesce(pg_catalog.array_agg(item.key), array[]::text[])
    into search_candidate_ids
    from pg_catalog.jsonb_object_keys(fields_by_id) as item(key);
  end if;
  foreach field_key in array search_candidate_ids loop
    if (fields_by_id ? field_key)
      and (fields_by_id -> field_key ->> 'searchPriority') in ('first', 'normal', 'last') then
      search_field_ids := pg_catalog.array_append(search_field_ids, field_key);
    end if;
  end loop;

  -- Projection: only fields the published query selects.
  select coalesce(pg_catalog.array_agg(pg_catalog.lower(item.value #>> '{}')), array[]::text[])
  into selected_ids
  from pg_catalog.jsonb_array_elements(query_item -> 'selectedFieldIds') as item(value);
  if exists (select 1 from pg_catalog.unnest(requested_ids) as requested(id) where requested.id <> all (selected_ids)) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'field_unbounded');
  end if;
  if board_member_mode then
    if pg_catalog.lower(query_item #>> '{groupByFieldIds,0}') is distinct from board_choice_field_id
      or not (board_choice_field_id = any (selected_ids))
      or not (fields_by_id ? board_choice_field_id)
      or fields_by_id -> board_choice_field_id ->> 'type' is distinct from 'choice'
      or coalesce((fields_by_id -> board_choice_field_id ->> 'filterable')::boolean, false) is not true then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    board_options := fields_by_id #> array[board_choice_field_id, 'settings', 'options'];
    if pg_catalog.jsonb_typeof(board_options) is distinct from 'array'
      or pg_catalog.jsonb_array_length(board_options) not between 1 and 12 then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    for board_option in select item.value from pg_catalog.jsonb_array_elements(board_options) as item(value) loop
      if pg_catalog.jsonb_typeof(board_option) is distinct from 'object'
        or board_option - array['value', 'label', 'requiredPermissionId']::text[] <> '{}'::jsonb
        or not (board_option ? 'value') or not (board_option ? 'label')
        or pg_catalog.jsonb_typeof(board_option -> 'value') is distinct from 'string'
        or coalesce(pg_catalog.length(board_option ->> 'value'), 0) not between 1 and 120
        or pg_catalog.jsonb_typeof(board_option -> 'label') is distinct from 'string'
        or coalesce(pg_catalog.length(pg_catalog.btrim(board_option ->> 'label')), 0) not between 1 and 60
        or (board_option ? 'requiredPermissionId' and (
          pg_catalog.jsonb_typeof(board_option -> 'requiredPermissionId') is distinct from 'string'
          or pg_catalog.lower(board_option ->> 'requiredPermissionId') !~ uuid_pattern
          or pg_catalog.lower(board_option ->> 'requiredPermissionId') = '00000000-0000-0000-0000-000000000000'
        ))
        or (board_option ->> 'value') collate "C" = any (board_option_values) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      board_option_values := pg_catalog.array_append(board_option_values, board_option ->> 'value');
    end loop;
    if board_column_kind = 'option'
      and not (board_column_value collate "C" = any (board_option_values)) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
  end if;

  -- Order: the published sort, or the user's chosen sort when one is supplied,
  -- over orderable typed columns, then the record id. A published sort field the
  -- reader is not guaranteed to see is validated but never pushed, so the scan
  -- order never depends on a value it may withhold. A user sort must instead be a
  -- field the component declares sortable, the record type declares sortable and
  -- the reader is guaranteed to see: silently ordering by something else would be
  -- wrong, so it is refused rather than pushed away.
  if board_member_mode or group_member_mode then
    effective_sort := '[]'::jsonb;
    effective_sort_is_user := false;
  elsif pg_catalog.jsonb_array_length(user_sort) > 0 then
    effective_sort := user_sort;
    effective_sort_is_user := true;
  else
    effective_sort := query_item -> 'sort';
    effective_sort_is_user := false;
  end if;
  for sort_item in
    select item.value from pg_catalog.jsonb_array_elements(effective_sort) as item(value)
  loop
    field_key := pg_catalog.lower(sort_item ->> 'fieldId');
    if field_key is null or not (fields_by_id ? field_key)
      or sort_item ->> 'direction' not in ('ascending', 'descending')
      or field_key = any (declared_sort_ids) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'sort_invalid');
    end if;
    if effective_sort_is_user
      and (not (field_key = any (declared_sortable_ids))
        or coalesce((fields_by_id -> field_key ->> 'sortable')::boolean, false) is not true) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'sort_invalid');
    end if;
    select mapping.* into mapping_row
    from vortex_record.field_storage_mappings as mapping
    where mapping.storage_contract_id = v_storage_contract_id
      and mapping.field_id = field_key::uuid;
    if not found or mapping_row.state is distinct from 'active' then
      if preview_mode then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'query_unavailable');
      end if;
      raise exception using errcode = '55000',
        message = 'Record storage disagrees with the installed definition';
    end if;
    declared_sort_ids := pg_catalog.array_append(declared_sort_ids, field_key);
    pushed := field_key = any (readable_field_ids);
    if effective_sort_is_user and not pushed then
      -- The user's order must actually be the scan order.
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'sort_invalid');
    end if;
    -- A read-time field is worked out inside this statement, from the
    -- record's own stored values and one statement timestamp; it is never a
    -- stored column here.
    read_time_field := fields_by_id -> field_key ->> 'type' = 'calculation'
      and (fields_by_id -> field_key #>> '{settings,evaluation}' = 'read_time'
        or fields_by_id -> field_key #>> '{settings,expression,kind}' = 'deadline_passed');
    if read_time_field then
      read_time_clock := coalesce(read_time_clock, vortex_record.read_time_clock_internal());
      read_time_sql := vortex_record.read_time_deadline_expression_internal(
        v_storage_contract_id, fields_by_id -> field_key #> '{settings,expression}',
        read_time_clock
      );
      if read_time_sql is null then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'sort_invalid');
      end if;
      if not pushed then
        continue;
      end if;
      sort_ids := pg_catalog.array_append(sort_ids, field_key);
      sort_directions := pg_catalog.array_append(sort_directions, sort_item ->> 'direction');
      sort_value_sql := pg_catalog.array_append(sort_value_sql, read_time_sql);
      sort_sql_types := pg_catalog.array_append(sort_sql_types, 'boolean');
      continue;
    end if;
    -- JSON-valued fields (money, links, choice sets, documents) have no total
    -- order here; money in particular is never ordered across currencies.
    if mapping_row.database_value_type not in (
      'integer', 'decimal', 'boolean', 'date', 'timestamp_with_time_zone', 'text', 'uuid'
    ) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'sort_invalid');
    end if;
    if not pushed then
      continue;
    end if;
    sort_ids := pg_catalog.array_append(sort_ids, field_key);
    sort_directions := pg_catalog.array_append(sort_directions, sort_item ->> 'direction');
    sort_value_sql := pg_catalog.array_append(
      sort_value_sql, pg_catalog.format('stored.%I', mapping_row.physical_column_token)
    );
    sort_sql_types := pg_catalog.array_append(sort_sql_types, case mapping_row.database_value_type
      when 'integer' then 'bigint'
      when 'decimal' then 'numeric'
      when 'boolean' then 'boolean'
      when 'date' then 'date'
      when 'timestamp_with_time_zone' then 'timestamp with time zone'
      when 'uuid' then 'uuid'
      else 'text' end);
  end loop;
  if pg_catalog.cardinality(declared_sort_ids) = 0
    and not board_member_mode and not group_member_mode then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'sort_invalid');
  end if;

  prepared_plan := vortex_record.prepare_module_query_internal(
    p_module_root_id, p_query_id, p_expected_release_revision, p_input_values,
    p_user_inputs -> 'filter', coalesce(p_user_inputs -> 'filterableFieldIds', '[]'::jsonb),
    'complete', prepared_plan
  );
  if prepared_plan ->> 'outcome' is distinct from 'prepared' then
    return prepared_plan;
  end if;
  if preview_mode and (
    prepared_plan -> 'storage' is distinct from storage_plan -> 'storage'
    or prepared_plan -> 'fieldMappings' is distinct from storage_plan -> 'fieldMappings'
    or prepared_plan -> 'readableFieldIds' is distinct from storage_plan -> 'readableFieldIds'
    or prepared_plan -> 'access' is distinct from storage_plan -> 'access'
  ) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'query_unavailable');
  end if;
  filter_condition := prepared_plan #> '{filter,residualCondition}';
  if filter_condition = 'null'::jsonb then
    filter_condition := null;
  end if;
  filter_types := coalesce(prepared_plan #> '{filter,residualFieldTypes}', '{}'::jsonb);
  filter_nulls := coalesce(prepared_plan #> '{filter,residualNullValues}', '{}'::jsonb);
  parameter_types := coalesce(prepared_plan #> '{filter,residualInputTypes}', '{}'::jsonb);
  parameter_values := coalesce(prepared_plan #> '{filter,residualInputs}', '{}'::jsonb);
  filter_predicate := coalesce(prepared_plan #>> '{filter,pushedPredicate}', 'true');
  filter_parameters := coalesce(prepared_plan #> '{filter,pushedParameters}', '[]'::jsonb);
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[])
  into filter_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan -> 'filterFieldIds') as item(value);
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[])
  into filter_expressions
  from pg_catalog.jsonb_array_elements_text(prepared_plan #> '{filter,expressions}') as item(value);

  -- The keyset position, which must fit this exact order. The cursor carries
  -- only the readable sort fields' values and a record identity, so it never
  -- carries a hidden field value.
  if p_after is not null and p_after <> 'null'::jsonb then
    if pg_catalog.jsonb_typeof(p_after) <> 'object'
      or p_after - array['sortKey', 'recordId']::text[] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(p_after -> 'sortKey') is distinct from 'array'
      or pg_catalog.jsonb_array_length(p_after -> 'sortKey') <> pg_catalog.cardinality(sort_ids)
      or pg_catalog.jsonb_typeof(p_after -> 'recordId') is distinct from 'string'
      or pg_catalog.lower(p_after ->> 'recordId') !~ uuid_pattern
      or exists (
        select 1 from pg_catalog.jsonb_array_elements(p_after -> 'sortKey') as item(value)
        where pg_catalog.jsonb_typeof(item.value) not in ('string', 'null')
      ) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'cursor_invalid');
    end if;
    select pg_catalog.array_agg(item.value #>> '{}' order by item.ordinality)
    into after_sort_key
    from pg_catalog.jsonb_array_elements(p_after -> 'sortKey') with ordinality as item(value, ordinality);
    after_record_id := (p_after ->> 'recordId')::uuid;
    for sort_index in 1 .. pg_catalog.cardinality(sort_ids) loop
      if after_sort_key[sort_index] is not null
        and not pg_catalog.pg_input_is_valid(after_sort_key[sort_index], sort_sql_types[sort_index]) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'cursor_invalid');
      end if;
    end loop;
  end if;

  -- The scan. Identifiers come only from the storage catalogue; every value is
  -- a bound parameter. Nulls order first ascending and last descending. The
  -- order always ends with the record id, so the keyset stays total even when
  -- no readable sort field may be pushed.
  for sort_index in 1 .. pg_catalog.cardinality(sort_ids) loop
    column_sql := case when sort_sql_types[sort_index] = 'text'
      then sort_value_sql[sort_index] || ' collate "C"'
      else sort_value_sql[sort_index] end;
    order_terms := pg_catalog.array_append(order_terms, column_sql || case
      when sort_directions[sort_index] = 'ascending' then ' asc nulls first'
      else ' desc nulls last' end);
    sort_key_terms := pg_catalog.array_append(sort_key_terms, case sort_sql_types[sort_index]
      when 'timestamp with time zone' then pg_catalog.format(
        'vortex_context.format_timestamp_utc(%s)',
        sort_value_sql[sort_index])
      when 'date' then pg_catalog.format(
        'pg_catalog.to_char(%s, ''YYYY-MM-DD'')', sort_value_sql[sort_index])
      else pg_catalog.format('(%s)::text', sort_value_sql[sort_index]) end);

    if after_record_id is not null then
      value_sql := case when sort_sql_types[sort_index] = 'text'
        then pg_catalog.format('$3[%s] collate "C"', sort_index)
        else pg_catalog.format('($3[%s])::%s', sort_index, sort_sql_types[sort_index]) end;
      if after_sort_key[sort_index] is null then
        after_terms := pg_catalog.array_append(after_terms, equal_prefix || case
          when sort_directions[sort_index] = 'ascending'
            then pg_catalog.format('(%s) is not null', sort_value_sql[sort_index])
          else 'false' end);
        equal_prefix := equal_prefix
          || pg_catalog.format('(%s) is null and ', sort_value_sql[sort_index]);
      else
        after_terms := pg_catalog.array_append(after_terms, equal_prefix || case
          when sort_directions[sort_index] = 'ascending'
            then pg_catalog.format('coalesce(%s > %s, false)', column_sql, value_sql)
          else pg_catalog.format('((%s) is null or coalesce(%s < %s, false))',
            sort_value_sql[sort_index], column_sql, value_sql) end);
        equal_prefix := equal_prefix
          || pg_catalog.format('coalesce(%s = %s, false) and ', column_sql, value_sql);
      end if;
    end if;
  end loop;
  if after_record_id is not null then
    after_terms := pg_catalog.array_append(after_terms, equal_prefix || 'stored.record_id > $4');
    keyset_sql := ' and ((' || pg_catalog.array_to_string(after_terms, ') or (') || '))';
  end if;
  order_by_sql := pg_catalog.array_to_string(order_terms, ', ');
  if order_by_sql = '' then
    order_by_sql := 'stored.record_id asc';
  else
    order_by_sql := order_by_sql || ', stored.record_id asc';
  end if;

  scan_sql := pg_catalog.format(
    'select stored.record_id,
       array[%s]::text[] as sort_key,
       pg_catalog.jsonb_build_object(%s) as filter_values,
       pg_catalog.jsonb_build_object(%s) as system_values
     from record_data.%I as stored
     where stored.organisation_id = $1
       and stored.lifecycle_state = ''active''
       and %s
       and (%s)
       and (%s)%s
     order by %s
     limit $5',
    pg_catalog.array_to_string(sort_key_terms, ', '),
    (select pg_catalog.string_agg(
       filter_chunk.pairs_text,
       ') || pg_catalog.jsonb_build_object(' order by filter_chunk.chunk_index
     )
     from (
       select (filter_pair.pair_number - 1) / 50 as chunk_index,
         pg_catalog.string_agg(
           filter_pair.pair_text, ', ' order by filter_pair.pair_number
         ) as pairs_text
       from pg_catalog.unnest(filter_expressions)
         with ordinality as filter_pair(pair_text, pair_number)
       group by (filter_pair.pair_number - 1) / 50
     ) as filter_chunk),
    system_columns_sql,
    physical_table_token,
    case when storage_scope = 'application_contained'
      then 'stored.application_root_id = $2' else 'stored.application_root_id is null' end,
    access_sql,
    filter_predicate,
    keyset_sql,
    order_by_sql
  );

  for scan_record in execute scan_sql
    using context_organization_id, context_application_root_id, after_sort_key,
      after_record_id, scan_limit + 1, access_owner_account_id,
      access_owner_group_ids, access_shared_record_ids,
      filter_parameters, access_parameters
  loop
    examined := examined + 1;
    if examined > scan_limit then
      budget_exhausted := true;
      exit;
    end if;

    -- The filter is evaluated on stored values first only to avoid reading
    -- rows it rejects; a row it admits is still read through the protected
    -- projection, and every filtered and sorted field must be readable there.
    -- A value the condition engine refuses decides nothing until the row is
    -- known to be readable, so an unreadable row can never cause a refusal.
    needs_refusal_check := false;
    if filter_condition is null then
      passes := true;
    else
      begin
        passes := vortex_access.evaluate_query_condition_internal(
          filter_condition, filter_types, scan_record.filter_values,
          parameter_types, parameter_values, false
        );
      exception when invalid_parameter_value then
        passes := true;
        needs_refusal_check := true;
      end;
    end if;

    if passes then
      projection := vortex_record.read_record(record_type_id_value, scan_record.record_id);
      if projection ->> 'outcome' = 'allowed' then
        readable_values := projection -> 'values';
        if not exists (
          select 1 from pg_catalog.unnest(declared_sort_ids || filter_ids) as referenced(id)
          where not (readable_values ? referenced.id)
        ) then
          if needs_refusal_check then
            return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'filter_invalid');
          end if;
          -- A search term matches only through a searchable field this row exposes
          -- to the reader; a field the reader cannot see never decides a match, so
          -- a hidden value can neither satisfy a search nor be inferred from one.
          -- Only a text or number value, or the text members of a list value, is
          -- searched; a structured value's JSON keys and identifiers never match.
          if board_member_mode then
            if board_column_kind = 'option' then
              board_member_matches := (readable_values ? board_choice_field_id)
                and pg_catalog.jsonb_typeof(readable_values -> board_choice_field_id) = 'string'
                and (readable_values ->> board_choice_field_id) collate "C"
                  = board_column_value collate "C";
            else
              board_member_matches := not (
                (readable_values ? board_choice_field_id)
                and pg_catalog.jsonb_typeof(readable_values -> board_choice_field_id) = 'string'
                and (readable_values ->> board_choice_field_id) collate "C"
                  = any (board_option_values)
              );
            end if;
            if not board_member_matches then
              last_examined_sort_key := scan_record.sort_key;
              last_examined_record_id := scan_record.record_id;
              continue;
            end if;
          end if;
          if group_member_mode then
            group_member_matches := not exists (
              select 1 from pg_catalog.unnest(group_by_ids) as grouped(id)
              where not (readable_values ? grouped.id)
            );
            if group_member_matches then
              select pg_catalog.jsonb_object_agg(grouped.id, readable_values -> grouped.id)
              into group_candidate_values
              from pg_catalog.unnest(group_by_ids) as grouped(id);
              group_member_matches := group_candidate_values = group_selector_values;
            end if;
            if not group_member_matches then
              last_examined_sort_key := scan_record.sort_key;
              last_examined_record_id := scan_record.record_id;
              continue;
            end if;
          end if;
          if user_search is not null then
            search_matches := false;
            foreach field_key in array search_field_ids loop
              if readable_values ? field_key and (
                (pg_catalog.jsonb_typeof(readable_values -> field_key) in ('string', 'number')
                  and pg_catalog.strpos(
                    pg_catalog.lower(readable_values ->> field_key), user_search_folded
                  ) > 0)
                or (pg_catalog.jsonb_typeof(readable_values -> field_key) = 'array'
                  and exists (
                    select 1
                    from pg_catalog.jsonb_array_elements(readable_values -> field_key) as member(value)
                    where pg_catalog.jsonb_typeof(member.value) = 'string'
                      and pg_catalog.strpos(
                        pg_catalog.lower(member.value #>> '{}'), user_search_folded
                      ) > 0
                  ))
              ) then
                search_matches := true;
                exit;
              end if;
            end loop;
            if not search_matches then
              last_examined_sort_key := scan_record.sort_key;
              last_examined_record_id := scan_record.record_id;
              continue;
            end if;
          end if;
          if row_count = p_page_size then
            more_rows := true;
            exit;
          end if;
          -- Every returned row carries the record's concurrency number from
          -- read_record and its per-row capabilities, each action decided exactly
          -- as its own writer decides it and only for a row read_record admits.
          -- The capabilities are computed only for a returned row; a row whose
          -- capabilities cannot be computed is withheld rather than exposed
          -- without them.
          row_capabilities := vortex_record.read_record_capabilities(
            record_type_id_value, scan_record.record_id
          );
          if row_capabilities is not null then
            rows_value := rows_value || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
              'recordId', scan_record.record_id,
              'revision', projection -> 'concurrencyNumber',
              'capabilities', row_capabilities,
              'values', coalesce((
                select pg_catalog.jsonb_object_agg(requested.id, readable_values -> requested.id)
                from pg_catalog.unnest(requested_ids) as requested(id)
                where readable_values ? requested.id
              ), '{}'::jsonb)
            ));
            row_count := row_count + 1;
            if pg_catalog.cardinality(system_field_keys) > 0 then
              rows_value := pg_catalog.jsonb_set(
                rows_value, array[(row_count - 1)::text, 'systemValues'], scan_record.system_values
              );
            end if;
            last_returned_sort_key := scan_record.sort_key;
            last_returned_record_id := scan_record.record_id;
          end if;
        end if;
      end if;
    end if;

    last_examined_sort_key := scan_record.sort_key;
    last_examined_record_id := scan_record.record_id;
  end loop;

  if more_rows then
    next_value := pg_catalog.jsonb_build_object(
      'sortKey', pg_catalog.to_jsonb(last_returned_sort_key),
      'recordId', last_returned_record_id
    );
  elsif budget_exhausted then
    next_value := pg_catalog.jsonb_build_object(
      'sortKey', pg_catalog.to_jsonb(last_examined_sort_key),
      'recordId', last_examined_record_id
    );
  end if;

  if group_member_mode then
    return pg_catalog.jsonb_build_object(
      'outcome', 'completed',
      'moduleReleaseRevision', resolved -> 'moduleReleaseRevision',
      'moduleReleaseVersion', resolved -> 'moduleReleaseVersion',
      'groupByFieldIds', pg_catalog.to_jsonb(group_by_ids),
      'groupValues', group_selector_values,
      'rows', rows_value,
      'next', next_value
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'outcome', 'completed',
    'moduleReleaseRevision', resolved -> 'moduleReleaseRevision',
    'moduleReleaseVersion', resolved -> 'moduleReleaseVersion',
    'rows', rows_value,
    'next', next_value
  );
end
$function$;


ALTER FUNCTION vortex_record.run_module_query(p_module_root_id uuid, p_query_id uuid, p_expected_release_revision bigint, p_input_values jsonb, p_requested_field_ids jsonb, p_page_size integer, p_after jsonb, p_requested_system_field_keys jsonb, p_user_inputs jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION run_module_query(p_module_root_id uuid, p_query_id uuid, p_expected_release_revision bigint, p_input_values jsonb, p_requested_field_ids jsonb, p_page_size integer, p_after jsonb, p_requested_system_field_keys jsonb, p_user_inputs jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.run_module_query(p_module_root_id uuid, p_query_id uuid, p_expected_release_revision bigint, p_input_values jsonb, p_requested_field_ids jsonb, p_page_size integer, p_after jsonb, p_requested_system_field_keys jsonb, p_user_inputs jsonb) IS 'One bounded keyset page of rows readable through read_record for one installed Module query, or one exact current human-owned preview query over isolated preview storage, each carrying the record''s concurrency number and the per-row capabilities from read_record_capabilities, each action decided exactly as its own writer decides it, with only the declared Record system values, or one refusal before any row is exposed; accepts a bound list component''s declared sortable, filterable and searchable field sets together with the viewer''s chosen sort, typed filter and search term, refuses a sort or filter outside the declared sets, keeps a user sort only over a field the record type declares sortable and the reader is guaranteed to see, ANDs the user filter with the published filter so it can only narrow, and matches a search only through searchable fields the returned row exposes to the reader; requires every filtered field to be declared filterable; pushes a filter or a sort into the candidate scan only for fields the reader is guaranteed to see for the whole record type, evaluates a filter on a possibly-withheld field per row, and keeps the keyset cursor over readable sort values and a record identity so no cursor carries a hidden field value and the scan order and budget never depend on one; narrows an installed scan with one predicate that OR-s every eligible alternative''s exact owner, owner-group and direct-share route test with its saved condition compiled over the record''s own catalogue columns where that condition can be expressed as a superset of the per-row decision, leaves the installed scan unrestricted where a route or condition has no exact stored form, and still decides every returned row through read_record; validates every preview stage against the current human, candidate revision and exact release and storage pins, uses only active preview catalogue mappings and preview field bounds, and never falls through to installed resolution; works out read-time fields, such as a deadline-passed calculation, inside an installed query at one statement timestamp in the organisation time zone, so no installed query is refused for freshness; admits board members only through a separately validated board selector over the sole filterable choice grouping key, classifies those columns from current readable values, and admits generic grouped members only when every installed grouping value is present in the current readable projection and JSONB-equal to the closed typed selector; missing or withheld values belong to no generic group while JSON null is a value, and generic group membership never uses hidden stored values or affects scan order or budget; orders board and generic group pages by record identity, returns generic group identity even for empty pages, and binds each member operation, selector and projection in its own uncached continuation; refuses preview member, grouped, aggregate and system projection modes.';


--
-- Name: run_module_query_summary(uuid, uuid, bigint, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.run_module_query_summary(
  p_module_root_id uuid,
  p_query_id uuid,
  p_expected_release_revision bigint,
  p_input_values jsonb,
  p_user_inputs jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  summary_candidate_limit constant integer := 100000;
  uuid_pattern constant text :=
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  prepared_plan jsonb;
  resolved jsonb;
  query_item jsonb;
  record_type_item jsonb;
  record_type_id_value uuid;
  context_organization_id uuid;
  context_application_root_id uuid;
  v_storage_contract_id uuid;
  physical_table_token text;
  storage_scope text;
  access_sql text;
  access_parameters jsonb := '[]'::jsonb;
  access_owner_account_id uuid;
  access_owner_group_ids uuid[] := array[]::uuid[];
  access_shared_record_ids uuid[] := array[]::uuid[];
  readable_field_ids text[] := array[]::text[];
  filter_condition jsonb;
  filter_types jsonb := '{}'::jsonb;
  parameter_types jsonb := '{}'::jsonb;
  parameter_values jsonb := '{}'::jsonb;
  filter_ids text[] := array[]::text[];
  filter_predicate text := 'true';
  filter_parameters jsonb := '[]'::jsonb;
  filter_expression_pairs text[] := array[]::text[];
  filter_values_sql text := '''{}''::jsonb';
  group_ids text[] := array[]::text[];
  aggregate_items jsonb := '[]'::jsonb;
  aggregate_item jsonb;
  aggregate_aliases text[] := array[]::text[];
  summary_field_ids text[] := array[]::text[];
  fast_field_ids text[] := array[]::text[];
  fields_by_id jsonb := '{}'::jsonb;
  field_item jsonb;
  field_key text;
  field_type text;
  mapping_row vortex_record.field_storage_mappings%rowtype;
  fast_path boolean := false;
  fast_path_fields_valid boolean := true;
  scan_sql text;
  candidate_sql text;
  selected_sql text;
  summary_sql text;
  expression_pairs text[] := array[]::text[];
  group_value_pairs text[] := array[]::text[];
  group_by_terms text[] := array[]::text[];
  group_presence_terms text[] := array[]::text[];
  group_values_sql text;
  group_by_sql text;
  group_presence_sql text;
  aggregate_object_sql text := '';
  aggregate_result_sql text;
  aggregate_count_sql text;
  aggregate_sum_sql text;
  aggregate_average_sql text;
  aggregate_present_sql text;
  aggregate_value_sql text;
  aggregate_currency_sql text;
  aggregate_amount_sql text;
  aggregate_mixed_currency_sql text;
  aggregate_operation text;
  aggregate_field_id text;
  aggregate_field_type text;
  aggregate_original_field_type text;
  aggregate_alias text;
  average_places integer;
  value_expression text;
  groups_json_sql text := '''[]''::jsonb';
  board_summary_mode boolean := false;
  board_summary jsonb;
  board_choice_field_id text;
  board_options jsonb;
  board_option jsonb;
  board_option_values text[] := array[]::text[];
  board_bucket_sql text;
  board_totals_sql text;
  board_empty_aggregates_sql text;
  result_value jsonb;
  preview_address text;
begin
  preview_address := nullif(
    pg_catalog.current_setting('vortex_record.preview_installation_id', true), ''
  );
  if preview_address is not null then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'query_unavailable');
  end if;
  if p_module_root_id is null or p_query_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_query_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_input_values is null or pg_catalog.jsonb_typeof(p_input_values) <> 'object'
    or (p_expected_release_revision is not null
      and p_expected_release_revision not between 1 and 9007199254740991) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  if p_user_inputs is null then
    p_user_inputs := '{}'::jsonb;
  end if;
  board_summary_mode := p_user_inputs ? 'boardSummary';
  if pg_catalog.jsonb_typeof(p_user_inputs) <> 'object'
    or exists (
      select 1 from pg_catalog.jsonb_object_keys(p_user_inputs) as supplied(key)
      where supplied.key not in ('filter', 'filterableFieldIds', 'boardSummary')
    ) then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'request_invalid');
  end if;
  if board_summary_mode then
    board_summary := p_user_inputs -> 'boardSummary';
    if pg_catalog.jsonb_typeof(board_summary) is distinct from 'object' then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    if board_summary - array['choiceFieldId']::text[] <> '{}'::jsonb
      or not (board_summary ? 'choiceFieldId') then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    if pg_catalog.jsonb_typeof(board_summary -> 'choiceFieldId') is distinct from 'string'
      or pg_catalog.lower(board_summary ->> 'choiceFieldId') !~ uuid_pattern then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    board_choice_field_id := pg_catalog.lower(board_summary ->> 'choiceFieldId');
  end if;

  prepared_plan := vortex_record.prepare_module_query_internal(
    p_module_root_id, p_query_id, p_expected_release_revision, p_input_values,
    p_user_inputs -> 'filter', coalesce(p_user_inputs -> 'filterableFieldIds', '[]'::jsonb),
    'resolution', null
  );
  if prepared_plan ->> 'outcome' is distinct from 'prepared' then
    return prepared_plan;
  end if;
  resolved := prepared_plan -> 'resolved';
  query_item := prepared_plan -> 'query';
  record_type_item := prepared_plan -> 'recordType';
  record_type_id_value := (prepared_plan ->> 'recordTypeId')::uuid;
  context_organization_id := (prepared_plan #>> '{scope,organizationId}')::uuid;
  context_application_root_id := (prepared_plan #>> '{scope,applicationRootId}')::uuid;

  if coalesce((query_item ->> 'relationshipHops')::integer, 0) <> 0 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'relationship_invalid');
  end if;
  if pg_catalog.jsonb_typeof(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) <> 'array'
    or pg_catalog.jsonb_array_length(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) > 10
    or pg_catalog.jsonb_typeof(coalesce(query_item -> 'aggregates', '[]'::jsonb)) <> 'array'
    or pg_catalog.jsonb_array_length(coalesce(query_item -> 'aggregates', '[]'::jsonb)) > 20 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
  end if;
  if board_summary_mode
    and pg_catalog.jsonb_array_length(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) <> 1 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
  end if;

  for field_item in
    select item.value from pg_catalog.jsonb_array_elements(coalesce(record_type_item -> 'fields', '[]'::jsonb)) as item(value)
  loop
    fields_by_id := fields_by_id || pg_catalog.jsonb_build_object(
      pg_catalog.lower(field_item ->> 'fieldId'), field_item
    );
  end loop;

  for field_item in
    select item.value from pg_catalog.jsonb_array_elements(coalesce(query_item -> 'groupByFieldIds', '[]'::jsonb)) as item(value)
  loop
    if pg_catalog.jsonb_typeof(field_item) <> 'string'
      or pg_catalog.lower(field_item #>> '{}') !~ uuid_pattern then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    field_key := pg_catalog.lower(field_item #>> '{}');
    field_type := coalesce(fields_by_id -> field_key ->> 'type', '');
    if field_key = any (group_ids)
      or field_type not in (
        'text', 'whole_number', 'decimal_number', 'yes_no', 'date', 'date_time',
        'choice', 'reference_number', 'email_address', 'phone_number', 'web_address',
        'link', 'link_to_one_of_several', 'link_to_person'
      ) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    group_ids := pg_catalog.array_append(group_ids, field_key);
    if not (field_key = any (summary_field_ids)) then
      summary_field_ids := pg_catalog.array_append(summary_field_ids, field_key);
      fast_field_ids := pg_catalog.array_append(fast_field_ids, field_key);
    end if;
  end loop;

  if board_summary_mode then
    if pg_catalog.cardinality(group_ids) <> 1
      or group_ids[1] is distinct from board_choice_field_id
      or not (fields_by_id ? board_choice_field_id)
      or fields_by_id -> board_choice_field_id ->> 'type' is distinct from 'choice'
      or coalesce((fields_by_id -> board_choice_field_id ->> 'filterable')::boolean, false) is not true
      or pg_catalog.jsonb_typeof(coalesce(query_item -> 'selectedFieldIds', '[]'::jsonb)) is distinct from 'array'
      or not exists (
        select 1
        from pg_catalog.jsonb_array_elements(coalesce(query_item -> 'selectedFieldIds', '[]'::jsonb)) as selected(value)
        where pg_catalog.jsonb_typeof(selected.value) = 'string'
          and pg_catalog.lower(selected.value #>> '{}') = board_choice_field_id
      ) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    board_options := fields_by_id #> array[board_choice_field_id, 'settings', 'options'];
    if pg_catalog.jsonb_typeof(board_options) is distinct from 'array' then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    if pg_catalog.jsonb_array_length(board_options) not between 1 and 12 then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    for board_option in
      select item.value from pg_catalog.jsonb_array_elements(board_options) as item(value)
    loop
      if pg_catalog.jsonb_typeof(board_option) is distinct from 'object' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      if board_option - array['value', 'label', 'requiredPermissionId']::text[] <> '{}'::jsonb
        or not (board_option ? 'value') or not (board_option ? 'label')
        or pg_catalog.jsonb_typeof(board_option -> 'value') is distinct from 'string'
        or coalesce(pg_catalog.length(board_option ->> 'value'), 0) not between 1 and 120
        or pg_catalog.jsonb_typeof(board_option -> 'label') is distinct from 'string'
        or coalesce(pg_catalog.length(pg_catalog.btrim(board_option ->> 'label')), 0) not between 1 and 60
        or (board_option ? 'requiredPermissionId' and (
          pg_catalog.jsonb_typeof(board_option -> 'requiredPermissionId') is distinct from 'string'
          or pg_catalog.lower(board_option ->> 'requiredPermissionId') !~ uuid_pattern
          or pg_catalog.lower(board_option ->> 'requiredPermissionId') = '00000000-0000-0000-0000-000000000000'
        ))
        or (board_option ->> 'value') collate "C" = any (board_option_values) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      board_option_values := pg_catalog.array_append(board_option_values, board_option ->> 'value');
    end loop;
  end if;

  aggregate_items := coalesce(query_item -> 'aggregates', '[]'::jsonb);
  for aggregate_item in
    select item.value from pg_catalog.jsonb_array_elements(aggregate_items) as item(value)
  loop
    aggregate_operation := aggregate_item ->> 'operation';
    aggregate_alias := aggregate_item ->> 'alias';
    aggregate_field_id := nullif(pg_catalog.lower(aggregate_item ->> 'fieldId'), '');
    if aggregate_operation not in ('count', 'sum', 'minimum', 'maximum', 'average')
      or aggregate_alias is null
      or aggregate_alias !~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
      or pg_catalog.length(aggregate_alias) > 40
      or aggregate_alias = any (aggregate_aliases)
      or (aggregate_item ? 'fieldId' and aggregate_field_id is null)
      or (aggregate_operation <> 'count' and aggregate_field_id is null)
      or (aggregate_operation = 'count' and aggregate_field_id is not null) then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
    end if;
    aggregate_aliases := pg_catalog.array_append(aggregate_aliases, aggregate_alias);
    if aggregate_field_id is not null then
      if aggregate_field_id !~ uuid_pattern or not (fields_by_id ? aggregate_field_id) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      aggregate_original_field_type := coalesce(fields_by_id -> aggregate_field_id ->> 'type', '');
      aggregate_field_type := aggregate_original_field_type;
      if aggregate_original_field_type = 'calculation' then
        if (fields_by_id -> aggregate_field_id) #>> '{settings,expression,kind}' is distinct from 'numeric'
          or (fields_by_id -> aggregate_field_id) #>> '{settings,evaluation}' is distinct from 'stored'
          or coalesce((fields_by_id -> aggregate_field_id) #>> '{settings,resultType}', '')
            not in ('whole_number', 'decimal_number') then
          return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
        end if;
        aggregate_field_type := (fields_by_id -> aggregate_field_id) #>> '{settings,resultType}';
      elsif aggregate_original_field_type = 'total' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      if (aggregate_operation in ('sum', 'average')
          and aggregate_field_type not in ('whole_number', 'decimal_number', 'money'))
        or (aggregate_operation in ('minimum', 'maximum')
          and aggregate_field_type not in (
            'text', 'whole_number', 'decimal_number', 'yes_no', 'money', 'date', 'date_time'
          )) then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      if not (aggregate_field_id = any (summary_field_ids)) then
        summary_field_ids := pg_catalog.array_append(summary_field_ids, aggregate_field_id);
        fast_field_ids := pg_catalog.array_append(fast_field_ids, aggregate_field_id);
      end if;
    end if;
  end loop;

  prepared_plan := vortex_record.prepare_module_query_internal(
    p_module_root_id, p_query_id, p_expected_release_revision, p_input_values,
    p_user_inputs -> 'filter', coalesce(p_user_inputs -> 'filterableFieldIds', '[]'::jsonb),
    'storage', prepared_plan
  );
  if prepared_plan ->> 'outcome' is distinct from 'prepared' then
    return prepared_plan;
  end if;
  v_storage_contract_id := (prepared_plan #>> '{storage,storageContractId}')::uuid;
  physical_table_token := prepared_plan #>> '{storage,physicalTableToken}';
  storage_scope := prepared_plan #>> '{storage,storageScope}';
  access_sql := coalesce(prepared_plan #>> '{access,predicate}', 'true');
  access_parameters := coalesce(prepared_plan #> '{access,parameters}', '[]'::jsonb);
  access_owner_account_id := nullif(prepared_plan #>> '{access,ownerAccountId}', '')::uuid;
  select coalesce(pg_catalog.array_agg(item.value::uuid), array[]::uuid[])
  into access_owner_group_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan #> '{access,ownerGroupIds}') as item(value);
  select coalesce(pg_catalog.array_agg(item.value::uuid), array[]::uuid[])
  into access_shared_record_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan #> '{access,sharedRecordIds}') as item(value);
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[])
  into readable_field_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan -> 'readableFieldIds') as item(value);

  prepared_plan := vortex_record.prepare_module_query_internal(
    p_module_root_id, p_query_id, p_expected_release_revision, p_input_values,
    p_user_inputs -> 'filter', coalesce(p_user_inputs -> 'filterableFieldIds', '[]'::jsonb),
    'complete', prepared_plan
  );
  if prepared_plan ->> 'outcome' is distinct from 'prepared' then
    return prepared_plan;
  end if;
  filter_condition := prepared_plan #> '{filter,residualCondition}';
  if filter_condition = 'null'::jsonb then
    filter_condition := null;
  end if;
  filter_types := coalesce(prepared_plan #> '{filter,residualFieldTypes}', '{}'::jsonb);
  parameter_types := coalesce(prepared_plan #> '{filter,residualInputTypes}', '{}'::jsonb);
  parameter_values := coalesce(prepared_plan #> '{filter,residualInputs}', '{}'::jsonb);
  filter_predicate := coalesce(prepared_plan #>> '{filter,pushedPredicate}', 'true');
  filter_parameters := coalesce(prepared_plan #> '{filter,pushedParameters}', '[]'::jsonb);
  select coalesce(pg_catalog.array_agg(item.value order by item.position), array[]::text[])
  into filter_expression_pairs
  from pg_catalog.jsonb_array_elements_text(prepared_plan #> '{filter,expressions}')
    with ordinality as item(value, position);
  if pg_catalog.cardinality(filter_expression_pairs) > 0 then
    select pg_catalog.string_agg(
      'pg_catalog.jsonb_build_object(' || chunk.pairs_text || ')', ' || '
      order by chunk.chunk_index
    )
    into filter_values_sql
    from (
      select (pair.position - 1) / 50 as chunk_index,
        pg_catalog.string_agg(pair.value, ', ' order by pair.position) as pairs_text
      from pg_catalog.unnest(filter_expression_pairs)
        with ordinality as pair(value, position)
      group by (pair.position - 1) / 50
    ) as chunk;
  end if;
  select coalesce(pg_catalog.array_agg(item.value), array[]::text[])
  into filter_ids
  from pg_catalog.jsonb_array_elements_text(prepared_plan -> 'filterFieldIds') as item(value);

  -- The plan is exact only when every candidate is readable and every field
  -- used by grouping, aggregates or filtering is readable on every candidate.
  -- Derived filter and aggregate fields can lose their projection on an
  -- individual record when an input is withheld, so both require read_record.
  fast_path := pg_catalog.cardinality(readable_field_ids) > 0
    and not exists (
      select 1 from pg_catalog.unnest(filter_ids) as required(id)
      where fields_by_id -> required.id ->> 'type' in ('calculation', 'total')
    )
    and not exists (
      select 1
      from pg_catalog.jsonb_array_elements(aggregate_items) as item(value)
      where item.value ? 'fieldId'
        and fields_by_id -> pg_catalog.lower(item.value ->> 'fieldId') ->> 'type'
          in ('calculation', 'total')
    )
    and not exists (
      select 1 from pg_catalog.unnest(group_ids || filter_ids) as required(id)
      where required.id <> all (readable_field_ids)
    )
    and not exists (
      select 1
      from pg_catalog.jsonb_array_elements(aggregate_items) as item(value)
      where item.value ? 'fieldId'
        and pg_catalog.lower(item.value ->> 'fieldId') <> all (readable_field_ids)
    );

  if fast_path then
    foreach field_key in array fast_field_ids loop
      select mapping.* into mapping_row
      from vortex_record.field_storage_mappings as mapping
      where mapping.storage_contract_id = v_storage_contract_id
        and mapping.field_id = field_key::uuid;
      if not found or mapping_row.state <> 'active' then
        fast_path_fields_valid := false;
        exit;
      end if;
      field_type := fields_by_id -> field_key ->> 'type';
      fast_path_fields_valid := fast_path_fields_valid and case field_type
        when 'whole_number' then mapping_row.database_value_type = 'integer'
        when 'decimal_number' then mapping_row.database_value_type = 'decimal'
        when 'yes_no' then mapping_row.database_value_type = 'boolean'
        when 'date' then mapping_row.database_value_type = 'date'
        when 'date_time' then mapping_row.database_value_type = 'timestamp_with_time_zone'
        when 'money' then mapping_row.database_value_type = 'json'
        when 'link' then mapping_row.database_value_type = 'json'
        when 'link_to_one_of_several' then mapping_row.database_value_type = 'json'
        when 'link_to_person' then mapping_row.database_value_type = 'json'
        when 'text' then mapping_row.database_value_type = 'text'
        when 'long_text' then mapping_row.database_value_type = 'text'
        when 'formatted_text' then mapping_row.database_value_type = 'json'
        when 'choice' then mapping_row.database_value_type = 'text'
        when 'reference_number' then mapping_row.database_value_type = 'text'
        when 'email_address' then mapping_row.database_value_type = 'text'
        when 'phone_number' then mapping_row.database_value_type = 'text'
        when 'web_address' then mapping_row.database_value_type = 'text'
        when 'several_choices' then mapping_row.database_value_type = 'json'
        when 'table' then mapping_row.database_value_type = 'json'
        when 'attachment' then mapping_row.database_value_type = 'json'
        else false end;
      if not fast_path_fields_valid then
        exit;
      end if;
      value_expression := case mapping_row.database_value_type
        when 'decimal' then pg_catalog.format('pg_catalog.to_jsonb(stored.%I::text)', mapping_row.physical_column_token)
        when 'timestamp_with_time_zone' then pg_catalog.format(
          'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(stored.%I))',
          mapping_row.physical_column_token
        )
        when 'date' then pg_catalog.format(
          'pg_catalog.to_jsonb(pg_catalog.to_char(stored.%I, ''YYYY-MM-DD''))',
          mapping_row.physical_column_token
        )
        else pg_catalog.format('pg_catalog.to_jsonb(stored.%I)', mapping_row.physical_column_token)
      end;
      expression_pairs := pg_catalog.array_append(
        expression_pairs, pg_catalog.format('%L, %s', field_key, value_expression)
      );
    end loop;
    fast_path := fast_path_fields_valid;
  end if;

  for aggregate_item in
    select item.value from pg_catalog.jsonb_array_elements(aggregate_items) as item(value)
  loop
    aggregate_operation := aggregate_item ->> 'operation';
    aggregate_alias := aggregate_item ->> 'alias';
    aggregate_field_id := nullif(pg_catalog.lower(aggregate_item ->> 'fieldId'), '');
    aggregate_count_sql := 'pg_catalog.count(*)';
    aggregate_present_sql := 'true';
    aggregate_value_sql := 'pg_catalog.to_jsonb(pg_catalog.count(*))';
    aggregate_mixed_currency_sql := 'false';
    if aggregate_field_id is not null then
      aggregate_original_field_type := coalesce(fields_by_id -> aggregate_field_id ->> 'type', '');
      aggregate_field_type := aggregate_original_field_type;
      if aggregate_original_field_type = 'calculation' then
        if (fields_by_id -> aggregate_field_id) #>> '{settings,expression,kind}' is distinct from 'numeric'
          or (fields_by_id -> aggregate_field_id) #>> '{settings,evaluation}' is distinct from 'stored'
          or coalesce((fields_by_id -> aggregate_field_id) #>> '{settings,resultType}', '')
            not in ('whole_number', 'decimal_number') then
          return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
        end if;
        aggregate_field_type := (fields_by_id -> aggregate_field_id) #>> '{settings,resultType}';
      elsif aggregate_original_field_type = 'total' then
        return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
      end if;
      aggregate_present_sql := pg_catalog.format(
        '(candidate.projected_values ? %L and candidate.projected_values -> %L <> ''null''::jsonb)',
        aggregate_field_id, aggregate_field_id
      );
      aggregate_count_sql := pg_catalog.format(
        'pg_catalog.count(*) filter (where %s)', aggregate_present_sql
      );
      value_expression := pg_catalog.format('(candidate.projected_values -> %L)', aggregate_field_id);
      aggregate_currency_sql := pg_catalog.format(
        '(candidate.projected_values -> %L ->> ''currency'')', aggregate_field_id
      );
      aggregate_amount_sql := pg_catalog.format(
        '((candidate.projected_values -> %L ->> ''amount'')::numeric)', aggregate_field_id
      );
      if aggregate_operation = 'count' then
        aggregate_value_sql := pg_catalog.format('pg_catalog.to_jsonb(%s)', aggregate_count_sql);
      elsif aggregate_field_type = 'money' then
        aggregate_mixed_currency_sql := pg_catalog.format(
          '(pg_catalog.count(distinct %s) filter (where %s)) > 1',
          aggregate_currency_sql, aggregate_present_sql
        );
        if aggregate_operation = 'minimum' then
          value_expression := pg_catalog.format(
            '(pg_catalog.array_agg(%s order by %s asc, %s collate "C" asc) filter (where %s))[1]',
            value_expression, aggregate_amount_sql, aggregate_currency_sql, aggregate_present_sql
          );
          aggregate_value_sql := value_expression;
        elsif aggregate_operation = 'maximum' then
          value_expression := pg_catalog.format(
            '(pg_catalog.array_agg(%s order by %s desc, %s collate "C" asc) filter (where %s))[1]',
            value_expression, aggregate_amount_sql, aggregate_currency_sql, aggregate_present_sql
          );
          aggregate_value_sql := value_expression;
        else
          average_places := coalesce((aggregate_item ->> 'decimalPlaces')::integer, 2);
          if average_places not between 0 and 12 then
            return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
          end if;
          if aggregate_operation = 'sum' then
            value_expression := pg_catalog.format(
              'pg_catalog.trim_scale(pg_catalog.sum(%s) filter (where %s))::text',
              aggregate_amount_sql, aggregate_present_sql
            );
          else
            aggregate_sum_sql := pg_catalog.format(
              'pg_catalog.sum(%s) filter (where %s)', aggregate_amount_sql, aggregate_present_sql
            );
            aggregate_average_sql := pg_catalog.format(
              'case when %3$s = 0 then null else
                 pg_catalog.sign(%1$s) * (
                   pg_catalog.div(
                     pg_catalog.abs(%1$s) * pg_catalog.power(10::numeric, %2$s),
                     (%3$s)::numeric
                   )
                   + case when 2 * pg_catalog.mod(
                       pg_catalog.abs(%1$s) * pg_catalog.power(10::numeric, %2$s),
                       (%3$s)::numeric
                     ) >= (%3$s)::numeric then 1 else 0 end
                 ) / pg_catalog.power(10::numeric, %2$s)
               end',
              aggregate_sum_sql, average_places, aggregate_count_sql
            );
            value_expression := pg_catalog.format(
              'pg_catalog.trim_scale((%s))::text', aggregate_average_sql
            );
          end if;
          aggregate_value_sql := pg_catalog.format(
            'pg_catalog.jsonb_build_object(''amount'', %s, ''currency'', (pg_catalog.array_agg(%s order by %s collate "C" asc) filter (where %s))[1])',
            value_expression, aggregate_currency_sql, aggregate_currency_sql, aggregate_present_sql
          );
        end if;
      elsif aggregate_operation in ('minimum', 'maximum') then
        if aggregate_field_type = 'text' then
          value_expression := pg_catalog.format(
            '(pg_catalog.array_agg(%s order by (candidate.projected_values ->> %L) collate "C" %s) filter (where %s))[1]',
            value_expression, aggregate_field_id,
            case aggregate_operation when 'minimum' then 'asc' else 'desc' end,
            aggregate_present_sql
          );
        elsif aggregate_field_type = 'yes_no' then
          value_expression := pg_catalog.format(
            '(pg_catalog.array_agg(%s order by (candidate.projected_values ->> %L)::boolean %s) filter (where %s))[1]',
            value_expression, aggregate_field_id,
            case aggregate_operation when 'minimum' then 'asc' else 'desc' end,
            aggregate_present_sql
          );
        elsif aggregate_field_type = 'whole_number' then
          value_expression := pg_catalog.format(
            'pg_catalog.to_jsonb(pg_catalog.%s((candidate.projected_values ->> %L)::bigint) filter (where %s))',
            case aggregate_operation when 'minimum' then 'min' else 'max' end,
            aggregate_field_id, aggregate_present_sql
          );
        elsif aggregate_field_type = 'decimal_number' then
          value_expression := pg_catalog.format(
            'pg_catalog.to_jsonb(pg_catalog.trim_scale(pg_catalog.%s((candidate.projected_values ->> %L)::numeric) filter (where %s))::text)',
            case aggregate_operation when 'minimum' then 'min' else 'max' end,
            aggregate_field_id, aggregate_present_sql
          );
        elsif aggregate_field_type = 'date' then
          value_expression := pg_catalog.format(
            'pg_catalog.to_jsonb(pg_catalog.%s(candidate.projected_values ->> %L) filter (where %s))',
            case aggregate_operation when 'minimum' then 'min' else 'max' end,
            aggregate_field_id, aggregate_present_sql
          );
        else
          value_expression := pg_catalog.format(
            'pg_catalog.to_jsonb(vortex_context.format_timestamp_utc(pg_catalog.%s((candidate.projected_values ->> %L)::timestamp with time zone) filter (where %s)))',
            case aggregate_operation when 'minimum' then 'min' else 'max' end,
            aggregate_field_id, aggregate_present_sql
          );
        end if;
        aggregate_value_sql := value_expression;
      else
        average_places := coalesce((aggregate_item ->> 'decimalPlaces')::integer, 2);
        if aggregate_operation = 'average' and average_places not between 0 and 12 then
          return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'descriptor_invalid');
        end if;
        if aggregate_operation = 'sum' then
          value_expression := pg_catalog.format(
            'pg_catalog.trim_scale(pg_catalog.sum((candidate.projected_values ->> %L)::numeric) filter (where %s))::text',
            aggregate_field_id, aggregate_present_sql
          );
        else
          aggregate_sum_sql := pg_catalog.format(
            'pg_catalog.sum((candidate.projected_values ->> %L)::numeric) filter (where %s)',
            aggregate_field_id, aggregate_present_sql
          );
          aggregate_average_sql := pg_catalog.format(
            'case when %3$s = 0 then null else
               pg_catalog.sign(%1$s) * (
                 pg_catalog.div(
                   pg_catalog.abs(%1$s) * pg_catalog.power(10::numeric, %2$s),
                   (%3$s)::numeric
                 )
                 + case when 2 * pg_catalog.mod(
                     pg_catalog.abs(%1$s) * pg_catalog.power(10::numeric, %2$s),
                     (%3$s)::numeric
                   ) >= (%3$s)::numeric then 1 else 0 end
               ) / pg_catalog.power(10::numeric, %2$s)
             end',
            aggregate_sum_sql, average_places, aggregate_count_sql
          );
          value_expression := pg_catalog.format(
            'pg_catalog.trim_scale((%s))::text', aggregate_average_sql
          );
        end if;
        aggregate_value_sql := pg_catalog.format('pg_catalog.to_jsonb(%s)', value_expression);
      end if;
      if aggregate_operation = 'count' then
        aggregate_result_sql := pg_catalog.format(
          'pg_catalog.jsonb_build_object(''outcome'', ''completed'', ''valueCount'', %s, ''value'', %s)',
          aggregate_count_sql, aggregate_value_sql
        );
      else
        aggregate_result_sql := pg_catalog.format(
          'case when %s then pg_catalog.jsonb_build_object(''outcome'', ''refused'', ''reasonCode'', ''mixed_currency'') else pg_catalog.jsonb_build_object(''outcome'', ''completed'', ''valueCount'', %s, ''value'', case when %s = 0 then ''null''::jsonb else %s end) end',
          aggregate_mixed_currency_sql, aggregate_count_sql, aggregate_count_sql, aggregate_value_sql
        );
      end if;
    else
      aggregate_result_sql := pg_catalog.format(
        'pg_catalog.jsonb_build_object(''outcome'', ''completed'', ''valueCount'', pg_catalog.count(*), ''value'', pg_catalog.to_jsonb(pg_catalog.count(*)))'
      );
    end if;
    if aggregate_object_sql <> '' then
      aggregate_object_sql := aggregate_object_sql || ', ';
    end if;
    aggregate_object_sql := aggregate_object_sql || pg_catalog.format('%L, %s', aggregate_alias, aggregate_result_sql);
  end loop;

  foreach field_key in array group_ids loop
    group_value_pairs := pg_catalog.array_append(
      group_value_pairs,
      pg_catalog.format('%L, candidate.projected_values -> %L', field_key, field_key)
    );
    group_by_terms := pg_catalog.array_append(
      group_by_terms, pg_catalog.format('(candidate.projected_values -> %L)', field_key)
    );
    group_presence_terms := pg_catalog.array_append(
      group_presence_terms, pg_catalog.format('(candidate.projected_values ? %L)', field_key)
    );
  end loop;
  group_values_sql := 'pg_catalog.jsonb_build_object(' || pg_catalog.array_to_string(group_value_pairs, ', ') || ')';
  group_by_sql := pg_catalog.array_to_string(group_by_terms, ', ');
  group_presence_sql := pg_catalog.array_to_string(group_presence_terms, ' and ');

  if fast_path then
    candidate_sql := pg_catalog.format(
      'select pg_catalog.jsonb_build_object(%s) as projected_values,
         %s as filter_values
       from record_data.%I as stored
       where stored.organisation_id = $1
         and stored.lifecycle_state = ''active''
         and %s
         and (%s)
         and (%s)
       limit $5',
      pg_catalog.array_to_string(expression_pairs, ', '),
      filter_values_sql,
      physical_table_token,
      case when storage_scope = 'application_contained'
        then 'stored.application_root_id = $2' else 'stored.application_root_id is null' end,
      access_sql,
      filter_predicate
    );
  else
    -- The access predicate supplies only the planner's candidate superset.
    -- Decide every scanned row through read_record before evaluating its Query
    -- filter, so a withheld field can never decide whether it counts.
    scan_sql := pg_catalog.format(
      'select stored.record_id
       from record_data.%I as stored
       where stored.organisation_id = $1
         and stored.lifecycle_state = ''active''
         and %s
         and (%s)
         and (%s)
       limit $5',
      physical_table_token,
      case when storage_scope = 'application_contained'
        then 'stored.application_root_id = $2' else 'stored.application_root_id is null' end,
      access_sql,
      filter_predicate
    );
    candidate_sql := scan_sql;
  end if;

  -- A compiled predicate may be a superset. The fast path still evaluates the
  -- complete condition over values the exact plan proves readable; the raw
  -- candidate count remains the ceiling, before any totals are returned.
  if fast_path then
    selected_sql := case when filter_condition is not null then
      'select candidate.projected_values from candidate where
         vortex_access.evaluate_query_condition_internal(
           $12, $13, candidate.filter_values, $14, $15, false
         )'
      else 'select candidate.projected_values from candidate' end;
  else
    -- Materialize each read once. The raw candidate count gates the reads, and
    -- every filter and aggregate uses only the fields this read returned.
    selected_sql := pg_catalog.format(
      'with readable as materialized (
         select vortex_record.read_record(%L::uuid, candidate.record_id) as result
         from candidate
         where (select value from candidate_count) <= %s
       )
       select (
         select coalesce(pg_catalog.jsonb_object_agg(field.id, readable.result -> ''values'' -> field.id), ''{}''::jsonb)
         from pg_catalog.unnest($17::text[]) as field(id)
         where readable.result -> ''values'' ? field.id
       ) as projected_values
       from readable
       where readable.result ->> ''outcome'' = ''allowed''
         and not exists (
           select 1 from pg_catalog.unnest($16::text[]) as required(id)
           where not (readable.result -> ''values'' ? required.id)
         )
         and ($12::jsonb is null or vortex_access.evaluate_query_condition_internal(
           $12, $13,
           (select coalesce(pg_catalog.jsonb_object_agg(referenced.id,
             case $13 ->> referenced.id
               when ''record_reference'' then pg_catalog.to_jsonb(
                 pg_catalog.lower(readable.result -> ''values'' -> referenced.id ->> ''recordId''))
               when ''organization_account_reference'' then pg_catalog.to_jsonb(
                 pg_catalog.lower(readable.result -> ''values'' -> referenced.id ->> ''organizationAccountId''))
               else readable.result -> ''values'' -> referenced.id
             end), ''{}''::jsonb)
            from pg_catalog.unnest($16::text[]) as referenced(id)),
           $14, $15, false
         ))',
      record_type_id_value::text, summary_candidate_limit
    );
  end if;

  -- Omitted grouping fields are withheld on that row, so they form no group;
  -- a readable JSON null remains a legitimate null group.
  if board_summary_mode then
    board_bucket_sql := pg_catalog.format(
      'coalesce((
         select installed_option.position::integer
         from pg_catalog.jsonb_array_elements(%L::jsonb)
           with ordinality as installed_option(value, position)
         where pg_catalog.jsonb_typeof(candidate.projected_values -> %L) = ''string''
           and (candidate.projected_values ->> %L) collate "C"
             = (installed_option.value ->> ''value'') collate "C"
       ), 0)',
      board_options::text, board_choice_field_id, board_choice_field_id
    );
    if aggregate_object_sql = '' then
      board_totals_sql := 'select ''{}''::jsonb as aggregate_values';
      board_empty_aggregates_sql := 'select ''{}''::jsonb as aggregates';
    else
      board_totals_sql := pg_catalog.format(
        'select pg_catalog.jsonb_build_object(%s) as aggregate_values
         from normalized as candidate',
        aggregate_object_sql
      );
      board_empty_aggregates_sql := pg_catalog.format(
        'select pg_catalog.jsonb_build_object(%s) as aggregates
         from normalized as candidate where false',
        aggregate_object_sql
      );
    end if;
    summary_sql := pg_catalog.format(
      'with candidate as materialized (%s),
       candidate_count as (select pg_catalog.count(*)::integer as value from candidate),
       selected as materialized (%s),
       normalized as materialized (
         select candidate.projected_values, %s as bucket_index
         from selected as candidate
       ),
       selected_count as (select pg_catalog.count(*)::integer as value from normalized),
       installed_options as (
         select choice_option.value, choice_option.position::integer as position
         from pg_catalog.jsonb_array_elements(%L::jsonb)
           with ordinality as choice_option(value, position)
       ),
       totals as (%s),
       grouped as (
         select candidate.bucket_index,
           pg_catalog.count(*)::integer as row_count,
           pg_catalog.jsonb_build_object(%s) as aggregates
         from normalized as candidate
         group by candidate.bucket_index
       ),
       empty_aggregates as (%s),
       columns_result as (
         select coalesce(pg_catalog.jsonb_agg(
           pg_catalog.jsonb_build_object(
             ''value'', installed.value ->> ''value'',
             ''label'', installed.value ->> ''label'',
             ''rowCount'', coalesce(grouped.row_count, 0),
             ''aggregates'', coalesce(grouped.aggregates, empty_aggregates.aggregates)
           ) order by installed.position
         ), ''[]''::jsonb) as value
         from installed_options as installed
         left join grouped on grouped.bucket_index = installed.position
         cross join empty_aggregates
       ),
       unassigned_result as (
         select pg_catalog.jsonb_build_object(
           ''rowCount'', coalesce(grouped.row_count, 0),
           ''aggregates'', coalesce(grouped.aggregates, empty_aggregates.aggregates)
         ) as value
         from (select 0::integer as bucket_index) as unassigned
         left join grouped on grouped.bucket_index = unassigned.bucket_index
         cross join empty_aggregates
       )
       select case when candidate_count.value > %s
         then pg_catalog.jsonb_build_object(''outcome'', ''refused'', ''reasonCode'', ''dataset_limit_exceeded'')
         else pg_catalog.jsonb_build_object(
           ''outcome'', ''completed'',
           ''moduleRootId'', %L,
           ''moduleReleaseVersion'', %L,
           ''queryId'', %L,
           ''choiceFieldId'', %L,
           ''totalRowCount'', selected_count.value,
           ''columns'', columns_result.value,
           ''unassigned'', unassigned_result.value,
           ''aggregates'', totals.aggregate_values
         ) end
       from candidate_count cross join selected_count cross join totals
         cross join columns_result cross join unassigned_result',
      candidate_sql,
      selected_sql,
      board_bucket_sql,
      board_options::text,
      board_totals_sql,
      aggregate_object_sql,
      board_empty_aggregates_sql,
      summary_candidate_limit,
      p_module_root_id::text,
      resolved ->> 'moduleReleaseVersion',
      p_query_id::text,
      board_choice_field_id
    );
  elsif pg_catalog.cardinality(group_ids) > 0 then
    groups_json_sql := pg_catalog.format(
      '(select coalesce(pg_catalog.jsonb_agg(
         pg_catalog.jsonb_build_object(
           ''groupKey'', grouped.group_values::text,
           ''groupValues'', grouped.group_values,
           ''rowCount'', grouped.row_count,
           ''aggregates'', grouped.aggregates
         ) order by grouped.group_values::text collate "C"
       ), ''[]''::jsonb) from grouped)'
    );
    summary_sql := pg_catalog.format(
      'with candidate as materialized (%s),
       candidate_count as (select pg_catalog.count(*)::integer as value from candidate),
       selected as materialized (%s),
       selected_count as (select pg_catalog.count(*)::integer as value from selected),
       totals as (select pg_catalog.jsonb_build_object(%s) as aggregate_values from selected as candidate),
       grouped as (
         select %s as group_values,
           pg_catalog.count(*)::integer as row_count,
           pg_catalog.jsonb_build_object(%s) as aggregates
         from selected as candidate
         where %s
         group by %s
       )
       select case when candidate_count.value > %s
         then pg_catalog.jsonb_build_object(''outcome'', ''refused'', ''reasonCode'', ''dataset_limit_exceeded'')
         else pg_catalog.jsonb_build_object(
           ''outcome'', ''completed'',
           ''moduleRootId'', %L,
           ''moduleReleaseVersion'', %L,
           ''queryId'', %L,
           ''groupByFieldIds'', %s::jsonb,
           ''totalRowCount'', selected_count.value,
           ''groups'', %s,
           ''aggregates'', totals.aggregate_values
         ) end
       from candidate_count cross join selected_count cross join totals',
      candidate_sql,
      selected_sql,
      aggregate_object_sql,
      group_values_sql,
      aggregate_object_sql,
      group_presence_sql,
      group_by_sql,
      summary_candidate_limit,
      p_module_root_id::text,
      resolved ->> 'moduleReleaseVersion',
      p_query_id::text,
      pg_catalog.to_jsonb(group_ids)::text,
      groups_json_sql
    );
  else
    summary_sql := pg_catalog.format(
      'with candidate as materialized (%s),
       candidate_count as (select pg_catalog.count(*)::integer as value from candidate),
       selected as materialized (%s),
       selected_count as (select pg_catalog.count(*)::integer as value from selected),
       totals as (select pg_catalog.jsonb_build_object(%s) as aggregate_values from selected as candidate)
       select case when candidate_count.value > %s
         then pg_catalog.jsonb_build_object(''outcome'', ''refused'', ''reasonCode'', ''dataset_limit_exceeded'')
         else pg_catalog.jsonb_build_object(
           ''outcome'', ''completed'',
           ''moduleRootId'', %L,
           ''moduleReleaseVersion'', %L,
           ''queryId'', %L,
           ''groupByFieldIds'', %s::jsonb,
           ''totalRowCount'', selected_count.value,
           ''groups'', ''[]''::jsonb,
           ''aggregates'', totals.aggregate_values
         ) end
       from candidate_count cross join selected_count cross join totals',
      candidate_sql,
      selected_sql,
      aggregate_object_sql,
      summary_candidate_limit,
      p_module_root_id::text,
      resolved ->> 'moduleReleaseVersion',
      p_query_id::text,
      pg_catalog.to_jsonb(group_ids)::text
    );
  end if;

  begin
    execute summary_sql into result_value
      using context_organization_id, context_application_root_id, null::text[], null::uuid,
        summary_candidate_limit + 1, access_owner_account_id, access_owner_group_ids,
        access_shared_record_ids, filter_parameters, access_parameters, null::jsonb,
        filter_condition, filter_types, parameter_types, parameter_values,
        filter_ids, summary_field_ids;
  exception when invalid_parameter_value then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'filter_invalid');
  end;
  return result_value;
end
$function$;


ALTER FUNCTION vortex_record.run_module_query_summary(p_module_root_id uuid, p_query_id uuid, p_expected_release_revision bigint, p_input_values jsonb, p_user_inputs jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION run_module_query_summary(p_module_root_id uuid, p_query_id uuid, p_expected_release_revision bigint, p_input_values jsonb, p_user_inputs jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.run_module_query_summary(p_module_root_id uuid, p_query_id uuid, p_expected_release_revision bigint, p_input_values jsonb, p_user_inputs jsonb) IS 'Runs one bounded database-backed installed Module query summary or protected board summary. It uses shared query preparation and the same organisation, Application, record visibility, published filter and declared user filter as list reads, counts rows only after vortex_record.read_record admits them unless the exact readable-field plan permits SQL aggregation, normalizes unreadable board choices to one unassigned bucket, refuses every explicit preview address before preparation, and refuses neutrally above 100000 candidate rows.';


--
-- Name: save_base_record(uuid, text, uuid, uuid, bigint, jsonb, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.save_base_record(
  p_command_id uuid,
  p_operation text,
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint,
  p_submitted_values jsonb,
  p_final_values jsonb,
  p_selected_group_id uuid,
  p_activity_id uuid,
  p_occurrence_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  mutation_kind text;
  mutations jsonb;
begin
  if p_command_id is null
    or p_command_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_operation not in ('create', 'update')
    or p_record_type_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or pg_catalog.jsonb_typeof(p_submitted_values) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_final_values) is distinct from 'object'
    or p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_occurrence_id is null
    or p_occurrence_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (p_operation = 'create' and (
      p_record_id is not null or p_expected_concurrency_number is not null
    ))
    or (p_operation = 'update' and (
      p_record_id is null
      or p_expected_concurrency_number not between 1 and 9007199254740990
      or p_selected_group_id is not null
    )) then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'command_invalid'
    );
  end if;

  -- The ordinary save is the record-change operation with one mutation: a
  -- create subject or one field set. The operation owns the receipt, the
  -- canonical lock order, the access decision, the Activity and the Event.
  mutation_kind := case when p_operation = 'create'
    then 'create_subject' else 'set_fields' end;
  mutations := pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
    'kind', mutation_kind,
    'values', p_final_values
  ));

  return vortex_record.apply_record_changes(
    p_command_id, p_operation, p_record_type_id, p_record_id,
    p_expected_concurrency_number, p_submitted_values, p_selected_group_id,
    mutations, p_activity_id, p_occurrence_id
  );
end
$function$;


ALTER FUNCTION vortex_record.save_base_record(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_selected_group_id uuid, p_activity_id uuid, p_occurrence_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION save_base_record(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_selected_group_id uuid, p_activity_id uuid, p_occurrence_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.save_base_record(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_selected_group_id uuid, p_activity_id uuid, p_occurrence_id uuid) IS 'The ordinary human Record save, expressed as one create_subject or set_fields record-change mutation through the one protected apply_record_changes operation.';


--
-- Name: save_base_record_with_relationship_totals(uuid, text, uuid, uuid, bigint, jsonb, jsonb, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.save_base_record_with_relationship_totals(
  p_command_id uuid,
  p_operation text,
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint,
  p_submitted_values jsonb,
  p_final_values jsonb,
  p_selected_group_id uuid,
  p_activity_id uuid,
  p_occurrence_id uuid,
  p_parent_mutations jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  result_value jsonb;
  parent_value jsonb;
  prepared_parent jsonb;
  preparation_value jsonb;
  reduced_final_values jsonb;
  context_value jsonb;
  catalogue jsonb;
  closure_value jsonb;
  root_type jsonb;
  root_snapshot jsonb;
  relationship_value jsonb;
  target_type jsonb;
  total_field jsonb;
  dependency_contract jsonb;
  dependency_field_id text;
  relationship_field_id text;
  old_relationship_target jsonb;
  proposed_relationship_target jsonb;
  contributes_to_total boolean := false;
  expected_parents jsonb;
  supplied_parents jsonb;
  preview_installation jsonb;
begin
  preview_installation :=
    vortex_record.read_current_preview_installation_internal();
  if preview_installation is not null then
    if preview_installation ->> 'outcome' = 'refused'
      or p_parent_mutations is distinct from '[]'::jsonb then
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'unsupported_relationship_total_save'
      );
    end if;
    return vortex_record.save_base_record(
      p_command_id, p_operation, p_record_type_id, p_record_id,
      p_expected_concurrency_number, p_submitted_values, p_final_values,
      p_selected_group_id, p_activity_id, p_occurrence_id
    );
  end if;
  if pg_catalog.jsonb_typeof(p_parent_mutations) <> 'array' then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'command_invalid');
  end if;
  context_value := vortex_access.validated_human_request_context();
  -- Receipt identity remains authoritative for replay and changed-input
  -- duplicate classification. A completed command must reach that owner even
  -- if a caller supplies no longer-current relationship mutations.
  if not vortex_record.command_receipt_exists_internal('record_save', p_command_id) then
    -- The writer repeats the protected preparation itself.  Closure identity,
    -- revisions and the complete generated-field set therefore never depend
    -- on caller-controlled transaction state or a replayable preparation token.
    preparation_value := vortex_record.prepare_relationship_total_save(
      p_command_id, p_operation, p_record_type_id, p_record_id,
      p_expected_concurrency_number, p_submitted_values, p_selected_group_id,
      p_activity_id
    );
    if preparation_value ->> 'outcome' in ('restart', 'conflict', 'refused', 'refused_recorded') then
      return preparation_value;
    end if;
    if preparation_value ->> 'outcome' = 'defer' and vortex_record.command_receipt_exists_internal('record_save', p_command_id) then
      preparation_value := null;
    elsif preparation_value ->> 'outcome' = 'defer' then
      catalogue := vortex_record.relationship_total_catalogue_internal();
      if coalesce((catalogue ->> 'hasInstalledRules')::boolean, false) then
        closure_value := vortex_record.discover_relationship_total_closure_internal(
          catalogue, p_operation, p_record_type_id, p_record_id, p_submitted_values
        );
        select item.value into root_type
        from pg_catalog.jsonb_array_elements(catalogue -> 'recordTypes') item(value)
        where pg_catalog.lower(item.value ->> 'recordTypeId') =
          pg_catalog.lower(p_record_type_id::text);
        select item.value into root_snapshot
        from pg_catalog.jsonb_array_elements(closure_value -> 'records') item(value)
        where item.value ->> 'recordKey' = 'root';
        if root_type is null or root_snapshot is null then
          return pg_catalog.jsonb_build_object(
            'outcome', 'refused', 'reasonCode', 'unsupported_relationship_total_save'
          );
        end if;
        for relationship_value, target_type in
          select item.value, target.value
          from pg_catalog.jsonb_array_elements(root_type -> 'relationships') item(value)
          join pg_catalog.jsonb_array_elements(catalogue -> 'recordTypes') target(value)
            on vortex_record.relationship_declares_target_internal(
              item.value, (target.value ->> 'recordTypeId')::uuid
            )
          where item.value ->> 'cardinality' in ('one_to_one', 'many_to_one')
          order by item.value ->> 'relationshipId', target.value ->> 'recordTypeId'
        loop
          relationship_field_id := pg_catalog.lower(relationship_value ->> 'fromFieldId');
          old_relationship_target := root_snapshot -> 'existingValues' -> relationship_field_id;
          proposed_relationship_target := old_relationship_target;
          if p_submitted_values ? relationship_field_id then
            proposed_relationship_target := p_submitted_values -> relationship_field_id;
          end if;
          if not (
            (pg_catalog.jsonb_typeof(old_relationship_target) = 'object' and
              pg_catalog.lower(old_relationship_target ->> 'recordTypeId') =
                pg_catalog.lower(target_type ->> 'recordTypeId'))
            or
            (pg_catalog.jsonb_typeof(proposed_relationship_target) = 'object' and
              pg_catalog.lower(proposed_relationship_target ->> 'recordTypeId') =
                pg_catalog.lower(target_type ->> 'recordTypeId'))
          ) then
            continue;
          end if;
          for total_field in
            select field.value
            from pg_catalog.jsonb_array_elements(target_type -> 'fields') field(value)
            where field.value ->> 'type' = 'total'
              and pg_catalog.lower(field.value #>> '{settings,relationshipId}') =
                pg_catalog.lower(relationship_value ->> 'relationshipId')
          loop
            if p_submitted_values ? relationship_field_id and
              p_submitted_values -> relationship_field_id is distinct from
                coalesce(root_snapshot -> 'existingValues' -> relationship_field_id, 'null'::jsonb) then
              contributes_to_total := true;
              exit;
            end if;
            dependency_contract := vortex_record.total_dependency_contract_internal(
              catalogue -> 'recordTypes',
              pg_catalog.jsonb_build_array(relationship_value),
              (target_type ->> 'recordTypeId')::uuid, total_field
            );
            for dependency_field_id in
              select item.value
              from pg_catalog.jsonb_array_elements_text(
                dependency_contract -> 'sourceFieldIds'
              ) item(value)
            loop
              if p_final_values ? dependency_field_id and
                p_final_values -> dependency_field_id is distinct from
                  coalesce(root_snapshot -> 'existingValues' -> dependency_field_id, 'null'::jsonb) then
                contributes_to_total := true;
                exit;
              end if;
            end loop;
            exit when contributes_to_total;
          end loop;
          exit when contributes_to_total;
        end loop;
        if contributes_to_total then
          return pg_catalog.jsonb_build_object(
            'outcome', 'refused', 'reasonCode', 'unsupported_relationship_total_save'
          );
        end if;
      end if;
    end if;
    if preparation_value ->> 'outcome' <> 'prepared' then
      if pg_catalog.jsonb_array_length(p_parent_mutations) = 0 then
        preparation_value := null;
      else
        return pg_catalog.jsonb_build_object(
          'outcome', 'refused', 'reasonCode', 'unsupported_relationship_total_save'
        );
      end if;
    else
      select coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'recordTypeId', item.value -> 'recordTypeId',
          'recordId', item.value -> 'recordId',
          'expectedConcurrencyNumber', item.value -> 'concurrencyNumber',
          'finalFieldIds', coalesce((
            select pg_catalog.jsonb_agg(
              pg_catalog.lower(field.value ->> 'fieldId')
              order by pg_catalog.lower(field.value ->> 'fieldId') collate "C"
            )
            from pg_catalog.jsonb_array_elements(item.value -> 'recordType' -> 'fields') field(value)
            where field.value ->> 'type' in ('total', 'calculation')
          ), '[]'::jsonb)
        ) order by item.value ->> 'recordTypeId', item.value ->> 'recordId'
      ), '[]'::jsonb) into expected_parents
      from pg_catalog.jsonb_array_elements(preparation_value -> 'records') item(value)
      where item.value ->> 'recordKey' <> 'root';
      select coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'recordTypeId', item.value -> 'recordTypeId',
          'recordId', item.value -> 'recordId',
          'expectedConcurrencyNumber', item.value -> 'expectedConcurrencyNumber',
          'finalFieldIds', coalesce((
            select pg_catalog.jsonb_agg(field_id order by field_id collate "C")
            from pg_catalog.jsonb_object_keys(item.value -> 'finalValues') field(field_id)
          ), '[]'::jsonb)
        ) order by item.value ->> 'recordTypeId', item.value ->> 'recordId'
      ), '[]'::jsonb) into supplied_parents
      from pg_catalog.jsonb_array_elements(p_parent_mutations) item(value)
      where pg_catalog.jsonb_typeof(item.value) = 'object'
        and item.value ?& array[
          'recordTypeId', 'recordId', 'expectedConcurrencyNumber', 'finalValues'
        ]
        and pg_catalog.jsonb_typeof(item.value -> 'finalValues') = 'object';
      if supplied_parents is distinct from expected_parents
        or pg_catalog.jsonb_array_length(supplied_parents) <>
          pg_catalog.jsonb_array_length(p_parent_mutations) then
        return pg_catalog.jsonb_build_object(
          'outcome', 'refused', 'reasonCode', 'unsupported_relationship_total_save'
        );
      end if;
    end if;
  end if;
  result_value := vortex_record.save_base_record(
    p_command_id, p_operation, p_record_type_id, p_record_id,
    p_expected_concurrency_number, p_submitted_values, p_final_values,
    p_selected_group_id, p_activity_id, p_occurrence_id
  );
  if result_value ->> 'outcome' <> 'saved' or coalesce((result_value ->> 'replayed')::boolean, false) then
    return result_value;
  end if;
  for parent_value in
    select item.value from pg_catalog.jsonb_array_elements(p_parent_mutations) item(value)
    order by (item.value ->> 'recordTypeId')::uuid, (item.value ->> 'recordId')::uuid
  loop
    if not (parent_value ?& array[
      'recordTypeId', 'recordId', 'expectedConcurrencyNumber', 'finalValues'
    ]) then
      raise exception using errcode = '22023', message = 'Relationship total parent mutation is incomplete';
    end if;
    select item.value into strict prepared_parent
    from pg_catalog.jsonb_array_elements(preparation_value -> 'records') item(value)
    where item.value ->> 'recordTypeId' = parent_value ->> 'recordTypeId'
      and item.value ->> 'recordId' = parent_value ->> 'recordId';
    select coalesce(pg_catalog.jsonb_object_agg(entry.key, entry.value), '{}'::jsonb)
      into reduced_final_values
    from pg_catalog.jsonb_each(parent_value -> 'finalValues') entry(key, value)
    where entry.value is distinct from coalesce(
      prepared_parent -> 'existingValues' -> entry.key, 'null'::jsonb
    );
    perform vortex_record.apply_relationship_total_parent_internal(
      (parent_value ->> 'recordTypeId')::uuid,
      (parent_value ->> 'recordId')::uuid,
      (parent_value ->> 'expectedConcurrencyNumber')::bigint,
      reduced_final_values
    );
  end loop;
  return result_value;
end
$function$;


ALTER FUNCTION vortex_record.save_base_record_with_relationship_totals(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_selected_group_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_parent_mutations jsonb) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION save_base_record_with_relationship_totals(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_selected_group_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_parent_mutations jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.save_base_record_with_relationship_totals(p_command_id uuid, p_operation text, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_selected_group_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_parent_mutations jsonb) IS 'Existing protected base save composed with revision-checked generated parent totals, Activity and standard Events in the same transaction.';


--
-- Name: save_initial_record_type_lifecycle_policy_for_provisioned_setup(uuid, bigint, uuid, uuid, bigint, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.save_initial_record_type_lifecycle_policy_for_provisioned_setup(p_binding_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_activity_id uuid, p_policy jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority record;
  limits_row vortex_record.organization_lifecycle_limits%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  existing vortex_record.record_type_lifecycle_policies%rowtype;
  next_policy_id uuid;
  full_policy jsonb;
  connection_readiness jsonb;
begin
  if p_binding_application_root_id is null
    or p_binding_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_binding_revision is null
    or p_expected_binding_revision not between 1 and 9007199254740991
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    -- The policy scope is either this exact Application or, for an
    -- organisation-shared record type, no Application at all.
    or (p_application_root_id is not null
      and p_application_root_id is distinct from p_binding_application_root_id)
    or p_expected_settings_revision is null
    or p_expected_settings_revision not between 1 and 9007199254740991
    or p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_policy is null
    or pg_catalog.jsonb_typeof(p_policy) <> 'object'
    -- Identity, scope and revision are assigned here, never accepted.
    or p_policy ?| array[
      'policyId', 'organizationId', 'storageContractId', 'applicationRootId',
      'policyRevision'
    ] then
    raise exception using errcode = '22023',
      message = 'Record-type lifecycle policy provisioned setup command is invalid';
  end if;

  -- The same registered `platform.organization.applications.manage` authority
  -- #566 requires, taken under the same organisation Access-version lock.
  select locked.* into strict authority
  from vortex_access.lock_record_lifecycle_policy_authority() as locked;

  -- Provisioned setup is always an Application-scoped request, and it must be
  -- scoped to exactly the Application whose binding authorises it.
  if authority.application_root_id is distinct from p_binding_application_root_id then
    raise exception using errcode = '42501',
      message = 'Record lifecycle policy administration is unavailable';
  end if;

  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = p_storage_contract_id
  for share;
  if not found
    or catalogue_row.state <> 'active'
    or (catalogue_row.storage_scope = 'organization_shared')
      <> (p_application_root_id is null) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy target is unavailable';
  end if;

  select limits.* into limits_row
  from vortex_record.organization_lifecycle_limits as limits
  where limits.organization_id = authority.organization_id
  for share;
  if not found then
    raise exception using errcode = '42501',
      message = 'Organisation lifecycle limits are unavailable';
  end if;
  if limits_row.settings_revision <> p_expected_settings_revision then
    raise exception using errcode = '40001',
      message = 'Organisation lifecycle limits are stale';
  end if;

  -- Initial setup only. An existing policy belongs to the #566 administration
  -- save, which requires an active installation.
  select stored.* into existing
  from vortex_record.record_type_lifecycle_policies as stored
  where stored.organization_id = authority.organization_id
    and stored.storage_contract_id = p_storage_contract_id
    and stored.application_root_id is not distinct from p_application_root_id
  for update;
  if found then
    raise exception using errcode = '40001',
      message = 'Record-type lifecycle policy is stale';
  end if;

  next_policy_id := pg_catalog.gen_random_uuid();
  full_policy := p_policy || pg_catalog.jsonb_build_object(
    'policyId', next_policy_id,
    'organizationId', authority.organization_id,
    'storageContractId', p_storage_contract_id,
    'applicationRootId', p_application_root_id,
    'policyRevision', 1
  );

  if not vortex_record.is_record_type_lifecycle_policy(full_policy) then
    raise exception using errcode = '22023',
      message = 'Record-type lifecycle policy provisioned setup command is invalid';
  end if;

  if full_policy ->> 'action' <> all (limits_row.allowed_actions) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy action is not permitted by organisation limits';
  end if;

  if pg_catalog.jsonb_typeof(full_policy -> 'maxAgeDays') = 'number' then
    if limits_row.max_retention_days is not null
      and (full_policy #>> '{maxAgeDays}')::numeric > limits_row.max_retention_days then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy maxAgeDays exceeds organisation limit';
    end if;
  elsif not limits_row.allow_unlimited_retention_days then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy unlimited age retention is not permitted';
  end if;

  if pg_catalog.jsonb_typeof(full_policy -> 'maxCount') = 'number' then
    if limits_row.max_record_count is not null
      and (full_policy #>> '{maxCount}')::numeric > limits_row.max_record_count then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy maxCount exceeds organisation limit';
    end if;
  elsif not limits_row.allow_unlimited_record_count then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy unlimited record count is not permitted';
  end if;

  if full_policy ->> 'action' = 'archive_workflow'
    and (full_policy ->> 'archiveDestination')
      <> all (limits_row.allowed_archive_destinations) then
    raise exception using errcode = '42501',
      message =
        'Record-type lifecycle policy archive destination is not permitted by organisation limits';
  end if;

  -- The exact provisioned binding revision, and (for an archive policy) the
  -- workflow of that exact immutable Application release.
  if not vortex_module.record_lifecycle_provisioned_setup_target_internal(
    authority.organization_id,
    p_binding_application_root_id,
    p_expected_binding_revision,
    p_storage_contract_id,
    case when full_policy ->> 'action' = 'archive_workflow'
      then (full_policy ->> 'archiveWorkflowId')::uuid end,
    case when full_policy ->> 'action' = 'archive_workflow'
      then (full_policy #>> '{expectedWorkflowRevision}')::bigint end
  ) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy target is unavailable';
  end if;

  if full_policy ->> 'action' = 'archive_workflow' then
    -- Runtime workflows and Connection grants require one permanent
    -- Application scope. An organisation-shared policy cannot invent one.
    if p_application_root_id is null then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy archive workflow is unavailable';
    end if;

    connection_readiness := vortex_connection.resolve_connection_instance_readiness(
      authority.organization_id,
      p_application_root_id,
      (full_policy ->> 'archiveConnectionInstanceId')::uuid,
      full_policy ->> 'archiveDestination',
      (full_policy #>> '{expectedConnectionRevision}')::bigint,
      full_policy ->> 'expectedDestinationFingerprint'
    );
    if connection_readiness ->> 'outcome' is distinct from 'ready'
      or pg_catalog.lower(connection_readiness ->> 'connectionInstanceId')
        is distinct from pg_catalog.lower(full_policy ->> 'archiveConnectionInstanceId')
      or connection_readiness ->> 'organizationId'
        is distinct from authority.organization_id::text
      or connection_readiness ->> 'applicationRootId'
        is distinct from p_application_root_id::text
      or connection_readiness ->> 'destinationKey'
        is distinct from full_policy ->> 'archiveDestination'
      or connection_readiness ->> 'destinationFingerprint'
        is distinct from full_policy ->> 'expectedDestinationFingerprint'
      or connection_readiness ->> 'revision'
        is distinct from full_policy #>> '{expectedConnectionRevision}'
      or connection_readiness ->> 'healthOutcome' is distinct from 'healthy'
      or connection_readiness ->> 'state' is distinct from 'active' then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy archive connection is unavailable';
    end if;
  end if;

  begin
    insert into vortex_record.record_type_lifecycle_policies (
      policy_id, organization_id, storage_contract_id, application_root_id,
      policy_revision, action, policy_body
    ) values (
      next_policy_id, authority.organization_id, p_storage_contract_id,
      p_application_root_id, 1, full_policy ->> 'action', full_policy
    );
  exception when unique_violation then
    raise exception using errcode = '40001',
      message = 'Record-type lifecycle policy is stale';
  end;

  perform vortex_record.append_lifecycle_policy_activity_internal(
    p_activity_id, next_policy_id
  );

  return full_policy;
end
$$;


ALTER FUNCTION vortex_record.save_initial_record_type_lifecycle_policy_for_provisioned_setup(p_binding_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_activity_id uuid, p_policy jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION save_initial_record_type_lifecycle_policy_for_provisioned_setup(p_binding_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_activity_id uuid, p_policy jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.save_initial_record_type_lifecycle_policy_for_provisioned_setup(p_binding_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_activity_id uuid, p_policy jsonb) IS 'Narrow provisioned-setup save of one record type''s first lifecycle policy at revision 1, under one exact provisioned binding revision, exact organisation limits revision and the current applications.manage human authority; an existing policy is refused, never updated.';


--
-- Name: save_organization_settings_record(uuid, uuid, uuid, bigint, jsonb, jsonb, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.save_organization_settings_record(
  p_command_id uuid,
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint,
  p_submitted_values jsonb,
  p_final_values jsonb,
  p_activity_id uuid,
  p_occurrence_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  meta jsonb;
  loaded jsonb;
  read_decision jsonb;
  read_bounds jsonb;
  record_type_value jsonb;
  field_item jsonb;
  field_id text;
  field_key text;
  field_type text;
  database_type text;
  field_value jsonb;
  candidate_values jsonb;
  core_values jsonb := '{}'::jsonb;
  extension_values jsonb := '{}'::jsonb;
  changed_field_ids uuid[] := array[]::uuid[];
  command_fingerprint_value text;
  receipt_claim jsonb;
  access_result jsonb;
  projection jsonb;
  event_result jsonb;
  correlation_id_value uuid;
  failure_sqlstate text;
  failure_message text;
begin
  if p_command_id is null
    or p_command_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_type_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_id is null
    or p_record_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_concurrency_number not between 1 and 9007199254740990
    or pg_catalog.jsonb_typeof(p_submitted_values) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_final_values) is distinct from 'object'
    or p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_occurrence_id is null
    or p_occurrence_id = '00000000-0000-0000-0000-000000000000'::uuid then
    if p_command_id is not null then
      perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    end if;
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'command_invalid');
  end if;

  meta := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'read');
  record_type_value := meta -> 'recordType';
  if record_type_value ->> 'key' is distinct from 'organization_settings'
    or record_type_value #>> '{systemProjection,protectedView}' is distinct from
      'organization_runtime_settings'
    or not coalesce((record_type_value -> 'standardActions') ? 'update', false)
    or not exists (
      select 1
      from vortex_definition.roots as root
      where root.root_id = (meta ->> 'moduleRootId')::uuid
        and root.kind = 'module'
        and root.key = 'vortex.organisation_administration'
    ) then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'record_unavailable');
  end if;

  correlation_id_value := (meta -> 'context' ->> 'correlationId')::uuid;
  if p_record_id is distinct from (meta -> 'context' ->> 'organizationId')::uuid then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'record_unavailable',
      'correlationId', correlation_id_value
    );
  end if;

  loaded := vortex_record.load_record_access_facts_internal(
    p_record_type_id, 'read', p_record_id, null
  );
  if loaded ->> 'outcome' <> 'loaded' then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'record_unavailable',
      'correlationId', correlation_id_value
    );
  end if;
  read_decision := vortex_access.evaluate_organization_record_access_internal(
    loaded -> 'declaration', p_record_id, loaded -> 'facts'
  );
  if read_decision ->> 'outcome' is distinct from 'allowed' then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'record_unavailable',
      'correlationId', correlation_id_value
    );
  end if;
  read_bounds := vortex_access.resolve_record_field_bounds_internal(read_decision);
  if exists (
    select 1
    from (
      select supplied.key
      from pg_catalog.jsonb_object_keys(p_submitted_values) as supplied(key)
      union
      select supplied.key
      from pg_catalog.jsonb_object_keys(p_final_values) as supplied(key)
    ) as supplied
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements_text(
        read_bounds -> 'readableFieldIds'
      ) as readable(field_id)
      where pg_catalog.lower(readable.field_id) = pg_catalog.lower(supplied.key)
    )
  ) then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'field_refused',
      'correlationId', correlation_id_value
    );
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_object_keys(p_final_values) as supplied(key)
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as field(value)
      where pg_catalog.lower(field.value ->> 'fieldId') = pg_catalog.lower(supplied.key)
    )
  ) or exists (
    select 1
    from pg_catalog.jsonb_object_keys(p_submitted_values) as supplied(key)
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as field(value)
      where pg_catalog.lower(field.value ->> 'fieldId') = pg_catalog.lower(supplied.key)
    )
  ) then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'command_invalid',
      'correlationId', correlation_id_value
    );
  end if;

  candidate_values := (loaded -> 'fieldValues') || p_final_values;
  for field_item in
    select item.value
    from pg_catalog.jsonb_array_elements(record_type_value -> 'fields') as item(value)
    order by item.value ->> 'fieldId'
  loop
    field_id := pg_catalog.lower(field_item ->> 'fieldId');
    field_key := field_item ->> 'key';
    field_type := field_item ->> 'type';
    database_type := meta #>> array['columns', field_id, 'databaseValueType'];
    if database_type is null then
      raise exception using errcode = '55000',
        message = 'Organization settings field storage is unavailable';
    end if;

    if (field_item ->> 'required')::boolean
      and (not (candidate_values ? field_id)
        or pg_catalog.jsonb_typeof(candidate_values -> field_id) = 'null') then
      perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'required_field_missing',
        'correlationId', correlation_id_value
      );
    end if;
    if not (p_final_values ? field_id) then
      continue;
    end if;

    field_value := p_final_values -> field_id;
    if field_key in ('organization_id', 'revision')
      or field_type in (
        'reference_number', 'table', 'link', 'link_to_one_of_several', 'total',
        'attachment', 'calculation'
      )
      or not vortex_record.canonical_record_value_matches(
        field_value, field_type, database_type
      ) then
      perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'field_refused',
        'correlationId', correlation_id_value
      );
    end if;

    if field_type = 'choice'
      and pg_catalog.jsonb_typeof(field_value) <> 'null'
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(field_item #> '{settings,options}') as option(value)
        where option.value ->> 'value' = field_value #>> '{}'
      ) then
      perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'field_refused',
        'correlationId', correlation_id_value
      );
    end if;
    if field_type = 'several_choices'
      and pg_catalog.jsonb_typeof(field_value) <> 'null'
      and exists (
        select 1
        from pg_catalog.jsonb_array_elements_text(field_value) as selected(value)
        where not exists (
          select 1
          from pg_catalog.jsonb_array_elements(field_item #> '{settings,options}') as option(value)
          where option.value ->> 'value' = selected.value
        )
      ) then
      perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'field_refused',
        'correlationId', correlation_id_value
      );
    end if;
    if field_type in ('text', 'long_text', 'choice', 'email_address', 'phone_number', 'web_address')
      and field_item #> '{settings,maxLength}' is not null
      and pg_catalog.jsonb_typeof(field_value) = 'string'
      and pg_catalog.char_length(field_value #>> '{}') >
        (field_item #>> '{settings,maxLength}')::integer then
      perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'field_refused',
        'correlationId', correlation_id_value
      );
    end if;

    if field_key in (
      'language', 'time_zone', 'currency', 'date_format', 'number_format',
      'default_application_root_id'
    ) then
      core_values := core_values || pg_catalog.jsonb_build_object(field_key, field_value);
    else
      extension_values := extension_values || pg_catalog.jsonb_build_object(field_key, field_value);
    end if;
  end loop;

  select coalesce(pg_catalog.array_agg(key::uuid order by key::uuid), array[]::uuid[])
  into changed_field_ids
  from pg_catalog.jsonb_object_keys(p_final_values) as key;

  command_fingerprint_value := vortex_record.base_save_command_fingerprint_internal(
    p_command_id, 'update', p_record_type_id, p_record_id,
    p_expected_concurrency_number, p_submitted_values, null::uuid
  );
  receipt_claim := vortex_record.claim_command_receipt_internal(
    'record_save', p_command_id, 'update', command_fingerprint_value,
    p_record_type_id, null, '{}'::jsonb, '{}'::jsonb, false
  );
  if receipt_claim ->> 'status' is distinct from 'claimed' then
    if receipt_claim ->> 'status' = 'identity_conflict' then
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused', 'reasonCode', 'command_identity_conflict',
        'correlationId', correlation_id_value
      );
    end if;
    if receipt_claim ->> 'status' = 'completed' then
      projection := vortex_record.read_record(p_record_type_id, p_record_id);
      if projection ->> 'outcome' <> 'allowed' then
        return pg_catalog.jsonb_build_object(
          'outcome', 'refused', 'reasonCode', 'record_unavailable',
          'correlationId', correlation_id_value
        );
      end if;
      return pg_catalog.jsonb_build_object(
        'outcome', 'saved',
        'recordId', projection -> 'recordId',
        'concurrencyNumber', projection -> 'concurrencyNumber',
        'values', projection -> 'values',
        'correlationId', correlation_id_value,
        'backgroundDelivery', 'pending',
        'replayed', true
      );
    end if;
    if receipt_claim ->> 'status' is distinct from 'none' then
      return pg_catalog.jsonb_build_object(
        'outcome', 'conflict', 'reasonCode', 'command_pending',
        'correlationId', correlation_id_value
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'command_invalid',
      'correlationId', correlation_id_value
    );
  end if;

  if (loaded ->> 'concurrencyNumber')::bigint <> p_expected_concurrency_number then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'conflict',
      'reasonCode', 'record_revision_conflict',
      'concurrencyNumber', loaded -> 'concurrencyNumber',
      'correlationId', correlation_id_value
    );
  end if;

  access_result := vortex_access.save_organization_settings_record_for_administration(
    p_record_id, p_expected_concurrency_number, core_values, extension_values
  );
  if access_result ->> 'outcome' = 'conflict' then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return access_result || pg_catalog.jsonb_build_object(
      'reasonCode', coalesce(access_result ->> 'reasonCode', 'access_conflict'),
      'correlationId', correlation_id_value
    );
  end if;
  if access_result ->> 'outcome' <> 'saved' then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', coalesce(access_result ->> 'reasonCode', 'access_refused'),
      'correlationId', correlation_id_value
    );
  end if;

  perform vortex_record.append_base_save_activity_internal(
    p_activity_id, 'update', p_record_id, changed_field_ids, 'completed'
  );
  event_result := vortex_event.append_record_occurrences(
    (meta ->> 'storageContractId')::uuid,
    p_record_id,
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'occurrenceId', p_occurrence_id,
      'descriptor', pg_catalog.jsonb_build_object(
        'kind', 'standard', 'eventKind', 'changed', 'recordTypeId', p_record_type_id
      ),
      'payload', pg_catalog.jsonb_build_object(
        'kind', 'changed', 'changedFieldIds', pg_catalog.to_jsonb(changed_field_ids)
      )
    ))
  );
  if pg_catalog.jsonb_array_length(event_result) <> 1 then
    raise exception using errcode = '55000', message = 'Organization settings Event append failed';
  end if;

  perform vortex_record.complete_command_receipt_internal(
    'record_save', p_command_id, p_record_id,
    (access_result ->> 'concurrencyNumber')::bigint,
    'Organization settings record save receipt is stale'
  );
  projection := vortex_record.read_record(p_record_type_id, p_record_id);
  if projection ->> 'outcome' <> 'allowed' then
    raise exception using errcode = '55000',
      message = 'Saved organisation settings projection is unavailable';
  end if;
  return pg_catalog.jsonb_build_object(
    'outcome', 'saved',
    'recordId', projection -> 'recordId',
    'concurrencyNumber', projection -> 'concurrencyNumber',
    'values', projection -> 'values',
    'correlationId', correlation_id_value,
    'backgroundDelivery', 'pending',
    'replayed', false
  );
exception
  when serialization_failure or deadlock_detected then
    get stacked diagnostics
      failure_sqlstate = returned_sqlstate,
      failure_message = message_text;
    raise log 'Organization settings record save conflicted: % (%)', failure_message, failure_sqlstate;
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'conflict', 'reasonCode', 'database_conflict_' || failure_sqlstate,
      'correlationId', correlation_id_value
    );
  when no_data_found or too_many_rows or insufficient_privilege or check_violation
    or object_not_in_prerequisite_state or invalid_text_representation then
    get stacked diagnostics
      failure_sqlstate = returned_sqlstate,
      failure_message = message_text;
    raise log 'Organization settings record save refused: % (%)', failure_message, failure_sqlstate;
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused', 'reasonCode', 'database_refused_' || failure_sqlstate,
      'correlationId', correlation_id_value
    );
end
$function$;


ALTER FUNCTION vortex_record.save_organization_settings_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_activity_id uuid, p_occurrence_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION save_organization_settings_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_activity_id uuid, p_occurrence_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.save_organization_settings_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_submitted_values jsonb, p_final_values jsonb, p_activity_id uuid, p_occurrence_id uuid) IS 'Closed Record save writer for the organisation_settings system projection: rechecks its installed definition, delegates protected settings authorization and persistence to Access, and records one receipt, Activity and Event.';


--
-- Name: save_record_type_lifecycle_policy_for_administration(uuid, uuid, bigint, bigint, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.save_record_type_lifecycle_policy_for_administration(p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_expected_policy_revision bigint, p_activity_id uuid, p_policy jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority record;
  limits_row vortex_record.organization_lifecycle_limits%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  existing vortex_record.record_type_lifecycle_policies%rowtype;
  has_existing boolean;
  next_revision bigint;
  next_policy_id uuid;
  full_policy jsonb;
  connection_readiness jsonb;
begin
  if p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (p_application_root_id is not null
      and p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid)
    or p_expected_settings_revision is null
    or p_expected_settings_revision not between 1 and 9007199254740991
    or (p_expected_policy_revision is not null
      and p_expected_policy_revision not between 1 and 9007199254740991)
    or p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_policy is null
    or pg_catalog.jsonb_typeof(p_policy) <> 'object'
    -- Identity, scope and revision are assigned by this operation. A caller
    -- that supplies any of them is refused rather than silently overridden.
    or p_policy ?| array[
      'policyId', 'organizationId', 'storageContractId', 'applicationRootId',
      'policyRevision'
    ] then
    raise exception using errcode = '22023',
      message = 'Record-type lifecycle policy command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_record_lifecycle_policy_authority() as locked;

  -- The resolved request scope must be application-bound exactly when the
  -- target is application-contained, and bound to the exact same application.
  if (p_application_root_id is null) <> (authority.application_root_id is null)
    or (p_application_root_id is not null
      and authority.application_root_id <> p_application_root_id) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy administration is unavailable';
  end if;

  -- Exact target existence and application-contained/organisation-shared
  -- scope shape: the storage contract must be an active record-type target
  -- whose declared scope matches the supplied application root ID (null only
  -- for organisation-shared record types).
  select catalogue.* into catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = p_storage_contract_id
  for share;
  if not found
    or catalogue_row.state <> 'active'
    or (catalogue_row.storage_scope = 'organization_shared')
      <> (p_application_root_id is null) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy target is unavailable';
  end if;

  -- A platform storage contract is not a target for every organisation: the
  -- record type must belong to a currently active installation here.
  if not vortex_module.record_lifecycle_target_is_installed_internal(
    authority.organization_id, p_application_root_id, p_storage_contract_id
  ) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy target is unavailable';
  end if;

  -- A policy can only be bound to the exact, current organisation limits
  -- revision the caller reviewed; a concurrently changed ceiling is a stale
  -- refusal, never a silent reinterpretation under the new limits.
  select limits.* into limits_row
  from vortex_record.organization_lifecycle_limits as limits
  where limits.organization_id = authority.organization_id
  for share;
  if not found then
    raise exception using errcode = '42501',
      message = 'Organisation lifecycle limits are unavailable';
  end if;
  if limits_row.settings_revision <> p_expected_settings_revision then
    raise exception using errcode = '40001',
      message = 'Organisation lifecycle limits are stale';
  end if;

  select stored.* into existing
  from vortex_record.record_type_lifecycle_policies as stored
  where stored.organization_id = authority.organization_id
    and stored.storage_contract_id = p_storage_contract_id
    and stored.application_root_id is not distinct from p_application_root_id
  for update;
  -- `found` is reset by every later query, so the create/update decision is
  -- kept in its own variable.
  has_existing := found;

  if has_existing then
    if p_expected_policy_revision is null
      or existing.policy_revision <> p_expected_policy_revision then
      raise exception using errcode = '40001',
        message = 'Record-type lifecycle policy is stale';
    end if;
    if existing.policy_revision = 9007199254740991 then
      raise exception using errcode = '22003',
        message = 'Record-type lifecycle policy revision is exhausted';
    end if;
    next_revision := existing.policy_revision + 1;
    next_policy_id := existing.policy_id;
  else
    if p_expected_policy_revision is not null then
      raise exception using errcode = '40001',
        message = 'Record-type lifecycle policy is stale';
    end if;
    next_revision := 1;
    next_policy_id := pg_catalog.gen_random_uuid();
  end if;

  -- The envelope (identity, scope and revision) is assigned here, never
  -- accepted from the caller; this is what keeps `policyId` immutable.
  full_policy := p_policy || pg_catalog.jsonb_build_object(
    'policyId', next_policy_id,
    'organizationId', authority.organization_id,
    'storageContractId', p_storage_contract_id,
    'applicationRootId', p_application_root_id,
    'policyRevision', next_revision
  );

  if not vortex_record.is_record_type_lifecycle_policy(full_policy) then
    raise exception using errcode = '22023',
      message = 'Record-type lifecycle policy command is invalid';
  end if;

  -- Enforce organisation limits: allowed action, age/count ceilings and
  -- unlimited permissions, and (for archive_workflow) an allowed
  -- destination. This is re-checked here, under the limits row's lock,
  -- rather than trusted from an earlier, possibly stale, client read.
  if full_policy ->> 'action' <> all (limits_row.allowed_actions) then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy action is not permitted by organisation limits';
  end if;

  if pg_catalog.jsonb_typeof(full_policy -> 'maxAgeDays') = 'number' then
    if limits_row.max_retention_days is not null
      and (full_policy #>> '{maxAgeDays}')::numeric > limits_row.max_retention_days then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy maxAgeDays exceeds organisation limit';
    end if;
  elsif not limits_row.allow_unlimited_retention_days then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy unlimited age retention is not permitted';
  end if;

  if pg_catalog.jsonb_typeof(full_policy -> 'maxCount') = 'number' then
    if limits_row.max_record_count is not null
      and (full_policy #>> '{maxCount}')::numeric > limits_row.max_record_count then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy maxCount exceeds organisation limit';
    end if;
  elsif not limits_row.allow_unlimited_record_count then
    raise exception using errcode = '42501',
      message = 'Record-type lifecycle policy unlimited record count is not permitted';
  end if;

  if full_policy ->> 'action' = 'archive_workflow'
    and (full_policy ->> 'archiveDestination')
      <> all (limits_row.allowed_archive_destinations) then
    raise exception using errcode = '42501',
      message =
        'Record-type lifecycle policy archive destination is not permitted by organisation limits';
  end if;

  if full_policy ->> 'action' = 'archive_workflow' then
    -- Runtime workflows and Connection grants require one permanent
    -- Application scope. An organisation-shared policy cannot invent one.
    if p_application_root_id is null
      or not vortex_module.record_lifecycle_workflow_is_installed_internal(
        authority.organization_id,
        p_application_root_id,
        p_storage_contract_id,
        (full_policy ->> 'archiveWorkflowId')::uuid,
        (full_policy #>> '{expectedWorkflowRevision}')::bigint
      ) then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy archive workflow is unavailable';
    end if;

    connection_readiness := vortex_connection.resolve_connection_instance_readiness(
      authority.organization_id,
      p_application_root_id,
      (full_policy ->> 'archiveConnectionInstanceId')::uuid,
      full_policy ->> 'archiveDestination',
      (full_policy #>> '{expectedConnectionRevision}')::bigint,
      full_policy ->> 'expectedDestinationFingerprint'
    );
    if connection_readiness ->> 'outcome' is distinct from 'ready'
      or pg_catalog.lower(connection_readiness ->> 'connectionInstanceId')
        is distinct from pg_catalog.lower(full_policy ->> 'archiveConnectionInstanceId')
      or connection_readiness ->> 'organizationId'
        is distinct from authority.organization_id::text
      or connection_readiness ->> 'applicationRootId'
        is distinct from p_application_root_id::text
      or connection_readiness ->> 'destinationKey'
        is distinct from full_policy ->> 'archiveDestination'
      or connection_readiness ->> 'destinationFingerprint'
        is distinct from full_policy ->> 'expectedDestinationFingerprint'
      or connection_readiness ->> 'revision'
        is distinct from full_policy #>> '{expectedConnectionRevision}'
      or connection_readiness ->> 'healthOutcome' is distinct from 'healthy'
      or connection_readiness ->> 'state' is distinct from 'active' then
      raise exception using errcode = '42501',
        message = 'Record-type lifecycle policy archive connection is unavailable';
    end if;
  end if;

  if has_existing then
    update vortex_record.record_type_lifecycle_policies as stored set
      policy_revision = next_revision,
      action = full_policy ->> 'action',
      policy_body = full_policy,
      changed_at = pg_catalog.statement_timestamp()
    where stored.policy_id = next_policy_id;
  else
    begin
      insert into vortex_record.record_type_lifecycle_policies (
        policy_id, organization_id, storage_contract_id, application_root_id,
        policy_revision, action, policy_body
      ) values (
        next_policy_id, authority.organization_id, p_storage_contract_id,
        p_application_root_id, next_revision, full_policy ->> 'action', full_policy
      );
    exception when unique_violation then
      raise exception using errcode = '40001',
        message = 'Record-type lifecycle policy is stale';
    end;
  end if;

  perform vortex_record.append_lifecycle_policy_activity_internal(
    p_activity_id, next_policy_id
  );

  return full_policy;
end
$$;


ALTER FUNCTION vortex_record.save_record_type_lifecycle_policy_for_administration(p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_expected_policy_revision bigint, p_activity_id uuid, p_policy jsonb) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION save_record_type_lifecycle_policy_for_administration(p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_expected_policy_revision bigint, p_activity_id uuid, p_policy jsonb); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.save_record_type_lifecycle_policy_for_administration(p_storage_contract_id uuid, p_application_root_id uuid, p_expected_settings_revision bigint, p_expected_policy_revision bigint, p_activity_id uuid, p_policy jsonb) IS 'Protected administrator save (create or update) of one record type''s current lifecycle policy within current organisation limits; stale organisation-limits/policy revisions, uninstalled or unknown targets, unready archive bindings and disallowed actions/destinations are refused. policyId is server-assigned and immutable; successful Activity commits atomically.';


--
-- Name: share_lock_named_action_target_internal(jsonb, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.share_lock_named_action_target_internal(
  p_catalogue jsonb,
  p_record_type_id uuid,
  p_record_id uuid
)
returns boolean
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  context_value jsonb;
  record_type jsonb;
begin
  if p_record_type_id is null or p_record_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return false;
  end if;

  select item.value into record_type
  from pg_catalog.jsonb_array_elements(p_catalogue -> 'recordTypes') as item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') =
    pg_catalog.lower(p_record_type_id::text);
  if record_type is null or not exists (
    select 1
    from vortex_record.storage_catalogue as stored
    where stored.storage_contract_id = (record_type ->> 'storageContractId')::uuid
      and stored.record_type_id = p_record_type_id
      and stored.state = 'active'
  ) then
    return false;
  end if;

  context_value := vortex_access.validated_human_request_context();
  begin
    perform vortex_record.lock_relationship_target_row_internal(
      p_record_type_id, p_record_id,
      (context_value ->> 'organizationId')::uuid
    );
    return true;
  exception when no_data_found then
    return false;
  end;
end
$function$;


ALTER FUNCTION vortex_record.share_lock_named_action_target_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION share_lock_named_action_target_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.share_lock_named_action_target_internal(p_catalogue jsonb, p_record_type_id uuid, p_record_id uuid) IS 'Private named-action preflight target lock: checks the installed target contract, then takes the canonical active same-organisation record or protected projection lock before later command locks.';


--
-- Name: soft_delete_record_internal(uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.soft_delete_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_record_type_id is null or p_record_id is null
    or p_expected_concurrency_number not between 1 and 9007199254740990 then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'command_invalid');
  end if;
  begin
    perform vortex_record.soft_delete_record_recursive_internal(
      p_record_type_id, p_record_id, p_expected_concurrency_number, array[]::text[]
    );
    return pg_catalog.jsonb_build_object(
      'outcome', 'completed', 'recordId', p_record_id,
      'concurrencyNumber', p_expected_concurrency_number + 1
    );
  exception
    when serialization_failure or deadlock_detected then
      return pg_catalog.jsonb_build_object('outcome', 'conflict');
    when no_data_found or insufficient_privilege or object_not_in_prerequisite_state then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'record_unavailable');
    when check_violation then
      return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'relationship_refused');
  end;
end
$$;


ALTER FUNCTION vortex_record.soft_delete_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION soft_delete_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.soft_delete_record_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint) IS 'Private revision-checked recoverable delete primitive with current Access and declared incoming relationship handling; it sets no recovery policy.';


--
-- Name: soft_delete_record_recursive_internal(uuid, uuid, bigint, text[]); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.soft_delete_record_recursive_internal(
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint,
  p_visited text[]
)
returns void
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  meta jsonb;
  loaded jsonb;
  facts jsonb;
  decision jsonb;
  context_value jsonb;
  record_fact jsonb;
  identity_value text;
  incoming record;
  source_catalogue vortex_record.storage_catalogue%rowtype;
  source_meta jsonb;
  source_loaded jsonb;
  source_decision jsonb;
  source_record_type jsonb;
  source_concurrency bigint;
  source_link_column text;
  source_link_value jsonb;
  source_identity text;
  source_action_kind text;
  changed_rows integer;
  application_scope uuid;
  saved_record_id uuid;
  saved_concurrency_number bigint;
  preview_installation jsonb;
  notice_sequence bigint;
begin
  meta := vortex_record.resolve_record_action_context_internal(p_record_type_id, 'delete');
  context_value := meta -> 'context';
  identity_value := pg_catalog.lower((meta ->> 'storageContractId')) || ':'
    || pg_catalog.lower(p_record_id::text);
  if identity_value = any (p_visited) then
    raise exception using errcode = '23514', message = 'Relationship deletion cycle is invalid';
  end if;
  p_visited := pg_catalog.array_append(p_visited, identity_value);

  loaded := vortex_record.load_record_access_facts_internal(
    p_record_type_id, 'delete', p_record_id, p_expected_concurrency_number
  );
  if loaded ->> 'outcome' = 'conflict' then
    raise exception using errcode = '40001', message = 'Record delete revision is stale';
  end if;
  if loaded ->> 'outcome' <> 'loaded'
    or pg_catalog.jsonb_typeof(meta -> 'declaration') <> 'object' then
    raise exception using errcode = 'P0002', message = 'Record is unavailable';
  end if;
  select item.value into record_fact
  from pg_catalog.jsonb_array_elements(loaded -> 'facts' -> 'records') as item(value)
  where (item.value -> 'recordScope' ->> 'recordId')::uuid = p_record_id;
  if record_fact ->> 'lifecycleState' <> 'active' then
    raise exception using errcode = 'P0002', message = 'Record is unavailable';
  end if;
  facts := (loaded -> 'facts') || pg_catalog.jsonb_build_object(
    'binding', meta -> 'declaration' -> 'recordBinding'
  );
  decision := vortex_access.evaluate_organization_record_access_internal(
    meta -> 'declaration', p_record_id, facts
  );
  if decision ->> 'outcome' <> 'allowed' then
    raise exception using errcode = 'P0002', message = 'Record is unavailable';
  end if;

  -- Incoming edges are canonicalised before any child lock.  Every affected
  -- child is then reloaded and locked by #401's fixed loader.
  for incoming in
    select edge.*, mapping.on_parent_delete, mapping.relationship_id,
      mapping.source_field_id
    from vortex_record.relationship_edges as edge
    join vortex_record.relationship_storage_mappings as mapping
      on mapping.relationship_id = edge.relationship_id
    where edge.to_organisation_id = (context_value ->> 'organizationId')::uuid
      and edge.to_storage_contract_id = (meta ->> 'storageContractId')::uuid
      and edge.to_record_id = p_record_id
    order by edge.from_storage_contract_id, edge.from_record_id, edge.relationship_id
  loop
    select catalogue.* into source_catalogue
    from vortex_record.storage_catalogue as catalogue
    where catalogue.storage_contract_id = incoming.from_storage_contract_id;
    source_identity := pg_catalog.lower(incoming.from_storage_contract_id::text) || ':'
      || pg_catalog.lower(incoming.from_record_id::text);
    if source_identity = any (p_visited) then
      raise exception using errcode = '23514', message = 'Relationship deletion cycle is invalid';
    end if;

    -- A child retained by another Application cannot be silently modified
    -- under this Application's request context.  It is therefore a safe
    -- blocking relationship, not an authority bypass.
    source_action_kind := case
      when incoming.on_parent_delete = 'empty_optional' then 'update'
      when incoming.on_parent_delete = 'soft_delete_dependent' then 'delete'
      else 'read'
    end;
    begin
      source_meta := vortex_record.resolve_record_action_context_internal(
        source_catalogue.record_type_id, source_action_kind
      );
    exception when others then
      raise exception using errcode = '23514', message = 'Parent deletion is blocked';
    end;

    select field_mapping.physical_column_token into strict source_link_column
    from vortex_record.field_storage_mappings as field_mapping
    where field_mapping.storage_contract_id = incoming.from_storage_contract_id
      and field_mapping.field_id = incoming.source_field_id
      and field_mapping.state = 'active'
      and field_mapping.introduced_at_release_revision <=
        (source_meta ->> 'moduleReleaseRevision')::bigint;

    execute pg_catalog.format(
      'select concurrency_number, %I from record_data.%I as stored
       where stored.organisation_id = $1 and stored.record_id = $2
         and stored.lifecycle_state = ''active'' for update',
      source_link_column, source_meta ->> 'table'
    ) into source_concurrency, source_link_value using
      (context_value ->> 'organizationId')::uuid, incoming.from_record_id;
    if not found then
      continue;
    end if;
    -- The incoming-edge cursor may have been opened before a concurrent link
    -- change committed. The source row lock returns the current tuple, so
    -- re-check its exact field before applying parent-delete behaviour. This
    -- prevents a stale edge snapshot from clearing or revising the source a
    -- second time after that link was already removed or redirected.
    if pg_catalog.jsonb_typeof(source_link_value) <> 'object'
      or source_link_value ->> 'recordId' is distinct from p_record_id::text then
      continue;
    end if;
    source_loaded := vortex_record.load_record_access_facts_internal(
      source_catalogue.record_type_id, source_action_kind, incoming.from_record_id,
      source_concurrency
    );
    if source_loaded ->> 'outcome' <> 'loaded' then
      continue;
    end if;
    select item.value into record_fact
    from pg_catalog.jsonb_array_elements(source_loaded -> 'facts' -> 'records') as item(value)
    where (item.value -> 'recordScope' ->> 'recordId')::uuid = incoming.from_record_id;
    if record_fact ->> 'lifecycleState' <> 'active' then
      continue;
    end if;
    if incoming.on_parent_delete = 'refuse' then
      raise exception using errcode = '23514', message = 'Parent deletion is blocked';
    end if;
    if pg_catalog.jsonb_typeof(source_meta -> 'declaration') <> 'object' then
      raise exception using errcode = '42501', message = 'Affected record is unavailable';
    end if;
    source_decision := vortex_access.evaluate_organization_record_access_internal(
      source_meta -> 'declaration', incoming.from_record_id,
      (source_loaded -> 'facts') || pg_catalog.jsonb_build_object(
        'binding', source_meta -> 'declaration' -> 'recordBinding'
      )
    );
    if source_decision ->> 'outcome' <> 'allowed' then
      raise exception using errcode = '42501', message = 'Affected record is unavailable';
    end if;

    if incoming.on_parent_delete = 'empty_optional' then
      perform vortex_record.write_relationship_value_internal(
        source_catalogue.record_type_id, incoming.from_record_id,
        incoming.relationship_id, 'null'::jsonb, true
      );
      perform vortex_record.append_record_lifecycle_effect_internal(
        'optional_cleared', incoming.from_storage_contract_id,
        source_catalogue.record_type_id, incoming.from_record_id,
        source_concurrency, incoming.relationship_id
      );
    elsif incoming.on_parent_delete = 'soft_delete_dependent' then
      source_record_type := source_meta -> 'recordType';
      if source_record_type ->> 'ownershipMode' <> 'inherited'
        or not source_record_type ? 'ownershipRelationshipId'
        or (source_record_type ->> 'ownershipRelationshipId')::uuid <>
          incoming.relationship_id then
        raise exception using errcode = '23514', message = 'Dependent deletion is not declared';
      end if;
      perform vortex_record.soft_delete_record_recursive_internal(
        source_catalogue.record_type_id, incoming.from_record_id,
        source_concurrency, p_visited
      );
    else
      raise exception using errcode = '23514', message = 'Parent deletion behavior is invalid';
    end if;
  end loop;

  execute pg_catalog.format(
    'update record_data.%I as stored
     set lifecycle_state = ''soft_deleted'',
       concurrency_number = concurrency_number + 1,
       updated_at = pg_catalog.statement_timestamp(), updated_by = $3,
       deleted_at = pg_catalog.statement_timestamp(), deleted_by = $3,
       removal_due_at = null, definition_revision = $4
     where organisation_id = $1 and record_id = $2
       and lifecycle_state = ''active'' and concurrency_number = $5
     returning stored.record_id, stored.concurrency_number',
    meta ->> 'table'
  ) into saved_record_id, saved_concurrency_number using
    (context_value ->> 'organizationId')::uuid, p_record_id,
    (context_value ->> 'organizationAccountId')::uuid,
    (meta ->> 'moduleReleaseRevision')::bigint, p_expected_concurrency_number;
  get diagnostics changed_rows = row_count;
  if changed_rows <> 1 then
    raise exception using errcode = '40001', message = 'Record delete revision changed';
  end if;
  if saved_record_id is distinct from p_record_id
    or saved_concurrency_number is null
    or saved_concurrency_number not between 1 and 9007199254740991 then
    raise exception using errcode = '55000', message = 'Record delete saved identity is unavailable';
  end if;
  perform vortex_record.append_record_lifecycle_effect_internal(
    'soft_deleted', (meta ->> 'storageContractId')::uuid,
    p_record_type_id, p_record_id, p_expected_concurrency_number, null
  );
  application_scope := case when meta ->> 'storageScope' = 'application_contained'
    then (context_value ->> 'applicationRootId')::uuid else null end;
  preview_installation :=
    vortex_record.read_current_preview_installation_internal();
  if preview_installation is null
    and meta ->> 'storageScope' = 'application_contained' then
    begin
      notice_sequence := pg_catalog.nextval(
        'vortex_record.record_invalidation_sequence'::pg_catalog.regclass
      );
      perform vortex_invalidation.publish_change_notice(
        (context_value ->> 'organizationId')::uuid,
        application_scope, p_record_type_id,
        saved_record_id, saved_concurrency_number, 'deleted',
        notice_sequence, notice_sequence,
        (context_value ->> 'correlationId')::uuid
      );
    exception when others then
      -- Invalidation is advisory; the protected delete remains transactional.
      null;
    end;
  else
    perform vortex_record.bump_record_data_version_internal(
      (context_value ->> 'organizationId')::uuid,
      (meta ->> 'storageContractId')::uuid, application_scope
    );
  end if;
end
$function$;


ALTER FUNCTION vortex_record.soft_delete_record_recursive_internal(p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_visited text[]) OWNER TO vortex_record_adapter;

--
-- Name: sql_value_type(text); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.sql_value_type(p_database_value_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_database_value_type
    when 'integer' then 'bigint'
    when 'decimal' then 'numeric'
    when 'boolean' then 'boolean'
    when 'date' then 'date'
    when 'timestamp_with_time_zone' then 'timestamp with time zone'
    when 'uuid' then 'uuid'
    when 'json' then 'jsonb'
    else 'text'
  end
$$;


ALTER FUNCTION vortex_record.sql_value_type(p_database_value_type text) OWNER TO vortex_record_owner;

--
-- Name: storage_conversion_contract_identity(uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.storage_conversion_contract_identity(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (
    pg_catalog.substr(source.digest_hex, 1, 12)
    || '8'
    || pg_catalog.substr(source.digest_hex, 14, 3)
    || pg_catalog.substr(
      '89ab',
      (pg_catalog.strpos(
        '0123456789abcdef', pg_catalog.substr(source.digest_hex, 17, 1)
      ) - 1) % 4 + 1,
      1
    )
    || pg_catalog.substr(source.digest_hex, 18, 15)
  )::uuid
  from (
    select pg_catalog.md5(
      pg_catalog.lower(p_source_storage_contract_id::text) || ':'
        || pg_catalog.lower(p_source_field_id::text) || ':'
        || pg_catalog.lower(p_target_field_id::text)
    ) as digest_hex
  ) as source
$$;


ALTER FUNCTION vortex_record.storage_conversion_contract_identity(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION storage_conversion_contract_identity(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.storage_conversion_contract_identity(p_source_storage_contract_id uuid, p_source_field_id uuid, p_target_field_id uuid) IS 'Stable derived RFC 9562 version-8 conversion identity for one exact storage contract and source/target field pair.';


--
-- Name: storage_meaning(jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.storage_meaning(p_record_type jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'recordTypeId', p_record_type -> 'recordTypeId',
    'storageContractId', p_record_type -> 'storageContractId',
    'storageScope', p_record_type -> 'storageScope',
    'ownershipMode', p_record_type -> 'ownershipMode',
    'fields', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'fieldId', field.value -> 'fieldId',
        'type', field.value -> 'type',
        'required', field.value -> 'required',
        'unique', field.value -> 'unique',
        'filterable', field.value -> 'filterable',
        'sortable', field.value -> 'sortable',
        'settings', field.value -> 'settings'
      ) order by field.value ->> 'fieldId')
      from pg_catalog.jsonb_array_elements(p_record_type -> 'fields') as field(value)
    ), '[]'::jsonb),
    'relationships', coalesce((
      select pg_catalog.jsonb_agg(relationship.value order by relationship.value ->> 'relationshipId')
      from pg_catalog.jsonb_array_elements(p_record_type -> 'relationships') as relationship(value)
    ), '[]'::jsonb)
  )
$$;


ALTER FUNCTION vortex_record.storage_meaning(p_record_type jsonb) OWNER TO vortex_record_owner;

--
-- Name: storage_meaning_fingerprint(jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.storage_meaning_fingerprint(p_record_type jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'sha256:' || pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(vortex_record.storage_meaning(p_record_type)::text, 'UTF8'), 'sha256'),
    'hex'
  )
$$;


ALTER FUNCTION vortex_record.storage_meaning_fingerprint(p_record_type jsonb) OWNER TO vortex_record_owner;

--
-- Name: switch_storage_conversion_mappings_internal(uuid, boolean); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE FUNCTION vortex_record.switch_storage_conversion_mappings_internal(p_conversion_contract_id uuid, p_owns_module boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  conversion vortex_record.storage_conversion_catalogue%rowtype;
  catalogue_row vortex_record.storage_catalogue%rowtype;
  source_mapping vortex_record.field_storage_mappings%rowtype;
  target_mapping vortex_record.field_storage_mappings%rowtype;
  mapping_lock record;
  dependent_release_revisions bigint[];
  dependent_count bigint;
  index_purpose text;
begin
  if p_owns_module is null then
    raise exception using errcode = '22023',
      message = 'Storage adoption switch command is invalid';
  end if;

  select entry.* into strict conversion
  from vortex_record.storage_conversion_catalogue as entry
  where entry.conversion_contract_id = p_conversion_contract_id;
  select catalogue.* into strict catalogue_row
  from vortex_record.storage_catalogue as catalogue
  where catalogue.storage_contract_id = conversion.source_storage_contract_id;
  if catalogue_row.state <> 'active' then
    raise exception using errcode = '55000',
      message = 'Storage adoption contract is unavailable';
  end if;

  -- Both mappings, in canonical field-id order, the same order the provisioner
  -- and the #625 staging use.
  for mapping_lock in
    select mapping.field_id
    from vortex_record.field_storage_mappings as mapping
    where mapping.storage_contract_id = conversion.source_storage_contract_id
      and mapping.field_id in (conversion.source_field_id, conversion.target_field_id)
    order by mapping.field_id
    for update
  loop
    null;
  end loop;

  select mapping.* into strict source_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.source_field_id;
  select mapping.* into strict target_mapping
  from vortex_record.field_storage_mappings as mapping
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.target_field_id;

  -- A completed switch is an unchanged replay, for the Module owner and for
  -- any other organisation adopting its own converted plan afterwards.
  if source_mapping.state = 'retired'
    and source_mapping.retired_at_release_revision = conversion.target_release_revision
    and target_mapping.state = 'active'
    and target_mapping.introduced_at_release_revision = conversion.target_release_revision then
    return pg_catalog.jsonb_build_object('changed', false, 'dependentCount', 0);
  end if;

  -- Making the switch changes the Module's shared storage for every
  -- installation, so only the organisation that owns the Module may do it.
  if not p_owns_module then
    raise exception using errcode = '42501',
      message = 'Storage adoption switch requires the Module owner';
  end if;

  if source_mapping.state <> 'active'
    or source_mapping.database_value_type <> conversion.source_database_value_type
    or target_mapping.state <> 'planned'
    or target_mapping.database_value_type <> conversion.target_database_value_type
    or target_mapping.physical_column_token <> 'f_' || pg_catalog.replace(
      pg_catalog.lower(conversion.target_field_id::text), '-', ''
    )
    or target_mapping.introduced_at_release_revision <> conversion.target_release_revision
    or vortex_record.field_storage_meaning(target_mapping.field_definition)
      is distinct from vortex_record.field_storage_meaning(conversion.target_field_definition)
  then
    raise exception using errcode = '55000',
      message = 'Storage adoption mappings are incompatible';
  end if;

  -- Every published release of the Module whose content still carries the
  -- source field in this storage, whatever its revision: an older release
  -- provisioned after a newer one introduced the field, and a later release
  -- that kept it, both need the source column.
  select coalesce(
    pg_catalog.array_agg(release.release_revision order by release.release_revision),
    array[]::bigint[]
  )
  into dependent_release_revisions
  from vortex_definition.releases as release
  where release.root_id = catalogue_row.module_root_id
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(
            release.compilation_output #> '{canonical,content,recordTypes}'
          ) = 'array'
            then release.compilation_output #> '{canonical,content,recordTypes}'
          else '[]'::jsonb
        end
      ) as record_item(value)
      cross join lateral pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(record_item.value -> 'fields') = 'array'
            then record_item.value -> 'fields'
          else '[]'::jsonb
        end
      ) as field_item(value)
      where pg_catalog.lower(record_item.value ->> 'storageContractId')
          = conversion.source_storage_contract_id::text
        and pg_catalog.lower(field_item.value ->> 'fieldId')
          = conversion.source_field_id::text
    );

  -- Any installation of such a release keeps the whole storage in place:
  -- retiring it would strip an installation of a required column.
  dependent_count := vortex_module.count_storage_adoption_dependents_internal(
    catalogue_row.module_root_id, conversion.source_storage_contract_id,
    dependent_release_revisions
  );
  if dependent_count > 0 then
    raise exception using errcode = '55006',
      message = 'Storage adoption is blocked while installations still use the source storage';
  end if;

  update vortex_record.field_storage_mappings as mapping
  set state = 'retired',
      retired_by_module_root_id = catalogue_row.module_root_id,
      retired_at_release_revision = conversion.target_release_revision
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.source_field_id
    and mapping.state = 'active';
  if not found then
    raise exception using errcode = '40001',
      message = 'Storage adoption source mapping changed';
  end if;

  update vortex_record.field_storage_mappings as mapping
  set state = 'active'
  where mapping.storage_contract_id = conversion.source_storage_contract_id
    and mapping.field_id = conversion.target_field_id
    and mapping.state = 'planned';
  if not found then
    raise exception using errcode = '40001',
      message = 'Storage adoption target mapping changed';
  end if;

  -- The activation gate reads the recorded index of every active field, and
  -- the provisioner only indexes a field it creates, so the switched target
  -- field's index is created here with the provisioner's branch order. A
  -- duplicate converted value refuses the uniqueness index and rolls the whole
  -- adoption back.
  index_purpose := case
    when coalesce((target_mapping.field_definition ->> 'unique')::boolean, false)
      then 'uniqueness'
    when coalesce((target_mapping.field_definition ->> 'filterable')::boolean, false)
      or coalesce((target_mapping.field_definition ->> 'sortable')::boolean, false)
      then 'performance'
    else null
  end;
  if index_purpose is not null then
    begin
      perform vortex_record.ensure_field_index_internal(
        conversion.source_storage_contract_id, conversion.target_field_id, index_purpose,
        catalogue_row.storage_scope, catalogue_row.physical_table_token,
        vortex_record.index_scope_columns(catalogue_row.storage_scope),
        target_mapping.physical_column_token
      );
    exception
      when unique_violation then
        raise exception using errcode = '55000',
          message = 'Storage adoption converted values are not unique';
    end;
  end if;

  return pg_catalog.jsonb_build_object('changed', true, 'dependentCount', dependent_count);
exception
  when no_data_found or too_many_rows then
    raise exception using errcode = '55000',
      message = 'Storage adoption evidence is unavailable';
end
$$;


ALTER FUNCTION vortex_record.switch_storage_conversion_mappings_internal(p_conversion_contract_id uuid, p_owns_module boolean) OWNER TO vortex_record_owner;

--
-- Name: FUNCTION switch_storage_conversion_mappings_internal(p_conversion_contract_id uuid, p_owns_module boolean); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_owner
--

COMMENT ON FUNCTION vortex_record.switch_storage_conversion_mappings_internal(p_conversion_contract_id uuid, p_owns_module boolean) IS 'Private helper: refuses while any installation of a release carrying the source field remains, then (Module owner only) switches the target mapping to active, the source mapping to retired and records the target field''s index; a completed switch is an unchanged replay; never drops a column.';


--
-- Name: total_dependency_contract_internal(jsonb, jsonb, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.total_dependency_contract_internal(
  p_record_types jsonb,
  p_relationships jsonb,
  p_target_record_type_id uuid,
  p_total_field jsonb
)
returns jsonb
language plpgsql
immutable
security invoker
set search_path = ''
as $function$
declare
  relationship_id_value uuid;
  relationship_value jsonb;
  source_type_value jsonb;
  source_type_id uuid;
  source_ids jsonb := '[]'::jsonb;
  source_field_id text;
begin
  if p_target_record_type_id is null
    or pg_catalog.jsonb_typeof(p_record_types) <> 'array'
    or pg_catalog.jsonb_typeof(p_relationships) <> 'array'
    or pg_catalog.jsonb_typeof(p_total_field) <> 'object'
    or p_total_field ->> 'type' <> 'total'
    or not pg_catalog.pg_input_is_valid(
      p_total_field #>> '{settings,relationshipId}', 'uuid'
    ) then
    return null;
  end if;
  relationship_id_value := (p_total_field #>> '{settings,relationshipId}')::uuid;

  select item.value into relationship_value
  from pg_catalog.jsonb_array_elements(p_relationships) as item(value)
  where pg_catalog.lower(item.value ->> 'relationshipId') =
      pg_catalog.lower(relationship_id_value::text)
    and vortex_record.relationship_declares_target_internal(
      item.value, p_target_record_type_id
    );
  if relationship_value is null
    or not pg_catalog.pg_input_is_valid(
      relationship_value ->> 'fromRecordTypeId', 'uuid'
    ) then
    return null;
  end if;
  source_type_id := (relationship_value ->> 'fromRecordTypeId')::uuid;
  select item.value into source_type_value
  from pg_catalog.jsonb_array_elements(p_record_types) as item(value)
  where pg_catalog.lower(item.value ->> 'recordTypeId') =
    pg_catalog.lower(source_type_id::text);
  if source_type_value is null
    or not pg_catalog.pg_input_is_valid(
      source_type_value ->> 'storageContractId', 'uuid'
    )
    or source_type_value ->> 'storageScope' not in (
      'organization_shared', 'application_contained'
    ) then
    return null;
  end if;

  if p_total_field #>> '{settings,operation}' <> 'count' then
    source_field_id := p_total_field #>> '{settings,fieldId}';
    if not pg_catalog.pg_input_is_valid(source_field_id, 'uuid') then
      return null;
    end if;
    source_ids := source_ids || pg_catalog.jsonb_build_array(
      pg_catalog.lower(source_field_id)
    );
  end if;

  -- Condition leaves are field operands.  The compiler has already validated
  -- their shape; repeat only the exact extraction here so malformed facts
  -- cannot widen a projection.
  source_ids := source_ids || coalesce((
    with recursive nodes(value) as (
      select p_total_field -> 'settings' -> 'filter'
      union all
      select child.value
      from nodes
      cross join lateral (
        select entry.value from pg_catalog.jsonb_each(nodes.value) as entry(key, value)
        where pg_catalog.jsonb_typeof(nodes.value) = 'object'
        union all
        select entry.value from pg_catalog.jsonb_array_elements(nodes.value) as entry(value)
        where pg_catalog.jsonb_typeof(nodes.value) = 'array'
      ) as child
      where nodes.value is not null
    )
    select pg_catalog.jsonb_agg(pg_catalog.lower(value ->> 'fieldId') order by pg_catalog.lower(value ->> 'fieldId'))
    from nodes
    where value ->> 'source' = 'field'
      and pg_catalog.pg_input_is_valid(value ->> 'fieldId', 'uuid')
  ), '[]'::jsonb);

  return pg_catalog.jsonb_build_object(
    'relationshipId', relationship_id_value,
    'sourceRecordTypeId', source_type_id,
    'sourceStorageContractId', source_type_value -> 'storageContractId',
    'sourceStorageScope', source_type_value -> 'storageScope',
    'sourceFieldIds', coalesce((
      select pg_catalog.jsonb_agg(distinct entry.value order by entry.value)
      from pg_catalog.jsonb_array_elements_text(source_ids) as entry(value)
    ), '[]'::jsonb)
  );
end
$function$;


ALTER FUNCTION vortex_record.total_dependency_contract_internal(p_record_types jsonb, p_relationships jsonb, p_target_record_type_id uuid, p_total_field jsonb) OWNER TO vortex_record_adapter;

--
-- Name: total_inputs_readable_internal(jsonb, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.total_inputs_readable_internal(
  p_loaded jsonb,
  p_target_record_type_id uuid,
  p_target_record_id uuid,
  p_total_field jsonb,
  p_seen_derived_field_keys jsonb
)
returns boolean
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  contract_value jsonb;
  source_projection jsonb;
  edge_row vortex_record.relationship_edges%rowtype;
  required_field_id text;
begin
  contract_value := vortex_record.total_dependency_contract_internal(
    p_loaded -> 'facts' -> 'recordTypes', p_loaded -> 'facts' -> 'relationships',
    p_target_record_type_id, p_total_field
  );
  if contract_value is null
    or pg_catalog.jsonb_typeof(p_seen_derived_field_keys) <> 'array' then
    return false;
  end if;
  for edge_row in
    select edge.* from vortex_record.relationship_edges as edge
    where edge.relationship_id = (contract_value ->> 'relationshipId')::uuid
      and edge.from_storage_contract_id =
        (contract_value ->> 'sourceStorageContractId')::uuid
      and edge.to_storage_contract_id =
        (p_loaded -> 'facts' -> 'binding' ->> 'storageContractId')::uuid
      and edge.to_record_id = p_target_record_id
      and edge.to_organisation_id = (p_loaded -> 'context' ->> 'organizationId')::uuid
      and edge.from_application_root_id is not distinct from case
        when contract_value ->> 'sourceStorageScope' = 'application_contained'
          then (p_loaded -> 'context' ->> 'applicationRootId')::uuid
        else null end
      and edge.to_application_root_id is not distinct from case
        when p_loaded -> 'facts' -> 'binding' ->> 'storageScope' = 'application_contained'
          then (p_loaded -> 'context' ->> 'applicationRootId')::uuid
        else null end
  loop
    source_projection := vortex_record.read_derived_field_ids_for_exact_record_internal(
      (contract_value ->> 'sourceRecordTypeId')::uuid,
      edge_row.from_record_id,
      contract_value -> 'sourceFieldIds',
      p_seen_derived_field_keys
    );
    if source_projection is null then
      if vortex_record.relationship_total_source_is_retained_internal(
        p_loaded -> 'facts',
        (contract_value ->> 'sourceRecordTypeId')::uuid,
        edge_row.from_record_id,
        (p_loaded -> 'context' ->> 'organizationId')::uuid,
        (p_loaded -> 'context' ->> 'applicationRootId')::uuid
      ) then
        continue;
      end if;
      return false;
    end if;
    for required_field_id in
      select item.value from pg_catalog.jsonb_array_elements_text(
        contract_value -> 'sourceFieldIds'
      ) as item(value)
    loop
      if not (source_projection ? required_field_id) then
        return false;
      end if;
    end loop;
  end loop;
  return true;
end
$function$;


ALTER FUNCTION vortex_record.total_inputs_readable_internal(p_loaded jsonb, p_target_record_type_id uuid, p_target_record_id uuid, p_total_field jsonb, p_seen_derived_field_keys jsonb) OWNER TO vortex_record_adapter;

--
-- Name: transfer_offboarding_active_owned_record(uuid, uuid, uuid, bigint, text, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.transfer_offboarding_active_owned_record(
  p_command_id uuid,
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint,
  p_target_kind text,
  p_target_id uuid,
  p_activity_id uuid,
  p_occurrence_id uuid,
  p_expected_access_version bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
begin
  select authorized.* into strict scope
  from vortex_access.organization_accounts_offboarding_inventory_scope_internal() as authorized;
  if p_expected_access_version is null
    or scope.access_version is distinct from p_expected_access_version then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'access_changed');
  end if;

  begin
    return vortex_record.apply_lifecycle_record_changes_internal(
      'transfer_ownership',
      p_command_id,
      p_record_type_id,
      p_record_id,
      p_expected_concurrency_number,
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'kind', 'transfer_ownership',
        'targetKind', p_target_kind,
        'targetId', p_target_id
      )),
      p_activity_id,
      p_occurrence_id
    );
  exception
    when serialization_failure then
      -- Identical per-record boundary to the retained entry: a contested final
      -- update rolls back its own pending receipt and is reported as a
      -- conflict, so one contested record never fails the whole batch.
      return pg_catalog.jsonb_build_object('outcome', 'conflict');
  end;
end
$function$;


ALTER FUNCTION vortex_record.transfer_offboarding_active_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_expected_access_version bigint) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION transfer_offboarding_active_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_expected_access_version bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.transfer_offboarding_active_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_expected_access_version bigint) IS 'Protected request entry for one disclosed account-offboarding transfer of an ordinary active record; it rechecks accounts.manage scope and delegates all target, owner, lifecycle, authority and revision checks to the one record-change operation''s terminal ownership transfer.';


--
-- Name: transfer_offboarding_owned_record(uuid, uuid, uuid, bigint, text, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.transfer_offboarding_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid, p_expected_access_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scope record;
begin
  -- Re-admit the current accounts.manage scope for every item. The nested
  -- fixed transfer then reloads record facts, locks the target and requires the
  -- caller's expected concurrency number before it can mutate anything.
  select authorized.* into strict scope
  from vortex_access.organization_accounts_offboarding_inventory_scope_internal() as authorized;
  if p_expected_access_version is null
    or scope.access_version is distinct from p_expected_access_version then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'access_changed');
  end if;

  begin
    return vortex_record.transfer_record_ownership_for_offboarding_internal(
      p_command_id,
      p_record_type_id,
      p_record_id,
      p_expected_concurrency_number,
      p_target_kind,
      p_target_id,
      p_activity_id,
      p_occurrence_id,
      p_source_organization_account_id
    );
  exception
    when serialization_failure then
      -- A contested final update is an expected per-record result. The nested
      -- exception block rolls back its pending receipt before returning it.
      return pg_catalog.jsonb_build_object('outcome', 'conflict');
  end;
end
$$;


ALTER FUNCTION vortex_record.transfer_offboarding_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid, p_expected_access_version bigint) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION transfer_offboarding_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid, p_expected_access_version bigint); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.transfer_offboarding_owned_record(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid, p_expected_access_version bigint) IS 'Protected request entry for one disclosed account-offboarding retained or disabled-installation transfer; it rechecks accounts.manage scope and delegates all target, owner, lifecycle and revision checks to the fixed adapter-only operation.';


--
-- Name: transfer_record_ownership_for_offboarding_internal(uuid, uuid, uuid, bigint, text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.transfer_record_ownership_for_offboarding_internal(
  p_command_id uuid,
  p_record_type_id uuid,
  p_record_id uuid,
  p_expected_concurrency_number bigint,
  p_target_kind text,
  p_target_id uuid,
  p_activity_id uuid,
  p_occurrence_id uuid,
  p_source_organization_account_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb; organization_id_value uuid; application_root_id_value uuid;
  actor_id_value uuid; fingerprint text; receipt_claim jsonb;
  loaded jsonb; decision jsonb; record_fact jsonb; type_fact jsonb;
  previous_owner uuid; updated_concurrency bigint; changed_rows integer; event_result jsonb;
  evaluation_facts jsonb;
  updated_record_id uuid; updated_organization_id uuid; updated_application_root_id uuid;
  storage_scope_value text; preview_installation jsonb;
  exact_notice boolean := false; notice_sequence bigint;
  correlation_id_value uuid;
begin
  if p_command_id is null or p_record_type_id is null or p_record_id is null
    or p_expected_concurrency_number is null
    or p_expected_concurrency_number not between 1 and 9007199254740990
    or p_target_kind is distinct from 'organization_account' or p_target_id is null
    or p_activity_id is null or p_occurrence_id is null
    or p_source_organization_account_id is null
    or p_source_organization_account_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return pg_catalog.jsonb_build_object('outcome', 'refused', 'reasonCode', 'command_invalid');
  end if;
  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId' then
    raise exception using errcode = '42501', message = 'Offboarding ownership transfer requires an Application context';
  end if;
  organization_id_value := (context_value ->> 'organizationId')::uuid;
  application_root_id_value := (context_value ->> 'applicationRootId')::uuid;
  actor_id_value := (context_value ->> 'organizationAccountId')::uuid;
  correlation_id_value := (context_value ->> 'correlationId')::uuid;
  if correlation_id_value is null or not vortex_context.is_non_nil_uuid(correlation_id_value::text) then
    raise exception using errcode='42501',message='Offboarding ownership transfer authority is unavailable';
  end if;
  fingerprint := vortex_record.ownership_transfer_command_fingerprint_internal(
    p_command_id,p_record_type_id,p_record_id,p_expected_concurrency_number,p_target_kind,p_target_id,
    'offboarding',p_source_organization_account_id);
  receipt_claim := vortex_record.claim_command_receipt_internal(
    'record_save', p_command_id, 'transfer_ownership', fingerprint,
    p_record_type_id, null, '{}'::jsonb, '{}'::jsonb, false
  );
  if receipt_claim ->> 'status' is distinct from 'claimed' then
    if receipt_claim ->> 'status' = 'identity_conflict' then
      return pg_catalog.jsonb_build_object('outcome','refused','reasonCode','command_identity_conflict','correlationId',context_value -> 'correlationId');
    end if;
    if receipt_claim ->> 'status' is distinct from 'completed' then
      return pg_catalog.jsonb_build_object('outcome','conflict','correlationId',context_value -> 'correlationId');
    end if;
    return pg_catalog.jsonb_build_object('outcome','transferred','recordId',(receipt_claim ->> 'recordId')::uuid,
      'concurrencyNumber',(receipt_claim ->> 'concurrencyNumber')::bigint,'correlationId',context_value -> 'correlationId','replayed',true);
  end if;
  loaded := vortex_record.load_offboarding_ownership_transfer_facts_internal(
    p_record_type_id,p_record_id,p_expected_concurrency_number);
  if loaded ->> 'outcome' = 'conflict' then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object('outcome','conflict','concurrencyNumber',loaded -> 'concurrencyNumber','correlationId',context_value -> 'correlationId');
  end if;
  if loaded ->> 'outcome' is distinct from 'loaded'
    or pg_catalog.jsonb_typeof(loaded -> 'declaration') is distinct from 'object'
    or loaded ->> 'installationState' is null
    or loaded ->> 'installationState' not in ('active', 'detached')
    or pg_catalog.jsonb_typeof(loaded -> 'facts') is distinct from 'object'
    or pg_catalog.jsonb_typeof(loaded #> '{facts,records}') is distinct from 'array'
    or pg_catalog.jsonb_typeof(loaded #> '{facts,recordTypes}') is distinct from 'array' then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object('outcome','refused','reasonCode','record_unavailable','correlationId',context_value -> 'correlationId');
  end if;
  select item.value into record_fact from pg_catalog.jsonb_array_elements(loaded -> 'facts' -> 'records') as item(value)
  where (item.value -> 'recordScope' ->> 'recordId')::uuid = p_record_id;
  select item.value into type_fact from pg_catalog.jsonb_array_elements(loaded -> 'facts' -> 'recordTypes') as item(value)
  where (item.value ->> 'recordTypeId')::uuid = p_record_type_id;
  storage_scope_value := record_fact #>> '{recordScope,storageScope}';
  if pg_catalog.jsonb_typeof(record_fact) is distinct from 'object'
    or pg_catalog.jsonb_typeof(type_fact) is distinct from 'object'
    or record_fact ->> 'lifecycleState' is null
    or record_fact ->> 'lifecycleState' not in ('active','soft_deleted')
    or (loaded ->> 'installationState' = 'active' and record_fact ->> 'lifecycleState' is distinct from 'soft_deleted')
    or type_fact ->> 'ownershipMode' is distinct from 'organization_account'
    or storage_scope_value is null
    or storage_scope_value not in ('application_contained', 'organization_shared')
    or (record_fact #>> '{recordScope,organizationId}')::uuid is distinct from organization_id_value
    or (record_fact #>> '{recordScope,recordTypeId}')::uuid is distinct from p_record_type_id
    or (record_fact #>> '{recordScope,storageContractId}')::uuid is distinct from (type_fact ->> 'storageContractId')::uuid
    or type_fact ->> 'storageContractId' is null
    or not vortex_context.is_non_nil_uuid(type_fact ->> 'storageContractId')
    or (storage_scope_value = 'application_contained'
      and (record_fact #>> '{recordScope,applicationRootId}')::uuid is distinct from application_root_id_value)
    or (record_fact ->> 'ownerOrganizationAccountId')::uuid is distinct from p_source_organization_account_id then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object('outcome','refused','reasonCode','owner_unavailable','correlationId',context_value -> 'correlationId');
  end if;
  -- Retained rows are never restored.  The unchanged complete Access
  -- evaluator sees only this locked target as active in an in-memory facts
  -- view, preserving every existing transfer route and condition.
  evaluation_facts := loaded -> 'facts';
  if record_fact ->> 'lifecycleState' = 'soft_deleted' then
    evaluation_facts := evaluation_facts || pg_catalog.jsonb_build_object(
      'records',
      (
        select pg_catalog.jsonb_agg(
          case
            when (item.value -> 'recordScope' ->> 'recordId')::uuid = p_record_id
              then pg_catalog.jsonb_set(
                item.value, '{lifecycleState}', '"active"'::jsonb, false
              )
            else item.value
          end
          order by item.ordinal
        )
        from pg_catalog.jsonb_array_elements(evaluation_facts -> 'records')
          with ordinality as item(value, ordinal)
      )
    );
  end if;
  decision := vortex_access.evaluate_organization_record_access_internal(
    loaded -> 'declaration', p_record_id, evaluation_facts
  );
  if decision ->> 'outcome' = 'refused' then
    perform vortex_record.append_ownership_transfer_activity_internal(p_activity_id,organization_id_value,'refused');
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object('outcome','refused_recorded','reasonCode','record_unavailable','correlationId',context_value -> 'correlationId');
  elsif decision ->> 'outcome' is distinct from 'allowed' then
    raise exception using errcode='42501', message='Offboarding ownership transfer authority is unavailable';
  end if;
  if not vortex_access.lock_active_record_ownership_target_internal('organization_account',p_target_id)
    or p_target_id = p_source_organization_account_id then
    perform vortex_record.release_command_receipt_internal('record_save', p_command_id);
    return pg_catalog.jsonb_build_object('outcome','refused','reasonCode','owner_unavailable','correlationId',context_value -> 'correlationId');
  end if;
  execute pg_catalog.format(
    'update record_data.%I as stored set owner_organisation_account_id=$3,owner_group_id=null,concurrency_number=concurrency_number+1,updated_at=pg_catalog.statement_timestamp(),updated_by=$4 where stored.organisation_id=$1 and stored.record_id=$2 and stored.concurrency_number=$5 returning stored.record_id,stored.concurrency_number,stored.organisation_id,%s',
    loaded ->> 'table',
    case when storage_scope_value = 'application_contained'
      then 'stored.application_root_id' else 'null::uuid' end
  ) into updated_record_id,updated_concurrency,updated_organization_id,updated_application_root_id
    using organization_id_value,p_record_id,p_target_id,actor_id_value,p_expected_concurrency_number;
  get diagnostics changed_rows = row_count;
  if changed_rows <> 1 then raise exception using errcode='40001',message='Offboarding ownership transfer revision changed'; end if;
  if updated_record_id is distinct from p_record_id
    or not vortex_context.is_non_nil_uuid(updated_record_id::text)
    or updated_organization_id is distinct from organization_id_value
    or updated_concurrency is null
    or updated_concurrency not between 1 and 9007199254740991
    or (storage_scope_value = 'application_contained'
      and updated_application_root_id is distinct from application_root_id_value) then
    raise exception using errcode='40001',message='Offboarding ownership transfer revision changed';
  end if;
  preview_installation := vortex_record.read_current_preview_installation_internal();
  if preview_installation ->> 'outcome' = 'refused' then
    raise exception using errcode='42501',message='Preview Record context is unavailable';
  end if;
  exact_notice := preview_installation is null
    and loaded ->> 'installationState' = 'active'
    and storage_scope_value = 'application_contained';
  if exact_notice then
    -- Defer the exact notice until the protected transfer is complete.
    null;
  else
    perform vortex_record.bump_record_data_version_internal(
      organization_id_value, (type_fact ->> 'storageContractId')::uuid,
      case when storage_scope_value = 'application_contained'
        then application_root_id_value else null end
    );
  end if;
  perform vortex_record.append_ownership_transfer_activity_internal(p_activity_id,p_record_id,'completed');
  if loaded ->> 'installationState' = 'detached' then
    event_result := vortex_event.append_detached_offboarding_reassignment_internal(
      (type_fact ->> 'storageContractId')::uuid, p_record_id, p_record_type_id, p_occurrence_id
    );
  else
    event_result := vortex_event.append_record_occurrences(
      (type_fact ->> 'storageContractId')::uuid, p_record_id,
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'occurrenceId',p_occurrence_id,
        'descriptor',pg_catalog.jsonb_build_object(
          'kind','standard','eventKind','reassigned','recordTypeId',p_record_type_id
        ),
        'payload',pg_catalog.jsonb_build_object('kind','reassigned')
      ))
    );
  end if;
  if pg_catalog.jsonb_typeof(event_result) is distinct from 'array' then
    raise exception using errcode='55000',message='Offboarding ownership transfer Event append failed';
  end if;
  if pg_catalog.jsonb_array_length(event_result) <> 1 then raise exception using errcode='55000',message='Offboarding ownership transfer Event append failed'; end if;
  perform vortex_record.complete_command_receipt_internal(
    'record_save', p_command_id, updated_record_id, updated_concurrency,
    'Offboarding ownership transfer receipt is stale'
  );
  if exact_notice then
    begin
      notice_sequence := pg_catalog.nextval(
        'vortex_record.record_invalidation_sequence'::pg_catalog.regclass
      );
      if notice_sequence is null or notice_sequence not between 1 and 9007199254740991 then
        raise exception using errcode='22023',message='Invalidation notice command is invalid';
      end if;
      perform vortex_invalidation.publish_change_notice(
        updated_organization_id, updated_application_root_id, p_record_type_id,
        updated_record_id, updated_concurrency, 'changed',
        notice_sequence, notice_sequence, correlation_id_value
      );
    exception when others then
      -- Notice allocation and publication are advisory after the protected transfer is complete.
      null;
    end;
  end if;
  return pg_catalog.jsonb_build_object('outcome','transferred','recordId',updated_record_id,
    'concurrencyNumber',updated_concurrency,'correlationId',context_value -> 'correlationId','replayed',false);
end
$function$;


ALTER FUNCTION vortex_record.transfer_record_ownership_for_offboarding_internal(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid) OWNER TO vortex_record_adapter;

--
-- Name: FUNCTION transfer_record_ownership_for_offboarding_internal(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid); Type: COMMENT; Schema: vortex_record; Owner: vortex_record_adapter
--

COMMENT ON FUNCTION vortex_record.transfer_record_ownership_for_offboarding_internal(p_command_id uuid, p_record_type_id uuid, p_record_id uuid, p_expected_concurrency_number bigint, p_target_kind text, p_target_id uuid, p_activity_id uuid, p_occurrence_id uuid, p_source_organization_account_id uuid) IS 'Private offboarding single-record ownership transfer: the public transfer contract, with the command receipt, Activity and Event, for a named source owner.';


--
-- Name: validate_named_action_reference_inputs(text, uuid, bigint, uuid, uuid, jsonb); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

CREATE FUNCTION vortex_record.validate_named_action_reference_inputs(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid, p_inputs jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  context_value jsonb;
  action_context jsonb;
  input_definition jsonb;
  input_candidate jsonb;
  catalogue jsonb;
  reference_record_type_id uuid;
  reference_record_id uuid;
  resolved_target_count integer;
begin
  if pg_catalog.jsonb_typeof(p_inputs) is distinct from 'object' then
    return false;
  end if;
  context_value := vortex_access.validated_human_request_context();
  action_context := vortex_record.resolve_named_action_context_internal(
    p_action_owner_kind, p_action_owner_id, p_action_release_revision,
    p_action_id, p_record_type_id
  );
  for input_definition in
    select item.value
    from pg_catalog.jsonb_array_elements(action_context -> 'action' -> 'inputs') item(value)
    where item.value ->> 'type' in (
      'organization_account_reference', 'record_reference'
    )
  loop
    if not p_inputs ? (input_definition ->> 'key') then
      continue;
    end if;
    input_candidate := p_inputs -> (input_definition ->> 'key');
    if input_definition ->> 'type' = 'organization_account_reference' then
      if pg_catalog.jsonb_typeof(input_candidate) is distinct from 'string'
        or not pg_catalog.pg_input_is_valid(input_candidate #>> '{}', 'uuid')
        or not vortex_identity.is_active_organization_account_reference_internal(
          (context_value ->> 'tenantId')::uuid,
          (context_value ->> 'organizationId')::uuid,
          (input_candidate #>> '{}')::uuid
        ) then
        return false;
      end if;
      continue;
    end if;

    reference_record_type_id := null;
    reference_record_id := null;
    if pg_catalog.jsonb_typeof(input_candidate) = 'object'
      and input_candidate ?& array['recordTypeId', 'recordId']
      and input_candidate - array['recordTypeId', 'recordId'] = '{}'::jsonb
      and pg_catalog.pg_input_is_valid(input_candidate ->> 'recordTypeId', 'uuid')
      and pg_catalog.pg_input_is_valid(input_candidate ->> 'recordId', 'uuid') then
      reference_record_type_id := (input_candidate ->> 'recordTypeId')::uuid;
      reference_record_id := (input_candidate ->> 'recordId')::uuid;
    elsif pg_catalog.jsonb_typeof(input_candidate) = 'string'
      and pg_catalog.pg_input_is_valid(input_candidate #>> '{}', 'uuid') then
      select pg_catalog.count(*),
        (pg_catalog.array_agg(
          (target.value ->> 'recordTypeId')::uuid
          order by (target.value ->> 'recordTypeId')::uuid
        ))[1]
      into resolved_target_count, reference_record_type_id
      from pg_catalog.jsonb_array_elements(input_definition -> 'recordTypes') target(value)
      where target.value ->> 'state' = 'resolved';
      if resolved_target_count = 1 then
        reference_record_id := (input_candidate #>> '{}')::uuid;
      end if;
    end if;
    if reference_record_type_id is null or reference_record_id is null
      or not exists (
        select 1
        from pg_catalog.jsonb_array_elements(input_definition -> 'recordTypes') target(value)
        where target.value ->> 'state' = 'resolved'
          and (target.value ->> 'recordTypeId')::uuid = reference_record_type_id
      ) then
      return false;
    end if;
    catalogue := coalesce(catalogue,
      vortex_record.relationship_total_catalogue_internal());
    if vortex_record.relationship_total_record_snapshot_internal(
      catalogue, reference_record_type_id, reference_record_id, false
    ) is null then
      return false;
    end if;
  end loop;
  return true;
exception
  when no_data_found or too_many_rows or invalid_text_representation
    or insufficient_privilege or object_not_in_prerequisite_state
    or check_violation then
    return false;
end
$$;


ALTER FUNCTION vortex_record.validate_named_action_reference_inputs(p_action_owner_kind text, p_action_owner_id uuid, p_action_release_revision bigint, p_action_id uuid, p_record_type_id uuid, p_inputs jsonb) OWNER TO vortex_record_adapter;

--
-- Name: write_named_action_relationship_value_internal(uuid, uuid, uuid, jsonb, text, uuid, bigint, uuid, uuid, uuid); Type: FUNCTION; Schema: vortex_record; Owner: vortex_record_adapter
--

create or replace function vortex_record.write_named_action_relationship_value_internal(
  p_source_record_type_id uuid,
  p_source_record_id uuid,
  p_relationship_id uuid,
  p_target_value jsonb,
  p_action_owner_kind text,
  p_action_owner_id uuid,
  p_action_release_revision bigint,
  p_action_id uuid,
  p_subject_record_type_id uuid,
  p_subject_record_id uuid
)
returns void
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
declare
  source_meta jsonb;
  source_context jsonb;
  source_type jsonb;
  relationship_value jsonb;
  field_value jsonb;
  field_column jsonb;
  target_type_id uuid;
  target_record_id uuid;
  target_meta jsonb;
  target_loaded jsonb;
  target_decision jsonb;
  target_record jsonb;
  target_scope jsonb;
  source_application_root_id uuid;
  target_application_root_id uuid;
  mapping_row vortex_record.relationship_storage_mappings%rowtype;
  application_root_required boolean;
  existing_other boolean;
  update_sql text;
  changed_rows integer;
begin
  if p_source_record_type_id is null or p_source_record_id is null
    or p_relationship_id is null
    or p_action_owner_kind not in ('application', 'module')
    or p_action_owner_id is null or p_action_id is null
    or p_action_release_revision not between 1 and 9007199254740991
    or p_subject_record_type_id is null or p_subject_record_id is null then
    raise exception using errcode = '22023', message = 'Relationship change is invalid';
  end if;
  source_meta := vortex_record.resolve_record_action_context_internal(
    p_source_record_type_id, 'read'
  );
  source_context := source_meta -> 'context';
  source_type := source_meta -> 'recordType';
  select item.value into relationship_value
  from pg_catalog.jsonb_array_elements(source_type -> 'relationships') as item(value)
  where (item.value ->> 'relationshipId')::uuid = p_relationship_id;
  if not found then
    raise exception using errcode = '23514',
      message = 'Relationship is not declared by the active record type';
  end if;
  select item.value into field_value
  from pg_catalog.jsonb_array_elements(source_type -> 'fields') as item(value)
  where (item.value ->> 'fieldId')::uuid = (relationship_value ->> 'fromFieldId')::uuid;
  if not found or field_value ->> 'type' not in ('link', 'link_to_one_of_several') then
    raise exception using errcode = '55000',
      message = 'Relationship field definition is unavailable';
  end if;
  field_column := source_meta -> 'columns' -> pg_catalog.lower(field_value ->> 'fieldId');

  select mapping.* into mapping_row
  from vortex_record.relationship_storage_mappings as mapping
  where mapping.relationship_id = p_relationship_id
    and mapping.source_storage_contract_id = (source_meta ->> 'storageContractId')::uuid
    and mapping.source_field_id = (field_value ->> 'fieldId')::uuid
    and mapping.release_revision <= (source_meta ->> 'moduleReleaseRevision')::bigint;
  if not found
    or mapping_row.cardinality is distinct from (relationship_value ->> 'cardinality')
    or mapping_row.on_parent_delete is distinct from (relationship_value ->> 'onParentDelete') then
    raise exception using errcode = '55000',
      message = 'Relationship storage disagrees with the active definition';
  end if;

  if pg_catalog.jsonb_typeof(p_target_value) = 'null' then
    if (field_value ->> 'required')::boolean then
      raise exception using errcode = '23514', message = 'Required relationship cannot be empty';
    end if;
    perform vortex_record.acquire_relationship_edge_locks_internal(
      vortex_record.relationship_edge_lock_identities_internal(
        p_relationship_id, (source_meta ->> 'storageContractId')::uuid,
        p_source_record_id, null, null
      )
    );
    delete from vortex_record.relationship_edges as edge
    where edge.relationship_id = p_relationship_id
      and edge.from_organisation_id = (source_context ->> 'organizationId')::uuid
      and edge.from_storage_contract_id = (source_meta ->> 'storageContractId')::uuid
      and edge.from_record_id = p_source_record_id;
    update_sql := pg_catalog.format(
      'update record_data.%I as stored set %I = null
       where stored.organisation_id = $1 and stored.record_id = $2',
      source_meta ->> 'table', field_column ->> 'token'
    );
    execute update_sql using (source_context ->> 'organizationId')::uuid, p_source_record_id;
    get diagnostics changed_rows = row_count;
    if changed_rows <> 1 then
      raise exception using errcode = '40001', message = 'Relationship source record changed';
    end if;
    return;
  end if;

  if pg_catalog.jsonb_typeof(p_target_value) <> 'object'
    or not (p_target_value ?& array['recordTypeId', 'recordId'])
    or p_target_value - array['recordTypeId', 'recordId'] <> '{}'::jsonb then
    raise exception using errcode = '22023', message = 'Relationship target is invalid';
  end if;
  begin
    target_type_id := (p_target_value ->> 'recordTypeId')::uuid;
    target_record_id := (p_target_value ->> 'recordId')::uuid;
  exception when invalid_text_representation then
    raise exception using errcode = '22023', message = 'Relationship target is invalid';
  end;
  if target_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or target_record_id = '00000000-0000-0000-0000-000000000000'::uuid
    or target_type_id <> all (mapping_row.target_record_type_ids) then
    raise exception using errcode = '23514', message = 'Relationship target is unavailable';
  end if;

  target_meta := vortex_record.resolve_record_action_context_internal(target_type_id, 'read');
  source_application_root_id := case when source_meta ->> 'storageScope' = 'application_contained'
    then (source_context ->> 'applicationRootId')::uuid else null end;
  application_root_required := coalesce(
    (field_value #>> '{settings,applicationRootIdRequired}')::boolean, false
  );
  if application_root_required
    and (target_meta #>> '{recordType,systemProjection,protectedView}')
      is distinct from 'organization_accounts' then
    raise exception using errcode = 'P0002', message = 'Relationship target is unavailable';
  end if;

  perform vortex_record.lock_relationship_target_row_internal(
    target_type_id, target_record_id,
    (source_context ->> 'organizationId')::uuid
  );

  -- The one substitution. Executing a permitted named action must not require
  -- ordinary read authority on its own subject (#50 section 4), so when the
  -- selected target is exactly this command's subject the decision is taken on
  -- the installed named declaration instead. The loader re-resolves the active
  -- installation, the owner kind/id/release revision, the action id and the
  -- action's declared subject record type, and the Access evaluation binds the
  -- organization, application, record type, record and the actor's current
  -- authority. Every other target keeps the ordinary read check unchanged.
  if target_type_id = p_subject_record_type_id and target_record_id = p_subject_record_id then
    target_loaded := vortex_record.load_named_action_facts_internal(
      p_action_owner_kind, p_action_owner_id, p_action_release_revision,
      p_action_id, target_type_id, target_record_id, null
    );
  else
    target_loaded := vortex_record.load_record_access_facts_internal(
      target_type_id, 'read', target_record_id, null
    );
  end if;
  if target_loaded ->> 'outcome' <> 'loaded'
    or pg_catalog.jsonb_typeof(target_loaded -> 'declaration') <> 'object' then
    raise exception using errcode = 'P0002', message = 'Relationship target is unavailable';
  end if;
  target_decision := vortex_access.evaluate_organization_record_access_internal(
    target_loaded -> 'declaration', target_record_id, target_loaded -> 'facts'
  );
  if target_decision ->> 'outcome' <> 'allowed' then
    raise exception using errcode = 'P0002', message = 'Relationship target is unavailable';
  end if;
  select item.value into target_record
  from pg_catalog.jsonb_array_elements(target_loaded -> 'facts' -> 'records') as item(value)
  where (item.value -> 'recordScope' ->> 'recordId')::uuid = target_record_id;
  target_scope := target_record -> 'recordScope';
  target_application_root_id := case when target_meta ->> 'storageScope' = 'application_contained'
    then (target_scope ->> 'applicationRootId')::uuid else null end;
  if target_record is null or target_record ->> 'lifecycleState' <> 'active'
    or (target_scope ->> 'organizationId')::uuid <>
      (source_context ->> 'organizationId')::uuid
    or (source_application_root_id is not null and target_application_root_id is not null
      and source_application_root_id <> target_application_root_id) then
    raise exception using errcode = 'P0002', message = 'Relationship target is unavailable';
  end if;
  if application_root_required
    and not vortex_access.organization_account_has_current_application_access_internal(
      (source_context ->> 'organizationId')::uuid,
      target_record_id,
      (source_context ->> 'applicationRootId')::uuid
    ) then
    raise exception using errcode = 'P0002', message = 'Relationship target is unavailable';
  end if;

  -- The target row is share-locked (the command preflight already holds every
  -- link target) and eligible; the shared edge identities are taken last,
  -- exactly as `write_relationship_value_internal` takes them.
  perform vortex_record.acquire_relationship_edge_locks_internal(
    vortex_record.relationship_edge_lock_identities_internal(
      p_relationship_id, (source_meta ->> 'storageContractId')::uuid,
      p_source_record_id, (target_meta ->> 'storageContractId')::uuid,
      target_record_id
    )
  );
  if mapping_row.cardinality = 'one_to_one' then
    select exists (
      select 1 from vortex_record.relationship_edges as edge
      where edge.relationship_id = p_relationship_id
        and edge.to_organisation_id = (source_context ->> 'organizationId')::uuid
        and edge.to_storage_contract_id = (target_meta ->> 'storageContractId')::uuid
        and edge.to_record_id = target_record_id
        and edge.from_record_id <> p_source_record_id
    ) into existing_other;
    if existing_other then
      raise exception using errcode = '23514', message = 'Relationship cardinality is exceeded';
    end if;
  end if;

  delete from vortex_record.relationship_edges as edge
  where edge.relationship_id = p_relationship_id
    and edge.from_organisation_id = (source_context ->> 'organizationId')::uuid
    and edge.from_storage_contract_id = (source_meta ->> 'storageContractId')::uuid
    and edge.from_record_id = p_source_record_id;
  insert into vortex_record.relationship_edges (
    relationship_id, from_organisation_id, to_organisation_id,
    from_application_root_id, to_application_root_id,
    from_storage_contract_id, from_record_id, to_storage_contract_id, to_record_id
  ) values (
    p_relationship_id,
    (source_context ->> 'organizationId')::uuid,
    (source_context ->> 'organizationId')::uuid,
    source_application_root_id, target_application_root_id,
    (source_meta ->> 'storageContractId')::uuid, p_source_record_id,
    (target_meta ->> 'storageContractId')::uuid, target_record_id
  );

  update_sql := pg_catalog.format(
    'update record_data.%I as stored set %I = $3::jsonb
     where stored.organisation_id = $1 and stored.record_id = $2',
    source_meta ->> 'table', field_column ->> 'token'
  );
  execute update_sql using (source_context ->> 'organizationId')::uuid,
    p_source_record_id, p_target_value;
  get diagnostics changed_rows = row_count;
  if changed_rows <> 1 then
    raise exception using errcode = '40001', message = 'Relationship source record changed';
  end if;
end
$function$;


