--
-- Name: FUNCTION consume_flow_continuation(p_token_hash text, p_organization_id uuid, p_identity_id uuid, p_flow_id uuid, p_release_key text); Type: COMMENT; Schema: vortex_workflow; Owner: vortex_workflow_owner
--

COMMENT ON FUNCTION vortex_workflow.consume_flow_continuation(p_token_hash text, p_organization_id uuid, p_identity_id uuid, p_flow_id uuid, p_release_key text) IS 'Private flow-continuation consume: returns the stored run state once, and only to the exact initiator, organisation and flow release it was issued for while it has not expired; every other case is one neutral unavailable result.';


--
-- Name: flow_registrations; Type: TABLE; Schema: vortex_workflow; Owner: postgres
--

CREATE TABLE vortex_workflow.flow_registrations (
    environment text NOT NULL,
    organization_id uuid NOT NULL,
    application_root_id uuid NOT NULL,
    application_version text NOT NULL,
    installation_revision bigint NOT NULL,
    workflow_revision bigint NOT NULL,
    namespace text NOT NULL,
    flow_id text NOT NULL,
    candidate_fingerprint text NOT NULL,
    status text DEFAULT 'inactive'::text NOT NULL,
    registered_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    CONSTRAINT flow_registrations_application_version_valid CHECK ((application_version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'::text)),
    CONSTRAINT flow_registrations_environment_valid CHECK ((environment = ANY (ARRAY['local'::text, 'testing'::text, 'production'::text]))),
    CONSTRAINT flow_registrations_fingerprint_valid CHECK ((candidate_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT flow_registrations_flow_id_valid CHECK (((char_length(flow_id) >= 1) AND (char_length(flow_id) <= 100))),
    CONSTRAINT flow_registrations_ids_non_nil CHECK ((vortex_context.is_non_nil_uuid((organization_id)::text) AND vortex_context.is_non_nil_uuid((application_root_id)::text))),
    CONSTRAINT flow_registrations_namespace_valid CHECK (((char_length(namespace) >= 1) AND (char_length(namespace) <= 150))),
    CONSTRAINT flow_registrations_registered_at_valid CHECK ((registered_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone]))),
    CONSTRAINT flow_registrations_revisions_valid CHECK ((((installation_revision >= 1) AND (installation_revision <= '9007199254740991'::bigint)) AND ((workflow_revision >= 1) AND (workflow_revision <= '9007199254740991'::bigint)))),
    CONSTRAINT flow_registrations_status_inactive CHECK ((status = 'inactive'::text))
);

ALTER TABLE ONLY vortex_workflow.flow_registrations FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_workflow.flow_registrations OWNER TO postgres;

--
-- Name: TABLE flow_registrations; Type: COMMENT; Schema: vortex_workflow; Owner: postgres
--

COMMENT ON TABLE vortex_workflow.flow_registrations IS 'Protected mapping from one exact installation and release identity to the generated inactive Kestra flow candidate: namespace, flow id and candidate fingerprint. Rows are inactive and are written only by the protected register function.';


