-- Name: flow_registration_to_json_internal(vortex_workflow.flow_registrations); Type: FUNCTION; Schema: vortex_workflow; Owner: postgres
--

CREATE FUNCTION vortex_workflow.flow_registration_to_json_internal(r vortex_workflow.flow_registrations) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'environment', r.environment,
    'organizationId', r.organization_id,
    'applicationRootId', r.application_root_id,
    'applicationVersion', r.application_version,
    'installationRevision', r.installation_revision,
    'workflowRevision', r.workflow_revision,
    'namespace', r.namespace,
    'flowId', r.flow_id,
    'candidateFingerprint', r.candidate_fingerprint,
    'status', r.status,
    'registeredAt', pg_catalog.to_char(r.registered_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  )
$$;


