--
-- Name: issue_flow_continuation(text, uuid, uuid, uuid, uuid, text, jsonb, integer, integer); Type: FUNCTION; Schema: vortex_workflow; Owner: vortex_workflow_owner
--

create or replace function vortex_workflow.issue_flow_continuation(
  p_token_hash text,
  p_run_id uuid,
  p_organization_id uuid,
  p_identity_id uuid,
  p_flow_id uuid,
  p_release_key text,
  p_state jsonb,
  p_elapsed_milliseconds integer,
  p_lifetime_seconds integer
)
returns timestamptz
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expiry timestamptz;
begin
  if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$'
    or not vortex_context.is_non_nil_uuid(p_run_id::text)
    or not vortex_context.is_non_nil_uuid(p_organization_id::text)
    or not vortex_context.is_non_nil_uuid(p_identity_id::text)
    or not vortex_context.is_non_nil_uuid(p_flow_id::text)
    or p_release_key is null
    or pg_catalog.length(p_release_key) not between 1 and 200
    or p_state is null
    or pg_catalog.jsonb_typeof(p_state) <> 'object'
    or pg_catalog.pg_column_size(p_state) > 262144
    or p_elapsed_milliseconds is null
    or p_elapsed_milliseconds not between 0 and 3600000
    or p_lifetime_seconds is null
    or p_lifetime_seconds not between 60 and 3600 then
    raise exception using errcode = '22023', message = 'Flow continuation is invalid';
  end if;

  -- Expired continuations are useless; remove a bounded few on every issue so the table never
  -- needs a separate sweeper.
  delete from vortex_workflow.flow_continuations as stale
  where stale.ctid in (
    select candidate.ctid
    from vortex_workflow.flow_continuations as candidate
    where candidate.expires_at < pg_catalog.statement_timestamp() - interval '1 day'
    limit 100
  );

  expiry := pg_catalog.statement_timestamp() + pg_catalog.make_interval(secs => p_lifetime_seconds);

  insert into vortex_workflow.flow_continuations (
    token_hash, run_id, organization_id, identity_id, flow_id, release_key, state,
    elapsed_milliseconds, created_at, expires_at
  ) values (
    p_token_hash, p_run_id, p_organization_id, p_identity_id, p_flow_id, p_release_key, p_state,
    p_elapsed_milliseconds, pg_catalog.statement_timestamp(), expiry
  );

  return expiry;
end
$function$;


ALTER FUNCTION vortex_workflow.issue_flow_continuation(p_token_hash text, p_run_id uuid, p_organization_id uuid, p_identity_id uuid, p_flow_id uuid, p_release_key text, p_state jsonb, p_elapsed_milliseconds integer, p_lifetime_seconds integer) OWNER TO vortex_workflow_owner;

--
-- Name: FUNCTION issue_flow_continuation(p_token_hash text, p_run_id uuid, p_organization_id uuid, p_identity_id uuid, p_flow_id uuid, p_release_key text, p_state jsonb, p_elapsed_milliseconds integer, p_lifetime_seconds integer); Type: COMMENT; Schema: vortex_workflow; Owner: vortex_workflow_owner
--

COMMENT ON FUNCTION vortex_workflow.issue_flow_continuation(p_token_hash text, p_run_id uuid, p_organization_id uuid, p_identity_id uuid, p_flow_id uuid, p_release_key text, p_state jsonb, p_elapsed_milliseconds integer, p_lifetime_seconds integer) IS 'Private flow-continuation issue: stores the suspended state of one server-driven flow run bound to its run, initiator, organisation and exact flow release, expiring, under the hash of a server-generated token.';


--
-- Name: read_committed_flow_start_intent(uuid); Type: FUNCTION; Schema: vortex_workflow; Owner: vortex_workflow_owner
--

create or replace function vortex_workflow.read_committed_flow_start_intent(
  p_intent_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  stored record;
begin
  if not vortex_context.is_non_nil_uuid(p_intent_id::text) then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  select
    intent.intent_id,
    intent.organization_id,
    intent.application_root_id,
    intent.application_release_revision,
    intent.application_release_version,
    intent.flow_owner_kind,
    intent.flow_owner_root_id,
    intent.flow_release_revision,
    intent.flow_release_version,
    intent.flow_release_fingerprint,
    intent.flow_id,
    intent.source_kind,
    intent.source_id,
    intent.trigger_type,
    intent.trigger_id,
    intent.inputs,
    intent.trigger_values,
    intent.caller,
    intent.status,
    intent.accepted_at
  into stored
  from vortex_workflow.flow_start_intents as intent
  where intent.intent_id = p_intent_id
    and intent.status = 'pending';

  if not found then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  if stored.source_kind <> 'event'
    or stored.trigger_type <> 'Event'
    or stored.caller ->> 'kind' is distinct from 'event'
    or stored.caller ->> 'correlationId' is null
    or not vortex_context.is_non_nil_uuid(stored.caller ->> 'correlationId') then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  return pg_catalog.jsonb_build_object(
    'kind', 'available',
    'intent', pg_catalog.jsonb_build_object(
      'intentId', stored.intent_id,
      'organizationId', stored.organization_id,
      'applicationRootId', stored.application_root_id,
      'applicationReleaseRevision', stored.application_release_revision,
      'applicationReleaseVersion', stored.application_release_version,
      'flowRelease', pg_catalog.jsonb_build_object(
        'ownerKind', stored.flow_owner_kind,
        'rootId', stored.flow_owner_root_id,
        'revision', stored.flow_release_revision,
        'version', stored.flow_release_version,
        'fingerprint', stored.flow_release_fingerprint
      ),
      'flowId', stored.flow_id,
      'origin', 'event',
      'originId', stored.source_id,
      'trigger', pg_catalog.jsonb_build_object(
        'type', 'Event',
        'id', stored.trigger_id
      ),
      'inputs', stored.inputs,
      'triggerValues', stored.trigger_values,
      'correlationId', stored.caller ->> 'correlationId',
      'acceptedAt', stored.accepted_at
    )
  );
end
$function$;


ALTER FUNCTION vortex_workflow.read_committed_flow_start_intent(p_intent_id uuid) OWNER TO vortex_workflow_owner;

--
-- Name: FUNCTION read_committed_flow_start_intent(p_intent_id uuid); Type: COMMENT; Schema: vortex_workflow; Owner: vortex_workflow_owner
--

COMMENT ON FUNCTION vortex_workflow.read_committed_flow_start_intent(p_intent_id uuid) IS 'Runtime-only read of one committed pending Event start intent, including its exact accepted release and persisted origin; absent, action-based and malformed starts return one neutral unavailable result.';


--
-- Name: read_protected_node_effect(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: vortex_workflow; Owner: postgres
--

create or replace function vortex_workflow.read_protected_node_effect(
  p_run_id uuid,
  p_organization_id uuid,
  p_identity_id uuid,
  p_task_path text,
  p_iteration text,
  p_operation_key text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  existing record;
begin
  if not exists (
    select 1
    from vortex_workflow.protected_workflow_runs as stored
    where stored.run_id = p_run_id
      and stored.organization_id = p_organization_id
      and stored.identity_id = p_identity_id
      and exists (
        select 1
        from pg_catalog.jsonb_array_elements(stored.run_record -> 'nodes') as node(value)
        where pg_catalog.lower(node.value ->> 'nodeId') = pg_catalog.lower(p_task_path)
          and node.value ->> 'operationKey' = p_operation_key
      )
  ) then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  select ledger.state, ledger.outcome, ledger.outputs into existing
  from vortex_workflow.flow_effect_ledger as ledger
  where ledger.run_id = p_run_id
    and ledger.organization_id = p_organization_id
    and ledger.identity_id = p_identity_id
    and ledger.task_path = p_task_path
    and ledger.iteration = p_iteration;
  if not found then
    return pg_catalog.jsonb_build_object('kind', 'missing');
  end if;
  if existing.state = 'completed' then
    return pg_catalog.jsonb_build_object(
      'kind', 'completed',
      'outcome', existing.outcome,
      'outputs', coalesce(existing.outputs, '{}'::jsonb)
    );
  end if;
  return pg_catalog.jsonb_build_object('kind', 'in_progress');
end
$function$;


ALTER FUNCTION vortex_workflow.read_protected_node_effect(p_run_id uuid, p_organization_id uuid, p_identity_id uuid, p_task_path text, p_iteration text, p_operation_key text) OWNER TO postgres;

--
-- Name: FUNCTION read_protected_node_effect(p_run_id uuid, p_organization_id uuid, p_identity_id uuid, p_task_path text, p_iteration text, p_operation_key text); Type: COMMENT; Schema: vortex_workflow; Owner: postgres
--

COMMENT ON FUNCTION vortex_workflow.read_protected_node_effect(p_run_id uuid, p_organization_id uuid, p_identity_id uuid, p_task_path text, p_iteration text, p_operation_key text) IS 'Reads a prior protected node response only for the exact retained run and node binding; it never claims or changes an effect.';


