    CONSTRAINT application_role_template_continuities_ids_non_nil CHECK (((application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_role_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT application_role_template_continuities_revision_range CHECK ((((continuity_revision >= 1) AND (continuity_revision <= '9007199254740991'::bigint)) AND ((last_processed_registration_revision >= 1) AND (last_processed_registration_revision <= '9007199254740991'::bigint)))),
    CONSTRAINT application_role_template_continuities_state_valid CHECK ((state = ANY (ARRAY['available'::text, 'unavailable'::text])))
);

