--
-- Name: capability_limit_changes; Type: TABLE; Schema: vortex_access; Owner: postgres
--

CREATE TABLE vortex_access.capability_limit_changes (
    change_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    organization_id uuid,
    change_kind text NOT NULL,
    actor_kind text NOT NULL,
    actor_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    policy_revision bigint NOT NULL,
    assignment_id uuid,
    assignment_revision bigint,
    capability_key text NOT NULL,
    unit text NOT NULL,
    quantity_limit numeric,
    expires_at timestamp with time zone,
    source text NOT NULL,
    correlation_id uuid NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    CONSTRAINT capability_limit_changes_ids_non_nil CHECK ((vortex_context.is_non_nil_uuid((change_id)::text) AND vortex_context.is_non_nil_uuid((tenant_id)::text) AND ((organization_id IS NULL) OR vortex_context.is_non_nil_uuid((organization_id)::text)) AND vortex_context.is_non_nil_uuid((actor_id)::text) AND vortex_context.is_non_nil_uuid((policy_id)::text) AND ((assignment_id IS NULL) OR vortex_context.is_non_nil_uuid((assignment_id)::text)) AND vortex_context.is_non_nil_uuid((correlation_id)::text))),
    CONSTRAINT capability_limit_changes_kind_valid CHECK ((((change_kind = 'policy_published'::text) AND (actor_kind = 'platform_operator'::text) AND (organization_id IS NULL) AND (assignment_id IS NULL) AND (assignment_revision IS NULL) AND (quantity_limit IS NOT NULL) AND (expires_at IS NULL)) OR ((change_kind = ANY (ARRAY['ceiling_set'::text, 'ceiling_revised'::text])) AND (actor_kind = ANY (ARRAY['platform_operator'::text, 'identity'::text])) AND (organization_id IS NULL) AND (assignment_id IS NOT NULL) AND (assignment_revision IS NOT NULL) AND (quantity_limit IS NOT NULL)) OR ((change_kind = 'ceiling_revoked'::text) AND (actor_kind = ANY (ARRAY['platform_operator'::text, 'identity'::text])) AND (organization_id IS NULL) AND (assignment_id IS NOT NULL) AND (assignment_revision IS NOT NULL) AND (quantity_limit IS NULL) AND (expires_at IS NULL)) OR ((change_kind = ANY (ARRAY['allocation_set'::text, 'allocation_revised'::text])) AND (actor_kind = 'tenant_administrator'::text) AND (assignment_id IS NOT NULL) AND (assignment_revision IS NOT NULL) AND (quantity_limit IS NOT NULL)) OR ((change_kind = 'allocation_revoked'::text) AND (actor_kind = 'tenant_administrator'::text) AND (assignment_id IS NOT NULL) AND (assignment_revision IS NOT NULL) AND (quantity_limit IS NULL) AND (expires_at IS NULL)))),
    CONSTRAINT capability_limit_changes_revisions_valid CHECK ((((policy_revision >= 1) AND (policy_revision <= '9007199254740991'::bigint)) AND ((assignment_revision IS NULL) OR ((assignment_revision >= 1) AND (assignment_revision <= '9007199254740991'::bigint))))),
    CONSTRAINT capability_limit_changes_scope_valid CHECK ((vortex_access.capability_policy_key_is_valid(capability_key) AND vortex_access.capability_policy_unit_is_valid(unit) AND ((quantity_limit IS NULL) OR vortex_access.capability_policy_quantity_is_valid(quantity_limit)))),
    CONSTRAINT capability_limit_changes_source_valid CHECK ((source = ANY (ARRAY['web'::text, 'mcp'::text, 'programmatic_interface'::text, 'connection'::text, 'federation'::text, 'durable_workflow'::text, 'system'::text]))),
    CONSTRAINT capability_limit_changes_time_valid CHECK (((occurred_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND ((expires_at IS NULL) OR (expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])))))
);

ALTER TABLE ONLY vortex_access.capability_limit_changes FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_access.capability_limit_changes OWNER TO postgres;

