-- Name: TABLE capability_limit_changes; Type: COMMENT; Schema: vortex_access; Owner: postgres
--

COMMENT ON TABLE vortex_access.capability_limit_changes IS 'Append-only evidence of every capability policy publication, ceiling change and allocation change, with its actor, scope, quantity and correlation; it grants no data access.';


--
-- Name: capability_policy_assignments; Type: TABLE; Schema: vortex_access; Owner: postgres
--

CREATE TABLE vortex_access.capability_policy_assignments (
    assignment_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    organization_id uuid,
    policy_id uuid NOT NULL,
    policy_revision bigint NOT NULL,
    capability_key text NOT NULL,
    unit text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    revision bigint NOT NULL,
    assigned_at timestamp with time zone NOT NULL,
    assigned_by_actor_id uuid NOT NULL,
    assignment_correlation_id uuid NOT NULL,
    changed_at timestamp with time zone NOT NULL,
    changed_by_actor_id uuid NOT NULL,
    change_correlation_id uuid NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by_actor_id uuid,
    revocation_correlation_id uuid,
    assignment_kind text NOT NULL,
    allocated_quantity numeric,
    CONSTRAINT capability_policy_assignments_ids_non_nil CHECK ((vortex_context.is_non_nil_uuid((assignment_id)::text) AND vortex_context.is_non_nil_uuid((tenant_id)::text) AND ((organization_id IS NULL) OR vortex_context.is_non_nil_uuid((organization_id)::text)) AND vortex_context.is_non_nil_uuid((policy_id)::text) AND vortex_context.is_non_nil_uuid((assigned_by_actor_id)::text) AND vortex_context.is_non_nil_uuid((assignment_correlation_id)::text) AND vortex_context.is_non_nil_uuid((changed_by_actor_id)::text) AND vortex_context.is_non_nil_uuid((change_correlation_id)::text) AND ((revoked_by_actor_id IS NULL) OR vortex_context.is_non_nil_uuid((revoked_by_actor_id)::text)) AND ((revocation_correlation_id IS NULL) OR vortex_context.is_non_nil_uuid((revocation_correlation_id)::text)))),
    CONSTRAINT capability_policy_assignments_kind_valid CHECK ((((assignment_kind = 'ceiling'::text) AND (organization_id IS NULL) AND (allocated_quantity IS NULL)) OR ((assignment_kind = 'allocation'::text) AND (allocated_quantity IS NOT NULL) AND vortex_access.capability_policy_quantity_is_valid(allocated_quantity)))),
    CONSTRAINT capability_policy_assignments_revisions_valid CHECK ((((policy_revision >= 1) AND (policy_revision <= '9007199254740991'::bigint)) AND ((revision >= 1) AND (revision <= '9007199254740991'::bigint)))),
    CONSTRAINT capability_policy_assignments_revocation_complete CHECK ((((revoked_at IS NULL) AND (revoked_by_actor_id IS NULL) AND (revocation_correlation_id IS NULL)) OR ((revoked_at IS NOT NULL) AND (revoked_by_actor_id IS NOT NULL) AND (revocation_correlation_id IS NOT NULL) AND (revoked_at = changed_at) AND (revoked_by_actor_id = changed_by_actor_id) AND (revocation_correlation_id = change_correlation_id)))),
    CONSTRAINT capability_policy_assignments_scope_valid CHECK ((vortex_access.capability_policy_key_is_valid(capability_key) AND vortex_access.capability_policy_unit_is_valid(unit))),
    CONSTRAINT capability_policy_assignments_time_valid CHECK (((starts_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (assigned_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (changed_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND ((expires_at IS NULL) OR (expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone]))) AND ((revoked_at IS NULL) OR (revoked_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone]))) AND ((expires_at IS NULL) OR (expires_at > starts_at))))
);

ALTER TABLE ONLY vortex_access.capability_policy_assignments FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_access.capability_policy_assignments OWNER TO postgres;

