    multi_factor_authentication_expires_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    correlation_id uuid NOT NULL,
    CONSTRAINT record_share_grant_consent_decisions_decision_valid CHECK (((decision = ANY (ARRAY['consented'::text, 'refused'::text])) AND ((note IS NULL) OR (char_length(note) <= 500)))),
    CONSTRAINT record_share_grant_consent_decisions_finite_time CHECK (((multi_factor_authenticated_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (multi_factor_authentication_expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (proposal_expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (decided_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])))),
    CONSTRAINT record_share_grant_consent_decisions_ids_non_nil CHECK (((decision_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (approver_application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (correlation_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT record_share_grant_consent_decisions_mfa_valid CHECK (((multi_factor_authenticated_at <= decided_at) AND (multi_factor_authenticated_at >= (decided_at - '00:05:00'::interval)) AND (multi_factor_authentication_expires_at >= decided_at) AND (multi_factor_authentication_expires_at <= (multi_factor_authenticated_at + '00:05:00'::interval)) AND ((expires_at >= decided_at) AND (expires_at <= multi_factor_authentication_expires_at)) AND (expires_at <= proposal_expires_at) AND (proposal_expires_at > decided_at))),
    CONSTRAINT record_share_grant_consent_decisions_path_valid CHECK (((jsonb_typeof(authorization_path) = 'object'::text) AND ((authorization_path ->> 'kind'::text) = ANY (ARRAY['direct'::text, 'group'::text, 'activated_pim_direct'::text, 'activated_pim_group'::text])) AND ((authorization_path ->> 'roleId'::text) IS NOT NULL) AND ((authorization_path ->> 'roleId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND ((authorization_path ->> 'roleAssignmentId'::text) IS NOT NULL) AND ((authorization_path ->> 'roleAssignmentId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND ((authorization_path ->> 'validUntil'::text) IS NOT NULL) AND ((((authorization_path ->> 'kind'::text) = 'direct'::text) AND (NOT (authorization_path ? 'membershipId'::text)) AND (NOT (authorization_path ? 'roleActivationId'::text))) OR (((authorization_path ->> 'kind'::text) = 'group'::text) AND ((authorization_path ->> 'membershipId'::text) IS NOT NULL) AND (NOT (authorization_path ? 'roleActivationId'::text))) OR (((authorization_path ->> 'kind'::text) = 'activated_pim_direct'::text) AND (NOT (authorization_path ? 'membershipId'::text)) AND ((authorization_path ->> 'roleActivationId'::text) IS NOT NULL)) OR (((authorization_path ->> 'kind'::text) = 'activated_pim_group'::text) AND ((authorization_path ->> 'membershipId'::text) IS NOT NULL) AND ((authorization_path ->> 'roleActivationId'::text) IS NOT NULL))))),
    CONSTRAINT record_share_grant_consent_decisions_proposal_valid CHECK (((source_organization_id <> recipient_organization_id) AND ((proposal_revision >= 1) AND (proposal_revision <= '9007199254740991'::bigint)) AND (proposed_grant_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text) AND ((access_version >= 1) AND (access_version <= '9007199254740991'::bigint)))),
    CONSTRAINT record_share_grant_consent_decisions_side_valid CHECK (((side = ANY (ARRAY['source_authorization'::text, 'recipient_acceptance'::text])) AND (((side = 'source_authorization'::text) AND (approver_organization_id = source_organization_id)) OR ((side = 'recipient_acceptance'::text) AND (approver_organization_id = recipient_organization_id)))))
);

