    CONSTRAINT record_share_grants_fields_valid CHECK ((((cardinality(readable_field_ids) >= 1) AND (cardinality(readable_field_ids) <= 500)) AND (cardinality(changeable_field_ids) <= 500) AND (changeable_field_ids <@ readable_field_ids) AND ((cardinality(recipient_role_ids) >= 1) AND (cardinality(recipient_role_ids) <= 100)) AND (cardinality(allowed_action_keys) <= 100))),
