    CONSTRAINT record_share_grants_ids_non_nil CHECK (((grant_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_cluster_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (recipient_cluster_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (recipient_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (recipient_application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (module_root_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (recipient_binding_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (created_by_organization_account_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT record_share_grants_revision_range CHECK (((revision >= 1) AND (revision <= '9007199254740991'::bigint))),
    CONSTRAINT record_share_grants_revocation_shape CHECK ((((status = 'revoked'::text) = ((revoked_at IS NOT NULL) AND (revoked_by_organization_account_id IS NOT NULL) AND (revocation_reason IS NOT NULL))) AND ((revocation_reason IS NULL) OR ((char_length(revocation_reason) >= 1) AND (char_length(revocation_reason) <= 500))) AND ((revoked_at IS NULL) OR (revoked_at = changed_at)))),
    CONSTRAINT record_share_grants_scope_shape CHECK ((((scope_kind = 'module'::text) AND (record_type_id IS NULL) AND (record_id IS NULL) AND (saved_condition_id IS NULL) AND (saved_condition_revision IS NULL) AND (saved_condition_fingerprint IS NULL) AND (saved_condition_parameters IS NULL)) OR ((scope_kind = 'record_type'::text) AND (record_type_id IS NOT NULL) AND (record_id IS NULL) AND (saved_condition_id IS NULL) AND (saved_condition_revision IS NULL) AND (saved_condition_fingerprint IS NULL) AND (saved_condition_parameters IS NULL)) OR ((scope_kind = 'saved_condition'::text) AND (record_type_id IS NOT NULL) AND (record_id IS NULL) AND (saved_condition_id IS NOT NULL) AND (saved_condition_revision IS NOT NULL) AND (saved_condition_fingerprint IS NOT NULL) AND (saved_condition_parameters IS NOT NULL) AND (jsonb_typeof(saved_condition_parameters) = 'object'::text)) OR ((scope_kind = 'record'::text) AND (record_type_id IS NOT NULL) AND (record_id IS NOT NULL) AND (saved_condition_id IS NULL) AND (saved_condition_revision IS NULL) AND (saved_condition_fingerprint IS NULL) AND (saved_condition_parameters IS NULL)))),
    CONSTRAINT record_share_grants_status_proposal_only CHECK ((status = ANY (ARRAY['draft'::text, 'pending_consent'::text, 'revoked'::text]))),
    CONSTRAINT record_share_grants_window_valid CHECK (((expires_at IS NULL) OR (expires_at > starts_at)))
