    dependency_content_fingerprint text NOT NULL,
    evidence_fingerprint text NOT NULL,
    target_root_id uuid,
    target_release_revision bigint,
    catalogue_item_id uuid,
    dependency_entry jsonb,
    CONSTRAINT release_dependencies_content_fingerprint_format CHECK ((dependency_content_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT release_dependencies_entry_shape CHECK ((COALESCE(((dependency_kind = ANY (ARRAY['platform_flow'::text, 'application_flow'::text, 'application_flow_node'::text, 'application_query'::text, 'module_query'::text, 'application_form'::text, 'application_workflow'::text, 'application_action'::text, 'protected_operation'::text])) AND (jsonb_typeof(dependency_entry) = 'object'::text) AND ((dependency_entry ->> 'kind'::text) = dependency_kind) AND (dependency_reference = vortex_definition.flow_target_dependency_reference(dependency_entry)) AND (dependency_version = (dependency_entry ->> 'releaseVersion'::text)) AND (dependency_content_fingerprint = (dependency_entry ->> 'contentFingerprint'::text)) AND (evidence_fingerprint =
CASE
    WHEN (dependency_kind = 'platform_flow'::text) THEN (dependency_entry ->> 'catalogueFingerprint'::text)
    ELSE (dependency_entry ->> 'resolutionFingerprint'::text)
END)), false) OR ((dependency_kind = ANY (ARRAY['module'::text, 'connection_type'::text, 'platform_block'::text, 'platform_theme'::text])) AND (dependency_entry IS NULL)))),
    CONSTRAINT release_dependencies_evidence_fingerprint_format CHECK ((evidence_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT release_dependencies_kind_valid CHECK ((dependency_kind = ANY (ARRAY['module'::text, 'connection_type'::text, 'platform_block'::text, 'platform_theme'::text, 'platform_flow'::text, 'application_flow'::text, 'application_flow_node'::text, 'application_query'::text, 'module_query'::text, 'application_form'::text, 'application_workflow'::text, 'application_action'::text, 'protected_operation'::text]))),
    CONSTRAINT release_dependencies_reference_shape CHECK ((((dependency_kind = ANY (ARRAY['module'::text, 'connection_type'::text])) AND ((char_length(dependency_reference) >= 3) AND (char_length(dependency_reference) <= 120)) AND (dependency_reference ~ '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)+$'::text) AND (dependency_reference !~ '(^|\.)[^.]{41,}(\.|$)'::text)) OR ((dependency_kind = ANY (ARRAY['platform_block'::text, 'platform_theme'::text])) AND (dependency_reference ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND (dependency_reference <> '00000000-0000-0000-0000-000000000000'::text)) OR ((dependency_kind = ANY (ARRAY['platform_flow'::text, 'application_flow'::text, 'application_flow_node'::text, 'application_query'::text, 'module_query'::text, 'application_form'::text, 'application_workflow'::text, 'application_action'::text, 'protected_operation'::text])) AND ((char_length(dependency_reference) >= 1) AND (char_length(dependency_reference) <= 500)) AND (dependency_reference !~ '[[:space:]]'::text)))),
    CONSTRAINT release_dependencies_target_shape CHECK ((((dependency_kind = 'module'::text) AND (target_root_id IS NOT NULL) AND ((target_release_revision >= 1) AND (target_release_revision <= '9007199254740991'::bigint)) AND (catalogue_item_id IS NULL)) OR ((dependency_kind = 'connection_type'::text) AND (target_root_id IS NULL) AND (target_release_revision IS NULL) AND (catalogue_item_id IS NOT NULL) AND (catalogue_item_id <> '00000000-0000-0000-0000-000000000000'::uuid)) OR ((dependency_kind = 'platform_block'::text) AND (target_root_id IS NULL) AND (target_release_revision IS NULL) AND (catalogue_item_id IS NOT NULL) AND ((catalogue_item_id)::text = dependency_reference)) OR ((dependency_kind = 'platform_theme'::text) AND (target_root_id IS NULL) AND (target_release_revision IS NULL) AND (catalogue_item_id IS NULL)) OR ((dependency_kind = ANY (ARRAY['platform_flow'::text, 'application_flow'::text, 'application_flow_node'::text, 'application_query'::text, 'module_query'::text, 'application_form'::text, 'application_workflow'::text, 'application_action'::text, 'protected_operation'::text])) AND (target_root_id IS NULL) AND (target_release_revision IS NULL) AND (catalogue_item_id IS NULL)))),
    CONSTRAINT release_dependencies_version_format CHECK ((dependency_version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'::text))
);

