    CONSTRAINT consumer_occurrence_progress_check CHECK (((lease_expires_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (lease_expires_at > claimed_at))),
    CONSTRAINT consumer_occurrence_progress_check1 CHECK (((acknowledged_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (acknowledged_at >= claimed_at))),
    CONSTRAINT consumer_occurrence_progress_claimed_at_check CHECK ((claimed_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone]))),
    CONSTRAINT consumer_occurrence_progress_consumer_key_check CHECK ((((octet_length(consumer_key) >= 1) AND (octet_length(consumer_key) <= 128)) AND (consumer_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text))),
    CONSTRAINT consumer_occurrence_progress_failure_code_valid CHECK (((last_failure_code IS NULL) OR (last_failure_code = ANY (ARRAY['transient_dependency_unavailable'::text, 'transient_timeout'::text, 'validation_rejected'::text, 'authorization_denied'::text, 'conflict_or_duplicate'::text, 'unclassified'::text])))),
    CONSTRAINT consumer_occurrence_progress_failure_count_range CHECK (((failure_count >= 0) AND (failure_count <= 1000000))),
    CONSTRAINT consumer_occurrence_progress_last_failure_shape CHECK ((((last_failed_at IS NULL) = (last_failure_code IS NULL)) AND ((last_failed_at IS NULL) OR (last_failed_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone]))))),
    CONSTRAINT consumer_occurrence_progress_recovered_at_shape CHECK ((((recovered_at IS NULL) = (recovered_by IS NULL)) AND ((recovery_count = 0) = (recovered_at IS NULL)) AND ((recovered_at IS NULL) OR ((recovered_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (recovered_by <> '00000000-0000-0000-0000-000000000000'::uuid))))),
    CONSTRAINT consumer_occurrence_progress_recovery_count_range CHECK (((recovery_count >= 0) AND (recovery_count <= 1000000))),
    CONSTRAINT consumer_occurrence_progress_terminally_failed_at_shape CHECK (((terminally_failed_at IS NULL) OR ((terminally_failed_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND (last_failed_at IS NOT NULL) AND (terminally_failed_at >= last_failed_at))))
);

