--
-- Name: event_outbox; Type: TABLE; Schema: vortex_event; Owner: postgres
--

CREATE TABLE vortex_event.event_outbox (
    occurrence_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    storage_contract_id uuid NOT NULL,
    storage_scope text NOT NULL,
    sequence_application_root_id uuid,
    record_id uuid NOT NULL,
    record_sequence bigint NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    envelope jsonb NOT NULL,
    CONSTRAINT event_outbox_check CHECK ((((storage_scope = 'organization_shared'::text) AND (sequence_application_root_id IS NULL)) OR ((storage_scope = 'application_contained'::text) AND (sequence_application_root_id IS NOT NULL)))),
    CONSTRAINT event_outbox_check1 CHECK (((envelope ?& ARRAY['contractVersion'::text, 'occurrenceId'::text, 'organizationId'::text, 'installation'::text, 'descriptor'::text, 'definitionRelease'::text, 'recordId'::text, 'occurredAt'::text, 'actorId'::text, 'correlationId'::text, 'recordSequence'::text, 'payload'::text]) AND ((envelope - ARRAY['contractVersion'::text, 'occurrenceId'::text, 'organizationId'::text, 'installation'::text, 'descriptor'::text, 'definitionRelease'::text, 'recordId'::text, 'occurredAt'::text, 'actorId'::text, 'correlationId'::text, 'recordSequence'::text, 'payload'::text]) = '{}'::jsonb) AND ((envelope ->> 'contractVersion'::text) = '2.0.0'::text) AND (NOT (((envelope ->> 'occurrenceId'::text))::uuid IS DISTINCT FROM occurrence_id)) AND (NOT (((envelope ->> 'organizationId'::text))::uuid IS DISTINCT FROM organization_id)) AND (NOT (((envelope ->> 'recordId'::text))::uuid IS DISTINCT FROM record_id)) AND (NOT (((envelope ->> 'recordSequence'::text))::bigint IS DISTINCT FROM record_sequence)) AND (NOT (((envelope ->> 'occurredAt'::text))::timestamp with time zone IS DISTINCT FROM occurred_at)))),
    CONSTRAINT event_outbox_envelope_check CHECK ((jsonb_typeof(envelope) = 'object'::text)),
    CONSTRAINT event_outbox_occurred_at_check CHECK ((occurred_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone]))),
    CONSTRAINT event_outbox_record_sequence_check CHECK (((record_sequence >= 1) AND (record_sequence <= '9007199254740991'::bigint))),
    CONSTRAINT event_outbox_storage_scope_check CHECK ((storage_scope = ANY (ARRAY['organization_shared'::text, 'application_contained'::text])))
);

