    CONSTRAINT accepted_administration_receipts_operation_valid CHECK (((operation_key = btrim(operation_key)) AND ((char_length(operation_key) >= 3) AND (char_length(operation_key) <= 160)) AND (operation_key ~ '^[a-z][a-z0-9]*(?:[._][a-z][a-z0-9]*)+$'::text))),
