    CONSTRAINT identity_disablement_commands_times_valid CHECK (((requested_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])) AND ((completed_at IS NULL) OR (completed_at >= requested_at))))
);

