    CONSTRAINT identity_disablement_events_ids_non_nil CHECK ((vortex_context.is_non_nil_uuid((command_id)::text) AND vortex_context.is_non_nil_uuid((actor_identity_id)::text) AND vortex_context.is_non_nil_uuid((subject_identity_id)::text) AND vortex_context.is_non_nil_uuid((correlation_id)::text))),
    CONSTRAINT identity_disablement_events_sessions_shape CHECK ((((event = 'disabled'::text) AND (sessions_revoked >= 0)) OR ((event <> 'disabled'::text) AND (sessions_revoked IS NULL)))),
    CONSTRAINT identity_disablement_events_time_valid CHECK ((recorded_at <> ALL (ARRAY['-infinity'::timestamp with time zone, 'infinity'::timestamp with time zone])))
);

