    CONSTRAINT organization_accounts_display_name_valid CHECK (((display_name IS NULL) OR ((display_name = btrim(display_name)) AND ((char_length(display_name) >= 1) AND (char_length(display_name) <= 120))))),
    CONSTRAINT organization_accounts_id_non_nil CHECK ((organization_account_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT organization_accounts_identity_non_nil CHECK ((identity_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT organization_accounts_language_valid CHECK (((language IS NULL) OR ((language = btrim(language)) AND ((char_length(language) >= 2) AND (char_length(language) <= 35))))),
    CONSTRAINT organization_accounts_organization_non_nil CHECK ((organization_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT organization_accounts_revision_range CHECK (((revision >= 1) AND (revision <= '9007199254740991'::bigint))),
    CONSTRAINT organization_accounts_state_changed_by_non_nil CHECK ((state_changed_by <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT organization_accounts_state_evidence CHECK ((((state <> 'suspended'::text) OR (suspended_at IS NOT NULL)) AND ((state <> 'closed'::text) OR (closed_at IS NOT NULL)) AND ((state <> 'closing'::text) OR ((closing_at IS NOT NULL) AND (deleted_at IS NULL))) AND ((state <> 'deleted'::text) OR ((closing_at IS NOT NULL) AND (deleted_at IS NOT NULL))) AND ((state = ANY (ARRAY['closing'::text, 'deleted'::text])) OR ((closing_at IS NULL) AND (deleted_at IS NULL))))),
    CONSTRAINT organization_accounts_state_valid CHECK ((state = ANY (ARRAY['active'::text, 'suspended'::text, 'closed'::text, 'closing'::text, 'deleted'::text]))),
    CONSTRAINT organization_accounts_super_administrator_provisioning_shape CHECK ((((provisioning_kind IS NULL) AND (provisioning_assignment_id IS NULL) AND (provisioned_by_identity_id IS NULL)) OR ((provisioning_kind = 'vortex_super_administrator'::text) AND (provisioning_assignment_id IS NOT NULL) AND (provisioned_by_identity_id = identity_id)))),
    CONSTRAINT organization_accounts_time_order CHECK (((changed_at >= activated_at) AND (state_changed_at >= activated_at) AND ((suspended_at IS NULL) OR (suspended_at >= activated_at)) AND ((closed_at IS NULL) OR (closed_at >= activated_at)) AND ((closing_at IS NULL) OR (closing_at >= activated_at)) AND ((deleted_at IS NULL) OR ((closing_at IS NOT NULL) AND (deleted_at >= closing_at))))),
    CONSTRAINT organization_accounts_time_zone_valid CHECK (((time_zone IS NULL) OR ((time_zone = btrim(time_zone)) AND ((char_length(time_zone) >= 1) AND (char_length(time_zone) <= 100)))))
);

