-- Name: index_catalogue; Type: TABLE; Schema: vortex_record; Owner: vortex_record_owner
--

CREATE TABLE vortex_record.index_catalogue (
    index_contract_id uuid NOT NULL,
    storage_contract_id uuid NOT NULL,
    field_id uuid NOT NULL,
    purpose text NOT NULL,
    physical_index_token text NOT NULL,
    desired_definition_fingerprint text NOT NULL,
    observed_state text NOT NULL,
    observed_revision bigint NOT NULL,
    changed_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    claim_id uuid,
    claimed_by text,
    claimed_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    CONSTRAINT index_catalogue_check CHECK ((physical_index_token = (
CASE purpose
    WHEN 'uniqueness'::text THEN 'ux_'::text
    ELSE 'ix_'::text
END || replace(lower((field_id)::text), '-'::text, ''::text)))),
    CONSTRAINT index_catalogue_desired_definition_fingerprint_check CHECK ((desired_definition_fingerprint ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT index_catalogue_lease_consistent CHECK ((((claim_id IS NULL) AND (claimed_by IS NULL) AND (claimed_at IS NULL) AND (lease_expires_at IS NULL)) OR ((claim_id IS NOT NULL) AND (claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT index_catalogue_observed_revision_check CHECK (((observed_revision >= 1) AND (observed_revision <= '9007199254740991'::bigint))),
    CONSTRAINT index_catalogue_observed_state_check CHECK ((observed_state = ANY (ARRAY['missing'::text, 'present'::text, 'invalid'::text]))),
    CONSTRAINT index_catalogue_physical_index_token_check CHECK ((physical_index_token ~ '^(ux|ix)_[a-f0-9]{32}$'::text)),
    CONSTRAINT index_catalogue_purpose_check CHECK ((purpose = ANY (ARRAY['uniqueness'::text, 'performance'::text])))
);

ALTER TABLE ONLY vortex_record.index_catalogue FORCE ROW LEVEL SECURITY;


ALTER TABLE vortex_record.index_catalogue OWNER TO vortex_record_owner;

