    CONSTRAINT legal_hold_versions_creator_valid CHECK (((created_by_kind = ANY (ARRAY['human'::text, 'system'::text])) AND (created_by_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT legal_hold_versions_dates_valid CHECK ((review_at > starts_at)),
    CONSTRAINT legal_hold_versions_hold_id_valid CHECK ((hold_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT legal_hold_versions_hold_revision_valid CHECK (((hold_revision >= 1) AND (hold_revision <= '9007199254740990'::bigint))),
    CONSTRAINT legal_hold_versions_organization_id_valid CHECK ((organization_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT legal_hold_versions_reason_valid CHECK (((char_length(btrim(reason)) >= 1) AND (char_length(btrim(reason)) <= 4000))),
    CONSTRAINT legal_hold_versions_release_valid CHECK ((((status = 'active'::text) AND (release_decision_id IS NULL) AND (release_reason IS NULL) AND (released_by_kind IS NULL) AND (released_by_id IS NULL) AND (released_at IS NULL)) OR ((status = 'released'::text) AND (release_decision_id IS NOT NULL) AND (release_decision_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (release_reason IS NOT NULL) AND ((char_length(btrim(release_reason)) >= 1) AND (char_length(btrim(release_reason)) <= 4000)) AND (released_by_kind IS NOT NULL) AND (released_by_kind = ANY (ARRAY['human'::text, 'system'::text])) AND (released_by_id IS NOT NULL) AND (released_by_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (released_at IS NOT NULL)))),
    CONSTRAINT legal_hold_versions_scope_revision_valid CHECK (((scope_revision >= 1) AND (scope_revision <= hold_revision))),
    CONSTRAINT legal_hold_versions_scope_valid CHECK ((((scope_kind = 'all_organization_data'::text) AND (application_root_id IS NULL) AND (record_type_id IS NULL) AND (record_id IS NULL) AND (file_id IS NULL)) OR ((scope_kind = 'application'::text) AND (application_root_id IS NOT NULL) AND (application_root_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (record_type_id IS NULL) AND (record_id IS NULL) AND (file_id IS NULL)) OR ((scope_kind = 'record_type'::text) AND (application_root_id IS NULL) AND (record_type_id IS NOT NULL) AND (record_type_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (record_id IS NULL) AND (file_id IS NULL)) OR ((scope_kind = 'record'::text) AND (application_root_id IS NULL) AND (record_type_id IS NOT NULL) AND (record_type_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (record_id IS NOT NULL) AND (record_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (file_id IS NULL)) OR ((scope_kind = 'file'::text) AND (application_root_id IS NULL) AND (record_type_id IS NULL) AND (record_id IS NULL) AND (file_id IS NOT NULL) AND (file_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT legal_hold_versions_status_valid CHECK ((status = ANY (ARRAY['active'::text, 'released'::text]))),
    CONSTRAINT legal_hold_versions_tenant_id_valid CHECK ((tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid))
);

