    CONSTRAINT protected_workflow_runs_authority_binding CHECK ((((run_record #>> '{authority,runId}'::text[]) IS NOT NULL) AND (lower((run_record #>> '{authority,runId}'::text[])) = (run_id)::text) AND (lower((run_record #>> '{authority,organizationId}'::text[])) = (organization_id)::text) AND (lower((run_record #>> '{executionReference,runId}'::text[])) = (run_id)::text) AND (lower((run_record #>> '{executionReference,organizationId}'::text[])) = (organization_id)::text) AND ((run_record #>> '{authority,applicationRootId}'::text[]) IS NOT NULL) AND (lower((run_record #>> '{authority,applicationRootId}'::text[])) = lower((run_record #>> '{executionReference,applicationRootId}'::text[]))) AND ((run_record #>> '{authority,workflowId}'::text[]) IS NOT NULL) AND (lower((run_record #>> '{authority,workflowId}'::text[])) = lower((run_record #>> '{executionReference,workflowId}'::text[]))) AND ((run_record #>> '{authority,workflowRevision}'::text[]) IS NOT NULL) AND ((run_record #>> '{authority,workflowRevision}'::text[]) = (run_record #>> '{executionReference,workflowRevision}'::text[])) AND (NOT (jsonb_typeof((run_record -> 'nodes'::text)) IS DISTINCT FROM 'array'::text)) AND (NOT (jsonb_typeof((run_record -> 'kestra'::text)) IS DISTINCT FROM 'object'::text)))),
    CONSTRAINT protected_workflow_runs_identity_id_check CHECK (((identity_id IS NULL) OR vortex_context.is_non_nil_uuid((identity_id)::text))),
    CONSTRAINT protected_workflow_runs_initiator_binding CHECK (((((run_record #>> '{authority,runAs}'::text[]) = 'initiating_person'::text) AND (identity_id IS NOT NULL) AND (lower((run_record #>> '{authority,initiator,identityId}'::text[])) = (identity_id)::text)) OR (((run_record #>> '{authority,runAs}'::text[]) = 'system_with_source_authority'::text) AND (identity_id IS NULL)))),
    CONSTRAINT protected_workflow_runs_organization_id_check CHECK (vortex_context.is_non_nil_uuid((organization_id)::text)),
    CONSTRAINT protected_workflow_runs_run_id_check CHECK (vortex_context.is_non_nil_uuid((run_id)::text)),
    CONSTRAINT protected_workflow_runs_run_record_check CHECK (((jsonb_typeof(run_record) = 'object'::text) AND (pg_column_size(run_record) <= 262144)))
);


